    ('4ebe52eb-aca6-426b-8ff2-dbebac7b9cd3', 'e0000000-0000-0000-0000-000000050001', '40a9675b-3c1b-417f-bfe4-8f831d01a3d3', '9.2.2.f', '9.9_2.9_2_2.9_2_2_f'::ltree, FALSE, 'clause_iso_50001_2018_0200'),
