    ('50be5611-fc40-4c45-adca-3421ae7b9ff9', 'e0000000-0000-0000-0000-000000050001', '4dbe5158-d136-4330-aaa1-5a6eab7b9b40', '9.3.1', '9.9_3.9_3_1'::ltree, TRUE, 'clause_iso_50001_2018_0202'),
    ('4fbe547e-a92e-46da-9959-dd44ad7b9e66', 'e0000000-0000-0000-0000-000000050001', '4dbe5158-d136-4330-aaa1-5a6eab7b9b40', '9.3.2', '9.9_3.9_3_2'::ltree, TRUE, 'clause_iso_50001_2018_0203'),
