    ('47bc094f-551b-4e9b-addf-ed37c5798597', 'e0000000-0000-0000-0000-000000050001', '4dbe5158-d136-4330-aaa1-5a6eab7b9b40', '9.3.3', '9.9_3.9_3_3'::ltree, TRUE, 'clause_iso_50001_2018_0213'),
