    ('42bc0170-cb29-4624-9888-1c7ec0797db8', 'e0000000-0000-0000-0000-000000050001', '44bc0496-ae49-4ade-877e-2c14c27980de', '9.3.4.b', '9.9_3.9_3_4.9_3_4_b'::ltree, FALSE, 'clause_iso_50001_2018_0216'),
    ('43bc0303-5352-466f-816e-a5bbc1797f4b', 'e0000000-0000-0000-0000-000000050001', '44bc0496-ae49-4ade-877e-2c14c27980de', '9.3.4.c', '9.9_3.9_3_4.9_3_4_c'::ltree, FALSE, 'clause_iso_50001_2018_0217'),
    ('50bc177a-09f9-40f2-ad4e-2b28be797a92', 'e0000000-0000-0000-0000-000000050001', '44bc0496-ae49-4ade-877e-2c14c27980de', '9.3.4.d', '9.9_3.9_3_4.9_3_4_d'::ltree, FALSE, 'clause_iso_50001_2018_0218'),
    ('51bc190d-63c1-46bd-9cd2-fe05bf797c25', 'e0000000-0000-0000-0000-000000050001', '44bc0496-ae49-4ade-877e-2c14c27980de', '9.3.4.e', '9.9_3.9_3_4.9_3_4_e'::ltree, FALSE, 'clause_iso_50001_2018_0219'),
    ('42b9c2d9-245a-4871-9e56-95c5c0773f21', 'e0000000-0000-0000-0000-000000050001', '44bc0496-ae49-4ade-877e-2c14c27980de', '9.3.4.f', '9.9_3.9_3_4.9_3_4_f'::ltree, FALSE, 'clause_iso_50001_2018_0220'),
    ('41b9c146-496e-4476-bcdf-cee8bf773d8e', 'e0000000-0000-0000-0000-000000050001', '44bc0496-ae49-4ade-877e-2c14c27980de', '9.3.4.g', '9.9_3.9_3_4.9_3_4_g'::ltree, FALSE, 'clause_iso_50001_2018_0221'),
    ('40b9bfb3-f857-49e7-91b4-d57fbe773bfb', 'e0000000-0000-0000-0000-000000050001', NULL, '10', '10'::ltree, FALSE, 'clause_iso_50001_2018_0222'),
    ('3fb9be20-697b-4c3c-87f4-15f2bd773a68', 'e0000000-0000-0000-0000-000000050001', '40b9bfb3-f857-49e7-91b4-d57fbe773bfb', '10.1', '10.10_1'::ltree, FALSE, 'clause_iso_50001_2018_0223'),
    ('46b9c925-49bb-4bed-8f22-b2d9c477456d', 'e0000000-0000-0000-0000-000000050001', '3fb9be20-697b-4c3c-87f4-15f2bd773a68', '10.1.a', '10.10_1.10_1_a'::ltree, FALSE, 'clause_iso_50001_2018_0224'),
    ('45b9c792-ef56-4562-8cdc-6c5cc37743da', 'e0000000-0000-0000-0000-000000050001', '46b9c925-49bb-4bed-8f22-b2d9c477456d', '10.1.a.1', '10.10_1.10_1_a.10_1_a_1'::ltree, FALSE, 'clause_iso_50001_2018_0225'),
    ('44b9c5ff-751a-4c13-aee9-ab23c2774247', 'e0000000-0000-0000-0000-000000050001', '46b9c925-49bb-4bed-8f22-b2d9c477456d', '10.1.a.2', '10.10_1.10_1_a.10_1_a_2'::ltree, FALSE, 'clause_iso_50001_2018_0226'),
    ('43b9c46c-1c36-49d8-8b1e-6986c17740b4', 'e0000000-0000-0000-0000-000000050001', '3fb9be20-697b-4c3c-87f4-15f2bd773a68', '10.1.b', '10.10_1.10_1_b'::ltree, FALSE, 'clause_iso_50001_2018_0227'),
    ('4ab9cf71-97cf-4389-a300-027db8773289', 'e0000000-0000-0000-0000-000000050001', '43b9c46c-1c36-49d8-8b1e-6986c17740b4', '10.1.b.1', '10.10_1.10_1_b.10_1_b_1'::ltree, FALSE, 'clause_iso_50001_2018_0228'),
    ('49b9cdde-a749-4bce-8b4b-e6c0b77730f6', 'e0000000-0000-0000-0000-000000050001', '43b9c46c-1c36-49d8-8b1e-6986c17740b4', '10.1.b.2', '10.10_1.10_1_b.10_1_b_2'::ltree, FALSE, 'clause_iso_50001_2018_0229'),
    ('3cb77ad0-ae8c-4d88-908a-3c023a742d98', 'e0000000-0000-0000-0000-000000050001', '43b9c46c-1c36-49d8-8b1e-6986c17740b4', '10.1.b.3', '10.10_1.10_1_b.10_1_b_3'::ltree, FALSE, 'clause_iso_50001_2018_0230'),
    ('3db77c63-1d90-4843-ab67-7a0f3b742f2b', 'e0000000-0000-0000-0000-000000050001', '3fb9be20-697b-4c3c-87f4-15f2bd773a68', '10.1.c', '10.10_1.10_1_c'::ltree, FALSE, 'clause_iso_50001_2018_0231'),
    ('3eb77df6-65e5-4b12-a250-e9b83c7430be', 'e0000000-0000-0000-0000-000000050001', '3fb9be20-697b-4c3c-87f4-15f2bd773a68', '10.1.d', '10.10_1.10_1_d'::ltree, FALSE, 'clause_iso_50001_2018_0232'),
    ('3fb77f89-d8f7-42dd-a656-38d53d743251', 'e0000000-0000-0000-0000-000000050001', '3fb9be20-697b-4c3c-87f4-15f2bd773a68', '10.1.e', '10.10_1.10_1_e'::ltree, FALSE, 'clause_iso_50001_2018_0233'),
    ('40b7811c-1152-44ac-9e19-d4563e7433e4', 'e0000000-0000-0000-0000-000000050001', '40b9bfb3-f857-49e7-91b4-d57fbe773bfb', '10.2', '10.10_2'::ltree, FALSE, 'clause_iso_50001_2018_0234')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('25b8e4b7-cefd-4c51-85c5-fde3339a487e', '31d9ea19-5bf2-43e3-ae98-48ebd09a8bc8', 'en', 'Scope', '<div>This International Standard specifies requirements for a quality management system when an organization:</div><div>{clause_1.a}</div><div>{clause_1.b}</div><div>All the requirements of this International Standard are generic and are intended to be applicable to any organization, regardless of its type or size, or the products and services it provides.</div><div>NOTE 1: In this International Standard, the terms "product" or "service" only apply to products and services intended for, or required by, a customer.</div><div>NOTE 2: Statutory and regulatory requirements can be expressed as legal requirements. </div>'),
    ('28b8e970-c913-464a-b95f-bdd8409a5cf5', '31d9ea19-5bf2-43e3-ae98-48ebd09a8bc8', 'es', 'Objeto y campo de aplicación', '<div>Esta Norma Internacional especifica los requisitos para un sistema de gestión de la calidad cuando una organización:</div><div>{clause_1.a}</div><div>{clause_1.b}</div><div>Todos los requisitos de esta Norma Internacional son genéricos y se pretende que sean aplicables a todas las organizaciones, sin importar su tipo, tamaño y el producto suministrado.</div><div>NOTA 1: En esta Norma Internacional, los términos "producto" o "servicio" se aplican únicamente a productos y servicios destinados a un cliente o solicitados por él.</div><div>NOTA 2: El concepto que en la versión en inglés se expresa como "statutory and regulatory requirements" en esta versión en español se ha traducido como requisitos legales y reglamentarios.</div>'),
    ('06710acc-3da6-4322-8a1d-326c389b1ffd', '2ed9e560-ba65-4c32-b7ff-4a44d39a9081', 'en', '', '<div>a) needs to demonstrate its ability to consistently provide products and services that meet customer and applicable statutory and regulatory requirements, and</div>'),
    ('1b712bdb-e9f7-4df9-9266-f20f3b9b24b6', '2ed9e560-ba65-4c32-b7ff-4a44d39a9081', 'es', '', 'a) necesita demostrar su capacidad para proporcionar regularmente productos y servicios que satisfagan los requisitos del cliente y los legales y reglamentarios aplicables, y'),
    ('bfe477cd-5fab-457b-a01e-2c813281bd3c', '2fd9e6f3-2ff1-4cfd-8c6f-a121d29a8eee', 'en', '', '<div>b) aims to enhance customer satisfaction through the effective application of the system, including processes for improvement of the system and the assurance of conformity to customer and applicable statutory and regulatory requirements.</div>'),
    ('a2e44a26-bf39-417c-bacd-314e2781abeb', '2fd9e6f3-2ff1-4cfd-8c6f-a121d29a8eee', 'es', '', 'b) aspira a aumentar la satisfacción del cliente a través de la aplicación eficaz del sistema, incluidos los procesos para la mejora del sistema y el aseguramiento de la conformidad con los requisitos del cliente y los legales y reglamentarios aplicables.'),
    ('d33a82c2-499b-4fcc-9cc7-d9929e555cbb', '34d9eed2-3665-484c-841a-3a3ad59a93a7', 'en', 'Normative references', '<div>The following documents, in whole or in part, are normatively referenced in this document and are indispensable for its application. For dated references, only the edition cited applies. For undated references, the latest edition of the referenced document (including any amendments) applies.</div><div>ISO 9000:2015, Quality management systems - Fundamentals and vocabulary </div>'),
    ('c83a7171-49f8-44ab-950c-af8d89553bac', '34d9eed2-3665-484c-841a-3a3ad59a93a7', 'es', 'Referencias normativas', '<div>Los documentos indicados a continuación, en su totalidad o en parte, son normas para consulta indispensables para la aplicación de este documento. Para las referencias con fecha, sólo se aplica la edición citada. Para las referencias sin fecha se aplica la última edición (incluyendo cualquier modificación de ésta).</div><div>ISO 9000:2015, Sistemas de gestión de la calidad — Fundamentos y vocabulario.</div>'),
    ('72e40e0b-651d-45c5-84bb-7b5f4e6a00f2', '35d9f065-df2e-4eb7-a238-eba7d49a9214', 'en', 'Terms and definitions', '<div>For the purposes of this document, the terms and definitions given in ISO 9000:2015 apply. </div>'),
    ('7de41f5c-2850-4a06-8bb2-4fdc636a2201', '35d9f065-df2e-4eb7-a238-eba7d49a9214', 'es', 'Términos y definiciones', '<div>Para los fines de este documento, se aplican los términos y definiciones incluidos en la Norma ISO 9000:2015.</div>'),
    ('21425640-2deb-4926-9bca-8a8872f44981', 'f0000000-0000-0000-0000-000000000004', 'en', 'Context of the organization', '<div>{clause_4.1}</div><div>{clause_4.2}</div><div>{clause_4.3}</div><div>{clause_4.4}</div>'),
    ('3e4283e7-9a25-4265-a797-a5f35df42872', 'f0000000-0000-0000-0000-000000000004', 'es', 'Contexto de la organización', '<div>{clause_4.1}</div><div>{clause_4.2}</div><div>{clause_4.3}</div><div>{clause_4.4}</div>'),
    ('ba3ecf91-0a44-498f-a1e9-792d4cb3a4f0', 'f0000000-0000-0000-0000-000000000041', 'en', 'Understanding the organization and its context', '<div>The organization shall determine external and internal issues that are relevant to its purpose and its strategic direction and that affect its ability to achieve the intended result(s) of its quality management system.</div><div>The organization shall monitor and review information about these external and internal issues.</div><div>The organization shall determine whether climate change is a relevant issue.</div><div>NOTE 1: Issues can include positive and negative factors or conditions for consideration.</div><div>NOTE 2: Understanding the external context can be facilitated by considering issues arising from legal, technological, competitive, market, cultural, social and economic environments, whether international, national, regional or local.</div><div>NOTE 3: Understanding the internal context can be facilitated by considering issues related to values, culture, knowledge and performance of the organization. </div>'),
    ('c53ee0e2-1962-4c58-9b4e-a8b249b3a037', 'f0000000-0000-0000-0000-000000000041', 'es', 'Conocimiento de la organización y de su contexto', '<div>La organización debe determinar las cuestiones externas e internas que son pertinentes para su propósito y su dirección estratégica y que afectan a su capacidad para lograr los resultados previstos de su sistema de gestión de la calidad.</div><div>La organización debe realizar el seguimiento y la revisión de la información sobre estas cuestiones externas e internas.</div><div>La organización debe determinar si el cambio climático es un problema relevante.</div><div>NOTA 1: Las cuestiones pueden incluir factores positivos y negativos o condiciones para su consideración.</div><div>NOTA 2: La comprensión del contexto externo puede verse facilitado al considerar cuestiones que surgen de los entornos legal, tecnológico, competitivo, de mercado, cultural, social y económico, ya sea internacional, nacional, regional o local.</div><div>NOTA 3: La comprensión del contexto interno puede verse facilitada al considerar cuestiones relativas a los valores, la cultura, los conocimientos y el desempeño de la organización.</div>'),
    ('2065ac16-5a10-47a0-bb60-e35eb926a82f', 'f0000000-0000-0000-0000-000000000042', 'en', 'Understanding the needs and expectations of interested parties', '<div>Due to their effect or potential effect on the organization''s ability to consistently provide products and services that meet customer and applicable statutory and regulatory requirements, the organization shall determine: </div><div>{clause_4.2.a}</div><div>{clause_4.2.b}</div><div>The organization shall monitor and review information about these interested parties and their relevant requirements.</div><div>NOTE: Relevant interested parties can have requirements related to climate change.</div>'),
    ('1d65a75d-5356-4e07-a23c-5eb1ac2693b8', 'f0000000-0000-0000-0000-000000000042', 'es', 'Comprensión de las necesidades y expectativas de las partes interesadas', '<div>Debido a su efecto o efecto potencial en la capacidad de la organización de proporcionar regularmente productos y servicios que satisfagan los requisitos del cliente y los legales y reglamentarios aplicables, la organización debe determinar:&nbsp;</div><div>{clause_4.2.a}</div><div>{clause_4.2.b}</div><div>La organización debe realizar el seguimiento y la revisión de la información sobre estas partes interesadas y sus requisitos pertinentes.</div><div>NOTE: Las partes interesadas relevantes pueden tener requisitos relacionados con el cambio climático.</div>'),
    ('8d15f5bf-e179-4789-8d32-170b0bd69606', '39d9f6b1-0585-46db-b283-5f53c89a7f30', 'en', '', '<div>a) the interested parties that are relevant to the quality management system; </div>'),
    ('a01613a8-f1a3-4a92-9f9b-273028d6c3ad', '39d9f6b1-0585-46db-b283-5f53c89a7f30', 'es', '', '<div>a) las partes interesadas que son pertinentes al sistema de gestión de la calidad;</div>'),
    ('16ebf2bd-24a9-48bf-a390-991140771a80', '36dc308f-6535-4a11-8e5e-3891cb984552', 'en', '', '<div>b) the requirements of these interested parties that are relevant to the quality management system. </div>'),
    ('19ebf776-dc9c-49e8-872c-9b3e5d774827', '36dc308f-6535-4a11-8e5e-3891cb984552', 'es', '', '<div>b) los requisitos pertinentes de estas partes interesadas para el sistema de gestión de la calidad.</div>'),
    ('134b65fc-aac7-4b96-bf62-45fcd97393d1', '35dc2efc-9ded-4596-8374-fc34cc9846e5', 'en', 'Determining the scope of the quality management system', '<div>The organization shall determine the boundaries and applicability of the quality management system to establish its scope.</div><div>When determining this scope,the organization shall consider:</div><div>{clause_4.3.a}</div><div>{clause_4.3.b}</div><div>{clause_4.3.c}</div><div>The organization shall apply all the requirements of this International Standard if they are applicable within the determined scope of its quality management system.</div><div>The scope of the organization''s quality management system shall be available and be maintained as documented information. The scope shall state the types of products and services covered, and provide justification for any requirement of this International Standard that the organization determines is not applicable to the scope of its quality management system.</div><div>Conformity to this International Standard may only be claimed if the requirements determined as not being applicable do not affect the organization''s ability or responsibility to ensure the conformity of its products and services and the enhancement of customer satisfaction. </div>'),
    ('084b54ab-8dee-49b5-a7f0-317fe473a522', '35dc2efc-9ded-4596-8374-fc34cc9846e5', 'es', 'Determinación del alcance del sistema de gestión de la calidad', '<div>La organización debe determinar los límites y la aplicabilidad del sistema de gestión de la calidad para establecer su alcance.</div><div>Cuando se determina este alcance, la organización debe considerar:</div><div>{clause_4.3.a}</div><div>{clause_4.3.b}</div><div>{clause_4.3.c}</div><div>La organización debe aplicar todos los requisitos dé está Norma Internacional si son aplicables en el alcance determinado de su sistema de gestión de la calidad.</div><div>El alcance del sistema de gestión de la calidad de la organización debe estar disponible y mantenerse como información documentada. El alcance debe establecer los tipos de productos y servicios cubiertos, y proporcionar la justificación para cualquier requisito de esta Norma Internacional que la organización determine que no es aplicable para el alcance de su sistema de gestión de la calidad.</div><div>La conformidad con esta Norma Internacional sólo se puede declarar si los requisitos determinados como no aplicables no afectan a la capacidad o a la responsabilidad de la organización de asegurarse de la conformidad de sus productos y servicios y del aumento de la satisfacción del cliente.</div>'),
    ('31f3dc27-bc09-4a35-882c-3333f4e9b002', '38dc33b5-4f52-4407-85aa-a05bc998422c', 'en', '', '<div>a) the external and internal issues referred to in 4.1; </div>'),
    ('14f3ae80-d8e2-4c16-b531-bfc8e9e99eb1', '38dc33b5-4f52-4407-85aa-a05bc998422c', 'es', '', '<div>a) las cuestiones externas e internas referidas en el apartado 4.1;</div>'),
    ('11e9883e-507d-463c-877a-7846921a654b', '37dc3222-c075-465c-a812-411eca9843bf', 'en', '', '<div>b) the requirements of relevant interested parties referred to in 4.2; </div>'),
    ('1ee99cb5-f368-403b-8d9e-68299d1a769c', '37dc3222-c075-465c-a812-411eca9843bf', 'es', '', '<div>b) los requisitos de las partes interesadas pertinentes indicados en el apartado 4.2;</div>'),
    ('51451c41-f115-49eb-9962-fb7d2821cb0c', '32dc2a43-881b-448d-be84-665dc7983f06', 'en', '', '<div>c) the products and services of the organization. </div>'),
    ('3c44fb32-0c7f-430c-b401-bce23d21ec1b', '32dc2a43-881b-448d-be84-665dc7983f06', 'es', '', '<div>c) los productos y servicios de la organización.</div>'),
    ('2d7d4db0-9493-4a92-a791-e098df1acf0d', '31dc28b0-2a89-4182-99eb-fc20c8984099', 'en', 'Quality management system and its processes', '<div>{clause_4.4.1}</div><div>{clause_4.4.2}</div>'),
    ('2a7d48f7-846a-4789-b7d7-b1a3c21aa166', '31dc28b0-2a89-4182-99eb-fc20c8984099', 'es', 'Sistema de gestión de la calidad y sus procesos', '<div>{clause_4.4.1}</div><div>{clause_4.4.2}</div>'),
    ('7f20987b-caab-4981-bca5-f32f675e22ce', '34dc2d69-cc16-4933-a380-a9d7c5983be0', 'en', '', '<div>The organization shall establish, implement, maintain and continually improve a quality management system, including the processes needed and their interactions, in accordance with the requirements of this International Standard.</div><div>The organization shall determine the processes needed for the quality management system and their application throughout the organization, and shall:</div><div>{clause_4.4.1.a}</div><div>{clause_4.4.1.b}</div><div>{clause_4.4.1.c}</div><div>{clause_4.4.1.d}</div><div>{clause_4.4.1.e}</div><div>{clause_4.4.1.f}</div><div>{clause_4.4.1.g}</div><div>{clause_4.4.1.h}</div>'),
    ('6a20776c-066c-405a-b003-728c545e04e5', '34dc2d69-cc16-4933-a380-a9d7c5983be0', 'es', '', '<div>La organización debe establecer, implementar, mantener y mejorar continuamente un sistema de gestión de la calidad, incluidos los procesos necesarios y sus interacciones, de acuerdo con los requisitos de esta Norma Internacional. </div><div>La organización debe determinar los procesos necesarios para el sistema de gestión de la calidad y su aplicación a través de la organización, y debe:</div><div>{clause_4.4.1.a}</div><div>{clause_4.4.1.b}</div><div>{clause_4.4.1.c}</div><div>{clause_4.4.1.d}</div><div>{clause_4.4.1.e}</div><div>{clause_4.4.1.f}</div><div>{clause_4.4.1.g}</div><div>{clause_4.4.1.h}</div>'),
    ('2cbad3b2-9716-44b8-80c9-3862476811f7', '33dc2bd6-5d11-4b78-a54c-106ac6983d73', 'en', '', '<div>a) determine the inputs required and the outputs expected from these processes; </div>'),
    ('41baf4c1-9b9d-416f-a62a-76fd4a6816b0', '33dc2bd6-5d11-4b78-a54c-106ac6983d73', 'es', '', '<div>a) determinar las entradas requeridas y las salidas esperadas de estos procesos;</div>'),
    ('f1a2a945-bda6-4837-9fea-d119c7d5f0e8', '3edc3d27-eeca-4da9-a0f6-fd39d39851ea', 'en', '', '<div>b) determine the sequence and interaction of these processes; </div>'),
    ('04a2c72e-1e05-4c70-90bc-c0d6b4d5d2ff', '3edc3d27-eeca-4da9-a0f6-fd39d39851ea', 'es', '', '<div>b) determinar la secuencia e interacción de estos procesos;</div>'),
    ('582f6ea4-fe1e-490e-8df5-69043ef59f99', '3ddc3b94-e824-4d6e-9ac2-ebbcd498537d', 'en', '', '<div>c) determine and apply the criteria and methods (including monitoring, measurements and related performance indicators) needed to ensure the effective operation and control of these processes; </div>'),
    ('5d2f7683-8b2c-4d9d-bdcb-823759f5ca1a', '3ddc3b94-e824-4d6e-9ac2-ebbcd498537d', 'es', '', '<div>c) determinar y aplicar los criterios y los métodos (incluyendo el seguimiento, las mediciones y los indicadores del desempeño relacionados) necesarios para asegurarse de la operación eficaz y el control de estos procesos;</div>'),
    ('3e328e54-40ab-4dce-a4d5-e294bb080cd9', 'c4d4c154-e308-496a-8fcd-80acc595fd49', 'en', '', '<div>d) determine the resources needed for these processes and ensure their availability; </div>'),
    ('233263d3-b46d-405d-9e23-4227d608375a', 'c4d4c154-e308-496a-8fcd-80acc595fd49', 'es', '', '<div>d) determinar los recursos necesarios para estos procesos y asegurarse de su disponibilidad;</div>'),
    ('61d1ba75-9810-46f7-a7e0-0469416c6228', 'c5d4c2e7-36ba-4295-adb7-7ca9c495fbb6', 'en', '', '<div>e) assign the responsibilities and authorities for these processes;</div>'),
    ('54d1a5fe-11bc-4030-9988-af862e6c443f', 'c5d4c2e7-36ba-4295-adb7-7ca9c495fbb6', 'es', '', '<div>e) asignar las responsabilidades y autoridades para estos procesos;</div>'),
    ('5d6eb3b6-2d04-4974-b6f4-e1fee6678d13', 'c6d4c47a-dc43-4c00-89bb-4796c395fa23', 'en', '', '<div>f) address the risks and opportunities as determined in accordance with the requirements of 6.1; </div>'),
    ('5a6eaefd-c604-4d23-8526-f3d10167b794', 'c6d4c47a-dc43-4c00-89bb-4796c395fa23', 'es', '', '<div>f) abordar los riesgos y oportunidades determinados de acuerdo con los requisitos del apartado 6.1:</div>'),
    ('3d78a2df-1137-4e6d-b0a8-3a2bb5de92ea', 'c7d4c60d-e720-48bb-a031-2933c295f890', 'en', '', '<div>g) evaluate these processes and implement any changes needed to ensure that these processes achieve their intended results; </div>'),
    ('5078c0c8-4330-4d7e-a817-ec50bade9ac9', 'c7d4c60d-e720-48bb-a031-2933c295f890', 'es', '', '<div>g) evaluar estos procesos e implementar cualquier cambio necesario para asegurarse de que estos procesos logran los resultados previstos;</div>'),
    ('590246c8-9bc9-4b4a-978e-e250c00fe455', 'c0d4bb08-566d-4d7e-9cf2-97f8c9960395', 'en', '', '<div>h) improve the processes and the quality management system. </div>'),
    ('460228df-a1b3-4151-a01f-302bb30fcfde', 'c0d4bb08-566d-4d7e-9cf2-97f8c9960395', 'es', '', '<div>h) mejorar los procesos y el sistema de gestión de la calidad.</div>'),
    ('d0238879-fb3e-4323-a7b2-ae55291712b4', 'c1d4bc9b-5d11-4ab9-9e9c-9915c8960202', 'en', '', '<div>To the extent necessary, the organization shall:</div><div>{clause_4.4.2.a}</div><div>{clause_4.4.2.b}</div>'),
    ('eb23b2fa-623e-4f74-81f8-af8a0e16e833', 'c1d4bc9b-5d11-4ab9-9e9c-9915c8960202', 'es', '', '<div>En la medida en que sea necesario, la organización debe:</div><div>{clause_4.4.2.a}</div><div>{clause_4.4.2.b}</div>'),
    ('57a0690a-4004-4a50-a59c-753a285d273f', 'c2d4be2e-5fa8-4944-9510-be42c796006f', 'en', '', '<div>a) maintain documented information to support the operation of its processes;</div>'),
    ('5ca070e9-dfa5-4617-af46-3d253b5d4528', 'c2d4be2e-5fa8-4944-9510-be42c796006f', 'es', '', '<div>a) mantener información documentada para apoyar la operación de sus procesos;</div>'),
    ('882af633-b93a-4c79-ad6b-e907bbacdd96', 'c3d4bfc1-e7d1-498f-b228-a24fc695fedc', 'en', '', '<div>b) retain documented information to have confidence thatthe processes are being carried out as planned. </div>'),
    ('a32b20b4-0ce9-41a2-926d-fef4b8acd8dd', 'c3d4bfc1-e7d1-498f-b228-a24fc695fedc', 'es', '', '<div>b) conservar la información documentada para tener la confianza de que los procesos se realizan según lo planificado.</div>'),
    ('437ba56c-9c04-4656-8b03-a50c55860111', 'f0000000-0000-0000-0000-000000000005', 'en', 'Leadership', '<div>{clause_5.1}</div><div>{clause_5.2}</div><div>{clause_5.3}</div>'),
    ('587bc67b-81a7-4075-97a6-25af60861262', 'f0000000-0000-0000-0000-000000000005', 'es', 'Liderazgo', '<div>{clause_5.1}</div><div>{clause_5.2}</div><div>{clause_5.3}</div>'),
    ('fcef126d-6737-407f-ba65-2aa1bc8987c0', 'f0000000-0000-0000-0000-000000000051', 'en', 'Leadership and commitment', '<div>{clause_5.1.1}</div><div>{clause_5.1.2}</div>'),
    ('dfeee4c6-1f29-4ea8-b82c-0c6ed989b567', 'f0000000-0000-0000-0000-000000000051', 'es', 'Liderazgo y compromiso', '<div>{clause_5.1.1}</div><div>{clause_5.1.2}</div>'),
    ('2f83459b-09cc-4edd-8223-0c4fffc1f5ba', 'cad7095d-54c9-450b-8c85-5a373f92ebc0', 'en', 'General', '<div>Top management shall demonstrate leadership and commitment with respect to the quality management system by: </div><div>{clause_5.1.1.a}</div><div>{clause_5.1.1.b}</div><div>{clause_5.1.1.c}</div><div>{clause_5.1.1.d}</div><div>{clause_5.1.1.e}</div><div>{clause_5.1.1.f}</div><div>{clause_5.1.1.g}</div><div>{clause_5.1.1.h}</div><div>{clause_5.1.1.i}</div><div>{clause_5.1.1.j}</div><div>NOTE: Reference to "business" in this International Standard can be interpreted broadly to mean those activities that are core to the purposes of the organization''s existence, whether the organization is public, private, for profit or not for profit. </div>'),
    ('1a83248c-9609-4c4e-ad79-a9ace4c1cb39', 'cad7095d-54c9-450b-8c85-5a373f92ebc0', 'es', 'Generalidades', '<div>La alta dirección debe demostrar liderazgo y compromiso con respecto al sistema de gestión de la calidad:&nbsp;</div><div>{clause_5.1.1.a}</div><div>{clause_5.1.1.b}</div><div>{clause_5.1.1.c}</div><div>{clause_5.1.1.d}</div><div>{clause_5.1.1.e}</div><div>{clause_5.1.1.f}</div><div>{clause_5.1.1.g}</div><div>{clause_5.1.1.h}</div><div>{clause_5.1.1.i}</div><div>{clause_5.1.1.j}</div><div>NOTA: En ésta Norma Internacional se puede interpretar el término "negocio" en su sentido más amplio, es decir, Referido a aquellas actividades que son esenciales para la existencia de la organización; tanto si la organización es pública, privada, con o sin fines de lucro.</div>'),
    ('dd1d80d2-ae9e-4b64-b448-a3822fad1f23', 'c9d707ca-49ef-4b50-9403-254a4092ed53', 'en', '', '<div>a) taking accountability for the effectiveness of the quality management system; </div>'),
    ('f21da1e1-a145-4cb3-92f6-011d2aad1744', 'c9d707ca-49ef-4b50-9403-254a4092ed53', 'es', '', '<div>a) asumiendo la responsabilidad y obligación de rendir cuentas con relación a la eficacia del sistema de gestión de la calidad;</div>'),
    ('04223261-a39a-4ae7-9112-f49dc0859df8', 'c8d70637-a463-4ee5-a0b2-53bd4192eee6', 'en', '', '<div>b) ensuring that the quality policy and quality objectives are established for the quality management system and are compatible with the context and strategic direction of the organization; </div>'),
    ('ef221152-accd-4a80-b265-9702cd85b26f', 'c8d70637-a463-4ee5-a0b2-53bd4192eee6', 'es', '', '<div>b) asegurándose de que se establezcan la política de la calidad y los objetivos de la calidad para el sistema de gestión de la calidad, y que éstos sean compatibles con el contexto y la dirección estratégica de la organización;</div>'),
    ('6a87e850-f04f-4f3e-97c2-f838044c0be9', 'c7d704a4-5151-497a-8f79-75004292f079', 'en', '', '<div>c) ensuring the integration of the quality management system requirements into the organization''s business processes; </div>'),
    ('6787e397-d7a3-452d-a3c6-df43ff4c040a', 'c7d704a4-5151-497a-8f79-75004292f079', 'es', '', '<div>c) asegurándose de la integración de los requisitos del sistema de gestión de la calidad en los procesos de negocio de la organización;</div>'),
    ('6efe76c7-06a8-4e69-83c7-5453c4f20ae6', 'c6d70311-557b-45df-a014-12bb4392f20c', 'en', '', '<div>d) promoting the use of the process approach and risk-based thinking; </div>'),
    ('51fe4920-301f-4672-acc5-9468e1f2388d', 'c6d70311-557b-45df-a014-12bb4392f20c', 'es', '', '<div>d) promoviendo el uso del enfoque a procesos y el pensamiento basado en riesgos;</div>'),
    ('c4c8315e-3bb1-4480-878b-6fe6e59a2f8f', 'c5d7017e-cd52-4594-b72d-897e4492f39f', 'en', '', '<div>e) ensuring that the resources needed for the quality management system are available; </div>'),
    ('d1c845d5-327e-44e7-987e-fc49d89a1b18', 'c5d7017e-cd52-4594-b72d-897e4492f39f', 'es', '', '<div>e) asegurándose de que los recursos necesarios para el sistema de gestión de la calidad estén disponibles;</div>'),
    ('c9c908dd-923c-47d3-be8e-dfb132fa10c4', 'c4d6ffeb-b49d-4189-a65c-fef14592f532', 'en', '', '<div>f) communicating the importance of effective quality management and of conforming to the quality management system requirements; </div>'),
    ('ccc90d96-9f97-4984-97b3-645e37fa18a3', 'c4d6ffeb-b49d-4189-a65c-fef14592f532', 'es', '', '<div>f) comunicando la importancia de una gestión de la calidad eficaz y conforme con los requisitos del sistema de gestión de la calidad;</div>'),
    ('5056009c-a2a9-4eba-99ce-259cc9f2e265', 'c3d6fe58-c416-49ce-a623-99144692f6c5', 'en', '', '<div>g) ensuring that the quality management system achieves its intended results; </div>'),
    ('4555ef4b-4b23-4ce1-95c8-3f1fdcf3004e', 'c3d6fe58-c416-49ce-a623-99144692f6c5', 'es', '', '<div>g) asegurándose de que el sistema de gestión de la calidad logre los resultados previstos;</div>'),
    ('9465eda3-878e-4ba5-a0f1-f1d77864b252', 'c2d6fcc5-91e7-4a13-94d4-5dbf4792f858', 'en', '', '<div>h) engaging, directing and supporting persons to contribute to the effectiveness of the quality management system; </div>'),
    ('8f65e5c4-34a1-4766-935e-08a48d64d361', 'c2d6fcc5-91e7-4a13-94d4-5dbf4792f858', 'es', '', '<div>h) comprometiendo, dirigiendo y apoyando a las personas, para contribuir a la eficacia del sistema de gestión de la calidad;</div>'),
    ('647ac43a-5aaa-4d2c-8a53-f74acaca771b', 'c1d6fb32-3904-47d8-a94c-a4324892f9eb', 'en', '', '<div>i) promoting improvement; </div>'),
    ('497a99b9-3f40-440b-8890-2215b5ca560c', 'c1d6fb32-3904-47d8-a94c-a4324892f9eb', 'es', '', '<div>i) promoviendo la mejora;</div>'),
    ('f1e520aa-8e4d-45dc-bc71-2c5ae4c7576b', 'b8d03142-e7f7-4424-8ec7-13a249a4449f', 'en', '', '<div>j) supporting other relevant management roles to demonstrate their leadership as it applies to their areas of responsibility. </div>'),
    ('f6e52889-1572-41db-a158-e3c5efc768bc', 'b8d03142-e7f7-4424-8ec7-13a249a4449f', 'es', '', '<div>j) apoyando otros roles pertinentes de la dirección, para demostrar su liderazgo en la forma en la que aplique a sus áreas de responsabilidad.</div>'),
    ('24e883d3-f760-43d5-bbda-9ea7d43cfca2', 'b9d032d5-7020-446f-b378-b3af48a4430c', 'en', 'Customer focus', '<div>Top management shall demonstrate leadership and commitment with respect to customer focus by ensuring that: </div><div>{clause_5.1.2.a}</div><div>{clause_5.1.2.b}</div><div>{clause_5.1.2.c}</div>'),
    ('3fe8ae54-fe19-4a36-828d-3f14c93ceb51', 'b9d032d5-7020-446f-b378-b3af48a4430c', 'es', 'Enfoque al cliente', '<div>La alta dirección debe demostrar liderazgo y compromiso con respecto al enfoque al cliente asegurándose de que:&nbsp;</div><div>{clause_5.1.2.a}</div><div>{clause_5.1.2.b}</div><div>{clause_5.1.2.c}</div>'),
    ('7fed58e8-25f6-42b6-81ca-fe70b8c87371', 'b6d02e1c-cb17-48de-bee1-96584ba447c5', 'en', '', '<div>a) customer and applicable statutory and regulatory requirements are determined, understood and consistently met;</div>'),
    ('6ced3aff-1f3e-4c55-af90-124bc3c884c2', 'b6d02e1c-cb17-48de-bee1-96584ba447c5', 'es', '', '<div>a) se determinan, se comprenden y se cumplen regularmente los requisitos del cliente y los legales y reglamentarios aplicables;</div>'),
    ('f70d0799-dc98-44df-b14a-71f522466320', 'b7d02faf-d1bb-4619-8643-7af54aa44632', 'en', '', '<div>b) the risks and opportunities that can affect conformity of products and services and the ability to enhance customer satisfaction are determined and addressed;</div>'),
    ('120d321a-948c-4608-a88c-c4aa3f4690c7', 'b7d02faf-d1bb-4619-8643-7af54aa44632', 'es', '', '<div>b) se determinan y se consideran los riesgos y oportunidades que pueden afectar a la conformidad de los productos y servicios y a la capacidad de aumentar la satisfacción del cliente;</div>'),
    ('f7b1d856-4f05-40d8-9a9b-399e9a169717', 'b4d02af6-7ddf-4be0-8958-3df645a43e53', 'en', '', '<div>c) the focus on enhancing customer satisfaction is maintained. </div>'),
    ('f4b1d39d-3fe7-4e0f-9092-fdf19d169bd0', 'b4d02af6-7ddf-4be0-8958-3df645a43e53', 'es', '', '<div>c) se mantiene el enfoque en el aumento de la satisfacción del cliente.</div>'),
    ('6463b4ff-0342-4f21-8019-1c4bba0b14ee', 'b5d02c89-71e9-4c9b-a33a-8c1344a43cc0', 'en', 'Policy', '<div>{clause_5.2.1}</div><div>{clause_5.2.2}</div>'),
    ('7763d2e8-3f02-42fa-9254-0870a70af705', 'b5d02c89-71e9-4c9b-a33a-8c1344a43cc0', 'es', 'Política', '<div>{clause_5.2.1}</div><div>{clause_5.2.2}</div>'),
    ('651c0d74-25e1-4a32-a6cd-4934be6e1bad', 'b2d027d0-6dd2-4d4a-bbb3-7b0c47a44179', 'en', 'Developing the quality policy', '<div>Top management shall establish, implement and maintain a quality policy that: </div><div>{clause_5.2.1.a}</div><div>{clause_5.2.1.b}</div><div>{clause_5.2.1.c}</div><div>{clause_5.2.1.d}</div>'),
    ('4a1be2f3-1832-4029-98ed-5047a16dee06', 'b2d027d0-6dd2-4d4a-bbb3-7b0c47a44179', 'es', 'Establecimiento de la política de la calidad', '<div>La alta dirección debe establecer, implementar y mantener una política de la calidad que:&nbsp;</div><div>{clause_5.2.1.a}</div><div>{clause_5.2.1.b}</div><div>{clause_5.2.1.c}</div><div>{clause_5.2.1.d}</div>'),
    ('fe8f4815-a904-460b-915a-b309077517ac', 'b3d02963-ab64-4df5-a12c-2e0946a43fe6', 'en', '', '<div>a) is appropriate to the purpose and context of the organization and supports its strategic direction; </div>'),
    ('f18f339e-c46e-4f2c-973c-4ea61c7538bb', 'b3d02963-ab64-4df5-a12c-2e0946a43fe6', 'es', '', '<div>a) sea apropiada al propósito y contexto de la organización y apoye su dirección estratégica;</div>'),
    ('ad011802-60fe-4cd4-b06f-e7d24c246873', 'c0d03dda-a2c9-4e0c-bb1d-85fa51a45137', 'en', '', '<div>b) provides a framework for setting quality objectives; </div>'),
    ('a20106b1-0da3-4003-925e-edcd672492f4', 'c0d03dda-a2c9-4e0c-bb1d-85fa51a45137', 'es', '', '<div>b) proporcione un marco de referencia para el establecimiento de los objetivos de la calidad;</div>'),
    ('4a31cd4b-c6b7-4e4d-8c95-899f1b9b6e4a', 'c1d03f6d-3243-4c77-9cec-896750a44fa4', 'en', '', '<div>c) includes a commitment to satisfy applicable requirements; </div>'),
    ('5531de9c-fb2c-495e-909b-701c209b7629', 'c1d03f6d-3243-4c77-9cec-896750a44fa4', 'es', '', '<div>c) incluya un compromiso de cumplir los requisitos aplicables;</div>'),
    ('03499209-324d-4cb3-865f-e945f376a024', 'bed2794b-2013-481d-9519-9c6543a1fc96', 'en', '', '<div>d) includes a commitment to continual improvement of the quality management system. </div>'),
    ('fe498a2a-3fa6-4b64-a178-31daf876a803', 'bed2794b-2013-481d-9519-9c6543a1fc96', 'es', '', '<div>d) incluya un compromiso de mejora continua del sistema de gestión de la calidad.</div>'),
    ('4c27eb98-a97a-4b9a-a46c-91408ce9dac5', 'bdd277b8-ad00-4052-950c-800844a1fe29', 'en', 'Communicating the quality policу', '<div>The quality policy shall: </div><div>{clause_5.2.2.a}</div><div>{clause_5.2.2.b}</div><div>{clause_5.2.2.c}</div>'),
    ('5928000f-546e-42c1-af4c-a57b9fe9f8ae', 'bdd277b8-ad00-4052-950c-800844a1fe29', 'es', 'Comunicación de la política de la calidad', '<div>La política de la calidad debe:&nbsp;</div><div>{clause_5.2.2.a}</div><div>{clause_5.2.2.b}</div><div>{clause_5.2.2.c}</div>'),
    ('bdc9d5c3-7f38-4249-9633-92f787e90346', 'c0d27c71-6232-4783-8a77-ed1f41a1f970', 'en', '', '<div>a) be available and be maintained as documented information; </div>'),
    ('b8c9cde4-8f62-4552-b008-eac4a4e930ed', 'c0d27c71-6232-4783-8a77-ed1f41a1f970', 'es', '', '<div>a) estar disponible y mantenerse como información documentada;</div>'),
    ('febf7bda-4b4d-4260-88c0-78ea32bd196f', 'bfd27ade-d9e1-44c8-a77a-811242a1fb03', 'en', '', '<div>b) be communicated, understood and applied within the organization; </div>'),
    ('e3bf5159-4494-4bc7-b698-593525bd04f8', 'bfd27ade-d9e1-44c8-a77a-811242a1fb03', 'es', '', '<div>b) comunicarse, entenderse y aplicarse dentro de la organización;</div>'),
    ('c8eed585-b5b0-41c7-b082-ec590da887d8', 'c2d27f97-e205-4361-a701-e0f947a202e2', 'en', '', '<div>c) be available to relevant interested parties, as appropriate. </div>'),
    ('dbeef36e-bc68-4860-b20b-4c161aa89c4f', 'c2d27f97-e205-4361-a701-e0f947a202e2', 'es', '', '<div>c) estar disponible para las partes interesadas pertinentes; según corresponda.</div>'),
    ('31f603e4-938d-409e-a5bf-6f44c7430449', 'c1d27e04-2065-4466-9003-ac7c48a20475', 'en', 'Organizational roles, responsibilities and authorities', '<div>Top management shall ensure that the responsibilities and authorities for relevant roles are assigned, communicated and understood within the organization.</div><div>Top management shall assign the responsibility and authority for:</div><div>{clause_5.3.a}</div><div>{clause_5.3.b}</div><div>{clause_5.3.c}</div><div>{clause_5.3.d}</div><div>{clause_5.3.e}</div>'),
    ('36f60bc3-6194-418d-8bea-1777c242fc6a', 'c1d27e04-2065-4466-9003-ac7c48a20475', 'es', 'Roles, responsabilidades y autoridades en la organización', '<div>La alta dirección debe asegurarse de que las responsabilidades y autoridades para los roles pertinentes se asignen, se comuniquen y se entiendan en toda la organización.</div><div>La alta dirección debe asignar la responsabilidad y autoridad para:</div><div>{clause_5.3.a}</div><div>{clause_5.3.b}</div><div>{clause_5.3.c}</div><div>{clause_5.3.d}</div><div>{clause_5.3.e}</div>'),
    ('713e102f-d7e7-433d-a7a1-e19bc2b8ee1a', 'c4d282bd-cf4f-49d7-840e-7ac345a1ffbc', 'en', '', '<div>a) ensuring that the quality management system conforms to the requirements of this International Standard; </div>'),
    ('643dfbb8-4e05-482e-a22b-4e60a7b8c399', 'c4d282bd-cf4f-49d7-840e-7ac345a1ffbc', 'es', '', '<div>a) asegurarse de que el sistema de gestión de la calidad es conforme con los requisitos de esta Norma Internacional;</div>'),
    ('c3edfe06-b7ea-4144-a186-b4ae7f4a7203', 'c3d2812a-3f22-47ec-a084-3ca646a2014f', 'en', '', '<div>b) ensuring that the processes are delivering their intended outputs; </div>'),
    ('e0ee2bad-a815-4693-be18-58e17a4a6a24', 'c3d2812a-3f22-47ec-a084-3ca646a2014f', 'es', '', '<div>b) asegurarse de que los procesos están generando y proporcionando las salidas previstas;</div>'),
    ('2b0bb181-a4b2-433b-8f70-6ebdae92977c', 'b6d26cb3-4542-4ed5-b4b6-d81d4ba2092e', 'en', '', '<div>c) reporting on the performance of the quality management system and on opportunities for improvement (see 10.1), in particular to top management; </div>'),
    ('160b9072-01c7-493c-a759-6422a392862b', 'b6d26cb3-4542-4ed5-b4b6-d81d4ba2092e', 'es', '', '<div>c) informar, en particular, a la alta dirección sobre el desempeño del sistema de gestión de la calidad y sobre las oportunidades de mejora (véase 10.1):</div>'),
    ('04cb0cf0-d8a6-4ce2-87a1-fcd8b233243d', 'b5d26b20-f191-45aa-90e8-2be04ca20ac1', 'en', '', '<div>d) ensuring the promotion of customer focus throughout the organization;</div>'),
    ('01cb0837-6ba9-4fb9-9408-3ce3b53328f6', 'b5d26b20-f191-45aa-90e8-2be04ca20ac1', 'es', '', '<div>d) asegurarse de que se promueve el enfoque al cliente en toda la organización;</div>'),
    ('8b3308b0-7e7d-4f92-8a0f-13988165140d', '2ccad7b0-8e0f-40b6-a0f3-27205d9fe6ed', 'en', '', '<div>e) ensuring that the integrity of the quality management system is maintained when changes to the quality management system are planned and implemented. </div>'),
    ('883303f7-6e53-4c89-9a54-e4a36464e666', '2ccad7b0-8e0f-40b6-a0f3-27205d9fe6ed', 'es', '', '<div>e) asegurarse de que la integridad del sistema de gestión de la calidad se mantiene cuando se planifican e implementan cambios en el sistema de gestión de la calidad.</div>'),
    ('aefad741-dafe-4eeb-bbe0-2e7dca6c100c', '2dcad943-5229-48b1-858b-915d5c9fe55a', 'en', 'Planning', '<div>{clause_6.1}</div><div>{clause_6.2}</div><div>{clause_6.3}</div>'),
    ('99fab632-f668-480c-967e-efe2df6c311b', '2dcad943-5229-48b1-858b-915d5c9fe55a', 'es', 'Planificación', '<div>{clause_6.1}</div><div>{clause_6.2}</div><div>{clause_6.3}</div>'),
    ('8a708eb2-8100-49b8-a346-6b62e9b256f7', '2ecadad6-974a-4c7c-ac53-3b6a5b9fe3c7', 'en', 'Actions to address risks and opportunities', '<div>{clause_6.1.1}</div><div>{clause_6.1.2}</div>'),
    ('9f70afc1-8586-466f-88a7-a9fdecb25bb0', '2ecadad6-974a-4c7c-ac53-3b6a5b9fe3c7', 'es', 'Acciones para abordar riesgos y oportunidades', '<div>{clause_6.1.1}</div><div>{clause_6.1.2}</div>'),
    ('dcd6537b-b495-4e81-9f23-262f09a867ce', '2fcadc69-3f73-4f27-aa87-d4d75a9fe234', 'en', '', '<div>When planning for the quality management system, the organization shall consider the issues referred to in 4.1 and the requirements referred to in 4.2 and determine the risks and opportunities that need to be addressed to: </div><div>{clause_6.1.1.a}</div><div>{clause_6.1.1.b}</div><div>{clause_6.1.1.c}</div><div>{clause_6.1.1.d}</div>'),
    ('c7d6326c-f055-455a-9280-a58cf6a849e5', '2fcadc69-3f73-4f27-aa87-d4d75a9fe234', 'es', '', '<div>Al planificar el SGIA, la organización debe considerar las cuestiones referidas en el apartado 4.1 y los requisitos referidos en los apartados 4.2 y 4.3 y determinar los riesgos y oportunidades, que es necesario abordar con el fin de: &nbsp;</div><div>{clause_6.1.1.a}</div><div>{clause_6.1.1.b}</div><div>{clause_6.1.1.c}</div><div>{clause_6.1.1.d}</div>'),
    ('710120fc-94b1-4096-a1df-78fc7bbdd8d1', '30caddfc-1aaa-4ca2-8a7c-2734599fe0a1', 'en', '', '<div>a) give assurance that the quality management system can achieve its intended result(s); </div>'),
    ('66010fab-77d8-4eb5-8a6d-647f86bdea22', '30caddfc-1aaa-4ca2-8a7c-2734599fe0a1', 'es', '', '<div>a) asegurar que el sistema de gestión de la calidad pueda lograr sus resultados previstos;</div>'),
    ('74a1adbd-0e92-4dbf-860d-cc11e2c15f80', '31cadf8f-8e5c-482d-9565-6391589fdf0e', 'en', '', '<div>b) enhance desirable effects; </div>'),
    ('77a1b276-c686-4ee8-a9a9-ce3effc18d27', '31cadf8f-8e5c-482d-9565-6391589fdf0e', 'es', '', '<div>b) aumentar los efectos deseables;</div>'),
    ('6f9f433e-3a67-4b3c-a9f7-ab463464aa4b', '32cae122-4a05-4a18-af19-6c1e579fdd7b', 'en', '', '<div>c) prevent, or reduce, undesired effects; </div>'),
    ('7c9f57b5-dd52-453b-b01b-9b293f64bb9c', '32cae122-4a05-4a18-af19-6c1e579fdd7b', 'es', '', '<div>c) prevenir o reducir efectos no deseados;</div>'),
    ('8fa99727-a5f3-4f35-aaa9-66339733f502', '33cae2b5-bc37-4453-8cb1-cb5b569fdbe8', 'en', '', '<div>d) achieve improvement. </div>'),
    ('72a96980-c2cc-4116-97ae-f2c88c33e3b1', '33cae2b5-bc37-4453-8cb1-cb5b569fdbe8', 'es', '', '<div>d) lograr la mejora</div>'),
    ('d0171158-013e-478a-9fd5-9900e8c22515', '34cae448-d519-4f0e-a3bd-fe48559fda55', 'en', '', '<div>The organization shall plan:</div><div>{clause_6.1.2.a}</div><div>{clause_6.1.2.b}</div><div>Actions taken to address risks and opportunities shall be proportionate to the potential impact on the conformity of products and services.</div><div>NOTE 1: Options to address risks can include avoiding risk, taking risk in order to pursue an opportunity, eliminating the risk source, changing the likelihood or consequences, sharing the risk, or retaining risk by informed decision.</div><div>NOTE 2: Opportunities can lead to the adoption of new practices, launching new products, opening new markets, addressing new clients, building partnerships, using new technology and other desirable and viable possibilities to address the organization''s or its customers'' needs. </div>'),
    ('dd1725cf-09a4-4991-98a8-133bdbc2109e', '34cae448-d519-4f0e-a3bd-fe48559fda55', 'es', '', '<div>La organización debe planificar:</div><div>{clause_6.1.2.a}</div><div>{clause_6.1.2.b}</div><div>Las acciones tomadas para abordar los riesgos y oportunidades deben ser proporcionales al impacto potencial en la conformidad de los productos y los servicios.</div><div>NOTA 1: Las opciones para abordar los riesgos pueden incluir: evitar riesgos, asumir riesgos para perseguir una oportunidad, eliminar la fuente de riesgo, cambiar la probabilidad y las consecuencias, compartir el riesgo o mantener riesgos mediante decisiones informadas.</div><div>NOTA 2: Las oportunidades pueden conducir a la adopción, de nuevas prácticas, lanzamiento de nuevos productos, apertura de nuevos mercados, acercamiento a nuevos clientes, establecimiento de asociaciones, utilización de nuevas tecnologías y otras posibilidades deseables y viables para abordar las necesidades de la organización o las de sus clientes.</div>'),
    ('89b18dc9-f171-4463-961a-43054f4eea74', '35cae5db-deeb-48c9-9171-f5a5549fd8c2', 'en', '', '<div>a) actions to address these risks and opportunities;</div>'),
    ('84b185ea-5870-40b4-a95a-199a344ebff3', '35cae5db-deeb-48c9-9171-f5a5549fd8c2', 'es', '', '<div>a) las acciones para abordar estos riesgos y oportunidades;</div>'),
    ('5c852097-d63e-4af1-bfea-c2c386473a9e', '32cd1fb9-5a18-4db7-be7f-da8bd79cd564', 'en', '', '<div>b) how to: </div><ul><li>{clause_6.1.2.b.1}</li><li>{clause_6.1.2.b.2}</li></ul>'),
    ('5f852550-ba33-496a-b3e6-dbb893474f15', '32cd1fb9-5a18-4db7-be7f-da8bd79cd564', 'es', '', '<div>b)&nbsp;la manera de:</div><ul><li>{clause_6.1.2.b.1}</li><li>{clause_6.1.2.b.2}</li></ul>'),
    ('7c799e6e-f138-4328-9867-219632f7e907', '31cd1e26-b150-474c-812f-9c0ed89cd6f7', 'en', '', '<div>1) integrate and implement the actions into its quality management system processes (see 4.4);</div>'),
    ('69798085-3946-44ff-96de-c1d915f7bb60', '31cd1e26-b150-474c-812f-9c0ed89cd6f7', 'es', '', '<div>1) integrar e implementar las acciones en sus procesos del sistema de gestión de la calidad (véase 4,4.);</div>'),
    ('80dca52d-eccc-449b-8466-5361144f72dc', '30cd1c93-56ae-4ec1-83f6-a741d99cd88a', 'en', '', '<div>2) evaluate the effectiveness of these actions. </div>'),
    ('63dc7786-49e1-4a9c-a7d4-af2e094f618b', '30cd1c93-56ae-4ec1-83f6-a741d99cd88a', 'es', '', '<div>2) evaluar la eficacia de estas acciones.</div>'),
    ('c9e3a12c-1e46-4542-840b-a9cc8b48121d', '2fcd1b00-a8b4-4f46-b445-98e4da9cda1d', 'en', 'Quality objectives and planning to achieve them', '<div>{clause_6.2.1}</div><div>{clause_6.2.2}</div>'),
    ('dee3c23b-9da3-4899-9c3d-926f8e4816d6', '2fcd1b00-a8b4-4f46-b445-98e4da9cda1d', 'es', 'Objetivos de la calidad y planificación para lograrlos', '<div>{clause_6.2.1}</div><div>{clause_6.2.2}</div>'),
    ('a735e0eb-970b-4ee5-a756-a53fa1188612', '36cd2605-d6dc-42e3-bf3e-2bc7d39ccf18', 'en', '', '<div>The organization shall establish quality objectives at relevant functions, levels and processes needed for the quality management system.</div><div>The quality objectives shall:</div><div>{clause_6.2.1.a}</div><div>{clause_6.2.1.b}</div><div>{clause_6.2.1.c}</div><div>{clause_6.2.1.d}</div><div>{clause_6.2.1.e}</div><div>{clause_6.2.1.f}</div><div>{clause_6.2.1.g}</div><div>The organization shall maintain documented information on the quality objectives. </div>'),
    ('b235f23c-2ad2-45a6-84af-a0bcb618a721', '36cd2605-d6dc-42e3-bf3e-2bc7d39ccf18', 'es', '', '<div>La organización debe establecer objetivos de la calidad para las funciones y niveles pertinentes y los procesos necesarios para el sistema de gestión de la calidad.</div><div>Los objetivos de la calidad deben:</div><div>{clause_6.2.1.a}</div><div>{clause_6.2.1.b}</div><div>{clause_6.2.1.c}</div><div>{clause_6.2.1.d}</div><div>{clause_6.2.1.e}</div><div>{clause_6.2.1.f}</div><div>{clause_6.2.1.g}</div><div>La organización debe mantener información documentada sobre los objetivos de la calidad.</div>'),
    ('96ab8622-0207-4d6c-8e3e-97f2f1024edb', '35cd2472-67d7-4528-8c25-f05ad49cd0ab', 'en', '', '<div>a) be consistent with the quality policy; </div>'),
    ('8bab74d1-e69d-444b-aef3-0d6ddc022dcc', '35cd2472-67d7-4528-8c25-f05ad49cd0ab', 'es', '', '<div>a) ser coherentes con la política de la calidad;</div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('7b36fcf1-7b9f-4daf-a50d-0c0d2e815a90', '34cd22df-aadc-4bfd-9012-ea0dd59cd23e', 'en', '', '<div>b) be measurable; </div>'),
    ('86370e42-9064-42f8-acc8-36122b8155d7', '34cd22df-aadc-4bfd-9012-ea0dd59cd23e', 'es', '', '<div>b) ser medibles;</div>'),
    ('e4b4eca0-0e8b-4b46-b2bb-d2e8c5a2cea1', '33cd214c-354f-4b32-98e5-ec50d69cd3d1', 'en', '', '<div>c) take into account applicable requirements; </div>'),
    ('01b51a47-4dd2-4d05-89bd-92d3b0a2ad92', '33cd214c-354f-4b32-98e5-ec50d69cd3d1', 'es', '', '<div>c) tener en cuenta los requisitos aplicables; </div>'),
    ('c167c89f-6e9a-46a9-a4d6-acebeda44ba6', '3acd2c51-8123-49af-8c19-4f73cf9cc8cc', 'en', '', '<div>d) be relevant to conformity of products and services and to enhancement of customer satisfaction; </div>'),
    ('d467e688-7c49-40b2-a874-63100aa4794d', '3acd2c51-8123-49af-8c19-4f73cf9cc8cc', 'es', '', '<div>d) ser pertinentes para la conformidad de los productos y servicios y para el aumento de la satisfacción del cliente;</div>'),
    ('e3d84276-f9e0-40c0-a6a3-10be0bd39a4f', '39cd2abe-1245-4b64-be68-5ad6d09cca5f', 'en', '', '<div>e) be monitored; </div>'),
    ('e0d83dbd-f326-4727-8307-0e91fed385d8', '39cd2abe-1245-4b64-be68-5ad6d09cca5f', 'es', '', '<div>e) ser objeto de seguimiento;</div>'),
    ('87609466-d6e1-4990-9bcf-db8e0a0207ff', '40ed896e-fc8c-4d70-9a14-98c641aec563', 'en', '', '<div>f) be communicated; </div>'),
    ('a460c20d-7408-4c57-a0a6-edc11d0225e8', '40ed896e-fc8c-4d70-9a14-98c641aec563', 'es', '', '<div>f) comunicarse;</div>'),
    ('a808b90f-340a-42b9-9c40-287b9d502b56', '41ed8b01-f3c1-47ab-808e-d16340aec3d0', 'en', '', '<div>g) be updated as appropriate.</div>'),
    ('9b08a498-a108-4fe2-9160-14409a50269d', '41ed8b01-f3c1-47ab-808e-d16340aec3d0', 'es', '', '<div>g) actualizarse, Según corresponda</div>'),
    ('f5689a44-2d6b-4d8a-98c4-61a4a42d9b15', '3eed8648-edcf-431a-9857-219c43aec889', 'en', '', '<div>When planning how to achieve its quality objectives, the organization shall determine: </div><div>{clause_6.2.2.a}</div><div>{clause_6.2.2.b}</div><div>{clause_6.2.2.c}</div><div>{clause_6.2.2.d}</div><div>{clause_6.2.2.e}</div>'),
    ('fa68a223-35d1-4f91-a658-4ad7972d869e', '3eed8648-edcf-431a-9857-219c43aec889', 'es', '', '<div>Al planificar cómo lograr sus objetivos de la calidad, la organización debe determinar:&nbsp;</div><div>{clause_6.2.2.a}</div><div>{clause_6.2.2.b}</div><div>{clause_6.2.2.c}</div><div>{clause_6.2.2.d}</div><div>{clause_6.2.2.e}</div>'),
    ('8c616be5-1d9d-4a63-b4ef-0cb90aba6074', '3fed87db-2a0e-4c85-8903-bb1942aec6f6', 'en', '', '<div>a) what will be done;</div>'),
    ('9f6189ce-849d-46b4-b576-9376efba35f3', '3fed87db-2a0e-4c85-8903-bb1942aec6f6', 'es', '', '<div>a) qué sé va a hacer;</div>'),
    ('c2307f3a-4f64-40b4-acd1-2a4aca86d6d3', '44ed8fba-7ff0-4ab4-b053-cf3245aecbaf', 'en', '', '<div>b) what resources will be required; </div>'),
    ('a73054b9-e864-4463-ab0d-5515e5870154', '44ed8fba-7ff0-4ab4-b053-cf3245aecbaf', 'es', '', '<div>b) qué recursos se requerirán;</div>'),
    ('f21ba8a3-fb92-4dad-836f-24d7978373aa', '45ed914d-f1fa-427f-9bdb-88bf44aeca1c', 'en', '', '<div>c) who will be responsible;</div>'),
    ('ed1ba0c4-143e-47be-b5db-3ba49c837b89', '45ed914d-f1fa-427f-9bdb-88bf44aeca1c', 'es', '', '<div>c) quién será responsable;</div>'),
    ('82f42778-1435-440e-912d-e4209cab5a99', '42ed8c94-630e-4c6e-92fa-c32847aeced5', 'en', '', '<div>d) when it will be completed; </div>'),
    ('8ff43bef-a142-489d-80c5-be5bb7ab851a', '42ed8c94-630e-4c6e-92fa-c32847aeced5', 'es', '', '<div>d) cuándo se finalizará;</div>'),
    ('c6ba9569-d3bc-4337-b6ca-75a5258babe8', '43ed8e27-69b4-4ca9-827f-960546aecd42', 'en', '', '<div>e) how the results will be evaluated.</div>'),
    ('c1ba8d8a-341b-4770-ad20-adba128b8dff', '43ed8e27-69b4-4ca9-827f-960546aecd42', 'es', '', '<div>e) cómo se evaluarán los resultados.</div>'),
    ('227dec5e-ad2c-4fb8-aa08-a2e6a51dccf7', '38ed7cd6-d7fc-4a78-be34-b47e49aed1fb', 'en', 'Planning of changes', '<div>When the organization determines the need for changes to the quality management system, the changes shall be carried out in a planned manner (see 4.4).</div><div>The organization shall consider:</div><div>{clause_6.3.a}</div><div>{clause_6.3.b}</div><div>{clause_6.3.c}</div><div>{clause_6.3.d}</div>'),
    ('2f7e00d5-b1b3-4c6f-bafc-2f49a81dd1b0', '38ed7cd6-d7fc-4a78-be34-b47e49aed1fb', 'es', 'Planificación de los cambios', '<div>Cuando la organización determine la necesidad de cambios en el sistema de gestión de la calidad, estos cambios se deben llevar a cabo de manera planificada (véase 4.4). </div><div>La organización debe considerar:</div><div>{clause_6.3.a}</div><div>{clause_6.3.b}</div><div>{clause_6.3.c}</div><div>{clause_6.3.d}</div>'),
    ('ccb431c7-e0c2-4481-a644-8753c513ddce', '39ed7e69-4700-4833-a71b-3dbb48aed068', 'en', '', '<div>a) the purpose of the changes and their potential consequences; </div>'),
    ('afb40420-1c82-4b5a-8f42-c768b213bfe5', '39ed7e69-4700-4833-a71b-3dbb48aed068', 'es', '', '<div>a) el propósito de los cambios y sus consecuencias potenciales;</div>'),
    ('827e6dd5-3a77-4a27-9c4d-a0c9a22a7eb8', '46efd177-d7fc-49b9-9f10-b449dbabe63a', 'en', '', '<div>b) the integrity of the quality management system; </div>'),
    ('757e595e-4131-43c0-8b5a-1466af2a932f', '46efd177-d7fc-49b9-9f10-b449dbabe63a', 'es', '', '<div>b) la integridad del sistema de gestión de la calidad;</div>'),
    ('eb859c34-846d-4d7e-bde8-11f4e86b55a9', '45efcfe4-d157-4c7e-98c0-a44cdcabe7cd', 'en', '', '<div>c) the availability of resources;</div>'),
    ('d08571b3-5274-4e6d-98e5-fc07e36b4dca', '45efcfe4-d157-4c7e-98c0-a44cdcabe7cd', 'es', '', '<div>c) la disponibilidad de recursos;</div>'),
    ('eacbb0bf-f6a1-471d-afaf-4a0be166d67a', '48efd49d-62bc-488f-b98a-8a53d9abe314', 'en', '', '<div>d) the allocation or reallocation of responsibilities and authorities. </div>'),
    ('fdcbcea8-6993-428e-8218-5a30c666abf9', '48efd49d-62bc-488f-b98a-8a53d9abe314', 'es', '', '<div>d) la asignación o reasignación de responsabilidades y autoridades.</div>'),
    ('7e1b6716-29b6-4fa4-9dde-165e13cc68e3', '47efd30a-da93-4844-bf08-bd36daabe4a7', 'en', 'Support', '<div>{clause_7.1}</div><div>{clause_7.2}</div><div>{clause_7.3}</div><div>{clause_7.4}</div><div>{clause_7.5}</div>'),
    ('7b1b625d-35a8-42f3-84b9-91b10ecc6104', '47efd30a-da93-4844-bf08-bd36daabe4a7', 'es', 'Apoyo', '<div>{clause_7.1}</div><div>{clause_7.2}</div><div>{clause_7.3}</div><div>{clause_7.4}</div><div>{clause_7.5}</div>'),
    ('7d769659-0a92-4513-ad82-c7b5149ef184', '42efcb2b-b1a4-4195-849a-2035d7abdfee', 'en', 'Resources', '<div>{clause_7.1.1}</div><div>{clause_7.1.2}</div><div>{clause_7.1.3}</div><div>{clause_7.1.4}</div><div>{clause_7.1.5}</div><div>{clause_7.1.6}</div>'),
    ('9876c0da-1a67-4fc4-bfaa-e76a199ef963', '42efcb2b-b1a4-4195-849a-2035d7abdfee', 'es', 'Recursos', '<div>{clause_7.1.1}</div><div>{clause_7.1.2}</div><div>{clause_7.1.3}</div><div>{clause_7.1.4}</div><div>{clause_7.1.5}</div><div>{clause_7.1.6}</div>'),
    ('03daeba8-c509-45fa-b18f-5030ae122c25', '41efc998-5df3-486a-a92a-fb98d8abe181', 'en', 'General', '<div>The organization shall determine and provide the resources needed for the establishment, implementation, maintenance and continual improvement of the quality management system.</div><div>The organization shall consider:</div><div>{clause_7.1.1.a}</div><div>{clause_7.1.1.b}</div>'),
    ('f0dacdbf-894a-4221-9f26-400bc1124a0e', '41efc998-5df3-486a-a92a-fb98d8abe181', 'es', 'Generalidades', '<div>La organización debe determinar y proporcionar los recursos-necesarios para el establecimiento, implementación, mantenimiento y mejora continua del sistema de gestión de la calidad.</div><div>La organización debe considerar:</div><div>{clause_7.1.1.a}</div><div>{clause_7.1.1.b}</div>'),
    ('a8d61693-9ac7-4ca9-b7d3-4a67a90fc1a6', '44efce51-620a-47bb-ba2f-72efd5abdcc8', 'en', '', '<div>a) the capabilities of,and constraints on, existing internal resources;</div>'),
    ('c3d64114-a876-46b2-9a5a-97d4c60fef4d', '44efce51-620a-47bb-ba2f-72efd5abdcc8', 'es', '', '<div>a) las capacidades y limitaciones de los recursos internos existentes;</div>'),
    ('784d1c6a-260d-46c0-8453-141ac73f104f', '43efccbe-572e-4b00-8322-65e2d6abde5b', 'en', '', '<div>b) what needs to be obtained from external providers. </div>'),
    ('7d4d2449-1f53-4d27-b113-3d85ba3efbd8', '43efccbe-572e-4b00-8322-65e2d6abde5b', 'es', '', '<div>b) qué se necesita obtener de los proveedores externos.</div>'),
    ('1d9a32cd-a7cc-43af-829b-5f81e9ecd090', '3eefc4df-4e68-4921-9376-cc21d3abd9a2', 'en', 'Рeople', '<div>The organization shall determine and provide the persons necessary for the effective implementation of its quality management system and for the operation and control of its processes. </div>'),
    ('009a0526-bc91-48f8-9d4a-644ee6eccbd7', '3eefc4df-4e68-4921-9376-cc21d3abd9a2', 'es', 'Personas', '<div>La organización debe determinar y proporcionar las personas necesarias para la implementación eficaz de su sistema de gestión de la calidad y para la operación y control de sus procesos.</div>'),
    ('6426c5cc-3ab8-4146-ac9a-656c810e44a1', '3defc34c-7100-4926-bf06-7544d4abdb35', 'en', 'Infrastructure', '<div>The organization shall determine, provide and maintain the infrastructure necessary for the operation of its processes and to achieve conformity of products and services.</div><div>NOTE: Infrastructure can include:<br>{clause_7.1.3.a}</div><div>{clause_7.1.3.b}</div><div>{clause_7.1.3.c}</div><div>{clause_7.1.3.d}</div>'),
    ('7926e6db-79fe-4305-b4e4-250f6c0e2392', '3defc34c-7100-4926-bf06-7544d4abdb35', 'es', 'Infraestructura', '<div>La organización debe determinar, proporcionar y mantener la infraestructura necesaria para la operación de sus procesos y lograr la conformidad de los productos y servicios.</div><div>NOTA: La infraestructura puede incluir:<br>{clause_7.1.3.a}</div><div>{clause_7.1.3.b}</div><div>{clause_7.1.3.c}</div><div>{clause_7.1.3.d}</div>'),
    ('9b96664f-c87c-4f89-8ba3-963b61b55e06', 'af714eb1-d7d0-4edb-80ef-95a353032730', 'en', '', '<div>a) buildings and associated utilities;</div>'),
    ('8e9651d8-d8a6-4292-92d1-1c007eb58bad', 'af714eb1-d7d0-4edb-80ef-95a353032730', 'es', '', '<div>a) edificios y servicios asociados;</div>'),
    ('7d6717a6-4113-4fa0-8dfe-dd4e0f05702f', 'ae714d1e-e642-4a20-9d24-5406540328c3', 'en', '', '<div>b) equipment, including hardware and software; </div>'),
    ('9a67454d-3a59-4607-b34f-d88102055bb8', 'ae714d1e-e642-4a20-9d24-5406540328c3', 'es', '', '<div>b) equipo, incluyendo hardware y software;</div>'),
    ('82698225-979d-4ff3-bacc-4779cfbd63e4', 'ad714b8b-114b-4035-a128-9d5955032a56', 'en', '', '<div>c) transportation resources; </div>'),
    ('9569a00e-8bab-4ca4-9aa4-8e36d4bd6bc3', 'ad714b8b-114b-4035-a128-9d5955032a56', 'es', '', '<div>c) recursos de transporte;</div>'),
    ('e8f64784-4df1-4eda-aee9-1d6466b63585', 'ac7149f8-ed06-448a-9ee2-56dc56032be9', 'en', '', '<div>d) information and communication technology. </div>'),
    ('edf64f63-1230-4801-9e09-ae9779b6536e', 'ac7149f8-ed06-448a-9ee2-56dc56032be9', 'es', '', '<div>d) tecnología de la información y la comunicación.</div>'),
    ('e823bee3-3cf1-4b7d-bb20-88979c86dbda', 'b37154fd-d883-42af-a3ba-bfff57032d7c', 'en', 'Environment for the operation of processes', '<div>The organization shall determine, provide and maintain the environment necessary for the operation of its processes and to achieve conformity of products and services.</div><div>NOTE: A suitable environment can be a combination of human and physical factors, such as:<br>{clause_7.1.4.a}</div><div>{clause_7.1.4.b}</div><div>{clause_7.1.4.c}</div><div>These factors can differ substantially depending on the products and services provided. </div>'),
    ('e323b704-b30e-406e-8bff-f7648186b159', 'b37154fd-d883-42af-a3ba-bfff57032d7c', 'es', 'Ambiente para la operación de los procesos', '<div>La organización debe determinar, proporcionar y mantener el ambiente necesario para la operación de sus procesos y para lograr la conformidad de los productos y servicios.</div><div>NOTA: Un ambiente adecuado puede ser una combinación de factores humanos y físicos, tales como:<br>{clause_7.1.4.a}</div><div>{clause_7.1.4.b}</div><div>{clause_7.1.4.c}</div><div> Estos factores pueden diferir sustancialmente dependiendo de los productos y servicios suministrados.</div>'),
    ('b5be2c7a-7333-4084-805d-b50a5b9135c3', 'b271536a-69a5-4464-99fa-007258032f0f', 'en', '', '<div>a) social (e.g. non-discriminatory, calm, non-confrontational);</div>'),
    ('9abe01f9-65d8-4ed3-a617-b3d556912de4', 'b271536a-69a5-4464-99fa-007258032f0f', 'es', '', '<div>a) sociales (por ejemplo, no discriminatorio, ambiente tranquilo, libre de conflictos);</div>'),
    ('bcc2aba9-ab75-4c07-a996-3365e9ef4b98', 'b17151d7-50f1-4059-b05c-8045590330a2', 'en', '', '<div>b) psychological (e.g. stress-reducing, burnout prevention, emotionally protective);</div>'),
    ('b7c2a3ca-b22f-45a0-b6a6-027af6ef600f', 'b17151d7-50f1-4059-b05c-8045590330a2', 'es', '', '<div>b) psicológicos (por ejemplo, reducción del estrés, prevención del síndrome de agotamiento, cuidado de las emociones);</div>'),
    ('7681d4b8-3804-43de-b452-2ee0a110f209', 'b0715044-4a4b-401e-8ee5-b9685a033235', 'en', '', '<div>c) physical (e.g. temperature, heat, humidity, light, airflow, hygiene, noise). </div>'),
    ('8381e92f-038f-48cd-b9c8-c21b9c10ea2a', 'b0715044-4a4b-401e-8ee5-b9685a033235', 'es', '', '<div>c) físicos (por ejemplo, temperatura, calor, humedad, iluminación, circulación del aire, higiene, ruido). Estos factores pueden diferir sustancialmente dependiendo de los productos y servicios suministrados.</div>'),
    ('c2bab507-b600-4451-9da2-83138979107e', 'a7714219-2e3d-4be3-a06c-eefb5b0333c8', 'en', 'Мonitoring and measuring resources', '<div>{clause_7.1.5.1}</div><div>{clause_7.1.5.2}</div>'),
    ('a5ba8760-b016-4e4a-b29c-fd28967924f5', 'a7714219-2e3d-4be3-a06c-eefb5b0333c8', 'es', 'Recursos de seguimiento y medición', '<div>{clause_7.1.5.1}</div><div>{clause_7.1.5.2}</div>'),
    ('160a069e-8e63-4b08-b153-5aa6a9836467', 'a6714086-bf38-4e28-b13b-e0be5c03355b', 'en', 'General', '<div>The organization shall determine and provide the resources needed to ensure valid and reliable results when monitoring or measuring is used to verify the conformity of products and services to requirements.</div><div>The organization shall ensure that the resources provided:</div><div>{clause_7.1.5.1.a}</div><div>{clause_7.1.5.1.b}</div><div>The organization shall retain appropriate documented information as evidence of fitness for purpose of the monitoring and measurement resources.</div>'),
    ('230a1b15-d66f-49df-ab71-bf098c8336c0', 'a6714086-bf38-4e28-b13b-e0be5c03355b', 'es', 'Generalidades', '<div>La organización debe determinar y proporcionarlos recursos necesarios para asegurarse de la validez y fiabilidad de los resultados cuando se realice el seguimiento o la medición para verificar la conformidad de los productos y servicios con los requisitos.</div><div>La organización debe asegurarse de que los recursos proporcionados:</div><div>{clause_7.1.5.1.a}</div><div>{clause_7.1.5.1.b}</div><div>La organización debe conservar la información documentada apropiada como evidencia de que los recursos de seguimiento y medición son idóneos para su propósito.</div>'),
    ('aa45af08-5d9b-496a-8070-8c10ff991a75', 'a96f06a8-d300-49ba-b456-d43859056f39', 'en', '', '<div>a) are suitable for the specific type of monitoring and measurement activities being undertaken;</div>'),
    ('9745911f-79a6-4af1-bcd2-d5ebf29905fe', 'a96f06a8-d300-49ba-b456-d43859056f39', 'es', '', '<div>a) son apropiados para el tipo específico de actividades de seguimiento y medición realizadas;</div>'),
    ('23dfc6b9-63eb-4bc3-afe8-b315dbf9ee54', 'aa6f083b-0cc7-4d25-b85c-235558056da6', 'en', '', '<div>b) are maintained to ensure their continuing fitness for their purpose.</div>'),
    ('3edff13a-b4cc-4f94-b1ac-884ac0f9c3d3', 'aa6f083b-0cc7-4d25-b85c-235558056da6', 'es', '', '<div>b) se mantienen para asegurarse de la idoneidad continua para su propósito.</div>'),
    ('ab5e3a4a-4565-4270-919e-fcfadb4002df', 'ab6f09ce-cb9d-4b90-a290-268257056c13', 'en', 'Measurement traceability', '<div>When measurement traceability is a requirement, or is considered by the organization to be an essential part of providing confidence in the validity of measurement results, measuring equipment shall be:</div><div>{clause_7.1.5.2.a}</div><div>{clause_7.1.5.2.b}</div><div>{clause_7.1.5.2.c}</div><div>The organization shall determine if the validity of previous measurement results has been adversely affected when measuring equipment is found to be unfit for its intended purpose, and shall take appropriate action as necessary. </div>'),
    ('b05e4229-e506-4e37-848f-2de5ee4020c8', 'ab6f09ce-cb9d-4b90-a290-268257056c13', 'es', 'Trazabilidad de las mediciones', '<div>Cuando la trazabilidad de las mediciones es un requisito, o es considerada por la organización como parte esencial para proporcionar confianza en la validez de los resultados de la medición, el equipo de medición debe:</div><div>{clause_7.1.5.2.a}</div><div>{clause_7.1.5.2.b}</div><div>{clause_7.1.5.2.c}</div><div>La organización debe determinar si la validez de los resultados de medición previos se ha visto afectada de manera adversa cuando el equipo de medición se considere no apto para su propósito previsto, y debe tomar las acciones adecuadas cuando sea necesario.</div>'),
    ('dbe73473-bcf3-4b99-8074-7ec7fb3613b6', 'ac6f0b61-bd2d-434b-bd6d-648f56056a80', 'en', '', '<div>a) calibrated or verified, or both, at specified intervals, or prior to use, against measurement standards traceable to international or national measurement standards; when no such standards exist, the basis used for calibration or verification shall be retained as documented information; </div>'),
    ('f6e75ef4-3d95-4842-8e54-77b4f8360efd', 'ac6f0b61-bd2d-434b-bd6d-648f56056a80', 'es', '', '<div>a) calibrarse o verificarse, o ambas, a intervalos especificados, o antes de su utilización, contra patrones de medición trazables a patrones de medición internacionales o nacionales; cuando no existan tales patrones, debe conservarse como información documentada la base utilizada para la calibración o la verificación;</div>'),
    ('8f746394-5db0-41ee-8f5f-90546deae879', 'ad6f0cf4-2c7a-480e-881b-94ec5d057585', 'en', '', '<div>b) identified in order to determine their status; </div>'),
    ('74743913-e792-4cfd-acd8-42e788eb12fa', 'ad6f0cf4-2c7a-480e-881b-94ec5d057585', 'es', '', '<div>b) identificarse para determinar su estado;</div>'),
    ('b58df8b5-2e9b-4c97-8859-9429f6c9a6c8', 'ae6f0e87-364c-41c9-8ad8-bfe95c0573f2', 'en', '', '<div>c) safeguarded from adjustments, damage or deterioration that would invalidate the calibration status and subsequent measurement results. </div>'),
    ('a88de43e-8efa-40d0-8235-a446e3c988df', 'ae6f0e87-364c-41c9-8ad8-bfe95c0573f2', 'es', '', '<div>c) protegerse contra ajustes, daño o deterioro que pudieran invalidar el estado de calibración y los posteriores resultados de la medición.</div>'),
    ('b12c84f6-aa41-4714-8443-d4be25f25633', 'af6f101a-4f02-48d4-b01f-bed65b05725f', 'en', 'Organizational knowledge', '<div>The organization shall determine the knowledge necessary for the operation of its processes and to achieve conformity of products and services.</div><div>This knowledge shall be maintained and be made available to the extent necessary.</div><div>When addressing changing needs and trends, the organization shall consider its current knowledge and determine how to acquire or access any necessary additional knowledge and required updates.</div><div>NOTE 1: Organizational knowledge is knowledge specific to the organization; it is gained by experience. It is information that is used and shared to achieve the organization''s objectives.</div><div>NOTE 2: Organizational knowledge can be based on:</div><div>{clause_7.1.6.a}</div><div>{clause_7.1.6.b}</div>'),
    ('ae2c803d-5960-4343-a0a7-d29140f280b4', 'af6f101a-4f02-48d4-b01f-bed65b05725f', 'es', 'Conocimientos de la organización', '<div>La organización debe determinar los conocimientos necesarios para la operación de sus procesos y para lograr la conformidad de los productos y servicios.</div><div>Estos conocimientos deben mantenerse y ponerse a disposición en la medida en que sea necesario.</div><div>Cuando se abordan las necesidades y tendencias cambiantes, la organización debe considerar sus conocimientos Actuales y determinar cómo adquirir o acceder a los conocimientos adicionales necesarias yolas actualizaciones requeridas.</div><div>NOTA 1: Los conocimientos de la organización son conocimientos específicos que la organización adquiere generalmente con la experiencia. Es información que se utiliza y se comparte para lograr los objetivos de la organización.</div><div>NOTA 2: Los conocimientos de la organización pueden basarse en:</div><div>{clause_7.1.6.a}</div><div>{clause_7.1.6.b}</div>'),
    ('8ebc0b1f-d5ca-408d-8277-70ebf567c90a', 'b06f11ad-bdde-441f-bdd0-b3735a0570cc', 'en', '', '<div>a) internal sources (e.g. intellectual property; knowledge gained from experience; lessons learned from failures and successful projects; capturing and sharing undocumented knowledge and experience; the results of improvements in processes, products and services); </div>'),
    ('a1bc2908-07c3-4f9e-8615-2710fa67d0e9', 'b06f11ad-bdde-441f-bdd0-b3735a0570cc', 'es', '', '<div>a) fuentes internas (por ejemplo, propiedad intelectual; conocimientos adquiridos con la experiencia; lecciones aprendidas de los fracasos y de proyectos de éxito; capturar y compartir conocimientos y experiencia no documentados; los resultados de las mejoras en los procesos, productos y servicios);</div>'),
    ('b2092f20-8dab-4672-905c-96e89ab6726d', 'a16efa10-720b-45a2-8a9d-505061057bd1', 'en', '', '<div>b) external sources (e.g. standards; academia; conferences; gathering knowledge from customers or external providers). </div>'),
    ('cf095cc7-6435-4e69-a75e-56d37db644c6', 'a16efa10-720b-45a2-8a9d-505061057bd1', 'es', '', '<div>b) fuentes externas (por ejemplo, normas; academia; conferencias; recopilación de conocimientos provenientes de clientes o proveedores externos).</div>'),
    ('488b3f71-4d7b-494b-82ad-d00de143056c', 'a26efba3-e5bc-412d-81ca-4e0d60057a3e', 'en', 'Competence', '<div>The organization shall: </div><div>{clause_7.2.a}</div><div>{clause_7.2.b}</div><div>{clause_7.2.c}</div><div>{clause_7.2.d}</div><div>NOTE: Applicable actions can include, for example, the provision of training to, the mentoring of, or the reassignment of currently employed persons; or the hiring or contracting of competent persons. </div>'),
    ('538b50c2-68e5-426c-8a68-fa12f643267b', 'a26efba3-e5bc-412d-81ca-4e0d60057a3e', 'es', 'Competencia', '<div>La organización debe:&nbsp;</div><div>{clause_7.2.a}</div><div>{clause_7.2.b}</div><div>{clause_7.2.c}</div><div>{clause_7.2.d}</div><div>NOTA: Las acciones aplicables pueden incluir, por ejemplo, la formación, la tutoría o la reasignación de las personas empleadas actualmente; o la contratación o subcontratación de personas competentes.</div>'),
    ('a5015a81-730f-478b-bff4-7d3d67ab012c', '1b7675e3-3965-4c61-a110-2a9ddf0880c2', 'en', '', '<div>a) determine the necessary competence of person(s) doing work under its control that affects the performance and effectiveness of the quality management system; </div>'),
    ('90013972-8e79-40ac-97dd-72a27cab223b', '1b7675e3-3965-4c61-a110-2a9ddf0880c2', 'es', '', '<div>a) determinar la competencia necesaria de las personas que realizan, bajo su control, un trabajo que afecta al desempeño y eficacia del sistema de gestión de la calidad;</div>'),
    ('7ec0b5f0-efec-4bb2-b826-0b581ea4052d', '1a767450-77c5-4d66-bd41-7e60e0088255', 'en', '', '<div>b) ensure thatthese persons are competent on the basis of appropriate education, training, or experience;</div>'),
    ('7bc0b137-e23d-41a9-848c-4b6301a3d786', '1a767450-77c5-4d66-bd41-7e60e0088255', 'es', '', '<div>b) asegurarse de que estas personas sean competentes, basándose en la educación, formación o experiencia apropiadas;</div>'),
    ('d0626dbb-cd4d-40a1-9ede-23ef1a40fe6e', '1d767909-26af-42d7-a116-0717dd087d9c', 'en', '', '<div>c) where applicable, take actions to acquire the necessary competence, and evaluate the effectiveness of the actions taken; </div>'),
    ('bb624cac-090d-447a-86ac-3b4c0740e085', '1d767909-26af-42d7-a116-0717dd087d9c', 'es', '', '<div>c) cuando sea aplicable, tomar acciones para adquirir la competencia necesaria y evaluar la eficacia de las acciones tomadas;</div>'),
    ('807711f2-1910-4258-99c0-7f22fa4c8097', '1c767776-9682-40ec-8220-8faade087f2f', 'en', '', '<div>d) retain appropriate documented information as evidence of competence. </div>'),
    ('95773301-09f2-4f8f-81d7-89bdfd4c8550', '1c767776-9682-40ec-8220-8faade087f2f', 'es', '', '<div>d) conservar la información documentada apropiada como evidencia de la competencia.</div>'),
    ('6aa830fd-a6a3-465f-b8b1-bfd1827c4ca0', '1f767c2f-7773-411d-8ad2-52d1db087a76', 'en', 'Awareness', '<div>The organization shall ensure that persons doing work under the organization''s control are aware of: </div><div>{clause_7.3.a}</div><div>{clause_7.3.b}</div><div>{clause_7.3.c}</div><div>{clause_7.3.d}</div>'),
    ('6da835b6-5e97-4788-aa7f-adfe9f7c7a47', '1f767c2f-7773-411d-8ad2-52d1db087a76', 'es', 'Toma de conciencia', '<div>La organización debe asegurarse de que las personas que realizan el trabajo bajo el control de la organización tomen conciencia de:&nbsp;</div><div>{clause_7.3.a}</div><div>{clause_7.3.b}</div><div>{clause_7.3.c}</div><div>{clause_7.3.d}</div>'),
    ('648ece3c-f001-4436-9237-56bc18fe5cf1', '1e767a9c-0461-4952-93f7-6974dc087c09', 'en', '', '<div>a) the quality policу; </div>'),
    ('598ebceb-e949-4dd5-b4de-5b3f23fe6e42', '1e767a9c-0461-4952-93f7-6974dc087c09', 'es', '', '<div>a) la política de la calidad;</div>'),
    ('85b1ad67-c16b-4555-b4a2-a8f33472e622', '21767f55-b993-4083-957d-d99bd9087750', 'en', '', '<div>b) relevant quality objectives; </div>'),
    ('68b17fc0-c824-4bb6-a8d5-8d882972d4d1', '21767f55-b993-4083-957d-d99bd9087750', 'es', '', '<div>b) los objetivos de la calidad pertinentes;</div>'),
    ('65a7597e-5858-475c-9a53-f80644fd40eb', '20767dc2-3141-4dc8-ac50-815eda0878e3', 'en', '', '<div>c) their contribution to the effectiveness of the quality management system, including the benefits of improved performance;</div>'),
    ('72a76df5-df7d-435b-a8ab-4ce94ffd523c', '20767dc2-3141-4dc8-ac50-815eda0878e3', 'es', '', '<div>c) su contribución a la eficacia del sistema de gestión de la calidad, incluidos los beneficios de una mejora del desempeño;</div>'),
    ('7d3f3b09-3831-4303-b6e3-f7c55fe78114', '2376827b-dc47-44f9-8172-eee5e7088d5a', 'en', '', '<div>d) the implications of not conforming with the quality management system requirements. </div>'),
    ('783f332a-8b8c-4fd4-91fc-405a44e75693', '2376827b-dc47-44f9-8172-eee5e7088d5a', 'es', '', '<div>d) las implicaciones del incumplimiento de los requisitos del sistema de gestión de la calidad</div>'),
    ('c61d9498-c29d-42aa-94f0-9fc086011635', '227680e8-bc54-4fbe-8165-d288e8088eed', 'en', 'Communication', '<div>The organization shall determine the internal and external communications relevant to the quality management system, including: </div><div>{clause_7.4.a}</div><div>{clause_7.4.b}</div><div>{clause_7.4.c}</div><div>{clause_7.4.d}</div><div>{clause_7.4.e}</div>'),
    ('d31da90f-e120-4a31-9fd0-b3fb790101be', '227680e8-bc54-4fbe-8165-d288e8088eed', 'es', 'Comunicación', '<div>La organización debe determinar las comunicaciones internas y externas pertinentes al sistema de gestión de la calidad, que incluyan:&nbsp;</div><div>{clause_7.4.a}</div><div>{clause_7.4.b}</div><div>{clause_7.4.c}</div><div>{clause_7.4.d}</div><div>{clause_7.4.e}</div>'),
    ('26f6c102-2050-4db4-a0f3-f652c2afe3d3', 'b57396ba-c2fa-40b8-a776-d87ae50ac8cb', 'en', '', '<div>a) on what it will communicate; </div>'),
    ('1bf6afb1-b951-4163-82e2-fc4dddb00e54', 'b57396ba-c2fa-40b8-a776-d87ae50ac8cb', 'es', '', '<div>a) que comunicar;</div>'),
    ('c427764b-cc7f-4aad-bd19-981f8fac80aa', 'b673984d-4b4a-4073-8945-dbe7e40ac738', 'en', '', '<div>b) when to communicate; </div>'),
    ('cf27879c-e52b-44be-811f-7e9c94ac8889', 'b673984d-4b4a-4073-8945-dbe7e40ac738', 'es', '', '<div>b) cuándo comunicar; </div>'),
    ('72842b80-e522-410e-8de4-534894d46799', 'b3739394-a9be-4bc2-abef-3c70e70acbf1', 'en', '', '<div>c) with whom to communicate; </div>'),
    ('8f845927-722f-459d-a0de-c6b3afd4921a', 'b3739394-a9be-4bc2-abef-3c70e70acbf1', 'es', '', '<div>c) a quién comunicar; </div>'),
    ('0b80a4d1-a4a9-4037-b398-95ed1db4b8e8', 'b4739527-ee02-46cd-ad87-f92de60aca5e', 'en', '', '<div>d) how to communicate;</div>'),
    ('1680b622-0508-4470-92e4-20720ab49aff', 'b4739527-ee02-46cd-ad87-f92de60aca5e', 'es', '', '<div>d) cómo comunicar;</div>'),
    ('996b33ce-a7ce-4690-b2c5-c776022b14ff', 'b173906e-265e-4b9c-a58c-cfaee90acf17', 'en', '', '<div>e) who communicates. </div>'),
    ('866b15e5-44f5-4957-b23e-40b9152b32e8', 'b173906e-265e-4b9c-a58c-cfaee90acf17', 'es', '', '<div>e) quién comunica.</div>'),
    ('797522f7-04f7-4fb9-9ece-faa395793856', 'b2739201-ce87-4e47-ac0f-192be80acd84', 'en', 'Documented information', '<div>{clause_7.5.1}</div><div>{clause_7.5.2}</div><div>{clause_7.5.3}</div>'),
    ('7c7527b0-71f5-4ce2-8e89-29989279339d', 'b2739201-ce87-4e47-ac0f-192be80acd84', 'es', 'Información documentada', '<div>{clause_7.5.1}</div><div>{clause_7.5.2}</div><div>{clause_7.5.3}</div>'),
    ('5a2edc0c-fe58-4a8a-9fb2-272c9c56a815', 'af738d48-1d21-4cd6-ab83-ba84eb0ad23d', 'en', 'General', '<div>The organization''s quality management system shall include: </div><div>{clause_7.5.1.a}</div><div>{clause_7.5.1.b}</div><div>NOTE The extent of documented information for a quality management system can differ from one organization to another due to:</div><div>- the size of organization and its type of activities, processes, products and services; </div><div>- the complexity of processes and their interactions;</div><div>- the competence of persons. </div>'),
    ('6f2efd1b-06be-4c91-b45b-89cf8f56939e', 'af738d48-1d21-4cd6-ab83-ba84eb0ad23d', 'es', 'Generalidades', '<div>El sistema de gestión de la calidad de la organización debe incluir:&nbsp;</div><div>{clause_7.5.1.a}</div><div>{clause_7.5.1.b}</div><div>NOTA: La extensión de la información documentada para un sistema de gestión de la calidad puede variar de una organización a otra, debido a:</div><div>— el tamaño de la organización y a su tipo de actividades, procesos, productos y servicios;</div><div>— la complejidad de los procesos y sus interacciones;</div><div>— la competencia de las personas.</div>'),
    ('1127e00d-ee8a-4763-9b9a-144102e36d74', 'b0738edb-cb1c-4c51-9230-4e61ea0ad0aa', 'en', '', '<div>a) documented information required by this International Standard; </div>'),
    ('f427b266-558a-43b4-96c3-020ee7e342f3', 'b0738edb-cb1c-4c51-9230-4e61ea0ad0aa', 'es', '', '<div>a) la información documentada requerida por esta Norma Internacional;</div>'),
    ('6bdac9aa-3780-4e3c-acf5-3adae7f92d4b', 'ad738a22-034f-4eb0-bb20-6622dd0abc33', 'en', '', '<div>b) documented information determined by the organization as being necessary for the effectiveness of the quality management system. </div>'),
    ('70dad189-da6c-483b-91dc-f245f2f93e9c', 'ad738a22-034f-4eb0-bb20-6622dd0abc33', 'es', '', '<div>b) la información documentada que la organización determina como necesaria para la eficacia del sistema de gestión de la calidad.</div>'),
    ('9ede2cd3-a30c-4235-ac5e-ad274ac87802', 'ae738bb5-debf-4deb-9fd2-062fdc0abaa0', 'en', 'Creating and updating', '<div>When creating and updating documented information, the organization shall ensure appropriate:</div><div>{clause_7.5.2.a}</div><div>{clause_7.5.2.b}</div><div>{clause_7.5.2.c}</div>'),
    ('b9de5754-bfe6-4416-b311-4d943fc866b1', 'ae738bb5-debf-4deb-9fd2-062fdc0abaa0', 'es', 'Creación y actualización', '<div>Al crear y actualizar la información documentada, la organización debe asegurarse de que lo siguiente sea apropiado:</div><div>{clause_7.5.2.a}</div><div>{clause_7.5.2.b}</div><div>{clause_7.5.2.c}</div>'),
    ('18749e13-79cd-4275-b2f6-db67ceb79dc2', '277b05f5-4972-4d47-a4df-abefeb0d10d4', 'en', '', '<div>a) identification and description (e.g. a title, date, author, or reference number);</div>'),
    ('3374c894-942a-4856-957e-28d4c3b78c71', '277b05f5-4972-4d47-a4df-abefeb0d10d4', 'es', '', '<div>a) la identificación y descripción (por ejemplo, titulo, fecha, autor o número de referencia);</div>'),
    ('e7eba3ea-9efa-4d7c-bf76-a51a6e61290b', '267b0462-a149-4a9c-add2-9ee2ec0d1267', 'en', '', '<div>b) format (e.g. language, software version, graphics) and media (e.g. paper, electronic); </div>'),
    ('ecebabc9-3f6d-417b-ac36-ce8579613a5c', '267b0462-a149-4a9c-add2-9ee2ec0d1267', 'es', '', '<div>b) el formato (por ejemplo, idioma, versión del software, gráficos) y los medios de soporte (por ejemplo, papel, electrónico);</div>'),
    ('ed151dd9-3142-41ff-a8a6-58b51cbf7140', '257b02cf-4607-4b51-af4a-5935ed0d13fa', 'en', '', '<div>c) review and approval for suitability and adequacy. </div>'),
    ('0815485a-e934-4028-bace-786a39bf9ee7', '257b02cf-4607-4b51-af4a-5935ed0d13fa', 'es', '', '<div>c) la revisión y aprobación con respecto a la conveniencia y adecuación.</div>'),
    ('73797328-660f-47d6-acb2-e130b5bbea91', '247b013c-980c-4bd6-93db-3498ee0d158d', 'en', 'Control of documented information', '<div>{clause_7.5.3.1}</div><div>{clause_7.5.3.2}</div>'),
    ('6079553f-4bb2-41f5-9a49-d10bc0bbfbe2', '247b013c-980c-4bd6-93db-3498ee0d158d', 'es', 'Control de la información documentada', '<div>{clause_7.5.3.1}</div><div>{clause_7.5.3.2}</div>'),
    ('5a6a383f-13ef-46c1-aad2-db0b412c108e', '237affa9-c634-4f73-a43a-c353e70d0a88', 'en', '', '<div> Documented information required by the quality management system and by this International Standard shall be controlled to ensure: </div><div>{clause_7.5.3.1.a}</div><div>{clause_7.5.3.1.b}</div>'),
    ('6d6a5628-68fb-4f9a-bd3b-eb302e2bf2a5', '237affa9-c634-4f73-a43a-c353e70d0a88', 'es', '', '<div>La información documentada requerida por el sistema de gestión de la calidad y por esta Norma Internacional se debe controlar para asegurarse de que:&nbsp;</div><div>{clause_7.5.3.1.a}</div><div>{clause_7.5.3.1.b}</div>'),
    ('edb9ee96-fc20-4cf8-9901-a75e2135ffb7', '227afe16-3de4-4fb8-a9b8-f636e80d0c1b', 'en', '', '<div>a) it is available and suitable for use, where and when it is needed; </div>'),
    ('eab9e9dd-e75b-47af-bfdd-22b124360470', '227afe16-3de4-4fb8-a9b8-f636e80d0c1b', 'es', '', '<div>a) esté disponible y sea idónea para su uso, donde y cuando se necesite;</div>'),
    ('f21cf555-0026-492b-9771-31c901ee25cc', '217afc83-68ed-45cd-89c0-ed49e90d0dae', 'en', '', '<div>b) it is adequately protected (e.g. from loss of confidentiality, improper use, or loss of integrity). </div>'),
    ('e51ce0de-ffc9-444c-867d-a56616ee46db', '217afc83-68ed-45cd-89c0-ed49e90d0dae', 'es', '', '<div>b) esté protegida adecuadamente (por ejemplo, contra pérdida de la confidencialidad, uso inadecuado o pérdida de integridad).</div>'),
    ('5b2423b4-5255-4fd2-b90b-a2f4bb6192cd', '207afaf0-24a9-4ac2-8370-dd4cea0d0f41', 'en', '', '<div>For the control of documented information, the organization shall address the following activities, as applicable: </div><div>{clause_7.5.3.2.a}</div><div>{clause_7.5.3.2.b}</div><div>{clause_7.5.3.2.c}</div><div>{clause_7.5.3.2.d}</div><div>Documented information of external origin determined by the organization to benecessary forthe planning and operation of the quality management system shall be identified as appropriate, and be controlled.</div><div>Documented information retained as evidence ofconformity shall be protected from unintended alterations.</div><div>NOTE: Access can imply a decision regarding the permission to view the documented information only, or the permission and authority to view and change the documented information. </div>'),
    ('4023f933-422c-4cc9-9409-8d079e616526', '207afaf0-24a9-4ac2-8370-dd4cea0d0f41', 'es', '', '<div>Para el control de la información documentada, la organización debe abordar las siguientes actividades, según corresponda:&nbsp;</div><div>{clause_7.5.3.2.a}</div><div>{clause_7.5.3.2.b}</div><div>{clause_7.5.3.2.c}</div><div>{clause_7.5.3.2.d}</div><div>La información documentada de origen externo, que la organización determina como necesaria para la planificación y operación del sistema de gestión de la calidad, se debe identificar, según sea apropiado, y controlar.</div><div>La información documentada conservada como evidencia de la conformidad debe protegerse contra modificaciones no intencionadas.</div><div>NOTA: El acceso puede implicar una decisión en relación al permiso, solamente para consultar la información documentada, o al permiso y a la autoridad para consultar y modificar la información documentada.</div>'),
    ('4038508b-db42-4fed-a25c-3f5f16147c6a', '2f7b128d-5a5b-4dbf-93f0-4fa7e30d043c', 'en', '', '<div>a) distribution, access, retrieval and use;</div>'),
    ('4b3861dc-0d3b-4efe-a953-13dc1b148449', '2f7b128d-5a5b-4dbf-93f0-4fa7e30d043c', 'es', '', '<div>a) distribución, acceso, recuperación y uso;</div>'),
    ('a08ec542-f70f-4af4-ba68-9d92469d7693', '2e7b10fa-019f-4af4-b5d1-9e3ae40d05cf', 'en', '', '<div>b) storage and preservation, including preservation of legibility;</div>'),
    ('958eb3f1-900f-4ea3-b2ad-738d619da114', '2e7b10fa-019f-4af4-b5d1-9e3ae40d05cf', 'es', '', '<div>b) almacenamiento y preservación, incluida la preservación de la legibilidad;</div>'),
    ('bd714e6c-ebaf-4166-bb87-b38c4cc23741', '2178bdec-2a62-4f86-8d18-3224f10f58dd', 'en', '', '<div>c) control of changes (e.g. version control); </div>'),
    ('d2716f7b-3e9c-45a5-882a-342f37c21632', '2178bdec-2a62-4f86-8d18-3224f10f58dd', 'es', '', '<div>c) control de cambios (por ejemplo, control de versión);</div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('76e4bb6d-5648-4acf-aae9-392128fa68b0', '2278bf7f-d85d-4f01-92b9-ad81f00f574a', 'en', '', '<div>d) retention and disposition. </div>'),
    ('59e48dc6-67e0-4398-a8b0-1aee25fa63f7', '2278bf7f-d85d-4f01-92b9-ad81f00f574a', 'es', '', '<div>d) conservación y disposición.</div>'),
    ('7281b4ae-075f-480c-89d4-eb567a9db37b', 'f0000000-0000-0000-0000-000000000008', 'en', 'Operation', '<div>{clause_8.1}</div><div>{clause_8.2}</div><div>{clause_8.3}</div><div>{clause_8.4}</div><div>{clause_8.5}</div><div>{clause_8.6}</div><div>{clause_8.7}</div>'),
    ('5f8196c5-ebf5-4eeb-9902-fb99659d926c', 'f0000000-0000-0000-0000-000000000008', 'es', 'Operación', '<div>{clause_8.1}</div><div>{clause_8.2}</div><div>{clause_8.3}</div><div>{clause_8.4}</div><div>{clause_8.5}</div><div>{clause_8.6}</div><div>{clause_8.7}</div>'),
    ('50113ad7-b0da-4905-818a-16832837eeb2', '2478c2a5-c27a-48f7-aca8-ebcbee0f5424', 'en', 'Operational planning and control', '<div>The organization shall plan, implement and control the processes (see 4.4) needed to meet the requirements for the provision of products and services, and to implement the actions determined in Clause 6, by: </div><div>{clause_8.1.a}</div><div>{clause_8.1.b}</div><div>{clause_8.1.c}</div><div>{clause_8.1.d}</div><div>{clause_8.1.e}</div><div>The output of this planning shall be suitable for the organization''s operations.</div><div>The organization shall control planned changes and review the consequences of unintended changes, taking action to mitigate any adverse effects, as necessary.</div><div>The organization shall ensure that outsourced processes are controlled (see 8.4).</div>'),
    ('53113f90-7194-4746-8bb4-8d783d380fc1', '2478c2a5-c27a-48f7-aca8-ebcbee0f5424', 'es', 'Planificación y control operacional', '<div>La organización debe planificar, implementar y controlar los procesos (véase 4.4) necesarios para cumplir los requisitos para la provisión de productos y servicios, y para implementar las acciones determinadas en el capítulo 6 mediante:&nbsp;</div><div>{clause_8.1.a}</div><div>{clause_8.1.b}</div><div>{clause_8.1.c}</div><div>{clause_8.1.d}</div><div>{clause_8.1.e}</div><div>La salida de esta planificación debe ser adecuada para las operaciones de la organización.</div><div>La organización debe controlar los cambios planificados y revisar las consecuencias de los cambios no previstos, tomando acciones para mitigar cualquier efecto adverso, según sea necesario.</div><div>La organización debe asegurarse de que los procesos contratados externamente estén controlados (véase 8.4).</div>'),
    ('d84106e0-a2b1-4e62-9616-08a812690dbd', '1d78b7a0-b6fe-4b72-9494-ae90ed0f5291', 'en', '', '<div>a) determining the requirements for the products and services; </div>'),
    ('f5413487-35b4-4139-811b-8e9315691276', '1d78b7a0-b6fe-4b72-9494-ae90ed0f5291', 'es', '', '<div>a) la determinación de los requisitos para los productos y servicios;</div>'),
    ('713d8031-6ebd-44bb-b066-25cd0ec880fc', '1e78b933-10c5-413d-ad1d-8a4dec0f50fe', 'en', '', '<div>b) establishing criteria for: </div><ul><li>{clause_8.1.b.1}</li><li>{clause_8.1.b.2}</li></ul>'),
    ('7c3d9182-cbd2-4abc-8e77-1fd203c86fab', '1e78b933-10c5-413d-ad1d-8a4dec0f50fe', 'es', '', '<div>b) el establecimiento de criterios para:&nbsp;</div><ul><li>{clause_8.1.b.1}</li><li>{clause_8.1.b.2}</li></ul>'),
    ('8cb39c62-f363-4148-a4cd-f2b22d70f727', '1f78bac6-d03b-4368-afe2-389aeb0f4f6b', 'en', '', '<div>1) the processes; </div>'),
    ('81b38b11-3deb-4c1f-ab68-c32d1070c980', '1f78bac6-d03b-4368-afe2-389aeb0f4f6b', 'es', '', '<div>1) los procesos;</div>'),
    ('9d3c642b-3408-4791-a88d-4dff0d66a33e', '2078bc59-588b-4323-87bb-8d07ea0f4dd8', 'en', '', '<div>2) the acceptance of products and services; </div>'),
    ('a83c757c-2ba2-458a-bfff-627c1a66b7b5', '2078bc59-588b-4323-87bb-8d07ea0f4dd8', 'es', '', '<div>2) la aceptación de los productos y servicios;</div>'),
    ('b8283754-5d98-421e-9559-f1142778edc9', '2978ca84-5b4d-455e-bc26-d32ce90f4c45', 'en', '', '<div>c) determining the resources needed to achieve conformity to the product and service requirements; </div>'),
    ('9d280cd3-2b9f-430d-8ea7-50a72278e5ea', '2978ca84-5b4d-455e-bc26-d32ce90f4c45', 'es', '', '<div>c) la determinación de los recursos necesarios para lograr la conformidad con los requisitos de los productos y servicios;</div>'),
    ('dbc76375-7fbb-4347-9864-12e96dde7158', '2a78cc17-61f2-4299-9a10-cf29e80f4ab2', 'en', '', '<div>d) implementing control of the processes in accordance with the criteria;</div>'),
    ('cec74efe-8673-49e0-8a0c-be067ade85cf', '2a78cc17-61f2-4299-9a10-cf29e80f4ab2', 'es', '', '<div>d) la implementación del control de los procesos de acuerdo con los criterios;</div>'),
    ('57d83db5-44b1-4797-a5dc-6129547f61c8', 'b3805f87-f6bf-466d-83d1-94e957123806', 'en', '', '<div>e) determining and keeping documented information to the extent necessary:</div><ul><li>{clause_8.1.e.1}</li><li>{clause_8.1.e.2}</li></ul>'),
    ('4ad8293e-a510-4bd0-9fb8-7146417f43df', 'b3805f87-f6bf-466d-83d1-94e957123806', 'es', '', '<div>e) la determinación, el mantenimiento y la conservación de la información documentada en la extensión necesaria para:</div><ul><li>{clause_8.1.e.1}</li><li>{clause_8.1.e.2}</li></ul>'),
    ('31bea894-73c6-4cee-ace2-5d54cba0a379', 'b2805df4-9c5a-4fe2-8114-69ec58123999', 'en', '', '<div>1) to have confidence that the processes have been carried out as planned; </div>'),
    ('16be7e13-fda9-47fd-8a5b-0fe7e6a0cdfa', 'b2805df4-9c5a-4fe2-8114-69ec58123999', 'es', '', '<div>1) tener confianza en que los procesos se han llevado a cabo según lo planificado;</div>'),
    ('3106501f-ebe1-4b8d-9ffa-3deb531d840a', 'b58062ad-221e-4693-b6c9-8873551234e0', 'en', '', '<div>2) to demonstrate the conformity of products and services to their requirements.</div>'),
    ('44066e08-1dd9-4a9e-a397-f410581d8be9', 'b58062ad-221e-4693-b6c9-8873551234e0', 'es', '', '<div>2) demostrar la conformidad de los productos y servicios con sus requisitos.</div>'),
    ('5376c9f6-c057-4214-a1c6-a1be83a81133', 'b480611a-c93b-4458-a918-93d656123673', 'en', 'Requirements for products and services', '<div>{clause_8.2.1}</div><div>{clause_8.2.2}</div><div>{clause_8.2.3}</div><div>{clause_8.2.4}</div>'),
    ('5076c53d-6f77-4e43-be2a-9f919ea83bb4', 'b480611a-c93b-4458-a918-93d656123673', 'es', 'Requisitos para los productos y servicios', '<div>{clause_8.2.1}</div><div>{clause_8.2.2}</div><div>{clause_8.2.3}</div><div>{clause_8.2.4}</div>'),
    ('c62a0bb9-7a02-46c3-8d6b-801539afa954', 'af80593b-d15e-42f1-b154-f8555b123e52', 'en', 'Customer communication', '<div>Communication with customers shall include:</div><div>{clause_8.2.1.a}</div><div>{clause_8.2.1.b}</div><div>{clause_8.2.1.c}</div><div>{clause_8.2.1.d}</div><div>{clause_8.2.1.e}</div>'),
    ('e12a363a-cae2-4a94-8f2f-554a1eaf7ed3', 'af80593b-d15e-42f1-b154-f8555b123e52', 'es', 'Comunicación con el cliente', '<div>La comunicación con los clientes debe incluir:</div><div>{clause_8.2.1.a}</div><div>{clause_8.2.1.b}</div><div>{clause_8.2.1.c}</div><div>{clause_8.2.1.d}</div><div>{clause_8.2.1.e}</div>'),
    ('4c8ff408-73b2-446a-9df3-59105d4ed575', 'ae8057a8-f672-4ef6-ad4f-a9385c123fe5', 'en', '', '<div>a) providing information relating to products and services; </div>'),
    ('398fd61f-8fbd-45f1-9a55-a2eb504ec0fe', 'ae8057a8-f672-4ef6-ad4f-a9385c123fe5', 'es', '', '<div>a) proporcionar la información relativa a los productos y servicios;</div>'),
    ('7e317973-d309-4699-9df7-4bc758ebceb6', 'b1805c61-a55c-4467-b666-398f59123b2c', 'en', '', '<div>b) handling enquiries, contracts or orders, including changes; </div>'),
    ('9931a3f4-53ac-4342-abd7-44b455ebc9fd', 'b1805c61-a55c-4467-b666-398f59123b2c', 'es', '', '<div>b) tratar las consultas, los contratos o los pedidos, incluyendo los cambios;</div>'),
    ('4da87f4a-5b7b-4d70-af21-c9fa38f5bddf', 'b0805ace-1680-46bc-9b88-fb825a123cbf', 'en', '', '<div>c) obtaining customer feedback relating to products and services, including customer complaints;</div>'),
    ('52a88729-fb1c-4937-a211-fae54bf5dbc8', 'b0805ace-1680-46bc-9b88-fb825a123cbf', 'es', '', '<div>c) obtener la retroalimentación de los clientes relativa a los productos y servicios incluyendo las quejas de los clientes;</div>'),
    ('f07b2cad-9725-431f-bf89-e46159c878e0', 'ab8052ef-349a-4b65-aea6-e0415f12449e', 'en', '', '<div>d) handling or controlling customer property; </div>'),
    ('d37aff06-4c9d-4848-a2f8-402e76c8a687', 'ab8052ef-349a-4b65-aea6-e0415f12449e', 'es', '', '<div>d) manipular o controlar la propiedad del cliente;</div>'),
    ('398228ac-31d3-4af6-bf2f-3accf2c4f231', 'aa80515c-e188-45fa-9ef5-d1e460124631', 'en', '', '<div>e) establishing specific requirements for contingency actions, when relevant. </div>'),
    ('4e8249bb-4466-4695-9761-236ffdc50382', 'aa80515c-e188-45fa-9ef5-d1e460124631', 'es', '', '<div>e) establecer los requisitos específicos para las acciones de contingencia, cuando sea pertinente.</div>'),
    ('b9f61446-05bc-4600-a262-206e45d0190f', '2d7d4dfe-d751-43b4-9f91-ede65d14800f', 'en', 'Determining the requirements related to products and services', '<div>When determining the requirements for the products and services to be offered to customers, the organization shall ensure that: </div><div>{clause_8.2.2.a}&nbsp;</div><div>{clause_8.2.2.b}</div>'),
    ('d6f641ed-fc89-4667-a49b-3ea138d00498', '2d7d4dfe-d751-43b4-9f91-ede65d14800f', 'es', 'Determinación de los requisitos para los productos y servicios', '<div>Cuando se determinan los requisitos de los productos y servicios que se van a ofrecer a los clientes, la organización debe asegurarse de que:&nbsp;</div><div>{clause_8.2.2.a}&nbsp;</div><div>{clause_8.2.2.b}</div>'),
    ('64ca2a6f-d0b3-4fe9-9a46-7d5b2527f466', '2e7d4f91-495a-4b7f-ae41-6c035c147e7c', 'en', '', '<div>a) the requirements for the products and services are defined, including: </div><ul><li>{clause_8.2.2.a.1}</li><li>{clause_8.2.2.a.2}</li></ul>'),
    ('57ca15f8-fa2a-47f2-aaae-a3204228220d', '2e7d4f91-495a-4b7f-ae41-6c035c147e7c', 'es', '', '<div>a) los requisitos para los productos y servicios se definen, incluyendo:&nbsp;</div><ul><li>{clause_8.2.2.a.1}</li><li>{clause_8.2.2.a.2}</li></ul>'),
    ('2583b124-6cb4-403a-ab96-2d042a28cbe5', '2b7d4ad8-ba6f-456e-8c7a-4fbc5f148335', 'en', '', '<div>1) any applicable statutory and regulatory requirements; </div>'),
    ('2a83b903-152e-4e61-9b6c-46373d28e9ce', '2b7d4ad8-ba6f-456e-8c7a-4fbc5f148335', 'es', '', '<div>1) cualquier requisito legal y reglamentario aplicable;</div>'),
    ('bef6ebc5-5c47-4953-bd8b-9519932ffa44', '2c7d4c6b-c115-45a9-92ae-61395e1481a2', 'en', '', '<div>2) those considered necessary by the organization; </div>'),
    ('d1f709ae-69a2-4b04-ae5d-84d698300223', '2c7d4c6b-c115-45a9-92ae-61395e1481a2', 'es', '', '<div>2) aquellos considerados necesarios por la organización;</div>'),
    ('f4c5ff1a-78a9-4ce4-a226-64aa8fe308a3', '317d544a-53ec-4670-adcb-9152591479c3', 'en', '', '<div>b) the organization can meet the claims for the products and services it offers. </div>'),
    ('d9c5d499-6b50-4e33-aae4-11f58ae300c4', '317d544a-53ec-4670-adcb-9152591479c3', 'es', '', '<div>b) la organización puede cumplir con las declaraciones acerca de los productos y servicios que ofrece.</div>'),
    ('b1578303-d3d7-405d-b09a-30b75ff7df3a', '327d55dd-4b22-40ab-a8e0-2d5f58147830', 'en', 'Review of requirements related to products and services', '<div>{clause_8.2.3.1}</div><div>{clause_8.2.3.2}</div>'),
    ('ac577b24-6014-4dce-80c4-178444f7b4b9', '327d55dd-4b22-40ab-a8e0-2d5f58147830', 'es', 'Revisión de los requisitos para los productos y servicios', '<div>{clause_8.2.3.1}</div><div>{clause_8.2.3.2}</div>'),
    ('3fb598d8-ba5a-40be-9af9-2a006481f569', '2f7d5124-452f-4c1a-8e6e-37485b147ce9', 'en', '', '<div>The organization shall ensure that it has the ability to meet the requirements for products and services to be offered to customers. The organization shall conduct a review before committing to supply products and services to a customer, to include: </div><div>{clause_8.2.3.1.a}</div><div>{clause_8.2.3.1.b}</div><div>{clause_8.2.3.1.c}</div><div>{clause_8.2.3.1.d}</div><div>{clause_8.2.3.1.e}</div><div>The organization shall ensure that contract or order requirements differing from those previously defined are resolved.</div><div>The customer''s requirements shall be confirmed by the organization before acceptance, when the customer does not provide a documented statement of their requirements.</div><div>NOTE: In some situations, such as internet sales, a formal review is impractical for each order. Instead, the review can cover relevant product information, such as catalogues or advertising material. </div>'),
    ('4cb5ad4f-a1ae-46ad-93cb-a43b5f81ed8a', '2f7d5124-452f-4c1a-8e6e-37485b147ce9', 'es', '', '<div>La organización debe asegurarse de que tiene la capacidad de cumplir los requisitos para los productos y servicios que se van a ofrecer a los clientes. La organización debe llevar a cabo una revisión antes de comprometerse a suministrar productos y servicios a un cliente, para incluir:&nbsp;</div><div>{clause_8.2.3.1.a}</div><div>{clause_8.2.3.1.b}</div><div>{clause_8.2.3.1.c}</div><div>{clause_8.2.3.1.d}</div><div>{clause_8.2.3.1.e}</div><div>La organización debe asegurarse de que se resuelven las diferencias existentes entre los requisitos del contrato o pedido y los expresados previamente.</div><div>La organización debe confirmar los requisitos del cliente antes de la aceptación, cuando el cliente no proporcione una declaración documentada de sus requisitos.</div><div>NOTA: En algunas ocasiones, como las ventas por internet, es irrealizable llevar a cabo una revisión formal para cada pedido. En su lugar la revisión puede cubrir la información del producto pertinente, como catálogos</div>'),
    ('f9501549-6da5-4c67-913d-d40520bb8778', '307d52b7-816f-4585-bc22-2ea55a147b56', 'en', '', '<div>a) requirements specified by the customer, including the requirements for delivery and postdelivery activities;</div>'),
    ('f4500d6a-76d8-4c00-a47d-aa9a2dbb9bef', '307d52b7-816f-4585-bc22-2ea55a147b56', 'es', '', '<div>a) los requisitos especificados por el cliente, incluyendo los requisitos para las Actividades de entrega y las posteriores a la misma;</div>'),
    ('df3dcabe-abc5-4168-a51b-3c466a7b91c7', '257d4166-92c1-4e5c-99c9-a51e65148ca7', 'en', '', '<div>b) requirements not stated by the customer, but necessary for the specified or intended use, when known;</div>'),
    ('ec3ddf35-f3d2-403f-ab3f-2c294d7b6420', '257d4166-92c1-4e5c-99c9-a51e65148ca7', 'es', '', '<div>b) los requisitos no establecidos por el cliente, pero necesarios para el uso especificado o previsto, cuando sea conocido;</div>'),
    ('ff481ea7-90ca-4631-a5cc-f733c0454c5e', '267d42f9-219d-4c07-b762-045b64148b14', 'en', '', '<div>c) requirements specified by the organization; </div>'),
    ('e247f100-7246-4eaa-92d2-83c8cd4560d5', '267d42f9-219d-4c07-b762-045b64148b14', 'es', '', '<div>c) los requisitos especificados por la organización;</div>'),
    ('1bbf67f7-392f-4261-bc51-c7a3389db0ae', '9f5dadc9-457f-41c3-a507-ee2b6316c818', 'en', '', '<div>d) statutory and regulatory requirements applicable to the products and services; </div>'),
    ('1ebf6cb0-90b5-443a-ac0b-f698259d92c5', '9f5dadc9-457f-41c3-a507-ee2b6316c818', 'es', '', '<div>d) los requisitos legales y reglamentarios aplicables a los productos y servicios;</div>'),
    ('3bb578ce-dd64-4618-9048-9476162d36d7', '9e5dac36-d67b-4708-9e85-a4ae6416c9ab', 'en', '', '<div>e) contract or order requirements differing from those previously expressed.</div>'),
    ('28b55ae5-cbcd-4d4f-8fc1-0db9192d3b90', '9e5dac36-d67b-4708-9e85-a4ae6416c9ab', 'es', '', '<div>e) las diferencias existentes entre los requisitos del contrato o pedido y los expresados previamente.</div>'),
    ('b372250d-3764-4e4b-b91c-e141838d4a6c', '9d5daaa3-00e6-4c5d-8b29-23616516cb3e', 'en', '', '<div>The organization shall retain documented information, as applicable: </div><div>{clause_8.2.3.2.a}</div><div>{clause_8.2.3.2.b}</div>'),
    ('9671f766-52ce-476c-b445-cf0e988d6b7b', '9d5daaa3-00e6-4c5d-8b29-23616516cb3e', 'es', '', '<div>La organización debe conservar la información documentada, cuando sea aplicable:&nbsp;</div><div>{clause_8.2.3.2.a}</div><div>{clause_8.2.3.2.b}</div>'),
    ('fc79210c-7795-4b72-bd34-f42c3d00b76d', '9c5da910-8dd4-4492-a47c-8f846616ccd1', 'en', '', '<div>a) on the results of the review; </div>'),
    ('1179421b-4e1e-4369-91de-56cf200089c6', '9c5da910-8dd4-4492-a47c-8f846616ccd1', 'es', '', '<div>a) sobre los resultados de la revisión;</div>'),
    ('6671bb4b-4654-4115-9a9c-651f52cf9862', 'a35db415-b29d-4717-823e-b0e76716ce64', 'en', '', '<div>b) on any new requirements for the products and services. </div>'),
    ('7171cc9c-33c1-4576-9ea2-4b9c47cf8711', 'a35db415-b29d-4717-823e-b0e76716ce64', 'es', '', '<div>b) sobre cualquier requisito nuevo para los productos y servicios.</div>'),
    ('c9410602-c43c-4c1c-be76-c3526358602b', 'a25db282-3941-4e2c-a06f-ad7a6816cff7', 'en', 'Changes to requirements for products and services', '<div>The organization shall ensure that relevant documented information is amended, and that relevant persons are made aware ofthe changed requirements, when the requirements for products and services are changed. </div>'),
    ('be40f4b1-6727-461b-a065-c94d6e58717c', 'a25db282-3941-4e2c-a06f-ad7a6816cff7', 'es', 'Cambios en los requisitos para los productos y servicios', '<div>La organización debe asegurarse de que, cuando se cambien los requisitos para los productos y servicios, la información; documentada pertinente sea modificada, y de que las personas pertinentes sean conscientes de los requisitos modificados.</div>'),
    ('adcae9d1-6af8-4d1f-911b-62ed9e5d02e0', 'a15db0ef-de9f-45a1-a680-ce2d6916d18a', 'en', 'Design and development of products and services', '<div>{clause_8.3.1}<br>{clause_8.3.2}</div><div>{clause_8.3.3}</div><div>{clause_8.3.4}</div><div>{clause_8.3.5}</div><div>{clause_8.3.6}</div>'),
    ('b8cafb22-2070-4248-b066-ed72bb5d3087', 'a15db0ef-de9f-45a1-a680-ce2d6916d18a', 'es', 'Diseño y desarrollo de los productos y servicios', '<div>{clause_8.3.1}<br>{clause_8.3.2}</div><div>{clause_8.3.3}</div><div>{clause_8.3.4}</div><div>{clause_8.3.5}</div><div>{clause_8.3.6}</div>'),
    ('14ce7080-05a6-44f6-ab67-204837597c31', 'a05daf5c-0137-45a6-a4e8-11706a16d31d', 'en', 'General', '<div>The organization shall establish, implement and maintain a design and development process that appropriate to ensure the subsequent provision of products and services. </div>'),
    ('31ce9e27-1839-4095-be61-93b342598d82', 'a05daf5c-0137-45a6-a4e8-11706a16d31d', 'es', 'Generalidades', '<div>La organización debe establecer, implementar y mantener un proceso de diseño y desarrollo que sea adecuado para asegurarse de la posterior provisión de productos y servicios.</div>'),
    ('80a3a2ff-a6dc-4099-8e1f-f7cb9d8058b6', 'a75dba61-f241-443b-888c-b3935b16bb80', 'en', 'Design and development planning', '<div>In determining the stages and controls for design and development, the organization shall consider:</div><div>{clause_8.3.2.a}</div><div>{clause_8.3.2.b}</div><div>{clause_8.3.2.c}</div><div>{clause_8.3.2.d}</div><div>{clause_8.3.2.e}</div><div>{clause_8.3.2.f}</div><div>{clause_8.3.2.g}</div><div>{clause_8.3.2.h}</div><div>{clause_8.3.2.i}</div><div>{clause_8.3.2.j}</div>'),
    ('93a3c0e8-277f-4d42-a05a-e3f09a8053fd', 'a75dba61-f241-443b-888c-b3935b16bb80', 'es', 'Planificación del diseño y desarrollo', '<div>Al determinar las etapas y controles para el diseño y desarrollo, la organización debe considerar:</div><div>{clause_8.3.2.a}</div><div>{clause_8.3.2.b}</div><div>{clause_8.3.2.c}</div><div>{clause_8.3.2.d}</div><div>{clause_8.3.2.e}</div><div>{clause_8.3.2.f}</div><div>{clause_8.3.2.g}</div><div>{clause_8.3.2.h}</div><div>{clause_8.3.2.i}</div><div>{clause_8.3.2.j}</div>'),
    ('13f1c656-2f4f-4770-a8a2-151e7d8a47df', 'a65db8ce-e765-4780-aeaa-65765c16bd13', 'en', '', '<div>a) the nature, duration and complexity of the design and development activities; </div>'),
    ('10f1c19d-cef0-4337-9e99-d971908a65c8', 'a65db8ce-e765-4780-aeaa-65765c16bd13', 'es', '', '<div>a) La naturaleza, duración y complejidad de las actividades de diseño y desarrollo;</div>'),
    ('608e6b90-fdf4-4482-af90-a9f809daaddd', '195a9c40-35aa-4d02-964a-a640e919d9a1', 'en', '', '<div>b) the required process stages, including applicable design and development reviews; </div>'),
    ('5d8e66d7-9426-46d9-a566-33030cdab296', '195a9c40-35aa-4d02-964a-a640e919d9a1', 'es', '', '<div>b) las etapas del proceso requeridas, incluyendo las revisiones del diseño y desarrollo aplicables;</div>'),
    ('f7afdfa1-1ff8-43db-9261-225d9067a59c', '1a5a9dd3-933c-400d-adfe-c1fde819d80e', 'en', '', '<div>c) the required design and development verification and validation activities; </div>'),
    ('e2afbe92-98d4-47dc-a120-abc28567944b', '1a5a9dd3-933c-400d-adfe-c1fde819d80e', 'es', '', '<div>c) las actividades requeridas de verificación y validación del diseño y desarrollo;</div>'),
    ('d3259712-7f98-4b68-a303-b842af101bc7', '1b5a9f66-6832-46f8-b1f2-778ae719d67b', 'en', '', '<div>d) the responsibilities and authorities involved in the design and development process; </div>'),
    ('e825b821-c7a5-4a3f-9444-2edd920fee20', '1b5a9f66-6832-46f8-b1f2-778ae719d67b', 'es', '', '<div>d) las responsabilidades y autoridades involucradas en el proceso de diseño y desarrollo;</div>'),
    ('230f5fdb-649d-4031-a36e-d80f04d9d65e', '1c5aa0f9-d737-44b3-8110-2b77e619d4e8', 'en', '', '<div>e) the internal and external resource needs for the design and development of products and services;</div>'),
    ('0e0f3ecc-4619-48aa-9b25-186c11d9ead5', '1c5aa0f9-d737-44b3-8110-2b77e619d4e8', 'es', '', '<div>e) las necesidades de recursos internos y externos para el diseño y desarrollo de los productos y servicios;</div>'),
    ('465c83dc-603f-4c86-b285-c95c4433d761', '1d5aa28c-a90f-4116-857a-1a54ed19dfed', 'en', '', '<div>f) the need to control interfaces between persons involved in the design and development process;</div>'),
    ('3b5c728b-9d0c-4845-ab8e-f4df2f33b652', '1d5aa28c-a90f-4116-857a-1a54ed19dfed', 'es', '', '<div>f) la necesidad de controlar las interfaces entre las personas que participan activamente en el proceso de diseño y desarrollo;</div>'),
    ('bd55231d-cad8-45ef-85d0-c971aa998d50', '1e5aa41f-7056-4591-a280-9631ec19de5a', 'en', '', '<div>g) the need for involvement of customers and users in the design and development process;</div>'),
    ('c05527d6-c652-4938-8fd9-051ea7998897', '1e5aa41f-7056-4591-a280-9631ec19de5a', 'es', '', '<div>g) la necesidad de la participación activa de los clientes y usuarios en el proceso de diseño y desarrollo; </div>'),
    ('b8544b9e-f888-48ac-8ed6-27a66f94ea9b', '1f5aa5b2-cb97-41dc-aa34-b5beeb19dcc7', 'en', '', '<div>h) the requirements for subsequent provision of products and services;</div>'),
    ('c5546015-dd1e-4f8b-88f4-8c095a94c98c', '1f5aa5b2-cb97-41dc-aa34-b5beeb19dcc7', 'es', '', '<div>h) los requisitos para la posterior provisión de productos y servicios;</div>'),
    ('6504fa07-256c-4725-bb25-50131d2f25d2', '205aa745-5a73-4f87-9965-c3fbea19db34', 'en', '', '<div>i) the level of control expected for the design and development process by customers and other relevant interested parties; </div>'),
    ('4804cc60-d27f-42e6-901f-ca28322f46e1', '205aa745-5a73-4f87-9965-c3fbea19db34', 'es', '', '<div>i) el nivel de control del proceso de diseño y desarrollo esperado por los clientes y otras partes&nbsp;interesadas pertinentes;</div>'),
    ('18cc19b8-4087-4a3a-91d4-fbe06ebd55e5', '215aa8d8-7e05-4f9a-87de-8e68e119cd09', 'en', '', '<div>j) the documented information needed to demonstrate that design and development requirements have been met. </div>'),
    ('25cc2e2f-e901-4861-974b-8f1b81bd73ce', '215aa8d8-7e05-4f9a-87de-8e68e119cd09', 'es', '', '<div>j) la información documentada necesaria para demostrar que se han cumplido los requisitos del diseño y desarrollo.</div>'),
    ('5f0cf0a9-301a-4353-8719-0065d7c48444', '225aaa6b-ba45-4905-a955-5545e019cb76', 'en', 'Design and development inputs', '<div>The organization shall determine the requirements essential for the specific types of products and services to be designed and developed. The organization shall consider: </div><div>{clause_8.3.3.a}</div><div>{clause_8.3.3.b}</div><div>{clause_8.3.3.c}</div><div>{clause_8.3.3.d}</div><div>{clause_8.3.3.e}</div><div>Inputs shall be adequate for design and development purposes, complete and unambiguous.</div><div>Conflicting design and development inputs shall be resolved.</div><div>The organization shall retain documented information on design and development inputs. </div>'),
    ('5a0ce8ca-3d75-4504-9428-cf7adcc48c23', '225aaa6b-ba45-4905-a955-5545e019cb76', 'es', 'Entradas para el diseño y desarrollo', '<div>La organización debe determinar los requisitos esenciales para los tipos específicos de productos y servicios a diseñar y desarrollar. La organización debe considerar:&nbsp;</div><div>{clause_8.3.3.a}</div><div>{clause_8.3.3.b}</div><div>{clause_8.3.3.c}</div><div>{clause_8.3.3.d}</div><div>{clause_8.3.3.e}</div><div>Las entradas deben ser adecuadas para los fines del diseño y desarrollo, estar completas y sin ambigüedades.</div><div>Las entradas del diseño y desarrollo contradictorias deben resolverse.</div><div>La organización debe conservar la información documentada sobre las entradas del diseño y desarrollo</div>'),
    ('4e3376dc-6750-4672-a8ae-f45cec78b3ed', '526e1a10-c46e-4b42-a21b-fd54b0065bd1', 'en', '', '<div>a) functional and performance requirements; </div>'),
    ('4333658b-3dd9-4e69-a1b8-1fdfcf788646', '526e1a10-c46e-4b42-a21b-fd54b0065bd1', 'es', '', '<div>a) los requisitos funcionales y de desempeño;</div>'),
    ('c52c161d-271f-494b-bbf9-f471330546ec', '536e1ba3-08b2-464d-bf22-7931af065a3e', 'en', '', '<div>b) information derived from previous similar design and development activities;</div>'),
    ('c82c1ad6-4289-426c-8602-301e480567fb', '536e1ba3-08b2-464d-bf22-7931af065a3e', 'es', '', '<div>b) la información proveniente de actividades previas de diseño y desarrollo similares;</div>'),
    ('c02b3e9e-cd1f-4118-84ff-52a6c5a53357', '546e1d36-dda9-4038-86d6-98beae0658ab', 'en', '', '<div>c) statutory and regulatory requirements;</div>'),
    ('cd2b5315-bb87-484f-bf1d-b709c8a53810', '546e1d36-dda9-4038-86d6-98beae0658ab', 'es', '', '<div>c) los requisitos legales y reglamentarios;</div>'),
    ('6cdbed07-28ea-4d61-b14e-7b13e815ad2e', '556e1ec9-65f9-4ff3-b607-a6fbad065718', 'en', '', '<div>d) standards or codes of practice that the organization has committed to implement;</div>'),
    ('4fdbbf60-8070-4f3a-8648-f528d5158f45', '556e1ec9-65f9-4ff3-b607-a6fbad065718', 'es', '', '<div>d) normas o códigos de prácticas que la organización se ha comprometido a implementar;</div>'),
    ('68655e90-f561-4ff6-a5b9-d4f8e6d178b1', '566e205c-37d1-4c56-b2ec-8940b406621d', 'en', '', '<div>e) potential consequences of failure due to the nature of the products and services.</div>'),
    ('656559d7-07f4-4b95-9b8f-5e03f1d18a02', '566e205c-37d1-4c56-b2ec-8940b406621d', 'es', '', '<div>e) las consecuencias potenciales de fallar debido a la naturaleza de los productos y servicios.&nbsp;</div>'),
    ('ff86d2a1-5ab3-481f-888a-4d5d4dd4ff60', '576e21ef-e5cc-4bd1-8aa0-a4fdb306608a', 'en', 'Design and development controls', '<div>The organization shall apply controls to the design and development process to ensure that: </div><div>{clause_8.3.4.a}</div><div>{clause_8.3.4.b}</div><div>{clause_8.3.4.c}</div><div>{clause_8.3.4.d}</div><div>{clause_8.3.4.e}</div><div>{clause_8.3.4.f}</div><div>NOTE: Design and development reviews, verification and validation have distinct purposes. They can be conducted separately or in any combination, as is suitable for the products and services of the organization. </div>'),
    ('ea86b192-102b-4d48-9749-d6c26ad52d07', '576e21ef-e5cc-4bd1-8aa0-a4fdb306608a', 'es', 'Controles del diseño y desarrollo', '<div>La organización debe aplicar controles al proceso de diseño y desarrollo para asegurarse de que:&nbsp;</div><div>{clause_8.3.4.a}</div><div>{clause_8.3.4.b}</div><div>{clause_8.3.4.c}</div><div>{clause_8.3.4.d}</div><div>{clause_8.3.4.e}</div><div>{clause_8.3.4.f}</div><div>NOTA: Las revisiones, la verificación y la validación del diseño y desarrollo tienen propósitos distintos. Pueden realizarse de forma separada o en cualquier combinación, según sea idóneo para los productos y servicios de la organización.</div>'),
    ('dafc8a12-b3f6-471c-992c-e34212d05cab', '586e2382-410e-4b1c-8e94-5a8ab2065ef7', 'en', '', '<div>a) the results to be achieved are defined; </div>'),
    ('effcab21-56e2-411b-8a6d-59dd1dd06dfc', '586e2382-410e-4b1c-8e94-5a8ab2065ef7', 'es', '', '<div>a) se definen los resultados a lograr;</div>'),
    ('2ae652db-360f-4c15-9998-030f024794e2', '596e2515-e937-4dc7-9db2-0e77b1065d64', 'en', '', '<div>b) reviews are conducted to evaluate the ability of the results of design and development to meet requirements; </div>'),
    ('15e631cc-237c-4076-914e-436cf7478391', '596e2515-e937-4dc7-9db2-0e77b1065d64', 'es', '', '<div>b) se realizan las revisiones para evaluar la capacidad de los resultados del diseño y desarrollo para cumplir los requisitos;</div>'),
    ('93177f84-3740-496a-8295-1564515b5bf5', '5a6e26a8-f5f7-41da-b47d-0edca8064f39', 'en', '', '<div>c) verification activities are conducted to ensure that the design and development outputs meet the input requirements; </div>'),
    ('98178763-534b-4af1-b1b5-a697445b477e', '5a6e26a8-f5f7-41da-b47d-0edca8064f39', 'es', '', '<div>c) se realizan actividades de verificación para asegurarse de que las salidas del diseño y desarrollo cumplen los requisitos de las entradas;</div>'),
    ('2c8aba25-3d90-4bc3-8e78-3f792dbc2fd4', '5b6e283b-4909-4745-b6c3-5559a7064da6', 'en', '', '<div>d) validation activities are conducted to ensure that the resulting products and services meet the requirements for the specified application or intended use; </div>'),
    ('3f8ad80e-8e70-4f94-ae50-863612bc0553', '5b6e283b-4909-4745-b6c3-5559a7064da6', 'es', '', '<div>d) se realizan actividades de validación para asegurarse de que los productos y servicios resultantes satisfacen los ’requisitos para su aplicación especificada o uso previsto;</div>'),
    ('353f5043-8fa5-4451-8780-4ef7db3b51fe', '58706219-d443-4003-91ca-091faa0413c8', 'en', '', '<div>e) any necessary actions are taken on problems determined during the reviews, or verification and validation activities;</div>'),
    ('303f4864-89bb-4e4a-a155-a6c4e83b6675', '58706219-d443-4003-91ca-091faa0413c8', 'es', '', '<div>e) se toma cualquier acción necesaria sobre los problemas determinados durante las revisiones, o las actividades de verificación y validación;</div>'),
    ('7634f65a-6807-4b08-ba0d-34eafb45a5e7', '57706086-4bf1-4d48-aecc-9d12ab04155b', 'en', '', '<div>f) documented information of these activities is retained.</div>'),
    ('5b34cbd9-b014-49df-a7e5-1535de457840', '57706086-4bf1-4d48-aecc-9d12ab04155b', 'es', '', '<div>f) se conserva la información documentada de estas actividades.</div>'),
    ('7abf0c89-2053-4d7b-b7ac-a545da22c6bc', '56705ef3-9223-409d-9c6b-b865ac0416ee', 'en', 'Design and development outputs', '<div>The organization shall ensure that design and development outputs: </div><div>{clause_8.3.5.a}</div><div>{clause_8.3.5.b}</div><div>{clause_8.3.5.c}</div><div>{clause_8.3.5.d}</div><div>The organization shall retain documented information on design and development outputs.</div>'),
    ('75bf04aa-7fe0-497c-92c4-eddacf22b56b', '56705ef3-9223-409d-9c6b-b865ac0416ee', 'es', 'Salidas del diseño y desarrollo', '<div>La organización debe asegurarse de que las salidas del diseño y desarrollo:&nbsp;</div><div>{clause_8.3.5.a}</div><div>{clause_8.3.5.b}</div><div>{clause_8.3.5.c}</div><div>{clause_8.3.5.d}</div><div>La organización debe conservar información documentada sobre las salidas del diseño y desarrollo.</div>'),
    ('c39d6618-fe4e-4b22-95b9-4d40e03c297d', '55705d60-1f10-48d2-9c5e-9c08ad041881', 'en', '', '<div>a) meet the input requirements;</div>'),
    ('d09d7a8f-aa9e-45f9-a099-617be33c2e36', '55705d60-1f10-48d2-9c5e-9c08ad041881', 'es', '', '<div>a) cumplen los requisitos de las entradas;</div>'),
    ('e8b38aaf-25c5-4dc5-98ee-9d9bf60b0a72', '5c706865-415f-4257-8b60-96c3ae041a14', 'en', '', '<div>b) are adequate for the subsequent processes for the provision of products and services;</div>'),
    ('dbb37638-e8f7-4206-9378-0a600b0b2b81', '5c706865-415f-4257-8b60-96c3ae041a14', 'es', '', '<div>b) son adecuadas para los procesos posteriores para la provisión de productos y servicios;</div>'),
    ('3b637886-0a43-47cc-92d3-70ae45f6663b', '5b7066d2-b132-406c-a7d6-58a6af041ba7', 'en', '', '<div>c) include or reference monitoringand measuring requirements, as appropriate, and acceptance criteria;</div>'),
    ('5863a62d-0aa0-4cab-af65-14e130f6452c', '5b7066d2-b132-406c-a7d6-58a6af041ba7', 'es', '', '<div>c) incluyen o hacen referencia a los requisitos de seguimiento y medición, cuando sea apropiado, y a los criterios de aceptación;</div>'),
    ('40645005-caec-418f-a1cf-a859f454ae70', '5a70653f-5415-4be1-ae53-fcf9b0041d3a', 'en', '', '<div>d) specify the characteristics ofthe products and services that are essential for their intended purpose and their safe and proper provision. </div>'),
    ('53646dee-da0a-4458-a358-0816f154a9b7', '5a70653f-5415-4be1-ae53-fcf9b0041d3a', 'es', '', '<div>d) especifican las características de los productos y servicios que son esenciales para su propósito previsto y su provisión segura y correcta.</div>'),
    ('a96b7e64-ee93-4126-970c-2b441a955301', '597063ac-9275-4ce6-9755-c87cb1041ecd', 'en', 'Design and development changes', '<div>The organization shall identify, review and control changes made during, or subsequent to, the design and development of products and services, to the extent necessary to ensure that there is no adverse impact on conformity to requirements.</div><div>The organization shall retain documented information on:</div><div>{clause_8.3.6.a}</div><div>{clause_8.3.6.b}</div><div>{clause_8.3.6.c}</div><div>{clause_8.3.6.d}</div>'),
    ('ae6b8643-5acd-4a65-bd36-d377059531f2', '597063ac-9275-4ce6-9755-c87cb1041ecd', 'es', 'Cambios del diseño y desarrollo', '<div>La organización debe identificar, revisar y controlar los cambios hechos durante el diseño y desarrollo de los productos y servicios, o posteriormente en la medida necesaria para asegurarse de que no haya un impacto adverso en la conformidad con los requisitos.</div><div>La organización debe conservar la información documentada sobre:</div><div>{clause_8.3.6.a}</div><div>{clause_8.3.6.b}</div><div>{clause_8.3.6.c}</div><div>{clause_8.3.6.d}</div>'),
    ('cde23f3b-a221-4f89-9fa6-d16fb3779f86', '60706eb1-67b8-4d7b-bc0e-d097a2040730', 'en', '', '<div>a) design and development changes; </div>'),
    ('b8e21e2c-b24a-4292-8774-e8ccd077cd2d', '60706eb1-67b8-4d7b-bc0e-d097a2040730', 'es', '', '<div>a) los cambios del diseño y desarrollo;</div>'),
    ('7df6e372-1ab8-4fa0-9a89-2ca260c7b1af', '5f706d1e-7629-45c0-9d19-592aa30408c3', 'en', '', '<div>b) the results of reviews; </div>'),
    ('92f70481-13fe-4607-82a0-373d53c79d38', '5f706d1e-7629-45c0-9d19-592aa30408c3', 'es', '', '<div>b) los resultados de las revisiones;</div>'),
    ('d4e42e36-1125-4e3c-a841-9dfe39bb6ecb', '5e72aa22-4e54-4480-910d-63961c0b8303', 'en', '', '<div>c) the authorization of the changes; </div>'),
    ('d1e4297d-b410-483b-b673-afd144bb801c', '5e72aa22-4e54-4480-910d-63961c0b8303', 'es', '', '<div>c) la autorización de los cambios;</div>'),
    ('b4ee1d5f-7cb1-4235-a1f4-f62b9c8ab982', '5f72abb5-5930-413b-a783-45331b0b8170', 'en', '', '<div>d) the actions taken to prevent adverse impacts. </div>'),
    ('c7ee3b48-998a-4416-9964-a850918aa831', '5f72abb5-5930-413b-a783-45331b0b8170', 'es', '', '<div>d) las acciones tomadas para prevenir los impactos adversos.</div>'),
    ('b5a808d4-6b6f-4396-9622-9e9481149d51', '5c72a6fc-5518-41ea-971f-9cac1e0b8629', 'en', 'Control of externally provided processes, products and services', '<div>{clause_8.4.1}</div><div>{clause_8.4.2}</div><div>{clause_8.4.3}</div>'),
    ('9aa7de53-4e96-41b5-8f6f-fe278c14aea2', '5c72a6fc-5518-41ea-971f-9cac1e0b8629', 'es', 'Control de los procesos, productos y servicios suministrados externamente', '<div>{clause_8.4.1}</div><div>{clause_8.4.2}</div><div>{clause_8.4.3}</div>'),
    ('d94734f5-e550-40bf-992c-c069e8182400', '5d72a88f-a8ca-4b15-b509-98a91d0b8496', 'en', 'General', '<div>The organization shall ensure that externally provided processes, products and services conform to requirements.</div><div>The organization shall determine the controls to be applied to externally provided processes, products and services when:</div><div>{clause_8.4.1.a}</div><div>{clause_8.4.1.b}</div><div>{clause_8.4.1.c}</div><div>The organization shall determine and apply criteria for the evaluation, selection, monitoring of performance, and re-evaluation of external providers, based on their ability to provide processes or products and services in accordance with requirements. The organization shall retain documented information of these activities and any necessary actions arising from the evaluations.</div>'),
    ('cc47207e-9d44-41e8-8ad5-6b86051851a7', '5d72a88f-a8ca-4b15-b509-98a91d0b8496', 'es', 'Generalidades', '<div>La organización debe asegurarse de que los procesos, productos y servicios suministrados externamente son conformes a los requisitos.</div><div>La organización debe determinar los controles a aplicar a los procesos, productos y servicios suministrados externamente cuando:</div><div>{clause_8.4.1.a}</div><div>{clause_8.4.1.b}</div><div>{clause_8.4.1.c}</div><div>La organización debe determinar y aplicar criterios para la evaluación, la selección, el seguimiento del desempeño y la reevaluación de los proveedores externos, basándose en su capacidad para proporcionar procesos o productos y servicios de acuerdo con los requisitos. La organización debe conservar la información documentada de estas actividades y de cualquier acción necesaria que surja de las evaluaciones</div>'),
    ('cf15e38a-57be-4cb8-96e9-313aef091b77', '5a72a3d6-d1b8-41c4-9c62-da42200b894f', 'en', '', '<div>a) products and services from external providers are intended forincorporation into the organization''s own products and services; </div>'),
    ('d415eb69-5c44-496f-a092-f925f2092030', '5a72a3d6-d1b8-41c4-9c62-da42200b894f', 'es', '', '<div>a) los productos y servicios de proveedores externos están destinados a incorporarse dentro de los propios productos y servicios de la organización;</div>'),
    ('ffa070b3-8b53-4181-9eb8-a5070eff2c4e', '5b72a569-59e1-420f-b97a-be4f1f0b87bc', 'en', '', '<div>b) products and services are provided directly to the customer(s) by external providers on behalf of the organization;</div>'),
    ('1aa09b34-c714-485a-83ba-baf4fbff0e65', '5b72a569-59e1-420f-b97a-be4f1f0b87bc', 'es', '', '<div>b) los productos y servicio son proporcionados directamente a los clientes por proveedores externos en nombre de la organización;</div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('d077c148-553b-4292-88db-9e5086bbd88d', '5872a0b0-c87d-45fe-a444-b3f8220b8c75', 'en', '', '<div>c) a process, or part of a process, is provided by an external provider as a result of a decision by the organization. </div>'),
    ('bd77a35f-4511-4f89-916b-ec2b69bbaae6', '5872a0b0-c87d-45fe-a444-b3f8220b8c75', 'es', '', '<div>c) un proceso, o una parte de un proceso, es proporcionado por un proveedor externo como resultado de una decisión de la organización.</div>'),
    ('479902f9-b1bc-41eb-98ff-6a55cfc2d48c', '5972a243-cf21-4339-a5ee-b515210b8ae2', 'en', 'Тype and extent of control', '<div>The organization shall ensure that externally provided processes, products and services do not adversely affect the organization''s ability to consistently deliver conforming products and services to its customers.</div><div>The organization shall:</div><div>{clause_8.4.2.a}</div><div>{clause_8.4.2.b}</div><div>{clause_8.4.2.c}</div><div>{clause_8.4.2.d}</div>'),
    ('62992d7a-cd26-4b0c-b345-6b8ae4c2f59b', '5972a243-cf21-4339-a5ee-b515210b8ae2', 'es', 'Tipo y alcance del control', '<div>La organización debe asegurarse de que los procesos, productos y servicios suministrados externamente no afectan de manera adversa a la capacidad de la organización de entregar productos y servicios&nbsp;conformes de manera coherente a sus clientes.</div><div>La organización debe:</div><div>{clause_8.4.2.a}</div><div>{clause_8.4.2.b}</div><div>{clause_8.4.2.c}</div><div>{clause_8.4.2.d}</div>'),
    ('7001862e-f9f5-4db4-8a9d-98d614722553', '6672b6ba-3d6a-4408-8a29-11ce240b8f9b', 'en', '', '<div>a) ensure that externally provided processes remain within the control of its quality management system;</div>'),
    ('5d016845-92f5-4163-99cb-a9192f724fd4', '6672b6ba-3d6a-4408-8a29-11ce240b8f9b', 'es', '', '<div>a) asegurarse de que los procesos suministrados externamente permanecen dentro del control de su sistema de gestión de la calidad;</div>'),
    ('4d910c57-a623-4aad-8252-c403e16ec22a', '6772b84d-ac6d-4ec3-87a1-b54b230b8e08', 'en', '', '<div>b) define both the controls that it intends to apply to an external provider and those it intends to apply to the resulting output; </div>'),
    ('50911110-becf-44be-8c7d-3af8e66eca09', '6772b84d-ac6d-4ec3-87a1-b54b230b8e08', 'es', '', '<div>b) definir los controles que pretende aplicar a un proveedor externo y los que pretende aplicar a las salidas resultantes;</div>'),
    ('a6212b65-b523-4213-83be-95b95e8a4004', '6474f22b-26ad-4a09-894e-ac1936096d5a', 'en', '', '<div>c) take into consideration: </div><ul><li>{clause_8.4.2.c.1}</li><li>{clause_8.4.2.c.2}</li></ul>'),
    ('b921494e-c4f8-4cc4-8446-1c76638a47e3', '6474f22b-26ad-4a09-894e-ac1936096d5a', 'es', '', '<div>c) tener en consideración;&nbsp;</div><ul><li>{clause_8.4.2.c.1}</li><li>{clause_8.4.2.c.2}</li></ul>'),
    ('0f2859c4-6f9a-42fa-a793-eaa4f7fd7aa5', '6374f098-3627-424e-98a2-129c37096eed', 'en', '', '<div>1) the potential impact of the externally provided processes, products and services on the organization''s ability to consistently meet customer and applicable statutory and regulatory requirements; </div>'),
    ('142861a3-33db-4f21-b527-d3d70afd988e', '6374f098-3627-424e-98a2-129c37096eed', 'es', '', '<div>1) el impacto potencial de los procesos, productos y servicios suministrados externamente en la capacidad de la organización de cumplir regularmente los requisitos del cliente y los legales y reglamentarios aplicables;</div>'),
    ('c1c8788f-4558-49a9-ab0f-b17bf2fb1026', '6674f551-c78b-4e5f-80d9-c26334096a34', 'en', '', '<div>2) the effectiveness of the controls applied by the external provider; </div>'),
    ('b4c86418-5307-43b2-a02f-9d400ffb3dcd', '6674f551-c78b-4e5f-80d9-c26334096a34', 'es', '', '<div>2) la eficacia de los controles aplicados por el proveedor externo;</div>'),
    ('a12053e6-d09e-43c0-aa9f-648e112a5ecf', '6574f3be-3f62-4e14-9a5f-89c635096bc7', 'en', '', '<div>d) determine the verification, or other activities, necessary to ensure that the externally provided processes, products and services meet requirements. </div>'),
    ('be20818d-c9e4-4a27-af76-76c1042a4a58', '6574f3be-3f62-4e14-9a5f-89c635096bc7', 'es', '', '<div>d) determinar la verificación, u otras actividades necesarias para asegurarse de que los procesos, productos y servicios suministrados externamente cumplen los requisitos.</div>'),
    ('e07a54e9-e508-4727-8599-fea5ec15cd38', '6874f877-1674-4765-82ca-87053209670e', 'en', 'Information for external providers', '<div>The organization shall ensure the adequacy of requirements prior to their communication to the external provider.</div><div>The organization shall communicate to external providers its requirements for:</div><div>{clause_8.4.3.a}</div><div>{clause_8.4.3.b}</div><div>{clause_8.4.3.c}</div><div>{clause_8.4.3.d}</div><div>{clause_8.4.3.e}</div><div>{clause_8.4.3.f}</div>'),
    ('db7a4d0a-ebc2-40c0-bbf0-36baf915e1af', '6874f877-1674-4765-82ca-87053209670e', 'es', 'Información para los proveedores externos', '<div>La organización debe asegurarse de la adecuación de los requisitos antes de su comunicación al proveedor externo.</div><div>La organización debe comunicar a los proveedores externos sus requisitos para:</div><div>{clause_8.4.3.a}</div><div>{clause_8.4.3.b}</div><div>{clause_8.4.3.c}</div><div>{clause_8.4.3.d}</div><div>{clause_8.4.3.e}</div><div>{clause_8.4.3.f}</div>'),
    ('9cb3e6f8-2efe-4a7e-9ffd-6d203256a429', '6774f6e4-c361-41fa-9345-b428330968a1', 'en', '', '<div>a) the processes, products and services to be provided; </div>'),
    ('a9b3fb6f-fd06-4b6d-8f95-475b2d569c4a', '6774f6e4-c361-41fa-9345-b428330968a1', 'es', '', '<div>a) los procesos, productos y servicios a proporcionar;</div>'),
    ('0bdb6823-a132-441d-923e-add72b5224fa', '6a74fb9d-c6da-4d8b-9c26-79bf300963e8', 'en', '', '<div>b) the approval of: </div><ul><li>{clause_8.4.3.b.1}</li><li>{clause_8.4.3.b.2}</li><li>{clause_8.4.3.b.3}</li></ul>'),
    ('06db6044-1424-4f8e-84aa-c4a41051fa79', '6a74fb9d-c6da-4d8b-9c26-79bf300963e8', 'es', '', '<div>b) la aprobación de:&nbsp;</div><ul><li>{clause_8.4.3.b.1}</li><li>{clause_8.4.3.b.2}</li><li>{clause_8.4.3.b.3}</li></ul>'),
    ('dbf03eba-d447-4ca4-bba0-b34a5db7b763', '6974fa0a-bbff-43d0-b09e-c0323109657b', 'en', '', '<div>1) products and services; </div>'),
    ('c0f01439-e039-4ff3-b9dc-de1558b7af84', '6974fa0a-bbff-43d0-b09e-c0323109657b', 'es', '', '<div>1) productos y servicios;</div>'),
    ('413e835d-c38a-479b-afdb-9bb119a6375c', '5c74e593-b338-4ef1-adaf-1af12e0960c2', 'en', '', '<div>2) methods, processes and equipment; </div>'),
    ('443e8816-209f-4d9c-8900-205e0ea6260b', '5c74e593-b338-4ef1-adaf-1af12e0960c2', 'es', '', '<div>2) métodos, procesos y equipos;</div>'),
    ('c7cb7b1c-f504-4842-8b1a-e19c909ed69d', '5b74e400-d84b-4af6-ad75-b5142f096255', 'en', '', '<div>3) the release of products and services; </div>'),
    ('bccb69cb-7461-4b99-8714-fb1f939edb56', '5b74e400-d84b-4af6-ad75-b5142f096255', 'es', '', '<div>3) la liberación de productos y servicios;</div>'),
    ('fa69a1f8-cf64-4cae-827a-a0209973bf39', 'ea7803b4-d51e-44ee-9a4c-df28a810dc95', 'en', '', '<div>c) competence, including any required qualification of persons;</div>'),
    ('0769b66f-5946-47bd-b212-7a5bb473e9ba', 'ea7803b4-d51e-44ee-9a4c-df28a810dc95', 'es', '', '<div>c) la competencia, incluyendo cualquier calificación requerida de las personas;</div>'),
    ('3e300fe9-0f92-4257-a817-31a51fd9a788', 'eb780547-dbc5-4529-89d1-b205a710db02', 'en', '', '<div>d) the external providers'' interactions with the organization; </div>'),
    ('3930080a-726c-4f90-9e6d-69ba0cd9899f', 'eb780547-dbc5-4529-89d1-b205a710db02', 'es', '', '<div>d) las interacciones del proveedor externo con la organización;</div>'),
    ('39a5f9ba-37bc-4fd4-9e1d-e64a517b2cf3', 'ec7806da-f200-4334-b7a5-eb32a610d96f', 'en', '', '<div>e) control and monitoring of the external providers'' performance to be applied by the organization;</div>'),
    ('1ea5cf39-e461-4303-9c5a-11156c7b5774', 'ec7806da-f200-4334-b7a5-eb32a610d96f', 'es', '', '<div>e) el control y el seguimiento del desempeño del proveedor externo a aplicar por parte de la organización;</div>'),
    ('69912323-9d75-414d-b4bb-e0d720f232ca', 'ed78086d-640a-4aff-a32d-a4bfa510d7dc', 'en', '', '<div>f) verification or validation activities that the organization, or its customer, intends to perform at the external providers'' premises.</div>'),
    ('64911b44-d1ea-4c5e-a727-f7a425f23aa9', 'ed78086d-640a-4aff-a32d-a4bfa510d7dc', 'es', '', '<div>f) las actividades de verificación o validación que la organización, o su cliente, pretende llevar a cabo en las instalaciones del proveedor externo.</div>'),
    ('6cde14c4-cf50-442a-8a11-1da42b21f135', 'f0000000-0000-0000-0000-000000000085', 'en', 'Production and service provision', '<div>{clause_8.5.1}</div><div>{clause_8.5.2}</div><div>{clause_8.5.3}</div><div>{clause_8.5.4}</div><div>{clause_8.5.5}</div><div>{clause_8.5.6}</div>'),
    ('71de1ca3-edd3-4bb1-97a5-06d71e21dcbe', 'f0000000-0000-0000-0000-000000000085', 'es', 'Producción y provisión del servicio', '<div>{clause_8.5.1}</div><div>{clause_8.5.2}</div><div>{clause_8.5.3}</div><div>{clause_8.5.4}</div><div>{clause_8.5.5}</div><div>{clause_8.5.6}</div>'),
    ('03d6e665-44e4-4483-a63b-c8b905085c14', 'e777fefb-9c1f-4505-9055-d719a310d4b6', 'en', 'Control of production and service provision', '<div>The organization shall implement production and service provision under controlled conditions.</div><div>Controlled conditions shall include, as applicable:</div><div>{clause_8.5.1.a}</div><div>{clause_8.5.1.b}</div><div>{clause_8.5.1.c}</div><div>{clause_8.5.1.d}</div><div>{clause_8.5.1.e}</div><div>{clause_8.5.1.f}</div><div>{clause_8.5.1.g}</div><div>{clause_8.5.1.h}</div>'),
    ('16d7044e-983f-4154-a6c3-4f76ea083193', 'e777fefb-9c1f-4505-9055-d719a310d4b6', 'es', 'Control de la producción y de la provisión del servicio', '<div>La organización debe implementar la producción y provisión del servicio bajo condiciones controladas.</div><div>Las condiciones controladas deben incluir, cuando sea aplicable:</div><div>{clause_8.5.1.a}</div><div>{clause_8.5.1.b}</div><div>{clause_8.5.1.c}</div><div>{clause_8.5.1.d}</div><div>{clause_8.5.1.e}</div><div>{clause_8.5.1.f}</div><div>{clause_8.5.1.g}</div><div>{clause_8.5.1.h}</div>'),
    ('fed60ee6-28d7-4130-8d1c-978e0450039f', 'e878008e-6e9c-45f0-a166-b4c6a210d323', 'en', '', '<div>a) the availability of documented information that defines: </div><ul><li>{clause_8.5.1.a.1}</li><li>{clause_8.5.1.a.2}</li></ul>'),
    ('1bd63c8d-af2b-47f7-91f3-a9c117502188', 'e878008e-6e9c-45f0-a166-b4c6a210d323', 'es', '', '<div>a) la disponibilidad de información documentada que defina:&nbsp;</div><ul><li>{clause_8.5.1.a.1}</li><li>{clause_8.5.1.a.2}</li></ul>'),
    ('1f7e338f-ef3b-4e59-8d8c-e47b26c07d76', 'e9780221-65d1-402b-87e0-ed63a110d190', 'en', '', '<div>1) the characteristics ofthe products to be produced, the services to be provided, or the activities to be performed; </div>'),
    ('127e1f18-590a-4c02-82ac-d04023c078bd', 'e9780221-65d1-402b-87e0-ed63a110d190', 'es', '', '<div>1) las características de los productos a producir, los servicios a prestar, o las actividades a&nbsp;desempeñar;</div>'),
    ('3fb31dd0-fcb4-45b6-ab8c-e738be1f37f1', 'e277f71c-8ae8-4d16-9dd2-bc00b010e92d', 'en', '', '<div>2) the results to be achieved; </div>'),
    ('3cb31917-f5fc-4f55-b790-ce43c91f4942', 'e277f71c-8ae8-4d16-9dd2-bc00b010e92d', 'es', '', '<div>2) los resultados a alcanzar;</div>'),
    ('d94d67e1-b356-47df-a4dc-e39d279d27a0', 'e377f8af-5230-4191-af0b-9abdaf10e79a', 'en', '', '<div>b) the availability and use of suitable monitoring and measuring resources;</div>'),
    ('c44d46d2-6b4a-4908-862f-8602449d5547', 'e377f8af-5230-4191-af0b-9abdaf10e79a', 'es', '', '<div>b) la disponibilidad y el uso de los recursos de seguimiento y medición adecuados;</div>'),
    ('62412b3f-aea5-463d-a0fc-060bc80fb29a', 'f07a4bbd-d4cc-410f-80dc-a653220dcb0c', 'en', '', '<div>c) the implementation of monitoring and measurement activities at appropriate stages to verify that criteria for control of processes or outputs, and acceptance criteria for products and services, have been met; </div>'),
    ('75414928-24c3-4b2e-b365-1630ad0f8819', 'f07a4bbd-d4cc-410f-80dc-a653220dcb0c', 'es', '', '<div>c) la implementación de actividades de seguimiento y medición en las etapas apropiadas para verificar que se cumplen los criterios para el control de los procesos o sus salidas, y los criterios de aceptación para los productos y servicios;</div>'),
    ('f590e196-8ea8-4444-8f2a-d25e84a13683', 'ef7a4a2a-4ca3-40c4-865a-d936230dcc9f', 'en', '', '<div>d) the use of suitable infrastructure and environment for the operation of processes; </div>'),
    ('f290dcdd-7ed3-4993-b606-4db17fa12ea4', 'ef7a4a2a-4ca3-40c4-865a-d936230dcc9f', 'es', '', '<div>d) el uso de la infraestructura y el entorno adecuados para la operación de los procesos;</div>'),
    ('f9f3e855-8c6e-44c7-8d9a-5cc912ff4c58', 'ee7a4897-4a0c-4239-a662-d049240dce32', 'en', '', '<div>e) the appointment of competent persons, including any required qualification; </div>'),
    ('ecf3d3de-9326-4b60-bca6-d0661fff60cf', 'ee7a4897-4a0c-4239-a662-d049240dce32', 'es', '', '<div>e) la designación de personas competentes, incluyendo cualquier calificación requerida;</div>'),
    ('62fb16b4-6a4b-439e-af34-cdf4cc99c8c9', 'ed7a4704-4368-44fe-a012-c04c250dcfc5', 'en', '', '<div>f) the validation, and periodic revalidation, of the ability to achieve planned results of the processes for production and service provision, where the resulting output cannot be verified by subsequent monitoring or measurement; </div>'),
    ('47faec33-3852-448d-8a32-b807c799c0ea', 'ed7a4704-4368-44fe-a012-c04c250dcfc5', 'es', '', '<div>f) la validación y revalidación periódica de la capacidad para alcanzar los resultados planificados de los procesos de producción y de prestación del servicio, cuándo las salidas resultantes no puedan verificarse mediante actividades de seguimiento o medición posteriores;</div>'),
    ('204b9113-55f6-4549-a920-06678d3fc7c6', 'ec7a4571-d41a-403b-8181-8eef1e0dc4c0', 'en', '', '<div>g) the implementation of actions to prevent human error; </div>'),
    ('3b4bbb94-6620-4852-8ba7-53d4aa3ff56d', 'ec7a4571-d41a-403b-8181-8eef1e0dc4c0', 'es', '', '<div>g) la implementación de acciones para prevenir los errores humanos;</div>'),
    ('efc296ea-220b-4560-b59f-d01a3813ddef', 'eb7a43de-c93e-4380-8a74-81e21f0dc653', 'en', '', '<div>h) the implementation of release, delivery and post-delivery activities. </div>'),
    ('f4c29ec9-1b52-4ec7-a25f-f9852b13c978', 'eb7a43de-c93e-4380-8a74-81e21f0dc653', 'es', '', '<div>h) la implementación de actividades de liberación, entrega y posteriores a la entrega.</div>'),
    ('f4ec10d9-090b-4fb3-9ecf-83b5f8cd64a4', 'ea7a424b-23b4-4a15-8bec-3c35200dc7e6', 'en', 'Identification and traceability', '<div>The organization shall use suitable means to identify outputs when it is necessary to ensure the conformity of products and services.</div><div>The organization shall identify the status of outputs with respect to monitoring and measurement requirements throughout production and service provision.</div><div>The organization shall control the unique identification of the outputs when traceability is a requirement, and shall retain the documented information necessary to enable traceability. </div>'),
    ('0fec3b5a-1664-4e64-b0f7-a36afdcd6c83', 'ea7a424b-23b4-4a15-8bec-3c35200dc7e6', 'es', 'Identificación y trazabilidad', '<div>La organización debe utilizar los medios apropiados para identificar las salidas, cuando sea necesario, para asegurar la conformidad de los productos y servicios.</div><div>La organización debe identificar el estado de las salidas con respecto a los requisitos de seguimiento y medición a través de la producción y prestación del servicio.</div><div>La organización debe controlar la identificación única de las salidas cuando la trazabilidad sea un requisito, y debe conservar la información documentada necesaria para permitir la trazabilidad.</div>'),
    ('7b506628-8038-4e9a-a2dc-0c3092409f45', 'e97a40b8-d003-40ea-b07d-1798210dc979', 'en', 'Property belonging to customers or external providers', '<div>The organization shall exercise care with property belonging to customers or external providers while it is under the organization''s control or being used by the organization.</div><div>The organization shall identify,verify, protect and safeguard customers'' or external providers'' property provided for use or incorporation into the products and services.</div><div>When the property of a customer or external provider is lost, damaged or otherwise found to be unsuitable for use, the organization shall report this to the customer or external provider and retain documented information on what has occurred.</div><div>NOTE: A customer''s or external provider''s property can include material, components, tools and equipment, premises, intellectual property and personal data.</div>'),
    ('6850483f-2b2c-45c1-9072-fc0ba540bd2e', 'e97a40b8-d003-40ea-b07d-1798210dc979', 'es', 'Propiedad perteneciente a los clientes o proveedores externos', '<div>La organización debe cuidar la propiedad perteneciente a los clientes o a proveedores externos mientras esté bajo el control de la organización o esté siendo utilizado por la misma.</div><div>La organización debe identificar, verificar, proteger y salvaguardar la propiedad de los clientes o de los proveedores externos suministrada para su utilización o incorporación dentro de los productos y servicios.</div><div>Cuando la propiedad de un cliente o de un proveedor externo se pierda, deteriore o de algún otro modo se considere inadecuada para su uso, la organización debe informar de esto al cliente o proveedor externo y conservar la información documentada sobre lo ocurrido.</div><div>NOTA: La propiedad de un cliente o de un proveedor externo puede incluir materiales, componentes, herramientas y equipos, instalaciones, propiedad intelectual y datos personales.</div>'),
    ('fae41a37-bd8d-4a85-998f-ece3cd58c9b2', 'e87a3f25-9476-4317-bcf1-8feb2a0dd7a4', 'en', 'Preservation', '<div>The organization shall preserve the outputs during production and service provision, to the extent necessary to ensure conformity to requirements.</div><div>NOTE: Preservation can include identification, handling, contamination control, packaging, storage, transmission or transportation, and protection. </div>'),
    ('fde41ef0-7e47-48c6-8d29-acd8e258eac1', 'e87a3f25-9476-4317-bcf1-8feb2a0dd7a4', 'es', 'Preservación', '<div>La organización debe preservar las salidas durante la producción y prestación del servicio, en la medida necesaria para asegurarse de la conformidad con los requisitos.</div><div>NOTA: La preservación puede incluir la identificación, la manipulación, el control de la contaminación, el embalaje, el almacenamiento, la transmisión de la información o el transporte, y la protección.</div>'),
    ('1ada2b0e-1412-498c-9d98-deb61fbe8e7b', 'e77a3d92-1b1a-4a2c-97a0-0e6e2b0dd937', 'en', 'Post-delivery activities', '<div>The organization shall meet requirements for post-delivery activities associated with the products and services.</div><div>In determining the extent of post-delivery activities that are required, the organization shall consider:</div><div>{clause_8.5.5.a}</div><div>{clause_8.5.5.b}</div><div>{clause_8.5.5.c}</div><div>{clause_8.5.5.d}</div><div>{clause_8.5.5.e}</div><div>NOTE: Post-delivery activities can include actions under warranty provisions, contractual obligations such as maintenance services, and supplementary services such as recycling or final disposal. </div>'),
    ('07da0d25-f8a8-406b-bdc0-97f90abe6d6c', 'e77a3d92-1b1a-4a2c-97a0-0e6e2b0dd937', 'es', 'Actividades posteriores a la entrega', '<div>La organización debe cumplir los requisitos para las actividades posteriores a la entrega asociadas con los productos y servicios.</div><div>Al determinar el alcance de las actividades posteriores a la entrega que se requieren, la organización debe considerar:</div><div>{clause_8.5.5.a}</div><div>{clause_8.5.5.b}</div><div>{clause_8.5.5.c}</div><div>{clause_8.5.5.d}</div><div>{clause_8.5.5.e}</div><div>NOTA: Las actividades posteriores a la entrega pueden incluir acciones cubiertas por las condiciones de la garantía, obligaciones contractuales como servicios de mantenimiento, y servicios suplementarios como el reciclaje o la disposición final.</div>'),
    ('01e60932-856a-4168-9493-2762bc3dd347', 'd67c6166-095a-44fc-b3a5-576ab4156ca7', 'en', '', '<div>a) statutory and regulatory requirements;</div>'),
    ('16e62a41-cd76-403f-b9f4-65fd9f3da5a0', 'd67c6166-095a-44fc-b3a5-576ab4156ca7', 'es', '', '<div>a) los requisitos legales y reglamentarios;</div>'),
    ('544bcdfb-6a6e-4631-906f-e22f12078dde', 'd77c62f9-b183-47a7-b1d9-f0d7b3156b14', 'en', '', '<div>b) the potential undesired consequences associated with its products and services;</div>'),
    ('3f4bacec-4bea-4eaa-83cd-618c1f07a255', 'd77c62f9-b183-47a7-b1d9-f0d7b3156b14', 'es', '', '<div>b) las consecuencias potenciales no deseadas asociadas a sus productos y servicios;</div>'),
    ('02a88330-03c6-4a82-bb5b-cf981708655d', 'd47c5e40-001f-4936-a845-4320b6156fcd', 'en', '', '<div>c) the nature, use and intended lifetime of its products and services;</div>'),
    ('ffa87e77-99f7-4cd9-8ba1-a0a31a086a16', 'd47c5e40-001f-4936-a845-4320b6156fcd', 'es', '', '<div>c) la naturaleza, el uso y la vida útil prevista de sus productos y servicios;</div>'),
    ('267051c1-25c9-49db-ad2c-ea7d9d955d1c', 'd57c5fd3-c439-4131-8cdd-ad5db5156e3a', 'en', '', '<div>d) customer requirements; </div>'),
    ('117030b2-9ea5-4ddc-87cb-abe292954bcb', 'd57c5fd3-c439-4131-8cdd-ad5db5156e3a', 'es', '', '<div>d) los requisitos del cliente;</div>'),
    ('e714bdbe-fe59-4eac-9b44-67467cc2a21b', 'da7c67b2-bc15-4298-b66b-881eb015665b', 'en', '', '<div>e) customer feedback. </div>'),
    ('f414d235-e2ef-458b-a168-572967c2810c', 'da7c67b2-bc15-4298-b66b-881eb015665b', 'es', '', '<div>e) la retroalimentación del cliente.</div>'),
    ('071f11a7-2b3d-4d25-9bf6-22332a5cdd52', 'db7c6945-2e47-4cd3-9403-e75baf1564c8', 'en', 'Control of changes', '<div>The organization shall review and control changes for production or service provision, to the extent necessary to ensure continuing conformity with requirements.</div><div>The organization shall retain documented information describing the results of the review of changes, the person(s) authorizing the change, and any necessary actions arising from the review. </div>'),
    ('ea1ee400-d850-48e6-88fb-aec83f5cfe61', 'db7c6945-2e47-4cd3-9403-e75baf1564c8', 'es', 'Control de los cambios', '<div>La organización debe revisar y controlar los cambios para la producción o la prestación del servicio, en la extensión necesaria para asegurarse de la continuidad en la conformidad con los requisitos.</div><div>La organización debe conservar información documentada que describa los resultados de la revisión de los cambios, las personas que autorizan el cambio y de cualquier acción necesaria que surja de la revisión.</div>'),
    ('e8769b7c-6610-4286-932c-34fc51618ee1', 'd87c648c-8cba-4522-91ce-4334b2156981', 'en', 'Release of products and services', '<div>The organization shall implement planned arrangements, at appropriate stages, to verify that the product and service requirements have been met.</div><div>The release of products and services to the customer shall not proceed until the planned arrangements have been satisfactorily completed, unless otherwise approved by a relevant authority and, as applicable, by the customer.</div><div>The organization shall retain documented information on the release of products and services. The documented information shall include:</div><div>{clause_8.6.a}</div><div>{clause_8.6.b}</div>'),
    ('dd768a2b-a2de-4e45-bbba-207f3c616dd2', 'd87c648c-8cba-4522-91ce-4334b2156981', 'es', 'Liberación de los productos y servicios', '<div>La organización debe implementar las disposiciones planificadas, en las etapas adecuadas, para verificar que se cumplen los requisitos de los productos y servicios.</div><div>La liberación de los productos y servicios al cliente no debe llevarse a cabo hasta que se hayan completado satisfactoriamente las disposiciones planificadas, a menos que sea aprobado de otra manera por una autoridad pertinente y cuando sea aplicable, por el cliente.</div><div>La organización debe conservar la información documentada sobre la liberación de los productos y servicios. La información documentada debe incluir:</div><div>{clause_8.6.a}</div><div>{clause_8.6.b}</div>'),
    ('ec17283d-d0aa-4bef-b75a-8811b7c744d0', 'd97c661f-006c-40ad-9cb7-7f91b11567ee', 'en', '', '<div>a) evidence of conformity with the acceptance criteria; </div>'),
    ('ef172cf6-cc23-4f38-9af6-8a3eb4c74017', 'd97c661f-006c-40ad-9cb7-7f91b11567ee', 'es', '', '<div>a) evidencia de la conformidad con los criterios de aceptación;</div>'),
    ('fc9cf21a-df60-4600-984f-8faa97925a8f', 'de7c6dfe-69b1-4854-8a6d-7452ac15600f', 'en', '', '<div>b) traceability to the person(s) authorizing the release. </div>'),
    ('e19cc799-d62d-4667-a10d-3cf58a924618', 'de7c6dfe-69b1-4854-8a6d-7452ac15600f', 'es', '', '<div>b) trazabilidad a las personas que autorizan la liberación.</div>'),
    ('b92e7603-aa58-4fe9-a6c3-5bb776ea35e6', 'df7c6f91-d88e-439f-8582-105fab155e7c', 'en', 'Control of nonconforming outputs', '<div>{clause_8.7.1}</div><div>{clause_8.7.2}</div>'),
    ('b42e6e24-d3ce-47f2-b6ed-428493ea638d', 'df7c6f91-d88e-439f-8582-105fab155e7c', 'es', 'Control de las salidas no conformes', '<div>{clause_8.7.1}</div><div>{clause_8.7.2}</div>'),
    ('f2ac7771-70ca-431f-9659-c80dab8aba60', '5c7f72ef-2bfa-4fb5-9765-060dae13249e', 'en', '', '<div> The organization shall ensure that outputs that do not conform to their requirements areidentified and controlled to prevent their unintended use or delivery.</div><div>The organization shall take appropriate action based on the nature of the nonconformity and its effect on the conformity of products and services. This shall also apply to nonconforming products and services detected after delivery of products, during or after the provision of services.</div><div>The organization shall deal with nonconforming outputs in one or more of the following ways:</div><div>{clause_8.7.1.a}</div><div>{clause_8.7.1.b}</div><div>{clause_8.7.1.c}</div><div>{clause_8.7.1.d}</div><div>Conformity to the requirements shall be verified when nonconforming outputs are corrected. </div>'),
    ('fdac88c2-2641-4848-9e14-f212c88ae807', '5c7f72ef-2bfa-4fb5-9765-060dae13249e', 'es', '', '<div>La organización debe asegurarse de que las salidas que no sean conformes con sus requisitos se identifican y se controlan para prevenir su uso o entrega no intencionada.</div><div>La organización debe tomar las acciones adecuadas basándose en la naturaleza de la no conformidad y en su efecto sobre la conformidad de los productos y servicios. Esto se debe aplicar también a los productos y servicios no conformes detectados después de la entrega de los productos, durante o después de la provisión de los servicios.</div><div>La organización debe tratar las salidas no conformes de una o más de las siguientes maneras:</div><div>{clause_8.7.1.a}</div><div>{clause_8.7.1.b}</div><div>{clause_8.7.1.c}</div><div>{clause_8.7.1.d}</div><div>Debe verificarse la conformidad con los requisitos cuando se corrigen las salidas no conformes.</div>'),
    ('5c2a6720-0b77-4af6-a408-8ee8448733b1', '5b7f715c-07b5-440a-a038-0850af132631', 'en', '', '<div>a) correction; </div>'),
    ('792a94c7-1e0a-4695-bb0a-4ed34f874502', '5b7f715c-07b5-440a-a038-0850af132631', 'es', '', '<div>a) corrección;</div>'),
    ('1eab5b6b-4c25-4715-98a3-613f5ffd4fe2', '5e7f7615-f280-4e5b-8690-47c7ac132178', 'en', '', '<div>b) segregation, containment, return or suspension of provision of products and services;</div>'),
    ('29ab6cbc-3992-4b76-b5fc-5cbc54fd3e91', '5e7f7615-f280-4e5b-8690-47c7ac132178', 'es', '', '<div>b) separación, contención, devolución o suspensión de provisión de productos y servicios;</div>'),
    ('0e2100a2-ca0d-421c-bf8b-53f2708617ab', '5d7f7482-00f2-49a0-9378-0c5aad13230b', 'en', '', '<div>c) informing the customer; </div>'),
    ('0320ef51-6cf8-4c1b-a03f-c96d7b8628fc', '5d7f7482-00f2-49a0-9378-0c5aad13230b', 'es', '', '<div>c) información al cliente:</div>'),
    ('f8521fad-3d36-444b-b5b3-0f6190bb01ec', '587f6ca3-6ba0-4fd9-8b48-c341b2132aea', 'en', '', '<div>d) obtaining authorization for acceptance under concession.</div>'),
    ('db51f206-58a0-4d6c-9921-6b2ea5bb22fb', '587f6ca3-6ba0-4fd9-8b48-c341b2132aea', 'es', '', '<div>d) obtención de autorización para su aceptación bajo concesión.</div>'),
    ('41591bac-7d66-4172-b558-65cc4a2e6eed', '577f6b10-64fa-4f9e-bb97-b4e4b3132c7d', 'en', '', '<div>The organization shall retain documented information that: </div><div>{clause_8.7.2.a}</div><div>{clause_8.7.2.b}</div><div>{clause_8.7.2.c}</div><div>{clause_8.7.2.d}</div>'),
    ('56593cbb-53f0-4969-8d8a-4e6f2d2e4146', '577f6b10-64fa-4f9e-bb97-b4e4b3132c7d', 'es', '', '<div>La organización debe conservar la información documentada que:&nbsp;</div><div>{clause_8.7.2.a}</div><div>{clause_8.7.2.b}</div><div>{clause_8.7.2.c}</div><div>{clause_8.7.2.d}</div>'),
    ('d3fa9b17-3f00-4861-b137-7ec345cb682e', '5a7f6fc9-f333-422f-85d1-f68bb01327c4', 'en', '', '<div>a) describes the nonconformity; </div>'),
    ('d6fa9fd0-9686-4a3a-a533-97b832cb4a45', '5a7f6fc9-f333-422f-85d1-f68bb01327c4', 'es', '', '<div>a) describa la no conformidad:</div>'),
    ('f3ef18ee-e335-4c18-89b3-dd96235aee57', '597f6e36-8455-43e4-8881-b80eb1132957', 'en', '', '<div>b) describes the actions taken; </div>'),
    ('e0eefb05-d19e-434f-882b-7dd9265af310', '597f6e36-8455-43e4-8881-b80eb1132957', 'es', '', '<div>b) describa las acciones tomadas:</div>'),
    ('ce00feb9-1e56-4797-8394-ab15a641a348', '647f7f87-1cec-447d-8df6-db55a6131806', 'en', '', '<div>c) describes any concessions obtained;</div>'),
    ('e901293a-7eb5-4bd0-8558-804a9341855f', '647f7f87-1cec-447d-8df6-db55a6131806', 'es', '', '<div>c) describa todas las concesiones obtenidas;</div>'),
    ('5466e708-4d6b-4cee-941c-84101d62e4f9', '637f7df4-a75f-43b2-89f1-8c38a7131999', 'en', '', '<div>d) identifies the authority deciding the action in respect of the nonconformity. </div>'),
    ('4166c91f-d74d-47fd-907e-cdeb38630f7a', '637f7df4-a75f-43b2-89f1-8c38a7131999', 'es', '', '<div>d) identifique la autoridad que decide la acción con respecto a la no conformidad.</div>'),
    ('4bb5c364-3dac-49da-b48e-f844162e3205', '6281baf8-4877-42fa-904e-9d7c9ff2bae9', 'en', 'Performance evaluation', '<div>{clause_9.1}<br>{clause_9.2}</div><div>{clause_9.3}</div>'),
    ('50b5cb43-01eb-4301-9ab9-a077292e4fee', '6281baf8-4877-42fa-904e-9d7c9ff2bae9', 'es', 'Evaluación del desempeño', '<div>{clause_9.1}<br>{clause_9.2}</div><div>{clause_9.3}</div>'),
    ('e2ae9505-8758-4af3-bf52-75597f356064', '6381bc8b-9b89-4865-a74c-d1f99ef2b956', 'en', 'Monitoring, measurement, analysis and evaluation', '<div>{clause_9.1.1}</div><div>{clause_9.1.2}</div><div>{clause_9.1.3}</div>'),
    ('f5aeb2ee-7b66-47a4-80da-d51684356843', '6381bc8b-9b89-4865-a74c-d1f99ef2b956', 'es', 'Seguimiento, medición, análisis y evaluación', '<div>{clause_9.1.1}</div><div>{clause_9.1.2}</div><div>{clause_9.1.3}</div>'),
    ('ddadbd86-30ce-4aa0-b056-3daebe7d6caf', '6481be1e-4114-44d0-a0cf-2da69df2b7c3', 'en', 'General', '<div>The organization shall determine: </div><div>{clause_9.1.1.a}</div><div>{clause_9.1.1.b}</div><div>{clause_9.1.1.c}</div><div>{clause_9.1.1.d}</div><div>The organization shall evaluate the performance and the effectiveness of the quality management system.</div><div>The organization shall retain appropriate documented information as evidence of the results. </div>'),
    ('faadeb2d-2a14-4107-8ce7-e1e1b17d5838', '6481be1e-4114-44d0-a0cf-2da69df2b7c3', 'es', 'Generalidades', '<div>La organización debe determinar:&nbsp;</div><div>{clause_9.1.1.a}</div><div>{clause_9.1.1.b}</div><div>{clause_9.1.1.c}</div><div>{clause_9.1.1.d}</div><div>La organización debe evaluar el desempeño y la eficacia del sistema de gestión de la calidad.</div><div>La organización debe conservar la información documentada apropiada como evidencia de los resultados.</div>'),
    ('8afdcfaf-b837-4a89-b671-6a9b112d5a86', '6581bfb1-4bef-4e8b-8459-6bc39cf2b630', 'en', '', '<div>a) what needs to be monitored and measured;</div>'),
    ('7dfdbb38-c861-4d92-b0fa-d7602e2d882d', '6581bfb1-4bef-4e8b-8459-6bc39cf2b630', 'es', '', '<div>a) qué necesita seguimiento y medición;</div>'),
    ('65e7ab18-27bf-4ede-b33c-1a405088ee89', '6681c144-bb3c-434e-9557-7108a3f2c135', 'en', '', '<div>b) the methods for monitoring, measurement, analysis and evaluation needed to ensure valid results;</div>'),
    ('72e7bf8f-f34a-43cd-be1c-2e7b4b88e6aa', '6681c144-bb3c-434e-9557-7108a3f2c135', 'es', '', '<div>b) los métodos de seguimiento, medición, análisis y evaluación necesarios para asegurar resultados válidos;</div>'),
    ('1d095189-9b30-4707-952f-724599674818', '6781c2d7-abc3-4b09-9564-8d65a2f2bfa2', 'en', '', '<div>c) when the monitoring and measuring shall be performed; </div>'),
    ('180949aa-a1ea-40a0-b047-badaa6675c8f', '6781c2d7-abc3-4b09-9564-8d65a2f2bfa2', 'es', '', '<div>c) cuándo se deben llevar a cabo el seguimiento y la medición;</div>'),
    ('187f3b5a-62ee-4b84-9790-01ea0b093243', '6881c46a-c477-4f14-a7c5-7212a1f2be0f', 'en', '', '<div>d) when the results from monitoring and measurement shall be analysed and evaluated.</div>'),
    ('fd7f10d9-5593-49d3-8567-e23506092a64', '6881c46a-c477-4f14-a7c5-7212a1f2be0f', 'es', '', '<div>d) cuándo se deben analizar y evaluar los resultados del seguimiento y la medición.</div>'),
    ('d7899543-2cab-467d-a503-1bf74bfed85a', '6981c5fd-4ca0-4f5f-8ac2-de1fa0f2bc7c', 'en', 'Customer satisfaction', '<div>The organization shall monitor customers'' perceptions of the degree to which their needs and expectations have been fulfilled.The organization shall determine the methods for obtaining, monitoring and reviewing this information.</div><div>NOTE: Examples of monitoring customer perceptions can include customer surveys, customer feedback on delivered products and services, meetings with customers, market-share analysis, compliments, warranty claims and dealer reports. </div>'),
    ('d2898d64-a2c9-4b6e-bed8-73c430feadd9', '6981c5fd-4ca0-4f5f-8ac2-de1fa0f2bc7c', 'es', 'Satisfacción del cliente', '<div>La organización debe realizar el seguimiento de las percepciones de los clientes del grado en que se cumplen sus necesidades y expectativas. La organización debe determinar los métodos para obtener, realizar el seguimiento y revisar esta información.</div><div>NOTA: Los ejemplos de seguimiento de las percepciones del cliente pueden incluir las encuestas al cliente, la retroalimentación del cliente sobre los productos y servicios entregados, las reuniones con los clientes, el análisis de las cuotas de mercado, las felicitaciones, las garantías utilizadas y los informes de agentes comerciales.</div>'),
    ('0458e4bc-1464-4622-b082-d13c3df1e47d', '5a81ae60-0349-4ce2-a7e9-07f4a7f2c781', 'en', 'Analysis and evaluation', '<div>The organization shall analyse and evaluate appropriate data and information arising from monitoring and measurement.</div><div>The results of analysis shall be used to evaluate: </div><div>{clause_9.1.3.a}</div><div>{clause_9.1.3.b}</div><div>{clause_9.1.3.c}</div><div>{clause_9.1.3.d}</div><div>{clause_9.1.3.e}</div><div>{clause_9.1.3.f}</div><div>{clause_9.1.3.g}</div><div>NOTE: Methods to analyse data can include statistical techniques.</div>'),
    ('f958d36b-c0b5-40f9-9329-d5bf40f1e936', '5a81ae60-0349-4ce2-a7e9-07f4a7f2c781', 'es', 'Análisis y evaluación', '<div>La organización debe analizar y evaluar los datos y la información apropiados que surgen por el seguimiento y la medición.</div><div>Los resultados del análisis deben utilizarse para evaluar:&nbsp;</div><div>{clause_9.1.3.a}</div><div>{clause_9.1.3.b}</div><div>{clause_9.1.3.c}</div><div>{clause_9.1.3.d}</div><div>{clause_9.1.3.e}</div><div>{clause_9.1.3.f}</div><div>{clause_9.1.3.g}</div><div>NOTA: Los métodos para analizar los datos pueden incluir técnicas estadísticas.</div>'),
    ('0a72477d-3669-487b-96fd-3a5137d881bc', '5b81aff3-5dae-436d-9ec3-f151a6f2c5ee', 'en', '', '<div>a) conformity of products and services; </div>'),
    ('0d724c36-95f7-447c-88cb-287e2cd8706b', '5b81aff3-5dae-436d-9ec3-f151a6f2c5ee', 'es', '', '<div>a) la conformidad de los productos y servicios;</div>'),
    ('3d067aab-f4b2-4ab9-86d8-c87f44f134d6', '68840301-690f-461b-9bad-2b8799f072e0', 'en', '', '<div>b) the degree of customer satisfaction; </div>'),
    ('48068bfc-61af-47e2-9e4a-dcfc41f1301d', '68840301-690f-461b-9bad-2b8799f072e0', 'es', '', '<div>b) el grado de satisfacción del cliente;</div>'),
    ('2c7db2e2-9789-4190-8319-6d32b1a3117f', '6784016e-7505-4560-83d3-d71a9af07473', 'en', '', '<div>c) the performance and effectiveness ofthe quality management system; </div>'),
    ('217da191-34b0-4457-89b4-3dadc4a32f68', '6784016e-7505-4560-83d3-d71a9af07473', 'es', '', '<div>c) el desempeño y la eficacia del sistema de gestión de la calidad;</div>'),
    ('110796b1-de45-4263-8eb1-a04db25b69f4', '6683ffdb-a289-4775-810f-28cd9bf07606', 'en', '', '<div>d) if planning has been implemented effectively; </div>'),
    ('1c07a802-4545-4eb4-acc2-9a52975b3f73', '6683ffdb-a289-4775-810f-28cd9bf07606', 'es', '', '<div>d) si lo planificado se ha implementado de forma eficaz;</div>'),
    ('780b1d60-ee13-458a-b461-83284bcea495', '6583fe48-64f7-46ca-a886-4d109cf07799', 'en', '', '<div>e) the effectiveness of actions taken to address risks and opportunities; </div>'),
    ('950b4b07-f679-4791-9f67-09133ece901e', '6583fe48-64f7-46ca-a886-4d109cf07799', 'es', '', '<div>e) la eficacia de las acciones tomadas para abordar los riesgos y oportunidades;</div>'),
    ('efdb5157-bc3a-45ad-9fd5-91033f247d2a', '6c84094d-6745-4def-809a-8a4b9df0792c', 'en', '', '<div>f) the performance of external providers;</div>'),
    ('f2db5610-d4e6-4fbe-aa00-07f844248509', '6c84094d-6745-4def-809a-8a4b9df0792c', 'es', '', '<div>f) el desempeño de los proveedores externos;</div>'),
    ('124bcb2e-100b-48b4-a820-65d67227e053', '6b8407ba-df1d-4da4-8321-e6ce9ef07abf', 'en', '', '<div>g) the need for improvements to the quality management system. </div>'),
    ('ff4bad45-a90b-4c63-b74e-76198d280ad4', '6b8407ba-df1d-4da4-8321-e6ce9ef07abf', 'es', '', '<div>g) la necesidad de mejoras en el sistema de gestión de la calidad.</div>'),
    ('16aed1ed-9464-4b37-8934-b3a1cd2cb568', '6a840627-c8e1-4f99-a6ab-4c019ff07c52', 'en', 'Internal audit', '<div>{clause_9.2.1}</div><div>{clause_9.2.2}</div>'),
    ('f9aea446-f4c3-4f70-86fb-956eba2c977f', '6a840627-c8e1-4f99-a6ab-4c019ff07c52', 'es', 'Auditoria interna', '<div>{clause_9.2.1}</div><div>{clause_9.2.2}</div>'),
    ('5d3b64ec-d4dc-4c0e-99d3-2e0c444c6419', '69840494-c23c-425e-a109-d0a4a0f07de5', 'en', '', '<div>The organization shall conduct internal audits at planned intervals to provide information on whether the quality management system:<br>{clause_9.2.1.a}</div><div>{clause_9.2.1.b}</div>'),
    ('723b85fb-61ea-409d-a675-aeaf5f4c8e9a', '69840494-c23c-425e-a109-d0a4a0f07de5', 'es', '', '<div>La organización debe llevar a cabo auditorías internas a intervalos planificados para proporcionar información acerca de si el sistema de gestión de la calidad:<br>{clause_9.2.1.a}</div><div>{clause_9.2.1.b}</div>'),
    ('a1eab5b3-a169-4c81-bc3b-72076cb4e74e', '6083f669-bf79-4023-b273-934fa1f07f78', 'en', '', '<div>a) conforms to: &nbsp;</div><ul><li>{clause_9.2.1.a.1}</li><li>{clause_9.2.1.a.2}</li></ul>'),
    ('bceae034-dd2a-435a-a13d-87f459b4c965', '6083f669-bf79-4023-b273-934fa1f07f78', 'es', '', '<div>a) es conforme con:</div><ul><li>{clause_9.2.1.a.1}</li><li>{clause_9.2.1.a.2}</li></ul>'),
    ('7160288a-6dd4-47b8-b46b-fe3a4cbed677', '5f83f4d6-3729-4068-955b-af42a2f0810b', 'en', '', '<div>1) the organization’s own requirements for its quality management system;</div>'),
    ('76603069-725b-446f-be15-c6254fbedb30', '5f83f4d6-3729-4068-955b-af42a2f0810b', 'es', '', '<div>1) los requisitos propios de la organización para su sistema de gestión-de la calidad;&nbsp;</div>'),
    ('2025fa95-c8f4-4d43-a898-2989839af7d4', 'd242b4bb-f058-42c5-9367-28893031c126', 'en', '', '<div>2) the requirements of this International Standard; </div>'),
    ('1325e61e-19d4-4114-ae79-c526689acd53', 'd242b4bb-f058-42c5-9367-28893031c126', 'es', '', '<div>2) los requisitos de esta Norma internacional;</div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('86b2bff4-c2a3-4aea-be0a-bfb4a73a23f5', 'd142b328-9d46-4d5a-adee-758c3131c2b9', 'en', '', '<div>b) is effectively implemented and maintained. </div>'),
    ('6bb29573-deae-4c71-b02a-c6c79a3a0f7e', 'd142b328-9d46-4d5a-adee-758c3131c2b9', 'es', '', '<div>b) se implementa y mantiene eficazmente.</div>'),
    ('85fa677f-21fb-4d19-9756-92cba2d71d36', 'd442b7e1-a0be-48eb-9575-86932e31be00', 'en', '', '<div>The organization shall: </div><div>{clause_9.2.2.a}</div><div>{clause_9.2.2.b}</div><div>{clause_9.2.2.c}</div><div>{clause_9.2.2.d}</div><div>{clause_9.2.2.e}</div><div>{clause_9.2.2.f}</div><div>NOTE: See ISO 19011 for guidance. </div>'),
    ('98fa8568-a29d-49c2-a991-7ef09fd7187d', 'd442b7e1-a0be-48eb-9575-86932e31be00', 'es', '', '<div>La organización debe:&nbsp;</div><div>{clause_9.2.2.a}</div><div>{clause_9.2.2.b}</div><div>{clause_9.2.2.c}</div><div>{clause_9.2.2.d}</div><div>{clause_9.2.2.e}</div><div>{clause_9.2.2.f}</div><div>NOTA Véase la Norma ISO 19011 a modo de orientación.</div>'),
    ('19488ad6-aa6d-43f0-b1d8-b01e82e10c5f', 'd342b64e-c54e-49b0-bb93-38762f31bf93', 'en', '', '<div>a) plan, establish, implement and maintain an audit programme(s) including the frequency, methods, responsibilities, planning requirements and reporting, which shall take into consideration the importance of the processes concerned, changes affecting the organization, and the results of previous audits; </div>'),
    ('1648861d-4a0e-4fb7-a7d0-747195e12a48', 'd342b64e-c54e-49b0-bb93-38762f31bf93', 'es', '', '<div>a) planificar, establecer, implementar y mantener uno o varios programas de auditoría que incluyan la frecuencia, los métodos, las responsabilidades, los requisitos de planificación y la elaboración de informes, que deben tener en consideración la importancia de los procesos involucrados, los cambios que afecten a la organización y los resultados de las auditorías previas;</div>'),
    ('18a3ba19-93a3-4e17-8887-e8759e6ab048', 'd642bb07-16b0-4ae9-b87e-75753431c772', 'en', '', '<div>b) define the audit criteria and scope for each audit;</div>'),
    ('33a3e49a-f402-4250-bfca-3b2a8b6a925f', 'd642bb07-16b0-4ae9-b87e-75753431c772', 'es', '', '<div>b) definir los criterios de la auditoría y el alcance para cada auditoría;</div>'),
    ('a1840b68-c2b8-436e-9908-74f0158bf1f9', 'd542b974-100b-4dae-b11c-90d83531c905', 'en', '', '<div>c) select auditors and conduct audits to ensure objectivity and the impartiality of the audit process;</div>'),
    ('8e83ed7f-4c9a-4e7d-86cd-88cb308c1c7a', 'd542b974-100b-4dae-b11c-90d83531c905', 'es', '', '<div>c) seleccionar los auditores y llevar a cabo auditorías para asegurarse de la objetividad y la&nbsp;imparcialidad del proceso de auditoría;</div>'),
    ('467f3653-3ad2-420d-9318-15279d08d28a', 'd842be2d-a16f-49bf-a5b3-ae2f3231c44c', 'en', '', '<div>d) ensure that the results of the audits are reported to relevant management;</div>'),
    ('617f60d4-6ccb-411e-99ca-b594a208da69', 'd842be2d-a16f-49bf-a5b3-ae2f3231c44c', 'es', '', '<div>d) asegurarse de que los resultados de las auditorías se informen a la dirección pertinente;</div>'),
    ('137bd32a-0f49-4894-93ae-a2dacd935fb3', 'd742bc9a-48b3-46f4-8102-0e223331c5df', 'en', '', '<div>e) take appropriate correction and corrective actions without undue delay;</div>'),
    ('187bdb09-be69-44c3-b896-5a45e8938a34', 'd742bc9a-48b3-46f4-8102-0e223331c5df', 'es', '', '<div>e) realizar las correcciones y tomar las acciones correctivas adecuadas sin demora injustificada;</div>'),
    ('b8c8e98d-b283-4acb-8253-7c4188e40eec', 'ca42a823-b001-41cd-9811-f6613831cdbe', 'en', '', '<div>f) retain documented information as evidence of the implementation of the audit programme and the audit results. </div>'),
    ('9bc8bbe6-cded-43ec-bd7c-6a0e9de42ffb', 'ca42a823-b001-41cd-9811-f6613831cdbe', 'es', '', '<div>f) conservar información documentada como evidencia de la implementación del programa de auditoría y de los resultados de las auditorías.</div>'),
    ('01cfe58c-f2b3-47f2-866b-8f2c42577bed', 'c942a690-6bbd-46c2-b165-62843931cf51', 'en', 'Management review', '<div>{clause_9.3.1}</div><div>{clause_9.3.2}</div><div>{clause_9.3.3}</div>'),
    ('16d0069b-c93d-4fe9-9b14-f1cf25574e46', 'c942a690-6bbd-46c2-b165-62843931cf51', 'es', 'Revisión por la dirección', '<div>{clause_9.3.1}</div><div>{clause_9.3.2}</div><div>{clause_9.3.3}</div>'),
    ('25082126-73a6-452c-b4b8-454e74ebaf1b', '4c3fa332-7a14-468c-a305-fc06b634d2af', 'en', 'General', '<div>Top management shall review the organization''s quality management system, at planned intervals, to ensure its continuing suitability, adequacy, effectiveness and alignment with the strategic direction of the organization.</div>'),
    ('42084ecd-583c-4c0b-9a09-40815feb8e0c', '4c3fa332-7a14-468c-a305-fc06b634d2af', 'es', 'Generalidades', '<div>La alta dirección debe revisar el sistema de gestión de la calidad de la organización a intervalos planificados, para asegurarse de su conveniencia, adecuación, eficacia y alineación continuas con la dirección estratégica de la organización.</div>'),
    ('43376fcf-a08a-43a5-b25c-fe3b2285ea52', '4d3fa4c5-098e-44f7-86d1-3da3b534d11c', 'en', 'Management review inputs', '<div>The management review shall be planned and carried out taking into consideration: </div><div>{clause_9.3.2.a}</div><div>{clause_9.3.2.b}</div><div>{clause_9.3.2.c}</div><div>{clause_9.3.2.d}</div><div>{clause_9.3.2.e}</div><div>{clause_9.3.2.f}</div>'),
    ('36375b58-4d9d-4f66-b98a-840037860b61', '4d3fa4c5-098e-44f7-86d1-3da3b534d11c', 'es', 'Entradas de la revisión por la dirección', '<div>La revisión por la dirección debe planificarse y llevarse a cabo incluyendo consideraciones sobre:&nbsp;</div><div>{clause_9.3.2.a}</div><div>{clause_9.3.2.b}</div><div>{clause_9.3.2.c}</div><div>{clause_9.3.2.d}</div><div>{clause_9.3.2.e}</div><div>{clause_9.3.2.f}</div>'),
    ('90975104-db5d-4906-95a2-8564498a9be1', '4a3fa00c-7176-4b86-a4c3-fedcb834d5d5', 'en', '', '<div>a) the status of actions from previous management reviews; </div>'),
    ('959758e3-182b-44c5-84c3-1697348a7ad2', '4a3fa00c-7176-4b86-a4c3-fedcb834d5d5', 'es', '', '<div>a) el estado de las acciones de las revisiones por la dirección previas;</div>'),
    ('2a0a8ba5-45f7-426f-a185-af79aff051d0', '4b3fa19f-1f71-4b01-a70a-4559b734d442', 'en', '', '<div>b) changes in external and internal issues that are relevant to the quality management system;</div>'),
    ('3d0aa98e-4170-45b8-815d-f636acf04d17', '4b3fa19f-1f71-4b01-a70a-4559b734d442', 'es', '', '<div>b) los cambios en las cuestiones externas e internas que sean pertinentes al sistema de gestión de la calidad;</div>'),
    ('5d5f35fa-fab7-47e8-a717-1d0ab466e047', '483f9ce6-174f-4f68-9fdb-a872b234cc63', 'en', '', '<div>c) information on the performance and effectiveness of the quality management system, including trends in:</div><ul><li>{clause_9.3.2.c.1}</li><li>{clause_9.3.2.c.2}</li><li>{clause_9.3.2.c.3}</li><li>{clause_9.3.2.c.4}</li><li>{clause_9.3.2.c.5}</li><li>{clause_9.3.2.c.6}</li><li>{clause_9.3.2.c.7}</li></ul>'),
    ('425f0b79-42c3-46bf-8cd1-1bd59766b2a0', '483f9ce6-174f-4f68-9fdb-a872b234cc63', 'es', '', '<div>c) la información sobre el desempeño y la eficacia del sistema de gestión de la calidad, incluidas las tendencias relativas a:</div><ul><li>{clause_9.3.2.c.1}</li><li>{clause_9.3.2.c.2}</li><li>{clause_9.3.2.c.3}</li><li>{clause_9.3.2.c.4}</li><li>{clause_9.3.2.c.5}</li><li>{clause_9.3.2.c.6}</li><li>{clause_9.3.2.c.7}</li></ul>'),
    ('8fc4c863-dfbc-4cb1-a1d9-f0970a309ade', '493f9e79-9f9f-4f23-a99c-67ffb134cad0', 'en', '', '<div>1) customer satisfaction and feedback from relevant interested parties;</div>'),
    ('8ac4c084-c138-452a-b2b9-5f641730af55', '493f9e79-9f9f-4f23-a99c-67ffb134cad0', 'es', '', '<div>1) la satisfacción del cliente y la retroalimentación de las partes interesadas pertinentes;</div>'),
    ('1e22de38-7913-4102-9b0b-96e00f31725d', '463f99c0-fe12-4772-94c7-6168b434cf89', 'en', '', '<div>2) the extent to which quality objectives have been met; </div>'),
    ('2b22f2af-0f44-4359-a082-2a1b12317716', '463f99c0-fe12-4772-94c7-6168b434cf89', 'es', '', '<div>2) el grado en que se han logrado los objetivos de la calidad;</div>'),
    ('6463b529-9b17-405b-904f-9b6595be6a1c', '473f9b53-57d9-4d3d-b63e-2845b334cdf6', 'en', '', '<div>3) process performance and conformity of products and services; </div>'),
    ('5f63ad4a-13f3-445c-9d5f-6a7a8abe58cb', '473f9b53-57d9-4d3d-b63e-2845b334cdf6', 'es', '', '<div>3) el desempeño de los procesos y conformidad de los productos y servicios;</div>'),
    ('bdab101e-c79b-4364-980c-c2a6d9ce5723', '543fafca-bf42-4ca4-b71d-88bebe34df47', 'en', '', '<div>4) nonconformities and corrective actions; </div>'),
    ('caab2495-ba42-44b3-922b-2709d4ce4f44', '543fafca-bf42-4ca4-b71d-88bebe34df47', 'es', '', '<div>4) las no conformidades y acciones correctivas;</div>'),
    ('6a5bbe87-22c9-46dd-845b-eb13a9e32dba', '553fb15d-476b-4cef-a64e-96fbbd34ddb4', 'en', '', '<div>5) monitoring and measurement results; </div>'),
    ('4d5b90e0-af06-444e-9956-65288ee30339', '553fb15d-476b-4cef-a64e-96fbbd34ddb4', 'es', '', '<div>5) los resultados de seguimiento y medición;</div>'),
    ('83883df3-62e1-4d41-a72d-e6c78b175f0e', '463d5b29-7fdd-4f1f-834f-0c8f442d6374', 'en', '', '<div>6) audit results; </div>'),
    ('9e886874-b7ed-461a-b50d-dfb478174125', '463d5b29-7fdd-4f1f-834f-0c8f442d6374', 'es', '', '<div>6) los resultados de las auditorias;</div>'),
    ('52ff43ca-4b11-4378-b858-64fa6b214e37', '453d5996-1101-43d4-a871-ce82452d6507', 'en', '', '<div>7) the performance of external providers;</div>'),
    ('57ff4ba9-364d-4e2f-ab48-95e56e2152f0', '453d5996-1101-43d4-a871-ce82452d6507', 'es', '', '<div>7) el desempeño de los proveedores externos;</div>'),
    ('cb80d039-4f18-4fab-96a2-1b154bd9744c', '443d5803-f84a-4cc9-be3d-cb55462d669a', 'en', '', '<div>d) the adequacy of resources; </div>'),
    ('e680faba-4ebb-4acc-9865-f04a60d9955b', '443d5803-f84a-4cc9-be3d-cb55462d669a', 'es', '', '<div>d) la adecuación de los recursos;</div>'),
    ('51e6b888-a147-4652-a729-f410054ce14d', '433d5670-ee79-430e-ba38-7c38472d682d', 'en', '', '<div>e) the effectiveness of actions taken to address risks and opportunities (see 6.1);</div>'),
    ('3ee69a9f-911d-4349-a38c-3debe84cb3a6', '433d5670-ee79-430e-ba38-7c38472d682d', 'es', '', '<div>e) la eficacia de las acciones tomadas para abordar los riesgos y las oportunidades (véase 6.1);</div>'),
    ('365d149f-c8be-48f5-a930-d8eb18a2ec42', '4a3d6175-7f2b-4e4b-83b2-5b73402d5d28', 'en', '', '<div>f) opportunities for improvement.</div>'),
    ('495d3288-e31c-4ed6-acce-8f100da2daf1', '4a3d6175-7f2b-4e4b-83b2-5b73402d5d28', 'es', '', '<div>f) las oportunidades de mejora.</div>'),
    ('58cd8e76-edec-43fc-aafd-3cbeb84c778b', '493d5fe2-8d9c-4690-b601-66d6412d5ebb', 'en', 'Management review outputs', '<div>The outputs of the management review shall include decisions and actions related to: </div><div>{clause_9.3.3.a}</div><div>{clause_9.3.3.b}</div><div>{clause_9.3.3.c}</div><div>The organization shall retain documented information as evidence of the results of management reviews.</div>'),
    ('55cd89bd-8e5f-47fb-8761-3a91c34c88dc', '493d5fe2-8d9c-4690-b601-66d6412d5ebb', 'es', 'Salidas de la revisión por la dirección', '<div>Las salidas de la revisión por la dirección deben incluir las decisiones y acciones relacionadas con: &nbsp;</div><div>{clause_9.3.3.a}</div><div>{clause_9.3.3.b}</div><div>{clause_9.3.3.c}</div><div>La organización debe conservar información documentada como evidencia de los resultados de las revisiones por la dirección.</div>'),
    ('5d2f0235-8033-487f-af12-fc2966aabfc0', '483d5e4f-cec6-4825-90ba-67e9422d604e', 'en', '', '<div>a) opportunities for improvement; </div>'),
    ('502eedbe-3826-46a8-a8ef-0c4683aaed67', '483d5e4f-cec6-4825-90ba-67e9422d604e', 'es', '', '<div>a) las oportunidades de mejora;</div>'),
    ('37156d14-b501-4e56-b618-f854ffa73911', '473d5cbc-94ff-44ba-8dfd-3cec432d61e1', 'en', '', '<div>b) any need for changes to the quality management system; </div>'),
    ('1c154293-9aa3-4875-9391-aae70aa74a62', '473d5cbc-94ff-44ba-8dfd-3cec432d61e1', 'es', '', '<div>b) cualquier necesidad de cambio en el sistema de gestión de la calidad;</div>'),
    ('1c2b2ceb-d237-4479-abb0-d13f65ce1596', '4e3d67c1-58d2-4327-b6d7-37c73c2d56dc', 'en', '', '<div>c) resource needs. </div>'),
    ('272b3e3c-25e6-49a2-8909-ccbc62ce10dd', '4e3d67c1-58d2-4327-b6d7-37c73c2d56dc', 'es', '', '<div>c) las necesidades de recursos.</div>'),
    ('0ba0d222-5901-4250-9298-c3f2d27e5f3f', '4d3d662e-b0a9-407c-83be-fc5a3d2d586f', 'en', 'Improvement', '<div>{clause_10.1}</div><div>{clause_10.2}</div><div>{clause_10.3}</div>'),
    ('00a0c0d1-f8a2-4e17-b34d-396de57e7d28', '4d3d662e-b0a9-407c-83be-fc5a3d2d586f', 'es', 'Mejora', '<div>{clause_10.1}</div><div>{clause_10.2}</div><div>{clause_10.3}</div>'),
    ('85bd784c-f1a3-44e2-83d7-dbec5c545c3d', '403b1320-7e53-4abe-b141-6fc44a2fab7d', 'en', 'General', '<div>The organization shall determine and select opportunities for improvement and implement any necessary actions to meet customer requirements and enhance customer satisfaction. </div><div>These shall include:</div><div>{clause_10.1.a}</div><div>{clause_10.1.b}</div><div>{clause_10.1.c}</div><div>NOTE: Examples of improvement can include correction, corrective action, continual improvement, breakthrough change, innovation and re-organization. </div>'),
    ('9abd995b-84a5-47b9-8c21-9b8f5f5460f6', '403b1320-7e53-4abe-b141-6fc44a2fab7d', 'es', '', '<div>La organización debe determinar y seleccionar las oportunidades de mejora e implementar cualquier acción necesaria para cumplir los requisitos del cliente y aumentar la satisfacción del cliente.&nbsp;</div><div>Éstas deben incluir:</div><div>{clause_10.1.a}</div><div>{clause_10.1.b}</div><div>{clause_10.1.c}</div><div>NOTA: Los ejemplos de mejora pueden incluir corrección, acción correctiva, mejora continua, cambio abrupto, innovación y reorganización.</div>'),
    ('3f30e54d-bdaf-4b3b-99d8-d60158b3cf7c', '413b14b3-9e46-4ff9-85b1-c6a1492fa9ea', 'en', '', '<div>a) improving products and services to meet requirements as well as to address future needs and expectations;</div>'),
    ('2230b7a6-1ac4-413c-b487-dace4db3be2b', '413b14b3-9e46-4ff9-85b1-c6a1492fa9ea', 'es', '', '<div>a) mejorar los productos y servicios para cumplir los requisitos, así como considerar las necesidades y expectativas futuras;</div>'),
    ('c4fb630e-4254-47c8-8389-9936775c45a7', '423b1646-a0dc-4e84-8288-ecee482fa857', 'en', '', '<div>b) correcting, preventing or reducing undesired effects; </div>'),
    ('b1fb4525-8cdd-429f-a3b1-52795a5c1800', '423b1646-a0dc-4e84-8288-ecee482fa857', 'es', '', '<div>b) corregir, prevenir o reducir los efectos no deseados;</div>'),
    ('a5055237-82fa-4e11-bf80-a7635751f1be', '433b17d9-0fb9-49cf-a7da-6e6b472fa6c4', 'en', '', '<div>c) improving the performance and effectiveness of the quality management system.</div>'),
    ('a80556f0-7a94-4c0a-b31a-675864520635', '433b17d9-0fb9-49cf-a7da-6e6b472fa6c4', 'es', '', '<div>c) mejorar el desempeño y la eficacia del sistema de gestión de la calidad.</div>'),
    ('a08ec3c0-3aa1-47e6-9585-340896ad85c1', '443b196c-0af0-49aa-930e-26b0462fa531', 'en', 'Nonconformity and corrective action', '<div>{clause_10.2.1}</div><div>{clause_10.2.2}</div>'),
    ('bd8ef167-8d8e-4c25-a152-4f7381ad64b2', '443b196c-0af0-49aa-930e-26b0462fa531', 'es', 'No conformidad y acción correctiva', '<div>{clause_10.2.1}</div><div>{clause_10.2.2}</div>'),
    ('398b3d11-a53a-414f-9ba4-22ad72e5b730', '453b1aff-5ea1-42d5-9011-826d452fa39e', 'en', '', '<div>When a nonconformity occurs, including any arising from complaints, the organization shall:</div><div>{clause_10.2.1.a}</div><div>{clause_10.2.1.b}</div><div>{clause_10.2.1.c}</div><div>{clause_10.2.1.d}</div><div>{clause_10.2.1.e}</div><div>{clause_10.2.1.f}</div><div>Corrective actions shall be appropriate to the effects of the nonconformities encountered.</div>'),
    ('448b4e62-b6d2-4a18-9509-52326fe5b277', '453b1aff-5ea1-42d5-9011-826d452fa39e', 'es', '', '<div>Cuando ocurra una no conformidad, incluida cualquiera originada por quejas, la organización debe:</div><div>{clause_10.2.1.a}</div><div>{clause_10.2.1.b}</div><div>{clause_10.2.1.c}</div><div>{clause_10.2.1.d}</div><div>{clause_10.2.1.e}</div><div>{clause_10.2.1.f}</div><div>Las acciones correctivas deben ser apropiadas a los efectos de las no conformidades encontradas.</div>'),
    ('5286f042-5650-4e8c-9682-8312c48901fb', '463b1c92-1d78-4140-bd5c-5fba442fa20b', 'en', '', '<div>a) react to the nonconformity and, as applicable: </div><ul><li>{clause_10.2.1.a.1}</li><li>{clause_10.2.1.a.2}</li></ul>'),
    ('4786def1-3ae6-456b-8ec7-590daf88e0ec', '463b1c92-1d78-4140-bd5c-5fba442fa20b', 'es', '', '<div>a) reaccionar ante la no conformidad y, cuando sea aplicable:&nbsp;</div><ul><li>{clause_10.2.1.a.1}</li><li>{clause_10.2.1.a.2}</li></ul>'),
    ('f2307b8b-ffcc-4f85-be76-24df72233d32', '473b1e25-0f07-48fb-9b7b-1127432fa078', 'en', '', '<div>1) take action to control and correct it; </div>'),
    ('fd308cdc-c086-4dc6-856c-f95c87235e41', '473b1e25-0f07-48fb-9b7b-1127432fa078', 'es', '', '<div>1) tomar acciones para controlarla y corregirla;</div>'),
    ('0d1c4eb4-c277-439a-9525-8874370b12c5', '483b1fb8-39c4-4866-8afb-9ecc422f9ee5', 'en', '', '<div>2) deal with the consequences; </div>'),
    ('f21c2433-6d6b-4ac1-b023-72874a0b30ae', '483b1fb8-39c4-4866-8afb-9ecc422f9ee5', 'es', '', '<div>2) hacer frente a las consecuencias;</div>'),
    ('a4152055-4b4a-44b3-b38b-17499d97d824', '493b214b-fb64-4761-914b-aec9412f9d52', 'en', '', '<div>b) evaluate the need for action to eliminate the cause(s) of the nonconformity, in order that it does not recur or occur elsewhere, by:</div><ul><li>{clause_10.2.1.b.1}</li><li>{clause_10.2.1.b.2}</li><li>{clause_10.2.1.b.3}</li></ul>'),
    ('97150bde-58a3-4364-a297-8ae6a297e003', '493b214b-fb64-4761-914b-aec9412f9d52', 'es', '', '<div>b) evaluar la necesidad de acciones para eliminar las causas de la no conformidad, con el fin de que no vuelva a ocurrir ni ocurra en otra parte, mediante:</div><ul><li>{clause_10.2.1.b.1}</li><li>{clause_10.2.1.b.2}</li><li>{clause_10.2.1.b.3}</li></ul>'),
    ('836e9fe1-bb51-4c4f-8acd-9e1dd09b7230', '4a4c6bff-9805-4c59-99f4-793db82809e2', 'en', '', '<div>1) reviewing and analysing the nonconformity;</div>'),
    ('6e6e7ed2-cce8-4518-ac20-4082cd9b6d77', '4a4c6bff-9805-4c59-99f4-793db82809e2', 'es', '', '<div>1) la revisión y el análisis de la no conformidad;</div>'),
    ('e9d455d0-50b7-42e6-917d-a1b8f46340c1', '494c6a6c-915f-4c1e-88bb-9a80b9280b75', 'en', '', '<div>2) determining the causes of the nonconformity; </div>'),
    ('e6d45117-a3a4-4725-9d81-88c3df631fb2', '494c6a6c-915f-4c1e-88bb-9a80b9280b75', 'es', '', '<div>2) la determinación de las causas de la no conformidad;</div>'),
    ('aecfb31b-15e2-4a85-bbdd-b5cfcfd8f832', '4c4c6f25-1f97-4eaf-85c7-7fb7b62806bc', 'en', '', '<div>3) determining if similar nonconformities exist, or could potentially occur;</div>'),
    ('99cf920c-d69c-48c6-a734-532ce4d91941', '4c4c6f25-1f97-4eaf-85c7-7fb7b62806bc', 'es', '', '<div>3) la determinación de si existen no conformidades similares, o que potencialmente puedan ocurrir;</div>'),
    ('5c69ee52-6c67-498c-ae03-4d02223ebcfb', '4b4c6d92-b0ba-4064-8d45-4acab728084f', 'en', '', '<div>c) implement any action needed;</div>'),
    ('716a0f61-50fd-406b-8cb0-aa9d0d3e9bec', '4b4c6d92-b0ba-4064-8d45-4acab728084f', 'es', '', '<div>c) implementar cualquier acción necesaria; </div>'),
    ('4915765d-d3c5-463b-b849-8931b6698a7c', '464c65b3-585f-4c35-9f9f-2471b4280396', 'en', '', '<div>d) review the effectiveness of any corrective action taken; </div>'),
    ('4c157b16-30da-4c3c-916e-0ddeab69792b', '464c65b3-585f-4c35-9f9f-2471b4280396', 'es', '', '<div>d) revisar la eficacia de cualquier acción correctiva tomada;</div>'),
    ('cfa26e1c-07b9-4fe2-9388-cf1cba0a173d', '454c6420-341a-408a-9f65-be94b5280529', 'en', '', '<div>e) update risks and opportunities determined during planning, if necessary;</div>'),
    ('c4a25ccb-9abc-42b9-8f82-e89fbd0a1bf6', '454c6420-341a-408a-9f65-be94b5280529', 'es', '', '<div>e) si fuera necesario, actualizar los riesgos y oportunidades determinados, durante la planificación;</div>'),
    ('ee4ae447-9910-4911-bd81-fdd3b507acbe', '484c68d9-1ee5-4adb-9956-383bb2280070', 'en', '', '<div>f) make changes to the quality management system, if necessary.</div>'),
    ('d14ab6a0-90ab-470a-a680-3de8c207c135', '484c68d9-1ee5-4adb-9956-383bb2280070', 'es', '', '<div>f) si fuera necesario, hacer cambios al sistema de gestión de la calidad.</div>'),
    ('44149ede-586b-42c8-8146-1966d51200a7', '474c6746-2d57-4620-b06f-aefeb3280203', 'en', '', '<div>The organization shall retain documented information as evidence of:</div><div>{clause_10.2.2.a}</div><div>{clause_10.2.2.b}</div>'),
    ('5114b355-a2f3-4d9f-9239-a5c9b811d300', '474c6746-2d57-4620-b06f-aefeb3280203', 'es', '', '<div>La organización debe conservar información documentada tomo evidencia de:</div><div>{clause_10.2.2.a}</div><div>{clause_10.2.2.b}</div>'),
    ('e85147e9-e4c3-44c7-8e07-ec25157f7ad8', '524c7897-f523-43c1-b4ba-9085c028167a', 'en', '', '<div>a) the nature of the nonconformities and any subsequent actions taken; </div>'),
    ('e351400a-eb7c-4b60-845e-243a227f8f4f', '524c7897-f523-43c1-b4ba-9085c028167a', 'es', '', '<div>a) la naturaleza de las no conformidades y cualquier acción tomada posteriormente;</div>'),
    ('a48ad9f8-c2a0-439e-a86b-5aa0cf19f749', '514c7704-4729-4446-8535-bda8c128180d', 'en', '', '<div>b) the results of any corrective action. </div>'),
    ('b18aee6f-90a7-448d-9803-34dbca19ef6a', '514c7704-4729-4446-8535-bda8c128180d', 'es', '', '<div>b) los resultados de cualquier acción correctiva.</div>'),
    ('920a60e2-7e18-43d8-ae04-8db2a1ed8a17', '444a23f6-12b1-4790-bccb-0b9abe2a51eb', 'en', 'Continual improvement', '<div>The organization shall continually improve the suitability, adequacy and effectiveness of the quality management system.</div><div>The organization shall consider the results of analysis and evaluation, and the outputs from management review, to determine if there are needs or opportunities that shall be addressed as part of continual improvement. </div>'),
    ('870a4f91-6efa-410f-b49f-5e2da4ed8ed0', '444a23f6-12b1-4790-bccb-0b9abe2a51eb', 'es', 'Mejora continua', '<div>La organización debe mejorar continuamente la conveniencia, adecuación y eficacia del sistema de gestión de la calidad.</div><div>La organización debe considerar los resultados del análisis y la evaluación, y las salidas de la revisión por la dirección, para determinar si hay necesidades u oportunidades que deben considerarse como parte de la mejora continua.</div>'),
    ('189dce43-bc02-4e0f-9d47-83f7201ca1d7', '3810eb3f-42f6-442b-a9e7-861f53014cb7', 'en', 'Scope', '<div>This International Standard specifies the requirements for an environmental management system that an organization can use to enhance its environmental performance. This International Standard is intended for use by an organization seeking to manage its environmental responsibilities in a systematic manner that contributes to the environmental pillar of sustainability.</div><div>This International Standard helps an organization achieve the intended outcomes of its environmental management system, which provide value for the environment, the organization itself and interested parties. Consistent with the organization’s environmental policy, the intended outcomes of an environmental management system include:</div><div>— enhancement of environmental performance;</div><div>— fulfilment of compliance obligations;</div><div>— achievement of environmental objectives.</div><div>This International Standard is applicable to any organization, regardless of size, type and nature, and applies to the environmental aspects of its activities, products and services that the organization determines it can either control or influence considering a life cycle perspective. This International Standard does not state specific environmental performance criteria.</div><div>This International Standard can be used in whole or in part to systematically improve environmental management. Claims of conformity to this International Standard, however, are not acceptable unless all its requirements are incorporated into an organization’s environmental management system and fulfilled without exclusion</div>'),
    ('139dc664-cb21-40d8-b71c-dbc4231ca690', '3810eb3f-42f6-442b-a9e7-861f53014cb7', 'es', 'Objeto y campo de aplicación', '<div>Esta Norma Internacional especifica los requisitos para un sistema de gestión ambiental que una organización puede usar para mejorar su desempeño ambiental. La presente norma internacional está prevista para uso por una organización que busque gestionar sus responsabilidades ambientales de una forma sistemática que contribuya al pilar ambiental de la sostenibilidad.</div><div>Esta Norma Internacional ayuda a una organización a lograr los resultados previstos de su sistema de gestión ambiental, con lo que aporta valor al medio ambiente, a la propia organización y a sus partes interesadas. En coherencia con la política ambiental de la organización, los resultados previstos de un sistema de gestión ambiental incluyen:</div><div>— la mejora del desempeño ambiental;</div><div>— el cumplimiento de los requisitos legales y otros requisitos;</div><div>— el logro de los objetivos ambientales.</div><div>Esta Norma Internacional es aplicable a cualquier organización, independientemente de su tamaño, tipo y naturaleza, y se aplica a los aspectos ambientales de sus actividades, productos y servicios que la organización determine que puede controlar o influir en ellos, considerando una perspectiva de ciclo de vida. Esta Norma Internacional no establece criterios de desempeño ambiental específicos.</div><div>Esta Norma Internacional se puede usar en su totalidad o en parte para mejorar sistemáticamente la gestión ambiental. Sin embargo, las declaraciones de conformidad con esta Norma Internacional no son aceptables a menos que todos los requisitos estén incorporados en el sistema de gestión ambiental de una organización, y que se cumplan sin exclusiones. </div>'),
    ('a6fbe418-fb5a-444c-ab80-82408d7cb56c', '3910ecd2-3d03-4f9a-b47c-190854014e4a', 'en', 'Normative references', '<div>There are no normative references</div>'),
    ('b3fbf88f-fbb7-492b-b660-967ba27cd67b', '3910ecd2-3d03-4f9a-b47c-190854014e4a', 'es', 'Referencias normativas', '<div>No se citan referencias normativas.</div>'),
    ('5e1d8a89-16dc-4a45-8d73-da4546f0226d', '3a10ee65-7943-4905-b489-356555014fdd', 'en', 'Terms and definitions', '<div>For the purposes of this document, the following terms and definitions apply.</div><div>{clause_3.1}</div><div>{clause_3.2}</div><div>{clause_3.3}</div><div>{clause_3.4}</div>'),
    ('591d82aa-da0e-4e86-a88c-22da29eff4c6', '3a10ee65-7943-4905-b489-356555014fdd', 'es', 'Términos y definiciones', '<div>Para los propósitos de este documento, se aplican los términos y definiciones siguientes</div><div>{clause_3.1}</div><div>{clause_3.2}</div><div>{clause_3.3}</div><div>{clause_3.4}</div>'),
    ('1ec1f686-ef64-47a2-a89a-a5ae5cbf0362', '3310e360-cf25-4734-bff3-d5a64e0144d8', 'en', 'Terms related to organization and leadership', '<div>{clause_3.1.1}</div><div>{clause_3.1.2}</div><div>{clause_3.1.3}</div><div>{clause_3.1.4}</div><div>{clause_3.1.5}</div><div>{clause_3.1.6}</div>'),
    ('3bc2242d-9bb5-4279-852c-49e151bef211', '3310e360-cf25-4734-bff3-d5a64e0144d8', 'es', 'Términos relacionados con organización y liderazgo', '<div>{clause_3.1.1}</div><div>{clause_3.1.2}</div><div>{clause_3.1.3}</div><div>{clause_3.1.4}</div><div>{clause_3.1.5}</div><div>{clause_3.1.6}</div>'),
    ('cc1208af-116a-49fb-aeb5-d29b6d47cb2b', '3410e4f3-412e-4eff-a37e-13c34f01466b', 'en', 'management system', '<div>set of interrelated or interacting elements of an organization (3.1.4) to establish policies and objectives (3.2.5) and processes (3.3.5) to achieve those objectives</div><div>Note 1 to entry: A management system can address a single discipline or several disciplines (e.g. quality, environment, occupational health and safety, energy, financial management).</div><div>Note 2 to entry: The system elements include the organization’s structure, roles and responsibilities, planning and operation, performance evaluation and improvement.</div><div>Note 3 to entry: The scope of a management system can include the whole of the organization, specific and identified functions of the organization, specific and identified sections of the organization, or one or more functions across a group of organizations.</div>'),
    ('bf11f438-70f7-45fc-a93f-3f607847dc7c', '3410e4f3-412e-4eff-a37e-13c34f01466b', 'es', 'sistema de gestión', '<div>conjunto de elementos de una organización (3.1.4) interrelacionados o que interactúan para establecer políticas, y objetivos (3.2.5) y procesos (3.3.5) para el logro de estos objetivos.</div><div>Nota 1 a la entrada: Un sistema de gestión puede abordar una sola disciplina o varias disciplinas (por ejemplo, calidad, medio ambiente, salud y seguridad ocupacional, gestión de energía, gestión financiera).</div><div>Nota 2 a la entrada: Los elementos del sistema incluyen la estructura de la organización, los roles y las responsabilidades, la planificación y la operación, la evaluación y la mejora del desempeño.</div><div>Nota 3 a la entrada: El alcance de un sistema de gestión puede incluir la totalidad de la organización, funciones específicas e identificadas de la organización, secciones específicas e identificadas de la organización, o una o más funciones dentro de un grupo de organizaciones.</div>'),
    ('8cc9fc64-591e-4788-acd3-6044a84c6de0', '3510e686-b243-48ee-af73-457c500147fe', 'en', 'environmental management system', '<div>part of the management system (3.1.1) used to manage environmental aspects (3.2.2), fulfil compliance obligations (3.2.9), and address risks and opportunities (3.2.11)</div>'),
    ('91ca0443-a12a-465f-92fe-0877c54c9b87', '3510e686-b243-48ee-af73-457c500147fe', 'es', 'sistema de gestión ambiental', '<div>parte del sistema de gestión (3.1.1) usada para gestionar aspectos ambientales (3.2.2), cumplir los requisitos legales y otros requisitos (3.2.9), y abordar los riesgos y oportunidades (3.2.11).</div>'),
    ('23c2ce05-80bc-40d1-b796-dd594148e731', '3610e819-b8e9-4929-8671-79f951014991', 'en', 'environmental policy', '<div>intentions and direction of an organization (3.1.4) related to environmental performance (3.4.11), as formally expressed by its top management (3.1.5)</div>'),
    ('36c2ebee-7ad2-4aca-b91f-3d164c48f882', '3610e819-b8e9-4929-8671-79f951014991', 'es', 'política ambiental', '<div>intenciones y dirección de una organización (3.1.4), relacionadas con el desempeño ambiental (3.4.11),como las expresa formalmente su alta dirección (3.1.5).</div>'),
    ('61556172-02bf-405e-b050-61a2a76fc3b6', '3f10f644-2730-46f8-b536-d62a4a013e8c', 'en', 'organization', '<div>person or group of people that has its own functions with responsibilities, authorities and relationships to achieve its objectives (3.2.5)</div><div>Note 1 to entry: The concept of organization includes, but is not limited to sole-trader, company, corporation, firm, enterprise, authority, partnership, charity or institution, or part or combination thereof, whether incorporated or not, public or private.</div>'),
    ('76558281-ce4a-454d-9867-6c3da46fbefd', '3f10f644-2730-46f8-b536-d62a4a013e8c', 'es', 'organización', '<div>persona o grupo de personas que tienen sus propias funciones y responsabilidades, autoridades y relaciones para el logro de sus objetivos (3.2.5).</div><div>Nota 1 a la entrada: El concepto de organización incluye, entre otros, un trabajador independiente, compañía, corporación, firma, empresa, autoridad, sociedad, organización benéfica o institución, o una parte o combinación de éstas, ya estén constituidas o no, públicas o privadas. </div>'),
    ('b140bd3b-7631-4887-b56e-066f8779b2df', '4010f7d7-9635-44b3-942c-4d974b01401f', 'en', 'top management', '<div>person or group of people who directs and controls an organization (3.1.4) at the highest level</div><div>Note 1 to entry: Top management has the power to delegate authority and provide resources within the organization.</div><div>Note 2 to entry: If the scope of the management system (3.1.1) covers only par</div>'),
    ('9c409c2c-7cea-4220-9d3c-1dcc9a79d0c8', '4010f7d7-9635-44b3-942c-4d974b01401f', 'es', 'alta dirección', '<div>persona o grupo de personas que dirige y controla una organización (3.1.4) al más alto nivel.</div><div>Nota 1 a la entrada: La alta dirección tiene el poder para delegar autoridad y proporcionar recursos dentro de la organización.</div><div>Nota 2 a la entrada: Si el alcance del sistema de gestión (3.1.1) comprende solo una parte de una organización, entonces “alta dirección” se refiere a quienes dirigen y controlan esa parte de la organización. </div>'),
    ('2af780f9-6dc7-4eb5-aec6-9f5513ca18dd', '3d1331b5-2731-4639-be0c-3215d8045cad', 'en', 'interested party', '<div>person or organization (3.1.4) that can affect, be affected by, or perceive itself to be affected by a decision or activity</div><div>EXAMPLE: Customers, communities, suppliers, regulators, non-governmental organizations, investors and employees.</div><div>Note 1 to entry: To “perceive itself to be affected” means the perception has been made known to the organization.</div>'),
    ('45f7ab7a-8aa1-4096-890c-a08a16ca1d96', '3d1331b5-2731-4639-be0c-3215d8045cad', 'es', 'parte interesada', '<div>persona u organización (3.1.4) que puede afectar, verse afectada, o percibirse como afectada por una decisión o actividad.</div><div>EJEMPLO: Clientes, comunidades, proveedores, entes reguladores, organizaciones no gubernamentales, inversionistas, empleados.</div><div>Nota 1 a la entrada: “Percibirse como afectado” significa que esta percepción se ha dado a conocer a la organización.</div>'),
    ('b3d63f48-023c-4abc-9ea2-d3509a57109c', '3c133022-208c-48fe-bc62-30f8d7045b1a', 'en', 'Terms related to planning', '<div>{clause_3.2.1}</div><div>{clause_3.2.2}</div><div>{clause_3.2.3}</div><div>{clause_3.2.4}</div><div>{clause_3.2.5}</div><div>{clause_3.2.6}</div><div>{clause_3.2.7}</div><div>{clause_3.2.8}</div><div>{clause_3.2.9}</div><div>{clause_3.2.10}</div><div>{clause_3.2.11}</div>'),
    ('a0d6215f-a527-44bb-a733-212b8f56ff4b', '3c133022-208c-48fe-bc62-30f8d7045b1a', 'es', 'Términos relacionados con planificación', '<div>{clause_3.2.1}</div><div>{clause_3.2.2}</div><div>{clause_3.2.3}</div><div>{clause_3.2.4}</div><div>{clause_3.2.5}</div><div>{clause_3.2.6}</div><div>{clause_3.2.7}</div><div>{clause_3.2.8}</div><div>{clause_3.2.9}</div><div>{clause_3.2.10}</div><div>{clause_3.2.11}</div>'),
    ('e2feeeb3-d667-4d3f-b47f-da07b8ff86c7', '3b132e8f-b1f0-450f-9198-3b4fd6045987', 'en', 'environment', '<div>surroundings in which an organization (3.1.4) operates, including air, water, land, natural resources, flora, fauna, humans and their interrelationships</div><div>Note 1 to entry: Surroundings can extend from within an organization to the local, regional and global system.</div><div>Note 2 to entry: Surroundings can be described in terms of biodiversity, ecosystems, climate or other characteristics</div>'),
    ('fdff1934-8e5b-4e68-9981-eff49bff5920', '3b132e8f-b1f0-450f-9198-3b4fd6045987', 'es', 'medio ambiente', '<div>entorno en el cual una organización (3.1.4) opera, incluidos el aire, el agua, el suelo, los recursos naturales, la flora, la fauna, los seres humanos y sus interrelaciones.</div><div>Nota 1 a la entrada: El entorno puede abarcar desde el interior de una organización hasta el sistema local, regional y global.</div><div>Nota 2 a la entrada: El entorno se puede describir en términos de biodiversidad, ecosistemas, clima u otras características.</div>'),
    ('b274618a-5c86-4016-acb0-663a0ec9415e', '3a132cfc-29c7-44c4-b480-5742d50457f4', 'en', 'environmental aspect', '<div>element of an organization’s (3.1.4) activities or products or services that interacts or can interact with the environment (3.2.1)</div><div>Note 1 to entry: An environmental aspect can cause (an) environmental impact(s) (3.2.4). A significant environmental aspect is one that has or can have one or more significant environmental impact(s).</div><div>Note 2 to entry: Significant environmental aspects are determined by the organization applying one or more criteria</div>'),
    ('b7746969-3fad-4e35-b65a-2e251bc955d5', '3a132cfc-29c7-44c4-b480-5742d50457f4', 'es', 'aspecto ambiental', '<div>elemento de las actividades, productos o servicios de una organización (3.1.4) que interactúa o puede interactuar con el medio ambiente (3.2.1).</div><div>Nota 1 a la entrada: Un aspecto ambiental puede causar uno o varios impactos ambientales (3.2.4). Un aspecto ambiental significativo es aquel que tiene o puede tener uno o más impactos ambientales significativos.</div><div>Nota 2 a la entrada: La organización determina los aspectos ambientales significativos mediante la aplicación de uno o más criterios.</div>'),
    ('bca5b2f5-7c6a-4e01-aef3-f5694e234261', '39132b69-00d9-4e15-8d27-15a9d4045661', 'en', 'environmental condition', '<div>state or characteristic of the environment (3.2.1) as determined at a certain point in time</div>'),
    ('afa59e7e-b82a-44da-a09c-a08639232152', '39132b69-00d9-4e15-8d27-15a9d4045661', 'es', 'condición ambiental', '<div>estado o característica del medio ambiente (3.2.1), determinado en un punto específico en el tiempo.</div>'),
    ('990686d4-48d4-4938-abe9-d394b488f850', '381329d6-ad27-44ea-af3d-19acd30454ce', 'en', 'environmental impact', '<div>change to the environment (3.2.1), whether adverse or beneficial, wholly or partially resulting from an organization’s (3.1.4) environmental aspects (3.2.2)</div>'),
    ('7e065c53-4d5b-45ef-a537-3327b188f397', '381329d6-ad27-44ea-af3d-19acd30454ce', 'es', 'impacto ambiental', '<div>cambio en el medio ambiente (3.2.1), ya sea adverso o beneficioso, como resultado total o parcial de los aspectos ambientales (3.2.2) de una organización (3.1.4).</div>'),
    ('984c9b5f-a2d3-4e6b-b7bc-2b2b7984559b', '37132843-b13f-443b-bfa0-c233d204533b', 'en', 'objective', '<div>result to be achieved</div><div>Note 1 to entry: An objective can be strategic, tactical, or operational.</div><div>Note 2 to entry: Objectives can relate to different disciplines (such as financial, health and safety, and environmental goals) and can apply at different levels (such as strategic, organization-wide, project, product, service and process (3.3.5)).</div><div>Note 3 to entry: An objective can be expressed in other ways, e.g. as an intended outcome, a purpose, an operational criterion, as</div>'),
    ('ab4cb948-be3d-478c-af2b-dd506484348c', '37132843-b13f-443b-bfa0-c233d204533b', 'es', '', '<div>resultado a lograr.</div><div>Nota 1 a la entrada: Un objetivo puede ser estratégico, táctico u operacional.</div><div>Nota 2 a la entrada: Los objetivos pueden referirse a diferentes disciplinas (tales como, financieras, de salud y seguridad y ambientales) y se pueden aplicar en diferentes niveles (tales como estratégicos, para toda la organización, para proyectos, productos, servicios y procesos (3.3.5)).</div><div>Nota 3 a la entrada: Un objetivo se puede expresar de otras maneras, por ejemplo, como un resultado previsto, un propósito, un criterio operacional, un objetivo ambiental (3.2.6), o mediante el uso de otros términos con un significado similar (por ejemplo, finalidad o meta). </div>'),
    ('b842ac36-4652-4f12-be08-d2fe271e90d2', '361326b0-a663-4780-a92a-e096d10451a8', 'en', 'environmental objective', '<div>objective (3.2.5) set by the organization (3.1.4) consistent with its environmental policy (3.1.3)</div>'),
    ('b542a77d-3628-4c09-8c3a-e4d13c1eb1e1', '361326b0-a663-4780-a92a-e096d10451a8', 'es', 'objetivo ambiental', '<div>objetivo (3.2.5) establecido por la organización (3.1.4), coherente con su política ambiental (3.1.3).</div>'),
    ('521bcfb1-973a-472d-86f6-084d78acc0e5', '45133e4d-9d9d-45a1-a033-d0cdd0045015', 'en', 'prevention of pollution', '<div>use of processes (3.3.5), practices, techniques, materials, products, services or energy to avoid, reduce or control (separately or in combination) the creation, emission or discharge of any type of pollutant or waste, in order to reduce adverse environmental impacts (3.2.4)</div><div>Note 1 to entry: Prevention of pollution can include source reduction or elimination; process, product or service changes; efficient use of resources; material and energy substitution; reuse; recovery; recycling, reclamation; or treatment</div>'),
    ('5d1be102-afe6-413e-a507-02528bacdece', '45133e4d-9d9d-45a1-a033-d0cdd0045015', 'es', 'prevención de la contaminación', '<div>utilización de procesos (3.3.5), prácticas, técnicas, materiales, productos, servicios o energía para evitar, reducir o controlar (en forma separada o en combinación) la generación, emisión o descarga de cualquier tipo de contaminante o residuo, con el fin de reducir impactos ambientales (3.2.4) adversos.</div><div>Nota 1 a la entrada: La prevención de la contaminación puede incluir la reducción o la eliminación en la fuente; cambios en el proceso, producto o servicio; uso eficiente de recursos, sustitución de materiales y energía; reutilización; recuperación; reciclaje, regeneración o tratamiento. </div>'),
    ('b91f5660-eb0c-4a34-aca5-eb28e1b3ef44', '44133cba-c035-45a6-87aa-f510cf044e82', 'en', 'requirement', '<div>need or expectation that is stated, generally implied or obligatory&nbsp;</div><div>Note 1 to entry: “Generally implied” means that it is custom or common practice for the organization (3.1.4) and interested parties (3.1.6) that the need or expectation under consideration is implied.</div><div>Note 2 to entry: A specified requirement is one that is stated, for example in documented information (3.3.2).</div><div>Note 3 to entry: Requirements other than legal requirements become obligatory when the organization decides to comply with them.</div>'),
    ('d61f8407-840c-4de3-97ab-7113e6b3f723', '44133cba-c035-45a6-87aa-f510cf044e82', 'es', 'requisito', '<div>necesidad o expectativa establecida, generalmente implícita u obligatoria.</div><div>Nota 1 a la entrada: “Generalmente implícita” significa que es habitual o práctica común para la organización (3.1.4) y las partes interesadas (3.1.6), que la necesidad o expectativa bajo consideración está implícita.</div><div>Nota 2 a la entrada: Un requisito especificado es el que está declarado, por ejemplo, en información documentada (3.3.2).</div><div>Nota 3 a la entrada: Los requisitos diferentes de los legales se convierten en obligatorios cuando la organización decide cumplirlos.</div>'),
    ('3f88e520-c1b5-4040-b9cf-c3e8af1d1d74', '431579be-aed2-4ef2-b855-8550be067256', 'en', 'compliance obligations (preferred term)', '<div>legal requirements and other requirements (admitted term)</div><div>legal requirements (3.2.8) that an organization (3.1.4) has to comply with and other requirements that an organization has to or chooses to comply with</div><div>Note 1 to entry: Compliance obligations are related to the environmental management system (3.1.2).</div><div>Note 2 to entry: Compliance obligations can arise from mandatory requirements, such as applicable laws and regulations, or voluntary commitments, such as organizational and industry standards, contractual relationships, codes of practice and agreements with community groups or non-governmental organizations.</div>'),
    ('5c8912c7-bafb-46a7-90d1-83d3941cf2f3', '431579be-aed2-4ef2-b855-8550be067256', 'es', 'requisitos legales y otros requisitos', '<div>requisitos (3.2.8) legales que una organización (3.1.4) debe cumplir y otros requisitos que una organización decide cumplir.</div><div>Nota 1 a la entrada: Los requisitos legales y otros requisitos están relacionados con el sistema de gestión ambiental (3.1.2).</div><div>Nota 2 a la entrada: Los requisitos legales y otros requisitos pueden surgir de requisitos obligatorios, tales como las leyes y reglamentaciones aplicables, o de compromisos voluntarios, tales como las normas de organizaciones o de la industria, relaciones contractuales, códigos de buenas prácticas y acuerdos con grupos de la comunidad u organizaciones no gubernamentales. </div>'),
    ('d60af571-366f-4629-ac20-fd0d48905815', '44157b51-0899-44bd-af82-830dbf0673e9', 'en', 'risk', '<div>effect of uncertainty</div><div>Note 1 to entry: An effect is a deviation from the expected — positive or negative.</div><div>Note 2 to entry: Uncertainty is the state, even partial, of deficiency of information related to, understanding or knowledge of, an event, its consequence, or likelihood.</div><div>Note 3 to entry: Risk is often characterized by reference to potential “events” (as defined in ISO Guide 73:2009, 3.5.1.3) and “consequences” (as defined in ISO Guide 73:2009, 3.6.1.3), or a combination of these.</div><div>Note 4 to entry: Risk is often expressed in terms of a combination of the consequences of an event (including changes in circumstances) and the associated “likelihood” (as defined in ISO Guide 73:2009, 3.6.1.1) of occurrence.</div>'),
    ('e10b06c2-441e-4032-b3dc-27123b90439e', '44157b51-0899-44bd-af82-830dbf0673e9', 'es', 'riesgo', '<div>efecto de la incertidumbre.</div><div>Nota 1 a la entrada: Un efecto es una desviación de lo esperado, ya sea positivo o negativo.</div><div>Nota 2 a la entrada: Incertidumbre es el estado, incluso parcial, de deficiencia de información relacionada con la comprensión o conocimiento de un evento, su consecuencia o su probabilidad.</div><div>Nota 3 a la entrada: Con frecuencia el riesgo se caracteriza por referencia a “eventos” potenciales (como se definen en la Guía ISO 73:2009, 3.5.1.3) y “consecuencias” (según se definen en la Guía ISO 73:2009, 3.6.1.3), o a una combinación de estos.</div><div>Nota 4 a la entrada: Con frecuencia el riesgo se expresa en términos de una combinación de las consecuencias de un evento (incluidos cambios en las circunstancias) y la “”probabilidad” (como se define en la Guía ISO 73:2009, 3.6.1.1) asociada de que ocurra.</div>'),
    ('f17f7ea2-60b1-4f7a-9552-88f241b2e856', '41157698-c80f-46e8-ab95-895abc066f30', 'en', 'risks and opportunities', '<div>potential adverse effects (threats) and potential beneficial effects (opportunities)</div>'),
    ('e67f6d51-24f2-4ba1-b606-fe6d3eb2e39d', '41157698-c80f-46e8-ab95-895abc066f30', 'es', 'riesgos y oportunidades', '<div>efectos potenciales adversos (amenazas) y efectos potenciales beneficiosos (oportunidades).</div>'),
    ('0209d96b-a63a-4e93-ae6a-963fae64c4ff', '4215782b-505f-46a3-9ead-c4c7bd0670c3', 'en', 'Terms related to support and operation', '<div>{clause_3.3.1}</div><div>{clause_3.3.2}</div><div>{clause_3.3.3}</div><div>{clause_3.3.4}</div><div>{clause_3.3.5}</div>'),
    ('0d09eabc-b60f-4944-8bc3-91bcc164e2e8', '4215782b-505f-46a3-9ead-c4c7bd0670c3', 'es', 'Términos relacionados con soporte y operación', '<div>{clause_3.3.1}</div><div>{clause_3.3.2}</div><div>{clause_3.3.3}</div><div>{clause_3.3.4}</div><div>{clause_3.3.5}</div>'),
    ('24b799ac-c55e-4924-8b1f-9accc9ee68e8', '4715800a-2236-4306-93b5-31e4c20678a2', 'en', 'competence', '<div>ability to apply knowledge and skills to achieve intended results</div>'),
    ('39b7babb-d150-4c73-a351-836fb6ee4aff', '4715800a-2236-4306-93b5-31e4c20678a2', 'es', 'competencia', '<div>capacidad para aplicar conocimientos y habilidades con el fin de lograr los resultados previstos.</div>'),
    ('dbb09dad-9249-409d-8b7a-4461410e1799', '4815819d-d031-4281-a366-4041c3067a35', 'en', 'documented information', '<div>information required to be controlled and maintained by an organization (3.1.4) and the medium on which it is contained</div><div>Note 1 to entry: Documented information can be in any format and media, and from any source.</div><div>Note 2 to entry: Documented information can refer to:</div><div>— the environmental management system (3.1.2), including related processes (3.3.5);</div><div>—&nbsp;&nbsp;&nbsp;information created in order for the organization to operate (can be referred to as documentation);</div><div>— evidence of results achieved (can be referred to as records).</div>'),
    ('beb07006-053b-4c0e-aee8-a02e5c0e421a', '4815819d-d031-4281-a366-4041c3067a35', 'es', 'información documentada', '<div>información que una organización (3.1.4) tiene que controlar y mantener, y el medio que la contiene.</div><div>Nota 1 a la entrada: La información documentada puede estar en cualquier formato y medio, y puede provenir de cualquier fuente.</div><div>Nota 2 a la entrada: La información documentada puede hacer referencia a:</div><div>— el sistema de gestión ambiental (3.1.2), incluidos los procesos (3.3.5) relacionados;</div><div>— la información generada para que la organización opere (documentación);</div><div>— la evidencia de los resultados alcanzados (registros).</div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('d74d96ee-2015-46fe-9f7b-12963be630aa', '45157ce4-2ad4-4e0c-a09f-350ec006757c', 'en', 'life cycle', '<div>consecutive and interlinked stages of a product (or service) system, from raw material acquisition or generation from natural resources to final disposal</div><div>Note 1 to entry: The life cycle stages include acquisition of raw materials, design, production, transportation/ delivery, use, end-of-life treatment and final disposal.</div><div>[SOURCE: ISO 14044:2006, 3.1, modified ― The words “(or service)” have been added to the definition and Note 1 to entry has been added.]</div>'),
    ('c44d7905-ee1c-47ed-9df2-b2d940e63889', '45157ce4-2ad4-4e0c-a09f-350ec006757c', 'es', 'ciclo de vida', '<div>etapas consecutivas e interrelacionadas de un sistema de producto (o servicio), desde la adquisición de materia prima o su generación a partir de recursos naturales hasta la disposición final.</div><div>Nota 1 a la entrada: Las etapas del ciclo de vida incluyen la adquisición de materias primas, el diseño, la producción, el transporte/entrega, el uso, el tratamiento al finalizar la vida y la disposición final.</div><div>[FUENTE: ISO 14044:2006, 3.1, modificada. Las palabras “(o servicio)” se han agregado a la definición y se ha agregado la Nota 1 a la entrada.]</div>'),
    ('b7591917-d61f-43a7-86fe-b3c36ee993d3', '46157e77-ba4e-4c77-9def-738bc106770f', 'en', 'outsource (verb)', '<div>make an arrangement where an external organization (3.1.4) performs part of an organization’s function or process (3.3.5)</div><div>Note 1 to entry: An external organization is outside the scope of the management system (3.1.1), although the outsourced function or process is within the scope.</div>'),
    ('ba591dd0-dcd9-4d40-bafa-ccb889e9be54', '46157e77-ba4e-4c77-9def-738bc106770f', 'es', 'contratar externamente', '<div>establecer un acuerdo mediante el cual una organización (3.1.4) externa realiza parte de una función o proceso (3.3.5) de una organización.</div><div>Nota 1 a la entrada: Una organización externa está fuera del alcance del sistema de gestión (3.1.1) aunque la función o proceso contratado externamente forme parte del alcance. </div>'),
    ('37c56508-b90d-42a8-a9e3-b9102a3a430c', '3b156d26-f5dc-4d4a-a20f-0938c6067eee', 'en', 'process', '<div>set of interrelated or interacting activities which transforms inputs into outputs</div><div>Note 1 to entry: A process can be documented or not.</div>'),
    ('24c5471f-011b-447f-a646-02eb3f3a641b', '3b156d26-f5dc-4d4a-a20f-0938c6067eee', 'es', 'proceso', '<div>conjunto de actividades interrelacionadas o que interactúan, que transforman las entradas en salidas.</div><div>Nota 1 a la entrada: Un proceso puede estar documentado o no. </div>'),
    ('b15f7cb9-9e13-4a71-995b-e015e133470d', '3c156eb9-336e-4df5-a614-5855c7068081', 'en', 'Terms related to performance evaluation and improvement', '<div>{clause_3.4.1}</div><div>{clause_3.4.2}</div><div>{clause_3.4.3}</div><div>{clause_3.4.4}</div><div>{clause_3.4.5}</div><div>{clause_3.4.6}</div><div>{clause_3.4.7}</div><div>{clause_3.4.8}</div><div>{clause_3.4.9}</div><div>{clause_3.4.10}</div><div>{clause_3.4.11}</div>'),
    ('cc5fa73a-8208-48ea-9b1f-b54ac4331966', '3c156eb9-336e-4df5-a614-5855c7068081', 'es', 'Términos relacionados con la evaluación del desempeño y con la mejora', '<div>{clause_3.4.1}</div><div>{clause_3.4.2}</div><div>{clause_3.4.3}</div><div>{clause_3.4.4}</div><div>{clause_3.4.5}</div><div>{clause_3.4.6}</div><div>{clause_3.4.7}</div><div>{clause_3.4.8}</div><div>{clause_3.4.9}</div><div>{clause_3.4.10}</div><div>{clause_3.4.11}</div>'),
    ('503a6b07-00a9-4ed7-8715-b013a06dd4bb', 'c9188b47-be08-42f3-8e25-23fbc408ba5f', 'en', 'audit', '<div>systematic, independent and documented process (3.3.5) for obtaining audit evidence and evaluating it objectively to determine the extent to which the audit criteria are fulfilled</div><div>Note 1 to entry: An internal audit is conducted by the organization (3.1.4) itself, or by an external party on its behalf.</div><div>Note 2 to entry: An audit can be a combined audit (combining two or more disciplines).</div><div>Note 3 to entry: Independence can be demonstrated by the freedom from responsibility for the activity being audited or freedom from bias and conflict of interest.</div><div>Note 4 to entry: “Audit evidence” consists of records, statements of fact or other information which are relevant to the audit criteria and are verifiable; and “audit criteria” are the set of policies, procedures or requirements (3.2.8) used as a reference against which audit evidence is compared, as defined in ISO 19011:2011, 3.3 and 3.2 respectively</div>'),
    ('333a3d60-6382-4c10-9c10-2a288b6db3ac', 'c9188b47-be08-42f3-8e25-23fbc408ba5f', 'es', 'auditoría', '<div>proceso (3.3.5) sistemático, independiente y documentado para obtener las evidencias de auditoría y evaluarlas de manera objetiva con el fin de determinar el grado en el que se cumplen los criterios de auditoría.</div><div>Nota 1 a la entrada: Una auditoría interna la realiza la propia organización (3.1.4) o una parte externa en su nombre.</div><div>Nota 2 a la entrada: Una auditoría puede ser combinada (combinando dos o más disciplinas).</div><div>Nota 3 a la entrada: La independencia se puede demostrar por la ausencia de responsabilidad con relación a la actividad que se audita, o ausencia de sesgo y conflicto de intereses.</div><div>Nota 4 a la entrada: La “evidencia de auditoría” consiste en registros, declaraciones de hechos y demás información pertinente a los criterios de auditoría, que son verificables; los “criterios de auditoría” son el conjunto de políticas, procedimientos o requisitos (3.2.8) usados como referencia, frente a los cuales se compara la evidencia de auditoría, como se define en la Norma ISO 19011:2011, apartados 3.3 y 3.2 respectivamente.</div>'),
    ('a389bc9e-c07b-492e-9ac6-87a6508278f2', 'c81889b4-35b9-4338-9ef4-15bec308b8cc', 'en', 'conformity', '<div>fulfilment of a requirement (3.2.8)</div>'),
    ('b089d115-4a5d-443d-94e4-ec0965829a01', 'c81889b4-35b9-4338-9ef4-15bec308b8cc', 'es', 'conformidad', '<div>cumplimiento de un requisito (3.2.8).</div>'),
    ('a88a941d-8e8c-4dcd-91c1-2971750cc181', 'cb188e6d-60c1-494d-973f-f631c608bd85', 'en', 'nonconformity', '<div>non-fulfilment of a requirement (3.2.8)</div><div>Note 1 to entry: Nonconformity relates to requirements in this International Standard and additional environmental management system (3.1.2) requirements that an organization (3.1.4) establishes for itself.</div>'),
    ('ab8a98d6-c301-48de-9bc9-651e600ca072', 'cb188e6d-60c1-494d-973f-f631c608bd85', 'es', 'no conformidad', '<div>incumplimiento de un requisito (3.2.8).</div><div>Nota 1 a la entrada: La no conformidad se relaciona con los requisitos de esta Norma Internacional y con los requisitos adicionales delsistema de gestión ambiental(3.1.2) que una organización (3.1.4) establece para sí misma.</div>'),
    ('3191f4dc-28d3-4c54-be76-295c4ecc1cf0', 'ca188cda-1c7d-4e42-ba39-7a54c508bbf2', 'en', 'corrective action', '<div>action to eliminate the cause of a nonconformity (3.4.3) and to prevent recurrence</div><div>Note 1 to entry: There can be more than one cause for a nonconformity.</div>'),
    ('2691e38b-d578-4f83-b77f-54df4bcc1837', 'ca188cda-1c7d-4e42-ba39-7a54c508bbf2', 'es', 'acción correctiva', '<div>acción para eliminar la causa de una no conformidad (3.4.3) y evitar que vuelva a ocurrir.</div><div>Nota 1 a la entrada: Puede haber más de una causa para una no conformidad.</div>'),
    ('0e44d0db-35fb-4103-af5f-380f55bd1467', 'c51884fb-4146-40c7-b5cf-8b77c008b413', 'en', 'continual improvement', '<div>recurring activity to enhance performance (3.4.10)</div><div>Note 1 to entry: Enhancing performance relates to the use of the environmental management system (3.1.2) to enhance environmental performance (3.4.11) consistent with the organization’s (3.1.4) environmental policy (3.1.3).</div><div>Note 2 to entry: The activity need not take place in all areas simultaneously, or without interruption.</div>'),
    ('f944afcc-8956-4dd4-a715-786c38bce6c0', 'c51884fb-4146-40c7-b5cf-8b77c008b413', 'es', 'mejora continua', '<div>actividad recurrente para mejorar el desempeño (3.4.10).</div><div>Nota 1 a la entrada: La mejora del desempeño se relaciona con el uso del sistema de gestión ambiental (3.1.2) para mejorar el desempeño ambiental(3.4.11), en coherencia con la política ambiental(3.1.3) de la organización (3.1.4).</div><div>Nota 2 a la entrada:No es necesario que la actividad ocurra simultáneamente en todas las áreas, o sin interrupción.</div>'),
    ('be5b0812-c066-40aa-aef4-184235b2c07e', 'c4188368-991d-4e1c-a6b1-d78abf08b280', 'en', 'effectiveness', '<div>extent to which planned activities are realized and planned results achieved</div>'),
    ('d35b2921-deea-4831-a034-8edd42b2d4f5', 'c4188368-991d-4e1c-a6b1-d78abf08b280', 'es', 'eficacia', '<div>grado en el que se realizan las actividades planificadas y se logran los resultados planificados.</div>'),
    ('e2e550a1-e052-4ad9-9e51-825d3ab397fd', 'c7188821-3ddb-4ed1-a2be-21fdc208b739', 'en', 'indicator', '<div>indicator measurable representation of the condition or status of operations, management or conditions</div><div>[SOURCE: ISO 14031:2013, 3.15]</div>'),
    ('cde52f92-4a21-4882-ad11-0bc23db39cb6', 'c7188821-3ddb-4ed1-a2be-21fdc208b739', 'es', 'indicador', '<div>representación medible de la condición o el estado de las operaciones, la gestión, o las condiciones</div><div>[FUENTE: ISO 14031:2013, 3.15]</div>'),
    ('4bc3dc90-19ee-4db0-bb81-09f8349a353c', 'c618868e-8fe0-4f56-8b0a-0640c108b5a6', 'en', 'monitoring', '<div>determining the status of a system, a process (3.3.5) or an activity</div><div>Note 1 to entry: To determine the status, there might be a need to check, supervise or critically observe</div>'),
    ('48c3d7d7-a042-4477-b156-9303299a23eb', 'c618868e-8fe0-4f56-8b0a-0640c108b5a6', 'es', 'seguimiento', '<div>determinación del estado de un sistema, un proceso (3.3.5) o una actividad.</div><div>Nota 1 a la entrada: Para determinar el estado puede ser necesario verificar, supervisar u observar de forma crítica.</div>'),
    ('29161c4f-a46d-445f-b516-c33b07cae5c3', 'c1187eaf-517e-406b-aea7-caa3cc08c6f7', 'en', 'measurement', '<div>process (3.3.5) to determine a value</div>'),
    ('1c1607d8-5c61-4588-bc44-490002cadde4', 'c1187eaf-517e-406b-aea7-caa3cc08c6f7', 'es', 'medición', '<div>proceso (3.3.5) para determinar un valor.</div>'),
    ('0ae6cda6-edcb-4236-b772-0a4e48c08bda', 'c0187d1c-760e-4130-8adc-8906cb08c564', 'en', 'performance', '<div>measurable result</div><div>Note 1 to entry: Performance can relate either to quantitative or qualitative findings.</div><div>Note 2 to entry: Performance can relate to the management of activities, processes (3.3.5), products (including services), systems or organizations (3.1.4).</div>'),
    ('27e6fb4d-e712-4bd5-9cc3-05812dc06159', 'c0187d1c-760e-4130-8adc-8906cb08c564', 'es', 'desempeño', '<div>resultado medible.</div><div>Nota 1 a la entrada: El desempeño se puede relacionar con hallazgos cuantitativos o cualitativos.</div><div>Nota 2 a la entrada: El desempeño se puede relacionar con la gestión de actividades, procesos (3.3.5), productos (incluidos servicios), sistemas u organizaciones (3.1.4).</div>'),
    ('6cbd80be-aa50-45aa-8e8e-69467b69a14a', 'bf073268-0941-436c-8781-da1eb9f76180', 'en', 'environmental performance', '<div>performance (3.4.10) related to the management of environmental aspects (3.2.2)</div><div>Note 1 to entry: For an environmental management system (3.1.2), results can be measured against the organization’s (3.1.4) environmental policy (3.1.3), environmental objectives (3.2.6) or other criteria, using indicators (3.4.7).</div>'),
    ('79bd9535-c8d4-4d31-94b2-59298069a929', 'bf073268-0941-436c-8781-da1eb9f76180', 'es', 'desempeño ambiental', '<div>desempeño (3.4.10) relacionado con la gestión de aspectos ambientales (3.2.2).</div><div>Nota 1 a la entrada: En el contexto de un sistema de gestión ambiental (3.1.2), los resultados se pueden medir con respecto a la política ambiental (3.1.3) de la organización (3.1.4), sus objetivos ambientales (3.2.6) u otros criterios, mediante el uso de indicadores (3.4.7).</div>'),
    ('8cc7d4a7-1fe5-4603-8f40-2433abf29b73', 'c00733fb-996e-4557-a51a-395bbaf76313', 'en', 'Context of the organization', '<div>{clause_4.1}</div><div>{clause_4.2}</div><div>{clause_4.3}</div><div>{clause_4.4}</div>'),
    ('6fc7a700-733f-42d4-bc45-b0c8c6f2c5f4', 'c00733fb-996e-4557-a51a-395bbaf76313', 'es', 'Contexto de la organización', '<div>{clause_4.1}</div><div>{clause_4.2}</div><div>{clause_4.3}</div><div>{clause_4.4}</div>'),
    ('6e1f5e7c-03d7-42b0-8676-36fc7a511608', 'c107358e-ea84-4fe6-a2e4-9534bbf764a6', 'en', 'Understanding the organization and its context', '<div>The organization shall determine external and internal issues that are relevant to its purpose and that affect its ability to achieve the intended outcomes of its environmental management system. Such issues shall include environmental conditions being affected by or capable of affecting the organization.</div>'),
    ('631f4d2b-8a2c-4977-af04-227f6750f81f', 'c107358e-ea84-4fe6-a2e4-9534bbf764a6', 'es', 'Comprensión de la organización y de su contexto', '<div>La organización debe determinar las cuestiones externas e internas que son pertinentes para su propósito y que afectan a su capacidad para lograr los resultados previstos de su sistema de gestión ambiental. Estas cuestiones incluyen las condiciones ambientales capaces de afectar o de verse afectadas por la organización.</div>'),
    ('71bfeb3d-ca3c-4fd9-aaa4-8a11f3eb2db9', 'c2073721-ac24-4ee1-adcd-d191bcf76639', 'en', 'Understanding the needs and expectations of interested parties', '<div>The organization shall determine:</div><div>{clause_4.2.a}</div><div>{clause_4.2.b}</div><div>{clause_4.2.c}</div>'),
    ('74bfeff6-340b-4d82-8e40-8c3e0eeb583a', 'c2073721-ac24-4ee1-adcd-d191bcf76639', 'es', 'Comprensión de las necesidades y expectativas de las partes interesadas', '<div>La organización debe determinar:</div><div>{clause_4.2.a}</div><div>{clause_4.2.b}</div><div>{clause_4.2.c}</div>'),
    ('878ecc32-aa65-4e2e-87dd-29628137ebf6', 'c30738b4-a400-4048-84bb-a96abdf767cc', 'en', '', '<div>a) the interested parties that are relevant to the environmental management system;</div>'),
    ('9c8eed41-3447-493d-ad3e-67fd7e37e73d', 'c30738b4-a400-4048-84bb-a96abdf767cc', 'es', '', '<div>a) las partes interesadas que son pertinentes al sistema de gestión ambiental;</div>'),
    ('d9f490fb-ea93-43d7-83b9-e42f5ec7721f', 'c4073a47-2c52-4303-82f0-42d7bef7695f', 'en', '', '<div>b) the relevant needs and expectations (i.e. requirements) of these interested parties;</div>'),
    ('c4f46fec-4d6c-4110-b717-638c71c79008', 'c4073a47-2c52-4303-82f0-42d7bef7695f', 'es', '', '<div>b) las necesidades y expectativas pertinentes (es decir, requisitos) de estas partes interesadas;</div>'),
    ('88514630-12bc-4154-aea5-d1985f7fca94', 'c5073bda-7720-4bd2-b95b-9520bff76af2', 'en', '', '<div>c) which of these needs and expectations become its compliance obligations.</div>'),
    ('85514177-bf62-4483-beeb-a2a3447fa013', 'c5073bda-7720-4bd2-b95b-9520bff76af2', 'es', '', '<div>c) cuáles de estas necesidades y expectativas se convierten en requisitos legales y otros requisitos. </div>'),
    ('ac1914c1-7875-42cd-a076-ec7d85995fb5', 'c6073d6d-ea32-439d-9df3-ff5dc0f76c85', 'en', 'Determining the scope of the environmental management system', '<div>The organization shall determine the boundaries and applicability of the environmental management system to establish its scope.</div><div>When determining this scope, the organization shall consider:</div><div>{clause_4.3.a}</div><div>{clause_4.3.b}</div><div>{clause_4.3.c}</div><div>{clause_4.3.d}</div><div>{clause_4.3.e}</div><div>Once the scope is defined, all activities, products and services of the organization within that scope need to be included in the environmental management system.</div><div>The scope shall be maintained as documented information and be available to interested parties.</div>'),
    ('9718f3b2-acea-4dde-bb15-ade278994b3e', 'c6073d6d-ea32-439d-9df3-ff5dc0f76c85', 'es', 'Determinación del alcance del sistema de gestión ambiental', '<div>La organización debe determinar los límites y la aplicabilidad del sistema de gestión ambiental para establecer su alcance.</div><div>Cuando se determina este alcance, la organización debe considerar:</div><div>{clause_4.3.a}</div><div>{clause_4.3.b}</div><div>{clause_4.3.c}</div><div>{clause_4.3.d}</div><div>{clause_4.3.e}</div><div>Una vez que se defina el alcance, se deben incluir en el sistema de gestión ambientaltodas las actividades, productos y servicios de la organización que estén dentro de este alcance.</div><div>El alcance se debe mantener como información documentada y debe estar disponible para las partes interesadas.</div>'),
    ('4775ca46-d7a0-4eb2-8bd5-4d6e340b2fa2', 'b70725d0-519c-4604-8d4a-22e6c1f76e18', 'en', '', '<div>a) the external and internal issues referred to in 4.1;</div>'),
    ('6475f7ed-c9f0-44a9-8e0e-6ba1290b1e51', 'b70725d0-519c-4604-8d4a-22e6c1f76e18', 'es', '', '<div>a) las cuestiones externas e internas a que se hace referencia en el apartado 4.1;</div>'),
    ('f249e06f-5ac2-4a8b-83b9-aa5b44958a6b', 'b8072763-c079-414f-9bf9-a103c2f76fab', 'en', '', '<div>b) the compliance obligations referred to in 4.2;</div>'),
    ('e549cbf8-762c-43ac-9421-d0204f959bbc', 'b8072763-c079-414f-9bf9-a103c2f76fab', 'es', '', '<div>b) los requisitos legales y otros requisitos a que se hace referencia en el apartado 4.2; </div>'),
    ('7dfae2ad-30f7-46c9-a8fd-11618cce12a9', 'c5097a71-7f85-4fa5-9c5f-15413ffa7309', 'en', '', '<div>c) its organizational units, functions and physical boundaries;</div>'),
    ('60fab506-4120-49d2-8c6b-6d2e87ce0aca', 'c5097a71-7f85-4fa5-9c5f-15413ffa7309', 'es', '', '<div>c) las unidades, funciones y límites físicos de la organización;</div>'),
    ('c701deac-fd0b-46e0-a8a2-67cc468d3bb8', 'c40978de-45be-4c3a-8cae-06e43efa7176', 'en', '', '<div>d) its activities, products and services;</div>'),
    ('dc01ffbb-f653-4047-80d4-506f538d502f', 'c40978de-45be-4c3a-8cae-06e43efa7176', 'es', '', '<div>d) sus actividades, productos y servicios;</div>'),
    ('59a35e17-e40c-4133-a481-80c3b82f25e3', 'c309774b-2feb-45cb-96e8-488b3dfa6fe3', 'en', '', '<div>e) its authority and ability to exercise control and influence.</div>'),
    ('5ca362d0-f165-4fe4-987d-99b8b32f1e04', 'c309774b-2feb-45cb-96e8-488b3dfa6fe3', 'es', '', '<div>e) su autoridad y capacidad para ejercer control e influencia.</div>'),
    ('7997dbee-5b39-401a-bcfd-df9685c9937a', 'c20975b8-3e5c-4e10-9998-0a0e3cfa6e50', 'en', 'Environmental management system', '<div>To achieve the intended outcomes, including enhancing its environmental performance, the organization shall establish, implement, maintain and continually improve an environmental management system, including the processes needed and their interactions, in accordance with the requirements of this International Standard.</div><div>The organization shall consider the knowledge gained in 4.1 and 4.2 when establishing and maintaining the environmental management system.</div>'),
    ('6697be05-062d-4741-bb75-7fd96ac968f9', 'c20975b8-3e5c-4e10-9998-0a0e3cfa6e50', 'es', 'Sistema de gestión ambiental', '<div>Para lograr los resultados previstos, incluida la mejora de su desempeño ambiental, la organización debe establecer, implementar, mantener y mejorar continuamente un sistema de gestión ambiental, que incluya los procesos necesarios y sus interacciones, de acuerdo con los requisitos de esta Norma Internacional.</div><div>Al establecer y mantener el sistema de gestión ambiental, la organización debe considerar el conocimiento obtenido en los apartados 4.1 y 4.2. </div>'),
    ('78553a71-89a5-47bd-89a3-ca0d5274e925', 'c90980bd-a90a-4449-a87b-580d43fa7955', 'en', 'Leadership', '<div>{clause_5.1}</div><div>{clause_5.2}</div><div>{clause_5.3}</div>'),
    ('83554bc2-ffc3-4cae-915e-f4126575070e', 'c90980bd-a90a-4449-a87b-580d43fa7955', 'es', 'Liderazgo', '<div>{clause_5.1}</div><div>{clause_5.2}</div><div>{clause_5.3}</div>'),
    ('e1d32a20-69a8-45c4-9752-90e8b901ae84', 'c8097f2a-9f38-4a8e-b14e-5a5042fa77c2', 'en', 'Leadership and commitment', '<div>Top management shall demonstrate leadership and commitment with respect to the environmental management system by:</div><div>{clause_5.1.a}</div><div>{clause_5.1.b}</div><div>{clause_5.1.c}</div><div>{clause_5.1.d}</div><div>{clause_5.1.e}</div><div>{clause_5.1.f}</div><div>{clause_5.1.g}</div><div>{clause_5.1.h}</div><div>{clause_5.1.i}</div><div>NOTE: Reference to “business” in this International Standard can be interpreted broadly to mean those activities that are core to the purposes of the organization’s existence.</div>'),
    ('fed357c7-59d3-4b13-ae54-50d3be01b663', 'c8097f2a-9f38-4a8e-b14e-5a5042fa77c2', 'es', 'Liderazgo y compromiso', '<div>La alta dirección debe demostrar liderazgo y compromiso con respecto al sistema de gestión ambiental:</div><div>{clause_5.1.a}</div><div>{clause_5.1.b}</div><div>{clause_5.1.c}</div><div>{clause_5.1.d}</div><div>{clause_5.1.e}</div><div>{clause_5.1.f}</div><div>{clause_5.1.g}</div><div>{clause_5.1.h}</div><div>{clause_5.1.i}</div><div>NOTA: En esta Norma Internacional se puede interpretar el término “negocio” en su sentido más amplio, es decir, referido a aquellas actividades que son esenciales para los propósitos de la existencia de la organización.</div>'),
    ('a4541e6b-676f-4647-8bed-633f6ba1cd4f', 'c7097d97-309d-469f-97a6-99c741fa762f', 'en', '', '<div>a) taking accountability for the effectiveness of the environmental management system;</div>'),
    ('af542fbc-6e27-4ce0-a946-5ebc5ea1b8d8', 'c7097d97-309d-469f-97a6-99c741fa762f', 'es', '', '<div>a) asumiendo la responsabilidad y la rendición de cuentas con relación a la eficacia del sistema de gestión ambiental;</div>'),
    ('93c9c3a2-454c-451e-b2d5-55f24d727ea6', 'c6097c04-c1c0-4b54-a48e-5e5a40fa749c', 'en', '', '<div>b) ensuring that the environmental policy and environmental objectives are established and are compatible with the strategic direction and the context of the organization;</div>'),
    ('88c9b251-1353-460d-9389-cb6d6a72ac4d', 'c6097c04-c1c0-4b54-a48e-5e5a40fa749c', 'es', '', '<div>b) asegurándose de que se establezcan la política ambiental y los objetivos ambientales, y que éstos sean compatibles con la dirección estratégica y el contexto de la organización;</div>'),
    ('e557f3b5-1bbc-4a91-8f4f-8e29257101a1', 'bd096dd9-587b-43ad-b189-c9e947fa7fa1', 'en', '', '<div>c) ensuring the integration of the environmental management system requirements into the organization’s business processes;</div>'),
    ('d857df3e-1356-488a-892b-9e461070e092', 'bd096dd9-587b-43ad-b189-c9e947fa7fa1', 'es', '', '<div>c) asegurándose de la integración de los requisitos del sistema de gestión ambiental en los procesos de negocio de la organización;</div>'),
    ('bf3e5e94-db16-4448-9655-8a548e4f8d90', 'bc096c46-e4c9-4822-aecc-9eec46fa7e0e', 'en', '', '<div>d) ensuring that the resources needed for the environmental management system are available;</div>'),
    ('a43e3413-259e-4f1f-b3ce-3ce78b4f88d7', 'bc096c46-e4c9-4822-aecc-9eec46fa7e0e', 'es', '', '<div>d) asegurándose de que los recursos necesarios para el sistema de gestión ambiental estén disponibles;</div>'),
    ('f286d7c4-dec3-4df4-bd5b-1fa4123eb350', 'cb0bc27a-bd09-429e-b0bf-8f9c45fcbb12', 'en', '', '<div>e) communicating the importance of effective environmental management and of conforming to the environmental management system requirements;</div>'),
    ('f786dfa3-77c3-41a3-8aef-08d70f3eae97', 'cb0bc27a-bd09-429e-b0bf-8f9c45fcbb12', 'es', '', '<div>e) comunicando la importancia de una gestión ambiental eficaz y conforme con los requisitos del sistema de gestión ambiental;</div>'),
    ('897fa965-c2f6-42ed-9985-cab9abd8fd61', 'cc0bc40d-c3af-42d9-a16c-291946fcbca5', 'en', '', '<div>f) ensuring that the environmental management system achieves its intended outcomes;</div>'),
    ('9c7fc74e-f4ef-41fe-9a0d-517696d8dc52', 'cc0bc40d-c3af-42d9-a16c-291946fcbca5', 'es', '', '<div>f) asegurándose de que el sistema de gestión ambiental logre los resultados previstos;</div>'),
    ('847ed1e6-f269-424e-8066-998e84d44bd2', 'c90bbf54-dc64-46e4-b27d-06c643fcb7ec', 'en', '', '<div>g) directing and supporting persons to contribute to the effectiveness of the environmental management system;</div>'),
    ('a17eff8d-662c-44dd-853d-abc199d46ce1', 'c90bbf54-dc64-46e4-b27d-06c643fcb7ec', 'es', '', '<div>g) dirigiendo y apoyando a las personas, para contribuir a la eficacia del sistema de gestión ambiental;</div>'),
    ('a526f68f-49cf-4b77-80d6-e67bd73a109b', 'ca0bc0e7-4b42-452f-98f7-3f6344fcb97f', 'en', '', '<div>h) promoting continual improvement;</div>'),
    ('9826e218-c37a-44b0-b5f6-d240c239ef8c', 'ca0bc0e7-4b42-452f-98f7-3f6344fcb97f', 'es', '', '<div>h) promoviendo la mejora continua;</div>'),
    ('801264f8-f1c3-4ed0-b5c4-a220f80ccb9c', 'c70bbc2e-5fc4-470a-ab63-312841fcb4c6', 'en', '', '<div>i) supporting other relevant management roles to demonstrate their leadership as it applies to their areas of responsibility.</div>'),
    ('8d12796f-9164-4a97-a55c-7c5bed0cba4b', 'c70bbc2e-5fc4-470a-ab63-312841fcb4c6', 'es', '', '<div>i) apoyando otros roles pertinentes de la dirección, para demostrar su liderazgo en la forma en la que aplique a sus áreas de responsabilidad. </div>'),
    ('c3d8d2e9-6af9-40f9-9b61-33a5717fd3dd', 'c80bbdc1-840a-42b5-9ae8-040542fcb659', 'en', 'Environmental policy', '<div>Top management shall establish, implement and maintain an environmental policy that, within the defined scope of its environmental management system:</div><div>{clause_5.2.a}</div><div>{clause_5.2.b}</div><div>{clause_5.2.c}</div><div>{clause_5.2.d}</div><div>{clause_5.2.e}</div><div>The environmental policy shall:</div><div>— be maintained as documented information;</div><div>— be communicated within the organization;</div><div>— be available to interested parties.</div>'),
    ('bed8cb0a-bea8-4622-91b7-6bba747fd896', 'c80bbdc1-840a-42b5-9ae8-040542fcb659', 'es', 'Política ambiental', '<div>La alta dirección debe establecer, implementar y mantener una política ambiental que, dentro del alcance definido de su sistema de gestión ambiental:</div><div>{clause_5.2.a}</div><div>{clause_5.2.b}</div><div>{clause_5.2.c}</div><div>{clause_5.2.d}</div><div>{clause_5.2.e}</div><div>La política ambiental debe:</div><div>— mantenerse como información documentada;</div><div>— comunicarse dentro de la organización;</div><div>— estar disponible para las partes interesadas. </div>'),
    ('bf4ebcba-4d87-4fca-9167-e84a6c7efc5e', 'c50bb908-5901-4ca0-88bc-3d323ffcb1a0', 'en', '', '<div>a) is appropriate to the purpose and context of the organization, including the nature, scale and environmental impacts of its activities, products and services;</div>'),
    ('a44e9239-5371-45d1-8fa4-1315797f10d5', 'c50bb908-5901-4ca0-88bc-3d323ffcb1a0', 'es', '', '<div>a) sea apropiada al propósito y contexto de la organización, incluida la naturaleza, magnitud e impactos ambientales de sus actividades, productos y servicios;</div>'),
    ('ef39e623-acfd-47a3-a805-e2d716b541c7', 'c60bba9b-4a8f-415b-b443-f6bf40fcb333', 'en', '', '<div>b) provides a framework for setting environmental objectives;</div>'),
    ('ea39de44-13fc-43f4-9a71-f9a4f9b51420', 'c60bba9b-4a8f-415b-b443-f6bf40fcb333', 'es', '', '<div>b) proporcione un marco de referencia para el establecimiento de los objetivos ambientales; </div>'),
    ('ab29f91c-86ae-407c-a0e2-169cccf53778', 'c30bb5e2-72d3-4ac6-8593-32144dfcc7aa', 'en', '', '<div>c) includes a commitment to the protection of the environment, including prevention of pollution and other specific commitment(s) relevant to the context of the organization;</div><div>NOTE: Other specific commitment(s) to protect the environment can include sustainable resource use, climate change mitigation and adaptation, and protection of biodiversity and ecosystems.</div>'),
    ('a029e7cb-2720-447b-9cdc-301fd9f54bef', 'c30bb5e2-72d3-4ac6-8593-32144dfcc7aa', 'es', '', '<div>c) incluya un compromiso para la protección del medio ambiente, incluida la prevención de la contaminación, y otros compromisos específicos pertinentes al contexto de la organización;</div><div>NOTA: Otros compromisos específicos de protección del medio ambiente pueden incluir el uso sostenible de recursos, la mitigación y adaptación al cambio climático y la protección de la biodiversidad y de los ecosistemas.</div>'),
    ('249d015d-6180-4575-85a2-d0b110bba569', 'c40bb775-20ce-4a41-85cc-97f14efcc93d', 'en', '', '<div>d) includes a commitment to fulfil its compliance obligations;</div>'),
    ('279d0616-7bdd-4b56-9ec7-555e0bbb9d8a', 'c40bb775-20ce-4a41-85cc-97f14efcc93d', 'es', '', '<div>d) incluya un compromiso de cumplir con los requisitos legales y otros requisitos;</div>'),
    ('cdb8068b-1836-45cb-8bcf-6c5fcd6fafb7', '310ea1a3-bc19-4dff-81a8-84a74bff031b', 'en', '', '<div>e) includes a commitment to continual improvement of the environmental management system to enhance environmental performance.</div>'),
    ('d8b817dc-33a0-4eec-92c6-40dcd06fb470', '310ea1a3-bc19-4dff-81a8-84a74bff031b', 'es', '', '<div>e) incluya un compromiso de mejora continua del sistema de gestión ambiental para la mejora del desempeño ambiental.</div>'),
    ('2e0e7b42-5866-42f2-a3db-ca92ed65c08e', '300ea010-4a0f-4634-a389-d33a4aff0188', 'en', 'Organizational roles, responsibilities and authorities', '<div>Top management shall ensure that the responsibilities and authorities for relevant roles are assigned and communicated within the organization.</div><div>Top management shall assign the responsibility and authority for:</div><div>{clause_5.3.a}</div><div>{clause_5.3.b}</div>'),
    ('230e69f1-2ef0-4ae9-9c20-a08dda65a2a5', '300ea010-4a0f-4634-a389-d33a4aff0188', 'es', 'Roles, responsabilidades y autoridades en la organización', '<div>La alta dirección debe asegurarse de que las responsabilidades y autoridades para los roles pertinentes se asignen y comuniquen dentro de la organización. </div><div>La alta dirección debe asignar la responsabilidad y autoridad para: </div><div>{clause_5.3.a}</div><div>{clause_5.3.b}</div>'),
    ('1512c811-1a01-49e1-a8fd-6a2d679b42cd', '330ea4c9-33d4-4829-b63e-f5ed4dff0641', 'en', '', '<div>a) ensuring that the environmental management system conforms to the requirements of this International Standard;</div>'),
    ('2012d962-7187-4bba-a262-99b24a9b1526', '330ea4c9-33d4-4829-b63e-f5ed4dff0641', 'es', '', '<div>a) asegurarse de que el sistema de gestión ambiental es conforme con los requisitos de esta Norma Internacional;</div>'),
    ('7c164ec0-be36-4d98-a2de-7b88ae27d5cc', '320ea336-2d2d-47ee-b93b-9a304cff04ae', 'en', '', '<div>b) reporting on the performance of the environmental management system, including environmental performance, to top management.</div>'),
    ('99167c67-ac9e-44cf-aeab-96f3c327f6db', '320ea336-2d2d-47ee-b93b-9a304cff04ae', 'es', '', '<div>b) informar a la alta dirección sobre el desempeño del sistema de gestión ambiental, incluyendo su desempeño ambiental. </div>'),
    ('808cdd37-4bca-449f-8cd9-eee31a9ad90b', '350ea7ef-bde0-432b-8e07-e1eb4fff0967', 'en', 'Planning', '<div>{clause_6.1}</div><div>{clause_6.2}</div>'),
    ('838ce1f0-0142-49c8-8073-aed8259aea5c', '350ea7ef-bde0-432b-8e07-e1eb4fff0967', 'es', 'Planificación', '<div>{clause_6.1}</div><div>{clause_6.2}</div>'),
    ('a082ee0e-e678-4c76-90e2-e0b67af14dc2', '340ea65c-c6ab-48f0-a8b6-606e4eff07d4', 'en', 'Actions to address risks and opportunities', '<div>{clause_6.1.1}</div><div>{clause_6.1.2}</div><div>{clause_6.1.3}</div><div>{clause_6.1.4}</div>'),
    ('8d82d025-f90b-4815-b10a-99f96ff13c71', '340ea65c-c6ab-48f0-a8b6-606e4eff07d4', 'es', 'Acciones para abordar riesgos y oportunidades', '<div>{clause_6.1.1}</div><div>{clause_6.1.2}</div><div>{clause_6.1.3}</div><div>{clause_6.1.4}</div>'),
    ('1ab8704d-2725-4895-a732-1d8161f59a91', '370eab15-f42e-4805-abdf-3a2151ff0c8d', 'en', 'General', '<div>The organization shall establish, implement and maintain the process(es) needed to meet the requirements in 6.1.1 to 6.1.4.</div><div>When planning for the environmental management system, the organization shall consider:</div><div>{clause_6.1.1.a}</div><div>{clause_6.1.1.b}</div><div>{clause_6.1.1.c}</div><div>and determine the risks and opportunities, related to its environmental aspects (see 6.1.2), compliance obligations (see 6.1.3) and other issues and requirements, identified in 4.1 and 4.2, that need to be addressed to:</div><div>— give assurance that the environmental management system can achieve its intended outcomes;</div><div>— prevent or reduce undesired effects, including the potential for external environmental conditions to affect the organization;</div><div>— achieve continual improvement.</div><div>Within the scope of the environmental management system, the organization shall determine potential emergency situations, including those that can have an environmental impact.</div><div>The organization shall maintain documented information of its:</div><div>— risks and opportunities that need to be addressed;</div><div>— process(es) need</div>'),
    ('fdb842a6-1493-4cf6-81e1-224e6cf5abe2', '370eab15-f42e-4805-abdf-3a2151ff0c8d', 'es', 'Generalidades', '<div>La organización debe establecer, implementar y mantener los procesos necesarios para cumplir los requisitos de los apartados 6.1.1 a 6.1.4.</div><div>Al planificar el sistema de gestión ambiental, la organización debe considerar:</div><div>{clause_6.1.1.a}</div><div>{clause_6.1.1.b}</div><div>{clause_6.1.1.c}</div><div>y determinar los riesgos y oportunidades relacionados con sus:</div><div>— aspectos ambientales (véase 6.1.2);</div><div>— requisitos legales y otros requisitos (véase 6.1.3);</div><div>— y otras cuestiones y requisitos identificados en los apartados 4.1 y 4.2,</div><div>que necesitan abordarse para:</div><div>— asegurar que el sistema de gestión ambiental puede lograr sus resultados previstos;</div><div>— prevenir o reducir los efectos no deseados, incluida la posibilidad de que condiciones ambientales externas afecten a la organización;</div><div>— lograr la mejora continua.</div><div>Dentro del alcance del sistema de gestión ambiental, la organización debe determinar las situaciones de emergencia potenciales, incluidas las que pueden tener un impacto ambiental.</div><div>La organización debe mantener la información documentada de sus:</div><div>— riesgos y oportunidades que es necesario abordar;</div><div>— procesos necesarios especificados desde el apartado 6.1.1 al apartado 6.1.4, en la medida necesaria para tener confianza de que se llevan a cabo de la manera planificada.</div>'),
    ('6145034c-a50d-439c-9131-236cc8f92140', '360ea982-b7ee-4e9a-976e-e34450ff0afa', 'en', '', '<div>a) the issues referred to in 4.1;</div>'),
    ('7645245b-47f8-4d9b-997a-e30fe5f94ee7', '360ea982-b7ee-4e9a-976e-e34450ff0afa', 'es', '', '<div>a) las cuestiones referidas en el apartado 4.1; </div>'),
    ('a5f45413-2ea7-4843-9c6a-086734ccc0bf', '390eae3b-945c-4e87-9297-e0ef43fef683', 'en', '', '<div>b) the requirements referred to in 4.2;</div>'),
    ('c0f47e94-7f87-4c14-bef1-55d447ccdea8', '390eae3b-945c-4e87-9297-e0ef43fef683', 'es', '', '<div>b) los requisitos referidos en el apartado 4.2; </div>'),
    ('756b59ea-2857-45ea-a8e9-d21ac81c7716', '380eaca8-057f-40dc-9b8a-d3e242fef4f0', 'en', '', '<div>c) the scope of its environmental management system;</div>'),
    ('7a6b61c9-4462-4771-95a9-fb85c51c725d', '380eaca8-057f-40dc-9b8a-d3e242fef4f0', 'es', '', '<div>c) el alcance de su sistema de gestión ambiental;</div>'),
    ('1c10c312-8bf7-48be-9171-4b426ba4c906', 'c6fcb1a4-3c21-42a8-adb9-028ac215832c', 'en', 'Environmental aspects', '<div>Within the defined scope of the environmental management system, the organization shall determine the environmental aspects of its activities, products and services that it can control and those that it can influence, and their associated environmental impacts, considering a life cycle perspective.</div><div>When determining environmental aspects, the organization shall take into account:</div><div>{clause_6.1.2.a}</div><div>{clause_6.1.2.b}</div><div>The organization shall determine those aspects that have or can have a significant environmental impact, i.e. significant environmental aspects, by using established criteria.</div><div>The organization shall communicate its significant environmental aspects among the various levels and functions of the organization, as appropriate.</div><div>The organization shall maintain documented information of its:</div><div>— environmental aspects and associated environmental impacts;</div><div>— criteria used to determine its significant environmental aspects;</div><div>— significant environmental aspects.</div><div>NOTE: Significant environmental aspects can result in risks and opportunities associated with either adverse environmental impacts (threats) or beneficial environmental impacts (opportunities).</div>'),
    ('3110e421-734b-4ead-82b1-c1dd88a4f6ad', 'c6fcb1a4-3c21-42a8-adb9-028ac215832c', 'es', 'Aspectos ambientales', '<div>Dentro del alcance definido del sistema de gestión ambiental, la organización debe determinar los aspectos ambientales de sus actividades, productos y servicios que puede controlar y de aquellos en los que puede influir, y sus impactos ambientales asociados, desde una perspectiva de ciclo de vida.</div><div>Cuando se determinan los aspectos ambientales, la organización debe tener en cuenta:</div><div>{clause_6.1.2.a}</div><div>{clause_6.1.2.b}</div><div>La organización debe determinar aquellos aspectos que tengan o puedan tener un impacto ambiental significativo, es decir, los aspectos ambientales significativos, mediante el uso de criterios establecidos.</div><div>La organización debe comunicar sus aspectos ambientales significativos entre los diferentes niveles y funciones de la organización, según corresponda.</div><div>La organización debe mantener información documentada de sus: </div><div>— aspectos ambientales e impactos ambientales asociados;</div><div>— criterios usados para determinar sus aspectos ambientales significativos;</div><div>— aspectos ambientales significativos.</div><div>NOTA: Los aspectos ambientales significativos pueden dar como resultado riesgos y oportunidades asociados tanto con impactos ambientales adversos (amenazas) como con impactos ambientales beneficiosos (oportunidades).</div>'),
    ('6bfa8bdb-3f42-4467-91dc-6b0f18f4db2f', 'c7fcb337-ab26-4063-bcd6-b677c31584bf', 'en', '', '<div>a) change, including planned or new developments, and new or modified activities, products and services;</div>'),
    ('56fa6acc-4875-4400-8992-ab6c0bf4c6b8', 'c7fcb337-ab26-4063-bcd6-b677c31584bf', 'es', '', '<div>a) los cambios, incluidos los desarrollos nuevos o planificados, y las actividades, productos y servicios nuevos o modificados; </div>'),
    ('a9799790-4a46-44e4-9dfe-3cf8d9accee4', 'c8fcb4ca-0999-48b2-9211-3140c4158652', 'en', '', '<div>b) abnormal conditions and reasonably foreseeable emergency situations.</div>'),
    ('a67992d7-3cee-4633-93d3-c603deacd6c3', 'c8fcb4ca-0999-48b2-9211-3140c4158652', 'es', '', '<div>b) las condiciones anormales y las situaciones de emergencia razonablemente previsibles.</div>'),
    ('409b0ba1-a574-485d-80ce-b55d70a5a085', 'c9fcb65d-7f26-497d-a9c5-4cfdc51587e5', 'en', 'Compliance obligations', '<div>The organization shall:</div><div>{clause_6.1.3.a}</div><div>{clause_6.1.3.b}</div><div>{clause_6.1.3.c}</div><div>The organization shall maintain documented information of its compliance obligations.</div><div>NOTE: Compliance obligations can result in risks and opportunities to the organization.</div>'),
    ('2b9aea92-31b1-45ce-8f8e-3ec283a5be6e', 'c9fcb65d-7f26-497d-a9c5-4cfdc51587e5', 'es', 'Requisitos legales y otros requisitos', '<div>La organización debe: </div><div>{clause_6.1.3.a}</div><div>{clause_6.1.3.b}</div><div>{clause_6.1.3.c}</div><div>La organización debe mantener información documentada de sus requisitos legales y otros requisitos.</div><div>NOTA: Los requisitos legales y otros requisitos pueden dar como resultado riesgos y oportunidades para la organización.</div>'),
    ('013f779e-3e51-483a-bd43-baa6a67646da', 'c2fcab58-859a-44cc-a5fb-40bebe157ce0', 'en', '', '<div>a) determine and have access to the compliance obligations related to its environmental aspects;</div>'),
    ('0e3f8c15-e6cb-4661-b762-1f098b761c59', 'c2fcab58-859a-44cc-a5fb-40bebe157ce0', 'es', '', '<div>a) determinar y tener acceso a los requisitos legales y otros requisitos relacionados con sus aspectos ambientales; </div>'),
    ('adf02607-2de4-4153-a992-e3136580a0c3', 'c3fcaceb-2e62-4b37-952c-4efbbf157e73', 'en', '', '<div>b) determine how these compliance obligations apply to the organization;</div>'),
    ('90eff860-3b3f-4304-be8d-5d28608098e4', 'c3fcaceb-2e62-4b37-952c-4efbbf157e73', 'es', '', '<div>b) determinar cómo estos requisitos legales y otros requisitos se aplican a la organización.</div>'),
    ('8f47afdc-d759-4e00-a0f3-5c5cf3deb698', 'c4fcae7e-7cfe-4cc6-8140-a554c0158006', 'en', '', '<div>c) take these compliance obligations into account when establishing, implementing, maintaining and continually improving its environmental management system.</div>'),
    ('84479e8b-ce26-4e67-99fc-87df00decb0f', 'c4fcae7e-7cfe-4cc6-8140-a554c0158006', 'es', '', '<div>c) tener en cuenta estos requisitos legales y otros requisitos cuando se establezca, implemente, mantenga y mejore continuamente su sistema de gestión ambiental.</div>'),
    ('06404f1d-a250-47e9-b43e-5c71ab005d09', 'c5fcb011-2af8-4c41-9e47-2131c1158199', 'en', 'Planning action', '<div>The organization shall plan:</div><div>{clause_6.1.4.a}</div><div>{clause_6.1.4.b}</div><div>When planning these actions, the organization shall consider its technological options and its financial, operational and business requirements.</div>'),
    ('094053d6-cbc7-4ff2-be46-981ea600552a', 'c5fcb011-2af8-4c41-9e47-2131c1158199', 'es', 'Planificación de acciones', '<div>La organización debe planificar: </div><div>{clause_6.1.4.a}</div><div>{clause_6.1.4.b}</div><div>Cuando se planifiquen estas acciones, la organización debe considerar sus opciones tecnológicas y sus requisitos financieros, operacionales y de negocio.</div>'),
    ('a0f39d7a-5e09-4a86-8c4e-150a93687b7e', 'befca50c-632c-4ea0-8eb9-6072ca158fc4', 'en', '', '<div>a) to take actions to address its:</div><ul><li>{clause_6.1.4.a.1}</li><li>{clause_6.1.4.a.2}</li><li>{clause_6.1.4.a.3}</li></ul>'),
    ('85f372f9-9ad6-4645-b208-13d5a0688ff5', 'befca50c-632c-4ea0-8eb9-6072ca158fc4', 'es', '', '<div>a) la toma de acciones para abordar sus:</div><ul><li>{clause_6.1.4.a.1}</li><li>{clause_6.1.4.a.2}</li><li>{clause_6.1.4.a.3}</li></ul>'),
    ('d3592fe3-c8a2-43ef-8710-e897b372cf67', 'bffca69f-54ba-435b-987a-1fffcb159157', 'en', '', '<div>1) significant environmental aspects;</div>'),
    ('ce592804-c41c-4738-97f0-57649672a1c0', 'bffca69f-54ba-435b-987a-1fffcb159157', 'es', '', '<div>1) aspectos ambientales significativos;</div>'),
    ('f6b615d1-bd7e-438d-bf88-f5ed09888575', '4cffc32d-b469-4691-a247-592dc817cb35', 'en', '', '<div>2) compliance obligations;</div>'),
    ('01b62722-ef77-429e-9ed4-8072fc8870fe', '4cffc32d-b469-4691-a247-592dc817cb35', 'es', '', '<div>2) requisitos legales y otros requisitos;</div>'),
    ('5db99c80-91f4-4a14-99d4-b348e5e95954', '4bffc19a-ed22-4216-a0ae-9c70c717c9a2', 'en', '', '<div>3) risks and opportunities identified in 6.1.1;</div>'),
    ('7ab9ca27-4114-4643-accf-26b3cae92ed3', '4bffc19a-ed22-4216-a0ae-9c70c717c9a2', 'es', '', '<div>3) riesgos y oportunidades identificados en el apartado 6.1.1; </div>'),
    ('af5ce74b-164e-4f97-8909-f81fe52f6ddf', '4affc007-9e86-4087-be05-3be7c617c80f', 'en', '', '<div>b) how to:</div><ul><li>{clause_6.1.4.b.1}</li><li>{clause_6.1.4.b.2}</li></ul>'),
    ('ba5cf89c-76ad-43d0-8d0f-de9cf82f8bc8', '4affc007-9e86-4087-be05-3be7c617c80f', 'es', '', '<div>b) la manera de:</div><ul><li>{clause_6.1.4.b.1}</li><li>{clause_6.1.4.b.2}</li></ul>'),
    ('122c3202-4563-44ee-ace4-565205257eb6', '49ffbe74-0faa-42dc-9c36-387ac517c67c', 'en', '', '<div>1) integrate and implement the actions into its environmental management system processes (see 6.2, Clause 7, Clause 8 and 9.1), or other business processes;</div>'),
    ('072c20b1-cf46-4ffd-8ed3-5c4d022579fd', '49ffbe74-0faa-42dc-9c36-387ac517c67c', 'es', '', '<div>1) integrar e implementar las acciones en los procesos de su sistema de gestión ambiental (véanse 6.2, 7, 8 y 9.1) o en otros procesos de negocio;</div>'),
    ('fc5d510d-a4a6-4e99-a78a-744177da5379', '48ffbce1-d750-410d-86ef-ae61c417c4e9', 'en', '', '<div>2) evaluate the effectiveness of these actions (see 9.1).</div>'),
    ('df5d2366-2549-4b42-a2b3-620e92da7dfa', '48ffbce1-d750-410d-86ef-ae61c417c4e9', 'es', '', '<div>2) evaluar la eficacia de estas acciones (véase 9.1).</div>'),
    ('45644d0c-2d18-4570-aba2-872c00b911c8', '47ffbb4e-79bd-4e02-a043-1a84c317c356', 'en', 'Environmental objectives and planning to achieve them', '<div>{clause_6.2.1}</div><div>{clause_6.2.2}</div>'),
    ('5a646e1b-ccba-4137-804b-e9cfedb8f3df', '47ffbb4e-79bd-4e02-a043-1a84c317c356', 'es', 'Objetivos ambientales y planificación para lograrlos', '<div>{clause_6.2.1}</div><div>{clause_6.2.2}</div>'),
    ('64aa93f7-4b9f-4ec3-aabf-5aa32fe1c133', '46ffb9bb-1b4a-45b3-a0ce-792bc217c1c3', 'en', 'Environmental objectives', '<div>The organization shall establish environmental objectives at relevant functions and levels, taking into account the organization’s significant environmental aspects and associated compliance obligations, and considering its risks and opportunities.</div><div>The environmental objectives shall be:</div><div>{clause_6.2.1.a}</div><div>{clause_6.2.1.b}</div><div>{clause_6.2.1.c}</div><div>{clause_6.2.1.d}</div><div>{clause_6.2.1.e}</div><div>The organization shall maintain documented information on the environmental objectives.</div>'),
    ('67aa98b0-9c7f-4294-9a79-89984ae1ebb4', '46ffb9bb-1b4a-45b3-a0ce-792bc217c1c3', 'es', 'Objetivos ambientales', '<div>La organización debe establecer objetivos ambientales para las funciones y niveles pertinentes, teniendo en cuenta los aspectos ambientales significativos de la organización y sus requisitos legales y otros requisitos asociados, y considerando sus riesgos y oportunidades.</div><div>Los objetivos ambientales deben: </div><div>{clause_6.2.1.a}</div><div>{clause_6.2.1.b}</div><div>{clause_6.2.1.c}</div><div>{clause_6.2.1.d}</div><div>{clause_6.2.1.e}</div><div>La organización debe conservar información documentada sobre los objetivos ambientales.</div>'),
    ('84a0a4ce-454f-4c6a-beb6-2776ff57340a', '45ffb828-ac46-47f8-9a4c-2faec117c030', 'en', '', '<div>a) consistent with the environmental policy;</div>'),
    ('71a086e5-615a-4df1-be2e-a0b904573be9', '45ffb828-ac46-47f8-9a4c-2faec117c030', 'es', '', '<div>a) ser coherentes con la política ambiental; </div>'),
    ('5c382199-441e-4f15-adbe-e075a4a5dd6d', '44ffb695-3dfe-4a29-a75c-2d75d017d7cd', 'en', '', '<div>b) measurable (if practicable);</div>'),
    ('77384c1a-318b-4376-a501-332a87a5afc6', '44ffb695-3dfe-4a29-a75c-2d75d017d7cd', 'es', '', '<div>b) ser medibles (si es factible);</div>'),
    ('e51872e8-c205-4a1c-be3f-6cf0eb32706c', '43ffb502-3758-49ee-9ffa-48d8cf17d63a', 'en', '', '<div>c) monitored;</div>'),
    ('d21854ff-64f1-441b-ac04-80cb0032917b', '43ffb502-3758-49ee-9ffa-48d8cf17d63a', 'es', '', '<div>c) ser objeto de seguimiento;</div>'),
    ('07be13bb-5d34-4087-8919-fe6f6024d6ef', 'b5a84fd7-94b3-4e43-a9c7-05973099486f', 'en', '', '<div>d) communicated;</div>'),
    ('f2bdf2ac-63ee-4a20-b0e8-15cc5324c278', 'b5a84fd7-94b3-4e43-a9c7-05973099486f', 'es', '', '<div>d) comunicarse;</div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('b7d2b7f2-e9c3-485e-83fc-59a2b550c0c6', 'b4a84e44-25b0-4388-8ad1-8e2a2f9946dc', 'en', '', '<div>e) updated as appropriate.</div>'),
    ('ccd2d901-b54e-4d4d-ac13-643dd250ee6d', 'b4a84e44-25b0-4388-8ad1-8e2a2f9946dc', 'es', '', '<div>e) actualizarse, según corresponda. </div>'),
    ('dc5d0081-eeaf-4ffd-aa30-57bdba519845', 'b7a852fd-501b-48dd-a9c1-291d32994b95', 'en', 'Planning actions to achieve environmental objectives', '<div>When planning how to achieve its environmental objectives, the organization shall determine:</div><div>{clause_6.2.2.a}</div><div>{clause_6.2.2.b}</div><div>{clause_6.2.2.c}</div><div>{clause_6.2.2.d}</div><div>{clause_6.2.2.e}</div><div>The organization shall consider how actions to achieve its environmental objectives can be integrated into the organization’s business processes.</div>'),
    ('c75cdf72-64cd-44ee-8219-4d22cd51b62e', 'b7a852fd-501b-48dd-a9c1-291d32994b95', 'es', 'Planificación de acciones para lograr los objetivos ambientales', '<div>Al planificar cómo lograr sus objetivos ambientales, la organización debe determinar:</div><div>{clause_6.2.2.a}</div><div>{clause_6.2.2.b}</div><div>{clause_6.2.2.c}</div><div>{clause_6.2.2.d}</div><div>{clause_6.2.2.e}</div><div>La organización debe considerar cómo se pueden integrar las acciones para el logro de sus objetivos ambientales a los procesos de negocio de la organización.</div>'),
    ('b61c5bf0-24f1-4504-a261-e5d820de5da4', 'b6a8516a-dd08-4112-85f2-7ce031994a02', 'en', '', '<div>a) what will be done;</div>'),
    ('b31c5737-1797-4353-aec8-25e325de6583', 'b6a8516a-dd08-4112-85f2-7ce031994a02', 'es', '', '<div>a) qué se va a hacer;</div>'),
    ('bd0d5367-495b-4473-9ede-8373acb22f83', 'b1a8498b-01d1-4397-9e2e-d81b2c994223', 'en', '', '<div>b) what resources will be required;</div>'),
    ('a00d25c0-3d69-4124-9311-6808a7b227a4', 'b1a8498b-01d1-4397-9e2e-d81b2c994223', 'es', '', '<div>b) qué recursos se requerirán;</div>'),
    ('9d02ff7e-ffaf-435a-848f-d286f020ab9a', 'b0a847f8-8875-4aac-b501-7fde2b994090', 'en', '', '<div>c) who will be responsible;</div>'),
    ('aa0313f5-c3ef-4c81-92e7-2769d5208119', 'b0a847f8-8875-4aac-b501-7fde2b994090', 'es', '', '<div>c) quién será responsable; </div>'),
    ('a203d6fd-7a3b-4409-a2ed-9a51f4aac1c9', 'b3a84cb1-2dd4-4221-9383-51512e994549', 'en', '', '<div>d) when it will be completed;</div>'),
    ('a503dbb6-8a65-4712-94bb-887eefaab9ea', 'b3a84cb1-2dd4-4221-9383-51512e994549', 'es', '', '<div>d) cuándo se finalizará;</div>'),
    ('9bea743c-f2d2-4420-bc73-313c3b104558', 'b2a84b1e-506b-4226-9ca8-67f42d9943b6', 'en', '', '<div>e) how the results will be evaluated, including indicators for monitoring progress toward achievement of its measurable environmental objectives (see 9.1.1).</div>'),
    ('90ea62eb-ec18-4a87-9f1a-35bf481059cf', 'b2a84b1e-506b-4226-9ca8-67f42d9943b6', 'es', '', '<div>e) cómo se evaluarán los resultados, incluidos los indicadores de seguimiento de los avances para el logro de sus objetivos ambientales medibles (véase 9.1.1). </div>'),
    ('6f1b24c3-a306-460f-b0f3-7bf7faa2cb27', 'ada8433f-4176-40bb-bf82-3e1f38995507', 'en', 'Support', '<div>{clause_7.1}</div><div>{clause_7.2}</div><div>{clause_7.3}</div><div>{clause_7.4}</div><div>{clause_7.5}</div>'),
    ('6a1b1ce4-b224-48d8-8ac8-d3c4dda29d80', 'ada8433f-4176-40bb-bf82-3e1f38995507', 'es', 'Apoyo', '<div>{clause_7.1}</div><div>{clause_7.2}</div><div>{clause_7.3}</div><div>{clause_7.4}</div><div>{clause_7.5}</div>'),
    ('b010cada-c6ad-45a6-a380-61eada98773e', 'aca841ac-3699-4400-9c84-d21237995374', 'en', 'Resources', '<div>The organization shall determine and provide the resources needed for the establishment, implementation, maintenance and continual improvement of the environmental management system.</div>'),
    ('9510a059-32e7-4ee5-9158-4235e7988bb5', 'aca841ac-3699-4400-9c84-d21237995374', 'es', 'Recursos', '<div>La organización debe determinar y proporcionar los recursos necesarios para el establecimiento, implementación, mantenimiento y mejora continua del sistema de gestión ambiental.</div>'),
    ('166d5c74-f723-46f0-818d-32346ed41fa8', 'afa607ce-84df-4982-b0bd-cc0caa9636e6', 'en', 'Competence', '<div>The organization shall:</div><div>{clause_7.2.a}</div><div>{clause_7.2.b}</div><div>{clause_7.2.c}</div><div>{clause_7.2.d}</div><div>NOTE: Applicable actions can include, for example, the provision of training to, the mentoring of, or the reassignment of currently employed persons; or the hiring or contracting of competent persons.</div><div>The organization shall retain appropriate documented information as evidence of competence.</div>'),
    ('fb6d31f3-96c5-42b7-b3ad-39475bd401bf', 'afa607ce-84df-4982-b0bd-cc0caa9636e6', 'es', 'Competencia', '<div>La organización debe:</div><div>{clause_7.2.a}</div><div>{clause_7.2.b}</div><div>{clause_7.2.c}</div><div>{clause_7.2.d}</div><div>NOTA: Las acciones aplicables pueden incluir, por ejemplo, la formación, la tutoría o la reasignación de las personas empleadas actualmente, o la contratación o subcontratación de personas competentes.</div><div>La organización debe conservar información documentada apropiada, como evidencia de la competencia.</div>'),
    ('afe09715-6eb1-4019-ac1a-9c09e86fca59', 'b0a60961-e271-4c8d-9636-7f09ab963879', 'en', '', '<div>a) determine the necessary competence of person(s) doing work under its control that affects its environmental performance and its ability to fulfil its compliance obligations;</div>'),
    ('a2e0829e-ef54-4cc2-b1fc-37a6036ff4da', 'b0a60961-e271-4c8d-9636-7f09ab963879', 'es', '', '<div>a) determinar la competencia necesaria de las personas que realizan trabajos bajo su control, que afecte a su desempeño ambiental y su capacidad para cumplir sus requisitos legales y otros requisitos;</div>'),
    ('a9032756-0f5a-4dea-b55b-229ee346506a', 'ada604a8-b767-4378-be62-8ef6a89633c0', 'en', '', '<div>b) ensure that these persons are competent on the basis of appropriate education, training or experience;</div>'),
    ('a603229d-2b65-4f71-ab52-e6f1e8465849', 'ada604a8-b767-4378-be62-8ef6a89633c0', 'es', '', '<div>b) asegurarse de que estas personas sean competentes, con base en su educación, formación o experiencia apropiadas;</div>'),
    ('15b503ff-15aa-4043-9ad9-054b13cf4a93', 'aea6063b-266c-4133-9844-dd13a9963553', 'en', '', '<div>c) determine training needs associated with its environmental aspects and its environmental management system;</div>'),
    ('28b521e8-668a-4414-ad13-f1702ecf7514', 'aea6063b-266c-4133-9844-dd13a9963553', 'es', '', '<div>c) determinar las necesidades de formación asociadas con sus aspectos ambientales y su sistema de gestión ambiental;</div>'),
    ('313ea7e8-5bff-4b94-9c8a-e770567ed034', 'b3a60e1a-f843-4d96-b3eb-e758ae963d32', 'en', '', '<div>d) where applicable, take actions to acquire the necessary competence, and evaluate the effectiveness of the actions taken.</div>'),
    ('1e3e89ff-0b1f-47c3-8a4f-fb4b3b7ea5b3', 'b3a60e1a-f843-4d96-b3eb-e758ae963d32', 'es', '', '<div>d) cuando sea aplicable, tomar acciones para adquirir la competencia necesaria y evaluar la eficacia de las acciones tomadas.</div>'),
    ('a85e5699-8789-450d-8c0a-5af5ed77a1d5', 'b4a60fad-bf8b-4211-bb4d-cbf5af963ec5', 'en', 'Awareness', '<div>The organization shall ensure that persons doing work under the organization’s control are aware of:</div><div>{clause_7.3.a}</div><div>{clause_7.3.b}</div><div>{clause_7.3.c}</div><div>{clause_7.3.d}</div>'),
    ('c35e811a-b982-441e-834c-adaae0778d5e', 'b4a60fad-bf8b-4211-bb4d-cbf5af963ec5', 'es', 'Toma de conciencia', '<div>La organización debe asegurarse de que las personas que realicen el trabajo bajo el control de la organización tomen conciencia de: </div><div>{clause_7.3.a}</div><div>{clause_7.3.b}</div><div>{clause_7.3.c}</div><div>{clause_7.3.d}</div>'),
    ('a3366faa-0f6e-466e-9731-155ae9149b16', 'b1a60af4-1acb-4e5c-83d1-64a2ac963a0c', 'en', '', '<div>a) the environmental policy;</div>'),
    ('a8367789-9951-417d-bc18-ccc5e614965d', 'b1a60af4-1acb-4e5c-83d1-64a2ac963a0c', 'es', '', '<div>a) la política ambiental; </div>'),
    ('d639d2d3-e059-4117-969a-87a755c4e4bf', 'b2a60c87-a9a8-4c07-a883-04afad963b9f', 'en', '', '<div>b) the significant environmental aspects and related actual or potential environmental impacts associated with their work;</div>'),
    ('f139fd54-40b8-4550-9d4d-281468c502a8', 'b2a60c87-a9a8-4c07-a883-04afad963b9f', 'es', '', '<div>b) los aspectos ambientales significativos y los impactos ambientales reales o potenciales relacionados, asociados con su trabajo;</div>'),
    ('918a820c-a539-4598-89ee-01ace9f14540', 'a7a5fb36-cd3a-4c1a-b434-b904b296437e', 'en', '', '<div>c) their contribution to the effectiveness of the environmental management system, including the benefits of enhanced environmental performance;</div>'),
    ('a68aa31b-93a2-4ccf-9e97-644f06f172e7', 'a7a5fb36-cd3a-4c1a-b434-b904b296437e', 'es', '', '<div>c) su contribución a la eficacia del sistema de gestión ambiental, incluidos los beneficios de una mejora del desempeño ambiental; </div>'),
    ('4883860d-0104-41e1-85d5-eec182edbe91', 'a8a5fcc9-097a-4585-9ae1-4ce1b3964511', 'en', '', '<div>d) the implications of not conforming with the environmental management system requirements, including not fulfilling the organization’s compliance obligations.</div>'),
    ('2b835866-588a-43ba-80fe-dc8e8dedcfe2', 'a8a5fcc9-097a-4585-9ae1-4ce1b3964511', 'es', '', '<div>d) las implicaciones de no satisfacer los requisitos del sistema de gestión ambiental, incluido el incumplimiento de los requisitos legales y otros requisitos de la organización.</div>'),
    ('7b1a57dd-ed41-46a5-994e-c8b1f30a8c21', '29a2f645-006b-4d49-9b67-4ff1c494213d', 'en', 'Communication', '{clause_7.4.1}<br><div>{clause_7.4.2}</div><div>{clause_7.4.3}</div><br>'),
    ('7e1a5c96-9a54-4266-b273-4d5ede0a6b12', '29a2f645-006b-4d49-9b67-4ff1c494213d', 'es', 'Comunicación', '<div>{clause_7.4.1}</div><div>{clause_7.4.2}</div><div>{clause_7.4.3}</div>'),
    ('01a74f9c-c05d-482c-b48e-0e9c5be91810', '28a2f4b2-f699-438e-9b2d-ea14c3941faa', 'en', 'General', '<div>The organization shall establish, implement and maintain the process(es) needed for internal and external communications relevant to the environmental management system, including:</div><div>{clause_7.4.1.a}</div><div>{clause_7.4.1.b}</div><div>{clause_7.4.1.c}</div><div>{clause_7.4.1.d}</div><div>When establishing its communication process(es), the organization shall:</div><div>— take into account its compliance obligations;</div><div>— ensure that environmental information communicated is consistent with information generated within the environmental management system, and is reliable.</div><div>The organization shall respond to relevant communications on its environmental management system.</div><div>The organization shall retain documented information as evidence of its communications, as appropriate.</div>'),
    ('f6a73e4b-a4f3-4f0b-b088-281f58e91357', '28a2f4b2-f699-438e-9b2d-ea14c3941faa', 'es', 'Generalidades', '<div>La organización debe establecer, implementar y mantener los procesos necesarios para las comunicaciones internas y externas pertinentes al sistema de gestión ambiental, que incluyan: </div><div>{clause_7.4.1.a}</div><div>{clause_7.4.1.b}</div><div>{clause_7.4.1.c}</div><div>{clause_7.4.1.d}</div><div>Cuando establece sus procesos de comunicación, la organización debe:</div><div>— tener en cuenta sus requisitos legales y otros requisitos;</div><div>— asegurarse de que la información ambiental comunicada sea coherente con la información generada dentro del sistema de gestión ambiental, y que sea fiable.</div><div>La organización debe responder a las comunicaciones pertinentes sobre su sistema de gestión ambiental.</div><div>La organización debe conservar información documentada como evidencia de sus comunicaciones, según corresponda. </div>'),
    ('204fc5c7-92ad-456f-9e87-3d531e6a0c5b', '27a2f31f-87fd-4f9f-951e-63bbc2941e17', 'en', '', '<div>a) on what it will communicate;</div>'),
    ('034f9820-8e27-48b8-8785-7d680969eb4c', '27a2f31f-87fd-4f9f-951e-63bbc2941e17', 'es', '', '<div>a) qué comunicar;</div>'),
    ('7619805e-2814-4c06-a24b-58e6ce804392', '26a2f18c-1921-4454-ac37-da7ec1941c84', 'en', '', '<div>b) when to communicate;</div>'),
    ('831994d5-64e1-47c5-b33e-e549e38064a1', '26a2f18c-1921-4454-ac37-da7ec1941c84', 'es', '', '<div>b) cuándo comunicar; </div>'),
    ('b5738161-2c72-4fb1-abd2-dd9db8afcf9d', '25a2eff9-d6e6-48a5-95bc-a4bdc0941af1', 'en', '', '<div>c) with whom to communicate;</div>'),
    ('a0736052-0dee-482a-8d25-8002bbafd456', '25a2eff9-d6e6-48a5-95bc-a4bdc0941af1', 'es', '', '<div>c) a quién comunicar; </div>'),
    ('1bd93750-476d-4ae8-b282-e13841b7305c', '24a2ee66-9d1f-453a-8483-c600bf94195e', 'en', '', '<div>d) how to communicate.</div>'),
    ('18d93297-8f7a-49bf-be86-c84336b71f0b', '24a2ee66-9d1f-453a-8483-c600bf94195e', 'es', '', '<div>d) cómo comunicar. </div>'),
    ('e0d4949b-e7cd-435b-9ce2-f54f605fa687', '23a2ecd3-874c-4ecb-818f-ab37be9417cb', 'en', 'Internal communication', '<div>The organization shall:</div><div>{clause_7.4.2.a}</div><div>{clause_7.4.2.b}</div>'),
    ('cbd4738c-60a9-475c-8839-92ac435f78e0', '23a2ecd3-874c-4ecb-818f-ab37be9417cb', 'es', '', '<div>La organización debe:</div><div>{clause_7.4.2.a}</div><div>{clause_7.4.2.b}</div>'),
    ('8e6ecfd2-c5c9-4402-8f08-8c82b3aef81e', '22a2eb40-95bc-4710-890d-764abd941638', 'en', '', '<div>a) internally communicate information relevant to the environmental management system among the various levels and functions of the organization, including changes to the environmental management system, as appropriate;</div>'),
    ('a36ef0e1-5bfb-4659-adb5-ea1dc0af0c95', '22a2eb40-95bc-4710-890d-764abd941638', 'es', '', '<div>a) comunicar internamente la información pertinente del sistema de gestión ambiental entre los diversos niveles y funciones de la organización, incluidos los cambios en el sistema de gestión ambiental, según corresponda;</div>'),
    ('dffcffe5-6f7f-49dd-ad31-c2b95a679d29', '31a302dd-73a9-4d31-b706-e119bc9414a5', 'en', '', '<div>b) ensure its communication process(es) enable(s) persons doing work under the organization’s control to contribute to continual improvement.</div>'),
    ('f2fd1dce-fbbc-474e-adb9-49765567954a', '31a302dd-73a9-4d31-b706-e119bc9414a5', 'es', '', '<div>b) asegurarse de que sus procesos de comunicación permitan que las personas que realicen trabajos bajo el control de la organización contribuyan a la mejora continua. </div>'),
    ('49042e44-1451-4664-9107-17a41426c638', '30a3014a-af8e-4536-865a-479cbb941312', 'en', 'External communication', '<div>The organization shall externally communicate information relevant to the environmental management system, as established by the organization’s communication process(es) and as required by its compliance obligations.</div>'),
    ('4e043623-06f9-47b3-9e9b-00d72126daaf', '30a3014a-af8e-4536-865a-479cbb941312', 'es', 'Comunicación externa', '<div>La organización debe comunicar externamente información pertinente al sistema de gestión ambiental, según se establezca en los procesos de comunicación de la organización y según lo requieran sus requisitos legales y otros requisitos. </div>'),
    ('a9dd5aae-01b7-4156-b410-c5d601a4ba22', '23a0ae3c-2598-41c0-b7e1-46cebe91d934', 'en', 'Documented information', '<div>{clause_7.5.1}</div><div>{clause_7.5.2}</div><div>{clause_7.5.3}</div>'),
    ('96dd3cc5-e75a-4b75-833e-d619f6a4a8d1', '23a0ae3c-2598-41c0-b7e1-46cebe91d934', 'es', 'Información documentada', '<div>{clause_7.5.1}</div><div>{clause_7.5.2}</div><div>{clause_7.5.3}</div>'),
    ('876ce0d7-ccea-4b7f-abc5-f103122f14eb', '24a0afcf-1728-497b-b559-ea4bbf91dac7', 'en', 'General', '<div>The organization’s environmental management system shall include:</div><div>{clause_7.5.1.a}</div><div>{clause_7.5.1.b}</div><div>NOTE: The extent of documented information for an environmental management system can differ from one organization to another due to:</div><div>—&nbsp;&nbsp;&nbsp;the size of organization and its type of activities, processes, products and services;</div><div>—&nbsp;&nbsp;&nbsp;the need to demonstrate fulfilment of its compliance obligations;</div><div>—&nbsp;&nbsp;&nbsp;the complexity of processes and their interactions;</div><div>— the competence of persons doing work under the organization’s control.</div>'),
    ('8a6ce590-84dc-49a8-b5f0-67f81d2f263c', '24a0afcf-1728-497b-b559-ea4bbf91dac7', 'es', 'Generalidades', '<div>El sistema de gestión ambiental de la organización debe incluir: </div><div>{clause_7.5.1.a}</div><div>{clause_7.5.1.b}</div><div>NOTA: La extensión de la información documentada para un sistema de gestión ambiental puede variar de una organización a otra, debido a: </div><div>— el tamaño de la organización y su tipo de actividades, procesos, productos y servicios;</div><div>— la necesidad de demostrar el cumplimiento de sus requisitos legales y otros requisitos;</div><div>— la complejidad de los procesos y sus interacciones, y</div><div>— la competencia de las personas que realizan trabajos bajo el control de la organización</div>'),
    ('f4ccf46c-3aa3-46fc-a5c3-8e0c4fae20a0', '25a0b162-1310-4a2a-95c9-30a4c091dc5a', 'en', '', '<div>a) documented information required by this International Standard;</div>'),
    ('09cd157b-db15-4afb-b266-0eaf6cae4e47', '25a0b162-1310-4a2a-95c9-30a4c091dc5a', 'es', '', '<div>a) la información documentada requerida por esta Norma Internacional; </div>'),
    ('ae40616d-1575-4bf5-9525-13a1e63030f1', '26a0b2f5-66c2-4355-9b6a-ac01c191dded', 'en', '', '<div>b) documented information determined by the organization as being necessary for the effectiveness of the environmental management system.</div>'),
    ('914033c6-2fd2-41d6-92eb-f56ef1304242', '26a0b2f5-66c2-4355-9b6a-ac01c191dded', 'es', '', '<div>b) la información documentada que la organización determina como necesaria para la eficacia del sistema de gestión ambiental.</div>'),
    ('c40f4262-edfd-4952-8f09-cd32e772d26e', '1fa0a7f0-a8fd-4f04-b893-371aba91d2e8', 'en', 'Creating and updating', '<div>When creating and updating documented information, the organization shall ensure appropriate:</div><div>{clause_7.5.2.a}</div><div>{clause_7.5.2.b}</div><div>{clause_7.5.2.c}</div>'),
    ('b90f3111-ddd4-4649-95a4-9dadd472b485', '1fa0a7f0-a8fd-4f04-b893-371aba91d2e8', 'es', 'Creación y actualización', '<div>Al crear y actualizar la información documentada, la organización debe asegurarse de que lo siguiente sea apropiado:</div><div>{clause_7.5.2.a}</div><div>{clause_7.5.2.b}</div><div>{clause_7.5.2.c}</div>'),
    ('d4980a2b-9bcf-42ab-92c9-287fc77e5497', '20a0a983-17d9-4a4f-906c-8b87bb91d47b', 'en', '', '<div>a) identification and description (e.g. a title, date, author, or reference number);</div>'),
    ('df981b7c-9b72-4dcc-aa3b-3cfcca7e5950', '20a0a983-17d9-4a4f-906c-8b87bb91d47b', 'es', '', '<div>a) la identificación y descripción (por ejemplo, título, fecha, autor o número de referencia);</div>'),
    ('0f9cace0-97c8-4678-8051-e32834dcd52c', '21a0ab16-8673-4b3e-9d45-ad10bc91d60e', 'en', '', '<div>b) format (e.g. language, software version, graphics) and media (e.g. paper, electronic);</div>'),
    ('2c9cda87-8303-412f-ab57-691349dcf63b', '21a0ab16-8673-4b3e-9d45-ad10bc91d60e', 'es', '', '<div>b) el formato (por ejemplo, idioma, versión del software, gráficos) y los medios de soporte (por ejemplo, papel, electrónico);</div>'),
    ('a8992631-af98-4041-9aa2-004debd5d92d', '22a0aca9-a666-4079-b5ce-88cdbd91d7a1', 'en', '', '<div>c) review and approval for suitability and adequacy.</div>'),
    ('b3993782-04a3-491a-b8b2-fa52ced5ab86', '22a0aca9-a666-4079-b5ce-88cdbd91d7a1', 'es', '', '<div>c) la revisión y aprobación con respecto a la conveniencia y adecuación</div>'),
    ('0ec002b6-a65e-48ce-91b4-cafe49032bca', '2ba0bad4-fb61-4948-bec5-9896b691cc9c', 'en', 'Control of documented information', '<div>Documented information required by the environmental management system and by this International Standard shall be controlled to ensure:</div><div>{clause_7.5.3.a}</div><div>{clause_7.5.3.a}</div><div>For the control of documented information, the organization shall address the following activities as applicable:</div><div>— distribution, access, retrieval and use;</div><div>— storage and preservation, including preservation of legibility;</div><div>— control of changes (e.g. version control);</div><div>— retention and disposition.</div><div>Documented information of external origin determined by the organization to be necessary for the planning and operation of the environmental management system shall be identified, as appropriate, and controlled.</div><div>NOTE: Access can imply a decision regarding the permission to view the documented information only, or the permission and authority to view and change the documented information.</div>'),
    ('0bbffdfd-1a20-4b5d-9fe6-dcd14e0333a9', '2ba0bad4-fb61-4948-bec5-9896b691cc9c', 'es', 'Control de la información documentada', '<div>La información documentada requerida por el sistema de gestión ambiental y por esta Norma Internacional se debe controlar para asegurarse de que: </div><div>{clause_7.5.3.a}</div><div>{clause_7.5.3.b}</div><div>Para el control de la información documentada, la organización debe abordar las siguientes actividades, según corresponda: </div><div>— distribución, acceso, recuperación y uso;</div><div>— almacenamiento y preservación, incluida la preservación de la legibilidad;</div><div>— control de cambios (por ejemplo, control de versión);</div><div>— conservación y disposición.</div><div>La información documentada de origen externo, que la organización determina como necesaria para la planificación y operación del sistema de gestión ambiental, se debe determinar, según sea apropiado, y controlar.</div><div>NOTA: El acceso puede implicar una decisión en relación al permiso, solamente para consultar la información documentada, o al permiso y a la autoridad para consultar y modificar la información documentada.</div>'),
    ('eec9f1df-fdc3-41f7-8b68-232b798c25f3', '2ca0bc67-83b2-4c03-953b-7a33b791ce2f', 'en', '', '<div>a) it is available and suitable for use, where and when it is needed;</div>'),
    ('01ca0fc8-776f-4b30-82d7-d550948c5074', '2ca0bc67-83b2-4c03-953b-7a33b791ce2f', 'es', '', '<div>a) esté disponible y sea idónea para su uso, dónde y cuándo se necesite;</div>'),
    ('34bfeeb7-0a65-4e3b-8303-19e3f3242a33', '1d9e6633-92c4-494f-aaa9-c4eb388ec7ab', 'en', '', '<div>b) it is adequately protected (e.g. from loss of confidentiality, improper use, or loss of integrity).</div>'),
    ('37bff370-677a-443c-b69c-d9d80e2454b4', '1d9e6633-92c4-494f-aaa9-c4eb388ec7ab', 'es', '', '<div>b) esté protegida adecuadamente (por ejemplo, contra pérdida de confidencialidad, uso inadecuado, o pérdida de integridad).</div>'),
    ('54b5ff8e-3e59-47e2-870c-0bb6c2999d0a', '1c9e64a0-23e7-4e04-8558-436e378ec618', 'en', 'Operation', '{clause_8.1}<br><div>{clause_8.2}</div><br>'),
    ('41b5e1a5-d15c-4ab9-a733-c4f9c799a4e9', '1c9e64a0-23e7-4e04-8558-436e378ec618', 'es', 'Operación', '<div>{clause_8.1}</div><div>{clause_8.2}</div>'),
    ('ceeb81cd-cfb0-4111-9d5b-48813b1cbc79', '1f9e6959-2151-4f79-8881-1d213a8ecad1', 'en', 'Operational planning and control', '<div>The organization shall establish, implement, control and maintain the processes needed to meet environmental management system requirements, and to implement the actions identified in 6.1 and 6.2, by:</div><div>— establishing operating criteria for the process(es);</div><div>— implementing control of the process(es), in accordance with the operating criteria.</div><div>NOTE: Controls can include engineering controls and procedures. Controls can be implemented following a hierarchy (e.g. elimination, substitution, administrative) and can be used individually or in combination.</div><div>The organization shall control planned changes and review the consequences of unintended changes, taking action to mitigate any adverse effects, as necessary.</div><div>The organization shall ensure that outsourced processes are controlled or influenced. The type and extent of control or influence to be applied to the process(es) shall be defined within the environmental management system.</div><div>Consistent with a life cycle perspective, the organization shall:</div><div>{clause_8.1.a}</div><div>{clause_8.1.b}</div><div>{clause_8.1.c}</div><div>{clause_8.1.d}</div><div>The organization shall maintain documented information to the extent necessary to have confidence that the processes have been carried out as planned.</div>'),
    ('b1eb5426-c74a-4f0a-b80a-4d4e561ce6fa', '1f9e6959-2151-4f79-8881-1d213a8ecad1', 'es', 'Planificación y control operacional', '<div>La organización debe establecer, implementar, controlar y mantener los procesos necesarios para satisfacer los requisitos del sistema de gestión ambiental y para implementar las acciones determinadas en los apartados 6.1 y 6.2, mediante:</div><div>— el establecimiento de criterios de operación para los procesos;</div><div>— la implementación del control de los procesos de acuerdo con los criterios de operación.</div><div>NOTA: Los controles pueden incluir controles de ingeniería y procedimientos. Los controles se pueden implementar siguiendo una jerarquía (por ejemplo, de eliminación, de sustitución, administrativa) y se pueden usar solos o combinados.</div><div>La organización debe controlar los cambios planificados y examinar las consecuencias de los cambios no previstos, tomando acciones para mitigar los efectos adversos, cuando sea necesario.</div><div>La organización debe asegurarse de que los procesos contratados externamente estén controlados o que se tenga influencia sobre ellos. Dentro del sistema de gestión ambiental se debe definir el tipo y grado de control o influencia que se va a aplicar a estos procesos.</div><div>En coherencia con la perspectiva del ciclo de vida, la organización debe:</div><div>{clause_8.1.a}</div><div>{clause_8.1.b}</div><div>{clause_8.1.c}</div><div>{clause_8.1.d}</div><div>La organización debe mantener la información documentada en la medida necesaria para tener la confianza en que los procesos se han llevado a cabo según lo planificado.</div>'),
    ('157814cc-8f0b-4ac8-875a-4e6cc3fb7ac8', '1e9e67c6-015e-4a3e-b410-c644398ec93e', 'en', '', '<div>a) establish controls, as appropriate, to ensure that its environmental requirement(s) is (are) addressed in the design and development process for the product or service, considering each life cycle stage;</div>'),
    ('2a7835db-d993-459f-8fa4-0e0fb0fb5cdf', '1e9e67c6-015e-4a3e-b410-c644398ec93e', 'es', '', '<div>a) establecer los controles, según corresponda, para asegurarse de que sus requisitos ambientales se aborden en el proceso de diseño y desarrollo del producto o servicio, considerando cada etapa de su ciclo de vida; </div>'),
    ('81eb180b-f1f1-444f-81f8-975fa871d6df', '219e6c7f-9212-487b-9e4a-67a73c8ecdf7', 'en', '', '<div>b) determine its environmental requirement(s) for the procurement of products and services, as appropriate;</div>'),
    ('8ceb295c-0388-4d18-88ef-6bdcbb71f4c8', '219e6c7f-9212-487b-9e4a-67a73c8ecdf7', 'es', '', '<div>b) determinar sus requisitos ambientales para la compra de productos y servicios, según corresponda;</div>'),
    ('e2418cc2-8757-4ae6-9a04-f592c867e7b6', '209e6aec-a083-40c0-802b-b63a3b8ecc64', 'en', '', '<div>c) communicate its relevant environmental requirement(s) to external providers, including contractors;</div>'),
    ('d7417b71-da44-4f25-9249-cb8dc567e2fd', '209e6aec-a083-40c0-802b-b63a3b8ecc64', 'es', '', '<div>c) comunicar sus requisitos ambientales pertinentes a los proveedores externos, incluidos los contratistas; </div>'),
    ('c945d991-4c82-4285-9f26-952dcccaee75', '239e6fa5-e1ac-4255-92e0-d8ed3e8ed11d', 'en', '', '<div>d) consider the need to provide information about potential significant environmental impacts associated with the transportation or delivery, use, end-of-life treatment and final disposal of its products and services.</div>'),
    ('d445eae2-0d3c-40c6-988b-c4b2bfcad9fe', '239e6fa5-e1ac-4255-92e0-d8ed3e8ed11d', 'es', '', '<div>d) considerar la necesidad de suministrar información acerca de los impactos ambientales potenciales significativos asociados con el transporte o la entrega, el uso, el tratamiento al fin de la vida útil y la disposición final de sus productos o servicios. </div>'),
    ('30496040-a307-418c-9907-a688a92bc254', '229e6e12-8dfb-492a-95dd-7d303d8ecf8a', 'en', 'Emergency preparedness and response', '<div>The organization shall establish, implement and maintain the process(es) needed to prepare for and respond to potential emergency situations identified in 6.1.1.</div><div>The organization shall:</div><div>{clause_8.2.a}</div><div>{clause_8.2.b}</div><div>{clause_8.2.c}</div><div>{clause_8.2.d}</div><div>{clause_8.2.e}</div><div>{clause_8.2.f}</div><div>The organization shall maintain documented information to the extent necessary to have confidence that the process(es) is (are) carried out as planned.</div>'),
    ('4d498de7-879d-486b-a4d4-c1f38e2b97d3', '229e6e12-8dfb-492a-95dd-7d303d8ecf8a', 'es', 'Preparación y respuesta ante emergencias', '<div>La organización debe establecer, implementar y mantener los procesos necesarios acerca de cómo prepararse y responder a situaciones potenciales de emergencia identificadas en el apartado 6.1.1.</div><div>La organización debe:</div><div>{clause_8.2.a}</div><div>{clause_8.2.b}</div><div>{clause_8.2.c}</div><div>{clause_8.2.d}</div><div>{clause_8.2.e}</div><div>{clause_8.2.f}</div><div>La organización debe mantener la información documentada en la medida necesaria para tener confianza en que los procesos se llevan a cabo de la manera planificada. </div>'),
    ('9c1cffbf-9800-47b3-8a6f-330b8e3fef2b', '259e72cb-6bb9-4d57-ae94-db53308ebb13', 'en', '', '<div>a) prepare to respond by planning actions to prevent or mitigate adverse environmental impacts from emergency situations;</div>'),
    ('af1d1da8-a559-4664-9cd8-43309940007c', '259e72cb-6bb9-4d57-ae94-db53308ebb13', 'es', '', '<div>a) prepararse para responder, mediante la planificación de acciones para prevenir o mitigar los impactos ambientales adversos provocados por situaciones de emergencia;</div>'),
    ('2f6cb616-0f2d-469a-b89d-ff5e7db72762', '249e7138-db8c-4b6c-b413-0e362f8eb980', 'en', '', '<div>b) respond to actual emergency situations;</div>'),
    ('2c6cb15d-ba21-4dc1-9f79-7ab172b71611', '249e7138-db8c-4b6c-b413-0e362f8eb980', 'es', '', '<div>b) responder a situaciones de emergencia reales;</div>'),
    ('798ef250-964b-4624-9500-1438f7d3cd8c', 'b79b870a-9316-4d2e-8b8a-f100328c7fa2', 'en', '', '<div>c) take action to prevent or mitigate the consequences of emergency situations, appropriate to the magnitude of the emergency and the potential environmental impact;</div>'),
    ('768eed97-a23d-4973-a103-fb430cd3ee9b', 'b79b870a-9316-4d2e-8b8a-f100328c7fa2', 'es', '', '<div>c) tomar acciones para prevenir o mitigar las consecuencias de las situaciones de emergencia, apropiadas a la magnitud de la emergencia y al impacto ambiental potencial;</div>'),
    ('13293c61-6336-4d9d-8e50-109daeccd18d', 'b89b889d-99bb-4a69-9cc3-cfbd338c8135', 'en', '', '<div>d) periodically test the planned response actions, where practicable;</div>'),
    ('fe291b52-d628-490e-afa2-b30291cca3e6', 'b89b889d-99bb-4a69-9cc3-cfbd338c8135', 'es', '', '<div>d) poner a prueba periódicamente las acciones de respuesta planificadas, cuando sea factible;</div>'),
    ('ec248ad2-f102-43fe-b185-bf823710254e', 'b59b83e4-cbbe-4674-9014-a14a308c7c7c', 'en', '', '<div>e) periodically review and revise the process(es) and planned response actions, in particular after the occurrence of emergency situations or tests;</div>'),
    ('0124abe1-bf09-44ed-9033-1d1d24100765', 'b59b83e4-cbbe-4674-9014-a14a308c7c7c', 'es', '', '<div>e) evaluar y revisar periódicamente los procesos y las acciones de respuesta planificadas, en particular, después de que hayan ocurrido situaciones de emergencia o de que se hayan realizado pruebas</div>'),
    ('3e8a4f9b-a70c-40a7-bf60-284f171a1477', 'b69b8577-247b-493f-8896-d637318c7e0f', 'en', '', '<div>f) provide relevant information and training related to emergency preparedness and response, as appropriate, to relevant interested parties, including persons working under its control.</div>'),
    ('298a2e8c-adc6-4a40-aab6-c5ac1a1a1930', 'b69b8577-247b-493f-8896-d637318c7e0f', 'es', '', '<div>f) proporcionar información y formación pertinentes, con relación a la preparación y respuesta ante emergencias, según corresponda, a las partes interesadas pertinentes, incluidas las personas que trabajan bajo su control. </div>'),
    ('5f5d0a9c-92a2-4d40-970b-419c10291d00', 'b39b80be-2051-4cda-a235-15142e8c7956', 'en', 'Performance evaluation', '<div>{clause_9.1}</div><div>{clause_9.2}</div><div>{clause_9.3}</div>'),
    ('545cf94b-8be8-43a7-9305-5b1f2d294aa7', 'b39b80be-2051-4cda-a235-15142e8c7956', 'es', 'Evaluación del desempeño', '<div>{clause_9.1}</div><div>{clause_9.2}</div><div>{clause_9.3}</div>'),
    ('d8d012dd-075c-4329-bbcb-fbb1a9259651', 'b49b8251-7363-4245-a26e-7af12f8c7ae9', 'en', 'Monitoring, measurement, analysis and evaluation', '<div>{clause_9.1.1}</div><div>{clause_9.1.2}</div>'),
    ('dbd01796-150b-4d32-94f0-805eb425a7a2', 'b49b8251-7363-4245-a26e-7af12f8c7ae9', 'es', 'Seguimiento, medición, análisis y evaluación', '<div>{clause_9.1.1}</div><div>{clause_9.1.2}</div>'),
    ('d3cf3b5e-319e-4c7a-84c8-8be6c49bb282', 'b19b7d98-4859-4930-b33f-057e2c8c7630', 'en', 'General', '<div>The organization shall monitor, measure, analyse and evaluate its environmental performance.</div><div>The organization shall determine:</div><div>{clause_9.1.1.a}</div><div>{clause_9.1.1.b}</div><div>{clause_9.1.1.c}</div><div>{clause_9.1.1.d}</div><div>{clause_9.1.1.e}</div><div>The organization shall ensure that calibrated or verified monitoring and measurement equipment is used and maintained, as appropriate.</div><div>The organization shall evaluate its environmental performance and the effectiveness of the environmental management system.</div><div>The organization shall communicate relevant environmental performance information both internally and externally, as identified in its communication process(es) and as required by its compliance obligations.</div><div>The organization shall retain appropriate documented information as evidence of the monitoring, measurement, analysis and evaluation results.</div>'),
    ('e0cf4fd5-f5de-48a1-95bc-1849b99ba131', 'b19b7d98-4859-4930-b33f-057e2c8c7630', 'es', 'Generalidades', '<div>La organización debe hacer seguimiento, medir, analizar y evaluar su desempeño ambiental.</div><div>La organización debe determinar: </div><div>{clause_9.1.1.a}</div><div>{clause_9.1.1.b}</div><div>{clause_9.1.1.c}</div><div>{clause_9.1.1.d}</div><div>{clause_9.1.1.e}</div><div>La organización debe asegurarse de que se usan y mantienen equipos de seguimiento y medición calibrados o verificados, según corresponda.</div><div>La organización debe evaluar su desempeño ambiental y la eficacia del sistema de gestión ambiental.</div><div>La organización debe comunicar externa e internamente la información pertinente a su desempeño ambiental, según esté identificado en sus procesos de comunicación y como se exija en sus requisitos legales y otros requisitos.</div><div>La organización debe conservar información documentada apropiada como evidencia de los resultados del seguimiento, la medición, el análisis y la evaluación.</div>'),
    ('7e0580c7-7727-4b93-8104-705361cc67cb', 'b29b7f2b-23c9-486b-9c25-8ebb2d8c77c3', 'en', '', '<div>a) what needs to be monitored and measured;</div>'),
    ('61055320-86fc-4644-aa02-b0686ccc791c', 'b29b7f2b-23c9-486b-9c25-8ebb2d8c77c3', 'es', '', '<div>a) qué necesita seguimiento y medición;</div>'),
    ('34457678-9ac9-49ec-abed-cd207cb6a7f4', 'af9b7a72-622b-4756-8805-14283a8c8c3a', 'en', '', '<div>b) the methods for monitoring, measurement, analysis and evaluation, as applicable, to ensure valid results;</div>'),
    ('41458aef-7f5f-40cb-9b85-a75b61b67d73', 'af9b7a72-622b-4756-8805-14283a8c8c3a', 'es', '', '<div>b) los métodos de seguimiento, medición, análisis y evaluación, según corresponda, para asegurar resultados válidos;</div>'),
    ('780be469-2fcd-4b65-918a-5ea51629e295', 'b09b7c05-1026-46d1-b789-e7053b8c8dcd', 'en', '', '<div>c) the criteria against which the organization will evaluate its environmental performance, and appropriate indicators;</div>'),
    ('730bdc8a-c393-4226-87e0-96ba0929ce1e', 'b09b7c05-1026-46d1-b789-e7053b8c8dcd', 'es', '', '<div>c) los criterios contra los cuales la organización evaluará su desempeño ambiental, y los indicadores apropiados;</div>'),
    ('f41e51a9-a09f-4939-93d2-0de58fc1e6d5', 'b1993f01-05ba-45f5-b90d-7ec52c8a3799', 'en', '', '<div>d) when the monitoring and measuring shall be performed;</div>'),
    ('ef1e49ca-0d9d-4662-a0e1-dcfa82c1d25e', 'b1993f01-05ba-45f5-b90d-7ec52c8a3799', 'es', '', '<div>d) cuándo se deben llevar a cabo el seguimiento y la medición; </div>'),
    ('addd7ab8-4376-4010-9e8e-0960f8c91534', 'b0993d6e-c828-454a-9796-b7e82b8a3606', 'en', '', '<div>e) when the results from monitoring and measurement shall be analysed and evaluated.</div>'),
    ('badd8f2f-e09d-42d7-a404-9c9bddc8eab3', 'b0993d6e-c828-454a-9796-b7e82b8a3606', 'es', '', '<div>e) cuándo se deben analizar y evaluar los resultados del seguimiento y la medición.</div>'),
    ('1f7f64e3-8a32-40e3-a55c-6317f80f29bf', 'af993bdb-cc3f-449b-ac6b-be7f2a8a3473', 'en', 'Evaluation of compliance', '<div>The organization shall establish, implement and maintain the process(es) needed to evaluate fulfilment of its compliance obligations.</div><div>The organization shall:</div><div>{clause_9.1.2.a}</div><div>{clause_9.1.2.b}</div><div>{clause_9.1.2.c}</div><div>The organization shall retain documented information as evidence of the compliance evaluation result(s).</div>'),
    ('1a7f5d04-f132-4d34-b63b-d1e40b0f47a8', 'af993bdb-cc3f-449b-ac6b-be7f2a8a3473', 'es', 'Evaluación del cumplimiento', '<div>La organización debe establecer, implementar y mantener los procesos necesarios para evaluar el cumplimiento de sus requisitos legales y otros requisitos</div><div>La organización debe:</div><div>{clause_9.1.2.a}</div><div>{clause_9.1.2.b}</div><div>{clause_9.1.2.c}</div><div>La organización debe conservar información documentada como evidencia de los resultados de la evaluación del cumplimiento. </div>'),
    ('ed19d27a-9a00-440a-aa99-8f8a8b5ee016', 'ae993a48-d835-43e0-a2aa-fef2298a32e0', 'en', '', '<div>a) determine the frequency that compliance will be evaluated;</div>'),
    ('d219a7f9-a266-4611-9053-8e55885edb5d', 'ae993a48-d835-43e0-a2aa-fef2298a32e0', 'es', '', '<div>a) determinar la frecuencia con la que se evaluará el cumplimiento; </div>'),
    ('b9c52825-6827-442d-a508-21f98aba0f59', 'b599454d-2c11-4e19-a9d9-9bd9308a3de5', 'en', '', '<div>b) evaluate compliance and take action if needed;</div>'),
    ('ccc5460e-80d3-4e3e-84e0-68b6a5ba39da', 'b599454d-2c11-4e19-a9d9-9bd9308a3de5', 'es', '', '<div>b) evaluar el cumplimiento y emprender las acciones que fueran necesarias; </div>'),
    ('2051ed84-bbf8-4734-9924-f7e4111e64a8', 'b49943ba-256d-40de-a793-555c2f8a3c52', 'en', '', '<div>c) maintain knowledge and understanding of its compliance status.</div>'),
    ('2551f563-54f9-4ae3-8845-8917fe1e46bf', 'b49943ba-256d-40de-a793-555c2f8a3c52', 'es', '', '<div>c) mantener el conocimiento y la comprensión de su estado de cumplimiento.</div>'),
    ('d2f20c4f-4051-49b7-b5df-70bbb6198f93', 'b3994227-ca76-4c6f-89a0-94232e8a3abf', 'en', 'Internal audit', '<div>{clause_9.2.1}</div><div>{clause_9.2.2}</div>'),
    ('c5f1f7d8-a0b0-4df0-bd0c-f680d119ba14', 'b3994227-ca76-4c6f-89a0-94232e8a3abf', 'es', 'Auditoría interna', '<div>{clause_9.2.1}</div><div>{clause_9.2.2}</div>'),
    ('b4c2bda6-80ca-4a8e-b83a-b7ce8590956a', 'b2994094-424d-4c24-a5d5-52862d8a392c', 'en', 'General', '<div>The organization shall conduct internal audits at planned intervals to provide information on whether the environmental management system:</div><div>{clause_9.2.1.a}</div><div>{clause_9.2.1.b}</div>'),
    ('d1c2eb4d-0dd7-4f1d-9d8b-b3018a909d49', 'b2994094-424d-4c24-a5d5-52862d8a392c', 'es', 'Generalidades', '<div>La organización debe llevar a cabo auditorías internas a intervalos planificados para proporcionar información acerca de si el sistema de gestión ambiental:</div><div>{clause_9.2.1.a}</div><div>{clause_9.2.1.b}</div>'),
    ('8cc140a1-4d57-4b01-9f1a-2fdd2addabcd', 'a9993269-dae4-4cbd-bdb6-eb7d348a4431', 'en', '', '<div>a) conforms to:</div><ul><li>{clause_9.2.1.a.1}</li><li>{clause_9.2.1.a.2}</li></ul>'),
    ('77c11f92-8917-41da-add9-b9420ddd7e26', 'a9993269-dae4-4cbd-bdb6-eb7d348a4431', 'es', '', '<div>a) es conforme con:</div><ul><li>{clause_9.2.1.a.1}</li><li>{clause_9.2.1.a.2}</li></ul>'),
    ('f59fcc90-19c1-4638-bc49-b778716a3ecc', 'a89930d6-811d-46f2-a602-cfc0338a429e', 'en', '', '<div>1) the organization’s own requirements for its environmental management system;</div>'),
    ('f29fc7d7-1e48-42ef-b21f-4083866a5fdb', 'a89930d6-811d-46f2-a602-cfc0338a429e', 'es', '', '<div>1) los requisitos propios de la organización para su sistema de gestión ambiental;</div>'),
    ('e2b9e04a-e999-485a-bbda-d77a94a40d66', 'ab96f6f8-e09f-423c-ab41-25022687ef90', 'en', '', '<div>2) the requirements of this International Standard;</div>'),
    ('e7b9e829-add8-4181-aecb-0865b1a43b0d', 'ab96f6f8-e09f-423c-ab41-25022687ef90', 'es', '', '<div>2) los requisitos de esta Norma Internacional; </div>'),
    ('1342da73-3345-4973-aab0-5947b54c320f', 'ac96f88b-6f7b-4fe7-861e-630f2787f123', 'en', '', '<div>b) is effectively implemented and maintained.</div>'),
    ('2e4304f4-2753-4624-b890-5234a84c1d98', 'ac96f88b-6f7b-4fe7-861e-630f2787f123', 'es', '', '<div>b) se implementa y mantiene eficazmente.</div>'),
    ('e1a15508-dcbb-4920-aaac-669002ac1344', 'ad96fa1e-c091-4a76-bd07-d2b82887f2b6', 'en', 'Internal audit programme', '<div>The organization shall establish, implement and maintain (an) internal audit programme(s), including the frequency, methods, responsibilities, planning requirements and reporting of its internal audits.</div><div>When establishing the internal audit programme, the organization shall take into consideration the environmental importance of the processes concerned, changes affecting the organization and the results of previous audits.</div><div>The organization shall:</div><div>{clause_9.2.2.a}</div><div>{clause_9.2.2.b}</div><div>{clause_9.2.2.c}</div><div>The organization shall retain documented information as evidence of the implementation of the audit programme and the audit results.</div>'),
    ('cea1371f-d601-4f87-a70e-b06b07ac1b23', 'ad96fa1e-c091-4a76-bd07-d2b82887f2b6', 'es', 'Programa de auditoría interna', '<div>La organización debe establecer, implementar y mantener uno o varios programas de auditoría interna que incluyan la frecuencia, los métodos, las responsabilidades, los requisitos de planificación y la elaboración de informes de sus auditorías internas.</div><div>Cuando se establezca el programa de auditoría interna, la organización debe tener en cuenta la importancia ambiental de los procesos involucrados, los cambios que afectan a la organización y los resultados de las auditorías previas. </div><div>La organización debe:</div><div>{clause_9.2.2.a}</div><div>{clause_9.2.2.b}</div><div>{clause_9.2.2.c}</div><div>La organización debe conservar información documentada como evidencia de la implementación del programa de auditoría y de los resultados de ésta.</div>'),
    ('5b3b6cb9-6424-4909-9a24-8d9599a4e4e5', 'ae96fbb1-9b7e-4e71-810d-21d52987f449', 'en', '', '<div>a) define the audit criteria and scope for each audit;</div>'),
    ('763b973a-744e-4c12-9be8-62caaca502ce', 'ae96fbb1-9b7e-4e71-810d-21d52987f449', 'es', '', '<div>a) definir los criterios de auditoría y el alcance para cada auditoría;</div>'),
    ('e8882af6-d3ac-4d5e-ae7f-af3ecf73f83a', 'af96fd44-935a-4fd8-b8d0-bd562a87f5dc', 'en', '', '<div>b) select auditors and conduct audits to ensure objectivity and the impartiality of the audit process;</div>'),
    ('e588263d-9f37-424d-8ae3-ad11b473cdb9', 'af96fd44-935a-4fd8-b8d0-bd562a87f5dc', 'es', '', '<div>b) seleccionar los auditores y llevar a cabo auditorías para asegurarse de la objetividad y la imparcialidad del proceso de auditoría; </div>'),
    ('c617b11f-471d-4587-acb3-4b6bff5f21a3', 'b096fed7-ec3e-4213-8681-b1f32b87f76f', 'en', '', '<div>c) ensure that the results of the audits are reported to relevant management.</div>'),
    ('d917cf08-4dd7-4f20-b051-0190fa5f19c4', 'b096fed7-ec3e-4213-8681-b1f32b87f76f', 'es', '', '<div>c) asegurarse de que los resultados de las auditorías se informen a la dirección pertinente. </div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('c6d00994-0edb-4a04-b99b-6ad49037a078', 'b197006a-6679-4b62-90cc-936c2c87f902', 'en', 'Management review', '<div>Top management shall review the organization’s environmental management system, at planned intervals, to ensure its continuing suitability, adequacy and effectiveness.</div><div>The management review shall include consideration of:</div><div>{clause_9.3.a}</div><div>{clause_9.3.b}</div><div>{clause_9.3.c}</div><div>{clause_9.3.d}</div><div>{clause_9.3.e}</div><div>{clause_9.3.f}</div><div>{clause_9.3.g}</div><div>The outputs of the management review shall include:</div><div>— conclusions on the continuing suitability, adequacy and effectiveness of the environmental management system;</div><div>— decisions related to continual improvement opportunities;</div><div>— decisions related to any need for changes to the environmental management system, including resources;</div><div>— actions, if needed, when environmental objectives have not been achieved;</div><div>— opportunities to improve integration of the environmental management system with other business processes, if needed;</div><div>— any implications for the strategic direction of the organization.</div><div>The organization shall retain documented information as evidence of the results of management reviews.</div>'),
    ('abcfdf13-0180-4853-9714-1d679d37b4ef', 'b197006a-6679-4b62-90cc-936c2c87f902', 'es', 'Revisión por la dirección', '<div>La alta dirección debe revisar el sistema de gestión ambiental de la organización a intervalos planificados, para asegurarse de su conveniencia, adecuación y eficacia continuas.</div><div>La revisión por la dirección debe incluir consideraciones sobre:</div><div>{clause_9.3.a}</div><div>{clause_9.3.b}</div><div>{clause_9.3.c}</div><div>{clause_9.3.d}</div><div>{clause_9.3.e}</div><div>{clause_9.3.f}</div><div>{clause_9.3.g}</div><div>Las salidas de la revisión por la dirección deben incluir:</div><div>— las conclusiones sobre la conveniencia, adecuación y eficacia continuas del sistema de gestión ambiental;</div><div>— las decisiones relacionadas con las oportunidades de mejora continua;</div><div>— las decisiones relacionadas con cualquier necesidad de cambio en el sistema de gestión ambiental, incluidas los recursos;</div><div>— las acciones necesarias cuando no se hayan logrado los objetivos ambientales;</div><div>— las oportunidades de mejorar la integración del sistema de gestión ambiental a otros procesos de negocio, si fuera necesario;</div><div>— cualquier implicación para la dirección estratégica de la organización. </div><div>La organización debe conservar información documentada como evidencia de los resultados de las revisiones por la dirección.</div>'),
    ('ece99eb5-d899-44fd-b295-6ea9d3fe0e69', 'b29701fd-c0de-41ed-9389-be692d87fa95', 'en', '', '<div>a) the status of actions from previous management reviews;</div>'),
    ('dfe98a3e-4eb7-49ee-ac71-7ec6cefe068a', 'b29701fd-c0de-41ed-9389-be692d87fa95', 'es', '', '<div>a) el estado de las acciones de las revisiones por la dirección previas;</div>'),
    ('9b5b6ea2-c051-44a2-961b-36722fc1655e', 'a396ea60-27a8-4d94-868e-52da2e87fc28', 'en', '', '<div>b) changes in:</div><ul><li>{clause_9.3.b.1}</li><li>{clause_9.3.b.2}</li><li>{clause_9.3.b.3}</li><li>{clause_9.3.b.4}</li></ul>'),
    ('905b5d51-6ca2-4f79-b6cf-abed3cc179d5', 'a396ea60-27a8-4d94-868e-52da2e87fc28', 'es', '', '<div>b) los cambios en:</div><ul><li>{clause_9.3.b.1}</li><li>{clause_9.3.b.2}</li><li>{clause_9.3.b.3}</li><li>{clause_9.3.b.4}</li></ul>'),
    ('abe5c96b-e257-46fb-af33-43bfd9f7aac7', 'a496ebf3-afd1-4ddf-b9a6-8e472f87fdbb', 'en', '', '<div>1) external and internal issues that are relevant to the environmental management system;</div>'),
    ('b6e5dabc-41e4-42fc-8c8c-3f3cbcf77d20', 'a496ebf3-afd1-4ddf-b9a6-8e472f87fdbb', 'es', '', '<div>1) las cuestiones externas e internas que sean pertinentes al sistema de gestión ambiental;</div>'),
    ('33ef8dd3-1cb7-419f-b917-baa769c89997', 'a594aeef-2705-4b5b-af8a-2faf40ace957', 'en', '', '<div>2) the needs and expectations of interested parties, including compliance obligations;</div>'),
    ('4eefb854-d22f-46c8-bfca-5b146cc89e50', 'a594aeef-2705-4b5b-af8a-2faf40ace957', 'es', '', '<div>2) las necesidades y expectativas de las partes interesadas, incluidos los requisitos legales y otros requisitos; </div>'),
    ('00ec2aaa-b765-4976-b9ae-485a89bd176e', 'a494ad5c-3577-46a0-8ad8-8fa23face7c4', 'en', '', '<div>3) its significant environmental aspects;</div>'),
    ('05ec3289-c9f7-4515-9e95-ffc576bcf985', 'a494ad5c-3577-46a0-8ad8-8fa23face7c4', 'es', '', '<div>3) sus aspectos ambientales significativos; </div>'),
    ('06141199-f812-4595-ae87-8df58e201e2d', 'a794b215-607f-4cb5-8254-f6f542acec7d', 'en', '', '<div>4) risks and opportunities;</div>'),
    ('21143c1a-e57f-49f6-a5c9-e0aa711ff086', 'a794b215-607f-4cb5-8254-f6f542acec7d', 'es', '', '<div>4) los riesgos y oportunidades;</div>'),
    ('8ef462e8-75fa-409c-bf08-1a70d7271a2c', 'a694b082-3c3a-410a-baf3-125841aceaea', 'en', '', '<div>c) the extent to which environmental objectives have been achieved;</div>'),
    ('7bf444ff-18e5-4a9b-accd-2e4bec273b3b', 'a694b082-3c3a-410a-baf3-125841aceaea', 'es', '', '<div>c) el grado en el que se han logrado los objetivos ambientales; </div>'),
    ('736abeff-e923-42cb-bd56-384bb47959eb', 'a194a8a3-27b8-4f2f-9f4c-08133cace30b', 'en', '', '<div>d) information on the organization’s environmental performance, including trends in:</div><ul><li>{clause_9.3.d.1}</li><li>{clause_9.3.d.2}</li><li>{clause_9.3.d.3}</li><li>{clause_9.3.d.4}</li></ul>'),
    ('866adce8-048d-4bec-8f91-2470bf796b3c', 'a194a8a3-27b8-4f2f-9f4c-08133cace30b', 'es', '', '<div>d) la información sobre el desempeño ambiental de la organización, incluidas las tendencias relativas a</div><ul><li>{clause_9.3.d.1}</li><li>{clause_9.3.d.2}</li><li>{clause_9.3.d.3}</li><li>{clause_9.3.d.4}</li></ul>'),
    ('06b8e256-2953-4ff2-97d8-559ea3eeff22', 'a094a710-b8da-40e4-8569-b9f63bace178', 'en', '', '<div>1) nonconformities and corrective actions;</div>'),
    ('03b8dd9d-ffdd-47e9-8dd0-19f198eeedd1', 'a094a710-b8da-40e4-8569-b9f63bace178', 'es', '', '<div>1) no conformidades y acciones correctivas;</div>'),
    ('0d965215-eaed-46e1-8e97-cf09887a75f1', 'a394abc9-a025-4cd9-9d3d-aa093eace631', 'en', '', '<div>2) monitoring and measurement results;</div>'),
    ('00963d9e-4274-48ba-9479-6aa6937a8742', 'a394abc9-a025-4cd9-9d3d-aa093eace631', 'es', '', '<div>2) resultados de seguimiento y medición;</div>'),
    ('74231774-8f23-4a98-a40a-6534f1f865a0', 'a294aa36-997f-4c9e-b7c4-f70c3dace49e', 'en', '', '<div>3) fulfilment of its compliance obligations;</div>'),
    ('5922ecf3-7d8b-41cf-962a-6c470ef89347', 'a294aa36-997f-4c9e-b7c4-f70c3dace49e', 'es', '', '<div>3) cumplimiento de los requisitos legales y otros requisitos;</div>'),
    ('5938d74b-ca43-4617-89d2-a59fceab419f', 'ad94bb87-7d71-4863-98fe-056738acdcbf', 'en', '', '<div>4) audit results;</div>'),
    ('6438e89c-2aa2-4a50-8dd8-8c1ce1ab5f88', 'ad94bb87-7d71-4863-98fe-056738acdcbf', 'es', '', '<div>4) resultados de las auditorías;</div>'),
    ('bc082202-f958-4b6e-adad-03d2f11bbb76', 'ac94b9f4-0e6d-4aa8-b72f-01fa37acdb2c', 'en', '', '<div>e) adequacy of resources;</div>'),
    ('b10810b1-833a-467d-8f9c-09cdee1bb6bd', 'ac94b9f4-0e6d-4aa8-b72f-01fa37acdb2c', 'es', '', '<div>e) adecuación de los recursos;</div>'),
    ('d8eaab2c-3157-4fe8-8148-c5cc987681b0', '1f919d66-2234-463a-b057-14e43aaaa14e', 'en', '', '<div>f) relevant communication(s) from interested parties, including complaints;</div>'),
    ('edeacc3b-7963-4ebf-997a-ae6f95767cf7', '1f919d66-2234-463a-b057-14e43aaaa14e', 'es', '', '<div>f) las comunicaciones pertinentes de las partes interesadas, incluidas las quejas;</div>'),
    ('8fe3af2d-165c-44b1-81a3-6f61bc3e5041', '20919ef9-5bfb-49a5-8008-23413baaa2e1', 'en', '', '<div>g) opportunities for continual improvement</div>'),
    ('72e38186-f7d8-4d2a-a511-cb2ea73e2f32', '20919ef9-5bfb-49a5-8008-23413baaa2e1', 'es', '', '<div>g) las oportunidades de mejora continua;</div>'),
    ('8b80a86e-afb3-4902-95a4-3d9697b407b2', '1d919a40-1ad2-4810-bd41-180e38aa9e28', 'en', 'Improvement', '<div>{clause_10.1}</div><div>{clause_10.2}</div><div>{clause_10.3}</div>'),
    ('78808a85-45e4-4b59-941b-ddd9acb428c1', '1d919a40-1ad2-4810-bd41-180e38aa9e28', 'es', 'Mejora', '<div>{clause_10.1}</div><div>{clause_10.2}</div><div>{clause_10.3}</div>'),
    ('6b8c2a97-d1b7-485b-bd27-dec3ea19cc7b', '1e919bd3-0c61-4fcb-ba91-568b39aa9fbb', 'en', 'General', '<div>The organization shall determine opportunities for improvement (see 9.1, 9.2 and 9.3) and implement necessary actions to achieve the intended outcomes of its environmental management system.</div>'),
    ('6e8c2f50-4a93-4c5c-b123-f7b8d519ab6c', '1e919bd3-0c61-4fcb-ba91-568b39aa9fbb', 'es', 'Generalidades', '<div>La organización debe determinar las oportunidades de mejora (véanse 9.1, 9.2 y 9.3) e implementar las acciones necesarias para lograr los resultados previstos en su sistema de gestión ambiental. </div>'),
    ('f3bbf6a0-aa46-4d2c-aff8-eee87e4499fc', '2391a3b2-7bae-448e-94f7-68503eaaa79a', 'en', 'Nonconformity and corrective action', '<div>When a nonconformity occurs, the organization shall:</div><div>{clause_10.2.a}</div><div>{clause_10.2.b}</div><div>{clause_10.2.c}</div><div>{clause_10.2.d}</div><div>{clause_10.2.e}</div><div>Corrective actions shall be appropriate to the significance of the effects of the nonconformities encountered, including the environmental impact(s).</div><div>The organization shall retain documented information as evidence of:</div><div>— the nature of the nonconformities and any subsequent actions taken;</div><div>— the results of any corrective action</div>'),
    ('10bc2447-8edc-440b-86fa-aed3734488ab', '2391a3b2-7bae-448e-94f7-68503eaaa79a', 'es', 'No conformidad y acción correctiva', '<div>Cuando ocurra una no conformidad, la organización debe: </div><div>{clause_10.2.a}</div><div>{clause_10.2.b}</div><div>{clause_10.2.c}</div><div>{clause_10.2.d}</div><div>{clause_10.2.e}</div><div>Las acciones correctivas deben ser apropiadas a la importancia de los efectos de las no conformidades encontradas, incluidos los impactos ambientales.</div><div>La organización debe conservar información documentada como evidencia de:</div><div>— la naturaleza de las no conformidades y cualquier acción tomada posteriormente, y</div><div>— los resultados de cualquier acción correctiva.</div>'),
    ('8a3e06f1-d72a-4ba5-a24a-280d81e526bd', '2491a545-8580-4e49-8c24-660d3faaa92d', 'en', '', '<div>a) react to the nonconformity and, as applicable:</div><ul><li>{clause_10.2.a.1}</li><li>{clause_10.2.a.2}</li></ul>'),
    ('953e1842-843d-4766-aa05-521284e52b76', '2491a545-8580-4e49-8c24-660d3faaa92d', 'es', '', '<div>a) reaccionar ante la no conformidad, y cuando sea aplicable:</div><ul><li>{clause_10.2.a.1}</li><li>{clause_10.2.a.2}</li></ul>'),
    ('a5b29022-11fd-4106-8b7b-b3f27ce2bc3e', '2191a08c-9e36-4554-8837-6c5a3caaa474', 'en', '', '<div>1) take action to control and correct it;</div>'),
    ('9ab27ed1-4ecb-4cc5-ac30-296d89e2d0b5', '2191a08c-9e36-4554-8837-6c5a3caaa474', 'es', '', '<div>1) tomar acciones para controlarla y corregirla; </div>'),
    ('b63ceaeb-7c97-4a6f-a493-c13f9ced1027', '2291a21f-0d13-409f-bb4f-a7c73daaa607', 'en', '', '<div>2) deal with the consequences, including mitigating adverse environmental impacts;</div>'),
    ('c13cfc3c-7810-4db8-81ec-bcbc7fece280', '2291a21f-0d13-409f-bb4f-a7c73daaa607', 'es', '', '<div>2) hacer frente a las consecuencias, incluida la mitigación de los impactos ambientales adversos;</div>'),
    ('d1272b14-8b4d-4480-aefb-e854dd5a8a58', '2791a9fe-c13f-4222-9275-acec32aa94b6', 'en', '', '<div>b) evaluate the need for action to eliminate the causes of the nonconformity, in order that it does not recur or occur elsewhere, by:</div><ul><li>{clause_10.2.b.1}</li><li>{clause_10.2.b.2}</li><li>{clause_10.2.b.3}</li></ul>'),
    ('b6270093-821b-44e7-8c74-9ae7ea5a9ecf', '2791a9fe-c13f-4222-9275-acec32aa94b6', 'es', '', '<div>b) evaluar la necesidad de acciones para eliminar las causas de la no conformidad, con el fin de que no vuelva a ocurrir en ese mismo lugar ni ocurra en otra parte, mediante:</div><ul><li>{clause_10.2.b.1}</li><li>{clause_10.2.b.2}</li><li>{clause_10.2.b.3}</li></ul>'),
    ('f740c035-5645-4e69-a7f5-ec2996f506c9', '2891ab91-34f1-4dad-9532-d7e933aa9649', 'en', '', '<div>1) reviewing the nonconformity;</div>'),
    ('ea40abbe-7fbb-4672-a1d1-fc4691f4feea', '2891ab91-34f1-4dad-9532-d7e933aa9649', 'es', '', '<div>1) la revisión de la no conformidad; </div>'),
    ('d6245ea8-5a19-47dc-bc34-bfb0861b8cfc', '952dcfc2-8258-438a-a53a-d718b06de31a', 'en', '', '<div>2) determining the causes of the nonconformity;</div>'),
    ('c32440bf-e13e-43db-a9cb-af8b7b1b7bab', '952dcfc2-8258-438a-a53a-d718b06de31a', 'es', '', '<div>2) la determinación de las causas de la no conformidad; </div>'),
    ('4fc00959-c32c-45d5-b828-373589bc19bd', '962dd155-a69d-4f35-80a9-fbb5b16de4ad', 'en', '', '<div>3) determining if similar nonconformities exist, or could potentially occur;</div>'),
    ('6ac033da-c9e5-4c36-8a50-56ea8cbc1e76', '962dd155-a69d-4f35-80a9-fbb5b16de4ad', 'es', '', '<div>3) la determinación de si existen no conformidades similares, o que potencialmente puedan ocurrir;</div>'),
    ('4a968f6a-f1c2-44b6-8ef8-839a84b9af3e', '932dcc9c-7b94-4920-bf32-4162ae6ddff4', 'en', '', '<div>c) implement any action needed;</div>'),
    ('4f969749-eb09-4e55-bbb8-ad0591b9c3b5', '932dcc9c-7b94-4920-bf32-4162ae6ddff4', 'es', '', '<div>c) implementar cualquier acción necesaria;</div>'),
    ('7b1f8993-a864-46df-8278-b9e7a4c40327', '942dce2f-6d22-4ddb-b63f-4e6faf6de187', 'en', '', '<div>d) review the effectiveness of any corrective action taken;</div>'),
    ('961fb414-6058-4808-a500-075487c3d580', '942dce2f-6d22-4ddb-b63f-4e6faf6de187', 'es', '', '<div>d) revisar la eficacia de cualquier acción correctiva tomada; y</div>'),
    ('bdcf0f34-1ad1-42d8-888d-8174a04d74b0', '912dc976-df9d-4f1e-94d0-7fccac6ddcce', 'en', '', '<div>e) make changes to the environmental management system, if necessary</div>'),
    ('a2cee4b3-0bb3-400f-a38b-6b879d4d6ff7', '912dc976-df9d-4f1e-94d0-7fccac6ddcce', 'es', '', '<div>e) si fuera necesario, hacer cambios al sistema de gestión ambiental. </div>'),
    ('54c7e0d5-cf0e-4121-a6f3-1049c4154341', '922dcb09-e643-4f59-9b20-8fc9ad6dde61', 'en', 'Continual improvement', '<div>The organization shall continually improve the suitability, adequacy and effectiveness of the environmental management system to enhance environmental performance.</div>'),
    ('47c7cc5e-0acd-44fa-95ff-83e6af152232', '922dcb09-e643-4f59-9b20-8fc9ad6dde61', 'es', 'Mejora continua', '<div>La organización debe mejorar continuamente la conveniencia, adecuación y eficacia del sistema de gestión ambiental para mejorar el desempeño ambiental.</div>'),
    ('91c4e372-686c-482e-b611-d522bdbb9416', '1e23c6b4-8a6f-45b0-8d3b-55aa2f3789fc', 'en', 'Scope', '<div>This document specifies requirements for an occupational health and safety (OH&amp;S) management system, and gives guidance for its use, to enable organizations to provide safe and healthy workplaces by preventing work-related injury and ill health, as well as by proactively improving its OH&amp;S performance.</div><div>This document is applicable to any organization that wishes to establish, implement and maintain an OH&amp;S management system to improve occupational health and safety, eliminate hazards and minimize OH&amp;S risks (including system deficiencies), take advantage of OH&amp;S opportunities, and address OH&amp;S management system nonconformities associated with its activities.</div><div>This document helps an organization to achieve the intended outcomes of its OH&amp;S management system. Consistent with the organization’s OH&amp;S policy, the intended outcomes of an OH&amp;S management system include:</div><div>{clause_1.a}</div><div>{clause_1.b}</div><div>{clause_1.c}</div><div>This document is applicable to any organization regardless of its size, type and activities. It is applicable to the OH&amp;S risks under the organization’s control, taking into account factors such as the context in which the organization operates and the needs and expectations of its workers and other interested parties.</div><div>This document does not state specific criteria for OH&amp;S performance, nor is it prescriptive about the design of an OH&amp;S management system.</div><div>This document enables an organization, through its OH&amp;S management system, to integrate other aspects of health and safety, such as worker wellness/wellbeing.</div><div>This document does not address issues such as product safety, property damage or environmental impacts, beyond the risks to workers and other relevant interested parties.</div><div>This document can be used in whole or in part to systematically improve occupational health and safety management. However, claims of conformity to this document are not acceptable unless all its requirements are incorporated into an organization’s OH&amp;S management system and fulfilled without exclusion.</div>'),
    ('a6c50481-f24e-433d-9e28-dfbdbabb8f5d', '1e23c6b4-8a6f-45b0-8d3b-55aa2f3789fc', 'es', 'Alcance', '<div>Este documento especifica requerimientos para un sistema de administración/gestión de la seguridad y salud en el trabajo (SyST) y proporciona orientación para su uso, para permitir a las organizaciones proporcionar lugares de trabajo seguros y saludables previniendo las lesiones y el deterioro de la salud relacionados con el trabajo, así como mejorando de manera proactiva su desempeño de SyST. </div><div>Este documento es aplicable a cualquier organizaciónque desee establecer, implementar ymantener un sistema de administración/gestión de SyST para mejorar la seguridad y salud en el trabajo, eliminar los peligros y minimizar los riesgos para SyST (incluyendo las deficiencias del sistema), aprovechar las oportunidades para SyST y abordar las no conformidades del sistema de administración/gestión de SyST asociadas a sus actividades.</div><div>Este documento ayuda a una organización a alcanzar los resultados previstos de su sistema de administración/gestión de SyST. En coherencia con la política de SyST de la organización, los resultados previstos de un sistema de administración/gestión de SyST incluyen: </div><div>{clause_1.a}</div><div>{clause_1.b}</div><div>{clause_1.c}</div><div>Este documento es aplicable a cualquier organización sin importar su tamaño, tipo y actividades. Es aplicable a los riesgos para SyST bajo el control de la organización, teniendo en cuenta factores tales como el contexto en el que opera la organización y las necesidades y expectativas de sus trabajadores y otras partes interesadas.</div><div>Este documento no establece criterios específicos para el desempeño de SyST, ni para el diseño de un sistema de administración/gestión de SyST. </div><div>Este documento permite a una organización, mediante su sistema de administración/gestión de SyST, integrar otros aspectos de la seguridad y salud, tales como el bienestar del trabajador. </div><div>Este documento no aborda factores tales como la seguridad del producto, los daños a la propiedad o los impactos ambientales, más allá de los riesgos para los trabajadores y para otras partes interesadas pertinentes.</div><div>Este documento puede ser utilizado total o parcialmente para mejorar de manera sistemática la administración/gestión de la seguridad y salud en el trabajo. Sin embargo, las declaraciones de conformidad con este documento no son aceptables a menos que todos sus requerimientos estén incorporados en el sistema de administración/gestión de SyST de una organización y se cumplan sin exclusión.</div>'),
    ('b64f2c01-367d-4ccd-9c45-d33dc21e9ad5', '2123cb6d-b579-4ec5-ac2a-f09d32378eb5', 'en', '', '<div>a) continual improvement of OH&amp;S performance;</div>'),
    ('a14f0af2-6af1-47de-b42e-c8a2b51e865e', '2123cb6d-b579-4ec5-ac2a-f09d32378eb5', 'es', '', '<div>a) la mejora continua del desempeño de SyST; </div>'),
    ('900e8770-d0c4-4b54-9477-61582b25c934', '2023c9da-6267-495a-885c-446031378d22', 'en', '', '<div>b) fulfilment of legal requirements and other requirements;</div>'),
    ('8d0e82b7-7d69-4e83-a0dd-a16310259eb3', '2023c9da-6267-495a-885c-446031378d22', 'es', '', '<div>b) el cumplimiento de los requerimientos legales y otros requerimientos; </div>'),
    ('96ff7ee7-ddec-4003-90f3-fef3e8764393', '1b23c1fb-6691-45bf-a098-9f9b2c378543', 'en', '', '<div>c) achievement of OH&amp;S objectives.</div>'),
    ('79ff5140-3147-4cd4-8526-e38803766e14', '1b23c1fb-6691-45bf-a098-9f9b2c378543', 'es', '', '<div>c) el logro de los objetivos de SyST.</div>'),
    ('76f52afe-6857-4faa-b6a5-4e06b7ed496a', '1a23c068-0dd4-42f4-b76b-475e2b3783b0', 'en', 'Normative references', '<div>There are no normative references in this document.</div>'),
    ('83f53f75-86db-4731-84fc-a2e9bced5149', '1a23c068-0dd4-42f4-b76b-475e2b3783b0', 'es', 'Referencias Normativas', '<div>El presente documento no contiene referencias normativas. </div>'),
    ('7bf6027d-8843-49d9-9503-15d1bd16c359', '1d23c521-dbd1-46e9-95ed-18d12e378869', 'en', 'Terms and definitions', '<div>For the purposes of this document, the following terms and definitions apply.</div><div>ISO and IEC maintain terminological databases for use in standardization at the following addresses:</div><div>— ISO Online browsing platform: available at <a href="https://www.iso.org/obp">https://www.iso.org/obp</a></div><div>— IEC Electropedia: available at <a href="http://www.electropedia.org/">http://www.electropedia.org/</a></div><div>{clause_3.1}</div><div>{clause_3.2}</div><div>{clause_3.3}</div><div>{clause_3.4}</div><div>{clause_3.5}</div><div>{clause_3.6}</div><div>{clause_3.7}</div><div>{clause_3.8}</div><div>{clause_3.9}</div><div>{clause_3.10}</div><div>{clause_3.11}</div><div>{clause_3.12}</div><div>{clause_3.13}</div><div>{clause_3.14}</div><div>{clause_3.15}</div><div>{clause_3.16}</div><div>{clause_3.17}</div><div>{clause_3.18}</div><div>{clause_3.19}</div><div>{clause_3.20}</div><div>{clause_3.21}</div><div>{clause_3.22}</div><div>{clause_3.23}</div><div>{clause_3.24}</div><div>{clause_3.25}</div><div>{clause_3.26}</div><div>{clause_3.27}</div><div>{clause_3.28}</div><div>{clause_3.29}</div><div>{clause_3.30}</div><div>{clause_3.31}</div><div>{clause_3.32}</div><div>{clause_3.33}</div><div>{clause_3.34}</div><div>{clause_3.35}</div><div>{clause_3.36}</div><div>{clause_3.37}</div>'),
    ('7ef60736-f212-4782-86d1-03fed816edda', '1d23c521-dbd1-46e9-95ed-18d12e378869', 'es', 'Terminos y definiciones', '<div>Para los fines de este documento, se aplican los términos y definiciones siguientes.</div><div>ISO e IEC mantienen bases de datos terminológicas para su utilización en normalización en las siguientes direcciones: </div><div>— Plataforma de búsqueda en línea de ISO: disponible en <a href=''https://www.iso.org/obp''>https://www.iso.org/obp</a></div><div>— Electropedia de IEC: disponible en <a href=''http://www.electropedia.org/''>http://www.electropedia.org/</a></div><div>{clause_3.1}</div><div>{clause_3.2}</div><div>{clause_3.3}</div><div>{clause_3.4}</div><div>{clause_3.5}</div><div>{clause_3.6}</div><div>{clause_3.7}</div><div>{clause_3.8}</div><div>{clause_3.9}</div><div>{clause_3.10}</div><div>{clause_3.11}</div><div>{clause_3.12}</div><div>{clause_3.13}</div><div>{clause_3.14}</div><div>{clause_3.15}</div><div>{clause_3.16}</div><div>{clause_3.17}</div><div>{clause_3.18}</div><div>{clause_3.19}</div><div>{clause_3.20}</div><div>{clause_3.21}</div><div>{clause_3.22}</div><div>{clause_3.23}</div><div>{clause_3.24}</div><div>{clause_3.25}</div><div>{clause_3.26}</div><div>{clause_3.27}</div><div>{clause_3.28}</div><div>{clause_3.29}</div><div>{clause_3.30}</div><div>{clause_3.31}</div><div>{clause_3.32}</div><div>{clause_3.33}</div><div>{clause_3.34}</div><div>{clause_3.35}</div><div>{clause_3.36}</div><div>{clause_3.37}</div>'),
    ('75dc9fbc-c1de-4cb0-ae88-acbc437b18a8', '1c23c38e-d52c-49ae-9f12-2f742d3786d6', 'en', 'organization', '<div>person or group of people that has its own functions with responsibilities, authorities and relationships to achieve its objectives (3.16).</div><div>Note 1 to entry: The concept of organization includes, but is not limited to sole-trader, company, corporation, firm, enterprise, authority, partnership, charity or institution, or part or combination thereof, whether incorporated or not, public or private.</div><div>Note 2 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1.</div>'),
    ('6adc8e6b-4833-4377-912f-b13f307afabf', '1c23c38e-d52c-49ae-9f12-2f742d3786d6', 'es', 'organización', '<div>persona o grupo de personas que tiene sus propias funciones con responsabilidades, autoridades y relaciones para el logro de sus objetivos (3.16).</div><div>Nota 1 de entrada: El concepto de organización incluye, entre otros, un trabajador independiente, compañía, corporación, firma, empresa, autoridad, sociedad, organización benéfica o institución, o una parte o combinación de éstas, ya estén constituidas o no, públicas o privadas.</div><div>Nota 2 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de administración/gestión de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1. </div>'),
    ('490d5043-4c5e-435f-a308-f777c30eccb7', '1723bbaf-d26a-4773-81ec-059f38379827', 'en', 'interested party (preferred term) stakeholder (admitted term)', '<div>person or organization (3.1) that can affect, be affected by, or perceive itself to be affected by a decision or activity.</div><div>Note 1 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1.</div>'),
    ('440d4864-0451-4488-bcde-4f44c60ed170', '1723bbaf-d26a-4773-81ec-059f38379827', 'es', 'partes interesadas (término preferido). stakeholder (término admitido)', ''),
    ('8a02f65a-95bc-4136-9595-dd6ae304dd8e', '1623ba1c-4a1a-47b8-9eee-999237379694', 'en', 'worker', '<div>person performing work or work-related activities that are under the control of the organization (3.1).</div><div>Note 1 to entry: Persons perform work or work-related activities under various arrangements, paid or unpaid, such as regularly or temporarily, intermittently or seasonally, casually or on a part-time basis.</div><div>Note 2 to entry: Workers include top management (3.12), managerial and non-managerial persons.</div><div>Note 3 to entry: The work or work-related activities performed under the control of the organization may be performed by workers employed by the organization, workers of external providers, contractors, individuals, agency workers, and by other persons to the extent the organization shares control over their work or workrelated activities, according to the context of the organization.</div>'),
    ('6f02cbd9-8f03-4ad5-836d-bdb5d004bfa5', '1623ba1c-4a1a-47b8-9eee-999237379694', 'es', 'trabajador', '<div>persona que realiza trabajo o actividades relacionadas con el trabajo que están bajo el control de la organización (3.1).</div><div>Nota 1 de entrada: Personas que realizan trabajo o actividades relacionadas con el trabajo bajo diversos acuerdos, pagados o no pagados, tales como de manera regular o temporal, intermitente o estacional, esporádica o a tiempo parcial.</div><div>Nota 2 de entrada: Los trabajadores incluyen la alta dirección (3.12), personas directivas y no directivas.</div><div>Nota 3 de entrada: El trabajo o las actividades relacionadas con el trabajo realizadas bajo el control de la organización puede ser realizado por trabajadores empleados por la organización, trabajadores de proveedores externos, contratistas, independientes, trabajadores proporcionados por otra organización, y por otras personas en la medida en que la organización comparta el control sobre su trabajo o actividades relacionadas con el trabajo, de acuerdo con el contexto de la organización.</div>'),
    ('f05f87f4-69a6-4f40-b3a2-adb4c2945478', '9920b6be-0a3e-41ca-b327-938c2a354386', 'en', 'participation', '<div>involvement in decision-making.</div><div>Note 1 to entry: Participation includes engaging health and safety committees and workers’ representatives, where they exist.</div>'),
    ('d55f5d73-62ec-45a7-a5c2-b4c7cf9468ef', '9920b6be-0a3e-41ca-b327-938c2a354386', 'es', 'participación', '<div>acción y efecto de involucrar en la toma de decisiones.</div><div>Nota 1 de entrada: La participación incluye el comprometer a los comités de seguridad y salud y a los representantes de los trabajadores, cuando existan.</div>'),
    ('89d2c295-de60-4529-9e30-1789065ac269', '9a20b851-47d0-4275-98a0-46892b354519', 'en', 'consultation', '<div>seeking views before making a decision.</div><div>Note 1 to entry: Consultation includes engaging health and safety committees and workers’ representatives, where they exist.</div>'),
    ('7cd2ae1e-ec0f-4f32-a411-b326015aba8a', '9a20b851-47d0-4275-98a0-46892b354519', 'es', 'consulta', '<div>búsqueda de opiniones antes de tomar una decisión.</div><div>Nota 1 de entrada: La consulta incluye el comprometer a los comités de seguridad y salud y a los representantes de los trabajadores, cuandoexistan.</div>'),
    ('82f552d6-08a1-4e7a-a770-9e1e01d0ac3a', '9720b398-1a4b-4060-80cc-567628354060', 'en', 'workplace', '<div>place under the control of the organization (3.1) where a person needs to be or to go for work purposes.</div><div>Note 1 to entry: The organization’s responsibilities under the OH&amp;S management system (3.11) for the workplace depend on the degree of control over the workplace.</div>'),
    ('7ff54e1d-cce2-4aa1-9d68-6271e6d081b9', '9720b398-1a4b-4060-80cc-567628354060', 'es', 'lugar de trabajo', '<div>lugar bajo el control de la organización (3.1) donde una persona necesita estar o ir por razones de trabajo.</div><div>Nota 1 de entrada: Las responsabilidades de la organización bajo el sistema de administración/gestión de SyST (3.11) para el lugar de trabajo dependen del grado de control sobre el lugar de trabajo.</div>'),
    ('efa72f7f-4e2b-4d93-8cee-80cb31bbd5a3', '9820b52b-0e55-411b-9aae-a493293541f3', 'en', 'contractor', '<div>external organization (3.1) providing services to the organization in accordance with agreed specifications, terms and conditions.</div><div>Note 1 to entry: Services may include construction activities, among others.</div>'),
    ('02a74d68-5e00-4844-9f29-6cf02cbbcdc4', '9820b52b-0e55-411b-9aae-a493293541f3', 'es', 'contratista', '<div>organización (3.1) externa que proporciona servicios a la organización de acuerdo con las especificaciones, términos y condiciones acordados.</div><div>Nota 1 de entrada: Los servicios pueden incluir actividades de construcción, entre otros.</div>'),
    ('0b30d368-6d4f-4824-8ea0-62f03508c744', '9d20bd0a-6783-4d5e-b655-aed82e3549d2', 'en', 'requirement', '<div>need or expectation that is stated, generally implied or obligatory.</div><div>Note 1 to entry: “Generally implied” means that it is custom or common practice for the organization (3.1) and interested parties (3.2) that the need or expectation under consideration is implied.</div><div>Note 2 to entry: A specified requirement is one that is stated, for example in documented information (3.24).</div><div>Note 3 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1.</div>'),
    ('f830b57f-7941-4b73-bc65-76cb3a08cf23', '9d20bd0a-6783-4d5e-b655-aed82e3549d2', 'es', 'requerimiento', '<div>necesidad o expectativa establecida, generalmente implícita u obligatoria.</div><div>Nota 1 de entrada: “Generalmente implícita” significa que es habitual o práctica común para la organización (3.1) y las partesinteresadas (3.2) que la necesidad o expectativa bajo consideración está implícita.</div><div>Nota 2 de entrada: Un requerimiento especificado es el que está declarado, por ejemplo en información documentada (3.24).</div><div>Nota 3 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de administración/gestión de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1.</div>'),
    ('82508219-3a3a-4f9d-be1f-d675cc0198e5', '9e20be9d-6e27-4a99-bdb7-93752f354b65', 'en', 'legal requirements and other requirements', '<div>legal requirements that an organization (3.1) has to comply with and other requirements (3.8) that an organization has to or chooses to comply with.</div><div>Note 1 to entry: For the purposes of this document, legal requirements and other requirements are those relevant to the OH&amp;S management system (3.11).</div><div>Note 2 to entry: “Legal requirements and other requirements” include the provisions in collective agreements.</div><div>Note 3 to entry: Legal requirements and other requirements include those that determine the persons who are workers’ (3.3) representatives in accordance with laws, regulations, collective agreements and practices.</div>'),
    ('9d50ac9a-ad2c-4b0e-b562-292adf01b6ce', '9e20be9d-6e27-4a99-bdb7-93752f354b65', 'es', 'requerimientos legales y otros requerimientos', '<div>requerimientos legales que una organización (3.1) tiene que cumplir y otros requerimientos (3.8) que una organización tiene que cumplir o que elige cumplir.</div><div>Nota 1 de entrada: Para los propósitos de este documento, los requerimientos legales y otros requerimientos son aquellos que son pertinentes para el sistema de administración/gestión de SyST (3.11).</div><div>Nota 2 de entrada: “Los requerimientos legales y otros requerimientos” incluyen las disposiciones de acuerdos colectivos.</div><div>Nota 3 de entrada: Los requerimientos legales y otros requerimientos incluyen aquellos que identifican a las personas que son los representantes de los trabajadores (3.3) de acuerdo con las leyes, los reglamentos, los acuerdos colectivos y las prácticas.</div>'),
    ('7d289b2a-c806-45fe-8946-90dac700c166', '9b20b9e4-8463-48a4-863b-2c222c3546ac', 'en', 'management system', '<div>set of interrelated or interacting elements of an organization (3.1) to establish policies (3.14) and objectives (3.16) and processes (3.25) to achieve those objectives.</div><div>Note 1 to entry: A management system can address a single discipline or several disciplines.</div><div>Note 2 to entry: The system elements include the organization’s structure, roles and responsibilities, planning, operation, performance evaluation and improvement.</div><div>Note 3 to entry: The scope of a management system may include the whole of the organization, specific and identified functions of the organization, specific and identified sections of the organization, or one or more functions across a group of organizations.</div><div>Note 4 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1. Note 2 to entry has been modified to clarify some of the wider elements of a management system.</div>'),
    ('8228a309-960d-46ed-ae2e-4845e400ef0d', '9b20b9e4-8463-48a4-863b-2c222c3546ac', 'es', 'sistema de gestión/administración', '<div>conjunto de elementos de una organización (3.1) interrelacionados o que interactúan para establecer políticas (3.14) objetivos(3.16) y procesos (3.25) para lograr estos objetivos.</div><div>Nota 1 de entrada: Un sistema de administración/gestión puede abordar una sola disciplina o varias disciplinas.</div><div>Nota 2 de entrada: Los elementos del sistema incluyen la estructura de la organización, los roles y las responsabilidades, la planeación, la operación, la evaluación del desempeño y la mejora.</div><div>Nota 3 de entrada: El alcance de un sistema de administración/gestión puede incluir la totalidad de la organización, funciones específicas e identificadas de la organización, secciones específicas e identificadas de la organización, ouna o más funciones dentro de un grupo de organizaciones.</div><div>Nota 4 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de administración/gestión de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1. La Nota 2 de entrada se ha modificado para clarificar ciertos aspectos más amplios de un sistema de administración/gestión.</div>'),
    ('b02bfe53-7e10-42a7-88b0-0327e7a8e60f', '9c20bb77-0c8c-48ef-aaec-cc2f2d35483f', 'en', 'occupational health and safety management system. OH&S management system', '<div>management system (3.10) or part of a management system used to achieve the OH&amp;S policy (3.15).</div><div>Note 1 to entry: The intended outcomes of the OH&amp;S management system are to prevent injury and ill health (3.18) to workers (3.3) and to provide safe and healthy workplaces (3.6).</div><div>Note 2 to entry: The terms “occupational health and safety” (OH&amp;S) and “occupational safety and health” (OSH) have the same meaning.</div>'),
    ('cb2c28d4-84ca-4c40-8f62-a394daa8d198', '9c20bb77-0c8c-48ef-aaec-cc2f2d35483f', 'es', 'sistema de gestión/administración de la seguridad y salud en el trabajo. sistema de gestión/administración de SyST', '<div>sistema de administración/gestión (3.10) o parte de un sistema de administración/gestión utilizado para alcanzar la política de SyST (3.15).</div><div>Nota 1 de entrada: Los resultados previstos del sistema de administración/gestión de SyST son prevenir lesiones y deterioro de la salud (3.18) a los trabajadores (3.3) y proporcionar lugares de trabajo (3.6) seguros y saludables.</div><div>Nota 2 de entrada: Los términos “salud y seguridad en el trabajo” (en inglés, OSH) y “seguridad y salud en el trabajo” (en inglés, OH&amp;S) tienen el mismo significado.</div>'),
    ('6b7cad8c-60fe-41a8-bc03-7d2c07ddd050', '9120aa26-c333-4372-b69e-80843235501e', 'en', 'top management', '<div>person or group of people who directs and controls an organization (3.1) at the highest level.</div><div>Note 1 to entry: Top management has the power to delegate authority and provide resources within the organization, provided ultimate responsibility for the OH&amp;S management system (3.11) is retained.</div><div>Note 2 to entry: If the scope of the management system (3.10) covers only part of an organization, then top management refers to those who direct and control that part of the organization.</div><div>Note 3 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1. Note 1 to entry has been modified to clarify the responsibility of top management in relation to an OH&amp;S management system.</div>'),
    ('807cce9b-a90c-437f-90ac-dfcf04ddcb97', '9120aa26-c333-4372-b69e-80843235501e', 'es', 'alta dirección', '<div>persona o grupo de personas que dirige y controla una organización (3.1) al más alto nivel.</div><div>Nota 1 de entrada: La alta dirección tiene el poder para delegar autoridad y proporcionar recursos dentro de la organización siempre que se conserve la responsabilidad última del sistema de administración/gestión de SyST (3.11).</div><div>Nota 2 de entrada: Si el alcance del sistema de administración/gestión (3.10) comprende sólo una parte de la organización, entonces alta dirección se refiere a quienes dirigen y controlan esa parte de la organización.</div><div>Nota 3 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de administración/gestión de ISOproporcionados en el Anexo SL del suplemento de ISOconsolidado de las Directivas ISO/IEC, Parte 1. La Nota 1 de entrada se ha modificado para clarificar la responsabilidad de la alta dirección en relación con un sistema de administración/gestión de SyST. </div>'),
    ('2275b18d-4604-4971-b7eb-6a41a1781a61', '9220abb9-1cfa-493d-9d4b-1461333551b1', 'en', 'effectiveness', '<div>extent to which planned activities are realized and planned results achieved.</div><div>Note 1 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1.</div>'),
    ('057583e6-29f9-47ea-b314-580e8c77f952', '9220abb9-1cfa-493d-9d4b-1461333551b1', 'es', 'efectividad', '<div>grado en el que se realizan las actividades planeadas y se alcanzan los resultados planeados.</div><div>Nota 1 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de administración/gestión de ISOproporcionados en el Anexo SL del suplemento de ISOconsolidado de las Directivas ISO/IEC, Parte 1.</div>'),
    ('550c835d-15b8-4db5-8b64-4431bad729f1', '931e6eb5-dd94-4af1-9dd1-1771c432645d', 'en', 'policy', '<div>intentions and direction of an organization (3.1), as formally expressed by its top management (3.12).</div><div>Note 1 to entry: This constitutes one of the common terms and core definitions for ISO manag</div>'),
    ('580c8816-3292-4f96-a488-c8dec5d73b42', '931e6eb5-dd94-4af1-9dd1-1771c432645d', 'es', 'politica', '<div>intenciones y dirección de una organización (3.1), como las expresa formalmente su alta dirección (3.12).</div><div>Nota 1 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de administración/gestión de ISOproporcionados en el Anexo SL del suplemento de ISOconsolidado de las Directivas ISO/IEC, Parte 1.</div>'),
    ('db997b1c-aa2c-49bc-a6a3-8a1c245519a0', '921e6d22-02a7-46f6-9d97-b194c33262ca', 'en', 'occupational health and safety policy. OH&S policy', '<div>policy (3.14) to prevent work-related injury and ill health (3.18) to workers (3.3) and to provide safe and healthy workplaces (3.6).</div>'),
    ('d09969cb-4d18-43bb-a29d-a39f41554747', '921e6d22-02a7-46f6-9d97-b194c33262ca', 'es', 'política de la seguridad y salud en el trabajo. política de SyST', '<div>política (3.14) para prevenir lesiones y daños a la salud (3.18) relacionados con el trabajo a los trabajadores (3.3) y para proporcionar lugares de trabajo (3.6) seguros y saludables.</div>'),
    ('fa41f147-7e58-4c3f-909c-b8d3e6d60deb', '911e6b8f-b191-4c67-9788-2b3bc2326137', 'en', 'objective', '<div>result to be achieved.</div><div>Note 1 to entry: An objective can be strategic, tactical, or operational.</div><div>Note 2 to entry: Objectives can relate to different disciplines (such as financial, health and safety, and environmental goals) and can apply at different levels (such as strategic, organization-wide, project, product and process (3.25)).</div><div>Note 3 to entry: An objective can be expressed in other ways, e.g. as an intended outcome, a purpose, an operational criterion, as an OH&amp;S objective (3.17), or by the use of other words with similar meaning (e.g. aim, goal, or target).</div><div>Note 4 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1. The original Note 4 to entry has been deleted as the term “OH&amp;S objective” has been defined separately in 3.17.</div>'),
    ('dd41c3a0-364c-4d68-b99a-f8e8f1d61f3c', '911e6b8f-b191-4c67-9788-2b3bc2326137', 'es', 'objetivo', '<div>resultado a alcanzar.</div><div>Nota 1 de entrada: Un objetivo puede ser estratégico, táctico u operativo.</div><div>Nota 2 de entrada: Los objetivos pueden referirse a diferentes disciplinas (tales como financieras, de seguridad y salud y ambientales) y se pueden aplicar en diferentes niveles [tales como estratégicos, para toda la organización, para proyectos, productos y procesos (3.25)].</div><div>Nota 3 de entrada: Un objetivo se puede expresar de otras maneras, por ejemplo, como un resultado previsto, un propósito, un criterio operativo, un objetivo de SyST (3.17), o mediante el uso de términos con un significado similar (por ejemplo finalidad ometa).</div><div>Nota 4 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de administración/gestión de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1. La “Nota 4 de entrada” original se ha eliminado porque el término “objetivo de SyST” se ha definido de forma separada en 3.17. </div>'),
    ('500babde-0477-4f16-9460-d466d64bb322', '901e69fc-22b5-4ebc-aea1-a1fec1325fa4', 'en', 'occupational health and safety objective. OH&S objective', '<div>objective (3.16) set by the organization (3.1) to achieve specific results consistent with the OH&amp;S policy (3.15).</div>'),
    ('5d0bc055-e79d-4d35-a554-60c9cb4ba1d1', '901e69fc-22b5-4ebc-aea1-a1fec1325fa4', 'es', 'objetivo de la seguridad y salud en el trabajo. objetivo de SyST', '<div>objetivo (3.16) establecido por la organización (3.1) para lograr resultados específicos coherentes con la política de SyST (3.15).</div>'),
    ('8f65ace1-245b-4d01-9de8-591dc07cd22d', '8f1e6869-02f4-4e6d-9826-6c3dc0325e11', 'en', 'injury and ill health', '<div>adverse effect on the physical, mental or cognitive condition of a person.</div><div>Note 1 to entry: These adverse effects include occupational disease, illness and death.</div><div>Note 2 to entry: The term “injury and ill health” implies the presence of injury or ill health, either on their own or in combination.</div>'),
    ('7a658bd2-601b-43da-bf3a-fb82a37ca486', '8f1e6869-02f4-4e6d-9826-6c3dc0325e11', 'es', 'lesión y daño a la salud', '<div>efecto adverso en la condición física, mental o cognitiva de una persona.</div><div>Nota 1 de entrada: Estos efectos adversos incluyen enfermedad profesional, enfermedad común y muerte.</div><div>Nota 2 de entrada: Eltérmino “lesión y daño a la salud” implica la presencia de lesiones o de daños a la salud, solos o encombinación. </div>'),
    ('f5cb62d0-f0c5-4838-a498-5cb80983ce2c', '8e1e66d6-a88f-47e2-86ed-8d80bf325c7e', 'en', 'hazard', '<div>source with a potential to cause injury and ill health (3.18).</div><div>Note 1 to entry: Hazards can include sources with the potential to cause harm or hazardous situations, or circumstances with the potential for exposure leading to injury and ill health.</div>'),
    ('f2cb5e17-f54c-44ef-b09c-43c31e83ef3b', '8e1e66d6-a88f-47e2-86ed-8d80bf325c7e', 'es', 'peligro', '<div>fuente con un potencial para causar lesiones y deterioro de la salud (3.18).</div><div>Nota 1 de entrada: Los peligros pueden incluir fuentes con el potencial de causar daños o situaciones peligrosas, o circunstancias con el potencial de exposición que conduzca a lesiones y deterioro de la salud.</div>'),
    ('bac6c01b-4ac4-4d6b-8ef8-70cf9c254d97', '8d1e6543-2e54-4e93-83f9-72b7be325aeb', 'en', 'risk', '<div>effect of uncertainty.</div><div>Note 1 to entry: An effect is a deviation from the expected — positive or negative.</div><div>Note 2 to entry: Uncertainty is the state, even partial, of deficiency of information related to, understanding or knowledge of, an event, its consequence, or likelihood.</div><div>Note 3 to entry: Risk is often characterized by reference to potential “events” (as defined in ISO Guide 73:2009, 3.5.1.3) and “consequences” (as defined in ISO Guide 73:2009, 3.6.1.3), or a combination of these.</div><div>Note 4 to entry: Risk is often expressed in terms of a combination of the consequences of an event (including changes in circumstances) and the associated “likelihood” (as defined in ISO Guide 73:2009, 3.6.1.1) of occurrence.</div><div>Note 5 to entry: In this document, where the term “risks and opportunities” is used this means OH&amp;S risks (3.21), OH&amp;S opportunities (3.22) and other risks and other opportunities for the management system.</div><div>Note 6 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1. Note 5 to entry has been added to clarify the term “risks and opportunities” for its use within this document.</div>'),
    ('a5c69f0c-662e-468c-ba4f-0e2c9f255250', '8d1e6543-2e54-4e93-83f9-72b7be325aeb', 'es', 'riesgo', '<div>efecto de la incertidumbre.</div><div>Nota 1 de entrada: Un efecto es una desviación de lo esperado — positiva o negativa.</div><div>Nota 2 de entrada: Incertidumbre es el estado, incluso parcial, de deficiencia de información relacionada con la comprensión o conocimiento de un evento, su consecuencia o su probabilidad.</div><div>Nota 3 de entrada: Con frecuencia el riesgo se caracteriza por referencia a “eventos” potenciales (según se define en la Guía ISO 73:2009, 3.5.1.3), y “consecuencias” (según se define en la Guía ISO 73:2009, 3.6.1.3), o una combinación de éstos.</div><div>Nota 4 de entrada: Con frecuencia el riesgo se expresa en términos de una combinación de las consecuencias de un evento (incluidos cambios en las circunstancias) y la “probabilidad” (según se define en la Guía ISO73:2009, 3.6.1.1) asociada de queocurra.</div><div>Nota 5 de entrada: En este documento, cuando se utiliza el término “riesgos y oportunidades” significa riesgos para SyST (3.21), oportunidades para SyST (3.22) y otros riesgos y otras oportunidades para el sistema de administración/gestión.</div><div>Nota 6 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de administración/gestión de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1. La Nota 5 de entrada se ha añadido para clarificar el término “riesgos y oportunidades” en su uso para este documento.</div>'),
    ('6860fb52-ee43-4e12-811e-0802bc19cb6e', '8c1e63b0-d570-4c58-8b77-3dcabd325958', 'en', 'occupational health and safety risk. OH&S risk', '<div>combination of the likelihood of occurrence of a work-related hazardous event(s) or exposure(s) and the severity of injury and ill health (3.18) that can be caused by the event(s) or exposure(s).</div>'),
    ('7d611c61-de19-4b09-9fcb-659da919ad85', '8c1e63b0-d570-4c58-8b77-3dcabd325958', 'es', 'riesgo para la seguridad y salud en el trabajo. riesgo para SyST', '<div>combinación de la probabilidad de que ocurran eventos o exposiciones peligrosos relacionados con el trabajo y la severidad de la lesión y deterioro de la salud (3.18) que pueden causar los eventos o exposiciones.</div>'),
    ('b9ef2b65-3f2b-462d-9f47-3e39962bb139', '9b1e7b4d-5109-4609-b970-a899bc3257c5', 'en', 'occupational health and safety opportunity. OH&S opportunity', '<div>circumstance or set of circumstances that can lead to improvement of OH&amp;S performance (3.28).</div>'),
    ('ccef494e-57d7-403e-9fce-c4f6b12bdbba', '9b1e7b4d-5109-4609-b970-a899bc3257c5', 'es', 'oportunidad para la seguridad y salud en el trabajo. oportunidad para SyST', '<div>circunstancia o conjunto de circunstancias que pueden conducir a la mejora del desempeño de SyST (3.28).</div>'),
    ('22f659c4-92fc-4934-831c-93241c919988', '9a1e79ba-6083-4e4e-88c4-0f1cbb325632', 'en', 'competence', '<div>ability to apply knowledge and skills to achieve intended results.</div><div>Note 1 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1.</div>'),
    ('27f661a3-2bfd-4ce3-90b0-7c5709917b9f', '9a1e79ba-6083-4e4e-88c4-0f1cbb325632', 'es', 'competencia', '<div>capacidad para aplicar conocimientos y habilidades con el fin de alcanzar los resultados previstos.</div><div>Nota 1 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de gestión/administración de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1.</div>'),
    ('83cf862e-879b-4ca6-a626-4156ca10bbb2', '8d1c26ac-67c6-4008-ba4b-0e4ebe301c54', 'en', 'documented information', '<div>information required to be controlled and maintained by an organization (3.1) and the medium on which it is contained.</div><div>Note 1 to entry: Documented information can be in any format and media, and from any source.</div><div>Note 2 to entry: Documented information can refer to:</div><div>{clause_3.24.a}</div><div>{clause_3.24.b}</div><div>{clause_3.24.c}</div><div>Note 3 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1. </div>'),
    ('70cf6845-f3d4-45e5-b554-5199df10dcc1', '8d1c26ac-67c6-4008-ba4b-0e4ebe301c54', 'es', 'información documentada', '<div>información que una organización (3.1) tiene que controlar y mantener, y el medio que la contiene.</div><div>Nota 1 deentrada: La información documentada puede estar en cualquier formato y medio, y puede provenir de cualquier fuente.</div><div>Nota 2 de entrada: La información documentada puede hacer referencia a:</div><div>{clause_3.24.a}</div><div>{clause_3.24.b}</div><div>{clause_3.24.c}</div><div>Nota 3 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de administración/gestión de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1.</div>'),
    ('615f0c57-63f3-4d0f-9ddb-6c831c76807b', '8e1c283f-d6c9-4ac3-b7c3-b1cbbf301de7', 'en', '', '<div>a) the management system (3.10), including related processes (3.25);</div>'),
    ('645f1110-7312-4fd8-a805-e37807765f6c', '8e1c283f-d6c9-4ac3-b7c3-b1cbbf301de7', 'es', '', '<div>a) el sistema de gestión/administración (3.10), incluidos los procesos (3.25) relacionados; </div>'),
    ('cebf1fec-a34a-434c-97d9-098ccad335b0', '8f1c29d2-1f1f-4d92-9832-f824c0301f7a', 'en', '', '<div>b) information created in order for the organization to operate (documentation); </div>'),
    ('e3bf40fb-a3a7-482b-a47b-8a2fc7d330f7', '8f1c29d2-1f1f-4d92-9832-f824c0301f7a', 'es', '', '<div>b) la información generada para que la organización opere (documentación); </div>'),
    ('88328ced-becd-4945-873a-8f21ee9b0441', '901c2b65-9231-455d-9dd4-7381c130210d', 'en', '', '<div>c) evidence of results achieved (records).</div>'),
    ('6b325f46-81ff-4d86-8501-70eed99ae332', '901c2b65-9231-455d-9dd4-7381c130210d', 'es', '', '<div>c) la evidencia delos resultados alcanzados (registros).</div>'),
    ('9e016de2-9755-46a2-811f-48b2af3f703e', '891c2060-ca8b-472c-bafc-fe9aba301608', 'en', 'process', '<div>set of interrelated or interacting activities which transforms inputs into outputs.</div><div>Note 1 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1.</div>'),
    ('93015c91-43a6-4179-87ba-192dbc3f84b5', '891c2060-ca8b-472c-bafc-fe9aba301608', 'es', 'proceso', '<div>conjunto de actividades interrelacionadas o que interactúan, que transforma las entradas en salidas.</div><div>Nota 1 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de gestión/administración de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1.</div>'),
    ('ae8a35ab-b95b-48fb-84de-a3ffcf49c427', '8a1c21f3-43e8-4017-92d6-5307bb30179b', 'en', 'procedure', '<div>specified way to carry out an activity or a process (3.25).</div><div>Note 1 to entry: Procedures may be documented or not.</div><div>[SOURCE: ISO 9000:2015, 3.4.5, modified — Note 1 to entry has been modified.] </div>'),
    ('b98a46fc-18e8-44fc-9c50-b87cb2499680', '8a1c21f3-43e8-4017-92d6-5307bb30179b', 'es', 'procedimiento', '<div>forma especificada de llevar a cabo una actividad o un proceso (3.25).</div><div>Nota 1 de entrada: Los procedimientos pueden estar documentados o no.</div><div>[FUENTE: ISO 9000:2015, 3.4.5, modificado — La Nota 1 de entrada se ha modificado en la versión inglesa al sustituir “can” por “may”, no aplica a la versión en español].</div>'),
    ('e98ed860-010f-4688-b267-5ea8b0a14dfc', '8b1c2386-9282-4ea6-9faf-7490bc30192e', 'en', 'performance', '<div>measurable result.</div><div>Note 1 to entry: Performance can relate either to quantitative or qualitative findings. Results can be determined and evaluated by qualitative or quantitative methods.</div><div>Note 2 to entry: Performance can relate to the management of activities, processes (3.25), products (including services), systems or organizations (3.1).</div><div>Note 3 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1. Note 1 to entry has been modified to clarify the types of methods that may be used for determining and evaluating results.</div>'),
    ('068f0607-491b-455f-9d6c-e493a5a13cab', '8b1c2386-9282-4ea6-9faf-7490bc30192e', 'es', 'desempeño', '<div>resultado medible.</div><div>Nota 1 de entrada: El desempeño se puede relacionar con hallazgos cuantitativos o cualitativos. Los resultados pueden determinarse y evaluarse por métodos cualitativos o cuantitativos.</div><div>Nota 2 de entrada: El desempeño se puede relacionar con la administración/gestión de actividades, procesos (3.25), productos (incluidos servicios), sistemas u organizaciones (3.1).</div><div>Nota 3 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de gestión/administración de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1. La Nota 1 deentrada se ha modificado para clarificar los tipos y métodos que pueden utilizarse para determinar y evaluar los resultados.</div>'),
    ('828b51b1-28ac-4fd1-8cb7-7bcdb441dabd', '8c1c2519-6fea-4ea1-b838-504dbd301ac1', 'en', 'occupational health and safety performance. OH&S performance', '<div>performance (3.27) related to the effectiveness (3.13) of the prevention of injury and ill health (3.18) to workers (3.3) and the provision of safe and healthy workplaces (3.6).</div>'),
    ('8d8b6302-22c2-49ca-aac8-75d2b741df76', '8c1c2519-6fea-4ea1-b838-504dbd301ac1', 'es', 'desempeño de la seguridad y salud en el trabajo. desempeño de SyST', '<div>desempeño (3.27) relacionado con la efectividad (3.13) de la prevención de lesiones y deterioro de la salud (3.18) para los trabajadores (3.3) y de la provisión de lugares de trabajo (3.6) seguros y saludables.</div>'),
    ('e8b22e36-aab0-4f5e-83ca-467ec4c7a49a', '951c3344-78b0-4080-812f-6016b6300fbc', 'en', 'outsource, verb', '<div>make an arrangement where an external organization (3.1) performs part of an organization’s function or process (3.25).</div><div>Note 1 to entry: An external organization is outside the scope of the management system (3.10), although the outsourced function or process is within the scope.</div><div>Note 2 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1.</div>'),
    ('e5b2297d-763b-444d-91fc-5851a9c77a19', '951c3344-78b0-4080-812f-6016b6300fbc', 'es', 'contratar externamente, verbo', '<div>establecer un acuerdo mediante el cual una organización (3.1) externa realiza parte de una función o proceso (3.25) de una organización.</div><div>Nota 1 de entrada: Una organización externa está fuera del alcance del sistema de gestión/administración (3.10), aunque la función o proceso contratado externamente forme parte del alcance.</div><div>Nota 2 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de gestión/administración de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1.</div>'),
    ('c8bc1d5f-1e21-4787-bd7d-9eab81592883', '961c34d7-838c-4d3b-97a5-41b3b730114f', 'en', 'monitoring', '<div>determining the status of a system, a process (3.25) or an activity.</div><div>Note 1 to entry: To determine the status, there may be a need to check, supervise or critically observe.</div><div>Note 2 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1.</div>'),
    ('dbbc3b48-24db-4120-b4ed-50d07c5920a4', '961c34d7-838c-4d3b-97a5-41b3b730114f', 'es', 'seguimiento', '<div>determinación del estado de un sistema, un proceso (3.25) o una actividad.</div><div>Nota 1 de entrada: Para determinar el estado, puede ser necesario verificar, supervisar u observar en forma crítica.</div><div>Nota 2 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de administración/gestión de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1.</div>'),
    ('0eb21a37-c027-44cb-b518-9563fd6a02c3', '8719dea3-bed2-4f17-ad13-8c6bb82dd44b', 'en', 'measurement', '<div>process (3.25) to determine a value.</div><div>Note 1 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1.</div>'),
    ('11b21ef0-db91-4dec-a8b2-5558f869fae4', '8719dea3-bed2-4f17-ad13-8c6bb82dd44b', 'es', 'medición', '<div>proceso (3.25) para determinar un valor.</div><div>Nota 1 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de administración/gestión de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 11.</div>'),
    ('2ea82b0e-0057-41f2-b921-87363e5fa8da', '8619dd10-4576-462c-87c2-0aeeb72dd2b8', 'en', 'audit', '<div>systematic, independent and documented process (3.25) for obtaining audit evidence and evaluating it objectively to determine the extent to which the audit criteria are fulfilled.</div><div>Note 1 to entry: An audit can be an internal audit (first party) or an external audit (second party or third party), and it can be a combined audit (combining two or more disciplines).</div><div>Note 2 to entry: An internal audit is conducted by the organization (3.1) itself, or by an external party on its behalf.</div><div>Note 3 to entry: “Audit evidence” and “audit criteria” are defined in ISO 19011.</div><div>Note 4 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1.</div>'),
    ('1ba80d25-d6e1-49e9-9949-4079235f7e59', '8619dd10-4576-462c-87c2-0aeeb72dd2b8', 'es', 'auditoría', '<div>proceso (3.25) sistemático, independiente y documentado para obtener las evidencias de auditoría y evaluarlas de manera objetiva con el fin de determinar el grado en el que se cumplen los criterios de auditoría.</div><div>Nota 1 de entrada: Una auditoría puede ser interna (de primera parte) o externa (de segunda o tercera parte), y puede ser combinada (combinando dos o más disciplinas).</div><div>Nota 2 de entrada: La auditoría interna la realiza la propia organización (3.1) o una parte externa en su nombre.</div><div>Nota 3 de entrada: “Evidencia de auditoría” y “criterios de auditoría” se definen en la Norma ISO19011.</div><div>Nota 4 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de gestión/administración de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1.</div>'),
    ('a8ddad4d-c1f1-48e1-8f70-c40142e9bf09', '8919e1c9-ead5-4da1-8aea-e4a1ba2dd771', 'en', 'conformity', '<div>fulfilment of a requirement (3.8).</div><div>Note 1 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1.</div>'),
    ('8bdd7fa6-1978-4aba-aa1f-c8ce3de9b72a', '8919e1c9-ead5-4da1-8aea-e4a1ba2dd771', 'es', 'conformidad', '<div>cumplimiento de un requerimiento (3.8).</div><div>Nota 1 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de gestión/administración de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1.</div>'),
    ('ef6a404c-6626-4c98-b96f-c9ec8bc81898', '8819e036-0d6c-4da6-b67a-8dc4b92dd5de', 'en', 'nonconformity', '<div>non-fulfilment of a requirement (3.8).</div><div>Note 1 to entry: Nonconformity relates to requirements in this document and additional OH&amp;S management system (3.11) requirements that an organization (3.1) establishes for itself.</div><div>Note 2 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1. Note 1 to entry has been added to clarify the relationship of nonconformities to the requirements of this document and to the organization’s own requirements for its OH&amp;S management system.</div>'),
    ('046a615b-548f-43cf-81b9-898f98c82d0f', '8819e036-0d6c-4da6-b67a-8dc4b92dd5de', 'es', 'no conformidad', '<div>incumplimiento de un requerimiento (3.8).</div><div>Nota 1 de entrada: La no conformidad está relacionada con requerimientos de este documento y con requerimientos adicionales del sistema de gestión/administración de SyST (3.11) que una organización (3.1) establece por sí misma.</div><div>Nota 2 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de gestión/administración de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1. La Nota 1 de entrada se ha añadido para clarificar la relación de las no conformidades con los requerimientos de este documento y con los requerimientos propios de la organización para su sistema de administración/gestión de SyST.</div>'),
    ('5bdd438b-f3bb-439f-b40e-12dfb0de3d2f', '8b19e4ef-51b4-49c3-a0b4-2f27bc2dda97', 'en', 'incident', '<div>occurrence arising out of, or in the course of, work that could or does result in injury and ill health (3.18).</div><div>Note 1 to entry: An incident where injury and ill health occurs is sometimes referred to as an “accident”.</div><div>Note 2 to entry: An incident where no injury and ill health occurs, but has the potential to do so, may be referred to as a “near-miss”, “near-hit” or “close call”.</div><div>Note 3 to entry: Although there can be one or more nonconformities (3.34) related to an incident, an incident can also occur where there is no nonconformity.</div>'),
    ('66dd54dc-a933-48c8-bb04-e75ca3de28b8', '8b19e4ef-51b4-49c3-a0b4-2f27bc2dda97', 'es', 'incidente', '<div>suceso que surge del trabajo o en el transcurso del trabajo que podría tener o tiene como resultado lesiones y deterioro de la salud (3.18).</div><div>Nota 1 de entrada: En ocasiones se denomina “accidente” a un incidente donde se han producido lesiones y deterioro de la salud.</div><div>Nota 2 de entrada: Un incidente donde no se han producido lesiones y deterioro de la salud, pero tiene el potencial para causarlos, puede denominarse un “cuasi-accidente”.</div><div>Nota 3 de entrada: Aunque puede haber una o más no conformidades (3.34) relacionadas con un incidente, un incidente también puede producirse aunque no haya ninguna no conformidad.</div>'),
    ('bc33b842-8e68-4b76-8c1a-7112038e2b06', '8a19e35c-e2b1-4f08-8295-7dbabb2dd904', 'en', 'corrective action', '<div>action to eliminate the cause(s) of a nonconformity (3.34) or an incident (3.35) and to prevent recurrence.</div><div>Note 1 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1. The definition has been modified to include reference to “incident”, as incidents are a key factor in occupational health and safety, yet the activities needed for resolving them are the same as for nonconformities, through corrective action.</div>'),
    ('b133a6f1-a0fb-4715-845f-470d208e58ad', '8a19e35c-e2b1-4f08-8295-7dbabb2dd904', 'es', 'acción correctiva', '<div>acción para eliminar la causa de una no conformidad (3.34) o un incidente (3.35) y prevenir que vuelva a ocurrir.</div><div>Nota 1 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas de sistemas de gestión de ISO proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1. La definición se ha modificado para incluir la referencia a “incidente”, dado que los incidentes son los factores clave de la seguridad y salud en el trabajo, sin embargo, las actividades necesarias para resolverlos son las mismas que para las no conformidades, a través de acciones correctivas.</div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('a3380511-cf16-4795-913c-10ad088f0285', '8d19e815-0d1c-445d-954a-a06dbe2dddbd', 'en', 'continual improvement', '<div>recurring activity to enhance performance (3.27).</div><div>Note 1 to entry: Enhancing performance relates to the use of the OH&amp;S management system (3.11) in order to achieve improvement in overall OH&amp;S performance (3.28) consistent with the OH&amp;S policy (3.15) and OH&amp;S objectives (3.17).</div><div>Note 2 to entry: Continual does not mean continuous, so the activity does not need to take place in all areas simultaneously.</div><div>Note 3 to entry: This constitutes one of the common terms and core definitions for ISO management system standards given in Annex SL of the Consolidated ISO Supplement to the ISO/IEC Directives, Part 1. Note 1 to entry has been added to clarify the meaning of “performance” in the context of an OH&amp;S management system; Note 2 to entry has been added to clarify the meaning of “continual”.</div>'),
    ('ae381662-bc83-4bf6-8aa1-40321b8f206e', '8d19e815-0d1c-445d-954a-a06dbe2dddbd', 'es', 'mejora continua', '<div>actividad recurrente para mejorar el desempeño (3.27).</div><div>Nota 1 de entrada: Mejorar el desempeño está relacionado con el uso del sistema de gestión/administración de SyST (3.11) para lograr la mejora en el desempeño global de SyST (3.28) coherente con la política de SyST (3.15) y los objetivos de SyST (3.17).</div><div>Nota 2 de entrada: Continua no significa ininterrumpida de manera que no es necesario que la actividad tenga lugar en todas las áreas de forma simultánea.</div><div>Nota 3 de entrada: Este constituye uno de los términos comunes y definiciones esenciales de las normas ISO de sistemas de gestión/administración de proporcionados en el Anexo SL del suplemento de ISO consolidado de las Directivas ISO/IEC, Parte 1. La Nota 1 de entrada se ha añadido para clarificar el significado de “desempeño” en el contexto del sistema de administración/gestión de SyST; y la Nota 2 de entrada se ha añadido para clarificar el significado de “continua”.</div>'),
    ('0a3b8bc0-4cfe-429c-8b1d-2208719630e4', '8c19e682-9a09-4c92-9847-44b0bd2ddc2a', 'en', 'Context of the organization', '<div>{clause_4.1}</div><div>{clause_4.2}</div><div>{clause_4.3}</div><div>{clause_4.4}</div>'),
    ('273bb967-efe9-4c9b-96ea-3d73769638c3', '8c19e682-9a09-4c92-9847-44b0bd2ddc2a', 'es', 'Contexto de la organización', '<div>{clause_4.1}</div><div>{clause_4.2}</div><div>{clause_4.3}</div><div>{clause_4.4}</div>'),
    ('760f2b3f-d698-4743-bc84-ae8b960cf1bb', '8f19eb3b-ff28-4d0f-b0fe-a2d3b02dc7b3', 'en', 'Understanding the organization and its context', '<div>The organization shall determine external and internal issues that are relevant to its purpose and that affect its ability to achieve the intended outcome(s) of its OH&amp;S management system.</div>'),
    ('890f4928-2778-4b14-8eed-beb0810cd0ac', '8f19eb3b-ff28-4d0f-b0fe-a2d3b02dc7b3', 'es', 'Comprensión de la organización y de su contexto', '<div>La organización debe determinar las cuestiones externas e internas que son pertinentes para su propósito y que afectan a su capacidad para alcanzar los resultados previstos de su sistema de gestión de la SST. </div>'),
    ('095ee196-d047-44ea-aab3-7ade462195f2', '8e19e9a8-76ff-4cc4-b67c-d5b6af2dc620', 'en', 'Understanding the needs and expectations of workers and other interested parties', '<div>The organization shall determine:</div><div>{clause_4.2.a}</div><div>{clause_4.2.b}</div><div>{clause_4.2.c}</div>'),
    ('065edcdd-ec52-4671-918e-f6315b21b701', '8e19e9a8-76ff-4cc4-b67c-d5b6af2dc620', 'es', 'Comprensión de las necesidades y expectativas de los trabajadores y de otras partes interesadas', '<div>La organización debe determinar: </div><div>{clause_4.2.a}</div><div>{clause_4.2.b}</div><div>{clause_4.2.c}</div>'),
    ('53811dd0-86b3-4cf4-8715-8fb8165e295c', '2116ff7a-b544-4916-8df4-b880b22b8c42', 'en', '', '<div>a) the other interested parties, in addition to workers, that are relevant to the OH&amp;S management system;</div>'),
    ('50811917-1fb4-40a3-9319-76c30b5e180b', '2116ff7a-b544-4916-8df4-b880b22b8c42', 'es', '', '<div>a) las otras partes interesadas, además de los trabajadores, que son pertinentes al sistema de gestión de la SST; </div>'),
    ('ed1b67e1-6ae7-41ed-8065-8c1d8d56c89d', '2217010d-7c8b-4d91-9f2d-973db32b8dd5', 'en', '', '<div>b) the relevant needs and expectations (i.e. requirements) of workers and other interested parties;</div>'),
    ('d81b46d2-9ce0-40fe-a1b8-2e829056cd56', '2217010d-7c8b-4d91-9f2d-973db32b8dd5', 'es', '', '<div>b) las necesidades y expectativas pertinentes (es decir, los requisitos) de los trabajadores y de otras partes interesadas; </div>'),
    ('c616b652-9a5a-414e-a39b-3b028855f11e', '1f16fc54-d7cc-49dc-927e-68cab02b891c', 'en', '', '<div>c) which of these needs and expectations are, or could become, legal requirements and other requirements.</div>'),
    ('db16d761-0e1d-43dd-8248-989d95560595', '1f16fc54-d7cc-49dc-927e-68cab02b891c', 'es', '', '<div>c) cuáles de estas necesidades y expectativas son, o podrían convertirse, en requisitos legales y otros requisitos. </div>'),
    ('187c7b1b-f1bf-4a77-b175-a3cf35069f87', '2016fde7-66a9-4787-8b00-9db7b12b8aaf', 'en', 'Determining the scope of the OH&S management system', '<div>The organization shall determine the boundaries and applicability of the OH&amp;S management system to establish its scope.</div><div>When determining this scope, the organization shall:</div><div>{clause_4.3.a}</div><div>{clause_4.3.b}</div><div>{clause_4.3.c}</div><div>The OH&amp;S management system shall include the activities, products and services within the organization’s control or influence that can impact the organization’s OH&amp;S performance.</div><div>The scope shall be available as documented information.</div>'),
    ('037c5a0c-6b6b-43b0-9ccc-412c180671e0', '2016fde7-66a9-4787-8b00-9db7b12b8aaf', 'es', 'Determinación del alcance del sistema de gestión de la SST', '<div>La organización debe determinar los límites y la aplicabilidad del sistema de gestión de la SST para establecer su alcance. </div><div>Cuando se determina este alcance, la organización debe:</div><div>{clause_4.3.a}</div><div>{clause_4.3.b}</div><div>{clause_4.3.c}</div><div>El sistema de gestión de la SST debe incluir las actividades, los productos y los servicios bajo el control o la influencia de la organización que pueden tener un impacto en el desempeño de la SST de la organización.</div><div>El alcance debe estar disponible como información documentada.</div>'),
    ('394f361c-99b3-4dd0-8920-bd1c30901110', '1d16f92e-41e0-4502-a49e-dc94ae2b85f6', 'en', '', '<div>a) consider the external and internal issues referred to in 4.1;</div>'),
    ('2e4f24cb-3954-4997-851a-d69f2d900c57', '1d16f92e-41e0-4502-a49e-dc94ae2b85f6', 'es', '', '<div>a) considerar las cuestiones externas e internas indicadas en el apartado 4.1;</div>'),
    ('b2c23e5d-12e9-4ff9-ade1-7731c7b18521', '1e16fac1-9f72-480d-a4d8-4271af2b8789', 'en', '', '<div>b) take into account the requirements referred to in 4.2;</div>'),
    ('b5c24316-6699-4522-8705-fbdeb2b16412', '1e16fac1-9f72-480d-a4d8-4271af2b8789', 'es', '', '<div>b) tener en cuenta los requisitos indicados en el apartado 4.2;</div>'),
    ('adc166de-f578-4eca-b6de-0766a3273c92', '1b16f608-7468-4ef8-b5a8-ccfeac2b82d0', 'en', '', '<div>c) take into account the planned or performed work-related activities.</div>'),
    ('bac17b55-fb62-44d1-87d1-93c9b8275da1', '1b16f608-7468-4ef8-b5a8-ccfeac2b82d0', 'es', '', '<div>c) tener en cuenta las actividades relacionadas con el trabajo, planificadas o realizadas.</div>'),
    ('57f7ac47-54ed-46a3-b319-ebd3f311055b', '1c16f79b-e36c-4cb3-9e8f-563bad2b8463', 'en', 'OH&S management system', '<div>The organization shall establish, implement, maintain and continually improve an OH&amp;S management system, including the processes needed and their interactions, in accordance with the requirements of this document.</div>'),
    ('3af77ea0-bbed-42f4-9c18-2be8de10e44c', '1c16f79b-e36c-4cb3-9e8f-563bad2b8463', 'es', 'Sistema de gestión de la SST', '<div>La organización debe establecer, implementar, mantener y mejorar continuamente un sistema de gestión de la SST, incluidos los procesos necesarios y sus interacciones, de acuerdo con los requisitos de este documento.</div>'),
    ('0e37a1f8-2e9f-4f7c-9e03-48a05b423204', '1916f2e2-ff7a-40ee-8a6e-dba8ba2b98da', 'en', 'Leadership and worker participation', '<div>{clause_5.1}</div><div>{clause_5.2}</div><div>{clause_5.3}</div><div>{clause_5.4}</div>'),
    ('1b37b66f-cf11-437b-8d9b-22db604239e3', '1916f2e2-ff7a-40ee-8a6e-dba8ba2b98da', 'es', 'Liderazgo y participación de los trabajadores', '<div>{clause_5.1}</div><div>{clause_5.2}</div><div>{clause_5.3}</div><div>{clause_5.4}</div>'),
    ('51fe0fe9-0971-4475-839f-da25f4b56ca5', '1a16f475-0621-4129-b9f3-ae85bb2b9a6d', 'en', 'Leadership and commitment', '<div>Top management shall demonstrate leadership and commitment with respect to the OH&amp;S management system by:</div><div>{clause_5.1.a}</div><div>{clause_5.1.b}</div><div>{clause_5.1.c}</div><div>{clause_5.1.d}</div><div>{clause_5.1.e}</div><div>{clause_5.1.f}</div><div>{clause_5.1.g}</div><div>{clause_5.1.h}</div><div>{clause_5.1.i}</div><div>{clause_5.1.j}</div><div>{clause_5.1.k}</div><div>{clause_5.1.l}</div><div>{clause_5.1.m}</div><div>NOTE: Reference to “business” in this document can be interpreted broadly to mean those activities that are core to the purposes of the organization’s existence.</div>'),
    ('4cfe080a-23ce-4a56-b9f6-123a07b58a8e', '1a16f475-0621-4129-b9f3-ae85bb2b9a6d', 'es', 'Liderazgo y compromiso', '<div>La alta dirección debe demostrar liderazgo y compromiso con respecto al sistema de gestión de la SST: </div><div>{clause_5.1.a}</div><div>{clause_5.1.b}</div><div>{clause_5.1.c}</div><div>{clause_5.1.d}</div><div>{clause_5.1.e}</div><div>{clause_5.1.f}</div><div>{clause_5.1.g}</div><div>{clause_5.1.h}</div><div>{clause_5.1.i}</div><div>{clause_5.1.j}</div><div>{clause_5.1.k}</div><div>{clause_5.1.l}</div><div>{clause_5.1.m}</div><div>NOTA: En este documento se puede interpretar el término “negocio” en su sentido más amplio para referirse a aquellas actividades que son esenciales para la existencia de la organización. </div>'),
    ('ce107d29-d8e7-45c9-85e7-89656e4bdde5', '1b14b771-4748-407d-bb77-46452c287ab9', 'en', '', '<div>a) taking overall responsibility and accountability for the prevention of work-related injury and ill health, as well as the provision of safe and healthy workplaces and activities;</div>'),
    ('c910754a-e911-48d2-92f7-587a814bfbce', '1b14b771-4748-407d-bb77-46452c287ab9', 'es', '', '<div>a) asumiendo la total responsabilidad y rendición de cuentas para la prevención de las lesiones y el deterioro de la salud relacionados con el trabajo, así como la provisión de actividades y lugares de trabajo seguros y saludables; </div>'),
    ('87cfa638-a4fc-45e0-90a3-84e0d7530c44', '1a14b5de-d1bb-4fb2-9a00-7f682b287926', 'en', '', '<div>b) ensuring that the OH&amp;S policy and related OH&amp;S objectives are established and are compatible with the strategic direction of the organization;</div>'),
    ('94cfbaaf-9e44-4f47-961a-181bdc531423', '1a14b5de-d1bb-4fb2-9a00-7f682b287926', 'es', '', '<div>b) asegurándose de que se establezcan la política de la SST y los objetivos relacionados de la SST y sean compatibles con la dirección estratégica de la organización;</div>'),
    ('f9719063-8bfd-4033-9771-de9789f32b0f', '1914b44b-7348-4763-aed5-85ff2a287793', 'en', '', '<div>c) ensuring the integration of the OH&amp;S management system requirements into the organization’s business processes;</div>'),
    ('f4718884-9956-4ee4-a851-4d647cf31698', '1914b44b-7348-4763-aed5-85ff2a287793', 'es', '', '<div>c) asegurándose de la integración de los requisitos del sistema de gestión de la SST en los procesos de negocio de la organización; </div>'),
    ('c70bfdfa-0329-4f1a-9caf-0b0a694b0666', '1814b2b8-0444-49a8-a514-c67229287600', 'en', '', '<div>d) ensuring that the resources needed to establish, implement, maintain and improve the OH&amp;S management system are available;</div>'),
    ('ac0bd379-ae1e-4641-8269-09d5864b340d', '1814b2b8-0444-49a8-a514-c67229287600', 'es', '', '<div>d) asegurándose de que los recursos necesarios para establecer, implementar, mantener y mejorar el sistema de gestión de la SST estén disponibles;</div>'),
    ('93b753a5-3196-46bd-971d-9d79a8a50769', '1f14bdbd-f31b-4341-ac43-635930288105', 'en', '', '<div>e) communicating the importance of effective OH&amp;S management and of conforming to the OH&amp;S management system requirements;</div>'),
    ('a6b7718e-a7b4-4bae-b6f5-e436a3a4ff8a', '1f14bdbd-f31b-4341-ac43-635930288105', 'es', '', '<div>e) comunicando la importancia de una gestión de la SST eficaz y conforme con los requisitos del sistema de gestión de la SST; </div>'),
    ('fa441904-1199-44c4-8b3a-736464de9978', '1e14bc2a-4520-43c6-a9fd-1cdc2f287f72', 'en', '', '<div>f) ensuring that the OH&amp;S management system achieves its intended outcome(s);</div>'),
    ('ff4420e3-01c4-4a13-ba5b-049771deadef', '1e14bc2a-4520-43c6-a9fd-1cdc2f287f72', 'es', '', '<div>f) asegurándose de que el sistema de gestión de la SST alcance los resultados previstos; </div>'),
    ('ace437cf-0f60-4547-a7f4-ec3bd4061aa3', '1d14ba97-f684-4237-8c0a-5ba32e287ddf', 'en', '', '<div>g) directing and supporting persons to contribute to the effectiveness of the OH&amp;S management system;</div>'),
    ('9fe42358-1618-4be0-af22-7200cf0612c4', '1d14ba97-f684-4237-8c0a-5ba32e287ddf', 'es', '', '<div>g) dirigiendo y apoyando a las personas, para contribuir a la eficacia del sistema de gestión de la SST; </div>'),
    ('8eb4e926-ed3c-441e-aa50-334ea41af13a', '1c14b904-4dbc-4bcc-a83f-1a062d287c4c', 'en', '', '<div>h) ensuring and promoting continual improvement;</div>'),
    ('abb516cd-bb44-450d-8fa1-2e81891ac6b9', '1c14b904-4dbc-4bcc-a83f-1a062d287c4c', 'es', '', '<div>h) asegurando y promoviendo la mejora continua; </div>'),
    ('66b36c21-c3ad-4991-912f-ab5d096935dd', '1314aad9-5656-4bb5-8020-b2fd34288751', 'en', '', '<div>i) supporting other relevant management roles to demonstrate their leadership as it applies to their areas of responsibility;</div>'),
    ('51b34b12-bb47-478a-9fef-34c20c693a96', '1314aad9-5656-4bb5-8020-b2fd34288751', 'es', '', '<div>i) apoyando otros roles pertinentes de la dirección, para demostrar su liderazgo aplicado a sus áreas de responsabilidad; </div>'),
    ('cf91f810-8307-4348-ae5f-32f88ff62d9c', '1214a946-3211-400a-a86c-9740332885be', 'en', '', '<div>j) developing, leading and promoting a culture in the organization that supports the intended outcomes of the OH&amp;S management system;</div>'),
    ('cc91f357-cd8f-4e1f-a434-bc0384f61c4b', '1214a946-3211-400a-a86c-9740332885be', 'es', '', '<div>j) desarrollando, liderando y promoviendo una cultura en la organización que apoye los resultados previstos del sistema de gestión de la SST;</div>'),
    ('bcac0bca-5241-44aa-adf0-52fa9d0ee0b6', '15126f68-65fe-4a84-adaa-ec82262632b0', 'en', '', '<div>k) protecting workers from reprisals when reporting incidents, hazards, risks and opportunities;</div>'),
    ('c1ac13a9-70c5-4c31-a0e0-83e59a0edbfd', '15126f68-65fe-4a84-adaa-ec82262632b0', 'es', '', '<div>k) protegiendo a los trabajadores de represalias al informar de incidentes, peligros, riesgos y oportunidades;</div>'),
    ('ed3505f3-c7d6-4503-9cc5-d4c77d18cfdf', '161270fb-d4da-45cf-8888-2a8f27263443', 'en', '', '<div>l) ensuring the organization establishes and implements a process(es) for consultation and participation of workers (see 5.4); </div>'),
    ('08353074-1b30-41d4-aaa5-cdb49018edc8', '161270fb-d4da-45cf-8888-2a8f27263443', 'es', '', '<div>l) asegurándose de que la organización establezca e implemente procesos para la consulta y la participación de los trabajadores (véase 5.4); </div>'),
    ('bb938088-abc8-41b0-9cc1-e2107dd2bb54', '1712728e-4374-46be-bf71-9a38282635d6', 'en', '', '<div>m) supporting the establishment and functioning of health and safety committees, [see 5.4 e) 1)].</div>'),
    ('a893629f-321c-4877-9924-2beb62d290d3', '1712728e-4374-46be-bf71-9a38282635d6', 'es', '', '<div>m) apoyando el establecimiento y funcionamiento de comités de seguridad y salud [véase 5.4 e) 1)]. </div>'),
    ('352d9839-722d-4ed9-8c3a-0915a171e775', '18127421-6367-4bf9-8376-e95529263769', 'en', 'OH&S policy', '<div>Top management shall establish, implement and maintain an OH&amp;S policy that:</div><div>{clause_5.2.a}</div><div>{clause_5.2.b}</div><div>{clause_5.2.c}</div><div>{clause_5.2.d}</div><div>{clause_5.2.e}</div><div>{clause_5.2.f}</div><div>The OH&amp;S policy shall:</div><div>— be available as documented information;</div><div>— be communicated within the organization;</div><div>— be available to interested parties, as appropriate;</div><div>— be relevant and appropriate.</div>'),
    ('502dc2ba-dbfb-4c82-8dfd-de4a9471d2fe', '18127421-6367-4bf9-8376-e95529263769', 'es', 'Política de la SST', '<div>La alta dirección debe establecer, implementar y mantener una política de la SST que: </div><div>{clause_5.2.a}</div><div>{clause_5.2.b}</div><div>{clause_5.2.c}</div><div>{clause_5.2.d}</div><div>{clause_5.2.e}</div><div>{clause_5.2.f}</div><div>La política de la SST debe:</div><div>— estar disponible como información documentada;</div><div>— comunicarse dentro de la organización;</div><div>— estar disponible para las partes interesadas, según sea apropiado;</div><div>— ser pertinente y apropiada. </div>'),
    ('c27a5676-5255-4d2e-a095-2abe9740960a', '191275b4-e299-4d40-bb3a-84d62a2638fc', 'en', '', '<div>a) includes a commitment to provide safe and healthy working conditions for the prevention of workrelated injury and ill health and is appropriate to the purpose, size and context of the organization and to the specific nature of its OH&amp;S risks and OH&amp;S opportunities;</div>'),
    ('bf7a51bd-dc38-483d-bcf9-28919c409de9', '191275b4-e299-4d40-bb3a-84d62a2638fc', 'es', '', '<div>a) incluya un compromiso para proporcionar condiciones de trabajo seguras y saludables para la prevención de lesiones y deterioro de la salud relacionados con el trabajo y que sea apropiada al propósito, tamaño y contexto de la organización y a la naturaleza específica de sus riesgos para la SST y sus oportunidades para la SST; </div>'),
    ('a009dc9f-9284-42d7-9ec8-c6ebc7cb2333', '1a127747-d429-44fb-88eb-79732b263a8f', 'en', '', '<div>b) provides a framework for setting the OH&amp;S objectives;</div>'),
    ('b309fa88-f55d-4010-a266-7d10e2cb4db4', '1a127747-d429-44fb-88eb-79732b263a8f', 'es', '', '<div>b) proporcione un marco de referencia para el establecimiento de los objetivos de la SST; </div>'),
    ('a0c23514-baad-4054-abb0-e65498a273c8', '1b1278da-d011-45aa-9336-5aec2c263c22', 'en', '', '<div>c) includes a commitment to fulfil legal requirements and other requirements;</div>'),
    ('85c20a93-6753-4383-8929-98e785a255df', '1b1278da-d011-45aa-9336-5aec2c263c22', 'es', '', '<div>c) incluya un compromiso para cumplir los requisitos legales y otros requisitos; </div>'),
    ('c6dbca35-2066-41cd-a4aa-ea290fc3b579', '1c127a6d-23c3-4ed5-95f3-85e92d263db5', 'en', '', '<div>d) includes a commitment to eliminate hazards and reduce OH&amp;S risks (see 8.1.2);</div>'),
    ('b9dbb5be-54db-4cde-9e86-fa462ac3dffa', '1c127a6d-23c3-4ed5-95f3-85e92d263db5', 'es', '', '<div>d) incluya un compromiso para eliminar los peligros y reducir los riesgos para la SST (véase 8.1.2); </div>'),
    ('754d9a22-7f90-4db2-8830-b1f2382c38ae', '0d1262d0-1da2-47ec-88f8-1a5a2e263f48', 'en', '', '<div>e) includes a commitment to continual improvement of the OH&amp;S management system;</div>'),
    ('6a4d88d1-71e1-43a9-a8e5-276d252c1ac5', '0d1262d0-1da2-47ec-88f8-1a5a2e263f48', 'es', '', '<div>e) incluya un compromiso para la mejora continua del sistema de gestión de la SST; </div>'),
    ('85d7f4eb-02b3-498b-a148-bf3f15bbbed7', '0e126463-adcf-49d7-bc10-55c72f2640db', 'en', '', '<div>f) includes a commitment to consultation and participation of workers, and, where they exist, workers’ representatives.</div>'),
    ('90d8063c-1e1d-42ac-bea1-babc18bbc390', '0e126463-adcf-49d7-bc10-55c72f2640db', 'es', '', '<div>f) incluya un compromiso para la consulta y la participación de los trabajadores, y cuando existan, de los representantes de los trabajadores.</div>'),
    ('0de1b953-d54f-412f-ab2d-362771940927', '8f0f5ddf-d38e-47d3-b1f3-f72f404b2c77', 'en', 'Organizational roles, responsibilities and authorities', '<div>Top management shall ensure that the responsibilities and authorities for relevant roles within the OH&amp;S management system are assigned and communicated at all levels within the organization and maintained as documented information. Workers at each level of the organization shall assume responsibility for those aspects of the OH&amp;S management system over which they have control.</div><div>NOTE: While responsibility and authority can be assigned, ultimately top management is still accountable for the functioning of the OH&amp;S management system.</div><div>Top management shall assign the responsibility and authority for:</div><div>{clause_5.3.a}</div><div>{clause_5.3.b}</div>'),
    ('28e1e3d4-ea13-4678-b1df-d6945493db80', '8f0f5ddf-d38e-47d3-b1f3-f72f404b2c77', 'es', 'Roles, responsabilidades y autoridades en la organización', '<div>La alta dirección debe asegurarse de que las responsabilidades y autoridades para los roles pertinentes dentro del sistema de gestión de la SST se asignen y comuniquen a todos los niveles dentro de la organización, y se mantengan como información documentada. Los trabajadores en cada nivel de la organización deben asumir la responsabilidad de aquellos aspectos del sistema de gestión de la SST sobre los que tengan control. </div><div>NOTA: Mientras que la responsabilidad y la autoridad se pueden asignar, finalmente, la alta dirección es la que rinde cuentas del funcionamiento del sistema de gestión de la SST.</div><div>La alta dirección debe asignar la responsabilidad y autoridad para:</div><div>{clause_5.3.a}</div><div>{clause_5.3.b}</div>'),
    ('dade562a-683b-4ec6-abc3-c3da5189b53e', '8e0f5c4c-615c-4d98-8d42-57223f4b2ae4', 'en', '', '<div>a) ensuring that the OH&amp;S management system conforms to the requirements of this document;</div>'),
    ('dfde5e09-a781-4085-90ab-7b455e89c9b5', '8e0f5c4c-615c-4d98-8d42-57223f4b2ae4', 'es', '', '<div>a) asegurarse de que el sistema de gestión de la SST es conforme con los requisitos de este documento;</div>'),
    ('e0063d19-f0bb-4265-a09d-0975568c1fbd', '910f6105-a5b3-4bad-84be-be75424b2f9d', 'en', '', '<div>b) reporting on the performance of the OH&amp;S management system to top management.</div>'),
    ('fb06679a-8481-4926-97df-5c2a598c2476', '910f6105-a5b3-4bad-84be-be75424b2f9d', 'es', '', '<div>b) informar a la alta dirección sobre el desempeño del sistema de gestión de la SST. </div>'),
    ('68e68e68-5bb6-40ec-b11d-95f052eb92fc', '900f5f72-3201-4022-bd5c-d9d8414b2e0a', 'en', 'Consultation and participation of workers', '<div>The organization shall establish, implement and maintain a process(es) for consultation and participation of workers at all applicable levels and functions, and, where they exist, workers’ representatives, in the development, planning, implementation, performance evaluation and actions for improvement of the OH&amp;S management system.</div><div>The organization shall:</div><div>{clause_5.4.a}</div><div>NOTE 1: Worker representation can be a mechanism for consultation and participation. </div><div>{clause_5.4.b}</div><div>{clause_5.4.c}</div><div>NOTE 2: Obstacles and barriers can include failure to respond to worker inputs or suggestions, language or literacy barriers, reprisals or threats of reprisals and policies or practices that discourage or penalize worker participation.</div><div>{clause_5.4.d}</div><div>{clause_5.4.e}</div><div>NOTE 3: Emphasizing the consultation and participation of non-managerial workers is intended to apply to persons carrying out the work activities, but is not intended to exclude, for example, managers who are impacted by work activities or other factors in the organization.</div><div>NOTE 4: It is recognized that the provision of training at no cost to workers and the provision of training during working hours, where possible, can remove significant barriers to worker participation.</div>'),
    ('55e6707f-404c-47cb-9ee2-a9cb47eb81ab', '900f5f72-3201-4022-bd5c-d9d8414b2e0a', 'es', 'Consulta y participación de los trabajadores', '<div>La organización debe establecer, implementar y mantener procesos para la consulta y la participación de los trabajadores a todos los niveles y funciones aplicables, y cuando existan, de los representantes de los trabajadores en el desarrollo, la planificación, la implementación, la evaluación del desempeño y las acciones para la mejora del sistema de gestión de la SST. </div><div>La organización debe: </div><div>{clause_5.4.a}</div><div>NOTA 1: La representación de los trabajadores puede ser un mecanismo para la consulta y la participación.&nbsp;</div><div>{clause_5.4.b}</div><div>{clause_5.4.c}</div><div>NOTA 2: Los obstáculos y barreras pueden incluir la falta de respuesta a los aportes o sugerencias de los trabajadores, barreras de idioma o de alfabetización, represalias o amenazas de represalias y políticas o prácticas que desalientan o penalizan la participación del trabajador. </div><div>{clause_5.4.d}</div><div>{clause_5.4.e}</div><div>NOTA 3: Enfatizar la consulta y la participación de los trabajadores no directivos pretende aplicarse a las personas que llevan a cabo actividades de trabajo, pero no pretende excluir, por ejemplo a los directivos que sufren un impacto por actividades de trabajo o por otros factores de la organización.</div><div>NOTA 4: Se reconoce que la provisión de formación sin costo para los trabajadores y la provisión de formación durante las horas de trabajo, cuando sea posible, puede eliminar barreras significativas para la participación de los trabajadores. </div>'),
    ('4d5cea7f-467b-481b-af6b-b3cbbec0c57b', '8b0f5793-56ca-42a7-a1b5-cf933c4b262b', 'en', '', '<div>a) provide mechanisms, time, training and resources necessary for consultation and participation;</div>'),
    ('605d0868-a390-4e1c-81a6-9ff0a9c0a46c', '8b0f5793-56ca-42a7-a1b5-cf933c4b262b', 'es', '', '<div>a) proporcionar los mecanismos, el tiempo, la formación y los recursos necesarios para la consulta y la participación; </div>'),
    ('e0ab0dd6-77f5-48c2-89ed-d11e6c5b00b2', '8a0f5600-aea1-4ffc-87d3-81763b4b2498', 'en', '', '<div>b) provide timely access to clear, understandable and relevant information about the OH&amp;S management system;</div>'),
    ('ddab091d-f752-4c19-bfe5-9571815b21c1', '8a0f5600-aea1-4ffc-87d3-81763b4b2498', 'es', '', '<div>b) proporcionar el acceso oportuno a información clara, comprensible y pertinente sobre el sistema de gestión de la SST; </div>'),
    ('e7887d95-2fed-4e71-80ad-4a8990e54941', '8d0f5ab9-6980-4c31-9fa7-71893e4b2951', 'en', '', '<div>c) determine and remove obstacles or barriers to participation and minimize those that cannot be removed;</div>'),
    ('da88691e-13e2-4cea-868e-e6267be52832', '8d0f5ab9-6980-4c31-9fa7-71893e4b2951', 'es', '', '<div>c) determinar y eliminar los obstáculos o barreras a la participación y minimizar aquellas que no puedan eliminarse; </div>'),
    ('4e1542f4-4ae7-46a8-961f-e0b46d1d7ab0', '8c0f5926-a565-4436-ba2e-be8c3d4b27be', 'en', '', '<div>d) emphasize the consultation of non-managerial workers on the following:</div><ul><li>{clause_5.4.d.1}</li><li>{clause_5.4.d.2}</li><li>{clause_5.4.d.3}</li><li>{clause_5.4.d.4}</li><li>{clause_5.4.d.5}</li><li>{clause_5.4.d.6}</li><li>{clause_5.4.d.7}</li><li>{clause_5.4.d.8}</li><li>{clause_5.4.d.9}</li></ul>'),
    ('33151873-92f5-487f-883f-e7c76a1d75f7', '8c0f5926-a565-4436-ba2e-be8c3d4b27be', 'es', '', '<div>d) enfatizar la consulta de los trabajadores no directivos sobre lo siguiente: </div><ul><li>{clause_5.4.d.1}</li><li>{clause_5.4.d.2}</li><li>{clause_5.4.d.3}</li><li>{clause_5.4.d.4}</li><li>{clause_5.4.d.5}</li><li>{clause_5.4.d.6}</li><li>{clause_5.4.d.7}</li><li>{clause_5.4.d.8}</li><li>{clause_5.4.d.9}</li></ul>'),
    ('332b02cb-67fa-47a7-bbe8-211fd71614ef', '970f6a77-7d23-4dcb-9b67-cce7384b1fdf', 'en', '', '<div>1) determining the needs and expectations of interested parties (see 4.2);</div>'),
    ('3e2b141c-6eb3-4140-bfee-079cca160078', '970f6a77-7d23-4dcb-9b67-cce7384b1fdf', 'es', '', '<div>1) la determinación de las necesidades y expectativas de las partes interesadas (véase 4.2); </div>'),
    ('95fa4d82-b1f0-4afe-9fc2-7f522c41fec6', '960f68e4-8b93-4610-b998-c97a374b1e4c', 'en', '', '<div>2) establishing the OH&amp;S policy (see 5.2);</div>'),
    ('8afa3c31-7ff7-4bed-81b1-854d49422c6d', '960f68e4-8b93-4610-b998-c97a374b1e4c', 'es', '', '<div>2) el establecimiento de la política de la SST (véase 5.2); </div>'),
    ('b2dcd6ac-daaf-4d38-b35e-414c60e28340', '890d15d6-c457-43d2-b2c0-dc643a48e46e', 'en', '', '<div>3) assigning organizational roles, responsibilities and authorities, as applicable (see 5.3);</div>'),
    ('c7dcf7bb-df35-49ef-8b90-29ef7de2b0e7', '890d15d6-c457-43d2-b2c0-dc643a48e46e', 'es', '', '<div>3) la asignación de roles, responsabilidades y autoridades de la organización, según sea aplicable (véase 5.3);</div>'),
    ('69d5daad-0e44-4201-b3b8-eae1f9defc91', '8a0d1769-3769-4b9d-8271-eac13b48e601', 'en', '', '<div>4) determining how to fulfil legal requirements and other requirements (see 6.1.3);</div>'),
    ('4cd5ad06-4a05-48da-9727-46ae04df0de2', '8a0d1769-3769-4b9d-8271-eac13b48e601', 'es', '', '<div>4) la determinación de cómo cumplir los requisitos legales y otros requisitos (véase 6.1.3); </div>'),
    ('6572d3ee-d82c-4312-87b9-b91612daafc2', '870d12b0-f138-4848-bfaa-df8e3848e148', 'en', '', '<div>5) establishing OH&amp;S objectives and planning to achieve them (see 6.2);</div>'),
    ('5272b605-c802-4009-8631-595907da9e71', '870d12b0-f138-4848-bfaa-df8e3848e148', 'es', '', '<div>5) el establecimiento de los objetivos de la SST y la planificación para lograrlos (véase 6.2);</div>'),
    ('457e5617-34ae-426b-af3d-5a43b2843b0b', '880d1443-7989-4b03-bcfb-1e0b3948e2db', 'en', '', '<div>6) determining applicable controls for outsourcing, procurement and contractors (see 8.1.4);</div>'),
    ('487e5ad0-5018-4b8c-a339-7338bd844c5c', '880d1443-7989-4b03-bcfb-1e0b3948e2db', 'es', '', '<div>6) la determinación de los controles aplicables para la contratación externa, las compras y los contratistas (véase 8.1.4);</div>'),
    ('cdae2220-9416-4ebc-a20e-6a68461137cc', '8d0d1c22-37bc-47e6-9761-2fd03e48eaba', 'en', '', '<div>7) determining what needs to be monitored, measured and evaluated (see 9.1);</div>'),
    ('eaae4fc7-3701-48bb-b910-2a535b1158db', '8d0d1c22-37bc-47e6-9761-2fd03e48eaba', 'es', '', '<div>7) la determinación de qué necesita seguimiento, medición y evaluación (véase 9.1); </div>'),
    ('64303271-ffa2-42b5-945f-a38dff84a4cd', '8e0d1db5-f95b-46e1-8e8e-2d8d3f48ec4d', 'en', '', '<div>8) planning, establishing, implementing and maintaining an audit programme(s) (see 9.2.2);</div>'),
    ('6f3043c2-1c7b-4496-9c1a-cd92e2847726', '8e0d1db5-f95b-46e1-8e8e-2d8d3f48ec4d', 'es', '', '<div>8) la planificación, el establecimiento, la implementación y el mantenimiento de programas de auditoría (véase 9.2.2);</div>'),
    ('7fa4bba2-ee60-4416-bd91-2f72854f228e', '8b0d18fc-5679-4b6c-8aa1-33da3c48e794', 'en', '', '<div>9) ensuring continual improvement (see 10.3);</div>'),
    ('74a4aa51-d187-4235-9e45-a4ed724f04a5', '8b0d18fc-5679-4b6c-8aa1-33da3c48e794', 'es', '', '<div>9) el aseguramiento de la mejora continua (véase 10.3);</div>'),
    ('902f166b-6842-413f-96a9-3cbf655911b7', '8c0d1a8f-e6a6-4d57-bdb9-6f473d48e927', 'en', '', '<div>e) emphasize the participation of non-managerial workers in the following:</div><ul><li>{clause_5.4.e.1}</li><li>{clause_5.4.e.2}</li><li>{clause_5.4.e.3}</li><li>{clause_5.4.e.4}</li><li>{clause_5.4.e.5}</li><li>{clause_5.4.e.6}</li><li>{clause_5.4.e.7}</li></ul>'),
    ('9b2f27bc-2035-4268-b402-383c68591670', '8c0d1a8f-e6a6-4d57-bdb9-6f473d48e927', 'es', '', '<div>e) enfatizar la participación de los trabajadores no directivos sobre lo siguiente: </div><ul><li>{clause_5.4.e.1}</li><li>{clause_5.4.e.2}</li><li>{clause_5.4.e.3}</li><li>{clause_5.4.e.4}</li><li>{clause_5.4.e.5}</li><li>{clause_5.4.e.6}</li><li>{clause_5.4.e.7}</li></ul>'),
    ('ab195694-0464-4710-a111-63d4e5c55da8', '910d226e-08e7-492a-94df-746c3248d7d6', 'en', '', '<div>1) determining the mechanisms for their consultation and participation;</div>'),
    ('90192c13-a18a-49d7-be8a-1667d2c53fbf', '910d226e-08e7-492a-94df-746c3248d7d6', 'es', '', '<div>1) la determinación de los mecanismos para su consulta y participación; </div>'),
    ('d132ebb5-618d-4039-9a0b-67a95f610859', '920d2401-5c99-4255-979c-9f693348d969', 'en', '', '<div>2) identifying hazards and assessing risks and opportunities (see 6.1.1 and 6.1.2);</div>'),
    ('c432d73e-ce8a-4d62-93e7-77c67a6132da', '920d2401-5c99-4255-979c-9f693348d969', 'es', '', '<div>2) la identificación de los peligros y la evaluación de los riesgos y oportunidades (véanse 6.1.1 y 6.1.2); </div>'),
    ('33859fda-aeb8-4936-81e9-e56a5dfd9afe', 'a08c621c-a2cb-4c38-8953-e192d1a057c4', 'en', '', '<div>3) determining actions to eliminate hazards and reduce OH&amp;S risks (see 6.1.4);</div>'),
    ('18857559-a800-42d5-afc1-c5b56afdaf75', 'a08c621c-a2cb-4c38-8953-e192d1a057c4', 'es', '', '<div>3) la determinación de acciones para eliminar los peligros y reducir los riesgos para la SST (véase 6.1.4);</div>'),
    ('f28ff9c3-655a-4b5f-8f5c-ff777e07eee7', 'a18c63af-2b1b-4bf3-ac51-4d9fd2a05957', 'en', '', '<div>4) determining competence requirements, training needs, training and evaluating training (see 7.2);</div>'),
    ('ed8ff1e4-1d4e-4c88-a932-57446107c140', 'a18c63af-2b1b-4bf3-ac51-4d9fd2a05957', 'es', '', '<div>4) la determinación de los requisitos de competencia, las necesidades de formación, la formación y la evaluación de la formación (véase 7.2);</div>'),
    ('80ee0f98-1710-4c5c-9d95-fdc05ce50fbc', 'a28c6542-898f-4742-b6e5-e088d3a05aea', 'en', '', '<div>5) determining what needs to be communicated and how this will be done (see 7.4);</div>'),
    ('8dee240f-9e34-485b-a876-11fb51e4fe6b', 'a28c6542-898f-4742-b6e5-e088d3a05aea', 'es', '', '<div>5) la determinación de qué información se necesita comunicar y cómo hacerlo (véase 7.4); </div>'),
    ('380fb609-8023-4a55-bf89-55c562fe727d', 'a38c66d5-cdd3-424d-b6f2-fce5d4a05c7d', 'en', '', '<div>6) determining control measures and their effective implementation and use (see 8.1, 8.1.3 and 8.2);</div>'),
    ('330fae2a-86db-40b6-9aa1-9e5a65fe7736', 'a38c66d5-cdd3-424d-b6f2-fce5d4a05c7d', 'es', '', '<div>6) la determinación de medidas de control y su implementación y uso eficaces (véanse 8.1, 8.1.3 y 8.2); </div>'),
    ('f8b42206-aea4-40b2-9ab0-212e78cd5372', '9c8c5bd0-062f-471c-825d-9d26cda05178', 'en', '', '<div>7) investigating incidents and nonconformities and determining corrective actions (see 10.2).</div>'),
    ('15b44fad-a0f4-46a9-b741-c5618dcd7481', '9c8c5bd0-062f-471c-825d-9d26cda05178', 'es', '', '<div>7) la investigación de los incidentes y no conformidades y la determinación de las acciones correctivas (véase 10.2).</div>'),
    ('a604342f-31c6-4c8b-a0cb-4e1bc8b8af3b', '9d8c5d63-ae58-49c7-a5e7-db43cea0530b', 'en', 'Planning', '<div>{clause_6.1}</div><div>{clause_6.2}</div>'),
    ('99041fb8-4d30-45ac-9b54-bae0b3b88e2c', '9d8c5d63-ae58-49c7-a5e7-db43cea0530b', 'es', 'Planificación', '<div>{clause_6.1}</div><div>{clause_6.2}</div>'),
    ('66bc27e4-d7c8-4758-9ee8-dbc47716f770', '9e8c5ef6-fcf2-4856-b1dd-0cfccfa0549e', 'en', 'Actions to address risks and opportunities', '<div>{clause_6.1.1}</div><div>{clause_6.1.2}</div><div>{clause_6.1.3}</div><div>{clause_6.1.4}</div>'),
    ('6bbc2fc3-c8a9-448f-8513-83f77416f2b7', '9e8c5ef6-fcf2-4856-b1dd-0cfccfa0549e', 'es', 'Acciones para abordar riesgos y oportunidades', '<div>{clause_6.1.1}</div><div>{clause_6.1.2}</div><div>{clause_6.1.3}</div><div>{clause_6.1.4}</div>'),
    ('fdb4f985-8c05-45a1-a9ac-58d99d579c01', '9f8c6089-aaed-47d1-88db-4179d0a05631', 'en', 'General', '<div>When planning for the OH&amp;S management system, the organization shall consider the issues referred to in 4.1 (context), the requirements referred to in 4.2 (interested parties) and 4.3 (the scope of its OH&amp;S management system) and determine the risks and opportunities that need to be addressed to:</div><div>{clause_6.1.1.a}</div><div>{clause_6.1.1.b}</div><div>{clause_6.1.1.c}</div><div>When determining the risks and opportunities for the OH&amp;S management system and its intended outcomes that need to be addressed, the organization shall take into account:</div><div>— hazards (see 6.1.2.1);</div><div>— OH&amp;S risks and other risks (see 6.1.2.2);</div><div>— OH&amp;S opportunities and other opportunities (see 6.1.2.3);</div><div>— legal requirements and other requirements (see 6.1.3).</div><div>The organization, in its planning process(es), shall determine and assess the risks and opportunities that are relevant to the intended outcomes of the OH&amp;S management system associated with changes in the organization, its processes or the OH&amp;S management system. In the case of planned changes, permanent or temporary, this assessment shall be undertaken before the change is implemented (see 8.1.3).</div><div>The organization shall maintain documented information on:</div><div>— risks and opportunities;</div><div>— the process(es) and actions needed to determine and address its risks and opportunities (see 6.1.2 to 6.1.4) to the extent necessary to have confidence that they are carried out as planned.</div>'),
    ('10b5176e-c7c4-497a-ab34-b89688577af2', '9f8c6089-aaed-47d1-88db-4179d0a05631', 'es', 'Generalidades', '<div>Al planificar el sistema de gestión de la SST, la organización debe considerar las cuestiones referidas en el apartado 4.1 (contexto), los requisitos referidos en los apartados 4.2 (partes interesadas) y 4.3 (el alcance de su sistema de gestión de la SST) y determinar los riesgos y oportunidades que es necesario abordar con el fin de: </div><div>{clause_6.1.1.a}</div><div>{clause_6.1.1.b}</div><div>{clause_6.1.1.c}</div><div>Al determinar los riesgos y oportunidades para el sistema de gestión de la SST y sus resultados previstos que es necesario abordar, la organización debe tener en cuenta: </div><div>— los peligros (véase 6.1.2.1);</div><div>— los riesgos para la SST y otros riesgos (véase 6.1.2.2);</div><div>— las oportunidades para la SST y otras oportunidades (véase 6.1.2.3);</div><div>— los requisitos legales y otros requisitos (véase 6.1.3). </div><div>La organización, en sus procesos de planificación, debe determinar y evaluar los riesgos y oportunidades que son pertinentes para los resultados previstos del sistema de gestión de la SST asociados con los cambios en la organización, sus procesos, o el sistema de gestión de la SST. En el caso de cambios planificados, permanentes o temporales, esta evaluación debe llevarse a cabo antes de que se implemente el cambio (véase 8.1.3). </div><div>La organización debe mantener información documentada sobre: </div><div>— los riesgos y oportunidades;</div><div>— los procesos y acciones necesarios para determinar y abordar sus riesgos y oportunidades (véase desde 6.1.2 hasta 6.1.4), en la medida necesaria para tener la confianza de que se llevan a cabo según lo planificado. </div>'),
    ('3b478cf2-8169-402e-a265-dd223639e886', 'a88c6eb4-e320-4a30-b7a0-9daac9a04b2c', 'en', '', '<div>a) give assurance that the OH&amp;S management system can achieve its intended outcome(s);</div>'),
    ('5047ae01-0b4b-4b3d-8a7c-e7bd533a162d', 'a88c6eb4-e320-4a30-b7a0-9daac9a04b2c', 'es', '', '<div>a) asegurar que el sistema de gestión de la SST pueda alcanzar sus resultados previstos;</div>'),
    ('8b32e8bb-c197-45d7-a783-81efe389faaf', 'a98c7047-be90-496b-9696-1517caa04cbf', 'en', '', '<div>b) prevent, or reduce, undesired effects;</div>'),
    ('7632c7ac-2470-4310-8f51-994cd689e638', 'a98c7047-be90-496b-9696-1517caa04cbf', 'es', '', '<div>b) prevenir o reducir efectos no deseados; </div>'),
    ('04e9ac79-6f92-4e05-a0dc-1ad56f3afced', 'a68eaa25-1936-47e1-8075-f995d7a29fcd', 'en', '', '<div>c) achieve continual improvement.</div>'),
    ('1fe9d6fa-304b-4c46-bb22-1c0a523acf46', 'a68eaa25-1936-47e1-8075-f995d7a29fcd', 'es', '', '<div>c) lograr la mejora continua. </div>'),
    ('8dc86ac8-c616-4d0c-90b8-4ed0b5c78fec', 'a58ea892-5796-48e6-becb-f878d6a29e3a', 'en', 'Hazard identification and assessment of risks and opportunities', '<div>{clause_6.1.2.1}</div><div>{clause_6.1.2.2}</div><div>{clause_6.1.2.3}</div>'),
    ('7ac84cdf-aaac-43eb-9948-9cabcac7b0fb', 'a58ea892-5796-48e6-becb-f878d6a29e3a', 'es', 'Identificación de peligros y evaluación de los riesgos y oportunidades', '<div>{clause_6.1.2.1}</div><div>{clause_6.1.2.2}</div><div>{clause_6.1.2.3}</div>'),
    ('bcf11a33-1500-4fcf-a695-558748677c57', 'a48ea6ff-0680-4e57-9402-02cfd5a29ca7', 'en', 'Hazard identification', '<div>The organization shall establish, implement and maintain a process(es) for hazard identification that is ongoing and proactive. The process(es) shall take into account, but not be limited to:</div><div>{clause_6.1.2.1.a}</div><div>{clause_6.1.2.1.b}</div><div>{clause_6.1.2.1.c}</div><div>{clause_6.1.2.1.d}</div><div>{clause_6.1.2.1.e}</div><div>{clause_6.1.2.1.f}</div><div>{clause_6.1.2.1.g}</div><div>{clause_6.1.2.1.h}</div>'),
    ('d7f144b4-2697-4898-8b97-6b744b678110', 'a48ea6ff-0680-4e57-9402-02cfd5a29ca7', 'es', 'Identificación de peligros', '<div>La organización debe establecer, implementar y mantener procesos de identificación continua y proactiva de los peligros. Los procesos deben tener en cuenta, pero no limitarse a: </div><div>{clause_6.1.2.1.a}</div><div>{clause_6.1.2.1.b}</div><div>{clause_6.1.2.1.c}</div><div>{clause_6.1.2.1.d}</div><div>{clause_6.1.2.1.e}</div><div>{clause_6.1.2.1.f}</div><div>{clause_6.1.2.1.g}</div><div>{clause_6.1.2.1.h}&nbsp;</div>'),
    ('8c668d0a-aa66-4666-9ec5-e1ba6ad7f62e', 'a38ea56c-7653-4c6c-b6ea-1ec2d4a29b14', 'en', '', '<div>a) how work is organized, social factors (including workload, work hours, victimization, harassment and bullying), leadership and the culture in the organization;</div>'),
    ('916694e9-fd53-4aa5-a86f-a9a557d7d845', 'a38ea56c-7653-4c6c-b6ea-1ec2d4a29b14', 'es', '', '<div>a) cómo se organiza el trabajo, los factores sociales [incluyendo la carga de trabajo, horas de trabajo, victimización y acoso (bullying) e intimidación], el liderazgo y la cultura de la organización; </div>'),
    ('9697de75-f2c0-4c91-a109-70e96993c1b1', 'a28ea3d9-5744-4c9d-8f90-dd29d3a29981', 'en', '', '<div>b) routine and non-routine activities and situations, including hazards arising from:</div><ul><li>{clause_6.1.2.1.b.1}</li><li>{clause_6.1.2.1.b.2}</li><li>{clause_6.1.2.1.b.3}</li><li>{clause_6.1.2.1.b.4}</li></ul>'),
    ('8997c9fe-ea5a-4a8a-92b2-1c067493d302', 'a28ea3d9-5744-4c9d-8f90-dd29d3a29981', 'es', '', '<div>b) las actividades y las situaciones rutinarias y no rutinarias, incluyendo los peligros que surjan de:</div><ul><li>{clause_6.1.2.1.b.1}</li><li>{clause_6.1.2.1.b.2}</li><li>{clause_6.1.2.1.b.3}</li><li>{clause_6.1.2.1.b.4}</li></ul>'),
    ('72f8b254-b21a-4648-9dff-4f14d0974860', 'a18ea246-e432-44d2-b1a6-e12cd2a297ee', 'en', '', '<div>1) infrastructure, equipment, materials, substances and the physical conditions of the workplace;</div>'),
    ('57f887d3-fca2-411f-974c-aea7ed977607', 'a18ea246-e432-44d2-b1a6-e12cd2a297ee', 'es', '', '<div>1) la infraestructura, los equipos, los materiales, las sustancias y las condiciones físicas del lugar de trabajo; </div>'),
    ('723ec6df-2d75-49bb-a9d1-a6ab9592a5ab', 'a08ea0b3-9964-4c03-820a-89b3d1a2965b', 'en', '', '<div>2) product and service design, research, development, testing, production, assembly, construction, service delivery, maintenance and disposal;</div>'),
    ('853ee4c8-8a89-4fbc-a141-58d0a092b6fc', 'a08ea0b3-9964-4c03-820a-89b3d1a2965b', 'es', '', '<div>2) el diseño de productos y servicios, la investigación, el desarrollo, los ensayos, la producción, el montaje, la construcción, la prestación de servicios, el mantenimiento y la disposición; </div>'),
    ('9234d7b6-6169-4362-b01e-4e7e8509dde2', '9f8e9f20-1112-4948-ab94-a816d0a294c8', 'en', '', '<div>3) human factors;</div>'),
    ('8f34d2fd-f46b-4639-be50-60517a09cc91', '9f8e9f20-1112-4948-ab94-a816d0a294c8', 'es', '', '<div>3) los factores humanos;</div>'),
    ('2c0dfb31-60a9-49bd-b90b-83cdd41da4f5', 'ae8eb6bd-bc18-4079-a29d-984dcfa29335', 'en', '', '<div>4) how the work is performed;</div>'),
    ('370e0c82-d6c7-4eae-971c-7dd2c71d907e', 'ae8eb6bd-bc18-4079-a29d-984dcfa29335', 'es', '', '<div>4) cómo se realiza el trabajo;</div>'),
    ('931181e0-40ac-47c4-9ebb-66a8b07e78d4', 'ad8eb52a-9c25-4b3e-8a14-bc90cea291a2', 'en', '', '<div>c) past relevant incidents, internal or external to the organization, including emergencies, and their causes;</div>'),
    ('b011af87-30d7-4d13-89c0-ec93957e4e53', 'ad8eb52a-9c25-4b3e-8a14-bc90cea291a2', 'es', '', '<div>c) los incidentes pasados pertinentes internos o externos a la organización, incluyendo emergencias, y sus causas; </div>'),
    ('197b10a0-c8c7-40d0-abe5-3f68e14c8904', 'ac90f22e-b2d1-453a-babf-4cd03da57ef6', 'en', '', '<div>d) potential emergency situations;</div>'),
    ('367b3e47-6868-4c97-82e6-ff53e64c90e3', 'ac90f22e-b2d1-453a-babf-4cd03da57ef6', 'es', '', '<div>d) las situaciones de emergencia potenciales; </div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('affd20f1-41fc-42f9-9e36-788d7abfc3a5', 'ad90f3c1-ec98-48a5-b1ec-4a8d3ea58089', 'en', '', '<div>e) people, including consideration of:</div><ul><li>{clause_6.1.2.1.e.1}</li><li>{clause_6.1.2.1.e.2}</li><li>{clause_6.1.2.1.e.3}</li></ul>'),
    ('bafd3242-95ac-4822-a5f1-a2928dbfe18e', 'ad90f3c1-ec98-48a5-b1ec-4a8d3ea58089', 'es', '', '<div>e) las personas, incluyendo la consideración de:</div><ul><li>{clause_6.1.2.1.e.1}</li><li>{clause_6.1.2.1.e.2}</li><li>{clause_6.1.2.1.e.3}</li></ul>'),
    ('cb71aa22-248b-41ca-8768-047275bd5926', 'aa90ef08-ab6e-4710-adff-50da3ba57bd0', 'en', '', '<div>1) those with access to the workplace and their activities, including workers, contractors, visitors and other persons;</div>'),
    ('c07198d1-2a75-47d1-a81c-79ed92bd86cd', 'aa90ef08-ab6e-4710-adff-50da3ba57bd0', 'es', '', '<div>1) aquéllas con acceso al lugar de trabajo y sus actividades, incluyendo trabajadores, contratistas, visitantes y otras personas; </div>'),
    ('dbfc04eb-8400-49a3-a080-11bf93eca7cf', 'ab90f09b-9cfd-4ecb-a117-8c473ca57d63', 'en', '', '<div>2) those in the vicinity of the workplace who can be affected by the activities of the organization;</div>'),
    ('e6fc163c-eb00-45f4-bdd9-0d3c86ec9358', 'ab90f09b-9cfd-4ecb-a117-8c473ca57d63', 'es', '', '<div>2) aquéllas en las inmediaciones del lugar de trabajo que pueden verse afectadas por las actividades de la organización; </div>'),
    ('fea9c52c-b5c7-4ff4-bd35-164c6ed81638', 'b090f87a-0c4b-438e-961e-f96441a58542', 'en', '', '<div>3) workers at a location not under the direct control of the organization;</div>'),
    ('13a9e63b-4ec7-43a3-9566-feef7bd82aaf', 'b090f87a-0c4b-438e-961e-f96441a58542', 'es', '', '<div>3) los trabajadores en una ubicación que no está bajo el control directo de la organización;</div>'),
    ('b5a2c92d-99fa-44ed-bd8f-bfe1b518ed29', 'b190fa0d-161c-4d49-a5d0-07c142a586d5', 'en', '', '<div>f) other issues, including consideration of:</div><ul><li>{clause_6.1.2.1.f.1}</li><li>{clause_6.1.2.1.f.2}</li><li>{clause_6.1.2.1.f.3}</li></ul>'),
    ('98a29b86-cbf3-43fe-a0fe-1baeb018e54a', 'b190fa0d-161c-4d49-a5d0-07c142a586d5', 'es', '', '<div>f) otras cuestiones, incluyendo la consideración de: </div><ul><li>{clause_6.1.2.1.f.1}</li><li>{clause_6.1.2.1.f.2}</li><li>{clause_6.1.2.1.f.3}</li></ul>'),
    ('b13fc26e-c96d-444e-9190-8e16ae146dfa', 'ae90f554-2ed3-4454-a308-fc8e3fa5821c', 'en', '', '<div>1) the design of work areas, processes, installations, machinery/equipment, operating procedures and work organization, including their adaptation to the needs and capabilities of the workers involved;</div>'),
    ('9e3fa485-3d30-46dd-9008-2e5993144379', 'ae90f554-2ed3-4454-a308-fc8e3fa5821c', 'es', '', '<div>1) el diseño de las áreas de trabajo, los procesos, las instalaciones, la maquinaria/equipos, los procedimientos operativos y la organización del trabajo, incluyendo su adaptación a las necesidades y capacidades de los trabajadores involucrados; </div>'),
    ('914b4497-20d3-4d77-b914-2f43e07a0063', 'af90f6e7-9daf-4f9f-a059-3b0b40a583af', 'en', '', '<div>2) situations occurring in the vicinity of the workplace caused by work-related activities under the control of the organization;</div>'),
    ('944b4950-9a7e-46b0-ad10-4838db79f884', 'af90f6e7-9daf-4f9f-a059-3b0b40a583af', 'es', '', '<div>2) las situaciones que ocurren en las inmediaciones del lugar de trabajo causadas por actividades relacionadas con el trabajo bajo el control de la organización; </div>'),
    ('11b79088-bad7-41f8-9bf9-34909c68805c', 'a490e596-51db-4122-a478-d0b845a58b8e', 'en', '', '<div>3) situations not controlled by the organization and occurring in the vicinity of the workplace that can cause injury and ill health to persons in the workplace;</div>'),
    ('feb7729f-a613-4caf-985b-7e6b91686f0b', 'a490e596-51db-4122-a478-d0b845a58b8e', 'es', '', '<div>3) las situaciones no controladas por la organización y que ocurren en las inmediaciones del lugar de trabajo que pueden causar lesiones y deterioro de la salud a personas en el lugar de trabajo;</div>'),
    ('8b51a839-d2a7-4bc1-8b71-5b9513611f9d', 'a590e729-c58d-4cad-a87e-1fd546a58d21', 'en', '', '<div>g) actual or proposed changes in organization, operations, processes, activities and the OH&amp;S management system (see 8.1.3);</div>'),
    ('a651d2ba-27b3-449a-8d35-30ca16612456', 'a590e729-c58d-4cad-a87e-1fd546a58d21', 'es', '', '<div>g) los cambios reales o propuestos en la organización, operaciones, procesos, actividades y el sistema de gestión de la SST (véase 8.1.3); </div>'),
    ('2a2c9687-2c5c-4167-b92b-2b93bc7db7cb', 'b2933a37-b7a1-4a5b-908e-eb7b43a7c6ff', 'en', '', '<div>h) changes in knowledge of, and information about, hazards.</div>'),
    ('0d2c68e0-358f-4100-8e25-a5a8c77dc91c', 'b2933a37-b7a1-4a5b-908e-eb7b43a7c6ff', 'es', '', '<div>h) los cambios en el conocimiento y la información sobre los peligros. </div>'),
    ('7d7be81e-7911-45be-8cdc-03261f4d0282', 'b19338a4-c613-45a0-a15d-dd3e42a7c56c', 'en', 'Assessment of OH&S risks and other risks to the OH&S management system', '<div>The organization shall establish, implement and maintain a process(es) to:</div><div>{clause_6.1.2.2.a}</div><div>{clause_6.1.2.2.b}</div><div>The organization’s methodology(ies) and criteria for the assessment of OH&amp;S risks shall be defined with respect to their scope, nature and timing to ensure they are proactive rather than reactive and are used in a systematic way. Documented information shall be maintained and retained on the methodology(ies) and criteria.</div>'),
    ('8a7bfc95-6065-4bad-86fa-6789144cf131', 'b19338a4-c613-45a0-a15d-dd3e42a7c56c', 'es', 'Evaluación de los riesgos para la SST y otros riesgos para el sistema de gestión de la SST', '<div>La organización debe establecer, implementar y mantener procesos para: </div><div>{clause_6.1.2.2.a}</div><div>{clause_6.1.2.2.b}</div><div>Las metodologías y criterios de la organización para la evaluación de los riesgos para la SST deben definirse con respecto al alcance, naturaleza y momento en el tiempo, para asegurarse de que son más proactivas que reactivas y que se utilicen de un modo sistemático. Estas metodologías y criterios deben mantenerse y conservarse como información documentada. </div>'),
    ('827cbf9d-928e-455d-83d6-a4f103d6e651', 'b4933d5d-f11c-4bb5-99a9-bdb145a7ca25', 'en', '', '<div>a) assess OH&amp;S risks from the identified hazards, while taking into account the effectiveness of existing controls;</div>'),
    ('857cc456-1ecc-42ce-8dde-e09e0ed6f7a2', 'b4933d5d-f11c-4bb5-99a9-bdb145a7ca25', 'es', '', '<div>a) evaluar los riesgos para la SST a partir de los peligros identificados, teniendo en cuenta la eficacia de los controles existentes; </div>'),
    ('0b84205c-3761-41e4-b08b-a4dc6ada6d00', 'b3933bca-ccd6-400a-bca3-41d444a7c892', 'en', '', '<div>b) determine and assess the other risks related to the establishment, implementation, operation and maintenance of the OH&amp;S management system.</div>'),
    ('00840f0b-2a08-4333-a994-d05f87da9aa7', 'b3933bca-ccd6-400a-bca3-41d444a7c892', 'es', '', '<div>b) determinar y evaluar los otros riesgos relacionados con el establecimiento, implementación, operación y mantenimiento del sistema de gestión de la SST. </div>'),
    ('e836fc5b-1afe-4e53-a174-b38f71cb6477', 'ae9333eb-b854-4e2f-b839-52f73fa7c0b3', 'en', 'Assessment of OH&S opportunities and other opportunities for the OH&S management system', '<div>The organization shall establish, implement and maintain a process(es) to assess:</div><div>{clause_6.1.2.3.a}</div><div>{clause_6.1.2.3.a}</div><div>NOTE: OH&amp;S risks and OH&amp;S opportunities can result in other risks and other opportunities for the organization.</div>'),
    ('d336db4c-2859-4004-992a-f3ec74cb6930', 'ae9333eb-b854-4e2f-b839-52f73fa7c0b3', 'es', 'Evaluación de las oportunidades para la SST y otras oportunidades para el sistema de gestión de la SST', '<div>La organización debe establecer, implementar y mantener procesos para evaluar: </div><div>{clause_6.1.2.3.a}</div><div>{clause_6.1.2.3.a}</div><div>NOTA: Los riesgos para la SST y las oportunidades para la SST pueden dar como resultado otros riesgos y otras oportunidades para la organización. </div>'),
    ('984d3392-2b6c-453a-a109-93c291c1754e', 'ad933258-4976-4fe4-a91b-9f0a3ea7bf20', 'en', '', '<div>a) OH&amp;S opportunities to enhance OH&amp;S performance, while taking into account planned changes to the organization, its policies, its processes or its activities and:</div><ul><li>{clause_6.1.2.3.a.1}</li><li>{clause_6.1.2.3.a.2}</li></ul>'),
    ('ad4d54a1-d3e5-4361-924a-0a5d7ec15765', 'ad933258-4976-4fe4-a91b-9f0a3ea7bf20', 'es', '', '<div>a) las oportunidades para la SST que permitan mejorar el desempeño de la SST, teniendo en cuenta los cambios planificados en la organización, sus políticas, sus procesos o sus actividades, y: </div><ul><li>{clause_6.1.2.3.a.1}</li><li>{clause_6.1.2.3.a.2}</li></ul>'),
    ('bcd77c21-8f6b-44e9-9066-fddd097e218d', 'b0933711-30c2-4bd9-a527-e97d41a7c3d9', 'en', '', '<div>1) opportunities to adapt work, work organization and work environment to workers;</div>'),
    ('a7d75b12-b8e1-4cf2-9f26-8742ec7df3e6', 'b0933711-30c2-4bd9-a527-e97d41a7c3d9', 'es', '', '<div>1) las oportunidades para adaptar el trabajo, la organización del trabajo y el ambiente de trabajo a los trabajadores; </div>'),
    ('25b60810-c473-4b00-ad96-857852851d8c', 'af93357e-2a1b-4b9e-8d73-cdc040a7c246', 'en', '', '<div>2) opportunities to eliminate hazards and reduce OH&amp;S risks;</div>'),
    ('22b60357-bb41-4b67-a36c-0e8367853e9b', 'af93357e-2a1b-4b9e-8d73-cdc040a7c246', 'es', '', '<div>2) las oportunidades de eliminar los peligros y reducir los riesgos para la SST; </div>'),
    ('030847cf-b5bd-40ef-a72c-3ebb97346e53', 'aa932d9f-0e0e-4763-b111-92234ba7d397', 'en', '', '<div>b) other opportunities for improving the OH&amp;S management system.</div>'),
    ('f6083358-b136-4438-ae59-c480b23498d4', 'aa932d9f-0e0e-4763-b111-92234ba7d397', 'es', '', '<div>b) otras oportunidades para mejorar el sistema de gestión de la SST. </div>'),
    ('e4d8f926-4b23-4786-a987-85ce64310b2a', 'a9932c0c-9f09-49a8-8d46-50864aa7d204', 'en', 'Determination of legal requirements and other requirements', '<div>The organization shall establish, implement and maintain a process(es) to:</div><div>{clause_6.1.3.a}</div><div>{clause_6.1.3.b}</div><div>{clause_6.1.3.c}</div><div>The organization shall maintain and retain documented information on its legal requirements and other requirements and shall ensure that it is updated to reflect any changes.</div><div>NOTE: Legal requirements and other requirements can result in risks and opportunities for the organization.</div>'),
    ('01d926cd-87f1-4345-8ed8-810169311309', 'a9932c0c-9f09-49a8-8d46-50864aa7d204', 'es', 'Determinación de los requisitos legales y otros requisitos', '<div>La organización debe establecer, implementar y mantener procesos para: </div><div>{clause_6.1.3.a}</div><div>{clause_6.1.3.b}</div><div>{clause_6.1.3.c}</div><div>La organización debe mantener y conservar información documentada sobre sus requisitos legales y otros requisitos y debe asegurarse de que se actualiza para reflejar cualquier cambio.</div><div>NOTA Los requisitos legales y otros requisitos pueden dar como resultado riesgos y oportunidades para la organización. </div>'),
    ('46afac3e-1555-4a3a-80a3-e4c64ad1fb9a', 'a881e158-b722-4f34-89eb-a19e39966e20', 'en', '', '<div>a) determine and have access to up-to-date legal requirements and other requirements that are applicable to its hazards, OH&amp;S risks and OH&amp;S management system;</div>'),
    ('53afc0b5-bdcf-4861-86c7-d4a92fd1d119', 'a881e158-b722-4f34-89eb-a19e39966e20', 'es', '', '<div>a) determinar y tener acceso a los requisitos legales y otros requisitos actualizados que sean aplicables a sus peligros, sus riesgos para la SST y su sistema de gestión de la SST;</div>'),
    ('66ba0027-04e8-4353-8155-9fb307637f83', 'a981e2eb-292b-46ff-a784-00db3a966fb3', 'en', '', '<div>b) determine how these legal requirements and other requirements apply to the organization and what needs to be communicated;</div>'),
    ('49b9d280-1243-4504-ae5b-2c48026377a4', 'a981e2eb-292b-46ff-a784-00db3a966fb3', 'es', '', '<div>b) determinar cómo estos requisitos legales y otros requisitos aplican a la organización y qué necesita comunicarse;</div>'),
    ('481189fc-ae5d-4000-b88b-b27c95c19558', 'aa81e47e-9a40-40ee-a54e-5cb43b967146', 'en', '', '<div>c) take these legal requirements and other requirements into account when establishing, implementing, maintaining and continually improving its OH&amp;S management system. </div>'),
    ('3d1178ab-a52a-4067-a119-9dffa2c1a9cf', 'aa81e47e-9a40-40ee-a54e-5cb43b967146', 'es', '', '<div>c) tener en cuenta estos requisitos legales y otros requisitos al establecer, implementar, mantener y mejorar de manera continua su sistema de gestión de la SST.</div>'),
    ('4bb216bd-7954-49e9-9cba-05914f5c11c9', 'ab81e611-a0e6-4129-b037-99113c9672d9', 'en', 'Planning action', '<div>The organization shall plan:</div><div>{clause_6.1.4.a}</div><div>{clause_6.1.4.b}</div><div>The organization shall take into account the hierarchy of controls (see 8.1.2) and outputs from the OH&amp;S management system when planning to take action.</div><div>When planning its actions, the organization shall consider best practices, technological options and financial, operational and business requirements.</div>'),
    ('4eb21b76-a2cb-41f2-8056-07be4a5c09ea', 'ab81e611-a0e6-4129-b037-99113c9672d9', 'es', 'Planificación de acciones', '<div>La organización debe planificar:</div><div>{clause_6.1.4.a}</div><div>{clause_6.1.4.b}</div><div>La organización debe tener en cuenta la jerarquía de los controles (véase 8.1.2) y las salidas del sistema de gestión de la SST cuando planifique la toma de acciones.</div><div>Al planificar sus acciones la organización debe considerar las mejores prácticas, las opciones tecnológicas y los requisitos financieros, operacionales y de negocio. </div>'),
    ('6180f7b2-62fb-4abe-b9f2-a4e2100210c6', 'ac81e7a4-33bd-41f0-8725-70ea3d96746c', 'en', '', '<div>a) actions to:</div><ul><li>{clause_6.1.4.a.1}</li><li>{clause_6.1.4.a.2}</li><li>{clause_6.1.4.a.3}</li></ul>'),
    ('768118c1-4a4f-40ad-9f53-e37d2d023e6d', 'ac81e7a4-33bd-41f0-8725-70ea3d96746c', 'es', '', '<div>a) las acciones para: </div><ul><li>{clause_6.1.4.a.1}</li><li>{clause_6.1.4.a.2}</li><li>{clause_6.1.4.a.3}</li></ul>'),
    ('b3e6bc7b-1646-4667-b5cf-5fafbad626ef', 'ad81e937-2af2-4c2b-855a-0a573e9675ff', 'en', '', '<div>1) address these risks and opportunities (see 6.1.2.2 and 6.1.2.3);</div>'),
    ('9ee69b6c-1f79-4600-a92c-df0cadd61278', 'ad81e937-2af2-4c2b-855a-0a573e9675ff', 'es', '', '<div>1) abordar estos riesgos y oportunidades (véanse 6.1.2.2 y 6.1.2.3);</div>'),
    ('624371b0-214a-46e4-a0bb-4d187b8fada4', 'ae81eaca-2500-479a-bbc5-5ca03f967792', 'en', '', '<div>2) address legal requirements and other requirements (see 6.1.3);</div>'),
    ('5f436cf7-13f1-4833-b101-1e23808fb583', 'ae81eaca-2500-479a-bbc5-5ca03f967792', 'es', '', '<div>2) abordar los requisitos legales y otros requisitos (véase 6.1.3);</div>'),
    ('860b4041-7c78-4a5d-928c-67fd1502e845', 'af81ec5d-6140-4105-a05d-c6dd40967925', 'en', '', '<div>3) prepare for and respond to emergency situations (see 8.2);</div>'),
    ('710b1f32-08b5-47ce-ad2b-29622803062e', 'af81ec5d-6140-4105-a05d-c6dd40967925', 'es', '', '<div>3) prepararse y responder ante situaciones de emergencia (véase 8.2);</div>'),
    ('2167f5c6-d2c2-4482-bdea-c8ee501b12b2', 'a081d4c0-7291-49dc-8fb3-ea6641967ab8', 'en', '', '<div>b) how to:</div><ul><li>{clause_6.1.4.b.1}</li><li>{clause_6.1.4.b.2}</li></ul>'),
    ('3e68236d-68f3-46d9-8023-e721651b33c1', 'a081d4c0-7291-49dc-8fb3-ea6641967ab8', 'es', '', '<div>b) la manera de: </div><ul><li>{clause_6.1.4.b.1}</li><li>{clause_6.1.4.b.2}</li></ul>'),
    ('cc3c0bef-f4c6-43db-b5cf-25dba280d77b', 'a181d653-016e-4787-9e63-688342967c4b', 'en', '', '<div>1) integrate and implement the actions into its OH&amp;S management system processes or other business processes;</div>'),
    ('bf3bf778-6da2-47dc-8637-4ba08d80b66c', 'a181d653-016e-4787-9e63-688342967c4b', 'es', '', '<div>1) integrar e implementar las acciones en sus procesos del sistema de gestión de la SST o en otros procesos de negocio;</div>'),
    ('57ed0e2d-7baa-4099-9b12-8ce11c360839', '2e84f2e1-d690-41ed-9ec8-dcc13f98b629', 'en', '', '<div>2) evaluate the effectiveness of these actions.</div>'),
    ('3aece086-fc4d-4d42-be80-e8ae373632ba', '2e84f2e1-d690-41ed-9ec8-dcc13f98b629', 'es', '', '<div>2) evaluar la eficacia de estas acciones.</div>'),
    ('a0f40a2c-041c-4770-9ab7-e34ca29bf088', '2d84f14e-7c2b-4b62-8f17-ce643e98b496', 'en', 'OH&S objectives and planning to achieve them', '<div>{clause_6.2.1}</div><div>{clause_6.2.2}</div>'),
    ('b5f42b3b-a3bd-4337-b2e9-cbef8f9bd29f', '2d84f14e-7c2b-4b62-8f17-ce643e98b496', 'es', 'Objetivos de la SST y planificación para lograrlos', '<div>{clause_6.2.1}</div><div>{clause_6.2.2}</div>'),
    ('33958997-22a3-40c3-9696-fc43d43d75f3', '2c84efbb-01ef-4213-9952-100b3d98b303', 'en', 'OH&S objectives', '<div>The organization shall establish OH&amp;S objectives at relevant functions and levels in order to maintain and continually improve the OH&amp;S management system and OH&amp;S performance (see 10.3).</div><div>The OH&amp;S objectives shall:</div><div>{clause_6.2.1.a}</div><div>{clause_6.2.1.b}</div><div>{clause_6.2.1.c}</div><div>{clause_6.2.1.d}</div><div>{clause_6.2.1.e}</div><div>{clause_6.2.1.f}</div>'),
    ('36958e50-7383-4494-8a93-1538ef3da074', '2c84efbb-01ef-4213-9952-100b3d98b303', 'es', 'Objetivos de la SST', '<div>La organización debe establecer objetivos de la SST para las funciones y niveles pertinentes para mantener y mejorar continuamente el sistema de gestión de la SST y el desempeño de la SST (véase 10.3).</div><div>Los objetivos de la SST deben: </div><div>{clause_6.2.1.a}</div><div>{clause_6.2.1.b}</div><div>{clause_6.2.1.c}</div><div>{clause_6.2.1.d}</div><div>{clause_6.2.1.e}</div><div>{clause_6.2.1.f}</div>'),
    ('538a076e-1c53-4e6a-af13-5b16a3b47bca', '2b84ee28-a90b-4fd8-9c01-d18e3c98b170', 'en', '', '<div>a) be consistent with the OH&amp;S policy;</div>'),
    ('4089e985-385e-4ff1-ad8a-fb59a8b483a9', '2b84ee28-a90b-4fd8-9c01-d18e3c98b170', 'es', '', '<div>a) ser coherentes con la política de la SST;</div>'),
    ('524765f1-9482-458d-bbb9-458dade43a35', '3284f92d-b12f-4e71-aae5-1f8d4398bc75', 'en', '', '<div>b) be measurable (if practicable) or capable of performance evaluation;</div>'),
    ('5d477742-c67b-449e-8374-6f92a0e425be', '3284f92d-b12f-4e71-aae5-1f8d4398bc75', 'es', '', '<div>b) ser medibles (si es posible) o evaluables en términos de desempeño;</div>'),
    ('bbc555a0-68f8-4c14-8968-0c6887caa514', '3184f79a-d643-4a76-b3b8-21d04298bae2', 'en', '', '<div>c) take into account:</div><ul><li>{clause_6.2.1.c.1}</li><li>{clause_6.2.1.c.2}</li><li>{clause_6.2.1.c.3}</li></ul>'),
    ('d8c58347-1818-4843-a069-cc536cca7a93', '3184f79a-d643-4a76-b3b8-21d04298bae2', 'es', '', '<div>c) tener en cuenta: </div><ul><li>{clause_6.2.1.c.1}</li><li>{clause_6.2.1.c.2}</li><li>{clause_6.2.1.c.3}</li></ul>'),
    ('7e4649eb-ed52-4197-be02-debf87124c9f', '3084f607-852d-4fe7-9a10-61474198b94f', 'en', '', '<div>1) applicable requirements;</div>'),
    ('89465b3c-4db1-45d0-9b5b-da3c9a126a88', '3084f607-852d-4fe7-9a10-61474198b94f', 'es', '', '<div>1) los requisitos aplicables; </div>'),
    ('6dbbef22-1c67-46ee-a4ea-d172a982c676', '2f84f474-f650-423c-a6f8-25da4098b7bc', 'en', '', '<div>2) the results of the assessment of risks and opportunities (see 6.1.2.2 and 6.1.2.3);</div>'),
    ('62bbddd1-a64a-41fd-859f-46eda682c1bd', '2f84f474-f650-423c-a6f8-25da4098b7bc', 'es', '', '<div>2) los resultados de la evaluación de los riesgos y oportunidades (véanse 6.1.2.2 y 6.1.2.3); </div>'),
    ('bf4a1f35-0dfd-4261-8165-09a940e180f1', '2684e649-146b-46e5-b3f3-91694798c2c1', 'en', '', '<div>3) the results of consultation with workers (see 5.4) and, where they exist, workers’ representatives;</div>'),
    ('b24a0abe-6583-443a-bb41-19c64be19242', '2684e649-146b-46e5-b3f3-91694798c2c1', 'es', '', '<div>3) los resultados de la consulta con los trabajadores (véase 5.4) y, cuando existan, con los representantes de los trabajadores;</div>'),
    ('99308a14-b232-4618-886b-05d4aa5f70a0', '2584e4b6-c159-417a-b136-666c4698c12e', 'en', '', '<div>d) be monitored;</div>'),
    ('7e305f93-a09b-4d4f-a5e3-b867c75f9e47', '2584e4b6-c159-417a-b136-666c4698c12e', 'es', '', '<div>d) ser objeto de seguimiento; </div>'),
    ('cc790344-31ea-4584-af70-9b242e4d0360', '34873aea-0a33-4b06-b329-571c459afe32', 'en', '', '<div>e) be communicated;</div>'),
    ('d1790b23-2490-43d3-bd04-84574b4d3107', '34873aea-0a33-4b06-b329-571c459afe32', 'es', '', '<div>e) comunicarse; </div>'),
    ('6371d4e5-fba8-407d-8b9b-4639c7497cb1', '35873c7d-b82e-4a81-a3d5-f099469affc5', 'en', '', '<div>f) be updated as appropriate.</div>'),
    ('7671f2ce-71c6-456e-8c22-ccf6d2498e02', '35873c7d-b82e-4a81-a3d5-f099469affc5', 'es', '', '<div>f) actualizarse, según sea apropiado.</div>'),
    ('5e70fd66-f6bb-48de-b27c-150ee2bf98e2', '328737c4-12d1-460c-b4e6-ce46439afb0c', 'en', 'Planning to achieve OH&S objectives', '<div>When planning how to achieve its OH&amp;S objectives, the organization shall determine:</div><div>{clause_6.2.2.a}</div><div>{clause_6.2.2.b}</div><div>{clause_6.2.2.c}</div><div>{clause_6.2.2.d}</div><div>{clause_6.2.2.e}</div><div>{clause_6.2.2.f}</div><div>The organization shall maintain and retain documented information on the OH&amp;S objectives and plans to achieve them.</div>'),
    ('7b712b0d-c247-4dcd-b753-2741d7bf8791', '328737c4-12d1-460c-b4e6-ce46439afb0c', 'es', 'Planificación para lograr los objetivos de la SST', '<div>Al planificar cómo lograr sus objetivos de la SST, la organización debe determinar: </div><div>{clause_6.2.2.a}</div><div>{clause_6.2.2.b}</div><div>{clause_6.2.2.c}</div><div>{clause_6.2.2.d}</div><div>{clause_6.2.2.e}</div><div>{clause_6.2.2.f}</div><div>La organización debe mantener y conservar información documentada sobre los objetivos de la SST y los planes para lograrlos.</div>'),
    ('7f19220f-6a2d-4107-b2ec-61fbf34860ab', '33873957-a24b-4477-9b61-06e3449afc9f', 'en', '', '<div>a) what will be done;</div>'),
    ('72190d98-70e7-4aa0-a80c-4dc0fe4871fc', '33873957-a24b-4477-9b61-06e3449afc9f', 'es', '', '<div>a) qué se va a hacer;</div>'),
    ('5a049078-ffcb-44a0-a7da-1da0137d4aec', '3087349e-96cf-46f2-adcc-f8a8419af7e6', 'en', '', '<div>b) what resources will be required;</div>'),
    ('6704a4ef-f911-4b07-9771-f7db287d6bfb', '3087349e-96cf-46f2-adcc-f8a8419af7e6', 'es', '', '<div>b) qué recursos se requerirán;</div>'),
    ('9dcafe69-8734-4489-8d76-af25ccf0b7ed', '31873631-f096-4cbd-9d51-cb85429af979', 'en', '', '<div>c) who will be responsible;</div>'),
    ('98caf68a-975e-4792-83cc-e73aaff08a46', '31873631-f096-4cbd-9d51-cb85429af979', 'es', '', '<div>c) quién será responsable;</div>'),
    ('9940e83a-0ca8-43da-837d-63cac88db12e', '2e873178-b00b-4ee8-8b26-04b23f9af4c0', 'en', '', '<div>d) when it will be completed;</div>'),
    ('7e40bdb9-d0e8-4d01-81b9-8e95b58d9345', '2e873178-b00b-4ee8-8b26-04b23f9af4c0', 'es', '', '<div>d) cuándo se finalizará;</div>'),
    ('c92c11a3-5654-44f3-9a1b-5e57a61d3757', '2f87330b-385b-4ea3-b6ad-be3f409af653', 'en', '', '<div>e) how the results will be evaluated, including indicators for monitoring;</div>'),
    ('c42c09c4-4a62-41a4-8c87-7524a91d3c10', '2f87330b-385b-4ea3-b6ad-be3f409af653', 'es', '', '<div>e) cómo se evaluarán los resultados, incluyendo los indicadores de seguimiento;</div>'),
    ('851c249c-ef56-4ccc-92f7-921c2903ec48', '2c872e52-3b1e-40de-87fc-f9944d9b0aca', 'en', '', '<div>f) how the actions to achieve OH&amp;S objectives will be integrated into the organization’s business processes.</div>'),
    ('7a1c134b-efb3-41ab-8ef1-ab9f1603ce5f', '2c872e52-3b1e-40de-87fc-f9944d9b0aca', 'es', '', '<div>f) cómo se integrarán las acciones para lograr los objetivos de la SST en los procesos de negocio de la organización.</div>'),
    ('fe8f2cdd-0ad8-42c5-b7b8-4c31a0252df9', '2d872fe5-41c3-4e19-8836-5f714e9b0c5d', 'en', 'Support', '<div>{clause_7.1}</div><div>{clause_7.2}</div><div>{clause_7.3}</div><div>{clause_7.4}</div><div>{clause_7.5}</div>'),
    ('018f3196-ce0b-4706-90dc-d0debb25587a', '2d872fe5-41c3-4e19-8836-5f714e9b0c5d', 'es', 'Apoyo', '<div>{clause_7.1}</div><div>{clause_7.2}</div><div>{clause_7.3}</div><div>{clause_7.4}</div><div>{clause_7.5}</div>'),
    ('a7aa320b-758e-4b1b-bde4-e7df3f001c47', '1a895093-2943-48c7-8412-4c27cb9e0fbb', 'en', 'Resources', '<div>The organization shall determine and provide the resources needed for the establishment, implementation, maintenance and continual improvement of the OH&amp;S management system.</div>'),
    ('b2aa435c-d2a3-411c-84db-bc5c21ffeea0', '1a895093-2943-48c7-8412-4c27cb9e0fbb', 'es', 'Recursos', '<div>La organización debe determinar y proporcionar los recursos necesarios para el establecimiento, implementación, mantenimiento y mejora continua del sistema de gestión de la SST. </div>'),
    ('0800a6c2-a708-4bc2-95f1-461294c9d6de', '19894f00-811a-461c-a5f3-9abaca9e0e28', 'en', 'Competence', '<div>The organization shall:</div><div>{clause_7.2.a}</div><div>{clause_7.2.b}</div><div>{clause_7.2.c}</div><div>{clause_7.2.d}</div><div>NOTE: Applicable actions can include, for example, the provision of training to, the mentoring of, or the reassignment of currently employed persons, or the hiring or contracting of competent persons.</div>'),
    ('fd009571-2665-4f19-8e36-1c0da1c9eb55', '19894f00-811a-461c-a5f3-9abaca9e0e28', 'es', 'Competencia', '<div>La organización debe: </div><div>{clause_7.2.a}</div><div>{clause_7.2.b}</div><div>{clause_7.2.c}</div><div>{clause_7.2.d}</div><div>NOTA: Las acciones aplicables pueden incluir, por ejemplo, la provisión de formación, la tutoría o la reasignación de las personas empleadas actualmente; o la contratación o subcontratación de personas competentes. </div>'),
    ('ef04f391-5f01-4171-9b12-e5ad99caae5d', '1c8953b9-25d7-46d1-b8a8-bd6dcd9e12e1', 'en', '', '<div>a) determine the necessary competence of workers that affects or can affect its OH&amp;S performance;</div>'),
    ('fa0504e2-42f6-4fea-9478-15329ccab316', '1c8953b9-25d7-46d1-b8a8-bd6dcd9e12e1', 'es', '', '<div>a) determinar la competencia necesaria de los trabajadores que afecta o puede afectar a su desempeño de la SST; </div>'),
    ('56087a40-79fa-49a8-94f3-f7082057a61c', '1b895226-77dd-4756-bba5-61b0cc9e114e', 'en', '', '<div>b) ensure that workers are competent (including the ability to identify hazards) on the basis of appropriate education, training or experience;</div>'),
    ('7308a7e7-c208-4b7f-a0c1-1273155794cb', '1b895226-77dd-4756-bba5-61b0cc9e114e', 'es', '', '<div>b) asegurarse de que los trabajadores sean competentes (incluyendo la capacidad de identificar los peligros), basándose en la educación, formación o experiencia apropiadas; </div>'),
    ('5a7f08b7-0462-442f-beef-6a63ff84eb1b', '1e8956df-a605-4af3-9071-a96bcf9e1607', 'en', '', '<div>c) where applicable, take actions to acquire and maintain the necessary competence, and evaluate the effectiveness of the actions taken;</div>'),
    ('5d7f0d70-1926-4978-b289-2a58ea84ca0c', '1e8956df-a605-4af3-9071-a96bcf9e1607', 'es', '', '<div>c) cuando sea aplicable, tomar acciones para adquirir y mantener la competencia necesaria y evaluar la eficacia de las acciones tomadas; </div>'),
    ('7a75198e-974e-41c6-82f8-5c36ad1f2652', '1d89554c-1db5-4b38-ab20-27eece9e1474', 'en', '', '<div>d) retain appropriate documented information as evidence of competence.</div>'),
    ('6774fba5-d694-4385-a320-1579c21f4761', '1d89554c-1db5-4b38-ab20-27eece9e1474', 'es', '', '<div>d) conservar la información documentada apropiada, como evidencia de la competencia. </div>'),
    ('f4aa9bcd-1fce-4565-9947-9901d423d7e1', '20895a05-48be-414d-ae49-01a1d19e192d', 'en', 'Awareness', '<div>Workers shall be made aware of:</div><div>{clause_7.3.a}</div><div>{clause_7.3.b}</div><div>{clause_7.3.c}</div><div>{clause_7.3.d}</div><div>{clause_7.3.e}</div><div>{clause_7.3.f}</div>'),
    ('d7aa6e26-b394-4c26-b3f6-9dcebf23b6d2', '20895a05-48be-414d-ae49-01a1d19e192d', 'es', 'Toma de conciencia', '<div>Los trabajadores deben ser sensibilizados sobre y tomar conciencia de:</div><div>{clause_7.3.a}</div><div>{clause_7.3.b}</div><div>{clause_7.3.c}</div><div>{clause_7.3.d}</div><div>{clause_7.3.e}</div><div>{clause_7.3.f}</div>'),
    ('3b372ecc-8ac9-43ec-8346-9eec3a898dd0', '1f895872-047a-4642-99d8-aac4d09e179a', 'en', '', '<div>a) the OH&amp;S policy and OH&amp;S objectives;</div>'),
    ('50374fdb-6f5f-4acb-8b90-5e8f37898917', '1f895872-047a-4642-99d8-aac4d09e179a', 'es', '', '<div>a) la política de la SST y los objetivos de la SST;</div>'),
    ('7fe67f93-6727-4593-8e7f-83e71a54a38f', '22895d2b-3a2c-493f-9501-a86fc39e0323', 'en', '', '<div>b) their contribution to the effectiveness of the OH&amp;S management system, including the benefits of improved OH&amp;S performance;</div>'),
    ('9ae6aa14-76fc-4044-b106-d1540d548f18', '22895d2b-3a2c-493f-9501-a86fc39e0323', 'es', '', '<div>b) su contribución a la eficacia del sistema de gestión de la SST, incluidos los beneficios de una mejora del desempeño de la SST; </div>'),
    ('4f5d856a-219e-467a-9aff-4d9af9ac7ee6', '21895b98-e16f-4674-9df4-9b62c29e0190', 'en', '', '<div>c) the implications and potential consequences of not conforming to the OH&amp;S management system requirements;</div>'),
    ('545d8d49-e5df-42a1-87bf-770516acac8d', '21895b98-e16f-4674-9df4-9b62c29e0190', 'es', '', '<div>c) las implicaciones y las consecuencias potenciales de no cumplir los requisitos del sistema de gestión de la SST; </div>'),
    ('f602ee92-8dc3-4b0e-8386-c6c2c7b37dd6', '30782a14-b634-40c0-b022-ca0ac1b3c64c', 'en', '', '<div>d) incidents and the outcomes of investigations that are relevant to them;</div>'),
    ('0b030fa1-1ad0-4f9d-b4c7-3d5dc4b3791d', '30782a14-b634-40c0-b022-ca0ac1b3c64c', 'es', '', '<div>d) los incidentes, y los resultados de investigaciones, que sean pertinentes para ellos; </div>'),
    ('45ecb75b-4d4a-4a37-83f1-e68f34655a7f', '31782ba7-a7c4-487b-bf40-7df7c2b3c7df', 'en', '', '<div>e) hazards, OH&amp;S risks and actions determined that are relevant to them;</div>'),
    ('30ec964c-ada9-4e70-bba8-26ec47657868', '31782ba7-a7c4-487b-bf40-7df7c2b3c7df', 'es', '', '<div>e) los peligros, los riesgos para la SST y las acciones determinadas, que sean pertinentes para ellos; </div>'),
    ('836bc310-c8f1-47b4-9013-b878351db2f4', '32782d3a-a3ac-492a-947a-f8c0c3b3c972', 'en', '', '<div>f) the ability to remove themselves from work situations that they consider present an imminent and serious danger to their life or health, as well as the arrangements for protecting them from undue consequences for doing so.</div>'),
    ('806bbe57-61f2-4b63-85e9-41831a1d8873', '32782d3a-a3ac-492a-947a-f8c0c3b3c972', 'es', '', '<div>f) la capacidad de alejarse de situaciones de trabajo que consideren que presentan un peligro inminente y serio para su vida o su salud, así como las disposiciones para protegerles de las consecuencias indebidas de hacerlo. </div>'),
    ('1a8d3721-7520-44ad-b2e4-30ddce90ed95', '33782ecd-f75e-4255-ac2f-147dc4b3cb05', 'en', 'Communication', '<div>{clause_7.4.1}</div><div>{clause_7.4.2}</div><div>{clause_7.4.3}</div>'),
    ('058d1612-8dcc-4ebe-81a3-ba42c190d91e', '33782ecd-f75e-4255-ac2f-147dc4b3cb05', 'es', 'Comunicación', '<div>{clause_7.4.1}</div><div>{clause_7.4.2}</div><div>{clause_7.4.3}</div>'),
    ('db31a31e-a6f9-448a-af59-3626c1e6c62a', '2c7823c8-3999-4e04-a865-083ebdb3c000', 'en', 'General', '<div>The organization shall establish, implement and maintain the process(es) needed for the internal and external communications relevant to the OH&amp;S management system, including determining:</div><div>{clause_7.4.1.a}</div><div>{clause_7.4.1.b}</div><div>{clause_7.4.1.c}</div><div>{clause_7.4.1.d}</div><div>The organization shall take into account diversity aspects (e.g. gender, language, culture, literacy, disability) when considering its communication needs.</div><div>The organization shall ensure that the views of external interested parties are considered in establishing its communication process(es).</div><div>When establishing its communication process(es), the organization shall:</div><div>— take into account its legal requirements and other requirements;</div><div>— ensure that OH&amp;S information to be communicated is consistent with information generated within the OH&amp;S management system, and is reliable.</div><div>The organization shall respond to relevant communications on its OH&amp;S management system.</div><div>The organization shall retain documented information as evidence of its communications, as appropriate.</div>'),
    ('e831b795-af5f-4691-a977-9a89c6e6ce09', '2c7823c8-3999-4e04-a865-083ebdb3c000', 'es', 'Generalidades', '<div>La organización debe establecer, implementar y mantener los procesos necesarios para las comunicaciones internas y externas pertinentes al sistema de gestión de la SST, incluyendo la determinación de:</div><div>{clause_7.4.1.a}</div><div>{clause_7.4.1.b}</div><div>{clause_7.4.1.c}</div><div>{clause_7.4.1.d}</div><div>La organización debe tener en cuenta aspectos de diversidad (por ejemplo, género, idioma, cultura, alfabetización, discapacidad), al considerar sus necesidades de comunicación.</div><div>La organización debe asegurarse de que se consideran los puntos de vista de partes interesadas externas al establecer sus procesos de comunicación.</div><div>Al establecer sus procesos de comunicación, la organización debe: </div><div>— tener en cuenta sus requisitos legales y otros requisitos;</div><div>— asegurarse de que la información de la SST a comunicar es coherente con la información generada dentro del sistema de gestión de la SST, y es fiable.</div><div>La organización debe responder a las comunicaciones pertinentes sobre su sistema de gestión de la SST.</div><div>La organización debe conservar la información documentada como evidencia de sus comunicaciones, según sea apropiado. </div>'),
    ('87e25187-972b-4163-9ba8-5e93f4ea2953', '2d78255b-a875-494f-9796-167bbeb3c193', 'en', '', '<div>a) on what it will communicate;</div>'),
    ('6ae223e0-fe2b-4db4-b0a2-d8a80fea53d4', '2d78255b-a875-494f-9796-167bbeb3c193', 'es', '', '<div>a) qué comunicar;</div>'),
    ('6939db5c-506f-4090-9308-d7dc4feefe68', '2e7826ee-170f-4a3e-83aa-6cd4bfb3c326', 'en', '', '<div>b) when to communicate;</div>'),
    ('5e39ca0b-ed96-4357-8c12-035f3ceee07f', '2e7826ee-170f-4a3e-83aa-6cd4bfb3c326', 'es', '', '<div>b) cuándo comunicar; </div>'),
    ('e0327a9d-ad98-49b9-a653-d7f1c70ead19', '2f782881-3702-4f79-a0b0-e8b1c0b3c4b9', 'en', '', '<div>c) with whom to communicate:</div><ul><li>{clause_7.4.1.c.1}</li><li>{clause_7.4.1.c.2}</li><li>{clause_7.4.1.c.3}</li></ul>'),
    ('e3327f56-1a96-46e2-b05c-139ee20ed79a', '2f782881-3702-4f79-a0b0-e8b1c0b3c4b9', 'es', '', '<div>c) a quién comunicar: </div><ul><li>{clause_7.4.1.c.1}</li><li>{clause_7.4.1.c.2}</li><li>{clause_7.4.1.c.3}</li></ul>'),
    ('7ae5c8fa-3a6c-4d96-be63-908aef77304e', '28781d7c-8bfd-4848-9123-27f2c9b3d2e4', 'en', '', '<div>1) internally among the various levels and functions of the organization;</div>'),
    ('5fe59e79-1d92-4bb5-a41d-8f55dc771265', '28781d7c-8bfd-4848-9123-27f2c9b3d2e4', 'es', '', '<div>1) internamente entre los diversos niveles y funciones de la organización; </div>'),
    ('ad4b5b63-b44d-4abf-b926-6417cf811f77', '29781f0f-144e-4b03-9ae3-e77fcab3d477', 'en', '', '<div>2) among contractors and visitors to the workplace;</div>'),
    ('a84b5384-6c41-4be8-8a05-d2e4d2812430', '29781f0f-144e-4b03-9ae3-e77fcab3d477', 'es', '', '<div>2) entre contratistas y visitantes al lugar de trabajo; </div>'),
    ('d0a84151-702f-4e1d-b19e-716d98f07b05', '367a721d-9107-4c49-a4b1-20ad47b6d7d5', 'en', '', '<div>3) among other interested parties;</div>'),
    ('dba852a2-e321-498e-90e9-fbf2abf098ee', '367a721d-9107-4c49-a4b1-20ad47b6d7d5', 'es', '', '<div>3) entre otras partes interesadas; </div>'),
    ('37abc800-a344-46a4-8bea-2ec801f7a964', '357a708a-8735-428e-a318-63f046b6d642', 'en', '', '<div>d) how to communicate.</div>'),
    ('54abf5a7-af36-49f3-9ee4-a23306f7b143', '357a708a-8735-428e-a318-63f046b6d642', 'es', '', '<div>d) cómo comunicar. </div>'),
    ('894f12cb-b405-4127-bb1f-739f413fb5af', '347a6ef7-1899-4e9f-806f-036745b6d4af', 'en', 'Internal communication', '<div>The organization shall:</div><div>{clause_7.4.2.a}</div><div>{clause_7.4.2.b}</div>'),
    ('944f241c-babf-4ac0-bf25-5a1c343fa138', '347a6ef7-1899-4e9f-806f-036745b6d4af', 'es', 'Comunicación interna', '<div>La organización debe: </div><div>{clause_7.4.2.a}</div><div>{clause_7.4.2.b}</div>'),
    ('ec1e5d82-fdfb-447e-9ef9-d1d293efa386', '337a6d64-a9bd-4354-9e9f-fffa44b6d31c', 'en', '', '<div>a) internally communicate information relevant to the OH&amp;S management system among the various levels and functions of the organization, including changes to the OH&amp;S management system, as appropriate;</div>'),
    ('e11e4c31-cc02-456d-80e8-d7cdb0efd12d', '337a6d64-a9bd-4354-9e9f-fffa44b6d31c', 'es', '', '<div>a) comunicar internamente la información pertinente para el sistema de gestión de la SST entre los diversos niveles y funciones de la organización, incluyendo los cambios en el sistema de gestión de la SST, según sea apropiado; </div>'),
    ('d64f7c8d-1455-43a9-999f-efc1d34b3789', '327a6bd1-6782-47a5-8959-75e143b6d189', 'en', '', '<div>b) ensure its communication process(es) enables workers to contribute to continual improvement.</div>'),
    ('b94f4ee6-2204-4db2-94c8-dd8ece4b2faa', '327a6bd1-6782-47a5-8959-75e143b6d189', 'es', '', '<div>b) asegurarse de que sus procesos de comunicación permitan a los trabajadores contribuir a la mejora continua. </div>'),
    ('1f56788c-9f9b-4dc0-9db8-02ac1c299118', '317a6a3e-2dbb-443a-a2ac-e20442b6cff6', 'en', 'External communication', '<div>The organization shall externally communicate information relevant to the OH&amp;S management system, as established by the organization’s communication process(es) and taking into account its legal requirements and other requirements.</div>'),
    ('3456999b-98e1-4427-b261-654f2929a58f', '317a6a3e-2dbb-443a-a2ac-e20442b6cff6', 'es', 'Comunicación externa', '<div>La organización debe comunicar externamente la información pertinente para el sistema de gestión de la SST, según se establece en los procesos de comunicación de la organización y teniendo en cuenta sus requisitos legales y otros requisitos. </div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('3e9cbf77-8420-4c13-9cd4-d6238dcb7b43', '307a68ab-17e8-4dcb-a338-40ab41b6ce63', 'en', 'Documented information', '<div>{clause_7.5.1}</div><div>{clause_7.5.2}</div><div>{clause_7.5.3}</div>'),
    ('419cc430-93f5-46c4-8c8f-051888cb7364', '307a68ab-17e8-4dcb-a338-40ab41b6ce63', 'es', 'Información documentada', '<div>{clause_7.5.1}</div><div>{clause_7.5.2}</div><div>{clause_7.5.3}</div>'),
    ('5e92d04e-3e96-4cfa-b0cb-a2f6cec1215a', '2f7a6718-2659-4610-9cb5-f72e40b6ccd0', 'en', 'General', '<div>The organization’s OH&amp;S management system shall include:</div><div>{clause_7.5.1.a}</div><div>{clause_7.5.1.b}</div><div>NOTE The extent of documented information for an OH&amp;S management system can differ from one organization to another due to:</div><div>—&nbsp;&nbsp;&nbsp;the size of organization and its type of activities, processes, products and services;</div><div>—&nbsp;&nbsp;&nbsp;the need to demonstrate fulfilment of legal requirements and other requirements;</div><div>—&nbsp;&nbsp;&nbsp;the complexity of processes and their interactions;</div><div>—&nbsp;&nbsp;&nbsp;the competence of workers.</div>'),
    ('4b92b265-02d7-4921-b044-1c39b3c0f6d9', '2f7a6718-2659-4610-9cb5-f72e40b6ccd0', 'es', 'Generalidades', '<div>El sistema de gestión de la SST de la organización debe incluir:</div><div>{clause_7.5.1.a}</div><div>{clause_7.5.1.b}</div><div>NOTA La extensión de la información documentada para un sistema de gestión de la SST puede variar de una organización a otra, debido a: </div><div>— el tamaño de la organización y su tipo de actividades, procesos, productos y servicios;</div><div>— la necesidad de demostrar el cumplimiento de los requisitos legales y otros requisitos;</div><div>— la complejidad de los procesos y sus interacciones;</div><div>— la competencia de los trabajadores. </div>'),
    ('362a4d19-3cc6-4be5-9fd4-5bf5c0b42d7d', '2e7a6585-0445-4c31-a9c5-f4f54fb6e46d', 'en', '', '<div>a) documented information required by this document;</div>'),
    ('512a779a-d08c-42a6-9716-aeaac3b43236', '2e7a6585-0445-4c31-a9c5-f4f54fb6e46d', 'es', '', '<div>a) la información documentada requerida por este documento; </div>'),
    ('bf0a9e68-a7c2-4a6c-b054-e870ba9acabc', '2d7a63f2-402b-4436-a264-10584eb6e2da', 'en', '', '<div>b) documented information determined by the organization as being necessary for the effectiveness of the OH&amp;S management system.</div>'),
    ('ac0a807f-8c58-414b-9e19-fc4baf9ab96b', '2d7a63f2-402b-4436-a264-10584eb6e2da', 'es', '', '<div>b) la información documentada que la organización determina como necesaria para la eficacia del sistema de gestión de la SST.</div>'),
    ('6e516111-7d88-4fdd-94cd-8f2d36999ac5', 'fd3fe4dd-c021-4e95-b1ea-e2ed0d662585', 'en', 'Creating and updating', '<div>When creating and updating documented information, the organization shall ensure appropriate:</div><div>{clause_7.5.2.a}</div><div>{clause_7.5.2.b}</div><div>{clause_7.5.2.c}</div>'),
    ('79517262-09c6-4d4e-8e32-beb24999b8ae', 'fd3fe4dd-c021-4e95-b1ea-e2ed0d662585', 'es', 'Creación y actualización', '<div>Al crear y actualizar la información documentada, la organización debe asegurarse de que lo siguiente sea apropiado:</div><div>{clause_7.5.2.a}</div><div>{clause_7.5.2.b}</div><div>{clause_7.5.2.c}</div>'),
    ('d554e7c0-225b-4c64-8eae-a0889d266024', 'fc3fe34a-6c6f-456a-b4e7-87300c6623f2', 'en', '', '<div>a) identification and description (e.g. a title, date, author or reference number);</div>'),
    ('f2551567-1502-4db3-9a7b-bbf3a2266803', 'fc3fe34a-6c6f-456a-b4e7-87300c6623f2', 'es', '', '<div>a) la identificación y descripción (por ejemplo, título, fecha, autor o número de referencia);</div>'),
    ('26f69f8b-1757-4be7-b79f-915fdc6cd96f', 'fb3fe1b7-7087-44bb-bd54-71a70b66225f', 'en', '', '<div>b) format (e.g. language, software version, graphics) and media (e.g. paper, electronic);</div>'),
    ('31f6b0dc-2089-4b80-be96-65dccf6cc4f8', 'fb3fe1b7-7087-44bb-bd54-71a70b66225f', 'es', '', '<div>b) el formato (por ejemplo, idioma, versión del software, gráficos) y los medios de soporte (por ejemplo, papel, electrónico); </div>'),
    ('874d1442-640b-403e-8fab-ef923198c346', 'fa3fe024-65aa-4800-9f35-c03a0a6620cc', 'en', '', '<div>c) review and approval for suitability and adequacy.</div>'),
    ('7c4d02f1-4b5f-462d-87f0-c58d4e98f0ed', 'fa3fe024-65aa-4800-9f35-c03a0a6620cc', 'es', '', '<div>c) la revisión y aprobación con respecto a la conveniencia y adecuación. </div>'),
    ('73f7094d-7a65-4f69-9302-428170f2c449', 'f93fde91-e678-46b9-a78b-272109661f39', 'en', 'Control of documented information', '<div>Documented information required by the OH&amp;S management system and by this document shall be controlled to ensure:</div><div>{clause_7.5.3.a}</div><div>{clause_7.5.3.b}</div><div>For the control of documented information, the organization shall address the following activities, as applicable:</div><div>— distribution, access, retrieval and use;</div><div>— storage and preservation, including preservation of legibility;</div><div>— control of changes (e.g. version control);</div><div>— retention and disposition.</div><div>Documented information of external origin determined by the organization to be necessary for the planning and operation of the OH&amp;S management system shall be identified, as appropriate, and controlled.</div><div>NOTE 1: Access can imply a decision regarding the permission to view the documented information only, or the permission and authority to view and change the documented information.</div><div>NOTE 2: Access to relevant documented information includes access by workers, and, where they exist, workers’ representatives.</div>'),
    ('56f6dba6-a3db-4772-adb1-474e6bf2bc6a', 'f93fde91-e678-46b9-a78b-272109661f39', 'es', 'Control de la Información documentada', '<div>La información documentada requerida por el sistema de gestión de la SST y por este documento se debe controlar para asegurarse de que: </div><div>{clause_7.5.3.a}</div><div>{clause_7.5.3.b}</div><div>Para el control de la información documentada, la organización debe abordar las siguientes actividades, según sea aplicable:</div><div>— distribución, acceso, recuperación y uso;</div><div>— almacenamiento y preservación, incluida la preservación de la legibilidad;</div><div>— control de cambios (por ejemplo control de versión);</div><div>— conservación y disposición. </div><div>La información documentada de origen externo que la organización determina como necesaria para la planificación y operación del sistema de gestión de la SST se debe identificar, según sea apropiado, y controlar.</div><div>NOTA 1: El acceso puede implicar una decisión en relación al permiso solamente para consultar la información documentada, o al permiso y a la autoridad para consultar y modificar la información documentada.</div><div>NOTA 2: El acceso a la información documentada pertinente incluye el acceso por parte de los trabajadores, y cuando existan, de los representantes de los trabajadores. </div>'),
    ('ba839c4c-af6d-4580-bd01-486cb75847d8', 'f83fdcfe-dfd4-497e-931a-d04408661da6', 'en', '', '<div>a) it is available and suitable for use, where and when it is needed;</div>'),
    ('cf83bd5b-a63b-45e7-854b-080fc4585c4f', 'f83fdcfe-dfd4-497e-931a-d04408661da6', 'es', '', '<div>a) esté disponible y sea idónea para su uso, dónde y cuándo se necesite;</div>'),
    ('d9cb7637-05f9-48d3-b8aa-13e328fa3203', 'f73fdb6b-7138-458f-89b3-ceeb07661c13', 'en', '', '<div>b) it is adequately protected (e.g. from loss of confidentiality, improper use or loss of integrity).</div>'),
    ('dccb7af0-1353-4a84-ac43-d3d823fa2a24', 'f73fdb6b-7138-458f-89b3-ceeb07661c13', 'es', '', '<div>b) esté protegida adecuadamente (por ejemplo, contra pérdida de la confidencialidad, uso inadecuado, o pérdida de integridad). </div>'),
    ('f9c1870e-1666-4fba-bcb3-05b66c68ae1a', 'f63fd9d8-e90f-4544-a462-4d6e06661a80', 'en', 'Operation', '<div>{clause_8.1}</div><div>{clause_8.2}</div>'),
    ('e6c16925-bee0-4de1-9cda-bef951688399', 'f63fd9d8-e90f-4544-a462-4d6e06661a80', 'es', 'Operación', '<div>{clause_8.1}</div><div>{clause_8.2}</div>'),
    ('d3d36cd9-fb4a-4ca5-bde9-aab55be2e43d', 'f53fd845-7f2c-4cdd-98ae-7b351566321d', 'en', 'Operational planning and control', '<div>{clause_8.1.1}</div><div>{clause_8.1.2}</div><div>{clause_8.1.3}</div><div>{clause_8.1.4}</div>'),
    ('eed3975a-a85d-4866-9011-ca6a5ee2e8f6', 'f53fd845-7f2c-4cdd-98ae-7b351566321d', 'es', 'Planificación y control operacional', '<div>{clause_8.1.1}</div><div>{clause_8.1.2}</div><div>{clause_8.1.3}</div><div>{clause_8.1.4}</div>'),
    ('5a37c228-ce66-4e2c-81f6-33305842577c', 'f43fd6b2-0c19-4512-bd3f-56981466308a', 'en', 'General', '<div>The organization shall plan, implement, control and maintain the processes needed to meet requirements of the OH&amp;S management system, and to implement the actions determined in Clause 6, by:</div><div>{clause_8.1.1.a}</div><div>{clause_8.1.1.b}</div><div>{clause_8.1.1.c}</div><div>{clause_8.1.1.d}</div><div>At multi-employer workplaces, the organization shall coordinate the relevant parts of the OH&amp;S management system with the other organizations.</div>'),
    ('4737a43f-b2fc-450b-af8d-230b4d42462b', 'f43fd6b2-0c19-4512-bd3f-56981466308a', 'es', 'Generalidades', '<div>La organización debe planificar, implementar, controlar y mantener los procesos necesarios para cumplir los requisitos del sistema de gestión de la SST y para implementar las acciones determinadas en el capítulo 6 mediante:</div><div>{clause_8.1.1.a}</div><div>{clause_8.1.1.b}</div><div>{clause_8.1.1.c}</div><div>{clause_8.1.1.d}</div><div>En lugares de trabajo con múltiples empleadores, la organización debe coordinar las partes pertinentes del sistema de gestión de la SST con las otras organizaciones. </div>'),
    ('91301252-b467-4ece-a72c-b982655c9d96', 'f73d9cd4-49dc-425c-af1e-ab4a0763dd7c', 'en', '', '<div>a) establishing criteria for the processes;</div>'),
    ('a6303361-282a-415d-85da-171d625c98dd', 'f73d9cd4-49dc-425c-af1e-ab4a0763dd7c', 'es', '', '<div>a) el establecimiento de criterios para los procesos;</div>'),
    ('e395d71b-0bcd-47f7-b507-224fd20ce73f', 'f83d9e67-d8b9-4007-a7a0-e0370863df0f', 'en', '', '<div>b) implementing control of the processes in accordance with the criteria;</div>'),
    ('ce95b60c-8579-4130-a05d-bface50d0528', 'f83d9e67-d8b9-4007-a7a0-e0370863df0f', 'es', '', '<div>b) la implementación del control de los procesos de acuerdo con los criterios; </div>'),
    ('1e9a79d0-a0c1-4a74-8aa7-0e38d2c6d2b4', 'f93d9ffa-2754-4196-aa94-fb000963e0a2', 'en', '', '<div>c) maintaining and retaining documented information to the extent necessary to have confidence that the processes have been carried out as planned;</div>'),
    ('1b9a7517-39c1-4e23-96aa-f543b7c6a833', 'f93d9ffa-2754-4196-aa94-fb000963e0a2', 'es', '', '<div>c) el mantenimiento y la conservación de información documentada en la medida necesaria para confiar en que los procesos se han llevado a cabo según lo planificado; </div>'),
    ('b834c3e1-84f4-4f6d-83f7-0a9d69bfa455', 'fa3da18d-ee9c-4611-bbcd-d9bd0a63e235', 'en', '', '<div>d) adapting work to workers.</div>'),
    ('a334a2d2-b6ed-4e7e-a549-ad025cbf8fde', 'fa3da18d-ee9c-4611-bbcd-d9bd0a63e235', 'es', '', '<div>d) la adaptación del trabajo a los trabajadores. </div>'),
    ('78dac2de-0f85-4c4a-ba6f-85e65f8e52ea', 'f33d9688-e678-4778-9249-0f7e0363d730', 'en', 'Eliminating hazards and reducing OH&S risks', '<div>The organization shall establish, implement and maintain a process(es) for the elimination of hazards and reduction of OH&amp;S risks using the following hierarchy of controls:</div><div>{clause_8.1.2.a}</div><div>{clause_8.1.2.b}</div><div>{clause_8.1.2.c}</div><div>{clause_8.1.2.d}</div><div>{clause_8.1.2.e}</div><div>NOTE: In many countries, legal requirements and other requirements include the requirement that personal protective equipment (PPE) is provided at no cost to workers.</div>'),
    ('85dad755-156f-4251-8b63-1249648e5ac9', 'f33d9688-e678-4778-9249-0f7e0363d730', 'es', 'Eliminar peligros y reducir riesgos para la SST', '<div>La organización debe establecer, implementar y mantener procesos para la eliminación de los peligros y la reducción de los riesgos para la SST utilizando la siguiente jerarquía de los controles: </div><div>{clause_8.1.2.a}</div><div>{clause_8.1.2.b}</div><div>{clause_8.1.2.c}</div><div>{clause_8.1.2.d}</div><div>{clause_8.1.2.e}</div><div>NOTA: En muchos países, los requisitos legales y otros requisitos incluyen el requisito de que los equipos de protección personal (EPP) se proporcionen sin costo para los trabajadores. </div>'),
    ('23110847-6efb-4423-b6ab-6a5390174d13', 'f43d981b-557d-4533-bb2f-98bb0463d8c3', 'en', '', '<div>a) eliminate the hazard;</div>'),
    ('0610daa0-d5fa-4074-9fa9-aa68ab177794', 'f43d981b-557d-4533-bb2f-98bb0463d8c3', 'es', '', '<div>a) eliminar el peligro;</div>'),
    ('0468921c-b3c1-4b50-8cb2-3b9ceb1c2228', 'f53d99ae-b3f0-4d82-813f-1f140563da56', 'en', '', '<div>b) substitute with less hazardous processes, operations, materials or equipment; </div>'),
    ('f96880cb-5362-4717-88ac-551fd81c043f', 'f53d99ae-b3f0-4d82-813f-1f140563da56', 'es', '', '<div>b) sustituir con procesos, operaciones, materiales o equipos menos peligrosos; </div>'),
    ('7ddb9a5d-2cf7-4d79-b172-f5b164b7ccd9', 'f63d9b41-1182-408d-8178-84f10663dbe9', 'en', '', '<div>c) use engineering controls and reorganization of work;</div>'),
    ('80db9f16-80a6-42a2-8a97-7a5e7fb7f75a', 'f63d9b41-1182-408d-8178-84f10663dbe9', 'es', '', '<div>c) utilizar controles de ingeniería y reorganización del trabajo; </div>'),
    ('188d55ba-0fc1-4756-bd38-0d4a8aa5e70e', 'ef3d903c-8e6d-47b4-8468-2a320f63ea14', 'en', '', '<div>d) use administrative controls, including training;</div>'),
    ('fd8d2b39-f563-4175-bb74-381577a5c925', 'ef3d903c-8e6d-47b4-8468-2a320f63ea14', 'es', '', '<div>d) utilizar controles administrativos, incluyendo la formación; </div>'),
    ('48787f23-daf3-417f-93d6-07d76aafd637', 'f03d91cf-0076-4f7f-afef-e3bf1063eba7', 'en', '', '<div>e) use adequate personal protective equipment.</div>'),
    ('43787744-92e6-4fa8-8642-1ea46dafdaf0', 'f03d91cf-0076-4f7f-afef-e3bf1063eba7', 'es', '', '<div>e) utilizar equipos de protección personal adecuados. </div>'),
    ('f18b345f-9865-49bf-a38c-502bd95cdf23', '69450c0f-f987-406f-bb4c-af33996b7f17', 'en', 'Management of change', '<div>The organization shall establish a process(es) for the implementation and control of planned temporary and permanent changes that impact OH&amp;S performance, including:</div><div>{clause_8.1.3.a}</div><div>{clause_8.1.3.b}</div><div>{clause_8.1.3.c}</div><div>{clause_8.1.3.d}</div><div>The organization shall review the consequences of unintended changes, taking action to mitigate any adverse effects, as necessary.</div><div>NOTE: Changes can result in risks and opportunities.</div>'),
    ('048b5248-5059-4ae8-9afc-0250d45cd744', '69450c0f-f987-406f-bb4c-af33996b7f17', 'es', 'Gestión del cambio', '<div>La organización debe establecer procesos para la implementación y el control de los cambios planificados temporales y permanentes que impactan en el desempeño de la SST, incluyendo: </div><div>{clause_8.1.3.a}</div><div>{clause_8.1.3.b}</div><div>{clause_8.1.3.c}</div><div>{clause_8.1.3.d}</div><div>La organización debe revisar las consecuencias de los cambios no previstos, tomando acciones para mitigar cualquier efecto adverso, según sea necesario.</div><div>NOTA: Los cambios pueden resultar en riesgos y oportunidades. </div>'),
    ('11814536-1e84-4c96-a9d8-f7fea971b5ba', '68450a7c-715e-4024-a4d6-cd96986b7d84', 'en', '', '<div>a) new products, services and processes, or changes to existing products, services and processes, including:</div><div>— workplace locations and surroundings;</div><div>— work organization;</div><div>— working conditions;</div><div>— equipment;</div><div>— work force;</div>'),
    ('0e81407d-01ab-4ab5-b80b-09d18e718b39', '68450a7c-715e-4024-a4d6-cd96986b7d84', 'es', '', '<div>a) los nuevos productos, servicios y procesos o los cambios de productos, servicios y procesos existentes, incluyendo:</div><div>— las ubicaciones de los lugares de trabajo y sus alrededores;</div><div>— la organización del trabajo;</div><div>— las condiciones de trabajo;</div><div>— los equipos;</div><div>— la fuerza de trabajo;</div>'),
    ('15e44bf5-2fc6-4b35-9ac4-1a69adfbcbe9', '6b450f35-5b22-4219-88d3-02a99b6b823d', 'en', '', '<div>b) changes to legal requirements and other requirements;</div>'),
    ('08e4377e-4c9f-4d16-8c6c-c586a8fbc40a', '6b450f35-5b22-4219-88d3-02a99b6b823d', 'es', '', '<div>b) cambios en los requisitos legales y otros requisitos;</div>'),
    ('f2451fd4-c43a-473c-97b9-f8946a355df8', '6a450da2-547e-44de-aae9-06ac9a6b80aa', 'en', '', '<div>c) changes in knowledge or information about hazards and OH&amp;S risks;</div>'),
    ('d744f553-6725-413b-9107-58277735726f', '6a450da2-547e-44de-aae9-06ac9a6b80aa', 'es', '', '<div>c) cambios en el conocimiento o la información sobre los peligros y riesgos para la SST; </div>'),
    ('3c3d87b3-64d1-4aeb-a04f-ff078f49ef8f', '654505c3-fb50-489b-8d44-284f956b78cb', 'en', '', '<div>d) developments in knowledge and technology.</div>'),
    ('573db234-803b-440c-8552-14f48249db18', '654505c3-fb50-489b-8d44-284f956b78cb', 'es', '', '<div>d) desarrollos en conocimiento y tecnología.</div>'),
    ('0bb2fa8a-0850-4b92-9880-8b3a6ea1cae6', '64450430-0746-47e0-b02c-4442946b7738', 'en', 'Procurement', '<div>{clause_8.1.4.1}</div><div>{clause_8.1.4.2}</div><div>{clause_8.1.4.3}</div>'),
    ('10b30269-f826-4889-a22a-53258ba1f88d', '64450430-0746-47e0-b02c-4442946b7738', 'es', 'Compras', '<div>{clause_8.1.4.1}</div><div>{clause_8.1.4.2}</div><div>{clause_8.1.4.3}</div>'),
    ('843619f9-3e68-4a81-9a96-c45573a2a265', '674508e9-34ca-49f5-b9b8-1f15976b7bf1', 'en', 'General', '<div>The organization shall establish, implement and maintain a process(es) to control the procurement of products and services in order to ensure their conformity to its OH&amp;S management system.</div>'),
    ('9f36447a-7a29-415a-b4dc-c58a86a2c04e', '674508e9-34ca-49f5-b9b8-1f15976b7bf1', 'es', 'Generalidades', '<div>La organización debe establecer, implementar y mantener procesos para controlar la compra de productos y servicios de forma que se asegure su conformidad con su sistema de gestión de la SST. </div>'),
    ('0d14d848-0ad3-45b8-8a72-f850dca9d0c4', '66450756-f738-494a-b80e-1df8966b7a5e', 'en', 'Contractors', '<div>The organization shall coordinate its procurement process(es) with its contractors, in order to identify hazards and to assess and control the OH&amp;S risks arising from:</div><div>{clause_8.1.4.2.a}</div><div>{clause_8.1.4.2.b}</div><div>{clause_8.1.4.2.c}</div><div>The organization shall ensure that the requirements of its OH&amp;S management system are met by contractors and their workers. The organization’s procurement process(es) shall define and apply occupational health and safety criteria for the selection of contractors.</div><div>NOTE It can be helpful to include the occupational health and safety criteria for the selection of contractors in the contractual documents.</div>'),
    ('fa14ba5f-0f59-426f-9303-462be1a9d8a3', '66450756-f738-494a-b80e-1df8966b7a5e', 'es', 'Contratistas', '<div>La organización debe coordinar sus procesos de compras con sus contratistas, para identificar los peligros y para evaluar y controlar los riesgos para la SST, que surjan de: </div><div>{clause_8.1.4.2.a}</div><div>{clause_8.1.4.2.b}</div><div>{clause_8.1.4.2.c}</div><div>La organización debe asegurarse de que los requisitos de su sistema de gestión de la SST se cumplen por los contratistas y sus trabajadores. Los procesos de compra de la organización deben definir y aplicar los criterios de la seguridad y salud en el trabajo para la selección de contratistas. </div><div>NOTA: Puede ser útil incluir los criterios de la seguridad y salud en el trabajo para la selección de los contratistas en los documentos contractuales. </div>'),
    ('8a2e2357-3163-4937-83ea-1e03747a371b', '714518a7-bbaa-4877-9b6b-1f4b916b727f', 'en', '', '<div>a) the contractors’ activities and operations that impact the organization;</div>'),
    ('8d2e2810-91c1-4d70-8e14-94f85f7a160c', '714518a7-bbaa-4877-9b6b-1f4b916b727f', 'es', '', '<div>a) las actividades y operaciones de los contratistas que impactan en la organización; </div>'),
    ('ac9e9d2e-71db-4a0e-8c34-f2d622147252', '70451714-2c30-4a0c-9df2-7bce906b70ec', 'en', '', '<div>b) the organization’s activities and operations that impact the contractors’ workers;</div>'),
    ('999e7f45-fee9-4e9d-9b63-031937149361', '70451714-2c30-4a0c-9df2-7bce906b70ec', 'es', '', '<div>b) las actividades y operaciones de la organización que impactan en los trabajadores de los contratistas; </div>'),
    ('003a7d18-1b1c-4408-9750-a740dc317d3c', '6342c406-4d7d-45ce-b028-06089369370e', 'en', '', '<div>c) the contractors’ activities and operations that impact other interested parties in the workplace.</div>'),
    ('0d3a918f-6329-42df-a230-bb7bd1316beb', '6342c406-4d7d-45ce-b028-06089369370e', 'es', '', '<div>c) las actividades y operaciones de los contratistas que impactan en otras partes interesadas en el lugar de trabajo. </div>'),
    ('b75c2389-42ba-4d51-b943-ff45e24adffd', '6442c599-3e04-4d89-b035-2265946938a1', 'en', 'Outsourcing', '<div>The organization shall ensure that outsourced functions and processes are controlled. The organization shall ensure that its outsourcing arrangements are consistent with legal requirements and other requirements and with achieving the intended outcomes of the OH&amp;S management system. The type and degree of control to be applied to these functions and processes shall be defined within the OH&amp;S management system.</div><div>NOTE: Coordination with external providers can assist an organization to address any impact that outsourcing has on its OH&amp;S performance.</div>'),
    ('b25c1baa-3cd0-474a-945c-47dae54ae4b6', '6442c599-3e04-4d89-b035-2265946938a1', 'es', 'Contratación externa', '<div>La organización debe asegurarse de que las funciones y los procesos contratados externamente estén controlados. La organización debe asegurarse de que sus acuerdos en materia de contratación externa son coherentes con los requisitos legales y otros requisitos y con alcanzar los resultados previstos del sistema de gestión de la SST. El tipo y el grado de control a aplicar a estas funciones y procesos deben definirse dentro del sistema de gestión de la SST. </div><div>NOTA: La coordinación con proveedores externos puede ayudar a una organización a abordar cualquier impacto que la contratación externa tenga sobre su desempeño de la SST. </div>'),
    ('b2d20d5a-b163-4422-bba4-8eeadd4a087e', '6142c0e0-56b9-4194-8296-0712916933e8', 'en', 'Emergency preparedness and response', '<div>The organization shall establish, implement and maintain a process(es) needed to prepare for and respond to potential emergency situations, as identified in 6.1.2.1, including:</div><div>{clause_8.2.a}</div><div>{clause_8.2.b}</div><div>{clause_8.2.c}</div><div>{clause_8.2.d}</div><div>{clause_8.2.e}</div><div>{clause_8.2.f}</div><div>{clause_8.2.g}</div><div>The organization shall maintain and retain documented information on the process(es) and on the plans for responding to potential emergency situations.</div>'),
    ('97d1e2d9-5db3-4ef9-a97c-6f35ea4a1cf5', '6142c0e0-56b9-4194-8296-0712916933e8', 'es', 'Preparación y respuesta ante emergencias', '<div>La organización debe establecer, implementar y mantener procesos necesarios para prepararse y para responder ante situaciones de emergencia potenciales, según se identifica en el apartado 6.1.2.1, incluyendo:</div><div>{clause_8.2.a}</div><div>{clause_8.2.b}</div><div>{clause_8.2.c}</div><div>{clause_8.2.d}</div><div>{clause_8.2.e}</div><div>{clause_8.2.f}</div><div>{clause_8.2.g}</div><div>La organización debe mantener y conservar información documentada sobre los procesos y sobre los planes de respuesta ante situaciones de emergencia potenciales. </div>'),
    ('71dc6743-d368-467b-8917-a8f7fd545c67', '6242c273-dee2-41df-a593-731f9269357b', 'en', '', '<div>a) establishing a planned response to emergency situations, including the provision of first aid;</div>'),
    ('6cdc5f64-32f6-427c-a2ed-00c4e0542ec0', '6242c273-dee2-41df-a593-731f9269357b', 'es', '', '<div>a) el establecimiento de una respuesta planificada a las situaciones de emergencia, incluyendo la prestación de primeros auxilios;</div>'),
    ('e6089564-bd58-40cc-98a3-8544f66364f0', '6742ca52-dab8-457a-ab1f-327c97693d5a', 'en', '', '<div>b) providing training for the planned response;</div>'),
    ('eb089d43-bdb5-45ab-bece-2d77f3636037', '6742ca52-dab8-457a-ab1f-327c97693d5a', 'es', '', '<div>b) la provisión de formación para la respuesta planificada; </div>'),
    ('7d016705-d8da-46c5-a367-02591ca40981', '6842cbe5-2dca-4ae5-821d-66f998693eed', 'en', '', '<div>c) periodically testing and exercising the planned response capability;</div>'),
    ('900184ee-9c0c-4b06-a4ef-621607a3e872', '6842cbe5-2dca-4ae5-821d-66f998693eed', 'es', '', '<div>c) las pruebas periódicas y el ejercicio de la capacidad de respuesta planificada; </div>'),
    ('78008f86-a1a8-4a26-946a-caaef819c0f2', '6542c72c-d356-4750-bb9f-c2a695693a34', 'en', '', '<div>d) evaluating performance and, as necessary, revising the planned response, including after testing and, in particular, after the occurrence of emergency situations;</div>'),
    ('9500bd2d-0de2-4365-b0fc-6ee10d19e201', '6542c72c-d356-4750-bb9f-c2a695693a34', 'es', '', '<div>d) la evaluación del desempeño y, cuando sea necesario, la revisión de la respuesta planificada, incluso después de las pruebas y, en particular, después de que ocurran situaciones de emergencia; </div>'),
    ('2550a1af-7e01-4a8f-9a85-f79b48051cbb', '6642c8bf-de30-410b-9f2a-00c396693bc7', 'en', '', '<div>e) communicating and providing relevant information to all workers on their duties and responsibilities;</div>'),
    ('18508d38-8d1f-4d58-950f-64603304fbac', '6642c8bf-de30-410b-9f2a-00c396693bc7', 'es', '', '<div>e) la comunicación y provisión de la información pertinente a todos los trabajadores sobre sus deberes y responsabilidades; </div>'),
    ('b8dd9e70-cdcd-48a0-ba86-12d8238e5be4', '6b42d09e-efa2-4e76-ac03-b1e08b692a76', 'en', '', '<div>f) communicating relevant information to contractors, visitors, emergency response services, government authorities and, as appropriate, the local community;</div>'),
    ('b5dd99b7-c713-4f07-86ec-52e3288e63c3', '6b42d09e-efa2-4e76-ac03-b1e08b692a76', 'es', '', '<div>f) la comunicación de la información pertinente a los contratistas, visitantes, servicios de respuesta ante emergencias, autoridades gubernamentales y, según sea apropiado, a la comunidad local;</div>'),
    ('df1e4301-5536-4889-8254-84bdba872d85', '6c42d231-ca8f-4271-8fd2-5e1d8c692c09', 'en', '', '<div>g) taking into account the needs and capabilities of all relevant interested parties and ensuring their involvement, as appropriate, in the development of the planned response.</div>'),
    ('ca1e21f2-655f-4b92-9a3d-7a22cd874b6e', '6c42d231-ca8f-4271-8fd2-5e1d8c692c09', 'es', '', '<div>g) tener en cuenta las necesidades y capacidades de todas las partes interesadas pertinentes y asegurándose que se involucran, según sea apropiado, en el desarrollo de la respuesta planificada. </div>'),
    ('1f4bac05-49fb-4bf1-80e9-cf59832353d1', '6535fb39-4de1-4f69-bb16-3bf9955c6e41', 'en', 'Performance evaluation', '<div>{clause_9.1}</div><div>{clause_9.2}</div><div>{clause_9.3}</div>'),
    ('324bc9ee-2df0-4a6a-8272-2f168e236522', '6535fb39-4de1-4f69-bb16-3bf9955c6e41', 'es', 'Evaluación del desempeño', '<div>{clause_9.1}</div><div>{clause_9.2}</div><div>{clause_9.3}</div>'),
    ('8852da64-64f5-4428-b626-5244ea26da80', '6435f9a6-473d-422e-a418-077c945c6cae', 'en', 'Monitoring, measurement, analysis and performance evaluation', '<div>{clause_9.1.1}</div><div>{clause_9.1.2}</div><div>{clause_9.1.3}</div>'),
    ('8d52e243-ad03-45ff-9c50-fa7707270827', '6435f9a6-473d-422e-a418-077c945c6cae', 'es', 'Seguimiento, medición, análisis y evaluación del desempeño', '<div>{clause_9.1.1}</div><div>{clause_9.1.2}</div><div>{clause_9.1.3}</div>'),
    ('c79ae6af-6089-459b-b808-c49b3bca254b', '6335f813-d8a1-4e3f-9822-d5c3935c6b1b', 'en', 'General', '<div>The organization shall establish, implement and maintain a process(es) for monitoring, measurement, analysis and performance evaluation.</div><div>The organization shall determine:</div><div>{clause_9.1.1.a}</div><div>{clause_9.1.1.b}</div><div>{clause_9.1.1.c}</div><div>{clause_9.1.1.d}</div><div>{clause_9.1.1.e}</div><div>The organization shall evaluate the OH&amp;S performance and determine the effectiveness of the OH&amp;S management system.</div><div>The organization shall ensure that monitoring and measuring equipment is calibrated or verified as applicable, and is used and maintained as appropriate.</div><div>NOTE: There can be legal requirements or other requirements (e.g. national or international standards) concerning the calibration or verification of monitoring and measuring equipment.</div><div>The organization shall retain appropriate documented information:</div><div>— as evidence of the results of monitoring, measurement, analysis and performance evaluation;</div><div>— on the maintenance, calibration or verification of measuring equipment.</div>'),
    ('ba9ad238-bd9d-4b9c-b292-316046ca369c', '6335f813-d8a1-4e3f-9822-d5c3935c6b1b', 'es', 'Generalidades', '<div>La organización debe establecer, implementar y mantener procesos para el seguimiento, la medición, el análisis y la evaluación del desempeño.</div><div>La organización debe determinar: </div><div>{clause_9.1.1.a}</div><div>{clause_9.1.1.b}</div><div>{clause_9.1.1.c}</div><div>{clause_9.1.1.d}</div><div>{clause_9.1.1.e}</div><div>La organización debe evaluar el desempeño de la SST y determinar la eficacia del sistema de gestión de la SST.</div><div>La organización debe asegurarse de que el equipo de seguimiento y medición se calibra o se verifica según sea aplicable, y se utiliza y mantiene según sea apropiado. </div><div>NOTA: Puede haber requisitos legales u otros requisitos (por ejemplo, normas nacionales o internacionales) relativos a la calibración o verificación del equipo de seguimiento y medición.</div><div>La organización debe conservar la información documentada adecuada:</div><div>— como evidencia de los resultados del seguimiento, la medición, el análisis y la evaluación del desempeño;</div><div>— sobre el mantenimiento, calibración o verificación de los equipos de medición. </div>'),
    ('1a4ad486-9202-4642-b1ed-97ae9e997002', '6235f680-7fe4-4b74-b498-97a6925c6988', 'en', '', '<div>a) what needs to be monitored and measured, including:</div><ul><li>{clause_9.1.1.a.1}</li><li>{clause_9.1.1.a.2}</li><li>{clause_9.1.1.a.3}</li><li>{clause_9.1.1.a.4}</li></ul>'),
    ('374b022d-1160-4999-8e7f-3be193995eb1', '6235f680-7fe4-4b74-b498-97a6925c6988', 'es', '', '<div>a) qué necesita seguimiento y medición, incluyendo: </div><ul><li>{clause_9.1.1.a.1}</li><li>{clause_9.1.1.a.2}</li><li>{clause_9.1.1.a.3}</li><li>{clause_9.1.1.a.4}</li></ul>'),
    ('59a66889-0ac8-4fe5-96c6-cc4588ca8f0d', '69360185-278a-4745-a92d-f765995c748d', 'en', '', '<div>1) the extent to which legal requirements and other requirements are fulfilled;</div>'),
    ('54a660aa-9e8e-46a6-b1df-14da6bca6166', '69360185-278a-4745-a92d-f765995c748d', 'es', '', '<div>1) el grado en que se cumplen los requisitos legales y otros requisitos;</div>'),
    ('a284c218-75c4-4e6c-b4d3-7440d1d18b0c', '6835fff2-d477-41da-a920-db08985c72fa', 'en', '', '<div>2) its activities and operations related to identified hazards, risks and opportunities;</div>'),
    ('af84d68f-5a59-454b-bfb3-887be6d1ac1b', '6835fff2-d477-41da-a920-db08985c72fa', 'es', '', '<div>2) sus actividades y operaciones relacionadas con los peligros, los riesgos y oportunidades identificados; </div>'),
    ('1426ac43-ef5c-4eaf-a69a-75f7f117d1f7', '6735fe5f-d7f0-4d6b-9e8c-481f975c7167', 'en', '', '<div>3) progress towards achievement of the organization’s OH&amp;S objectives;</div>'),
    ('0f26a464-0420-43f8-806f-cdc4f417d6b0', '6735fe5f-d7f0-4d6b-9e8c-481f975c7167', 'es', '', '<div>3) el progreso en el logro de los objetivos de la SST de la organización; </div>'),
    ('551c525a-8248-4c46-9927-5bea110de2ce', '6635fccc-fc7f-4e30-bb8e-dc12965c6fd4', 'en', '', '<div>4) effectiveness of operational and other controls;</div>'),
    ('3a1c27d9-c18e-4e05-86ff-3c35fe0dc4e5', '6635fccc-fc7f-4e30-bb8e-dc12965c6fd4', 'es', '', '<div>4) la eficacia de los controles operacionales y de otros controles; </div>'),
    ('470f5e7d-e257-47a9-9894-9451e8a55f99', '6d3607d1-c44c-4bd1-b28d-5b518d5c61a9', 'en', '', '<div>b) the methods for monitoring, measurement, analysis and performance evaluation, as applicable, to ensure valid results;</div>'),
    ('4a0f6336-f006-41b2-8a62-827e03a58a1a', '6d3607d1-c44c-4bd1-b28d-5b518d5c61a9', 'es', '', '<div>b) los métodos de seguimiento, medición, análisis y evaluación del desempeño, según sea aplicable, para asegurar resultados válidos; </div>'),
    ('40f5fbbc-6d9d-41c0-b21a-2b3c7185b0e8', '6c36063e-1652-4c56-bbb2-71f48c5c6016', 'en', '', '<div>c) the criteria against which the organization will evaluate its OH&amp;S performance;</div>'),
    ('35f5ea6b-66e3-4827-94c1-2fbf5e8592ff', '6c36063e-1652-4c56-bbb2-71f48c5c6016', 'es', '', '<div>c) los criterios frente a los que la organización evaluará su desempeño de la SST; </div>'),
    ('4e0eaed6-f23a-4092-ab02-1c9ea87e0112', '5f33b330-8c5b-48e0-9d6c-98f68f5a2638', 'en', '', '<div>d) when the monitoring and measuring shall be performed;</div>'),
    ('4b0eaa1d-e210-4d89-a0f9-e0f1bd7e2221', '5f33b330-8c5b-48e0-9d6c-98f68f5a2638', 'es', '', '<div>d) cuándo se debe realizar el seguimiento y la medición;</div>'),
    ('bac08b7f-4ebb-4feb-907f-ff4bf867c9db', '6033b4c3-8065-499b-b74e-e713905a27cb', 'en', '', '<div>e) when the results from monitoring and measurement shall be analysed, evaluated and communicated.</div>'),
    ('cdc0a968-6a25-490c-a2ba-eb70e367a8cc', '6033b4c3-8065-499b-b74e-e713905a27cb', 'es', '', '<div>e) cuándo se deben analizar, evaluar y comunicar los resultados del seguimiento y la medición. </div>'),
    ('bb78e3f4-f4bc-4ab8-b734-2c3435e6d590', '6133b656-7c4e-4a4a-8fc7-d60c915a295e', 'en', 'Evaluation of compliance', '<div>The organization shall establish, implement and maintain a process(es) for evaluating compliance with legal requirements and other requirements (see 6.1.3).</div><div>The organization shall:</div><div>{clause_9.1.2.a}</div><div>{clause_9.1.2.b}</div><div>{clause_9.1.2.c}</div><div>{clause_9.1.2.d}</div>'),
    ('a078b973-f943-476f-a954-334732e6d0d7', '6133b656-7c4e-4a4a-8fc7-d60c915a295e', 'es', 'Evaluación del cumplimiento', '<div>La organización debe establecer, implementar y mantener procesos para evaluar el cumplimiento con los requisitos legales y otros requisitos (véase 6.1.3).</div><div>La organización debe:</div><div>{clause_9.1.2.a}</div><div>{clause_9.1.2.b}</div><div>{clause_9.1.2.c}</div><div>{clause_9.1.2.d}</div>'),
    ('54ec1e95-2851-4f81-a1c1-9609cd0849a1', '6233b7e9-b9e0-4af5-b540-8909925a2af1', 'en', '', '<div>a) determine the frequency and method(s) for the evaluation of compliance;</div>'),
    ('47ec0a1e-6412-465a-a7a3-31a6b8082892', '6233b7e9-b9e0-4af5-b540-8909925a2af1', 'es', '', '<div>a) determinar la frecuencia y los métodos para la evaluación del cumplimiento;</div>'),
    ('4841f72a-086e-4196-8cd8-0f5a8dacb59e', '6333b97c-f673-4124-a2db-6ea2935a2c84', 'en', '', '<div>b) evaluate compliance and take action if needed (see 10.2);</div>'),
    ('4d41ff09-eb94-4fb5-b1bf-c6c59aacca15', '6333b97c-f673-4124-a2db-6ea2935a2c84', 'es', '', '<div>b) evaluar el cumplimiento y tomar acciones si es necesario (véase 10.2); </div>'),
    ('7b455a53-824f-4ebf-8c41-81a73a5d6407', '6433bb0f-7e9c-416f-878d-0eaf945a2e17', 'en', '', '<div>c) maintain knowledge and understanding of its compliance status with legal requirements and other requirements;</div>'),
    ('964584d4-3a43-4fe8-92f4-22141d5d3660', '6433bb0f-7e9c-416f-878d-0eaf945a2e17', 'es', '', '<div>c) mantener el conocimiento y la comprensión de su estado de cumplimiento con los requisitos legales y otros requisitos; </div>'),
    ('d64a2f68-ae23-4c3c-9231-e1701bb4eddc', '6533bca2-d993-45de-92f5-f158955a2faa', 'en', '', '<div>d) retain documented information of the compliance evaluation result(s).</div>'),
    ('c34a117f-510f-463b-bff6-f54b10b4dc8b', '6533bca2-d993-45de-92f5-f158955a2faa', 'es', '', '<div>d) conservar la información documentada de los resultados de la evaluación del cumplimiento. </div>'),
    ('4d69de19-19af-4035-81b1-54f592ad8d1d', '6633be35-e037-4319-9a57-d5f5965a313d', 'en', 'Internal audit', '<div>{clause_9.2.1}</div><div>{clause_9.2.2}</div>'),
    ('686a089a-3689-4216-b8f3-a7aa95ad91d6', '6633be35-e037-4319-9a57-d5f5965a313d', 'es', 'Auditoría interna', '<div>{clause_9.2.1}</div><div>{clause_9.2.2}</div>'),
    ('75d2614e-74fb-488a-92a8-9bf62d60db7a', '6733bfc8-4e80-43e8-8d47-d82e875a19a0', 'en', 'General', '<div>The organization shall conduct internal audits at planned intervals to provide information on whether the OH&amp;S management system:</div><div>{clause_9.2.1.a}</div><div>{clause_9.2.1.b}</div>'),
    ('62d24365-7d61-4a91-9221-15391260b0f9', '6733bfc8-4e80-43e8-8d47-d82e875a19a0', 'es', 'Generalidades', '<div>La organización debe llevar a cabo auditorías internas a intervalos planificados, para proporcionar información acerca de si el sistema de gestión de la SST: </div><div>{clause_9.2.1.a}</div><div>{clause_9.2.1.b}</div>'),
    ('55dc5077-652d-4563-beb1-cf235fc66de3', '6833c15b-d6d0-43a3-93ca-21ab885a1b33', 'en', '', '<div>a) conforms to:</div><ul><li>{clause_9.2.1.a.1}</li><li>{clause_9.2.1.a.2}</li></ul>'),
    ('58dc5530-cc2d-41b4-ae6b-fe185ac66604', '6833c15b-d6d0-43a3-93ca-21ab885a1b33', 'es', '', '<div>a) es conforme con: </div><ul><li>{clause_9.2.1.a.1}</li><li>{clause_9.2.1.a.2}</li></ul>'),
    ('c48aec63-a60a-4db3-9b03-5d17065eba1f', 'f13b54cb-e558-4fe3-8b75-c87f01619573', 'en', '', '<div>1) the organization’s own requirements for its OH&amp;S management system, including the OH&amp;S policy and OH&amp;S objectives;</div>'),
    ('bf8ae484-b363-4c64-abe2-cbe4195ed808', 'f13b54cb-e558-4fe3-8b75-c87f01619573', 'es', '', '<div>1) los requisitos propios de la organización para su sistema de gestión de la SST, incluyendo la política de la SST y los objetivos de la SST; </div>'),
    ('922559fa-1d37-4c9a-a040-898a28cf33f6', 'f03b5338-7654-4228-81b5-08f2006193e0', 'en', '', '<div>2) the requirements of this document;</div>'),
    ('77252f79-c82b-43c1-85fa-885525cf2f3d', 'f03b5338-7654-4228-81b5-08f2006193e0', 'es', '', '<div>2) los requisitos de este documento;</div>'),
    ('9929d929-f2f5-4349-8979-07e52d30a7b5', 'f33b57f1-b958-48fd-9817-88c503619899', 'en', '', '<div>b) is effectively implemented and maintained.</div>'),
    ('9429d14a-031f-4652-9688-d6fa2030933e', 'f33b57f1-b958-48fd-9817-88c503619899', 'es', '', '<div>b) se implementa y mantiene eficazmente. </div>'),
    ('52e90238-bf09-4360-9435-036007171294', 'f23b565e-43cc-4832-b6a0-c1e802619706', 'en', 'Internal audit programme', '<div>The organization shall:</div><div>{clause_9.2.2.a}</div><div>{clause_9.2.2.b}</div><div>{clause_9.2.2.c}</div><div>{clause_9.2.2.d}</div><div>{clause_9.2.2.e}</div><div>{clause_9.2.2.f}</div><div>NOTE: For more information on auditing and the competence of auditors, see ISO 19011.</div>'),
    ('5fe916af-b851-4cc7-99ab-969bec16e813', 'f23b565e-43cc-4832-b6a0-c1e802619706', 'es', 'Programa de auditoría interna', '<div>La organización debe: </div><div>{clause_9.2.2.a}</div><div>{clause_9.2.2.b}</div><div>{clause_9.2.2.c}</div><div>{clause_9.2.2.d}</div><div>{clause_9.2.2.e}</div><div>{clause_9.2.2.f}</div><div>NOTA: Para más información sobre las auditorías y las competencias de los auditores, véase la Norma ISO 19011.</div>'),
    ('77fd93cf-296d-42c7-ab86-6abb5389e373', 'f53b5b17-6895-4ab7-a8aa-9e2305619bbf', 'en', '', '<div>a) plan, establish, implement and maintain an audit programme(s) including the frequency, methods, responsibilities, consultation, planning requirements and reporting, which shall take into consideration the importance of the processes concerned and the results of previous audits;</div>'),
    ('6afd7f58-3025-4960-b2b3-f0806e8a0df4', 'f53b5b17-6895-4ab7-a8aa-9e2305619bbf', 'es', '', '<div>a) planificar, establecer, implementar y mantener programas de auditoría que incluyan la frecuencia, los métodos, las responsabilidades, la consulta, los requisitos de planificación, y la elaboración de informes, que deben tener en consideración la importancia de los procesos involucrados y los resultados de las auditorías previas; </div>'),
    ('59ce4526-074a-419e-ade1-b1ce2300e94a', 'f43b5984-bfcc-444c-84df-5c8604619a2c', 'en', '', '<div>b) define the audit criteria and scope for each audit;</div>'),
    ('76ce72cd-d551-428d-9332-ad012800f129', 'f43b5984-bfcc-444c-84df-5c8604619a2c', 'es', '', '<div>b) definir los criterios de la auditoría y el alcance para cada auditoría;</div>'),
    ('5ed0afa5-4ba4-443d-9aaf-1bf99b8275b9', 'f73b5e3d-652b-4bc1-88e3-a5d907619ee5', 'en', '', '<div>c) select auditors and conduct audits to ensure objectivity and the impartiality of the audit process;</div>'),
    ('71d0cd8e-c1c1-492e-ba87-62b6b682a03a', 'f73b5e3d-652b-4bc1-88e3-a5d907619ee5', 'es', '', '<div>c) seleccionar auditores y llevar a cabo auditorías para asegurarse de la objetividad y la imparcialidad del proceso de auditoría; </div>'),
    ('c55d7504-2ba6-4244-8ecb-f1e421e85e08', 'f63b5caa-b730-4c46-869d-5f5c06619d52', 'en', '', '<div>d) ensure that the results of the audits are reported to relevant managers; ensure that relevant audit results are reported to workers, and, where they exist, workers’ representatives, and other relevant interested parties;</div>'),
    ('ca5d7ce3-1bd1-4793-bdec-83170ee8401f', 'f63b5caa-b730-4c46-869d-5f5c06619d52', 'es', '', '<div>d) asegurarse de que los resultados de las auditorías se informan a los directivos pertinentes; asegurarse de que se informa de los hallazgos de la auditoría pertinentes a los trabajadores, y cuando existan, a los representantes de los trabajadores, y a otras partes interesadas pertinentes;</div>'),
    ('5d2c485b-186f-443b-a5ce-df8fa17c1217', 'e93b4833-8eec-42db-afd2-5ef70961a20b', 'en', '', '<div>e) take action to address nonconformities and continually improve its OH&amp;S performance (see Clause 10);</div>'),
    ('482c274c-7583-4a3c-9d85-1feca47c16d0', 'e93b4833-8eec-42db-afd2-5ef70961a20b', 'es', '', '<div>e) tomar acciones para abordar las no conformidades y mejorar continuamente su desempeño de la SST (véase el Capítulo 10);</div>'),
    ('0d427f92-4c63-4de2-a563-bfc2c1708fee', 'e83b46a0-9d5e-4e20-a0b4-ab0a0861a078', 'en', '', '<div>f) retain documented information as evidence of the implementation of the audit programme and the audit results.</div>'),
    ('2242a0a1-df65-40b9-96a4-365dae707205', 'e83b46a0-9d5e-4e20-a0b4-ab0a0861a078', 'es', '', '<div>f) conservar información documentada como evidencia de la implementación del programa de auditoría y de los resultados de las auditorías. </div>'),
    ('c75df77c-020a-46dc-b246-5bfc150e02d8', 'eb390cc2-2926-49a2-9e90-82349b5eb64a', 'en', 'Management review', '<div>Top management shall review the organization’s OH&amp;S management system, at planned intervals, to ensure its continuing suitability, adequacy and effectiveness.</div><div>The management review shall include consideration of:</div><div>{clause_9.3.a}</div><div>{clause_9.3.b}</div><div>{clause_9.3.c}</div><div>{clause_9.3.d}</div><div>{clause_9.3.e}</div><div>{clause_9.3.f}</div><div>{clause_9.3.g}</div><div>The outputs of the management review shall include decisions related to:</div><div>— the continuing suitability, adequacy and effectiveness of the OH&amp;S management system in achieving its intended outcomes;</div><div>— continual improvement opportunities;</div><div>— any need for changes to the OH&amp;S management system;</div><div>— resources needed;</div><div>— actions, if needed;</div><div>— opportunities to improve integration of the OH&amp;S management system with other business processes;</div><div>— any implications for the strategic direction of the organization.</div><div>Top management shall communicate the relevant outputs of management reviews to workers, and, where they exist, workers’ representatives (see 7.4).</div><div>The organization shall retain documented information as evidence of the results of management reviews.</div>'),
    ('bc5de62b-892e-42db-9ad4-477f220e174f', 'eb390cc2-2926-49a2-9e90-82349b5eb64a', 'es', 'Revisión por la dirección', '<div>La alta dirección debe revisar el sistema de gestión de la SST de la organización a intervalos planificados, para asegurarse de su conveniencia, adecuación y eficacia continuas.</div><div>La revisión por la dirección debe considerar: </div><div>{clause_9.3.a}</div><div>{clause_9.3.b}</div><div>{clause_9.3.c}</div><div>{clause_9.3.d}</div><div>{clause_9.3.e}</div><div>{clause_9.3.f}</div><div>{clause_9.3.g}</div><div>Las salidas de la revisión por la dirección deben incluir las decisiones relacionadas con: </div><div>— la conveniencia, adecuación y eficacia continuas del sistema de gestión de la SST en alcanzar sus resultados previstos;</div><div>— las oportunidades de mejora continua;</div><div>— cualquier necesidad de cambio en el sistema de gestión de la SST;</div><div>— los recursos necesarios;</div><div>— las acciones, si son necesarias;</div><div>— las oportunidades de mejorar la integración del sistema de gestión de la SST con otros procesos de negocio;</div><div>— cualquier implicación para la dirección estratégica de la organización. </div><div>La alta dirección debe comunicar los resultados pertinentes de las revisiones por la dirección a los trabajadores, y cuando existan, a los representantes de los trabajadores (véase 7.4).</div><div>La organización debe conservar información documentada como evidencia de los resultados de las revisiones por la dirección.</div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('cafe843d-6b1d-44d5-9674-af11cea87f49', 'ec390e55-9cd8-452d-a979-be919c5eb7dd', 'en', '', '<div>a) the status of actions from previous management reviews;</div>'),
    ('cdfe88f6-71d5-4b36-ba10-b13ec9a8776a', 'ec390e55-9cd8-452d-a979-be919c5eb7dd', 'es', '', '<div>a) el estado de las acciones de las revisiones por la dirección previas; </div>'),
    ('c5fc19be-99b2-43b6-ba5e-8e46ca1e691a', 'e939099c-5881-4718-832d-c71e995eb324', 'en', '', '<div>b) changes in external and internal issues that are relevant to the OH&amp;S management system, including:</div><ul><li>{clause_9.3.b.1}</li><li>{clause_9.3.b.2}</li><li>{clause_9.3.b.3}</li></ul>'),
    ('d2fc2e35-92fa-4d55-8082-7e29af1e3e99', 'e939099c-5881-4718-832d-c71e995eb324', 'es', '', '<div>b) los cambios en las cuestiones externas e internas que sean pertinentes al sistema de gestión de la SST, incluyendo: </div><ul><li>{clause_9.3.b.1}</li><li>{clause_9.3.b.2}</li><li>{clause_9.3.b.3}</li></ul>'),
    ('e6066da7-5055-45df-bb10-493386afed03', 'ea390b2f-cab3-4153-a0c6-265b9a5eb4b7', 'en', '', '<div>1) the needs and expectations of interested parties;</div>'),
    ('c9064000-0848-4708-a815-d5c881afe524', 'ea390b2f-cab3-4153-a0c6-265b9a5eb4b7', 'es', '', '<div>1) las necesidades y expectativas de las partes interesadas;</div>'),
    ('e18fdf30-c2c2-41d8-9a75-f698fadc1b24', 'e7390676-9c8b-4db6-b507-8220975eaffe', 'en', '', '<div>2) legal requirements and other requirements;</div>'),
    ('de8fda77-b3a3-4f0f-aabb-c7a3ffdc2303', 'e7390676-9c8b-4db6-b507-8220975eaffe', 'es', '', '<div>2) los requisitos legales y otros requisitos;</div>'),
    ('0557adc1-76ff-4021-8c47-117d944f55c5', 'e8390809-60a5-45b1-999f-ec5d985eb191', 'en', '', '<div>3) risks and opportunities;</div>'),
    ('f0578cb2-b2be-43fa-a6e5-d2e2a74f73ae', 'e8390809-60a5-45b1-999f-ec5d985eb191', 'es', '', '<div>3) los riesgos y oportunidades;</div>'),
    ('e0cd6532-999e-4b32-b3ad-4e628f4e7e46', 'e5390350-a5c6-497c-8067-966a955eacd8', 'en', '', '<div>c) the extent to which the OH&amp;S policy and the OH&amp;S objectives have been met;</div>'),
    ('f5cd8641-8bef-4129-990e-8cfdac4eabed', 'e5390350-a5c6-497c-8067-966a955eacd8', 'es', '', '<div>c) el grado en el que se han cumplido la política de la SST y los objetivos de la SST; </div>'),
    ('333329fb-1cc1-470b-af8a-092f3a22946f', 'e63904e3-4def-4c27-be9c-2fd7965eae6b', 'en', '', '<div>d) information on the OH&amp;S performance, including trends in:</div><ul><li>{clause_9.3.d.1}</li><li>{clause_9.3.d.2}</li><li>{clause_9.3.d.3}</li><li>{clause_9.3.d.4}</li><li>{clause_9.3.d.5}</li><li>{clause_9.3.d.6}</li></ul>'),
    ('1e3308ec-382b-402c-a2e7-888c2d227ff8', 'e63904e3-4def-4c27-be9c-2fd7965eae6b', 'es', '', '<div>d) la información sobre el desempeño de la SST, incluidas las tendencias relativas a: </div><ul><li>{clause_9.3.d.1}</li><li>{clause_9.3.d.2}</li><li>{clause_9.3.d.3}</li><li>{clause_9.3.d.4}</li><li>{clause_9.3.d.5}</li><li>{clause_9.3.d.6}</li></ul>'),
    ('0c420024-d4bb-4dd4-80d9-7f04d029fa30', 'f339195a-8a1b-4dba-b5de-71bc935ea9b2', 'en', '', '<div>1) incidents, nonconformities, corrective actions and continual improvement;</div>'),
    ('11420803-8160-4103-b0af-9837cd29f577', 'f339195a-8a1b-4dba-b5de-71bc935ea9b2', 'es', '', '<div>1) los incidentes, no conformidades, acciones correctivas y mejora continua;</div>'),
    ('a5b53ac5-3a74-4f4d-92ce-e719f3f1c8c1', 'f4391aed-c3e3-4125-bc12-8339945eab45', 'en', '', '<div>2) monitoring and measurement results;</div>'),
    ('b8b558ae-6ee8-4a5e-83a0-d6d6def1a7b2', 'f4391aed-c3e3-4125-bc12-8339945eab45', 'es', '', '<div>2) los resultados de seguimiento y medición;</div>'),
    ('a2913939-eef0-41c5-ad4e-54950a6820ad', '6d541ce5-9697-418d-9910-00d51d52b6fd', 'en', '', '<div>3) results of evaluation of compliance with legal requirements and other requirements;</div>'),
    ('bd9163ba-b223-4606-af12-29caed67f306', '6d541ce5-9697-418d-9910-00d51d52b6fd', 'es', '', '<div>3) los resultados de la evaluación del cumplimiento con los requisitos legales y otros requisitos; </div>'),
    ('28f72188-d36e-4bcc-bdd6-2d90536f1cac', '6c541b52-3905-4e82-950a-b1b81c52b56a', 'en', '', '<div>4) audit results;</div>'),
    ('15f7039f-d3cb-40ab-ba38-776b686f3dbb', '6c541b52-3905-4e82-950a-b1b81c52b56a', 'es', '', '<div>4) los resultados de la auditoría;</div>'),
    ('5a98a6f3-9417-458f-bdda-2047e6109c17', '6b5419bf-da92-4633-9e21-420f1b52b3d7', 'en', '', '<div>5) consultation and participation of workers;</div>'),
    ('7598d174-a336-4858-8bba-1934e910a0d0', '6b5419bf-da92-4633-9e21-420f1b52b3d7', 'es', '', '<div>5) la consulta y la participación de los trabajadores; </div>'),
    ('2a0facca-b7bf-4526-8f04-9e7a060519ee', '6a54182c-6b8d-4878-8344-04021a52b244', 'en', '', '<div>6) risks and opportunities;</div>'),
    ('2f0fb4a9-23f8-4e65-81f4-cf65f304fc05', '6a54182c-6b8d-4878-8344-04021a52b244', 'es', '', '<div>6) los riesgos y oportunidades; </div>'),
    ('343f6b35-58d0-4851-85bf-35a904c27871', '69541699-73b1-4711-ab8c-9d691952b0b1', 'en', '', '<div>e) adequacy of resources for maintaining an effective OH&amp;S management system;</div>'),
    ('273f56be-52e6-424a-bf9b-45c60fc289c2', '69541699-73b1-4711-ab8c-9d691952b0b1', 'es', '', '<div>e) la adecuación de los recursos para mantener un sistema de gestión de la SST eficaz; </div>'),
    ('0e25d614-3133-4f08-8cc5-31d46e406820', '68541506-ac6a-4296-a8cf-726c1852af1e', 'en', '', '<div>f) relevant communication(s) with interested parties;</div>'),
    ('f325ab93-793f-4ddf-aa3d-e4678b4095c7', '68541506-ac6a-4296-a8cf-726c1852af1e', 'es', '', '<div>f) las comunicaciones pertinentes con las partes interesadas; </div>'),
    ('0d6d7d9f-e97e-417b-bfdd-126b30c15c6b', '67541373-5dce-4107-9e84-90f31752ad8b', 'en', '', '<div>g) opportunities for continual improvement.</div>'),
    ('206d9b88-490c-4d7c-837a-c8903bc16dbc', '67541373-5dce-4107-9e84-90f31752ad8b', 'es', '', '<div>g) las oportunidades de mejora continua. </div>'),
    ('2fddf776-c779-4f22-81a9-763e203701a2', '665411e0-cef2-435c-90d3-9c561652abf8', 'en', 'Improvement', '<div>{clause_10.1}</div><div>{clause_10.2}</div><div>{clause_10.3}</div>'),
    ('2cddf2bd-73ca-49f9-9e0d-74111536f051', '665411e0-cef2-435c-90d3-9c561652abf8', 'es', 'Mejora', '<div>{clause_10.1}</div><div>{clause_10.2}</div><div>{clause_10.3}</div>'),
    ('c73cb1f1-dfc0-4f7d-8013-718d71c531b5', '7554297d-bda0-4a85-a27e-2b8d1552aa65', 'en', 'General', '<div>The organization shall determine opportunities for improvement (see Clause 9) and implement necessary actions to achieve the intended outcomes of its OH&amp;S management system.</div>'),
    ('d23cc342-55de-446e-87ce-9b9264c51d3e', '7554297d-bda0-4a85-a27e-2b8d1552aa65', 'es', 'Generalidades', '<div>La organización debe determinar las oportunidades de mejora (véase el Capítulo 9) e implementar las acciones necesarias para alcanzar los resultados previstos de su sistema de gestión de la SST. </div>'),
    ('30baa1a0-1603-4484-8dc2-38684bab9c94', '745427ea-8160-411a-ab51-2dd01452a8d2', 'en', 'Incident, nonconformity and corrective action', '<div>The organization shall establish, implement and maintain a process(es), including reporting, investigating and taking action, to determine and manage incidents and nonconformities.</div><div>When an incident or a nonconformity occurs, the organization shall:</div><div>{clause_10.2.a}</div><div>{clause_10.2.b}</div><div>{clause_10.2.c}</div><div>{clause_10.2.d}</div><div>{clause_10.2.e}</div><div>{clause_10.2.f}</div><div>{clause_10.2.g}</div><div>Corrective actions shall be appropriate to the effects or potential effects of the incidents or nonconformities encountered.</div><div>The organization shall retain documented information as evidence of:</div><div>— the nature of the incidents or nonconformities and any subsequent actions taken;</div><div>— the results of any action and corrective action, including their effectiveness.</div><div>The organization shall communicate this documented information to relevant workers, and, where they exist, workers’ representatives, and other relevant interested parties.</div><div>NOTE: The reporting and investigation of incidents without undue delay can enable hazards to be eliminated and associated OH&amp;S risks to be minimized as soon as possible.</div>'),
    ('4dbacf47-08a8-42d3-a4c3-f85330ab7213', '745427ea-8160-411a-ab51-2dd01452a8d2', 'es', 'Incidentes, no conformidades y acciones correctivas', '<div>La organización debe establecer, implementar y mantener procesos, incluyendo informar, investigar y tomar acciones para determinar y gestionar los incidentes y las no conformidades. </div><div>Cuando ocurra un incidente o una no conformidad, la organización debe: </div><div>{clause_10.2.a}</div><div>{clause_10.2.b}</div><div>{clause_10.2.c}</div><div>{clause_10.2.d}</div><div>{clause_10.2.e}</div><div>{clause_10.2.f}</div><div>{clause_10.2.g}</div><div>Las acciones correctivas deben ser apropiadas a los efectos o los efectos potenciales de los incidentes o las no conformidades encontradas.</div><div>La organización debe conservar información documentada, como evidencia de: </div><div>— la naturaleza de los incidentes o las no conformidades y cualquier acción tomada posteriormente;</div><div>— los resultados de cualquier acción y acción correctiva, incluyendo su eficacia. </div><div>La organización debe comunicar esta información documentada a los trabajadores pertinentes, y cuando existan, a los representantes de los trabajadores, y a otras partes interesadas pertinentes.</div><div>NOTA: Informar e investigar incidentes sin retrasos indebidos puede permitir que se eliminen los peligros y que los riesgos para la SST asociados se minimicen lo antes posible. </div>'),
    ('d12d2c9a-be8c-43f6-8209-392af92abebe', '6751d4dc-cd47-4954-9586-99d217506ef4', 'en', '', '<div>a) react in a timely manner to the incident or nonconformity and, as applicable:</div><ul><li>{clause_10.2.a.1}</li><li>{clause_10.2.a.2}</li></ul>'),
    ('b62d0219-d11f-4f95-8ac6-e675062ad335', '6751d4dc-cd47-4954-9586-99d217506ef4', 'es', '', '<div>a) reaccionar de manera oportuna ante el incidente o la no conformidad y, según sea aplicable:</div>'),
    ('8dbeb083-23df-4c1f-907d-0537193512a7', '6851d66f-3c23-449f-909b-35df18507087', 'en', '', '<div>1) take action to control and correct it;</div>'),
    ('88bea8a4-d956-4148-a0a6-ec04fc34e500', '6851d66f-3c23-449f-909b-35df18507087', 'es', '', '<div>1) tomar acciones para controlar y corregir el incidente o la no conformidad; </div>'),
    ('1c1cc658-7d22-4b1c-badb-fe80fa8c9c7c', '6951d802-aabf-488e-b629-3fc81950721a', 'en', '', '<div>2) deal with the consequences;</div>'),
    ('291cdacf-200d-451b-b3ae-78bbef8c8b2b', '6951d802-aabf-488e-b629-3fc81950721a', 'es', '', '<div>2) hacer frente a las consecuencias; </div>'),
    ('d5b742c9-ff3a-4015-b120-a885fe2d293d', '6a51d995-b491-4249-a3dd-37251a5073ad', 'en', '', '<div>b) evaluate, with the participation of workers (see 5.4) and the involvement of other relevant interested parties, the need for corrective action to eliminate the root cause(s) of the incident or nonconformity, in order that it does not recur or occur elsewhere, by:</div><ul><li>{clause_10.2.b.1}</li><li>{clause_10.2.b.2}</li><li>{clause_10.2.b.3}</li></ul>'),
    ('d0b73aea-eca7-4476-8460-7f1a012d2df6', '6a51d995-b491-4249-a3dd-37251a5073ad', 'es', '', '<div>b) evaluar, con la participación de los trabajadores (véase 5.4) e involucrando a otras partes interesadas pertinentes, la necesidad de acciones correctivas para eliminar las causas raíz del incidente o la no conformidad, con el fin de que no vuelva a ocurrir ni ocurra en otra parte, mediante:</div><ul><li>{clause_10.2.b.1}</li><li>{clause_10.2.b.2}</li><li>{clause_10.2.b.3}</li></ul>'),
    ('965d41c6-307b-4a72-8244-f4ee13fc0a32', '6351ce90-49e3-4c10-874c-f666135068a8', 'en', '', '<div>1) investigating the incident or reviewing the nonconformity;</div>'),
    ('b35d6f6d-0705-4269-847e-132128fc2b41', '6351ce90-49e3-4c10-874c-f666135068a8', 'es', '', '<div>1) la investigación del incidente o la revisión de la no conformidad; </div>'),
    ('413157ef-f04b-4d4b-ba29-51db6661cefb', '6451d023-3b72-43cb-95fc-748314506a3b', 'en', '', '<div>2) determining the cause(s) of the incident or nonconformity;</div>'),
    ('34314378-0bb5-466c-8a91-77a05161adec', '6451d023-3b72-43cb-95fc-748314506a3b', 'es', '', '<div>2) la determinación de las causas del incidente o la no conformidad;</div>'),
    ('01eadea4-964a-4518-8b79-018414be8430', '6551d1b6-5145-4a3a-b435-583c15506bce', 'en', '', '<div>3) determining if similar incidents have occurred, if nonconformities exist, or if they could potentially occur;</div>'),
    ('06eae683-84b3-4c4f-bb4f-1ab711be7f77', '6551d1b6-5145-4a3a-b435-583c15506bce', 'es', '', '<div>3) la determinación de si han ocurrido incidentes similares, si existen no conformidades, o si potencialmente podrían ocurrir; </div>'),
    ('9b5e1945-f215-4161-9d6e-6999388652c1', '6651d349-8b0c-4da5-ba69-69b916506d61', 'en', '', '<div>c) review existing assessments of OH&amp;S risks and other risks, as appropriate (see 6.1);</div>'),
    ('ae5e372e-499b-433a-8e40-5956238631b2', '6651d349-8b0c-4da5-ba69-69b916506d61', 'es', '', '<div>c) revisar las evaluaciones existentes de los riesgos para la SST y otros riesgos, según sea apropiado (véase 6.1); </div>'),
    ('d67643b2-0080-45ee-be4c-d0e2d3e30846', '6f51e174-6cf0-45fc-bebe-7cea0f50625c', 'en', '', '<div>d) determine and implement any action needed, including corrective action, in accordance with the hierarchy of controls (see 8.1.2) and the management of change (see 8.1.3);</div>'),
    ('eb7664c1-8a62-40fd-a3ae-0f7df0e335ed', '6f51e174-6cf0-45fc-bebe-7cea0f50625c', 'es', '', '<div>d) determinar e implementar cualquier acción necesaria, incluyendo acciones correctivas, de acuerdo con la jerarquía de los controles (véase 8.1.2) y la gestión del cambio (véase 8.1.3); </div>'),
    ('28dc087b-d16b-4097-ba29-8baf7eb71e6f', '7051e307-1519-48a7-bcf3-1657105063ef', 'en', '', '<div>e) assess OH&amp;S risks that relate to new or changed hazards, prior to taking action;</div>'),
    ('13dbe76c-31ca-44d0-ad87-0b0c71b709f8', '7051e307-1519-48a7-bcf3-1657105063ef', 'es', '', '<div>e) evaluar los riesgos de la SST que se relacionan con los peligros nuevos o modificados, antes de tomar acciones;</div>'),
    ('b0168a28-e763-462c-ae4a-3b304de82acc', '7ea87eb2-39ce-4d12-a7a4-9e98aecef1ba', 'en', '', '<div>f) review the effectiveness of any action taken, including corrective action;</div>'),
    ('9d166c3f-cbf9-4d0b-9be1-2b0b62e84bdb', '7ea87eb2-39ce-4d12-a7a4-9e98aecef1ba', 'es', '', '<div>f) revisar la eficacia de cualquier acción tomada, incluyendo las acciones correctivas; </div>'),
    ('29b234d9-1447-44a5-aa3d-b2b5075b97cd', '7fa88045-ace1-44dd-8313-c335afcef34d', 'en', '', '<div>g) make changes to the OH&amp;S management system, if necessary.</div>'),
    ('44b25f5a-c15a-4066-bc65-d26aea5b6a26', '7fa88045-ace1-44dd-8313-c335afcef34d', 'es', '', '<div>g) si fuera necesario, hacer cambios al sistema de gestión de la SST. </div>'),
    ('2488baea-4f1a-4a06-810d-ff1a8d26158e', '7ca87b8c-8276-4f88-819c-08e2acceee94', 'en', 'Continual improvement', '<div>The organization shall continually improve the suitability, adequacy and effectiveness of the OH&amp;S management system, by:</div><div>{clause_10.3.a}</div><div>{clause_10.3.b}</div><div>{clause_10.3.c}</div><div>{clause_10.3.d}</div><div>{clause_10.3.e}</div>'),
    ('2988c2c9-8be8-45c5-adce-28857a25f7a5', '7ca87b8c-8276-4f88-819c-08e2acceee94', 'es', 'Mejora continua', '<div>La organización debe mejorar continuamente la conveniencia, adecuación y eficacia del sistema de gestión de la SST para:</div><div>{clause_10.3.a}</div><div>{clause_10.3.b}</div><div>{clause_10.3.c}</div><div>{clause_10.3.d}</div><div>{clause_10.3.e}</div>'),
    ('5511b513-b9b4-436f-b48e-35676d3004b7', '7da87d1f-f179-4a43-b8a9-15efadcef027', 'en', '', '<div>a) enhancing OH&amp;S performance;</div>'),
    ('7011df94-b52d-46b8-9715-82d470300970', '7da87d1f-f179-4a43-b8a9-15efadcef027', 'es', '', '<div>a) mejorar el desempeño de la SST; </div>'),
    ('97c13ab4-6e74-48e8-baa2-fcf468b97640', '7aa87866-ad31-4e26-973a-474caaceeb6e', 'en', '', '<div>b) promoting a culture that supports an OH&amp;S management system;</div>'),
    ('7cc11033-b680-47bf-95a0-e70785b9a3e7', '7aa87866-ad31-4e26-973a-474caaceeb6e', 'es', '', '<div>b) promover una cultura que apoye al sistema de gestión de la SST;</div>'),
    ('2eba0c55-5378-4db1-9908-8bc901b5ef91', '7ba879f9-8a9a-4e21-9d8a-5749abceed01', 'en', '', '<div>c) promoting the participation of workers in implementing actions for the continual improvement of the OH&amp;S management system;</div>'),
    ('21b9f7de-34f4-462a-8814-ff660cb600e2', '7ba879f9-8a9a-4e21-9d8a-5749abceed01', 'es', '', '<div>c) promover la participación de los trabajadores en la implementación de acciones para la mejora continua del sistema de gestión de la SST; </div>'),
    ('2a570596-ecd0-4202-9a99-015e1ab1a2c2', '78a87540-e53b-46ac-bd82-6036a8cee848', 'en', '', '<div>d) communicating the relevant results of continual improvement to workers, and, where they exist, workers’ representatives;</div>'),
    ('275700dd-8301-4459-8174-7cb10fb19171', '78a87540-e53b-46ac-bd82-6036a8cee848', 'es', '', '<div>d) comunicar los resultados pertinentes de la mejora continua a sus trabajadores, y cuando existan, a los representantes de los trabajadores;</div>'),
    ('97074f3f-0ed4-415b-ac6a-350bba5b2e0b', '79a876d3-5e97-4f97-b804-2d53a9cee9db', 'en', '', '<div>e) maintaining and retaining documented information as evidence of continual improvement.</div>'),
    ('aa076d28-87af-455c-bed3-4530c55b3f5c', '79a876d3-5e97-4f97-b804-2d53a9cee9db', 'es', '', '<div>e) mantener y conservar información documentada como evidencia de la mejora continua. </div>'),
    ('184fd1d8-5fa2-4e50-8dd1-088081e7e4cc', '60679cae-0953-42ce-9c93-d9c8dcaaa7f6', 'en', 'Scope', '<div>This document specifies requirements for a food safety management system (FSMS) to enable an organization that is directly or indirectly involved in the food chain:</div><div>{clause_1.a}</div><div>{clause_1.b}</div><div>{clause_1.c}</div><div>{clause_1.d}</div><div>{clause_1.e}</div><div>{clause_1.f}</div><div>{clause_1.g}</div><div>All requirements of this document are generic and are intended to be applicable to all organizations in the food chain, regardless of size and complexity. Organizations that are directly or indirectly involved include, but are not limited to, feed producers, animal food producers, harvesters of wild plants and animals, farmers, producers of ingredients, food manufacturers, retailers, and organizations providing food services, catering services, cleaning and sanitation services, transportation, storage and distribution services, suppliers of equipment, cleaning and disinfectants, packaging materials and other food contact materials.</div><div>This document allows any organization, including small and/or less developed organizations (e.g. a small farm, a small packer-distributor, a small retail or food service outlet) to implement externallydeveloped elements in their FSMS.</div><div>Internal and/or external resources can be used to meet the requirements of this document.</div>'),
    ('254fe64f-ff43-4a17-86a3-82bb96e805db', '60679cae-0953-42ce-9c93-d9c8dcaaa7f6', 'es', 'Objeto y campo de aplicación', '<div>Este documento especifica los requisitos para un sistema de gestión de la inocuidad de los alimentos (SGIA) para permitir a una organización que está directa o indirectamente involucrada en la cadena alimentaria: </div><div>{clause_1.a}</div><div>{clause_1.b}</div><div>{clause_1.c}</div><div>{clause_1.d}</div><div>{clause_1.e}</div><div>{clause_1.f}</div><div>{clause_1.g}</div><div>Todos los requisitos de este documento son genéricos y se prevé que sean aplicables a todas las organizaciones de la cadena alimentaria, sin importar su tamaño o complejidad. Las organizaciones que están directa o indirectamente involucradas incluyen, pero no se limitan a, productores de alimento para animales productores de alimentos, productores de alimentos para animales, cosechadores de plantas y animales silvestres, agricultores, productores de ingredientes, fabricantes de alimentos, minoristas, y organizaciones que proporcionan servicios de alimentos, servicios de catering, servicios de limpieza y desinfección, servicios de transporte, almacenamiento y distribución, proveedores de equipamiento, limpieza y desinfectantes, materiales de embalaje y otros materiales en contacto con alimentos. </div><div>Este documento permite a cualquier organización, incluidas las pequeñas y/o menos desarrolladas (por ejemplo una granja pequeña, un envasador-distribuidor pequeño, un minorista pequeño o venta de servicio de alimentos) implementar elementos desarrollados externamente en su SGIA. </div><div>Los recursos internos y/o externos se pueden utilizar para cumplir los requisitos de este documento.</div>'),
    ('89f1bc03-1adc-4723-a372-0f37a12fbeb7', '5f679b1b-9ab8-4edf-b705-cfdfdbaaa663', 'en', '', '<div>a) to plan, implement, operate, maintain and update a FSMS providing products and services that are safe, in accordance with their intended use</div>'),
    ('84f1b424-81db-4374-b39b-f604a42fc370', '5f679b1b-9ab8-4edf-b705-cfdfdbaaa663', 'es', '', '<div>a) planificar, implementar, operar, mantener y actualizar un SGIA que proporcione productos y servicios que sean inocuos, de acuerdo con su uso previsto </div>'),
    ('cd60381a-bb66-4f4a-94fe-432ac125cf8e', '5e679988-128f-4e94-bbf1-33d2daaaa4d0', 'en', '', '<div>b) to demonstrate compliance with applicable statutory and regulatory food safety requirements</div>'),
    ('b2600d99-c150-4551-9dbb-f075ae25b1a5', '5e679988-128f-4e94-bbf1-33d2daaaa4d0', 'es', '', '<div>b) demostrar cumplimiento con los requisitos legales y reglamentarios de inocuidad de los alimentos aplicables </div>'),
    ('979124c5-30d5-426d-b063-739935b5a991', '6567a48d-e9a0-47e5-a0d4-03b9e1aaafd5', 'en', '', '<div>c) to evaluate and assess mutually agreed customer food safety requirements and to demonstrate conformity with them</div>'),
    ('aa9142ae-62ce-417e-a135-635640b5bae2', '6567a48d-e9a0-47e5-a0d4-03b9e1aaafd5', 'es', '', '<div>c) valorar y evaluar los requisitos de inocuidad alimentaria mutuamente acordados con los clientes y demostrar su conformidad con ellos </div>'),
    ('fe1dea24-4ca2-4d74-9e6e-0b849cb93040', '6467a2fa-968e-427a-9a9f-f23ce0aaae42', 'en', '', '<div>d) to effectively communicate food safety issues to interested parties within the food chain</div>'),
    ('031df203-e5a2-4123-8e44-24b7b9b95de7', '6467a2fa-968e-427a-9a9f-f23ce0aaae42', 'es', '', '<div>d) comunicar eficazmente los temas de inocuidad de los alimentos a las partes interesadas dentro de la cadena alimentaria</div>'),
    ('3d64636f-b7ae-4af7-8d1e-5bdbee5ae80b', '6367a167-9a06-4e0b-bc67-0e83dfaaacaf', 'en', '', '<div>e) to ensure that the organization conforms to its stated food safety policy</div>'),
    ('30644ef8-315a-4430-9d86-81a0f95af95c', '6367a167-9a06-4e0b-bc67-0e83dfaaacaf', 'es', '', '<div>e) asegurar que la organización cumpla con su polí­tica de inocuidad de los alimentos establecida </div>'),
    ('92904d46-6048-41ce-9539-feee4eb15cc2', '62679fd4-8f2c-4450-adb7-9066deaaab1c', 'en', '', '<div>f) to demonstrate conformity to relevant interested parties</div>'),
    ('af907aed-d40b-445d-9773-1d2143b14b71', '62679fd4-8f2c-4450-adb7-9066deaaab1c', 'es', '', '<div>f) demostrar conformidad con las partes interesadas pertinentes </div>'),
    ('f73397c1-6982-4941-a9db-9dfda03f8cd5', '596791a9-8664-4f71-be61-6cdde5aab621', 'en', '', '<div>g) to seek certification or registration of its FSMS by an external organization, or make a selfassessment or self-declaration of conformity to this document.</div>'),
    ('e23376b2-be8e-421a-847a-5f62933f785e', '596791a9-8664-4f71-be61-6cdde5aab621', 'es', '', '<div>g) buscar la certificación o registro de su SGIA por una organización externa, o realizar una autoevaluación o declaración de sí­ misma de la conformidad con este documento. </div>'),
    ('d36bc930-51b2-4f78-b80a-83180946bb34', '58679016-ab78-4b76-99c9-02a0e4aab48e', 'en', 'Normative references', '<div>There are no normative references in this document.</div>'),
    ('d06bc477-3cee-4a2f-8850-5423ee4690b3', '58679016-ab78-4b76-99c9-02a0e4aab48e', 'es', 'Referencias normativas', '<div>No hay referencias normativas en este documento.</div>'),
    ('c085dcea-c918-4f9a-b24e-839a403f0b5e', '5b655638-2180-4500-bbf8-416257a79800', 'en', 'Terms and definitions', '<div>For the purposes of this document, the following terms and definitions apply.</div><div>ISO and IEC maintain terminological databases for use in standardization at the following addresses:</div><div>— ISO Online browsing platform: available at <a href="https://www.iso.org/obp">https://www.iso.org/obp</a></div><div>— IEC Electropedia: available at <a href="http://www.electropedia.org/">http://www.electropedia.org/</a></div><div>{clause_3.1}</div><div>{clause_3.2}</div><div>{clause_3.3}</div><div>{clause_3.4}</div><div>{clause_3.5}</div><div>{clause_3.6}</div><div>{clause_3.7}</div><div>{clause_3.8}</div><div>{clause_3.9}</div><div>{clause_3.10}</div><div>{clause_3.11}</div><div>{clause_3.12}</div><div>{clause_3.13}</div><div>{clause_3.14}</div><div>{clause_3.15}</div><div>{clause_3.16}</div><div>{clause_3.17}</div><div>{clause_3.18}</div><div>{clause_3.19}</div><div>{clause_3.20}</div><div>{clause_3.21}</div><div>{clause_3.22}</div><div>{clause_3.23}</div><div>{clause_3.24}</div><div>{clause_3.25}</div><div>{clause_3.26}</div><div>{clause_3.27}</div><div>{clause_3.28}</div><div>{clause_3.29}</div><div>{clause_3.30}</div><div>{clause_3.31}</div><div>{clause_3.32}</div><div>{clause_3.33}</div><div>{clause_3.34}</div><div>{clause_3.35}</div><div>{clause_3.36}</div><div>{clause_3.37}</div><div>{clause_3.38}</div><div>{clause_3.39}</div><div>{clause_3.40}</div><div>{clause_3.41}</div><div>{clause_3.42}</div><div>{clause_3.43}</div><div>{clause_3.44}</div><div>{clause_3.45}</div>'),
    ('c585e4c9-740c-46c1-9f0e-ad054d3f1fd5', '5b655638-2180-4500-bbf8-416257a79800', 'es', 'Términos y definiciones', '<div>Para los fines de este documento, se aplican los términos y definiciones siguientes.</div><div>ISO e IEC mantienen bases de datos terminológicas para su utilización en normalización en las siguientes direcciones: </div><div>— Plataforma de búsqueda en lí­nea de ISO: disponible en <a href="https://www.iso.org/obp">https://www.iso.org/obp</a></div><div>— Electropedia de IEC: disponible en <a href="http://www.electropedia.org/">http://www.electropedia.org/</a></div><div>{clause_3.1}</div><div>{clause_3.2}</div><div>{clause_3.3}</div><div>{clause_3.4}</div><div>{clause_3.5}</div><div>{clause_3.6}</div><div>{clause_3.7}</div><div>{clause_3.8}</div><div>{clause_3.9}</div><div>{clause_3.10}</div><div>{clause_3.11}</div><div>{clause_3.12}</div><div>{clause_3.13}</div><div>{clause_3.14}</div><div>{clause_3.15}</div><div>{clause_3.16}</div><div>{clause_3.17}</div><div>{clause_3.18}</div><div>{clause_3.19}</div><div>{clause_3.20}</div><div>{clause_3.21}</div><div>{clause_3.22}</div><div>{clause_3.23}</div><div>{clause_3.24}</div><div>{clause_3.25}</div><div>{clause_3.26}</div><div>{clause_3.27}</div><div>{clause_3.28}</div><div>{clause_3.29}</div><div>{clause_3.30}</div><div>{clause_3.31}</div><div>{clause_3.32}</div><div>{clause_3.33}</div><div>{clause_3.34}</div><div>{clause_3.35}</div><div>{clause_3.36}</div><div>{clause_3.37}</div><div>{clause_3.38}</div><div>{clause_3.39}</div><div>{clause_3.40}</div><div>{clause_3.41}</div><div>{clause_3.42}</div><div>{clause_3.43}</div><div>{clause_3.44}</div><div>{clause_3.45}</div>'),
    ('f10ed713-51eb-40b3-a5ce-b9e7ea7550c7', '5c6557cb-2c5d-41bb-b305-4e6f58a79993', 'en', 'acceptable level', '<div>level of a food safety hazard (3.22) not to be exceeded in the end product (3.15) provided by the organization (3.31).</div>'),
    ('0c0f0194-5f44-4f64-8856-0754cd752320', '5c6557cb-2c5d-41bb-b305-4e6f58a79993', 'es', 'nivel aceptable', '<div>nivel de un peligro relacionado con la inocuidad de los alimentos (3.22) que no se debe exceder en el producto terminado (3.15) proporcionado por la organización (3.31).</div>'),
    ('4c13ac28-6aea-4660-9f8a-bfb0cbccda9c', '5d65595e-2845-426a-a200-d71859a79b26', 'en', 'action criterion', '<div>measurable or observable specification for the monitoring (3.27) of an OPRP (3.30) Note 1 to entry:</div><div>An action criterion is established to determine whether an OPRP remains in control, and distinguishes between what is acceptable (criterion met or achieved means the OPRP is operating as intended) and unacceptable (criterion not met nor achieved means the OPRP is not operating as intended).</div>'),
    ('39138e3f-6432-4fc7-8d21-af8bc0ccc94b', '5d65595e-2845-426a-a200-d71859a79b26', 'es', 'criterio de acción', '<div>especificación medible u observable para el seguimiento (3.27) de un PPRO (3.30).</div><div>Nota 1 a la entrada: Un criterio de acción se establece para determinar si un PPRO permanece bajo control, y distingue entre lo que es aceptable (que el criterio cumpla o logre significa que el PPRO está operando como está previsto) e inaceptable (que el criterio no se cumple ni se logre significa que el PPRO no está operando como está previsto).</div>'),
    ('c5af56d9-9ed6-4649-9b7e-3735453fe2dd', '5e655af1-7bf7-4b95-bd6f-fbb55aa79cb9', 'en', 'audit', '<div>systematic, independent and documented process (3.36) for obtaining audit evidence and evaluating it objectively to determine the extent to which the audit criteria are fulfilled.</div><div>Note 1 to entry: An audit can be an internal audit (first party) or an external audit (second party or third party), and it can be a combined audit (combining two or more disciplines).</div><div>Note 2 to entry: An internal audit is conducted by the organization itself, or by an external party on its behalf.</div><div>Note 3 to entry: “Audit evidence” and “audit criteria” are defined in ISO 19011.</div><div>Note 4 to entry: Relevant disciplines are, for example, food safety management, quality management or environmental management.</div>'),
    ('e0af815a-af00-4952-ada6-56ea483fe796', '5e655af1-7bf7-4b95-bd6f-fbb55aa79cb9', 'es', 'auditorí­a', '<div>proceso (3.36) sistemático, independiente y documentado para obtener evidencia de auditorí­a y evaluarla objetivamente para determinar el grado en el que se cumplen los criterios de auditorí­a.</div><div>Nota 1 a la entrada: Una auditorí­a puede ser interna (de primera parte), o externa (de segunda o tercera parte), y puede ser una auditorí­a combinada (combinando dos o más disciplinas).</div><div>Nota 2 a la entrada: Una auditorí­a interna es realizada por la propia organización, o por una parte externa en su nombre.</div><div>Nota 3 a la entrada: “Evidencia de auditoría” y “criterio de auditoría” se definen en la Norma ISO 19011.</div><div>Nota 4 a la entrada: Disciplinas pertinentes son, por ejemplo, gestión de la inocuidad de los alimentos, gestión de la calidad o gestión ambiental.</div>'),
    ('c6542796-b32b-449e-8bd9-85de58945ad2', '5f655c84-a4e5-4244-b7de-98b65ba79e4c', 'en', 'competence', '<div>ability to apply knowledge and skills to achieve intended results.</div>'),
    ('c35422dd-8132-458d-b2b5-01316d947be1', '5f655c84-a4e5-4244-b7de-98b65ba79e4c', 'es', 'competencia', '<div>capacidad para aplicar conocimientos y habilidades para lograr los resultados previstos.</div>'),
    ('3304713f-d54e-45c7-9daa-b98baafa1f9b', '60655e17-2d0e-428f-b260-65d35ca79fdf', 'en', 'conformity', '<div>fulfilment of a requirement (3.38).</div>'),
    ('46048f28-dc06-4c60-b013-c9b095f9fe8c', '60655e17-2d0e-428f-b260-65d35ca79fdf', 'es', 'conformidad', '<div>cumplimiento de un requisito (3.38).</div>'),
    ('33be5cb4-d787-4544-abe3-8174e5fec250', '61655faa-9baa-467e-9196-7fcc5da7a172', 'en', 'contamination', '<div>introduction or occurrence of a contaminant including a food safety hazard (3.22) in a product (3.37) or processing environment.</div>'),
    ('18be3233-c7b2-4a93-86e1-6b87e2febd97', '61655faa-9baa-467e-9196-7fcc5da7a172', 'es', 'contaminación', '<div>introducción o incidencia de un contaminante incluyendo un peligro relacionado con la inocuidad de los alimentos (3.22) en un producto (3.37) o ambiente de elaboración.</div>'),
    ('cab72e55-f785-473d-8a49-10497f990c61', '6265613d-a24e-43b9-97e6-8fc95ea7a305', 'en', 'continual improvement', '<div>recurring activity to enhance performance (3.33).</div>'),
    ('bdb719de-6da2-4c2e-b955-83e66a98eb52', '6265613d-a24e-43b9-97e6-8fc95ea7a305', 'es', 'mejora continua', '<div>actividad recurrente para mejorar el desempeño (3.33).</div>'),
    ('7928fe42-f844-40e2-ad40-7c12a521b366', '536549a0-1097-4488-83f7-40ba5fa7a498', 'en', 'control measure', '<div>action or activity that is essential to prevent a significant food safety hazard (3.22) or reduce it to an acceptable level (3.1).</div><div>Note 1 to entry: See also significant food safety hazard (3.40).</div><div>Note 2 to entry: Control measure(s) is (are) identified by hazard analysis.</div>'),
    ('6e28ecf1-8b46-43b9-a585-520dc221e10d', '536549a0-1097-4488-83f7-40ba5fa7a498', 'es', 'medida de control', '<div>acción o actividad que es esencial para prevenir un peligro relacionado con la inocuidad de los alimentos (3.22) significativo o reducirlo a un nivel aceptable (3.1).</div><div>Nota 1 a la entrada: Véase también la definición de peligro significativo relacionado con la inocuidad de los alimentos (3.40).</div><div>Nota 2 a la entrada: Las medidas de control están identificadas por el análisis de peligros.</div>'),
    ('18d2898b-c450-473b-9534-1ddfc5c9d80f', '54654b33-7f9a-4f43-a215-f22760a7a62b', 'en', 'correction', '<div>action to eliminate a detected nonconformity (3.28).</div><div>Note 1 to entry: A correction includes the handling of potentially unsafe products and can therefore be made in conjunction with a corrective action (3.10).</div><div>Note 2 to entry: A correction may be, for example, reprocessing, further processing and/or elimination of the adverse consequences of the nonconformity (such as disposal for other use or specific labelling).</div>'),
    ('23d29adc-2165-4d3c-9c2a-f25cb8c9c398', '54654b33-7f9a-4f43-a215-f22760a7a62b', 'es', 'corrección', '<div>acción para eliminar una no conformidad (3.28) detectada.</div><div>Nota 1 a la entrada: Una corrección incluye la manipulación de productos potencialmente no inocuos, y por lo tanto puede efectuarse conjuntamente con una acción correctiva (3.10).</div><div>Nota 2 a la entrada: Una corrección puede ser, por ejemplo, reproceso, procesamiento posterior, y/o eliminación de las consecuencias adversas de la no conformidad (por ejemplo la disposición para otro uso o un etiquetado especí­fico).</div>'),
    ('28ab73d7-7f49-497b-b461-f5039ebd952b', 'cd6cc573-a76f-4083-bace-8e4be9af399b', 'en', 'corrective action', '<div>action to eliminate the cause of a nonconformity (3.28) and to prevent recurrence.</div><div>Note 1 to entry: There can be more than one cause for a nonconformity.</div><div>Note 2 to entry: Corrective action includes cause analysis.</div>'),
    ('2bab7890-ded7-457c-be8c-6bf8a9bda67c', 'cd6cc573-a76f-4083-bace-8e4be9af399b', 'es', 'acción correctiva', '<div>acción para eliminar la causa de una no conformidad (3.28) y para prevenir la recurrencia.</div><div>Nota 1 a la entrada: Puede haber más de una causa para una no conformidad.</div><div>Nota 2 a la entrada: La acción correctiva incluye el análisis de las causas.</div>'),
    ('4b1bedae-5d44-4722-bcac-c9d68e34cd62', 'cc6cc3e0-1f1e-4dc8-bd55-eacee8af3808', 'en', 'critical control point. CCP', '<div>step in the process (3.36) at which control measure(s) (3.8) is (are) applied to prevent or reduce a significant food safety hazard (3.40) to an acceptable level, and defined critical limit(s) (3.12) and measurement (3.26) enable the application of corrections (3.9).</div>'),
    ('381bcfc5-0994-41f9-8bda-da198334bc11', 'cc6cc3e0-1f1e-4dc8-bd55-eacee8af3808', 'es', 'punto crí­tico de control. PCC', '<div>etapa en el proceso (3.36) en la que se aplican las medidas de control (3.8) para prevenir o reducir un peligro significativo relacionado con la inocuidad de los alimentos (3.40) hasta un nivel aceptable, y lí­mites crí­ticos (3.12) definidos y la medición (3.26) permite la aplicación de correcciones (3.9).</div>'),
    ('4f7ef46d-ee9b-4051-9dc1-17a172beb131', 'cf6cc899-6550-411d-a0df-5001ebaf3cc1', 'en', 'critical limit', '<div>measurable value which separates acceptability from unacceptability.</div><div>Note 1 to entry: Critical limits are established to determine whether a CCP (3.11) remains in control. If a critical limit is exceeded or not met, the products affected are to be handled as potentially unsafe products.</div><div>[SOURCE: CAC/RCP 1‑1969, modified — The definition has been modified and Note 1 to entry has been added].</div>'),
    ('327ec6c6-e8b1-4a4a-9b87-f96e7dbec282', 'cf6cc899-6550-411d-a0df-5001ebaf3cc1', 'es', 'lí­mite crí­tico', '<div>valor medible que diferencia la aceptabilidad de la inaceptabilidad.</div><div>Nota 1 a la entrada: Los lí­mites crí­ticos se establecen para determinar si un PCC (3.11) permanece bajo control. Si se excede o no se cumple un lí­mite crí­tico, los productos afectados se manipulan como productos potencialmente no inocuos.</div><div>[FUENTE: CAC/RCP 1-1969, modificado — La definición ha sido modificada y se ha agregado la Nota 1 a la entrada].</div>'),
    ('960b876c-c6fd-4708-ae5f-920cd9c237e0', 'ce6cc706-f23d-4952-9b3d-d4a4eaaf3b2e', 'en', 'documented information', '<div>information required to be controlled and maintained by an organization (3.31) and the medium on which it is contained.</div><div>Note 1 to entry: Documented information can be in any format and media, and from any source. Note 2 to entry: Documented information can refer to:</div><div>— the management system (3.25), including related processes (3.36)</div><div>— information created in order for the organization to operate (documentation)</div><div>— evidence of results achieved (records).</div>'),
    ('ab0ba87b-0f0a-45df-bb02-12aff6c26587', 'ce6cc706-f23d-4952-9b3d-d4a4eaaf3b2e', 'es', 'información documentada', '<div>información requerida para ser controlada y mantenida por una organización (3.31) y el medio en el cual está contenida.</div><div>Nota 1 a la entrada: La información documentada puede estar en cualquier formato y medio, y que provenga de cualquier fuente.</div><div>Nota 2 a la entrada: La información documentada puede referirse a:</div><div>— el sistema de gestión (3.25), incluidos los procesos (3.36) relacionados</div><div>— información creada para que la organización funcione (documentación)</div><div>— evidencia de los resultados logrados (registros).</div>'),
    ('75d69d2b-29e2-4d8f-9b65-2c7f51926bd7', 'd16ccbbf-148c-42d7-95e1-2f87edaf3fe7', 'en', 'effectiveness', '<div>extent to which planned activities are realized and planned results achieved.</div>'),
    ('80d6ae7c-3900-4058-b2d7-40fc54927090', 'd16ccbbf-148c-42d7-95e1-2f87edaf3fe7', 'es', 'eficacia', '<div>medida en que se realizan las actividades planificadas y se logran los resultados planificados.</div>'),
    ('654dd562-4d89-4d26-97a5-d1327402e5ae', 'd06cca2c-845f-40ec-be07-db1aecaf3e54', 'en', 'end product', '<div>product (3.37) that will undergo no further processing or transformation by the organization (3.31).</div><div>Note 1 to entry: A product that undergoes further processing or transformation by another organization is an end product in the context of the first organization and a raw material or an ingredient in the context of the second organization.</div>'),
    ('5a4dc411-b9c3-4665-9e40-a1ad6102c7c5', 'd06cca2c-845f-40ec-be07-db1aecaf3e54', 'es', 'producto terminado', '<div>producto (3.37) que no se someterá a procesamiento o transformación posterior por parte de la organización (3.31).</div><div>Nota 1 a la entrada: Un producto que es sometido a un procesamiento o transformación posterior por otra organización, es un producto terminado, en el contexto de la primera organización, y una materia prima o un ingrediente, en el contexto de la segunda organización.</div>'),
    ('49d7b931-84bb-49c5-a33e-044d7865ec6d', 'd36ccee5-2742-4c61-bb43-2ccdefaf430d', 'en', 'feed', '<div>single or multiple product(s), whether processed, semi-processed or raw, which is (are) intended to be fed to food-producing animals.</div><div>Note 1 to entry: Distinctions are made in this document between the terms food (3.18), feed (3.16) and animal food (3.19):</div><div>— food is intended for consumption by humans and animals, and includes feed and animal food</div><div>— feed is intended to be fed to food-producing animals</div><div>— animal food is intended to be fed to non-food-producing animals, such as pets.</div><div>[SOURCE: CAC/GL 81‑2013, modified — The word “materials” has been changed to “products” and “directly” has been deleted].</div>'),
    ('54d7ca82-47ee-4e06-814e-fe525b65bec6', 'd36ccee5-2742-4c61-bb43-2ccdefaf430d', 'es', 'alimento para animales productores de alimentos', '<div>productos simples o compuestos, ya sean procesados, semi-procesados o crudos, que se destinan para la alimentación de animales productores de alimentos.</div><div>Nota 1 a la entrada: En este documento se hacen distinciones entre los términos alimento (3.18), alimento para animales productores de alimentos (3.16) y alimento para animales (3.19):</div><div>— el alimento se destina para consumo humano y animal, e incluye alimento para animales productores de alimentos, y alimento para animales</div><div>— el alimento para animales productores de alimentos se destina para la alimentación de animales productores de alimentos</div><div>— el alimento para animales se destina para la alimentación de animales que no producen alimentos, tales como mascotas.</div><div>[FUENTE: CAC/GL 81-2013, modificado — El término “materiales” se ha cambiado a “productos” y “directamente” ha sido eliminado].</div>'),
    ('b0db3fe0-6939-43cc-88ed-e728bef27f6c', 'd26ccd52-65a2-4d66-a2ba-5110eeaf417a', 'en', 'flow diagram', '<div>schematic and systematic presentation of the sequence and interactions of steps in the process.</div>'),
    ('cddb6d87-6996-48ab-b3f3-6d13d3f2a07b', 'd26ccd52-65a2-4d66-a2ba-5110eeaf417a', 'es', 'diagrama de flujo', '<div>presentación esquemática y sistemática de la secuencia e interacciones de las etapas en el proceso.</div>'),
    ('900884df-d037-4bf3-9404-272b03a1d033', 'd56cd20b-3ae5-4dfb-9ab0-1e33e1af2d03', 'en', 'food', '<div>substance (ingredient), whether processed, semi-processed or raw, which is intended for consumption, and includes drink, chewing gum and any substance which has been used in the manufacture, preparation or treatment of “food” but does not include cosmetics or tobacco or substances (ingredients) used only as drugs.</div><div>Note 1 to entry: Distinctions are made in this document between the terms food (3.18), feed (3.16) and animal food (3.19):</div><div>— food is intended for consumption by humans and animals, and includes feed and animal food</div><div>— feed is intended to be fed to food-producing animals</div><div>— animal food is intended to be fed to non-food-producing animals, such as pets.</div><div>[SOURCE: CAC/GL 81‑2013, modified — The word “human” has been deleted].</div>'),
    ('a308a2c8-c445-48a4-8b73-d9501ea1fab4', 'd56cd20b-3ae5-4dfb-9ab0-1e33e1af2d03', 'es', 'alimento', '<div>sustancia (ingrediente), ya sea procesada, semi-procesada o cruda, que se destina para consumo, e incluye bebidas, goma de mascar y cualquier sustancia que se haya utilizado en la fabricación, preparación o tratamiento de "alimentos", pero no incluye cosméticos ni tabaco o sustancias (ingredientes) usados solamente como fármacos.</div><div>Nota 1 a la entrada: En este documento se hacen distinciones entre los términos alimento (3.18), alimento para animales productores de alimentos (3.16) y alimento para animales (3.19): </div><div>— el alimento se destina para consumo humano y animal, e incluye alimento para animales productores de alimentos, y alimento para animales</div><div>— el alimento para animales productores de alimentos se destina para la alimentación de animales productores de alimentos</div><div>— el alimento para animales se destina para la alimentación de animales que no producen alimentos, tales como mascotas.</div><div>[FUENTE: CAC/GL 81-2013, modificado — El término “humano” ha sido eliminado].</div>'),
    ('affe95b6-868b-4ada-9a50-cefed317430a', 'd46cd078-4955-4640-843a-3c96e0af2b70', 'en', 'animal food', '<div>single or multiple product(s), whether processed, semi-processed or raw, which is (are) intended to be fed to non-food-producing animals.</div><div>Note 1 to entry: Distinctions are made in this document between the terms food (3.18), feed (3.16) and animal food (3.19):</div><div>— food is intended for consumption by humans and animals, and includes feed and animal food</div><div>— feed is intended to be fed to food-producing animals</div><div>— animal food is intended to be fed to non-food-producing animals, such as pets.</div><div>[SOURCE: CAC/GL 81‑2013, modified — The word “materials” has been changed to “products”, “non” has been added and “directly” has been deleted].</div>'),
    ('acfe90fd-4acb-4401-a882-e0d1d8174ae9', 'd46cd078-4955-4640-843a-3c96e0af2b70', 'es', 'alimento para animales', '<div>productos simples o compuestos, ya sean procesados, semi-procesados o crudos, que se destinan para la alimentación de animales que no producen alimentos.</div><div>Nota 1 a la entrada: En este documento se hacen distinciones entre los términos alimento (3.18), alimento para animales productores de alimentos (3.16) y alimento para animales (3.19):</div><div>— el alimento se destina para consumo humano y animal, e incluye alimento para animales productores de alimentos, y alimento para animales</div><div>— el alimento para animales productores de alimentos se destina para la alimentación de animales productores de alimentos</div><div>— el alimento para animales se destina para la alimentación de animales que no producen alimentos, tales como mascotas.</div><div>[FUENTE: CAC/GL 81-2013, modificado — El término “materiales” ha sido cambiado por “productos”, “no” ha sido incluido y “directamente” ha sido eliminado].</div>'),
    ('575aeef0-ce3c-4f64-aafd-e9d8ad6cdde4', '6769e64a-979b-4bc2-8b67-20e0e3acf192', 'en', 'food chain', '<div>sequence of the stages in the production, processing, distribution, storage and handling of a food (3.18) and its ingredients, from primary production to consumption.</div><div>Note 1 to entry: This includes the production of feed (3.16) and animal food (3.19).</div><div>Note 2 to entry: The food chain also includes the production of materials intended to come into contact with food or raw materials.</div><div>Note 3 to entry: The food chain also includes service providers.</div>'),
    ('545aea37-c0e3-40b3-b764-29e3b26ce5c3', '6769e64a-979b-4bc2-8b67-20e0e3acf192', 'es', 'cadena alimentaria', '<div>secuencia de etapas en la producción, procesamiento, distribución, almacenamiento, y manipulación de un alimento (3.18) y sus ingredientes, desde la producción primaria hasta el consumo.</div><div>Nota 1 a la entrada: Esto incluye la producción de alimento para animales productores de alimentos (3.16) y alimento para animales (3.19).</div><div>Nota 2 a la entrada: La cadena alimentaria incluye la producción de materiales destinados a entrar en contacto con alimentos o materias primas.</div><div>Nota 3 a la entrada: La cadena alimentaria también incluye proveedores de servicio.</div>'),
    ('7d9b9381-296a-42dd-b2cc-5bbd4465af85', '6869e7dd-dbdf-46cd-af35-cd1de4acf325', 'en', 'food safety', '<div>assurance that food will not cause an adverse health effect for the consumer when it is prepared and/or consumed in accordance with its intended use.</div><div>Note 1 to entry: Food safety is related to the occurrence of food safety hazards (3.22) in end products (3.15) and does not include other health aspects related to, for example, malnutrition.</div><div>Note 2 to entry: It is not to be confused with the availability of, and access to, food (“food security”).</div><div>Note 3 to entry: This includes feed and animal food.</div><div>[SOURCE: CAC/RCP 1‑1969, modified — The word “harm” has been changed to “adverse health effect” and notes to entry have been added].</div>'),
    ('689b7272-b5a7-404e-8ab5-51225765cd6e', '6869e7dd-dbdf-46cd-af35-cd1de4acf325', 'es', 'inocuidad de los alimentos', '<div>seguridad que el alimento no causará un efecto adverso en la salud para el consumidor cuando se prepara y/o se consume de acuerdo con su uso previsto.</div><div>Nota 1 a la entrada: La inocuidad de los alimentos se relaciona con la ocurrencia de peligros relacionados con la inocuidad de los alimentos (3.22) en el producto terminado (3.15) y no incluye otros aspectos de salud relacionados con, por ejemplo, la desnutrición.</div><div>Nota 2 a la entrada: No se debe confundir con la disponibilidad de y acceso a, los alimentos (“seguridad alimentaria”).</div><div>Nota 3 a la entrada: Incluye alimento para animales productores de alimentos y alimento para animales.</div><div>[FUENTE: CAC/RCP 1-1969, modificado — El término “daño” ha sido cambiado por “efecto adverso en la salud” y notas al texto han sido incluidas].</div>'),
    ('59114af2-0fec-433e-8c98-5da23f64d806', '6569e324-b0d6-40b8-9046-322ae1acee6c', 'en', 'food safety hazard', '<div>biological, chemical or physical agent in food (3.18) with the potential to cause an adverse health effect.</div><div>Note 1 to entry: The term “hazard” is not to be confused with the term “risk” (3.39) which, in the context of food safety, means a function of the probability of an adverse health effect (e.g. becoming diseased) and the severity of that effect (e.g. death, hospitalization) when exposed to a specified hazard.</div><div>Note 2 to entry: Food safety hazards include allergens and radiological substances.</div><div>Note 3 to entry: In the context of feed and feed ingredients, relevant food safety hazards are those that can be present in and/or on feed and feed ingredients and that can through animal consumption of feed be transferred to food and can thus have the potential to cause an adverse health effect for the animal or the human consumer. In the context of operations other than those directly handling feed and food (e.g. producers of packaging materials, disinfectants), relevant food safety hazards are those hazards that can be directly or indirectly transferred to food when used as intended (see 8.5.1.4).</div><div>Note 4 to entry: In the context of animal food, relevant food safety hazards are those that are hazardous to the animal species for which the food is intended.</div><div>[SOURCE: CAC/RCP 1‑1969, modified — The phrase “or condition of” has been deleted from the definition and notes to entry have been added].</div>'),
    ('6e116c01-f740-492d-b4af-683d5c6505ad', '6569e324-b0d6-40b8-9046-322ae1acee6c', 'es', 'peligro relacionado con la inocuidad de los alimentos', '<div>agente biológico, quí­mico o fí­sico en el alimento (3.18) con potencial de causar un efecto adverso en la salud.</div><div>Nota 1 a la entrada: El término “peligro” no se debe confundir con el término “riesgo” (3.39) el cual, en el contexto de la inocuidad de los alimentos, significa una función de la probabilidad de un efecto adverso en la salud (por ejemplo, enfermar) y la gravedad de ese efecto (por ejemplo, muerte, hospitalización) cuando se expone a un peligro especificado.</div><div>Nota 2 a la entrada: Peligros para la inocuidad de los alimentos incluye alérgenos y sustancias radiológicas.</div><div>Nota 3 a la entrada: En el contexto de los alimentos para animales productores de alimentos e ingredientes para los alimentos de animales productores de alimentos, los peligros pertinentes relacionados con la inocuidad de los alimentos son aquellos que pueden estar presentes en y/o sobre los alimentos para animales productores de alimentos e ingredientes para los alimentos de animales productores de alimentos y que pueden ser transferidos a los alimentos a través del consumo animal del alimento para animales productores de alimentos y que pueden causar un efecto adverso a la salud del animal o del consumidor. En el contexto de las operaciones, distintas a la manipulación directa de alimentos y de los alimentos para los animales productores de alimentos (por ejemplo, productores de materiales de envase y embalaje, desinfectantes, entre otros), los peligros pertinentes relacionados con la inocuidad de los alimentos son aquellos peligros que pueden directa o indirectamente transferirse al alimento cuando se utiliza según lo previsto (véase 8.5.1.4).</div><div>Nota 4 a la entrada: En el contexto de alimento para animales, peligros pertinentes relacionados con la inocuidad de los alimentos, son aquellos que son peligrosos para las especies animales para las que el alimento se ha destinado.</div><div>[FUENTE: CAC/RCP 1-1969, modificado — La frase “o condición de” se ha eliminado de la definición y se han incluido notas al texto].</div>'),
    ('a8fca6bb-c338-4ee7-91b6-026fecb4ea2f', '6669e4b7-3926-4073-af3b-a997e2acefff', 'en', 'interested party (preferred term). stakeholder (admitted term)', '<div>person or organization (3.31) that can affect, be affected by, or perceive itself to be affected by a decision or activity.</div>'),
    ('93fc85ac-cc6a-4e80-b984-19ccdfb4d5b8', '6669e4b7-3926-4073-af3b-a997e2acefff', 'es', 'parte interesada', '<div>persona u organización (3.31) que puede afectar, verse afectada o percibirse como afectada por una decisión o actividad.</div><div>Nota: a la versión en español: Los términos en inglés "interested party" y "stakeholder" tienen una traducción única al español como "parte interesada".</div>'),
    ('3d29073c-5b4e-4880-850f-353cc79ec598', '6369dffe-0afe-4cd6-a21d-0bf4dfaceb46', 'en', 'lot', '<div>defined quantity of a product (3.37) produced and/or processed and/or packaged essentially under the same conditions.</div><div>Note 1 to entry: The lot is determined by parameters established beforehand by the organization and may be described by other terms, e.g. batch.</div><div>Note 2 to entry: The lot may be reduced to a single unit of product.</div><div>[SOURCE: CODEX STAN 1, modified — Reference to “and/or processed and/or packaged” has been included in the definition and notes to entry have been added].</div>'),
    ('3228f5eb-521c-48e7-a7b6-39bfd49eda0f', '6369dffe-0afe-4cd6-a21d-0bf4dfaceb46', 'es', 'lote', '<div>cantidad definida de un producto (3.37) producido y/o procesado y/o envasado/embalado bajo las mismas condiciones esencialmente.</div><div>Nota 1 a la entrada: El lote está determinado por los parámetros establecidos previamente por la organización y puede describirse por otros términos, por ejemplo, batch.</div><div>Nota 2 a la entrada: El lote se puede reducir a una sola unidad de producto.</div><div>[FUENTE: CODEX STAN 1, modificado — La referencia "y/o procesado y/o envasado/embalado" en la definición se ha incluido y se han incluido notas al texto].</div>'),
    ('434269fd-2646-4269-ab89-9e517ec06c09', '6469e191-b8f8-4c51-98f7-f551e0acecd9', 'en', 'management system', '<div>set of interrelated or interacting elements of an organization (3.31) to establish policies (3.34) and objectives (3.29) and processes (3.36) to achieve those objectives.</div><div>Note 1 to entry: A management system can address a single discipline or several disciplines.</div><div>Note 2 to entry: The system elements include the organization''s structure, roles and responsibilities, planning and operation.</div><div>Note 3 to entry: The scope of a management system may include the whole of the organization, specific and identified functions of the organization, specific and identified sections of the organization, or one or more functions across a group of organizations.</div><div>Note 4 to entry: Relevant disciplines are, for example, a quality management system or an environmental management system.</div>'),
    ('46426eb6-4fbc-4a72-9d57-8c7e79c0642a', '6469e191-b8f8-4c51-98f7-f551e0acecd9', 'es', 'sistema de gestión', '<div>conjunto de elementos de una organización (3.31) interrelacionados o que interactúan para establecer polí­ticas (3.34), objetivos (3.29) y procesos (3.36) para lograr estos objetivos.</div><div>Nota 1 a la entrada: Un sistema de gestión puede abarcar una sola disciplina o varias disciplinas.</div><div>Nota 2 a la entrada: Los elementos del sistema incluyen la estructura de la organización, los roles y las responsabilidades, la planificación y la operación.</div><div>Nota 3 a la entrada: El alcance de un sistema de gestión puede incluir la totalidad de la organización, funciones especí­ficas e identificadas de la organización, secciones especí­ficas e identificadas de la organización, o una o más funciones dentro de un grupo de organizaciones.</div><div>Nota 4 a la entrada: Disciplinas pertinentes son, por ejemplo, un sistema de gestión de la calidad o un sistema de gestión ambiental.</div>'),
    ('3e41927e-c247-42ba-8d2b-d6867a3655da', '6169dcd8-143b-4b9c-ba76-23deddace820', 'en', 'measurement', '<div>process (3.36) to determine a value.</div>'),
    ('4b41a6f5-6ac1-40e1-9b83-2b695f362b59', '6169dcd8-143b-4b9c-ba76-23deddace820', 'es', 'medición', '<div>proceso (3.36) para determinar un valor.</div>'),
    ('5e4be667-b1da-4bd3-a77a-87733940afc3', '6269de6b-bc64-4e47-a3a3-7c1bdeace9b3', 'en', 'monitoring', '<div>determining the status of a system, a process (3.36) or an activity.</div><div>Note 1 to entry: To determine the status, there may be a need to check, supervise or critically observe.</div><div>Note 2 to entry: In the context of food safety, monitoring is conducting a planned sequence of observations or measurements to assess whether a process is operating as intended.</div><div>Note 3 to entry: Distinctions are made in this document between the terms validation (3.44), monitoring (3.27) and verification (3.45):</div><div>— validation is applied prior to an activity and provides information about the capability to deliver intended results</div><div>— monitoring is applied during an activity and provides information for action within a specified time frame</div><div>— verification is applied after an activity and provides information for confirmation of conformity.</div>'),
    ('414bb8c0-bf34-4d84-9bad-6c083440a7e4', '6269de6b-bc64-4e47-a3a3-7c1bdeace9b3', 'es', 'seguimiento', '<div>determinación del estado de un sistema, un proceso (3.36) o una actividad.</div><div>Nota 1 a la entrada: Para determinar el estado, puede ser necesario verificar, supervisar u observar crí­ticamente.</div><div>Nota 2 a la entrada: En el contexto de la inocuidad de los alimentos, el seguimiento se lleva a cabo con una secuencia planificada de observaciones o mediciones para evaluar si un proceso está funcionando según lo previsto.</div><div>Nota 3 a la entrada: En este documento se hacen distinciones entre los términos validación (3.44), seguimiento (3.27) y verificación (3.45):</div><div>— la validación se aplica antes de una actividad y proporciona información sobre la capacidad para entregar los resultados previstos</div><div>— el seguimiento se aplica durante una actividad y proporciona información para la acción dentro de un perí­odo especificado de tiempo</div><div>— la verificación se aplica después de una actividad y proporciona información para la confirmación de la conformidad.</div>'),
    ('9eb7cd98-7a47-412c-87c8-7e40660fff3c', '5f69d9b2-c924-425a-8f8b-7508ebacfe2a', 'en', 'nonconformity', '<div>non-fulfilment of a requirement (3.38).</div>'),
    ('abb7e20f-5edd-480b-92a8-927b5b0fedeb', '5f69d9b2-c924-425a-8f8b-7508ebacfe2a', 'es', 'no conformidad', '<div>incumplimiento de un requisito (3.38).</div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('55d97409-a72b-4fa5-a9bb-d6456c2961fd', '6069db45-1c36-47c5-8f98-9165ecacffbd', 'en', 'objective', '<div>result to be achieved.</div><div>Note 1 to entry: An objective can be strategic, tactical, or operational.</div><div>Note 2 to entry: Objectives can relate to different disciplines (such as financial, health and safety, and environmental goals) and can apply at different levels (such as strategic, organization-wide, project, product and process (3.36)).</div><div>Note 3 to entry: An objective can be expressed in other ways, e.g. as an intended outcome, a purpose, an operational criterion, as a FSMS objective, or by the use of other words with similar meaning (e.g. aim, goal, or target).</div><div>Note 4 to entry: In the context of FSMS, objectives are set by the organization, consistent with the food safety policy, to achieve specific results</div>'),
    ('50d96c2a-543e-4b66-84d4-1eda6f2966b6', '6069db45-1c36-47c5-8f98-9165ecacffbd', 'es', 'objetivo', '<div>resultado a lograr.</div><div>Nota 1 a la entrada: Un objetivo puede ser estratégico, táctico u operativo.</div><div>Nota 2 a la entrada: Los objetivos pueden relacionarse con diferentes disciplinas (tales como metas financieras, de salud y seguridad, y ambientales) y pueden aplicarse a diferentes niveles (tales como estratégicos, de toda la organización, proyecto, producto y proceso (3.36)).</div><div>Nota 3 a la entrada: Un objetivo puede expresarse de otras maneras, por ejemplo, como un resultado previsto, un propósito, un criterio operativo, como un objetivo del SGIA, o mediante el uso de otras palabras con un significado similar (por ejemplo, fin, objetivo o meta).</div><div>Nota 4 a la entrada: En el contexto de los SGIA, la organización establece los objetivos, consistente con la polí­tica de inocuidad de los alimentos, para lograr resultados especí­ficos.</div>'),
    ('e58caefd-ccbf-4de5-890c-6b517283e199', 'd9715585-ff27-4035-91f0-ca5175b4932d', 'en', 'operational prerequisite programme. OPRP', '<div>control measure (3.8) or combination of control measures applied to prevent or reduce a significant food safety hazard (3.40) to an acceptable level (3.1), and where action criterion (3.2) and measurement (3.26) or observation enable effective control of the process (3.36) and/or product (3.37).</div>'),
    ('e88cb3b6-6086-44a6-bada-597e8d840c1a', 'd9715585-ff27-4035-91f0-ca5175b4932d', 'es', 'programa de prerrequisito operativo. PPRO', '<div>medida de control (3.8) o combinación de medidas de control aplicadas para prevenir o reducir un peligro significativo relacionado con la inocuidad de los alimentos (3.40) a un nivel aceptable (3.1), y donde el criterio de acción (3.2) y medición (3.26) u observación permite el control efectivo del proceso (3.36) y/o producto (3.37).</div>'),
    ('df734c3c-37bb-4c6c-a292-023cfb6432e8', 'd87153f2-dae2-448a-9b15-e0f474b4919a', 'en', 'organization', '<div>person or group of people that has its own functions with responsibilities, authorities and relationships to achieve its objectives (3.29).</div><div>Note 1 to entry: The concept of organization includes, but is not limited to sole-trader, company, corporation, firm, enterprise, authority, partnership, charity or institution, or part or combination thereof, whether incorporated or not, public or private.</div>'),
    ('d4733aeb-1c51-434b-8539-06bfe86414ff', 'd87153f2-dae2-448a-9b15-e0f474b4919a', 'es', 'organización', '<div>persona o grupo de personas que tienen sus propias funciones con responsabilidades, autoridades y relaciones para lograr sus objetivos (3.29).</div><div>Nota 1 a la entrada: El concepto de organización incluye, pero no se limita a, un operador individual, compañí­a, corporación, firma, empresa, autoridad, sociedad, institución benéfica o con otros fines, o parte o combinación de los mismos, ya sea incorporada o no, pública o privada.</div>'),
    ('00962b67-b153-4caf-84fd-5473a05f5dd3', 'd771525f-c5ad-4edb-9c9c-511b73b49007', 'en', 'outsource, verb', '<div>make an arrangement where an external organization (3.31) performs part of an organization’s function or process (3.36).</div><div>Note 1 to entry: An external organization is outside the scope of the management system (3.25), although the outsourced function or process is within the scope.</div>'),
    ('e395fdc0-c618-41f8-b930-3908bb5f8854', 'd771525f-c5ad-4edb-9c9c-511b73b49007', 'es', 'contratar externamente', '<div>establecer un acuerdo mediante el cual una organización (3.31) externa realiza parte de una función o proceso (3.36) de una organización.</div><div>Nota 1 a la entrada: Una organización externa está fuera del alcance del sistema de gestión (3.25), aunque la función o el proceso subcontratado está dentro del alcance.</div>'),
    ('e08bd77e-443f-4a46-aaae-a3866d5bfaaa', 'd67150cc-d41f-4a20-b36e-f8de72b48e74', 'en', 'performance', '<div>measurable result.</div><div>Note 1 to entry: Performance can relate either to quantitative or qualitative findings.</div><div>Note 2 to entry: Performance can relate to the management of activities, processes (3.36), products (3.37) (including services), systems or organizations (3.31).</div>'),
    ('ed8bebf5-8386-4c05-b905-f869725c0289', 'd67150cc-d41f-4a20-b36e-f8de72b48e74', 'es', 'desempeño', '<div>resultado medible.</div><div>Nota 1 a la entrada: El desempeño se puede relacionar con hallazgos cuantitativos o cualitativos.</div><div>Nota 2 a la entrada: El desempeño se puede relacionar con la gestión de actividades, procesos (3.36), productos (3.37) (incluyendo servicios), sistemas u organizaciones (3.31).</div>'),
    ('1fe5d881-0bf2-49f1-904f-28bd7a062215', 'd5714f39-3ecd-4059-a82e-a21d71b48ce1', 'en', 'policy', '<div>intentions and direction of an organization (3.31) as formally expressed by its top management (3.41).</div>'),
    ('0ae5b772-efe7-486a-a838-1e226d060d9e', 'd5714f39-3ecd-4059-a82e-a21d71b48ce1', 'es', 'polí­tica', '<div>intenciones y dirección de una organización (3.31) como las expresa formalmente su alta dirección (3.41).</div>'),
    ('f9a533f0-26ec-4228-8880-b6d8e092e774', 'd4714da6-3827-401e-845f-f5e070b48b4e', 'en', 'prerequisite programme. PRP', '<div>basic conditions and activities that are necessary within the organization (3.31) and throughout the food chain (3.20) to maintain food safety.</div><div>Note 1 to entry: The PRPs needed depend on the segment of the food chain in which the organization operates and the type of organization. Examples of equivalent terms are: good agricultural practice (GAP), good veterinary practice (GVP), good manufacturing practice (GMP), good hygiene practice (GHP), good production practice (GPP), good distribution practice (GDP) and good trading practice (GTP).</div>'),
    ('f6a52f37-6efa-43ff-94e6-f6e3c592bcf3', 'd4714da6-3827-401e-845f-f5e070b48b4e', 'es', 'programa de prerrequisito. PPR', '<div>condiciones y actividades básicas que son necesarias dentro de la organización (3.31) y a lo largo de la cadena alimentaria (3.20) para mantener la inocuidad de los alimentos.</div><div>Nota 1 a la entrada: Los PPR necesarios dependen del segmento de la cadena alimentaria en el que opera la organización y del tipo de organización. Son ejemplos de términos equivalentes: Buenas Prácticas Agrí­colas (BPA), Buenas Prácticas Veterinarias (BPV), Buenas Prácticas de Fabricación/Manufactura (BPF, BPM), Buenas Prácticas de Higiene (BPH), Buenas Prácticas de Producción (BPP), Buenas Prácticas de Distribución (BPD), y Buenas Prácticas de Comercialización (BPC).</div>'),
    ('4b46ebbb-2280-439b-af38-cf6fdfda8eff', 'd3714c13-c660-42af-a834-7e976fb489bb', 'en', 'process', '<div>set of interrelated or interacting activities which transforms inputs to outputs.</div>'),
    ('3646caac-7f95-499c-9706-e6ccf2daace8', 'd3714c13-c660-42af-a834-7e976fb489bb', 'es', 'proceso', '<div>conjunto de actividades interrelacionadas o que interactúan que transforman las entradas en salidas.</div>'),
    ('fb5b8ff2-53fa-4442-aa1b-2aa27328b256', 'd2714a80-5782-4464-893f-072a6eb48828', 'en', 'product', '<div>output that is a result of a process (3.36).</div><div>Note 1 to entry: A product can be a service.</div>'),
    ('105bb101-d357-4799-9232-353d7028ad9d', 'd2714a80-5782-4464-893f-072a6eb48828', 'es', 'producto', '<div>salida que es el resultado de un proceso (3.36).</div><div>Nota 1 a la entrada: Un producto puede ser un servicio.</div>'),
    ('bdc8fc85-0028-401d-b161-a6590d01d5d1', 'e171621d-f019-44fd-9a79-aaf96db48695', 'en', 'requirement', '<div>need or expectation that is stated, generally implied or obligatory.</div><div>Note 1 to entry: “Generally implied” means that it is custom or common practice for the organization and interested parties that the need or expectation under consideration is implied.</div><div>Note 2 to entry: A specified requirement is one that is stated, for example in documented information.</div>'),
    ('d0c91a6e-731b-4b8e-b2ea-06161801e722', 'e171621d-f019-44fd-9a79-aaf96db48695', 'es', 'requisito', '<div>necesidad o expectativa establecida, generalmente implí­cita u obligatoria.</div><div>Nota 1 a la entrada: "Generalmente implí­cito" significa que es costumbre o práctica común para la organización y las partes interesadas con necesidad o expectativa bajo consideración implí­cita.</div><div>Nota 2 a la entrada: Un requisito especí­fico es uno que se establece, por ejemplo, en información documentada.</div>'),
    ('26d02ae4-333d-48a4-a69e-294474055c80', 'e071608a-7a8c-4432-837b-767c6cb48502', 'en', 'risk', '<div>effect of uncertainty</div><div>Note 1 to entry: An effect is a deviation from the expected – positive or negative.</div><div>Note 2 to entry: Uncertainty is the state, even partial, of deficiency of information related to, understanding or knowledge of, an event, its consequence, or likelihood.</div><div>Note 3 to entry: Risk is often characterized by reference to potential “events” (as defined in ISO Guide 73:2009, 3.5.1.3) and “consequences” (as defined in ISO Guide 73:2009, 3.6.1.3), or a combination of these.</div><div>Note 4 to entry: Risk is often expressed in terms of a combination of the consequences of an event (including changes in circumstances) and the associated “likelihood” (as defined in ISO Guide 73:2009, 3.6.1.1) of occurrence.</div><div>Note 5 to entry: Food safety risk is a function of the probability of an adverse health effect and the severity of that effect, consequential to (a) hazard(s) in food (3.18), as specified in the Codex Procedural Manual[11].</div>'),
    ('2bd032c3-3f30-4bf3-8cc8-d17791058a27', 'e071608a-7a8c-4432-837b-767c6cb48502', 'es', 'riesgo', '<div>efecto de la incertidumbre.</div><div>Nota 1 a la entrada: Un efecto es una desviación de lo esperado - positivo o negativo.</div><div>Nota 2 a la entrada: La incertidumbre es el estado, incluso parcial, de la deficiencia de información relacionada con la comprensión o el conocimiento de un evento, su consecuencia o probabilidad.</div><div>Nota 3 a la entrada: El riesgo a menudo se caracteriza por referencia a posibles "eventos" (como se define en la Guí­a ISO 73:2009, 3.5.1.3) y "consecuencias" (como se define en la Guí­a ISO 73:2009, 3.6.1.3), o una combinación de estos.</div><div>Nota 4 a la entrada: El riesgo a menudo se expresa en términos de una combinación de las consecuencias de un evento (incluidos los cambios en las circunstancias) y la "probabilidad" asociada de su ocurrencia (según se define en la Guí­a ISO 73:2009, 3.6.1.1).</div><div>Nota 5 a la entrada: El riesgo de inocuidad de los alimentos es una función de la probabilidad de un efecto adverso para la salud y la gravedad de ese efecto, como consecuencia de peligros en el alimento (3.18), según lo especificado en el Manual de Procedimiento del Codex[11] .</div>'),
    ('144fb1ce-ca65-4f96-8320-72f6b73f5d7a', 'd36f0d7c-dc87-457c-acab-472eefb181a4', 'en', 'significant food safety hazard', '<div>food safety hazard (3.22), identified through the hazard assessment, which needs to be controlled by control measures (3.8).</div>'),
    ('014f93e5-ad8c-4db5-8298-ec399c3f32f9', 'd36f0d7c-dc87-457c-acab-472eefb181a4', 'es', 'peligro significativo relacionado con la inocuidad de los alimentos', '<div>peligro relacionado con la inocuidad de los alimentos (3.22), identificado mediante la evaluación de peligros, el cual necesita ser controlado por medidas de control (3.8).</div>'),
    ('f459a0f7-4446-4cbf-af29-a623e9a4efe3', 'd46f0f0f-84b0-4827-b32d-90abf0b18337', 'en', 'top management', '<div>person or group of people who directs and controls an organization (3.31) at the highest level.</div><div>Note 1 to entry: Top management has the power to delegate authority and provide resources within the organization.</div><div>Note 2 to entry: If the scope of the management system (3.25) covers only part of an organization, then top management refers to those who direct and control that part of the organization.</div>'),
    ('f759a5b0-fc3a-4de8-9ee3-d518e4a4e804', 'd46f0f0f-84b0-4827-b32d-90abf0b18337', 'es', 'alta dirección', '<div>persona o grupo de personas que dirige o controla una organización (3.31) al más alto nivel.</div><div>Nota 1 a la entrada: La alta dirección tiene el poder de delegar autoridad y proporcionar recursos dentro de la organización.</div><div>Nota 2 a la entrada: Si el alcance del sistema de gestión (3.25) cubre solo una parte de una organización, entonces la alta dirección se refiere a aquellos que dirigen y controlan esa parte de la organización. </div>'),
    ('d5135a0c-701b-4a3c-b00c-d2ac780305b8', 'd56f10a2-d34c-49b6-b2a2-3204f1b184ca', 'en', 'traceability', '<div>ability to follow the history, application, movement and location of an object through specified stage(s) of production, processing and distribution.</div><div>Note 1 to entry: Movement can relate to the origin of the materials, processing history or distribution of the food (3.18).</div><div>Note 2 to entry: An object can be a product (3.37), a material, a unit, equipment, a service, etc.</div><div>[SOURCE: CAC/GL 60‑2006, modified — Notes to entry have been added].</div>'),
    ('ea137b1b-1306-443b-84b6-354f85031a2f', 'd56f10a2-d34c-49b6-b2a2-3204f1b184ca', 'es', 'trazabilidad', '<div>capacidad para seguir la historia, aplicación, movimiento y localización de un objeto a través de las etapas especificadas de producción, procesamiento y distribución.</div><div>Nota 1 a la entrada: El movimiento puede estar relacionado con el origen de los materiales, historia del procesamiento o distribución del alimento (3.18).</div><div>Nota 2 a la entrada: Un objeto puede ser un producto (3.37), un material, una unidad, equipos, un servicio, etc.</div><div>[FUENTE: CAC/GL 60-2006, modificado — Notas al texto se han incluido].</div>'),
    ('8c0c5e0d-dba7-4e35-abf4-bfc1be43dca9', 'd66f1235-9766-41b1-994e-c5e1f2b1865d', 'en', 'update', '<div>immediate and/or planned activity to ensure application of the most recent information.</div><div>Note 1 to entry: Update is different from the terms “maintain” and “retain”:</div><div>— “maintain” is to keep something on-going/to keep in good condition</div><div>— “retain” is to keep something that is retrievable.</div>'),
    ('6f0c3066-f880-4016-a71d-ad8eb943d4ca', 'd66f1235-9766-41b1-994e-c5e1f2b1865d', 'es', 'actualización', '<div>actividad inmediata y/o planificada para asegurar la aplicación de la información más reciente.</div><div>Nota 1 a la entrada: La actualización es diferente de los términos "mantener" y "conservar”:</div><div>— “mantener” es tener algo en curso/tener en buenas condiciones</div><div>— “conservar” es tener algo que es recuperable.</div>'),
    ('a1db3f02-b431-4e92-b14e-a1d27ee848a6', 'cf6f0730-8f42-4318-ae95-4ffaebb17b58', 'en', 'validation', '<div>''food safety'' obtaining evidence that a control measure (3.8) (or combination of control measures) will be capable of effectively controlling the significant food safety hazard (3.40).</div><div>Note 1 to entry: Validation is performed at the time a control measure combination is designed, or whenever changes are made to the implemented control measures. Note 2 to entry: Distinctions are made in this document between the terms validation (3.44), monitoring (3.27) and verification (3.45):</div><div>— validation is applied prior to an activity and provides information about the capability to deliver intended results</div><div>— monitoring is applied during an activity and provides information for action within a specified time frame</div><div>— verification is applied after an activity and provides information for confirmation of conformity.</div>'),
    ('96db2db1-a407-4b89-933d-a7cd9be8764d', 'cf6f0730-8f42-4318-ae95-4ffaebb17b58', 'es', 'validación', '<div>''inocuidad de los alimentos'' obtención de evidencia de que una medida de control (3.8) (o combinación de medidas de control) serán capaces de controlar eficazmente el peligro significativo relacionado con la inocuidad de los alimentos (3.40).</div><div>Nota 1 a la entrada: La validación se realiza en el momento en que se diseña una combinación de medidas de control o cuando se realizan cambios en las medidas de control implementadas.</div><div>Nota 2 a la entrada: En este documento se hacen distinciones entre los términos validación (3.44), seguimiento (3.27) y verificación (3.45):</div><div>— la validación se aplica antes de una actividad y proporciona información sobre la capacidad para entregar los resultados previstos</div><div>— el seguimiento se aplica durante una actividad y proporciona información para la acción dentro de un perí­odo especificado de tiempo</div><div>— la verificación se aplica después de una actividad y proporciona información para la confirmación de la conformidad.</div>'),
    ('3f0bf44b-10b2-4deb-8d74-439f9d17974f', 'd06f08c3-0174-4d53-9064-5367ecb17ceb', 'en', 'verification', '<div>verification confirmation, through the provision of objective evidence, that specified requirements (3.38) have been fulfilled.</div><div>Note 1 to entry: Distinctions are made in this document between the terms validation (3.44), monitoring (3.27) and verification (3.45):</div><div>— validation is applied prior to an activity and provides information about the capability to deliver intended results</div><div>— monitoring is applied during an activity and provides information for action within a specified time frame</div><div>— verification is applied after an activity and provides information for confirmation of conformity</div>'),
    ('4a0c059c-2c1d-470c-917a-2a1c901782d8', 'd06f08c3-0174-4d53-9064-5367ecb17ceb', 'es', 'verificación', '<div>confirmación, mediante la aportación de evidencia objetiva, que se han cumplido los requisitos (3.38) especí­ficados.</div><div>Nota 1 a la entrada: En este documento se hacen distinciones entre los términos validación (3.44), seguimiento (3.27) y verificación (3.45):</div><div>— la validación se aplica antes de una actividad y proporciona información sobre la capacidad para entregar los resultados previstos</div><div>— el seguimiento se aplica durante una actividad y proporciona información para la acción dentro de un perí­odo especificado de tiempo</div><div>— la verificación se aplica después de una actividad y proporciona información para la confirmación de la conformidad.</div>'),
    ('ed68a980-b6b4-48b8-9e3e-fec8ea777884', 'd16f0a56-5fe7-45a2-b30d-b3f0edb17e7e', 'en', 'Context of the organization', '<div>{clause_4.1}</div><div>{clause_4.2}</div><div>{clause_4.3}</div><div>{clause_4.4}</div>'),
    ('0a68d727-bb3a-456f-b139-7233ef778063', 'd16f0a56-5fe7-45a2-b30d-b3f0edb17e7e', 'es', 'Contexto de la organización', '<div>{clause_4.1}</div><div>{clause_4.2}</div><div>{clause_4.3}</div><div>{clause_4.4}</div>'),
    ('866522d1-ea49-4d81-83f3-416d83eab325', 'd26f0be9-d399-412d-b4a6-70adeeb18011', 'en', 'Understanding the organization and its context', '<div>The organization shall determine external and internal issues that are relevant to its purpose and that affect its ability to achieve the intended result(s) of its FSMS.</div><div>The organization shall identify, review and update information related to these external and internal issues.</div><div>NOTE 1 Issues can include positive and negative factors or conditions for consideration.</div><div>NOTE 2 Understanding the context can be facilitated by considering external and internal issues, including, but not limited to, legal, technological, competitive, market, cultural, social and economic environments, cybersecurity and food fraud, food defence and intentional contamination, knowledge and performance of the organization, whether international, national, regional or local.</div>'),
    ('91653422-260a-445a-a33e-cbf296ead10e', 'd26f0be9-d399-412d-b4a6-70adeeb18011', 'es', 'Comprensión de la organización y de su contexto', '<div>La organización debe determinar las cuestiones externas e internas que son pertinentes para su propósito y que afectan a su capacidad para lograr los resultados previstos de su SGIA.</div><div>La organización debe identificar, revisar y actualizar la información relacionada con esas cuestiones internas y externas.</div><div>NOTA 1 Las cuestiones pueden incluir factores positivos y negativos o condiciones para su consideración.</div><div>NOTA 2 La comprensión del contexto puede verse facilitada al considerar cuestiones internas y externas incluyendo, pero no limitado a el entorno legal, tecnológico, competitivo, de mercado, cultural, social, económico, seguridad cibernética y fraude alimentario, defensa alimentaria y contaminación intencional, conocimiento y desempeño de la organización ya sea internacional, nacional, regional o local.</div>'),
    ('ec8bff56-1dbc-4d0e-9b79-f39e325c8312', 'db6f1a14-3cde-48d4-bcd0-07f6e7b1750c', 'en', 'Understanding the needs and expectations of interested parties', '<div>To ensure that the organization has the ability to consistently provide products and services that meet applicable statutory, regulatory and customer requirements with regard to food safety, the organization shall determine:</div><div>{clause_4.2.a}</div><div>{clause_4.2.b}</div><div>The organization shall identify, review and update information related to the interested parties and their requirements.</div>'),
    ('e98bfa9d-aaca-419d-9171-b7f1475ca421', 'db6f1a14-3cde-48d4-bcd0-07f6e7b1750c', 'es', 'Comprensión de las necesidades y expectativas de las partes interesadas', '<div>Para asegurar que la organización tiene la capacidad de proporcionar regularmente productos y servicios que satisfagan los requisitos del cliente y los requisitos legales y reglamentarios aplicables, referente a la inocuidad de los alimentos, la organización debe determinar:</div><div>{clause_4.2.a}</div><div>{clause_4.2.b}</div><div>La organización debe identificar, revisar y actualizar la información relacionada a estas partes interesadas y sus requisitos. </div>'),
    ('593ddbff-dd44-4c37-80f7-d64b82464bdb', 'dc6f1ba7-abba-441f-96b2-5613e8b1769f', 'en', '', '<div>a) the interested parties that are relevant to the FSMS</div>'),
    ('6c3df9e8-3da3-4070-9332-c2706d462acc', 'dc6f1ba7-abba-441f-96b2-5613e8b1769f', 'es', '', '<div>a) las partes interesadas que son pertinentes al SGIA </div>'),
    ('fba998db-eb64-40c7-9646-b68f0b207127', '6576af17-a7f8-418f-8f35-cdf761b8f0df', 'en', '', '<div>b) the relevant requirements of the interested parties of the FSMS.</div>'),
    ('e6a977cc-f21d-4760-8dfc-f6ecee204380', '6576af17-a7f8-418f-8f35-cdf761b8f0df', 'es', '', '<div>b) los requisitos pertinentes de estas partes interesadas para el SGIA</div>'),
    ('abbfd012-c941-4f9e-95db-96c2eb161d3e', '6476ad84-1fd0-4144-8018-1a0a60b8ef4c', 'en', 'Determining the scope of the food safety management system', '<div>The organization shall determine the boundaries and applicability of the FSMS to establish its scope. The scope shall specify the products and services, processes and production site(s) that are included in the FSMS. The scope shall include the activities, processes, products or services that can have an influence on the food safety of its end products.</div><div>When determining this scope, the organization shall consider:</div><div>{clause_4.3.a}</div><div>{clause_4.3.b}</div><div>The scope shall be available and maintained as documented information.</div>'),
    ('c0bff121-9749-408d-871c-0d5df81631b5', '6476ad84-1fd0-4144-8018-1a0a60b8ef4c', 'es', 'Determinación del alcance del sistema de gestión de inocuidad de los alimentos', '<div>La organización debe determinar los lí­mites y la aplicabilidad del SGIA para establecer su alcance. El alcance debe especificar los productos y servicios, procesos y sitios de producción que se incluyen en el SGIA. El alcance debe incluir las actividades, procesos, productos o servicios que pueden influir en la inocuidad de los alimentos de sus productos terminados.</div><div>Cuando se determina este alcance, la organización debe considerar:</div><div>{clause_4.3.a}</div><div>{clause_4.3.b}</div><div>El alcance debe estar disponible y mantenerse como información documentada.</div>'),
    ('d04a18a1-0d9b-423d-8539-00ddf01887bd', '6776b23d-1d39-42b9-bc24-647d63b8f405', 'en', '', '<div>a) the external and internal issues referred to in 4.1</div>'),
    ('bb49f792-83b9-472e-93f8-8a42f3188c76', '6776b23d-1d39-42b9-bc24-647d63b8f405', 'es', '', '<div>a) las cuestiones externas e internas indicadas en el apartado 4.1 </div>'),
    ('3928a490-ed9e-4044-a268-8878ec77fafc', '6676b0aa-1694-457e-a470-48c062b8f272', 'en', '', '<div>b) the requirements referred to in 4.2.</div>'),
    ('36289fd7-ddc9-4593-983e-1183e177e9ab', '6676b0aa-1694-457e-a470-48c062b8f272', 'es', '', '<div>b) los requisitos indicados en el apartado 4.2.</div>'),
    ('3d9f3307-6801-4bb3-adfd-2e93584d2d7b', '6176a8cb-a747-40bb-a78b-667b5db8ea93', 'en', 'Food safety management system', '<div>The organization shall establish, implement, maintain, update and continually improve a FSMS, including the processes needed and their interactions, in accordance with the requirements of this document.</div>'),
    ('209f0560-755a-4a64-82f7-a8a8434d0c6c', '6176a8cb-a747-40bb-a78b-667b5db8ea93', 'es', 'Sistema de gestión de inocuidad de los alimentos', '<div>La organización debe establecer, implementar, mantener, actualizar y mejorar continuamente un SGIA, incluyendo los procesos necesarios y sus interacciones, de acuerdo con los requisitos de este documento. </div>'),
    ('90ee849e-df2e-4a9a-81ae-062605e768b2', '6076a738-9c6b-4400-b85a-583e5cb8e900', 'en', 'Leadership', '<div>{clause_5.1}</div><div>{clause_5.2}</div><div>{clause_5.3}</div>'),
    ('9dee9915-8a22-41c1-bbcc-6a891ae789c1', '6076a738-9c6b-4400-b85a-583e5cb8e900', 'es', 'Liderazgo', '<div>{clause_5.1}</div><div>{clause_5.2}</div><div>{clause_5.3}</div>'),
    ('95ef5c1d-b4ec-4149-b8a8-a7f12a71b141', '6376abf1-f6e1-4a95-b0a6-38b15fb8edb9', 'en', 'Leadership and commitment', '<div>Top management shall demonstrate leadership and commitment with respect to the FSMS by:</div><div>{clause_5.1.a}</div><div>{clause_5.1.b}</div><div>{clause_5.1.c}</div><div>{clause_5.1.d}</div><div>{clause_5.1.e}</div><div>{clause_5.1.f}</div><div>{clause_5.1.g}</div><div>{clause_5.1.h}</div><div>NOTE: Reference to “business” in this document can be interpreted broadly to mean those activities that are core to the purposes of the organization’s existence.</div>'),
    ('98ef60d6-c516-4452-82b0-e39e15719032', '6376abf1-f6e1-4a95-b0a6-38b15fb8edb9', 'es', 'Liderazgo y compromiso', '<div>La alta dirección debe demostrar liderazgo y compromiso con respecto al SGIA:</div><div>{clause_5.1.a}</div><div>{clause_5.1.b}</div><div>{clause_5.1.c}</div><div>{clause_5.1.d}</div><div>{clause_5.1.e}</div><div>{clause_5.1.f}</div><div>{clause_5.1.g}</div><div>{clause_5.1.h}</div><div>NOTA: La referencia a "negocios" en este documento puede interpretarse en términos generales como aquellas actividades que son esenciales para los propósitos de la existencia de la organización. </div>'),
    ('1ef6bcdc-8101-4160-a55d-a7dc06a9e2b0', '6276aa5e-a330-416a-939f-bcd45eb8ec26', 'en', '', '<div>a) ensuring that the food safety policy and the objectives of the FSMS are established and are compatible with the strategic direction of the organization</div>'),
    ('13f6ab8b-7a48-4ac7-9e66-d35f03a9ddf7', '6276aa5e-a330-416a-939f-bcd45eb8ec26', 'es', '', '<div>a) asegurando que la polí­tica de inocuidad de los alimentos y los objetivos del SGIA están establecidos y que éstos son compatibles con la dirección estratégica de la organización</div>'),
    ('63083ce3-c1f2-484f-8b7b-341770a27cef', '5d76a27f-67a3-4397-aad9-377f69b8fd77', 'en', '', '<div>b) ensuring the integration of the FSMS requirements into the organization’s business processes</div>'),
    ('5e083504-d389-4118-9c5a-a2e463a26878', '5d76a27f-67a3-4397-aad9-377f69b8fd77', 'es', '', '<div>b) asegurando la integración de los requisitos del SGIA en los procesos de negocio de la organización</div>'),
    ('30a2aa7a-5758-4ee6-90b8-608ac5ce66c6', '5c76a0ec-ee47-4aac-a118-77f268b8fbe4', 'en', '', '<div>c) ensuring that the resources needed for the FSMS are available</div>'),
    ('15a27ff9-aa45-4325-b672-5f55e2ce946d', '5c76a0ec-ee47-4aac-a118-77f268b8fbe4', 'es', '', '<div>c) asegurando que estén disponibles los recursos necesarios para el SGIA</div>'),
    ('0a58e194-87cd-4d30-9fba-3bd4fa6eeb40', '5f74670e-a84b-456e-8f3a-0c6c5bb6a8d6', 'en', '', '<div>d) communicating the importance of effective food safety management and conforming to the FSMS requirements, applicable statutory and regulatory requirements, and mutually agreed customer requirements related to food safety</div>'),
    ('ef58b713-0e21-43f7-bd32-ee67176f18e7', '5f74670e-a84b-456e-8f3a-0c6c5bb6a8d6', 'es', '', '<div>d) comunicando la importancia de una gestión eficaz de la inocuidad de los alimentos y cumpliendo con los requisitos del SGIA, los requisitos legales y reglamentarios aplicables, y los requisitos relacionados con la inocuidad de los alimentos acordados mutuamente con los clientes </div>'),
    ('307276b5-4e31-4a59-98b4-3fa9936b6491', '607468a1-aef1-45a9-91f7-37695cb6aa69', 'en', '', '<div>e) ensuring that the FSMS is evaluated and maintained to achieve its intended result(s) (see 4.1)</div>'),
    ('2372623e-b800-4802-9290-4fc69e6b75e2', '607468a1-aef1-45a9-91f7-37695cb6aa69', 'es', '', '<div>e) asegurando que el SGIA se evalúa y mantiene para lograr sus resultados previstos (véase 4.1)</div>'),
    ('2c1102f6-2e46-402a-949e-803eac6717c2', '5d7463e8-c52d-43b4-b73e-365659b6a5b0', 'en', '', '<div>f) directing and supporting persons to contribute to the effectiveness of the FSMS</div>'),
    ('2910fe3d-4cca-47b1-b102-7e11a1670671', '5d7463e8-c52d-43b4-b73e-365659b6a5b0', 'es', '', '<div>f) dirigiendo y apoyando a las personas para que contribuyan con la eficacia del SGIA</div>'),
    ('09a0891f-a3db-4083-92d2-1c6b4c10a30b', '5e74657b-3736-4b7f-84ef-2af35ab6a743', 'en', '', '<div>g) promoting continual improvement</div>'),
    ('1ca0a708-f735-4d54-966f-d2905710b45c', '5e74657b-3736-4b7f-84ef-2af35ab6a743', 'es', '', '<div>g) promoviendo la mejora continua</div>'),
    ('252a2d08-96b2-4bd4-90cb-3790df9d9fcc', '63746d5a-330c-4c1a-bb75-4bb85fb6af22', 'en', '', '<div>h) supporting other relevant management roles to demonstrate their leadership as it applies to their areas of responsibility.</div>'),
    ('122a0f1f-4357-4f03-8d2d-816bf49dc0db', '63746d5a-330c-4c1a-bb75-4bb85fb6af22', 'es', '', '<div>h) apoyando otros roles pertinentes de la dirección, para demostrar su liderazgo en lo que respecta a sus áreas de responsabilidad.</div>'),
    ('9ec444b9-fc6b-4d4d-8043-5e9599110ccd', '64746eed-6f4b-4585-bf7a-9ad560b6b0b5', 'en', 'Policy', '<div>{clause_5.2.1}</div><div>{clause_5.2.2}</div>'),
    ('b9c46f3a-30e0-485e-8207-33ca7c10df26', '64746eed-6f4b-4585-bf7a-9ad560b6b0b5', 'es', 'Polí­tica', '<div>{clause_5.2.1}</div><div>{clause_5.2.2}</div>'),
    ('2642b84a-2e5a-48ae-a1f9-a87a1edb8a8e', '61746a34-41c8-4670-a9ae-9e025db6abfc', 'en', 'Establishing the food safety policy', '<div>Top management shall establish, implement and maintain a food safety policy that:</div><div>{clause_5.2.1.a}</div><div>{clause_5.2.1.b}</div><div>{clause_5.2.1.c}</div><div>{clause_5.2.1.d}</div><div>{clause_5.2.1.e}</div><div>{clause_5.2.1.f}</div>'),
    ('2b42c029-b83d-43bd-94e9-d9650bdb6ca5', '61746a34-41c8-4670-a9ae-9e025db6abfc', 'es', 'Establecimiento de la polí­tica de la inocuidad de los alimentos', '<div>La alta dirección debe establecer, implementar y mantener una polí­tica de la inocuidad de los alimentos que: </div><div>{clause_5.2.1.a}</div><div>{clause_5.2.1.b}</div><div>{clause_5.2.1.c}</div><div>{clause_5.2.1.d}</div><div>{clause_5.2.1.e}</div><div>{clause_5.2.1.f}</div>'),
    ('56cbb273-6e88-4e57-90cf-2a47fee579b7', '62746bc7-38fe-40ab-848b-dc0f5eb6ad8f', 'en', '', '<div>a) is appropriate to the purpose and context of the organization</div>'),
    ('71cbdcf4-d162-4b90-9eaf-233401e57e70', '62746bc7-38fe-40ab-848b-dc0f5eb6ad8f', 'es', '', '<div>a) sea apropiada al propósito y contexto de la organización </div>'),
    ('121c61ac-84b9-4fd8-b207-194c7f51c5a8', '57745a76-5e15-4d96-ad1b-746463b6b56e', 'en', '', '<div>b) provides a framework for setting and reviewing the objectives of the FSMS</div>'),
    ('271c82bb-759b-4d0f-8a39-01ef6c51a7bf', '57745a76-5e15-4d96-ad1b-746463b6b56e', 'es', '', '<div>b) proporcione un marco de referencia para establecer y revisar los objetivos del SGIA</div>'),
    ('c91565ad-38f7-4e21-b261-c2e1f8ed7059', '58745c09-255c-4211-bccc-82c164b6b701', 'en', '', '<div>c) includes a commitment to satisfy applicable food safety requirements, including statutory and regulatory requirements and mutually agreed customer requirements related to food safety</div>'),
    ('ac153806-74b6-41fa-95d0-1eae13ed9ada', '58745c09-255c-4211-bccc-82c164b6b701', 'es', '', '<div>c) incluya el compromiso de cumplir con los requisitos de inocuidad de los alimentos aplicables, incluidos los requisitos legales y reglamentarios y los requisitos mutuamente acordados con los clientes relacionados con la inocuidad de los alimentos</div>'),
    ('b467cf61-7385-4f11-96ec-149d07d845e5', '5153fd59-9dd0-4421-a238-73bdedbe4a71', 'en', '', '<div>d) addresses internal and external communication</div>'),
    ('9f67ae52-6b1f-4d0a-b83e-b7021ad863ce', '5153fd59-9dd0-4421-a238-73bdedbe4a71', 'es', '', '<div>d) aborde la comunicación interna y externa</div>'),
    ('1acd8550-32df-48c8-9d9c-183870df7444', '5053fbc6-c068-4426-90ff-9500ecbe48de', 'en', '', '<div>e) includes a commitment to continual improvement of the FSMS</div>'),
    ('17cd8097-7d67-439f-a99f-ff4375df7c23', '5053fbc6-c068-4426-90ff-9500ecbe48de', 'es', '', '<div>e) incluya un compromiso con la mejora continua del SGIA</div>'),
    ('dfc8e29b-ae39-4c3b-87fc-2c4f237f930f', '4f53fa33-71ce-4597-8e0b-7a37ebbe474b', 'en', '', '<div>f) addresses the need to ensure competencies related to food safety.</div>'),
    ('cac8c18c-0b4e-423c-b352-c9ac167f7e98', '4f53fa33-71ce-4597-8e0b-7a37ebbe474b', 'es', '', '<div>f) aborde la necesidad de asegurar las competencias relacionadas con la inocuidad de los alimentos.</div>'),
    ('8d631dd2-e22e-45e2-ba21-c38202d76e66', '4e53f8a0-f871-4cac-9589-454aeabe45b8', 'en', 'Communicating the food safety policy', '<div>The food safety policy shall:</div><div>{clause_5.2.2.a}</div><div>{clause_5.2.2.b}</div><div>{clause_5.2.2.c}</div>'),
    ('a2633ee1-7530-48b9-98cf-211d1fd79c0d', '4e53f8a0-f871-4cac-9589-454aeabe45b8', 'es', 'Comunicación de la polí­tica de la inocuidad de los alimentos', '<div>La polí­tica de la inocuidad de los alimentos debe:</div><div>{clause_5.2.2.a}</div><div>{clause_5.2.2.b}</div><div>{clause_5.2.2.c}</div>'),
    ('7a0ea5dd-f057-4085-8467-ffb142316f69', '555403a5-c017-4add-a7e3-1ef1f1be50bd', 'en', '', '<div>a) be available and maintained as documented information</div>'),
    ('7d0eaa96-b110-4ec6-9d8c-845e3d31678a', '555403a5-c017-4add-a7e3-1ef1f1be50bd', 'es', '', '<div>a) estar disponible y mantenerse como información documentada </div>'),
    ('009b9d9c-46db-4f8c-9fa7-459cfe6b0178', '54540212-4d05-4312-a7a9-b914f0be4f2a', 'en', '', '<div>b) be communicated, understood and applied at all levels within the organization</div>'),
    ('f59b8c4b-2b71-466b-9ba1-5f1f0b6b15ef', '54540212-4d05-4312-a7a9-b914f0be4f2a', 'es', '', '<div>b) comunicarse, entenderse y aplicarse a todos los niveles dentro de la organización</div>'),
    ('1f4413c7-95c5-424f-89a0-74536d9282a3', '5354007f-04b0-4043-a19a-32bbefbe4d97', 'en', '', '<div>c) be available to relevant interested parties, as appropriate.</div>'),
    ('0243e620-a75c-4b18-b29e-b46868927ac4', '5354007f-04b0-4043-a19a-32bbefbe4d97', 'es', '', '<div>c) estar disponible para las partes interesadas pertinentes, según sea apropiado.</div>'),
    ('750dce5e-2b2b-48e6-8d64-8fe63da7593a', '5253feec-95ac-4588-b8b3-a97eeebe4c04', 'en', 'Organizational roles, responsibilities and authorities', '<div>{clause_5.3.1}</div><div>{clause_5.3.2}</div><div>{clause_5.3.3}</div>'),
    ('820de2d5-7e18-4d25-9e58-1c4922a72eb9', '5253feec-95ac-4588-b8b3-a97eeebe4c04', 'es', 'Roles, responsabilidades y autoridades en la organización', '<div>{clause_5.3.1}</div><div>{clause_5.3.2}</div><div>{clause_5.3.3}</div>'),
    ('194a7769-88bf-4b49-9a26-62a5a2f59ddd', '595409f1-2764-44b9-bcfe-8b05e5be3dd9', 'en', '', '<div>Top management shall ensure that the responsibilities and authorities for relevant roles are assigned, communicated and understood within the organization.</div><div>Top management shall assign the responsibility and authority for:</div><div>{clause_5.3.1.a}</div><div>{clause_5.3.1.b}</div><div>{clause_5.3.1.c}</div><div>{clause_5.3.1.d}</div>'),
    ('144a6f8a-98e9-4e52-907c-9abaa5f5a296', '595409f1-2764-44b9-bcfe-8b05e5be3dd9', 'es', '', '<div>La alta dirección debe asegurarse que las responsabilidades y autoridades para los roles pertinentes se asignen, se comuniquen y se entiendan en toda la organización.</div><div>La alta dirección debe asignar la responsabilidad y autoridad para:</div><div>{clause_5.3.1.a}</div><div>{clause_5.3.1.b}</div><div>{clause_5.3.1.c}</div><div>{clause_5.3.1.d}</div>'),
    ('d5840978-54d4-4b60-b489-d1202982959c', '5854085e-20bf-477e-8d79-b828e4be3c46', 'en', '', '<div>a) ensuring that the FSMS conforms to the requirements of this document</div>'),
    ('e2841def-4e1c-44c7-a421-ab5b1e82844b', '5854085e-20bf-477e-8d79-b828e4be3c46', 'es', '', '<div>a) asegurar que el SGIA es conforme con los requisitos de este documento </div>'),
    ('c3039062-2f68-4332-ba23-0432369b48b6', '4b51b550-2763-4578-850f-061ae7bc0268', 'en', '', '<div>b) reporting on the performance of the FSMS to top management</div>'),
    ('b8037f11-21b9-4929-80bd-d4ad339b43fd', '4b51b550-2763-4578-850f-061ae7bc0268', 'es', '', '<div>b) informar a la alta dirección sobre el desempeño del SGIA </div>'),
    ('d38c582b-b28b-4f0b-bde2-5f7f16a537df', '4c51b6e3-9668-4333-9ce8-5a87e8bc03fb', 'en', '', '<div>c) appointing the food safety team and the food safety team leader</div>'),
    ('de8c697c-cdf5-482c-9554-73fc29a555c8', '4c51b6e3-9668-4333-9ce8-5a87e8bc03fb', 'es', '', '<div>c) designar al equipo de inocuidad de los alimentos y al lí­der del equipo de inocuidad de los alimentos</div>'),
    ('0e90fae0-588c-49d8-ab6b-1a28175f2354', '4d51b876-f4db-4b82-a9c1-7c10e9bc058e', 'en', '', '<div>d) designating persons with defined responsibility and authority to initiate and document action(s).</div>'),
    ('2b912887-496e-470f-9670-a013fc5ef8d3', '4d51b876-f4db-4b82-a9c1-7c10e9bc058e', 'es', '', '<div>d) designar personas con responsabilidad y autoridad definidas para iniciar y documentar acciones.</div>'),
    ('a78d7431-0cca-4821-85bb-374d3afe4f75', '4e51ba09-526d-4e8d-824a-57cdeabc0721', 'en', '', '<div>The food safety team leader shall be responsible for:</div><div>{clause_5.3.2.a}</div><div>{clause_5.3.2.b}</div><div>{clause_5.3.2.c}</div><div>{clause_5.3.2.d}</div>'),
    ('b28d8582-4889-4bfa-a3cc-31522dfe3afe', '4e51ba09-526d-4e8d-824a-57cdeabc0721', 'es', '', '<div>El lí­der del equipo de inocuidad de los alimentos debe ser responsable de</div><div>{clause_5.3.2.a}</div><div>{clause_5.3.2.b}</div><div>{clause_5.3.2.c}</div><div>{clause_5.3.2.d}</div>'),
    ('a8d1a8ae-2f7d-4bb6-9f29-fcd630ccfe0a', '4f51bb9c-8ac8-405c-845d-15ceebbc08b4', 'en', '', '<div>a) ensuring the FSMS is established, implemented, maintained and updated</div>'),
    ('95d18ac5-28c5-4555-ae58-0d1935cd05e9', '4f51bb9c-8ac8-405c-845d-15ceebbc08b4', 'es', '', '<div>a) asegurar que se establece, implementa, mantiene y actualiza el SGIA</div>'),
    ('86612ed7-e61f-4ddf-96df-280361578b33', '5051bd2f-19a4-4e07-81d5-b94becbc0a47', 'en', '', '<div>b) managing and organizing the work of the food safety team</div>'),
    ('89613390-9e13-4f08-a109-9ef87c57b5b4', '5051bd2f-19a4-4e07-81d5-b94becbc0a47', 'es', '', '<div>b) gestionar y organizar el trabajo del equipo de inocuidad de los alimentos</div>'),
    ('f3c1426c-97d5-4edc-90dc-c50c322edbc8', '5151bec2-6840-4f96-a244-ffa4edbc0bda', 'en', '', '<div>c) ensuring relevant training and competencies for the food safety team (see 7.2)</div>'),
    ('08c1637b-1ef9-4adb-9d7f-45af1f2ebddf', '5151bec2-6840-4f96-a244-ffa4edbc0bda', 'es', '', '<div>c) asegurar la formación y las competencias pertinentes para el equipo de inocuidad de los alimentos (véase 7.2):</div>'),
    ('ad34af6d-00e8-4cd5-803e-4aa1a9501d79', '5251c055-2f87-4411-a7e6-7b01eebc0d6d', 'en', '', '<div>d) reporting to top management on the effectiveness and suitability of the FSMS.</div>'),
    ('903481c6-07a0-4336-be05-2c6ec45047fa', '5251c055-2f87-4411-a7e6-7b01eebc0d6d', 'es', '', '<div>d) informar a la alta dirección sobre la eficacia y pertinencia del SGIA.</div>'),
    ('07e6060a-0219-4a2a-ab75-953ad1b8a0ae', '5351c1e8-4bf3-4870-9696-de42dfbbf5d0', 'en', '', '<div>All persons shall have the responsibility to report problem(s) with regards to the FSMS to identified person(s).</div>'),
    ('0ce60de9-209d-41b1-b51f-5d25beb882c5', '5351c1e8-4bf3-4870-9696-de42dfbbf5d0', 'es', '', '<div>Todas las personas deben tener la responsabilidad de informar los problemas con respecto al SGIA a las personas identificadas.</div>'),
    ('38709333-77ae-4a83-b345-0907af4826d7', '5451c37b-4329-42ab-b3ae-c24fe0bbf763', 'en', 'Planning', '<div>{clause_6.1}</div><div>{clause_6.2}</div><div>{clause_6.3}</div>'),
    ('5370bdb4-cb08-4754-9847-1ef4b2482b90', '5451c37b-4329-42ab-b3ae-c24fe0bbf763', 'es', 'Planificación', '<div>{clause_6.1}</div><div>{clause_6.2}</div><div>{clause_6.3}</div>'),
    ('c9b10040-6aaf-4778-9935-bd085f258334', 'e2d03816-d92d-4376-a962-17b0ff625e1e', 'en', 'Actions to address risks and opportunities', '<div>{clause_6.1.1}</div><div>{clause_6.1.2}</div><div>{clause_6.1.3}</div>'),
    ('e6b12de7-55eb-422f-a502-d873442558b3', 'e2d03816-d92d-4376-a962-17b0ff625e1e', 'es', 'Acciones para abordar riesgos y oportunidades', '<div>{clause_6.1.1}</div><div>{clause_6.1.2}</div><div>{clause_6.1.3}</div>'),
    ('62ad7991-827f-4141-9f54-abadf61e54d5', 'e3d039a9-b419-4771-a665-736d00625fb1', 'en', '', '<div>When planning for the FSMS, the organization shall consider the issues referred to in 4.1 and the requirements referred to in 4.2 and 4.3 and determine the risks and opportunities that need to be addressed to:</div><div>{clause_6.1.1.a}</div><div>{clause_6.1.1.b}</div><div>{clause_6.1.1.c}</div><div>{clause_6.1.1.d}</div><div>NOTE: In the context of this document, the concept of risks and opportunities is limited to events and their consequences relating to the performance and effectiveness of the FSMS. Public authorities are responsible for addressing public health risks. Organizations are required to manage food safety hazards (see 3.22) and the requirements related to this process that are laid down in Clause 8.</div>'),
    ('6dad8ae2-d78b-4a1a-98b9-db32e91e405e', 'e3d039a9-b419-4771-a665-736d00625fb1', 'es', '', '<div>Al planificar el SGIA, la organización debe considerar las cuestiones referidas en el apartado 4.1 y los requisitos referidos en los apartados 4.2 y 4.3 y determinar los riesgos y oportunidades, que es necesario abordar con el fin de: </div><div>{clause_6.1.1.a}</div><div>{clause_6.1.1.b}</div><div>{clause_6.1.1.c}</div><div>{clause_6.1.1.d}</div><div>NOTA: En el contexto de este documento, el concepto de riesgos y oportunidades se limita a los eventos y sus consecuencias relacionadas con el desempeño y la eficacia del SGIA. Las autoridades públicas son responsables de abordar los riesgos para la salud pública. Las organizaciones están obligadas a gestionar los peligros relacionados con la inocuidad de los alimentos (véase 3.22) y los requisitos relacionados con este proceso que se establecen en el Capí­tulo 8.</div>'),
    ('7ba92cc2-c0e5-4a52-9a33-0c12f1bb4e16', 'e0d034f0-f93a-4b3c-93b0-50bafd625af8', 'en', '', '<div>a) give assurance that the FSMS can achieve its intended result(s)</div>'),
    ('70a91b71-b0bb-4749-9277-e20deebb495d', 'e0d034f0-f93a-4b3c-93b0-50bafd625af8', 'es', '', '<div>a) asegurar que el SGIA pueda lograr sus resultados previstos</div>'),
    ('1b52b80b-6eb6-43ab-8226-addf5e6b97bf', 'e1d03683-8817-48e7-b1cf-0227fe625c8b', 'en', '', '<div>b) enhance desirable effects</div>'),
    ('2652c95c-6e59-4ecc-891d-825c716bb5a8', 'e1d03683-8817-48e7-b1cf-0227fe625c8b', 'es', '', '<div>b) aumentar los efectos deseables </div>'),
    ('aedfb4cc-0d8a-47fc-8788-64ec777ad2a8', 'e6d03e62-7f15-4462-8795-60c40362646a', 'en', '', '<div>c) prevent, or reduce, undesired effects</div>'),
    ('c3dfd5db-adfc-4bfb-8fd2-248f647ab4bf', 'e6d03e62-7f15-4462-8795-60c40362646a', 'es', '', '<div>c) prevenir o reducir efectos no deseados</div>'),
    ('685321cd-e85c-4cf5-9d89-5f01f1167d59', 'e7d03ff5-d97a-4aed-9c05-b7a1046265fd', 'en', '', '<div>d) achieve continual improvement.</div>'),
    ('4b52f426-02b9-42d6-b838-63ce0c16a7da', 'e7d03ff5-d97a-4aed-9c05-b7a1046265fd', 'es', '', '<div>d) lograr la mejora continua.</div>'),
    ('ee1d9f8e-d49f-4256-873a-2236ebed036a', 'e4d03b3c-abf6-48d8-98dc-ddee01626144', 'en', '', '<div>The organization shall plan:</div><div>{clause_6.1.2.a}</div><div>{clause_6.1.2.b}</div>'),
    ('db1d81a5-ba41-4c75-a761-db79f0ed0b49', 'e4d03b3c-abf6-48d8-98dc-ddee01626144', 'es', '', '<div>La organización debe planificar:</div><div>{clause_6.1.2.a}</div><div>{clause_6.1.2.b}</div>'),
    ('ce278eb7-9fd1-4c7f-8331-30631c75fd93', 'e5d03ccf-04d9-4b13-be2e-5f6b026262d7', 'en', '', '<div>a) actions to address these risks and opportunities</div>'),
    ('d1279370-57c3-4aa8-b6ca-f05837762814', 'e5d03ccf-04d9-4b13-be2e-5f6b026262d7', 'es', '', '<div>a) las acciones para abordar estos riesgos y oportunidades </div>'),
    ('4e93daa8-789f-4650-8c7d-4fb0d7c6accc', 'ead044ae-3708-4ace-b1b9-e718f7625186', 'en', '', '<div>b) how to:</div><ul><li>{clause_6.1.2.b.1}</li><li>{clause_6.1.2.b.2}</li></ul>'),
    ('3b93bcbf-1840-4217-ba14-3f8becc6cddb', 'ead044ae-3708-4ace-b1b9-e718f7625186', 'es', '', '<div>b) la manera de: </div><ul><li>{clause_6.1.2.b.1}</li><li>{clause_6.1.2.b.2}</li></ul>'),
    ('c82f8559-f1d4-4879-8870-c735913a19cd', 'ebd04641-278f-4289-8d29-0bb5f8625319', 'en', '', '<div>1) integrate and implement the actions into its FSMS processes</div>'),
    ('e32fafda-4584-4da2-9a98-e6ea7439ec26', 'ebd04641-278f-4289-8d29-0bb5f8625319', 'es', '', '<div>1) integrar e implementar las acciones en sus procesos del SGIA </div>'),
    ('da628627-6595-466f-8597-65b350763a7b', 'e8d2801f-a535-4d77-9540-b6db0564a627', 'en', '', '<div>2) evaluate the effectiveness of these actions.</div>'),
    ('bd625880-610e-49b8-b29c-f2483b76196c', 'e8d2801f-a535-4d77-9540-b6db0564a627', 'es', '', '<div>2) evaluar la eficacia de estas acciones.</div>'),
    ('ba58323e-fafb-4d06-84e5-aac6fe1075b2', 'e7d27e8c-15bb-4f0c-b7a8-579e0464a494', 'en', '', '<div>The actions taken by the organization to address risks and opportunities shall be proportionate to:</div><div>{clause_6.1.3.a}</div><div>{clause_6.1.3.b}</div><div>{clause_6.1.3.c}</div><div>NOTE 1: Actions to address risks and opportunities can include: avoiding risk, taking risk in order to pursue an opportunity, eliminating the risk source, changing the likelihood or consequences, sharing the risk, or accepting the presence of risk by informed decision.</div><div>NOTE 2: Opportunities can lead to the adoption of new practices (modification of products or processes), using new technology and other desirable and viable possibilities to address the food safety needs of the organization or its customers.</div>'),
    ('c75846b5-37c9-48c5-8b09-9aa9131096c1', 'e7d27e8c-15bb-4f0c-b7a8-579e0464a494', 'es', '', '<div>Las acciones tomadas por la organización para abordar los riesgos y oportunidades deben ser proporcionales a: </div><div>{clause_6.1.3.a}</div><div>{clause_6.1.3.b}</div><div>{clause_6.1.3.c}</div><div>NOTA 1 Las acciones para abordar los riesgos y oportunidades pueden incluir: evitar riesgos, asumir riesgos para perseguir una oportunidad, eliminar la fuente de riesgo, cambiar la probabilidad o las consecuencias, compartir el riesgo o aceptar la presencia del riesgo mediante decisión informada.</div><div>NOTA 2 Las oportunidades pueden conducir a la adopción de nuevas prácticas (modificación de los productos o los procesos), usando nuevas tecnologí­as y otras posibilidades deseables y viables para abordar las necesidades de inocuidad de los alimentos de la organización o de sus clientes.</div>'),
    ('bf5a9cbd-c028-47a5-a0fb-cb91229abe41', 'ead28345-bb18-4381-9df4-4f110764a94d', 'en', '', '<div>a) the impact on food safety requirements</div>'),
    ('c25aa176-6d3b-4366-8497-cdbe0d9a9d32', 'ead28345-bb18-4381-9df4-4f110764a94d', 'es', '', '<div>a) el impacto en los requisitos de inocuidad de los alimentos </div>'),
    ('bbba0ffc-9344-492c-bccd-787cfed2efb0', 'e9d281b2-0d1d-4406-930b-12b40664a7ba', 'en', '', '<div>b) the conformity of food products and services to customers</div>'),
    ('b0b9feab-77da-400b-a55b-63fffbd2eaf7', 'e9d281b2-0d1d-4406-930b-12b40664a7ba', 'es', '', '<div>b) la conformidad de los productos alimentarios y servicios para los clientes </div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('278f427b-bab5-445b-ba11-25af03497e27', 'e4d279d3-3b46-47a3-b316-c05701649fdb', 'en', '', '<div>c) requirements of interested parties in the food chain.</div>'),
    ('128f216c-3390-485c-ad6e-a50ce6495080', 'e4d279d3-3b46-47a3-b316-c05701649fdb', 'es', '', '<div>c) los requisitos de las partes interesadas en la cadena alimentaria.</div>'),
    ('d5297db2-98b1-4502-be34-6ae2e33f2a3e', 'e3d27840-b2f6-47e8-b4e2-26ea00649e48', 'en', 'Objectives of the food safety management system and planning to achieve them', '<div>{clause_6.2.1}</div><div>{clause_6.2.2}</div>'),
    ('ea299ec1-2ee2-4759-a395-a97df03f3eb5', 'e3d27840-b2f6-47e8-b4e2-26ea00649e48', 'es', 'Objetivos del sistema de gestión de inocuidad de los alimentos y planificación para lograrlos', '<div>{clause_6.2.1}</div><div>{clause_6.2.2}</div>'),
    ('f9b3c641-ff59-40b1-96ce-2dfde84194bd', 'e6d27cf9-f380-45bd-8e1a-7cdd0364a301', 'en', '', '<div>The organization shall establish objectives for the FSMS at relevant functions and levels.</div><div>The objectives of the FSMS shall:</div><div>{clause_6.2.1.a}</div><div>{clause_6.2.1.b}</div><div>{clause_6.2.1.c}</div><div>{clause_6.2.1.d}</div><div>{clause_6.2.1.e}</div><div>{clause_6.2.1.f}</div><div>The organization shall retain documented information on the objectives for the FSMS.</div>'),
    ('e4b3a532-e0d5-492a-b16c-ef62eb419976', 'e6d27cf9-f380-45bd-8e1a-7cdd0364a301', 'es', '', '<div>La organización debe establecer objetivos para el SGIA para las funciones y niveles pertinentes</div><div>Los objetivos del SGIA deben: </div><div>{clause_6.2.1.a}</div><div>{clause_6.2.1.b}</div><div>{clause_6.2.1.c}</div><div>{clause_6.2.1.d}</div><div>{clause_6.2.1.e}</div><div>{clause_6.2.1.f}</div><div>La organización debe conservar la información documentada sobre los objetivos para el SGIA.</div>'),
    ('d5ebf7b0-1a55-4be8-a4fd-1318e4a107fc', 'e5d27b66-99b9-4ff2-a982-12a00264a16e', 'en', '', '<div>a) be consistent with the food safety policy</div>'),
    ('d2ebf2f7-6261-4abf-b542-e423d9a0f6ab', 'e5d27b66-99b9-4ff2-a982-12a00264a16e', 'es', '', '<div>a) ser conherentes con la polí­tica de inocuidad de los alimentos</div>'),
    ('3fe491ef-dc34-46e7-ba10-ebdbb558e283', 'f0d28cb7-e312-456f-8c20-1e83fd64998f', 'en', '', '<div>b) be measurable (if practicable)</div>'),
    ('32e47d78-e567-4680-8a79-11a0b058daa4', 'f0d28cb7-e312-456f-8c20-1e83fd64998f', 'es', '', '<div>b) ser medibles (si es posible)</div>'),
    ('95107bc6-28e9-4b3e-822c-8eeef8c75e9a', 'efd28b24-5ae9-4524-bd70-a066fc6497fc', 'en', '', '<div>c) take into account applicable food safety requirements, including statutory, regulatory and customer requirements</div>'),
    ('b210a96d-103d-412d-8465-ad21ddc73419', 'efd28b24-5ae9-4524-bd70-a066fc6497fc', 'es', '', '<div>c) tener en cuenta los requisitos aplicables de la inocuidad de los alimentos, incluyendo los requisitos legales, reglamentarios y de los clientes</div>'),
    ('8681727a-c3ea-44fe-aac7-a60af019856e', '76cb10e4-4c60-48e4-b62f-9972735d048c', 'en', '', '<div>d) be monitored and verified</div>'),
    ('6b8147f9-91f1-45ed-9081-a4d5dd196785', '76cb10e4-4c60-48e4-b62f-9972735d048c', 'es', '', '<div>d) ser objeto de seguimiento y verificación</div>'),
    ('b8e704e3-79f4-41a7-a58a-7997d0250797', '77cb1277-bb3e-472f-bff0-58ff745d061f', 'en', '', '<div>e) be communicated</div>'),
    ('b3e6fd04-80ad-4b40-b669-e864d3250c50', '77cb1277-bb3e-472f-bff0-58ff745d061f', 'es', '', '<div>e) ser comunicados </div>'),
    ('47451ab8-6932-4724-9ebc-1fe03d83882c', '78cb140a-2d06-449e-ab1b-5268755d07b2', 'en', '', '<div>f) be maintained and updated as appropriate.</div>'),
    ('54452f2f-7525-4a73-a432-b31b5283a93b', '78cb140a-2d06-449e-ab1b-5268755d07b2', 'es', '', '<div>f) ser mantenidos y actualizados según sea apropiado.</div>'),
    ('8d85f1a9-361d-4e9d-9400-2465f47c8c2d', '79cb159d-33ac-44d9-8c92-1945765d0945', 'en', '', '<div>When planning how to achieve its objectives for the FSMS, the organization shall determine:</div><div>{clause_6.2.2.a}</div><div>{clause_6.2.2.b}</div><div>{clause_6.2.2.c}</div><div>{clause_6.2.2.d}</div><div>{clause_6.2.2.e}</div>'),
    ('8885e9ca-a910-4a0e-a10f-f37ad77c5e86', '79cb159d-33ac-44d9-8c92-1945765d0945', 'es', '', '<div>Al planificar cómo lograr sus objetivos para el SGIA, la organización debe determinar:</div><div>{clause_6.2.2.a}</div><div>{clause_6.2.2.b}</div><div>{clause_6.2.2.c}</div><div>{clause_6.2.2.d}</div><div>{clause_6.2.2.e}</div>'),
    ('4e2a5da6-0485-4d7a-b868-ce4e0a4b6d22', '72cb0a98-c8fd-4ea0-b959-ed066f5cfe40', 'en', '', '<div>a) what will be done</div>'),
    ('6b2a8b4d-c8c6-49a1-9db9-c981ff4b5bd1', '72cb0a98-c8fd-4ea0-b959-ed066f5cfe40', 'es', '', '<div>a) qué se va a hacer </div>'),
    ('6c59ac4f-4a0e-4c93-b60d-873b1ad5c7eb', '73cb0c2b-ba8b-435b-9d25-2ea3705cffd3', 'en', '', '<div>b) what resources will be required</div>'),
    ('5f5997d8-59e3-4744-bd3b-0d0025d5d93c', '73cb0c2b-ba8b-435b-9d25-2ea3705cffd3', 'es', '', '<div>b) qué recursos se requerirán </div>'),
    ('b9b98d84-6589-4e40-9953-0e645854d3a0', '74cb0dbe-cfc1-490a-bb17-efdc715d0166', 'en', '', '<div>c) who will be responsible</div>'),
    ('beb99563-5ed0-44a7-8873-9f9775550147', '74cb0dbe-cfc1-490a-bb17-efdc715d0166', 'es', '', '<div>c) quién será responsable </div>'),
    ('532cc825-da43-4429-a536-3879eed6e3f1', '75cb0f51-f406-44b5-bd5e-3659725d02f9', 'en', '', '<div>d) when it will be completed</div>'),
    ('662ce60e-e7f2-4e32-850e-7f36f9d6f542', '75cb0f51-f406-44b5-bd5e-3659725d02f9', 'es', '', '<div>d) cuándo se finalizará</div>'),
    ('019e9812-7a34-48c6-afea-dc4257782976', '6ecb044c-eb6b-44cc-952f-3b8a7b5d1124', 'en', '', '<div>e) how the results will be evaluated.</div>'),
    ('169eb921-b97b-4a85-a12b-52dd547824bd', '6ecb044c-eb6b-44cc-952f-3b8a7b5d1124', 'es', '', '<div>e) cómo se evaluarán los resultados.</div>'),
    ('518860db-e748-4b2f-b055-fc0f3507af9f', '6fcb05df-9434-4b37-a44c-ef777c5d12b7', 'en', 'Planning of changes', '<div>When the organization determines the need for changes to the FSMS, including personnel changes, the changes shall be carried out and communicated in a planned manner.</div><div>The organization shall consider:</div><div>{clause_6.3.a}</div><div>{clause_6.3.b}</div><div>{clause_6.3.c}</div><div>{clause_6.3.d}</div>'),
    ('3c883fcc-fc0d-4078-a80c-3c6c4807cd88', '6fcb05df-9434-4b37-a44c-ef777c5d12b7', 'es', 'Planificación de los cambios', '<div>Cuando la organización determine la necesidad de cambios en el SGIA, incluidos los cambios de personal, estos cambios se deben llevar a cabo y comunicarse de manera planificada.</div><div>La organización debe considerar:</div><div>{clause_6.3.a}</div><div>{clause_6.3.b}</div><div>{clause_6.3.c}</div><div>{clause_6.3.d}</div>'),
    ('41c5f699-3260-4bcd-8c38-7175c156829d', 'fcce226d-68b7-41dd-8ed2-6675f9601615', 'en', '', '<div>a) the purpose of the changes and their potential consequences</div>'),
    ('5cc6211a-66d5-46de-837a-c42ac4568756', 'fcce226d-68b7-41dd-8ed2-6675f9601615', 'es', '', '<div>a) el propósito de los cambios y sus consecuencias potenciales </div>'),
    ('caa647e8-cca7-4a54-9cb8-fdf04a5de35c', 'fbce20da-f5a4-4a12-8770-81d8f8601482', 'en', '', '<div>b) the continued integrity of the FSMS</div>'),
    ('b7a629ff-794c-4d83-8a7e-11cb3f5dd20b', 'fbce20da-f5a4-4a12-8770-81d8f8601482', 'es', '', '<div>b) la continua integridad del SGIA</div>'),
    ('6fa172d3-a47d-4cd7-96c8-9e2769065987', 'face1f47-ad4f-4743-bc07-9f2ff76012ef', 'en', '', '<div>c) the availability of resources to effectively implement the changes</div>'),
    ('8aa19d54-0757-4a10-9d7b-3e944c062be0', 'face1f47-ad4f-4743-bc07-9f2ff76012ef', 'es', '', '<div>c) la disponibilidad de recursos para implementar eficazmente los cambios </div>'),
    ('3c9e0faa-644f-472e-975f-2bdabc55ab1e', 'f9ce1db4-3e4c-4c88-9755-ff22f660115c', 'en', '', '<div>d) the allocation or re-allocation of responsibilities and authorities.</div>'),
    ('419e1789-ee32-423d-bc46-e345c955bf95', 'f9ce1db4-3e4c-4c88-9755-ff22f660115c', 'es', '', '<div>d) la asignación o reasignación de responsabilidades y autoridades.</div>'),
    ('49483715-8426-48d9-ac48-b289fbb13f21', 'f8ce1c21-4670-4b21-a9bb-1989f5600fc9', 'en', 'Support', '<div>{clause_7.1}</div><div>{clause_7.2}</div><div>{clause_7.3}</div><div>{clause_7.4}</div><div>{clause_7.5}</div>'),
    ('3c48229e-edf5-4682-b22a-4e26e6b11e12', 'f8ce1c21-4670-4b21-a9bb-1989f5600fc9', 'es', 'Apoyo', '<div>{clause_7.1}</div><div>{clause_7.2}</div><div>{clause_7.3}</div><div>{clause_7.4}</div><div>{clause_7.5}</div>'),
    ('afd4fc74-bdc2-4bb0-81bb-48b4648fcb10', 'f7ce1a8e-6907-4b26-8442-668cf4600e36', 'en', 'Resources', '<div>{clause_7.1.1}</div><div>{clause_7.1.2}</div><div>{clause_7.1.3}</div><div>{clause_7.1.4}</div><div>{clause_7.1.5}</div><div>{clause_7.1.6}</div>'),
    ('94d4d1f3-4416-4277-b3db-4fc7618fc657', 'f7ce1a8e-6907-4b26-8442-668cf4600e36', 'es', 'Recursos', '<div>{clause_7.1.1}</div><div>{clause_7.1.2}</div><div>{clause_7.1.3}</div><div>{clause_7.1.4}</div><div>{clause_7.1.5}</div><div>{clause_7.1.6}</div>'),
    ('af1ca3ff-d9d0-4f03-9b07-1bcb2710bf5b', 'f6ce18fb-1a6d-4c97-abc9-7793f3600ca3', 'en', 'General', '<div>The organization shall determine and provide the resources needed for the establishment, implementation, maintenance, update and continual improvement of the FSMS.</div><div>The organization shall consider:</div><div>{clause_7.1.1.a}</div><div>{clause_7.1.1.b}</div>'),
    ('c21cc1e8-2d2a-4bd4-ad42-07f012109e4c', 'f6ce18fb-1a6d-4c97-abc9-7793f3600ca3', 'es', 'Generalidades', '<div>La organización debe determinar y proporcionar los recursos necesarios para el establecimiento, implementación, mantenimiento, actualización y mejora continua del SGIA.</div><div>La organización debe considerar: </div><div>{clause_7.1.1.a}</div><div>{clause_7.1.1.b}</div>'),
    ('426ac756-643b-4eaa-b589-391ed726f692', 'f5ce1768-a111-43ac-91e7-2976f2600b10', 'en', '', '<div>a) the capability of, and any constraints on, existing internal resources </div>'),
    ('3f6ac29d-82bf-4631-ab80-fd71ec2717a1', 'f5ce1768-a111-43ac-91e7-2976f2600b10', 'es', '', '<div>a) la capacidad de, y toda limitación sobre, los recursos internos existentes </div>'),
    ('dc43ead1-630a-4155-9e02-86ed28b526a5', 'f4ce15d5-a9ab-4395-89bd-922d016022ad', 'en', '', '<div>b) the need for external resources.</div>'),
    ('e743fc22-69c2-47b6-bd4e-11723bb5448e', 'f4ce15d5-a9ab-4395-89bd-922d016022ad', 'es', '', '<div>b) la necesidad de recursos externos.</div>'),
    ('43477180-f9f7-435c-b84e-44488f41ec04', 'f3ce1442-55fa-4a6a-8824-d5700060211a', 'en', 'People', '<div>The organization shall ensure that persons necessary to operate and maintain an effective FSMS are competent (see 7.2).</div><div>Where the assistance of external experts is used for the development, implementation, operation or assessment of the FSMS, evidence of agreement or contracts defining the competency, responsibility and authority of external experts shall be retained as documented information.</div>'),
    ('60479f27-811b-4f5b-8b48-b7b39441f3e3', 'f3ce1442-55fa-4a6a-8824-d5700060211a', 'es', 'Personas', '<div>La organización debe asegurar que las personas necesarias para operar y mantener un SGIA eficaz, sean competentes (véase 7.2).</div><div>Cuando se utilice la asistencia de expertos externos para el desarrollo, implementación, operación o evaluación del SGIA, se debe conservar como información documentada la evidencia de acuerdos o contratos que definan la competencia, responsabilidad y autoridad de dichos expertos externos.</div>'),
    ('7caef2e4-9f2e-424c-80ad-6ec4c2458610', '6ac680d2-2bac-432a-9892-97fc8758a6da', 'en', 'Infrastructure', '<div>The organization shall provide the resources for the determination, establishment and maintenance of the infrastructure necessary to achieve conformity with the requirements of the FSMS.</div><div>NOTE Infrastructure can include:</div><div>— land, vessels, buildings and associated utilities</div><div>— equipment, including hardware and software</div><div>— transportation</div><div>— information and communication technology.</div>'),
    ('81aefac3-9f8b-472b-a6d8-16f7bf458157', '6ac680d2-2bac-432a-9892-97fc8758a6da', 'es', 'Infraestructura', '<div>La organización debe proporcionar los recursos para la determinación, establecimiento y mantenimiento de la infraestructura necesaria para lograr la conformidad con los requisitos del SGIA.</div><div>NOTA La infraestructura puede incluir:</div><div>— terrenos, embarcaciones, edificios y servicios asociados</div><div>— equipos, incluyendo hardware y software</div><div>— transporte</div><div>— tecnologí­as de la información y la comunicación.</div>'),
    ('13a7c485-bab0-4845-8b70-ebd95966fa21', '6bc68265-7f5e-4c55-af90-cc798858a86d', 'en', 'Work environment', '<div>The organization shall determine, provide and maintain the resources for the establishment, management and maintenance of the work environment necessary to achieve conformity with the requirements of the FSMS.</div><div>NOTE A suitable environment can be a combination of human and physical factors such as:</div><div>{clause_7.1.4.a}</div><div>{clause_7.1.4.b}</div><div>{clause_7.1.4.c}</div><div>These factors can differ substantially depending on the products and services provided.</div>'),
    ('26a7e26e-7de3-4c86-8cf9-4b964466d912', '6bc68265-7f5e-4c55-af90-cc798858a86d', 'es', 'Ambiente de trabajo', '<div>La organización debe determinar, proporcionar y mantener los recursos para el establecimiento, la gestión y el mantenimiento del ambiente de trabajo necesario para lograr la conformidad con los requisitos del SGIA.</div><div>NOTA Un ambiente adecuado puede ser una combinación de factores humanos y fí­sicos, como:</div><div>{clause_7.1.4.a}</div><div>{clause_7.1.4.b}</div><div>{clause_7.1.4.c}</div><div>Estos factores pueden diferir sustancialmente dependiendo de los productos y servicios suministrados.</div>'),
    ('0ea6ed06-837e-4ba6-bc74-b42e34dcb192', '68c67dac-3e34-4ac0-a913-28268558a3b4', 'en', '', '<div>a) social (e.g. non-discriminatory, calm, non-confrontational)</div>'),
    ('2ba71aad-efb8-44e5-9906-586149dcd2a1', '68c67dac-3e34-4ac0-a913-28268558a3b4', 'es', '', '<div>a) sociales (por ejemplo, no discriminatorio, tranquilo, sin confrontación)</div>'),
    ('bbf6ff2f-5fd7-4c0f-828f-e11b84c67a5b', '69c67f3f-2fc4-427b-8c9d-66438658a547', 'en', '', '<div>b) psychological (e.g. stress-reducing, burnout prevention, emotionally protective)</div>'),
    ('aef6eab8-6ef5-4ed8-bd19-4de06fc6594c', '69c67f3f-2fc4-427b-8c9d-66438658a547', 'es', '', '<div>b) psicológicos (por ejemplo, prevención del agotamiento, reducción del estrés, protección emocional)</div>'),
    ('96e0da98-fcf2-4588-bf5a-90c0a8139e5c', '66c67a86-9f0f-443e-9d9b-6b888358a08e', 'en', '', '<div>c) physical (e.g. temperature, heat, humidity, light, air flow, hygiene, noise).</div>'),
    ('a3e0ef0f-44ff-445f-8a3a-a4fb9d138d0b', '66c67a86-9f0f-443e-9d9b-6b888358a08e', 'es', '', '<div>c) fí­sicos (por ejemplo, temperatura, calor, humedad, iluminación, circulación de aire, higiene, ruido). </div>'),
    ('4e028109-2490-4ed1-a14d-e8c51f0c3d9d', '67c67c19-bf02-4979-9da8-87e58458a221', 'en', 'Externally developed elements of the food safety management system', '<div>When an organization establishes, maintains, updates and continually improves its FSMS by using externally developed elements of a FSMS, including PRPs, the hazard analysis and the hazard control plan (see 8.5.4), the organization shall ensure that the provided elements are:</div><div>{clause_7.1.5.a}</div><div>{clause_7.1.5.b}</div><div>{clause_7.1.5.c}</div><div>{clause_7.1.5.d}</div><div>{clause_7.1.5.e}</div>'),
    ('4902792a-1ea6-48ca-bc66-315a220c4256', '67c67c19-bf02-4979-9da8-87e58458a221', 'es', 'Elementos del sistema de gestión de la inocuidad de los alimentos desarrollados externamente', '<div>Cuando una organización establece, mantiene, actualiza y mejora continuamente su SGIA utilizando elementos de un SGIA desarrollados externamente, incluidos los PPR, el análisis de peligros y el plan de control de peligros (véase 8.5.4), la organización debe asegurarse de que los elementos proporcionados sean:</div><div>{clause_7.1.5.a}</div><div>{clause_7.1.5.b}</div><div>{clause_7.1.5.c}</div><div>{clause_7.1.5.d}</div><div>{clause_7.1.5.e}</div>'),
    ('49786ada-9339-45a2-a3ae-786a1a0b661e', '64c67760-c199-4804-b009-6c9281589d68', 'en', '', '<div>a) developed in conformance with requirements of this document</div>'),
    ('2e784059-3f89-4079-9186-58b5270b7a95', '64c67760-c199-4804-b009-6c9281589d68', 'es', '', '<div>a) desarrollados de conformidad con los requisitos de este documento </div>'),
    ('0882c4c3-b53e-47fb-b121-9277c6bc1487', '65c678f3-3075-434f-9306-d89f82589efb', 'en', '', '<div>b) applicable to the sites, processes and products of the organization</div>'),
    ('0382bce4-14cc-43fc-8af6-ea44a9bbe6e0', '65c678f3-3075-434f-9306-d89f82589efb', 'es', '', '<div>b) aplicables a los sitios, procesos y productos de la organización</div>'),
    ('3552143c-e1c2-4b04-bca1-47bc7a833438', '72c68d6a-e71c-4dd2-b02d-02747f589a42', 'en', '', '<div>c) specifically adapted to the processes and products of the organization by the food safety team</div>'),
    ('2a5202eb-d468-4953-9f48-4c3f878348af', '72c68d6a-e71c-4dd2-b02d-02747f589a42', 'es', '', '<div>c) adaptados especí­ficamente a los procesos y productos de la organización por el equipo de inocuidad de los alimentos</div>'),
    ('3b6b76fd-ab80-45fd-a31b-b0d1c0c40b29', '73c68efd-5a2e-459d-a707-ebd180589bd5', 'en', '', '<div>d) implemented, maintained and updated as required by this document</div>'),
    ('3e6b7bb6-219e-4aee-94e9-9efebbc4034a', '73c68efd-5a2e-459d-a707-ebd180589bd5', 'es', '', '<div>d) implementados, mantenidos y actualizados según lo requerido por este documento </div>'),
    ('6dffaa2b-5d1a-41e3-92f7-3eff7d768277', '70c8c8db-9fe8-47cb-a3f1-26076d5abc83', 'en', '', '<div>e) retained as documented information.</div>'),
    ('78ffbb7c-c419-4e34-aa69-537c80768730', '70c8c8db-9fe8-47cb-a3f1-26076d5abc83', 'es', '', '<div>e) conservados como información documentada.</div>'),
    ('5d76e262-6ce8-450a-8f37-e3b29d6c934e', '6fc8c748-ae58-4010-8c17-d19a6c5abaf0', 'en', 'Control of externally provided processes, products or services', '<div>The organization shall:</div><div>{clause_7.1.6.a}</div><div>{clause_7.1.6.b}</div><div>{clause_7.1.6.c}</div><div>{clause_7.1.6.d}</div>'),
    ('5276d111-754d-4711-95d2-b42d8a6c7565', '6fc8c748-ae58-4010-8c17-d19a6c5abaf0', 'es', 'Control de procesos, productos o servicios proporcionados externamente', '<div>La organización debe: </div><div>{clause_7.1.6.a}</div><div>{clause_7.1.6.b}</div><div>{clause_7.1.6.c}</div><div>{clause_7.1.6.d}</div>'),
    ('4200c631-7387-4a39-9ad0-16cd15293f8d', '72c8cc01-ef82-41a5-8953-234d6f5abfa9', 'en', '', '<div>a) establish and apply criteria for the evaluation, selection, monitoring of performance and reevaluation of external providers of processes, products and/or services</div>'),
    ('4d00d782-e084-4762-b8e1-10d2f82911e6', '72c8cc01-ef82-41a5-8953-234d6f5abfa9', 'es', '', '<div>a) establecer y aplicar criterios para la evaluación, selección, seguimiento del desempeño y reevaluación de proveedores externos de procesos, productos y/o servicios</div>'),
    ('a9044ce0-165e-4110-807f-f9a85e303b8c', '71c8ca6e-b5bb-4e3a-b0ca-47906e5abe16', 'en', '', '<div>b) ensure adequate communication of requirements to the external provider(s)</div>'),
    ('c6047a87-b384-43d7-ab85-7f9373305c9b', '71c8ca6e-b5bb-4e3a-b0ca-47906e5abe16', 'es', '', '<div>b) garantizar una comunicación adecuada de los requisitos a los proveedores externos</div>'),
    ('20d480d7-1339-4ab7-abf4-0783c828d5cb', '74c8cf27-a099-489f-88de-84cb715ac2cf', 'en', '', '<div>c) ensure that externally provided processes, products or services do not adversely affect the organization''s ability to consistently meet the requirements of the FSMS</div>'),
    ('23d48590-7398-4ef0-b61e-7e78d328e71c', '74c8cf27-a099-489f-88de-84cb715ac2cf', 'es', '', '<div>c) asegurar que los procesos, productos o servicios proporcionados externamente no afecten adversamente la capacidad de la organización de cumplir regularmente los requisitos del SGIA</div>'),
    ('4344faae-53b1-4b8e-b43e-dc562af82082', '73c8cd94-31bd-4d54-8b65-e14e705ac13c', 'en', '', '<div>d) retain documented information of these activities and any necessary actions as a result of the evaluations and re-evaluations.</div>'),
    ('3044dcc5-e0bf-401d-836c-ec991ff80f31', '73c8cd94-31bd-4d54-8b65-e14e705ac13c', 'es', '', '<div>d) conservar información documentada de estas actividades y todas las acciones necesarias como resultado de las evaluaciones y reevaluaciones. </div>'),
    ('47a8016d-3b0e-452d-9553-2a210f820451', '76c8d24d-1906-4649-aeef-4681735ac5f5', 'en', 'Competence', '<div>The organization shall:</div><div>{clause_7.2.a}</div><div>{clause_7.2.b}</div><div>{clause_7.2.c}</div><div>{clause_7.2.d}</div><div>{clause_7.2.e}</div><div>NOTE: Applicable actions can include, for example, the provision of training to, the mentoring of, or the reassignment of currently employed persons or the hiring or contracting of competent persons.</div>'),
    ('2aa7d3c6-53bb-4f3e-931a-0bee1a8215a2', '76c8d24d-1906-4649-aeef-4681735ac5f5', 'es', 'Competencia', '<div>La organización debe: </div><div>{clause_7.2.a}</div><div>{clause_7.2.b}</div><div>{clause_7.2.c}</div><div>{clause_7.2.d}</div><div>{clause_7.2.e}</div><div>NOTA: Las acciones aplicables pueden incluir, por ejemplo, la formación, la tutorí­a o la reasignación de las personas empleadas actualmente o la contratación o subcontratación de personas competentes.</div>'),
    ('8e34946c-8ee0-4834-a5f1-a48c76858b00', '75c8d0ba-0f35-4c8e-a94d-cb24725ac462', 'en', '', '<div>a) determine the necessary competence of person(s), including external providers, doing work under its control that affects its food safety performance and effectiveness of the FSMS</div>'),
    ('a334b57b-27e0-4be3-b294-252f9385b8a7', '75c8d0ba-0f35-4c8e-a94d-cb24725ac462', 'es', '', '<div>a) determinar la competencia necesaria de las personas, incluyendo los proveedores externos, que realizan bajo su control, un trabajo que afecta al desempeño y eficacia del SGIA</div>'),
    ('d2e3e533-46a7-4c6b-8859-e887e25abd7f', '68c8bc43-f652-41d3-bab7-8dcf755ac91b', 'en', '', '<div>b) ensure that these persons, including the food safety team and those responsible for the operation of the hazard control plan, are competent on the basis of appropriate education, training and/or experience</div>'),
    ('ede40fb4-6212-458c-ad5b-fe74f55adb68', '68c8bc43-f652-41d3-bab7-8dcf755ac91b', 'es', '', '<div>b) asegurarse de que estas personas, incluido el equipo de inocuidad de los alimentos y aquellos que son responsables por la operación del plan de control de peligros, sean competentes, basándose en la educación, formación o experiencia apropiadas</div>'),
    ('a259580a-ea26-4d12-808a-74ba75a8e0d6', '67c8bab0-8420-4798-9d9f-a9c2745ac788', 'en', '', '<div>c) ensure that the food safety team has a combination of multi-disciplinary knowledge and experience in developing and implementing the FSMS (including, but not limited to, the organization’s products, processes, equipment and food safety hazards within the scope of the FSMS)</div>'),
    ('a7595fe9-d9fc-4a09-8a34-3ca572a8dc1d', '67c8bab0-8420-4798-9d9f-a9c2745ac788', 'es', '', '<div>c) asegurarse que el equipo de inocuidad de los alimentos tenga una combinación de conocimiento multidisciplinario y experiencia en el desarrollo e implementación del SGIA (incluyendo, pero no limitado a, los productos, procesos, equipos y peligros relacionados con la inocuidad de los alimentos de la organización dentro del alcance del SGIA) </div>'),
    ('0f81205e-829a-4a02-a279-6f6628f60b0a', 'dec12740-380b-48e8-bfbc-74fefb534d48', 'en', '', '<div>d) where applicable, take actions to acquire the necessary competence, and evaluate the effectiveness of the actions taken </div>'),
    ('1c8134d5-18cb-4c59-b36c-fbc92df612e9', 'dec12740-380b-48e8-bfbc-74fefb534d48', 'es', '', '<div>d) cuando corresponda, tomar medidas para adquirir la competencia necesaria y evaluar la eficacia de las acciones tomadas</div>'),
    ('b9b765c7-a49e-495b-9eb5-53d359809833', 'dfc128d3-c05b-48a3-a8a2-fe3bfc534edb', 'en', '', '<div>e) retain appropriate documented information as evidence of competence.</div>'),
    ('9cb73820-1d7a-4d5c-87b3-93e87480c2b4', 'dfc128d3-c05b-48a3-a8a2-fe3bfc534edb', 'es', '', '<div>e) conservar la información documentada apropiada como evidencia de la competencia. </div>'),
    ('9b0eef9c-043e-40e8-b4bc-251c2a57e8c8', 'e0c12a66-1ece-40f2-aeb2-8494fd53506e', 'en', 'Awareness', '<div>The organization shall ensure that all relevant persons doing work under the organization’s control shall be aware of:</div><div>{clause_7.3.a}</div><div>{clause_7.3.b}</div><div>{clause_7.3.c}</div><div>{clause_7.3.d}</div>'),
    ('900ede4b-4c4b-4fbf-b0b6-3e9f1757cadf', 'e0c12a66-1ece-40f2-aeb2-8494fd53506e', 'es', 'Toma de conciencia', '<div>La organización debe asegurarse que las personas pertinentes que realizan trabajos bajo el control de la organización deben tomar conciencia de:</div><div>{clause_7.3.a}</div><div>{clause_7.3.b}</div><div>{clause_7.3.c}</div><div>{clause_7.3.d}</div>'),
    ('1481f7dd-e943-45b1-997c-df31a1792a79', 'e1c12bf9-7895-46bd-aeeb-ea71fe535201', 'en', '', '<div>a) the food safety policy</div>'),
    ('1781fc96-cabf-4e2a-b2a1-63debc7954fa', 'e1c12bf9-7895-46bd-aeeb-ea71fe535201', 'es', '', '<div>a) la polí­tica de la inocuidad de los alimentos</div>'),
    ('27d66fd2-e4e5-4206-8f36-a3022ec455b6', 'e2c12d8c-9ad0-400c-9c92-10caff535394', 'en', '', '<div>b) the objectives of the FSMS relevant to their task(s)</div>'),
    ('3cd690e1-21b2-4dc5-ade4-009d2bc450fd', 'e2c12d8c-9ad0-400c-9c92-10caff535394', 'es', '', '<div>b) los objetivos del SGIA pertinentes a sus tareas</div>'),
    ('7a3c349b-4f7e-4b6f-9d11-0bcf0ece44df', 'e3c12f1f-2a4a-4e77-9514-45b700535527', 'en', '', '<div>c) their individual contribution to the effectiveness of the FSMS, including the benefits of improved food safety performance</div>'),
    ('653c138c-4af8-4eb8-8867-a92c21ce62c8', 'e3c12f1f-2a4a-4e77-9514-45b700535527', 'es', '', '<div>c) su contribución individual a la eficacia del SGIA, incluyendo los beneficios de una mejora del desempeño de la inocuidad de los alimentos</div>'),
    ('b540d750-7d2e-4e2c-b2b0-f7b80f883054', 'e4c130b2-9233-4506-9808-6080015356ba', 'en', '', '<div>d) the implications of not conforming with the FSMS requirements.</div>'),
    ('b240d297-61c4-450b-beb4-dec3f48805d3', 'e4c130b2-9233-4506-9808-6080015356ba', 'es', '', '<div>d) las implicaciones del incumplimiento de los requisitos del SGIA.</div>'),
    ('4edb2161-aa12-4ca5-ac00-f41d33275c75', 'e5c13245-402d-4481-a941-3f3d0253584d', 'en', 'Communication', '<div>{clause_7.4.1}</div><div>{clause_7.4.2}</div><div>{clause_7.4.3}</div>'),
    ('39db0052-5725-4866-8d53-9682262747fe', 'e5c13245-402d-4481-a941-3f3d0253584d', 'es', 'Comunicación', '<div>{clause_7.4.1}</div><div>{clause_7.4.2}</div><div>{clause_7.4.3}</div>'),
    ('7463c866-c52d-4fba-9440-a80ee4139562', 'e6c133d8-75e6-4de0-9b9c-5946f35340b0', 'en', 'General', '<div>The organization shall determine the internal and external communications relevant to the FSMS, including:</div><div>{clause_7.4.1.a}</div><div>{clause_7.4.1.b}</div><div>{clause_7.4.1.c}</div><div>{clause_7.4.1.d}</div><div>{clause_7.4.1.e}</div><div>The organization shall ensure that the requirement for effective communication is understood by all persons whose activities have an impact on food safety.</div>'),
    ('9163f60d-6da7-4de1-9917-ba41d9138411', 'e6c133d8-75e6-4de0-9b9c-5946f35340b0', 'es', 'Generalidades', '<div>La organización debe determinar las comunicaciones internas y externas pertinentes al SGIA, que incluyan:</div><div>{clause_7.4.1.a}</div><div>{clause_7.4.1.b}</div><div>{clause_7.4.1.c}</div><div>{clause_7.4.1.d}</div><div>{clause_7.4.1.e}</div><div>La organización debe asegurar que todas las personas cuyas actividades tengan un impacto en la inocuidad de los alimentos, entiendan el requisito de una comunicación eficaz.</div>'),
    ('950bed0f-b4c0-48d3-94b0-f4fbf49c5d2b', 'e7c1356b-69f0-4e9b-8216-91e3f4534243', 'en', '', '<div>a) on what it will communicate</div>'),
    ('880bd898-c21b-4a84-89d0-e0c0ff9c6e7c', 'e7c1356b-69f0-4e9b-8216-91e3f4534243', 'es', '', '<div>a) qué comunicar </div>'),
    ('0a9d66cd-bdd5-47e1-bb0c-2c013a5a7c69', '64c438c9-add7-40d1-94fe-8ca101559551', 'en', '', '<div>b) when to communicate</div>'),
    ('ed9d3926-155b-49ba-95bb-30ce355a748a', '64c438c9-add7-40d1-94fe-8ca101559551', 'es', '', '<div>b) cuándo comunicar</div>'),
    ('5129f9cc-620a-4b98-a50b-31ecf6940e78', '63c43736-ffdc-4156-808e-35c4005593be', 'en', '', '<div>c) with whom to communicate</div>'),
    ('662a1adb-5073-42cf-ad54-f18f039422ef', '63c43736-ffdc-4156-808e-35c4005593be', 'es', '', '<div>c) a quién comunicar</div>'),
    ('7071d3b7-bc0a-43cb-a0b3-fd6365bb8fa3', '62c435a3-b142-42c7-b727-346bff55922b', 'en', '', '<div>d) how to communicate </div>'),
    ('7371d870-d774-4cec-944d-bd5860bb87c4', '62c435a3-b142-42c7-b727-346bff55922b', 'es', '', '<div>d) cómo comunicar </div>'),
    ('9067e48e-fc3b-40f2-a4bc-ef3635d0663a', '61c43410-0919-401c-91d5-b2eefe559098', 'en', '', '<div>e) who communicates.</div>'),
    ('7d67c6a5-d2c4-48e9-84e4-a8791ad03bb9', '61c43410-0919-401c-91d5-b2eefe559098', 'es', '', '<div>e) quién comunica.</div>'),
    ('04f7be91-cafa-4695-bcd7-78ad000152e5', '68c43f15-d0bd-4b4d-9f5e-486d05559b9d', 'en', 'External communication', '<div>The organization shall ensure that sufficient information is communicated externally and is available for interested parties of the food chain.</div><div>The organization shall establish, implement and maintain effective communications with:</div><div>{clause_7.4.2.a}</div><div>{clause_7.4.2.b}</div><div>{clause_7.4.2.c}</div><div>{clause_7.4.2.d}</div><div>Designated persons shall have defined responsibility and authority for the external communication of any information concerning food safety. Where relevant, information obtained through external communication shall be included as input for management review (see 9.3) and for updating the FSMS (see 4.4 and 10.3).</div><div>Evidence of external communication shall be retained as documented information.</div>'),
    ('0ff7cfe2-b867-4af6-b63c-a832130170ce', '68c43f15-d0bd-4b4d-9f5e-486d05559b9d', 'es', 'Comunicación externa', '<div>La organización debe asegurar que la información comunicada externamente es suficiente y se encuentra disponible para las partes interesadas de la cadena alimentaria. </div><div>La organización debe establecer, implementar y mantener una comunicación eficaz con:</div><div>{clause_7.4.2.a}</div><div>{clause_7.4.2.b}</div><div>{clause_7.4.2.c}</div><div>{clause_7.4.2.d}</div><div>El personal designado debe tener definida la responsabilidad y autoridad para comunicar externamente toda información concerniente a la inocuidad de los alimentos. Cuando sea pertinente, la información obtenida mediante comunicación externa debe ser incluida como elemento de entrada para la revisión por la dirección (véase 9.3) y para la actualización del SGIA (véanse 4.4 y 10.3).</div><div>Se debe conservar como información documentada la evidencia de comunicación externa.</div>'),
    ('6bfb4540-48e1-419c-b6b8-8a0869088144', '67c43d82-8c79-4042-a25a-ecb004559a0a', 'en', '', '<div>a) external providers and contractors</div>'),
    ('88fb72e7-ebcd-4b9b-8285-a5736e088923', '67c43d82-8c79-4042-a25a-ecb004559a0a', 'es', '', '<div>a) los proveedores y contratistas</div>'),
    ('bd9cfd0b-ef9e-429f-9fa9-7adf1ba8a00f', '66c43bef-2e05-44f3-aac7-d72703559877', 'en', '', '<div>b) customers and/or consumers, in relation to:</div><ul><li>{clause_7.4.2.b.1}</li><li>{clause_7.4.2.b.2}</li><li>{clause_7.4.2.b.3}</li><li>{clause_7.4.2.b.4}</li></ul>'),
    ('c89d0e5c-a516-47c8-a6a0-4f5c0ea88b98', '66c43bef-2e05-44f3-aac7-d72703559877', 'es', '', '<div>b) los clientes y/o consumidores, en relación con:</div><ul><li>{clause_7.4.2.b.1}</li><li>{clause_7.4.2.b.2}</li><li>{clause_7.4.2.b.3}</li><li>{clause_7.4.2.b.4}</li></ul>'),
    ('1df371c2-8a4c-4a76-b7b5-d912fb007b66', '65c43a5c-a5b5-4538-8ca9-25ba025596e4', 'en', '', '<div>1) product information related to food safety, to enable the handling, display, storage, preparation, distribution and use of the product within the food chain or by the consumer</div>'),
    ('12f36071-9cdf-4615-affa-af0d1800a90d', '65c43a5c-a5b5-4538-8ca9-25ba025596e4', 'es', '', '<div>1) la información del producto relacionada con la inocuidad de los alimentos que facilite la manipulación, presentación, almacenamiento, preparación, distribución y uso del producto dentro de la cadena alimentaria o por parte del consumidor </div>'),
    ('6f81a1d5-2b82-4619-94be-6d49d577d461', '6cc44561-376c-4469-a098-74c9f95588b9', 'en', '', '<div>2) identified foods safety hazards that need to be controlled by other organizations in the food chain and/or by consumers</div>'),
    ('62818d5e-ac25-42c2-83ca-e0e6c077b352', '6cc44561-376c-4469-a098-74c9f95588b9', 'es', '', '<div>2) la identificación de los peligros relacionados con la inocuidad de los alimentos que necesitan ser controlados por otras organizaciones en la cadena alimentaria y/o consumidores</div>'),
    ('d888d034-b3f4-4cf0-b658-de743bdd8a50', '6bc443ce-30c7-472e-9a48-64ccf8558726', 'en', '', '<div>3) contractual arrangements, enquiries and orders, including their amendments </div>'),
    ('bd88a5b3-5395-48b7-9156-c88738dd8597', '6bc443ce-30c7-472e-9a48-64ccf8558726', 'es', '', '<div>3) los arreglos contractuales, consultas y pedidos incluyendo sus modificaciones </div>'),
    ('2b62d178-8a62-4b80-8e99-16a01f2868ec', 'f2e3d8fe-b8f3-48de-a290-d9a8ef4ebd36', 'en', '', '<div>4) customer and/or consumer feedback, including complaints</div>'),
    ('3862e5ef-812f-4be7-be30-f0db342889fb', 'f2e3d8fe-b8f3-48de-a290-d9a8ef4ebd36', 'es', '', '<div>4) la retroalimentación de clientes y/o consumidores, incluyendo quejas</div>'),
    ('6f293f69-5559-4569-b435-a825d89bd5ed', 'f3e3da91-bf98-4619-9215-ac85f04ebec9', 'en', '', '<div>c) statutory and regulatory authorities </div>'),
    ('6a29378a-7ecf-4d72-aa8b-e03abb9ba846', 'f3e3da91-bf98-4619-9215-ac85f04ebec9', 'es', '', '<div>c) las autoridades legales y reglamentarias, y </div>'),
    ('6a9f293a-f15a-45ba-aa3c-5ccad438cf2e', 'f0e3d5d8-d5d3-4424-bfe9-e5b2ed4eba10', 'en', '', '<div>d) other organizations that have an impact on, or will be affected by, the effectiveness or updating of the FSMS.</div>'),
    ('4f9efeb9-99d4-43e1-a878-8795c138b145', 'f0e3d5d8-d5d3-4424-bfe9-e5b2ed4eba10', 'es', '', '<div>d) otras organizaciones que tienen un impacto en, o son afectadas por, la eficacia o la actualización del sistema del SGIA.</div>'),
    ('9a8a52a3-e0ed-4ed3-80da-5757b1c85557', 'f1e3d76b-5dfc-446f-ab71-9f3fee4ebba3', 'en', 'Internal communication', '<div>The organization shall establish, implement and maintain an effective system for communicating issues having an impact on food safety.</div><div>To maintain the effectiveness of the FSMS, the organization shall ensure that the food safety team is informed in a timely manner of changes in the following:</div><div>{clause_7.4.3.a}</div><div>{clause_7.4.3.b}</div><div>{clause_7.4.3.c}</div><div>{clause_7.4.3.d}</div><div>{clause_7.4.3.e}</div><div>{clause_7.4.3.f}</div><div>{clause_7.4.3.g}</div><div>{clause_7.4.3.h}</div><div>{clause_7.4.3.i}</div><div>{clause_7.4.3.j}</div><div>{clause_7.4.3.k}</div><div>{clause_7.4.3.l}</div><div>{clause_7.4.3.m}</div><div>The food safety team shall ensure that this information is included when updating the FSMS (see 4.4 and 10.3).</div><div>Top management shall ensure that relevant information is included as input to the management review (see 9.3).</div>'),
    ('958a4ac4-ee47-4084-b346-6e24b4c85a10', 'f1e3d76b-5dfc-446f-ab71-9f3fee4ebba3', 'es', 'Comunicación interna', '<div>La organización debe establecer, implementar y mantener un sistema eficaz para las cuestiones de comunicación que tienen impacto en la inocuidad de los alimentos. </div><div>Con el fin de mantener la eficacia del SGIA, la organización debe asegurarse que se informa oportunamente al equipo de la inocuidad de los alimentos sobre los cambios realizados a lo siguiente, entre otros: </div><div>{clause_7.4.3.a}</div><div>{clause_7.4.3.b}</div><div>{clause_7.4.3.c}</div><div>{clause_7.4.3.d}</div><div>{clause_7.4.3.e}</div><div>{clause_7.4.3.f}</div><div>{clause_7.4.3.g}</div><div>{clause_7.4.3.h}</div><div>{clause_7.4.3.i}</div><div>{clause_7.4.3.j}</div><div>{clause_7.4.3.k}</div><div>{clause_7.4.3.l}</div><div>{clause_7.4.3.m}</div><div>El equipo de la inocuidad de los alimentos debe asegurarse que esta información sea incluida en la actualización del SGIA (véanse 4.4 y 10.3).</div><div>La alta dirección debe asegurarse que la información pertinente sea incluida como información de entrada para la revisión por la dirección (véase 9.3).</div>'),
    ('9dd74444-fd4f-4264-962f-942439f82160', 'f6e3df4a-5bae-4d4a-a7ed-381cf34ec382', 'en', '', '<div>a) products or new products</div>'),
    ('a2d74c23-eff6-43b3-a3c3-7d5756f84f07', 'f6e3df4a-5bae-4d4a-a7ed-381cf34ec382', 'es', '', '<div>a) productos o productos nuevos</div>'),
    ('34d015e5-587d-45dd-b25a-3f39d2f49ab1', 'f7e3e0dd-9940-4df5-9899-d199f44ec515', 'en', '', '<div>b) raw materials, ingredients and services</div>'),
    ('47d033ce-e4ba-434e-b2e1-c5f6ddf4ac02', 'f7e3e0dd-9940-4df5-9899-d199f44ec515', 'es', '', '<div>b) materias primas, ingredientes y servicios</div>'),
    ('2fcf3e66-3f00-463e-993b-0e0eee6ab6e2', 'f4e3dc24-6bbb-4be0-a9aa-af46f14ec05c', 'en', '', '<div>c) production systems and equipment</div>'),
    ('4ccf6c0d-2653-4c2d-9e12-2041e36aa591', 'f4e3dc24-6bbb-4be0-a9aa-af46f14ec05c', 'es', '', '<div>c) sistemas de producción y equipos </div>'),
    ('5077630f-f24b-41e7-99ab-5afbfef37eab', 'f5e3ddb7-5fc5-4c9b-9024-e7e3f24ec1ef', 'en', '', '<div>d) production premises, location of equipment and surrounding environment</div>'),
    ('43774e98-fb7e-4180-8ecb-46c009f38ffc', 'f5e3ddb7-5fc5-4c9b-9024-e7e3f24ec1ef', 'es', '', '<div>d) locales de producción, ubicación de los equipos, entorno circundante </div>'),
    ('70ac4d50-306b-46e8-b7ab-5db819df51d4', 'eae3cc66-8808-4306-a616-b680f74ec9ce', 'en', '', '<div>e) cleaning and sanitation programmes</div>'),
    ('6dac4897-7877-45bf-83af-44c3fedf2753', 'eae3cc66-8808-4306-a616-b680f74ec9ce', 'es', '', '<div>e) programas de limpieza y desinfección </div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('0a469761-1570-4bb1-b0fb-5a1d3d7e7df5', 'ebe3cdf9-3603-4281-b74f-953df84ecb61', 'en', '', '<div>f) packaging, storage and distribution systems</div>'),
    ('f5467652-f6ec-442a-924d-fc82307e697e', 'ebe3cdf9-3603-4281-b74f-953df84ecb61', 'es', '', '<div>f) sistemas de embalaje, almacenamiento y distribución</div>'),
    ('933a5abf-c957-4d17-ad1a-7c8b7a2bb893', '78e6ea87-b801-413f-8920-a0d3f551053f', 'en', '', '<div>g) competencies and/or allocation of responsibilities and authorizations</div>'),
    ('a63a78a8-29b6-4150-bf83-8cb0952be314', '78e6ea87-b801-413f-8920-a0d3f551053f', 'es', '', '<div>g) competencias y/o asignación de responsabilidades y autorizaciones </div>'),
    ('268a1116-f86c-426e-9b49-48de49a2be6a', '77e6e8f4-5f44-4e74-8e9e-d3b6f45103ac', 'en', '', '<div>h) applicable statutory and regulatory requirements</div>'),
    ('238a0c5d-824e-4d7d-8224-c4314ea2c649', '77e6e8f4-5f44-4e74-8e9e-d3b6f45103ac', 'es', '', '<div>h) requisitos legales y reglamentarios aplicables</div>'),
    ('2aed17d5-7087-410d-99b8-d3494ecc3859', '7ae6edad-2d41-4269-aea6-cac9f7510865', 'en', '', '<div>i) knowledge regarding food safety hazards and control measures</div>'),
    ('1ded035e-a27f-401e-88c5-46e669cc62da', '7ae6edad-2d41-4269-aea6-cac9f7510865', 'es', '', '<div>i) conocimientos relativos a los peligros relacionados con la inocuidad de los alimentos y medidas de control </div>'),
    ('93f44634-44fd-4794-bb53-4474d5308da8', '79e6ec1a-269d-452e-a856-baccf65106d2', 'en', '', '<div>j) customer, sector and other requirements that the organization observes</div>'),
    ('78f41bb3-f41d-43c3-9651-2e87c2306fbf', '79e6ec1a-269d-452e-a856-baccf65106d2', 'es', '', '<div>j) requisitos del cliente, del sector y otros requisitos que la organización tiene en cuenta</div>'),
    ('5144c093-fea8-4c43-b53e-7ce7bc2152bf', '74e6e43b-b750-406b-89c5-896ff150fef3', 'en', '', '<div>k) relevant enquiries and communications from external interested parties</div>'),
    ('6c44eb14-4f88-4014-97c5-ca54cf2170a8', '74e6e43b-b750-406b-89c5-896ff150fef3', 'es', '', '<div>k) comunicaciones y consultas pertinentes de las partes interesadas externas </div>'),
    ('20bbc66a-f858-49ea-81be-469a4f710916', '73e6e2a8-dbe0-4130-92b8-7c62f050fd60', 'en', '', '<div>l) complaints and alerts indicating food safety hazards associated with the end product</div>'),
    ('25bbce49-1463-4b71-ae7e-70054c71045d', '73e6e2a8-dbe0-4130-92b8-7c62f050fd60', 'es', '', '<div>l) quejas y alertas que indiquen peligros relacionados con la inocuidad de los alimentos, asociados con el producto terminado</div>'),
    ('25e54059-57af-4c19-aaed-fa3553d40fd5', '76e6e761-06ea-4a45-9430-36b5f3510219', 'en', '', '<div>m) other conditions that have an impact on food safety.</div>'),
    ('40e56ada-d852-48c2-bd16-19ea46d3fb5e', '76e6e761-06ea-4a45-9430-36b5f3510219', 'es', '', '<div>m) otras condiciones que tengan un impacto en la inocuidad de los alimentos.</div>'),
    ('ac4995a8-e021-42f0-aefa-82b0bcdb3e34', '75e6e5ce-b3d8-44da-b8c1-1218f2510086', 'en', 'Documented information', '<div>{clause_7.5.1}</div><div>{clause_7.5.2}</div><div>{clause_7.5.3}</div>'),
    ('994977bf-7fc2-4eb7-9c91-728ba1db13b3', '75e6e5ce-b3d8-44da-b8c1-1218f2510086', 'es', 'Información documentada', '<div>{clause_7.5.1}</div><div>{clause_7.5.2}</div><div>{clause_7.5.3}</div>'),
    ('2bdd49b7-1bcb-489f-a5ae-6363a1ef6b0b', '70e6ddef-a718-40c7-8535-8a6bfd5111d7', 'en', 'General', '<div>The organization’s FSMS shall include:</div><div>{clause_7.5.1.a}</div><div>{clause_7.5.1.b}</div><div>{clause_7.5.1.c}</div><div>NOTE: The extent of documented information for a FSMS can differ from one organization to another due to:</div><div>— the size of organization and its type of activities, processes, products and services</div><div>— the complexity of processes and their interactions</div><div>— the competence of persons.</div>'),
    ('2edd4e70-d143-4dc8-9948-2358acef7c5c', '70e6ddef-a718-40c7-8535-8a6bfd5111d7', 'es', 'Generalidades', '<div>El SGIA de la organización debe incluir: </div><div>{clause_7.5.1.a}</div><div>{clause_7.5.1.b}</div><div>{clause_7.5.1.c}</div><div>NOTA La extensión de la información documentada para un SGIA puede variar de una organización a otra, debido a: </div><div>— el tamaño de la organización y sus tipos de actividades, procesos, productos y servicios</div><div>— la complejidad de los procesos y sus interacciones y</div><div>— la competencia de las personas.</div>'),
    ('4bd35a8e-b679-4076-a9b7-55360245dfc2', '6fe6dc5c-feee-4e1c-9fe4-08eefc511044', 'en', '', '<div>a) documented information required by this document</div>'),
    ('38d33ca5-c90c-4c15-89df-0e79f745ce71', '6fe6dc5c-feee-4e1c-9fe4-08eefc511044', 'es', '', '<div>a) la información documentada requerida por este documento </div>'),
    ('496dcd93-b6f3-4233-bf15-51e7967828c7', '8439044b-ece3-456f-ad23-a66f7f8dc373', 'en', '', '<div>b) documented information determined by the organization as being necessary for the effectiveness of the FSMS</div>'),
    ('646df814-c44c-40e4-a19c-9f547977fb20', '8439044b-ece3-456f-ad23-a66f7f8dc373', 'es', '', '<div>b) la información documentada que la organización determina como necesaria para la eficacia del SGIA</div>'),
    ('18e4d36a-2e20-411a-8b95-1b9aec41e35e', '833902b8-64ba-4524-b616-99627e8dc1e0', 'en', '', '<div>c) documented information and food safety requirements required by statutory, regulatory authorities and customers.</div>'),
    ('1de4db49-d914-4841-b855-4505f941f7d5', '833902b8-64ba-4524-b616-99627e8dc1e0', 'es', '', '<div>c) la información documentada y los requisitos de inocuidad de los alimentos requeridos por las autoridades legales, reglamentarias y los clientes.</div>'),
    ('1e0e4d59-03de-47c9-b4c4-cf35f142badd', '86390771-4e7e-4719-b78e-53b5818dc699', 'en', 'Creating and updating', '<div>When creating and updating documented information, the organization shall ensure appropriate:</div><div>{clause_7.5.2.a}</div><div>{clause_7.5.2.b}</div><div>{clause_7.5.2.c}</div>'),
    ('390e77da-1408-4ad2-86ec-eeeaf442bf96', '86390771-4e7e-4719-b78e-53b5818dc699', 'es', 'Creación y actualización', '<div>Al crear y actualizar la información documentada, la organización debe asegurarse que lo siguiente sea apropiado:</div><div>{clause_7.5.2.a}</div><div>{clause_7.5.2.b}</div><div>{clause_7.5.2.c}</div>'),
    ('a472a2a8-cff2-47e0-b8d1-57b077cfb29c', '853905de-47d9-49de-9c1f-2f18808dc506', 'en', '', '<div>a) identification and description (e.g. a title, date, author, or reference number)</div>'),
    ('917284bf-c93a-4147-a668-478b6ccfa14b', '853905de-47d9-49de-9c1f-2f18808dc506', 'es', '', '<div>a) la identificación y descripción (por ejemplo, tí­tulo, fecha, autor o número de referencia)</div>'),
    ('8b6367bf-3a56-4747-b6f1-518b56fcf79b', '88390a97-eeac-4d9b-ac7e-bdd3838dc9bf', 'en', '', '<div>b) format (e.g. language, software version, graphics) and media (e.g. paper, electronic)</div>'),
    ('9e6385a8-410e-4de0-895a-61b041fcd68c', '88390a97-eeac-4d9b-ac7e-bdd3838dc9bf', 'es', '', '<div>b) el formato (por ejemplo, idioma, versión de los softwares, gráficos) y los medios de soporte (por ejemplo, papel, electrónico) </div>'),
    ('1eb31e16-1833-461e-a520-1dde049732d2', '87390904-faa2-4ce0-b1fc-f0b6828dc82c', 'en', '', '<div>c) review and approval for suitability and adequacy.</div>'),
    ('1bb3195d-e63a-470d-8bfb-9931199753e1', '87390904-faa2-4ce0-b1fc-f0b6828dc82c', 'es', '', '<div>c) la revisión y aprobación con respecto a la pertinencia y adecuación.</div>'),
    ('231624d5-5c8d-48bd-a38f-a8492b9be461', '8a390dbd-2826-4ef5-9204-e7c9858dcce5', 'en', 'Control of documented information', '<div>{clause_7.5.3.1}</div><div>{clause_7.5.3.2}</div>'),
    ('1616105e-d2ab-4dae-929c-1be6169bc352', '8a390dbd-2826-4ef5-9204-e7c9858dcce5', 'es', 'Control de la información documentada', '<div>{clause_7.5.3.1}</div><div>{clause_7.5.3.2}</div>'),
    ('8c1d5334-3c90-46c4-852a-197492019a50', '89390c2a-ea94-4e4a-8bb4-d7cc848dcb52', 'en', '', '<div>Documented information required by the FSMS and by this document shall be controlled to ensure:</div><div>{clause_7.5.3.1.a}</div><div>{clause_7.5.3.1.b}</div>'),
    ('711d28b3-2cbb-4c13-a028-03878f019597', '89390c2a-ea94-4e4a-8bb4-d7cc848dcb52', 'es', '', '<div>La información documentada requerida por el SGIA y por este documento se debe controlar para asegurarse que: </div><div>{clause_7.5.3.1.a}</div><div>{clause_7.5.3.1.b}</div>'),
    ('7131800b-2958-48bb-ae7a-b5df71ccb00f', '7c38f7b3-af06-4d77-9c34-4a27878dd00b', 'en', '', '<div>a) it is available and suitable for use, where and when it is needed</div>'),
    ('7c31915c-866d-4ebc-b571-8a5c64cc9b98', '7c38f7b3-af06-4d77-9c34-4a27878dd00b', 'es', '', '<div>a) esté disponible y sea idónea para su uso, dónde y cuándo se necesite </div>'),
    ('d187f4c2-5d4c-4262-8687-141251248b66', '7b38f620-1f8c-4f0c-be15-98ba868dce78', 'en', '', '<div>b) it is adequately protected (e.g. from loss of confidentiality, improper use, or loss of integrity).</div>'),
    ('c687e371-f04f-4539-becb-ea0d6e24b90d', '7b38f620-1f8c-4f0c-be15-98ba868dce78', 'es', '', '<div>b) esté protegida adecuadamente (por ejemplo, contra pérdida de la confidencialidad, uso inadecuado o pérdida de integridad).</div>'),
    ('ee6a7dec-12f3-4b5c-87a6-2a0c85c50fe0', '7e36bc42-40d9-4ace-955c-2ca4198ae44a', 'en', '', '<div>For the control of documented information, the organization shall address the following activities, as applicable: </div><div>{clause_7.5.3.2.a}</div><div>{clause_7.5.3.2.b}</div><div>{clause_7.5.3.2.c}</div><div>{clause_7.5.3.2.d}</div><div>Documented information of external origin determined by the organization to be necessary for the planning and operation of the FSMS shall be identified, as appropriate, and controlled.</div><div>Documented information retained as evidence of conformity shall be protected from unintended alterations.</div><div>NOTE: Access can imply a decision regarding the permission to view the documented information only, or the permission and authority to view and change the documented information.</div>'),
    ('036a9efb-9a18-475b-9448-aaafa2c53d87', '7e36bc42-40d9-4ace-955c-2ca4198ae44a', 'es', '', '<div>Para el control de la información documentada, la organización debe abordar las siguientes actividades, según sea aplicable:&nbsp</div><div>{clause_7.5.3.2.a}</div><div>{clause_7.5.3.2.b}</div><div>{clause_7.5.3.2.c}</div><div>{clause_7.5.3.2.d}</div><div>La información documentada de origen externo, que la organización determina como necesaria para la planificación y operación del SGIA, se debe identificar, según sea apropiado, y controlar. </div><div>La información documentada conservada como evidencia de la conformidad debe protegerse contra modificaciones no intencionales.</div><div>NOTA: El acceso puede implicar una decisión en relación al permiso, solamente para consultar la información documentada, o al permiso y a la autoridad para consultar y modificar la información documentada.</div>'),
    ('a7ddeaed-7c06-4955-b707-afa11ec18931', '7f36bdd5-3160-4289-9afd-a8011a8ae5dd', 'en', '', '<div>a) distribution, access, retrieval and use</div>'),
    ('8addbd46-82bf-4fb6-b4ce-916e29c19a82', '7f36bdd5-3160-4289-9afd-a8011a8ae5dd', 'es', '', '<div>a) la distribución, acceso, recuperación y uso</div>'),
    ('a37ae42e-aa9c-4836-95f3-61d63a37a562', '7c36b91c-4a15-4694-b774-42ce178ae124', 'en', '', '<div>b) storage and preservation, including preservation of legibility</div>'),
    ('907ac645-a3e3-41d5-a521-72192f379411', '7c36b91c-4a15-4694-b774-42ce178ae124', 'es', '', '<div>b) el almacenamiento y preservación, incluida la preservación de la legibilidad </div>'),
    ('810a6a57-613e-4a5f-8da8-8d034ac06d2b', '7d36baaf-d23e-46df-b4ec-e64b188ae2b7', 'en', '', '<div>c) control of changes (e.g. version control)</div>'),
    ('840a6f10-1932-4b88-97d3-03f855c07e7c', '7d36baaf-d23e-46df-b4ec-e64b188ae2b7', 'es', '', '<div>c) el control de los cambios (por ejemplo, control de versión)</div>'),
    ('093a3660-d3ab-4658-a234-7f286af5576c', '7a36b5f6-ce14-4a7a-9cd8-a910158addfe', 'en', '', '<div>d) retention and disposition.</div>'),
    ('263a6407-c48d-438f-8d3a-05137ff5787b', '7a36b5f6-ce14-4a7a-9cd8-a910158addfe', 'es', '', '<div>d) la conservación y disposición.</div>'),
    ('a236afb1-87e8-44a1-bc84-9c4d2468c46d', '7b36b789-2126-4fe5-b561-84cd168adf91', 'en', 'Operation', '<div>{clause_8.1}</div><div>{clause_8.2}</div><div>{clause_8.3}</div><div>{clause_8.4}</div><div>{clause_8.5}</div><div>{clause_8.6}</div><div>{clause_8.7}</div><div>{clause_8.8}</div><div>{clause_8.9}</div>'),
    ('ad36c102-c3a7-487a-9a95-9652076896c6', '7b36b789-2126-4fe5-b561-84cd168adf91', 'es', 'Operación', '<div>{clause_8.1}</div><div>{clause_8.2}</div><div>{clause_8.3}</div><div>{clause_8.4}</div><div>{clause_8.5}</div><div>{clause_8.6}</div><div>{clause_8.7}</div><div>{clause_8.8}</div><div>{clause_8.9}</div>'),
    ('bdaccbe2-aa87-4fb2-b0ec-69322005bdae', '7836b2d0-c6b2-4c50-b826-331a138adad8', 'en', 'Operational planning and control', '<div>The organization shall plan, implement, control, maintain and update the processes needed to meet requirements for the realization of safe products, and to implement the actions determined in 6.1, by:</div><div>{clause_8.1.a}</div><div>{clause_8.1.b}</div><div>{clause_8.1.c}</div><div>The organization shall control planned changes and review the consequences of unintended changes, taking action to mitigate any adverse effects, as necessary.</div><div>The organization shall ensure that outsourced processes are controlled (see 7.1.6).</div>'),
    ('b2acba91-9cd8-45a9-b787-39ad0d059fc5', '7836b2d0-c6b2-4c50-b826-331a138adad8', 'es', 'Planificación y control operacional', '<div>La organización debe planificar, implementar, controlar, mantener y actualizar los procesos necesarios para cumplir los requisitos para la realización de productos inocuos, y para implementar las acciones determinadas en el apartado 6.1, mediante: </div><div>{clause_8.1.a}</div><div>{clause_8.1.b}</div><div>{clause_8.1.c}</div><div>La organización debe controlar los cambios planificados y revisar las consecuencias de los cambios no previstos, tomando acciones para mitigar todo efecto adverso, cuando sea necesario.</div><div>La organización debe asegurarse que los procesos contratados externamente estén controlados (véase 7.1.6).</div>'),
    ('ce3593ab-2daa-4b8b-b4ab-c47ffd9543d7', '7936b463-d18c-460b-8fff-8787148adc6b', 'en', '', '<div>a) establishing criteria for the processes</div>'),
    ('d935a4fc-4914-44ac-8c1d-d8fc00954890', '7936b463-d18c-460b-8fff-8787148adc6b', 'es', '', '<div>a) el establecimiento de criterios para los procesos</div>'),
    ('e92166d4-e5a4-4254-a178-6794807bf8c8', '8636c8da-e2fe-4376-846a-cdac118ad7b2', 'en', '', '<div>b) implementing control of the processes in accordance with the criteria</div>'),
    ('ce213c53-9249-4583-9ac5-c7276d7bdadf', '8636c8da-e2fe-4376-846a-cdac118ad7b2', 'es', '', '<div>b) la implementación del control de los procesos de acuerdo con los criterios</div>'),
    ('0cc092f5-4b5d-43cd-a482-8969f79d3a79', '8736ca6d-bdea-4771-a254-c9a9128ad945', 'en', '', '<div>c) keeping documented information to the extent necessary to have the confidence to demonstrate that the processes have been carried out as planned.</div>'),
    ('ffc07e7e-7fd2-4ede-962b-3486129d64fa', '8736ca6d-bdea-4771-a254-c9a9128ad945', 'es', '', '<div>c) el mantenimiento de la información documentada en la extensión necesaria para tener la confianza para demostrar que los procesos se han llevado a cabo según lo planificado.</div>'),
    ('88d16d35-5ae4-4071-b1fa-d7a973ae14b9', 'f833aab9-b37d-4395-8c15-8f6913889c41', 'en', 'Prerequisite programmes (PRPs)', '<div>{clause_8.2.1}</div><div>{clause_8.2.2}</div><div>{clause_8.2.3}</div><div>{clause_8.2.4}</div>'),
    ('7bd158be-3ed9-4eea-abd6-e7c68eae3f3a', 'f833aab9-b37d-4395-8c15-8f6913889c41', 'es', 'Programas de prerrequisitos. PPR', '<div>{clause_8.2.1}</div><div>{clause_8.2.2}</div><div>{clause_8.2.3}</div><div>{clause_8.2.4}</div>'),
    ('62b7d814-75de-48a8-b900-d3d4fa13fd08', 'f733a926-5fcb-4a6a-8958-646c12889aae', 'en', '', '<div>The organization shall establish, implement, maintain and update PRP(s) to facilitate the prevention and/or reduction of contaminants (including food safety hazards) in the products, product processing and work environment.</div>'),
    ('47b7ad93-bdec-4a7f-9679-8667e713df1f', 'f733a926-5fcb-4a6a-8958-646c12889aae', 'es', '', '<div>La organización debe establecer, implementar, mantener y actualizar PPR para facilitar la prevención y/o reducción de contaminantes (incluyendo peligros relacionados con la inocuidad de los alimentos) en los productos y sus procesos y en el ambiente de trabajo.</div>'),
    ('61ff7f9f-7172-4a1b-ac18-b46b2bb58273', 'f633a793-63e3-49bb-bf0d-82f31188991b', 'en', '', '<div>The PRP(s) shall be:</div><div>{clause_8.2.2.a}</div><div>{clause_8.2.2.b}</div><div>{clause_8.2.2.c}</div><div>{clause_8.2.2.d}</div>'),
    ('74ff9d88-ce87-401c-afb6-6a9046b5acf4', 'f633a793-63e3-49bb-bf0d-82f31188991b', 'es', '', '<div>Los PPR deben:</div><div>{clause_8.2.2.a}</div><div>{clause_8.2.2.b}</div><div>{clause_8.2.2.c}</div><div>{clause_8.2.2.d}</div>'),
    ('846ff976-a2ec-4ac2-ade5-183efb2c884a', 'f533a600-5906-4d00-b15c-8e5610889788', 'en', '', '<div>a) appropriate to the organization and its context with regard to food safety</div>'),
    ('816ff4bd-2249-4e19-8a49-1611002c9029', 'f533a600-5906-4d00-b15c-8e5610889788', 'es', '', '<div>a) ser apropiados para la organización y su contexto en relación a la inocuidad de los alimentos</div>'),
    ('f7233b39-1bb1-4465-9989-f695055c46b5', 'fc33b105-d9d4-4bb9-b998-f2d51788a28d', 'en', '', '<div>b) appropriate to the size and type of the operation and the nature of the products being manufactured and/or handled</div>'),
    ('122365ba-af78-4b26-9b4d-cbcaf85c323e', 'fc33b105-d9d4-4bb9-b998-f2d51788a28d', 'es', '', '<div>b) ser apropiados al tamaño y al tipo de operación, y a la naturaleza de los productos que se elaboran y/o manipulan</div>'),
    ('7d892388-86ad-42ec-aa11-cf90df42b194', 'fb33af72-d330-4e7e-b593-a3b81688a0fa', 'en', '', '<div>c) implemented across the entire production system, either as programmes applicable in general or as programmes applicable to a particular product or process</div>'),
    ('6a89059f-6b43-49cb-a674-196bc4428713', 'fb33af72-d330-4e7e-b593-a3b81688a0fa', 'es', '', '<div>c) implementarse a través de todo el sistema de producción, tanto como programas de aplicación en general o como programas aplicables a un producto o proceso en particular</div>'),
    ('af2aa8f3-0045-432f-aa15-c247de8a591f', 'fa33addf-6494-4a8f-beaa-340f15889f67', 'en', '', '<div>d) approved by the food safety team.</div>'),
    ('ca2ad374-150a-4878-b7f5-bb34f18a7708', 'fa33addf-6494-4a8f-beaa-340f15889f67', 'es', '', '<div>d) ser aprobados por el equipo de la inocuidad de los alimentos.</div>'),
    ('7ea1aeca-9331-40c6-bb40-407a00fad2f6', 'f933ac4c-dc6b-4a44-a3cc-f60214889dd4', 'en', '', '<div>When selecting and/or establishing PRP(s), the organization shall ensure that applicable statutory, regulatory and mutually agreed customer requirements are identified. The organization should consider:</div><div>{clause_8.2.3.a}</div><div>{clause_8.2.3.b}</div>'),
    ('83a1b6a9-d277-4285-ae30-7165fdface3d', 'f933ac4c-dc6b-4a44-a3cc-f60214889dd4', 'es', '', '<div>Cuando se seleccionan y/o establecen los PPR, la organización debe asegurar que se identifican los requisitos legales y reglamentarios aplicables y los requisitos mutuamente acordados con el cliente. La organización deberí­a considerar: </div><div>{clause_8.2.3.a}</div><div>{clause_8.2.3.b}</div>'),
    ('21745c2d-f340-4c29-8ba8-5ae198598d71', '0033b751-7288-41dd-b6ea-dac10b888fa9', 'en', '', '<div>a) the applicable part of the ISO/TS 22002 series</div>'),
    ('04742e86-00ef-4632-af16-b6aea3599ec2', '0033b751-7288-41dd-b6ea-dac10b888fa9', 'es', '', '<div>a) la parte aplicable de la serie ISO/TS 22002</div>'),
    ('6a7b582c-7e86-4640-8b4d-b14c01d77d20', 'ff33b5be-ff75-4a12-a739-cc640a888e16', 'en', '', '<div>b) applicable standards, codes of practice and guidelines.</div>'),
    ('7f7b793b-77cc-4ca7-a37f-99ef1ed7aac7', 'ff33b5be-ff75-4a12-a739-cc640a888e16', 'es', '', '<div>b) las normas, códigos de práctica y directrices aplicables. </div>'),
    ('eaef43c6-0323-4512-ae80-96eea24a081a', 'f23162b0-3d38-475c-a7d5-e8660d865438', 'en', '', '<div>When establishing PRP(s) the organization shall consider:</div><div>{clause_8.2.4.a}</div><div>{clause_8.2.4.b}</div><div>{clause_8.2.4.c}</div><div>{clause_8.2.4.d}</div><div>{clause_8.2.4.e}</div><div>{clause_8.2.4.f}</div><div>{clause_8.2.4.g}</div><div>{clause_8.2.4.h}</div><div>{clause_8.2.4.i}</div><div>{clause_8.2.4.j}</div><div>{clause_8.2.4.k}</div><div>{clause_8.2.4.l}</div><div>Documented information shall specify the selection, establishment, applicable monitoring and verification of the PRP(s).</div>'),
    ('07ef716d-f2f9-4209-b0b9-b5218749dd99', 'f23162b0-3d38-475c-a7d5-e8660d865438', 'es', '', '<div> La organización debe considerar lo siguiente al establecer los PPR:</div><div>{clause_8.2.4.a}</div><div>{clause_8.2.4.b}</div><div>{clause_8.2.4.c}</div><div>{clause_8.2.4.d}</div><div>{clause_8.2.4.e}</div><div>{clause_8.2.4.f}</div><div>{clause_8.2.4.g}</div><div>{clause_8.2.4.h}</div><div>{clause_8.2.4.i}</div><div>{clause_8.2.4.j}</div><div>{clause_8.2.4.k}</div><div>{clause_8.2.4.l}</div><div>La información documentada debe especificar la selección, el establecimiento, el seguimiento aplicable y la verificación de los PPR. </div>'),
    ('95c359ef-5fa4-446b-a664-f3db5edb8c03', 'f3316443-cc15-4507-b685-66830e8655cb', 'en', '', '<div>a) construction, lay-out of buildings and associated utilities</div>'),
    ('88c34578-7b0e-4d8c-b6cd-19a059db8424', 'f3316443-cc15-4507-b685-66830e8655cb', 'es', '', '<div>a) la construcción y la distribución de los edificios y las instalaciones relacionadas</div>'),
    ('567ce0a4-05a5-4f38-b7b4-a384ed39a1d8', 'f43165d6-1ab0-4696-94be-4a3c0f86575e', 'en', '', '<div>b) lay-out of premises, including zoning, workspace and employee facilities</div>'),
    ('5b7ce883-0a2c-4bef-a78a-bcb7fa39b64f', 'f43165d6-1ab0-4696-94be-4a3c0f86575e', 'es', '', '<div>b) la distribución de los locales, incluyendo el establecimiento de zonas de trabajo y las instalaciones para los empleados </div>'),
    ('eff01b45-393b-4401-89aa-0b99a6d41e49', 'f5316769-e1f8-4b11-9af2-5bb9108658f1', 'en', '', '<div>c) supplies of air, water, energy and other utilities</div>'),
    ('02f0392e-74fb-4ada-ba7b-fb56a1d4166a', 'f5316769-e1f8-4b11-9af2-5bb9108658f1', 'es', '', '<div>c) los suministros de aire, agua, energí­a y otros servicios </div>'),
    ('25bf2e9a-1957-4616-ae44-db2a677a1d46', 'f63168fc-d9d4-4c78-b60f-8bd211865a84', 'en', '', '<div>d) pest control, waste and sewage disposal and supporting services</div>'),
    ('0abf0419-fc7e-4435-b702-8875847a4aed', 'f63168fc-d9d4-4c78-b60f-8bd211865a84', 'es', '', '<div>d) los servicios de control de plagas, desechos y aguas residuales y servicios de apoyo</div>'),
    ('e250b283-9338-433f-bcb8-a737124e336f', 'f7316a8f-48d9-4a33-b124-27df12865c17', 'en', '', '<div>e) the suitability of equipment and its accessibility for cleaning and maintenance</div>'),
    ('dd50aaa4-4b2c-4468-8ce2-8e04054e1ef8', 'f7316a8f-48d9-4a33-b124-27df12865c17', 'es', '', '<div>e) la idoneidad del equipamiento y su accesibilidad para la limpieza, el mantenimiento</div>'),
    ('70aec858-bf0d-40bc-a717-a080d307ba24', 'f8316c22-a74c-4282-96b2-31c813865daa', 'en', '', '<div>f) supplier approval and assurance processes (e.g. raw materials, ingredients, chemicals and packaging)</div>'),
    ('7daedccf-61f8-4abb-9fea-1abbd807c203', 'f8316c22-a74c-4282-96b2-31c813865daa', 'es', '', '<div>f) los procesos de aprobación y aseguramiento de proveedores (por ejemplo, materias primas, ingredientes, productos quí­micos y envases)</div>'),
    ('2a4944c9-2a98-44b5-9d5c-4a856c7af4c5', 'f9316db5-04de-458d-8466-292514865f3d', 'en', '', '<div>g) reception of incoming materials, storage, dispatch, transportation and handling of products</div>'),
    ('25493cea-4772-4696-b09c-211a7f7b12ae', 'f9316db5-04de-458d-8466-292514865f3d', 'es', '', '<div>g) la recepción de materiales entrantes, almacenamiento, despacho, transporte y manipulación de productos</div>'),
    ('1036fa3e-85e4-4d0a-b139-b2c6a7931f32', 'fa316f48-81c8-4cb4-a20d-9f9e058647a0', 'en', '', '<div>h) measures for the prevention of cross contamination</div>'),
    ('1d370eb5-8e4a-4f11-b75d-a2a9bc934041', 'fa316f48-81c8-4cb4-a20d-9f9e058647a0', 'es', '', '<div>h) las medidas para prevenir la contaminación cruzada</div>'),
    ('30414e27-7616-49e3-b1eb-6db3f9f8e3fb', 'fb3170db-f3d2-447f-bfa5-fedb06864933', 'en', '', '<div>i) cleaning and disinfecting</div>'),
    ('13412080-dd16-4634-9ef0-fa48e4f8c2ec', 'fb3170db-f3d2-447f-bfa5-fedb06864933', 'es', '', '<div>i) la limpieza y desinfección</div>'),
    ('cc8f95cf-a94f-4e3f-97c2-0cbb13f5c44b', 'fc42bb8f-d8b4-44e3-8933-90231797ad17', 'en', '', '<div>j) personal hygiene</div>'),
    ('bf8f8158-6142-4f68-9eef-92801ef5d59c', 'fc42bb8f-d8b4-44e3-8933-90231797ad17', 'es', '', '<div>j) la higiene del personal </div>'),
    ('ae604726-2f6d-4116-9a1d-53ce76c50f02', 'fb42b9fc-69b0-4728-a568-4e861697ab84', 'en', '', '<div>k) product information/consumer awareness</div>'),
    ('cb6074cd-1294-4f35-bf6e-4f016bc4fdb1', 'fb42b9fc-69b0-4728-a568-4e861697ab84', 'es', '', '<div>k) la información del producto/concientización del consumidor </div>'),
    ('b362b1a5-40af-4fb5-86ea-bdf95b4ef2d1', 'fe42beb5-acb4-4dfd-a96c-97d91997b03d', 'en', '', '<div>l) others, as appropriate.</div>'),
    ('c662cf8e-5d88-4196-a6c3-04b6664f0422', 'fe42beb5-acb4-4dfd-a96c-97d91997b03d', 'es', '', '<div>l) otros aspectos según sea apropiado.</div>'),
    ('19ef7704-d523-4bbc-bb07-93e4c2527980', 'fd42bd22-3728-4d32-a726-515c1897aeaa', 'en', 'Traceability system', '<div>The traceability system shall be able to uniquely identify incoming material from the suppliers and the first stage of the distribution route of the end product. When establishing and implementing the traceability system, the following shall be considered as a minimum:</div><div>{clause_8.3.a}</div><div>{clause_8.3.b}</div><div>{clause_8.3.c}</div><div>The organization shall ensure that applicable statutory, regulatory and customer requirements are identified.</div><div>Documented information as evidence of the traceability system shall be retained for a defined period to include, as a minimum, the shelf life of the product. The organization shall verify and test the effectiveness of the traceability system.</div><div>NOTE: Where appropriate, the verification of the system is expected to include the reconciliation of quantities of end products with the quantity of ingredients as evidence of effectiveness.</div>'),
    ('1eef7ee3-780e-45bb-aa28-2517df52a727', 'fd42bd22-3728-4d32-a726-515c1897aeaa', 'es', 'Sistema de trazabilidad', '<div>El sistema de trazabilidad debe poder identificar de manera única el material entrante de los proveedores y la primera etapa de la ruta de distribución del producto terminado. Al establecer e implementar el sistema de trazabilidad se debe considerar como mí­nimo lo siguiente:</div><div>{clause_8.3.a}</div><div>{clause_8.3.b}</div><div>{clause_8.3.c}</div><div>La organización debe asegurarse que se identifiquen los requisitos del cliente y los requisitos legales y reglamentarios aplicables. </div><div>Se debe conservar la información documentada como evidencia del sistema de trazabilidad durante un perí­odo de tiempo definido que incluya como mí­nimo la vida útil del producto. La organización debe verificar y probar la eficacia del sistema de trazabilidad.</div><div>NOTA: Cuando corresponda, se espera que la verificación del sistema incluya la conciliación de las cantidades de productos terminados con la cantidad de ingredientes como evidencia de la eficacia. </div>'),
    ('191cee63-75bb-4f6b-873e-ff17c94370f7', 'f842b543-5bf0-4fb7-abfe-ba7f1397a6cb', 'en', '', '<div>a) relation of lots of received materials, ingredients and intermediate products to the end products</div>'),
    ('141ce684-9125-488c-981e-6de4cc4375b0', 'f842b543-5bf0-4fb7-abfe-ba7f1397a6cb', 'es', '', '<div>a) la relación de lotes de materiales recibidos, ingredientes y productos intermedios hasta los productos terminados </div>'),
    ('e6b75bfa-1939-4012-8c7c-2b8ae93981ce', 'f742b3b0-b328-494c-a23d-faf21297a538', 'en', '', '<div>b) reworking of materials/products</div>'),
    ('cbb73179-090f-4d09-b236-2a55d63963e5', 'f742b3b0-b328-494c-a23d-faf21297a538', 'es', '', '<div>b) el reproceso de materiales/productos </div>'),
    ('edbbdb29-4f51-4f01-b5b4-a9e560f62e0d', 'fa42b869-5887-40c1-b8a0-7ac51597a9f1', 'en', '', '<div>c) distribution of the end product.</div>'),
    ('e8bbd34a-8b12-45da-82c4-78fa43f60066', 'fa42b869-5887-40c1-b8a0-7ac51597a9f1', 'es', '', '<div>c) la distribución del producto terminado.</div>'),
    ('a77b0438-1bbc-4a38-8070-a560a9fd2a0c', 'f942b6d6-aa8c-4146-9729-b3e81497a85e', 'en', 'Emergency preparedness and response', '<div>{clause_8.4.1}</div><div>{clause_8.4.2}</div>'),
    ('b47b18af-2042-46ef-85e7-389bbefd4b1b', 'f942b6d6-aa8c-4146-9729-b3e81497a85e', 'es', 'Preparación y respuesta ante emergencias', '<div>{clause_8.4.1}</div><div>{clause_8.4.2}</div>'),
    ('f3b3e487-424c-4db7-a9c0-f993eeac7ad3', '0442c827-8248-47db-a8b0-e97b0f97a07f', 'en', 'General', '<div>Top management shall ensure procedures are in place to respond to potential emergency situations or incidents that can have an impact on food safety which are relevant to the role of the organization in the food chain.</div><div>Documented information shall be established and maintained to manage these situations and incidents.</div>'),
    ('d6b3b6e0-a2ab-41f0-bebb-73a809aca554', '0442c827-8248-47db-a8b0-e97b0f97a07f', 'es', 'Generalidades', '<div>La alta dirección debe asegurar que los procedimientos para responder a situaciones de emergencia potenciales o incidentes que pueden afectar a la inocuidad de los alimentos y que son pertinentes a la función de la organización en la cadena alimentaria, están disponibles.</div><div>Se debe establecer y mantener información documentada para gestionar estas situaciones e incidentes.</div>'),
    ('4703361e-82c4-4e8e-bd71-d126bba917aa', '0342c694-90ba-4320-b97f-db3e0e979eec', 'en', 'Handling of emergencies and incidents', '<div>The organization shall:</div><div>{clause_8.4.2.a}</div><div>{clause_8.4.2.b}</div><div>{clause_8.4.2.c}</div><div>{clause_8.4.2.d}</div><div>NOTE: Examples of emergency situations that can affect food safety and/or production are natural disasters, environmental accidents, bioterrorism, workplace accidents, public health emergencies and other accidents, e.g. interruption of essential services such as water, electricity or refrigeration supply.</div>'),
    ('54034a95-0fd2-431d-b790-3589c0a91f89', '0342c694-90ba-4320-b97f-db3e0e979eec', 'es', 'Gestión de emergencias e incidentes', '<div>La organización debe:</div><div>{clause_8.4.2.a}</div><div>{clause_8.4.2.b}</div><div>{clause_8.4.2.c}</div><div>{clause_8.4.2.d}</div><div>NOTA: Ejemplos de situaciones de emergencia que pueden afectar la inocuidad y/o producción de los alimentos son los desastres naturales, accidentes ambientales, bioterrorismo, accidentes en el lugar de trabajo, emergencias de salud pública y otros accidentes como la interrupción de servicios esenciales como agua, electricidad o suministro de refrigeración.</div>'),
    ('db3ede88-2c06-4888-8c8f-029038c49584', 'f6407386-1c82-4ea2-bc9a-ceb81195650e', 'en', '', '<div>a) respond to actual emergency situations and incidents by:</div><ul><li>{clause_8.4.2.a.1}</li><li>{clause_8.4.2.a.2}</li><li>{clause_8.4.2.a.3}</li></ul>'),
    ('c83ec09f-7412-475f-88f1-4c6b3dc49d63', 'f6407386-1c82-4ea2-bc9a-ceb81195650e', 'es', '', '<div>a) responder a situaciones e incidentes de emergencia reales: </div><ul><li>{clause_8.4.2.a.1}</li><li>{clause_8.4.2.a.2}</li><li>{clause_8.4.2.a.3}</li></ul>'),
    ('54d8f639-53a3-41d1-bc07-2995d237d025', 'f7407519-9034-4a2d-80a0-1dd5129566a1', 'en', '', '<div>1) ensuring applicable statutory and regulatory requirements are identified</div>'),
    ('6fd920ba-4db9-4bca-bdca-fecae537ee0e', 'f7407519-9034-4a2d-80a0-1dd5129566a1', 'es', '', '<div>1) asegurando que se identifiquen los requisitos legales y reglamentarios aplicables</div>'),
    ('dc5769ca-c24c-48a2-9dbd-737acd3565a6', 'f4407060-4bdd-4c18-aad4-21020f9561e8', 'en', '', '<div>2) communicating internally</div>'),
    ('e15771a9-6e9c-4379-90ad-a465ea35934d', 'f4407060-4bdd-4c18-aad4-21020f9561e8', 'es', '', '<div>2) a través de la comunicación interna</div>'),
    ('0ce063f3-e451-4afb-8c92-f547eb64b44f', 'f54071f3-be0f-4653-85b1-5f0f1095637b', 'en', '', '<div>3) communicating externally (e.g. suppliers, customers, appropriate authorities, media)</div>'),
    ('27e08e74-43df-46fc-9a72-ee34de649fd8', 'f54071f3-be0f-4653-85b1-5f0f1095637b', 'es', '', '<div>3) a través de la comunicación externa (por ejemplo, proveedores, clientes, autoridades apropiadas, medios)</div>'),
    ('c06d9314-ce41-454c-9b7e-06d4c65022b8', 'fa4079d2-8fe7-42b6-905f-8f6c15956b5a', 'en', '', '<div>b) take action to reduce the consequences of the emergency situation, appropriate to the magnitude of the emergency or incident and the potential food safety impact</div>'),
    ('a56d6893-ce9e-4a2b-b8f6-b967d350372f', 'fa4079d2-8fe7-42b6-905f-8f6c15956b5a', 'es', '', '<div>b) tomar medidas para reducir las consecuencias de la situación de emergencia, de acuerdo con la magnitud de la emergencia o incidente y el potencial impacto sobre la inocuidad de los alimentos</div>'),
    ('e6872835-e9c3-4b45-9478-0aa90c90f9a9', 'fb407b65-5401-4ab1-931c-ba6916956ced', 'en', '', '<div>c) periodically test procedures where practical</div>'),
    ('d98713be-acf6-4f86-8e54-1ac60790f1ca', 'fb407b65-5401-4ab1-931c-ba6916956ced', 'es', '', '<div>c) cuando sea práctico, probar periódicamente los procedimientos</div>'),
    ('e225b476-b291-4ea6-9062-4b3e058c7a7a', 'f84076ac-9922-4e7c-b863-b95613956834', 'en', '', '<div>d) review and, where necessary, update the documented information after the occurrence of any incident, emergency situation or tests.</div>'),
    ('df25afbd-1ecb-47e5-acc6-4911ea8c4ff9', 'f84076ac-9922-4e7c-b863-b95613956834', 'es', '', '<div>d) revisar y, de ser necesario, actualizar la información documentada después de la ocurrencia de todo incidente, situación de emergencia o pruebas.</div>'),
    ('bfb53a9f-8eea-4f0f-8e95-e76b37f20ce3', 'f940783f-414b-4127-8614-adf3149569c7', 'en', 'Hazard control', '<div>{clause_8.5.1}</div><div>{clause_8.5.2}</div><div>{clause_8.5.3}</div><div>{clause_8.5.4}</div>'),
    ('d2b55888-9e08-41d8-9233-9d9032f20504', 'f940783f-414b-4127-8614-adf3149569c7', 'es', 'Control de peligros', '<div>{clause_8.5.1}</div><div>{clause_8.5.2}</div><div>{clause_8.5.3}</div><div>{clause_8.5.4}</div>'),
    ('e3025ea0-deb6-4d20-9c7b-0d68f3e08cdc', 'fe40801e-7d77-42ba-92e1-4ad009955876', 'en', 'Preliminary steps to enable hazard analysis', '<div>{clause_8.5.1.1}</div><div>{clause_8.5.1.2}</div><div>{clause_8.5.1.3}</div><div>{clause_8.5.1.4}</div><div>{clause_8.5.1.5}</div>'),
    ('00028c47-d7fc-4387-b37c-cd53e8e07b8b', 'fe40801e-7d77-42ba-92e1-4ad009955876', 'es', 'Pasos preliminares para permitir el análisis de peligros', '<div>{clause_8.5.1.1}</div><div>{clause_8.5.1.2}</div><div>{clause_8.5.1.3}</div><div>{clause_8.5.1.4}</div><div>{clause_8.5.1.5}</div>'),
    ('79846ef1-661f-4d09-8ecc-468d6ad92c1d', 'ff4081b1-b73e-4625-8a0e-488d0a955a09', 'en', 'General', '<div>To carry out the hazard analysis, preliminary documented information shall be collected, maintained and updated by the food safety team. This shall include, but not be limited to:</div><div>{clause_8.5.1.1.a}</div><div>{clause_8.5.1.1.b}</div><div>{clause_8.5.1.1.c}</div>'),
    ('84848042-7649-4012-9687-70926dd930d6', 'ff4081b1-b73e-4625-8a0e-488d0a955a09', 'es', 'Generalidades', '<div>Para llevar a cabo el análisis de peligros, el equipo de inocuidad de los alimentos debe recopilar, mantener y actualizar la información documentada preliminar. Esto debe incluir, pero no se limita a:</div><div>{clause_8.5.1.1.a}</div><div>{clause_8.5.1.1.b}</div><div>{clause_8.5.1.1.c}</div>'),
    ('d5fa8a01-8e72-445d-8c12-f3bdc6b3096d', '903d945d-413d-4469-a954-251d8b925385', 'en', '', '<div>a) applicable statutory, regulatory and customer requirements </div>'),
    ('c0fa68f2-1aaf-41ce-a3fb-e922a9b2dbc6', '903d945d-413d-4469-a954-251d8b925385', 'es', '', '<div>a) los requisitos legales, reglamentarios y de los clientes aplicables </div>'),
    ('afb9e570-3344-40e4-8444-81d80d3f9c6c', '8f3d92ca-3a99-472e-8585-78e08a9251f2', 'en', '', '<div>b) the organization’s products, processes and equipment</div>'),
    ('acb9e0b7-25eb-4233-90aa-c1e3223fbd7b', '8f3d92ca-3a99-472e-8585-78e08a9251f2', 'es', '', '<div>b) los productos, procesos y equipos de la organización</div>'),
    ('015b9d3b-2840-4067-aafc-9a6f9fdf88d7', '8e3d9137-cbfd-433f-a95a-01978992505f', 'en', '', '<div>c) food safety hazards relevant to the FSMS.</div>'),
    ('ec5b7c2c-3173-4000-92ca-b1cca2df8d90', '8e3d9137-cbfd-433f-a95a-01978992505f', 'es', '', '<div>c) los peligros relacionados con la inocuidad de los alimentos pertinentes para el SGIA.</div>'),
    ('b1704172-74f5-44be-a5de-f5a2c25002ae', '8d3d8fa4-7340-4074-8a64-8a2a88924ecc', 'en', 'Characteristics of raw materials, ingredients and product contact materials', '<div>The organization shall ensure that all applicable statutory and regulatory food safety requirements are identified for all raw materials, ingredients and product contact materials.</div><div>The organization shall maintain documented information concerning all raw materials, ingredients and product contact materials to the extent needed to conduct the hazard analysis (see 8.5.2), including the following, as appropriate:</div><div>{clause_8.5.1.2.a}</div><div>{clause_8.5.1.2.b}</div><div>{clause_8.5.1.2.c}</div><div>{clause_8.5.1.2.d}</div><div>{clause_8.5.1.2.e}</div><div>{clause_8.5.1.2.f}</div><div>{clause_8.5.1.2.g}</div><div>{clause_8.5.1.2.h}</div><div>{clause_8.5.1.2.i}</div>'),
    ('c6706281-5c48-4aad-8df6-003daf4fe4c5', '8d3d8fa4-7340-4074-8a64-8a2a88924ecc', 'es', 'Caracterí­sticas de las materias primas, ingredientes y materiales en contacto con el producto', '<div>La organización debe asegurarse que se identifiquen todos los requisitos legales y reglamentarios de inocuidad de los alimentos aplicables a todas las materias primas, ingredientes y materiales en contacto con el producto. </div><div>La organización debe mantener la información documentada referente a las materias primas, los ingredientes y los materiales en contacto con el producto, en la medida necesaria para realizar el análisis de peligros (véase 8.5.2), incluyendo, según sea apropiado, lo siguiente:</div><div>{clause_8.5.1.2.a}</div><div>{clause_8.5.1.2.b}</div><div>{clause_8.5.1.2.c}</div><div>{clause_8.5.1.2.d}</div><div>{clause_8.5.1.2.e}</div><div>{clause_8.5.1.2.f}</div><div>{clause_8.5.1.2.g}</div><div>{clause_8.5.1.2.h}</div><div>{clause_8.5.1.2.i}</div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('9ba1607d-8b4e-43e9-84d0-3651c10bce31', '8c3d8e11-1ae6-4c45-9316-4d5187924d39', 'en', '', '<div>a) biological, chemical and physical characteristics</div>'),
    ('9ea16536-b4c4-4bf2-b69e-247ecc0bdf82', '8c3d8e11-1ae6-4c45-9316-4d5187924d39', 'es', '', '<div>a) las caracterí­sticas biológicas, quí­micas y fí­sicas</div>'),
    ('9587fdbc-c057-4a00-9e55-cd3c280f54e0', '8b3d8c7e-c7d3-46da-9c3b-63f486924ba6', 'en', '', '<div>b) composition of formulated ingredients, including additives and processing aids</div>'),
    ('8a87ec6b-b724-4a67-80fc-d1bf450f8287', '8b3d8c7e-c7d3-46da-9c3b-63f486924ba6', 'es', '', '<div>b) la composición de los ingredientes formulados, incluyendo los aditivos y coadyuvantes del proceso</div>'),
    ('b6aadce7-16e2-4d53-80c1-1f73ed0ab22b', '8a3d8aeb-cb4c-426b-9dc1-d41b85924a13', 'en', '', '<div>c) source (e.g. animal, mineral or vegetable)</div>'),
    ('99aaaf40-243c-4f04-b4f4-0408f80ac37c', '8a3d8aeb-cb4c-426b-9dc1-d41b85924a13', 'es', '', '<div>c) el origen (por ejemplo, animal, mineral o vegetal)</div>'),
    ('96a088fe-274f-443a-a672-6e86dc81ea62', '893d8958-efdb-4330-b494-7bde84924880', 'en', '', '<div>d) place of origin (provenance)</div>'),
    ('a3a09d75-cfc9-4261-b4c9-c369d181d911', '893d8958-efdb-4330-b494-7bde84924880', 'es', '', '<div>d) el lugar de origen (procedencia)</div>'),
    ('ae386a89-0c34-4125-8302-6e452b95b175', '883d87c5-b7a8-40d1-89b6-e9659392601d', 'en', '', '<div>e) method of production</div>'),
    ('a93862aa-b947-4ce6-9e1a-b6da1e959cfe', '883d87c5-b7a8-40d1-89b6-e9659392601d', 'es', '', '<div>e) el método de producción</div>'),
    ('f716c418-df50-42ac-a10f-164007f68554', '873d8632-09ae-4156-89a9-cd0892925e8a', 'en', '', '<div>f) method of packaging and delivery</div>'),
    ('0416d88f-c3e5-498b-abef-2a7becf65ad3', '873d8632-09ae-4156-89a9-cd0892925e8a', 'es', '', '<div>f) los métodos de embalaje y liberación</div>'),
    ('57eff082-c551-434e-ad12-6cd2b575a77e', '8a3b4c54-7fb7-4de0-afba-d2fa85900b7c', 'en', '', '<div>g) storage conditions and shelf life</div>'),
    ('4cefdf31-3913-45dd-8f01-72cdc275bbf5', '8a3b4c54-7fb7-4de0-afba-d2fa85900b7c', 'es', '', '<div>g) las condiciones de almacenamiento y la vida útil </div>'),
    ('f520a5cb-1cb6-4c77-8938-0e9fd57ffb67', '8b3b4de7-73c1-4e9b-9189-d66786900d0f', 'en', '', '<div>h) preparation and/or handling before use or processing</div>'),
    ('0020b71c-9662-45b0-8d3d-f51cb87fcdc0', '8b3b4de7-73c1-4e9b-9189-d66786900d0f', 'es', '', '<div>h) la preparación y/o el tratamiento previo a su uso o procesamiento</div>'),
    ('a37d5b00-b1aa-4ef4-9a02-c9c8b45d1c3c', '8c3b4f7a-6faa-4f4a-b433-36f087900ea2', 'en', '', '<div>i) acceptance criteria related to food safety or specifications of purchased materials and ingredients appropriate to their intended use.</div>'),
    ('c07d88a7-4aaa-42a3-acfd-3d33a95d0aeb', '8c3b4f7a-6faa-4f4a-b433-36f087900ea2', 'es', '', '<div>i) los criterios de aceptación relacionados con la inocuidad de los alimentos o las especificaciones de los materiales e ingredientes comprados, apropiados para su uso previsto.</div>'),
    ('3c79d451-95dd-43ed-bfb7-0c6dba767efd', '8d3b510d-ad3c-4ff5-b5cb-f3ad88901035', 'en', 'Characteristics of end products', '<div>The organization shall ensure that all applicable statutory and regulatory food safety requirements are identified for all the end products intended to be produced.</div><div>The organization shall maintain documented information concerning the characteristics of end products to the extent needed to conduct the hazard analysis (see 8.5.2), including information on the following, as appropriate:</div><div>{clause_8.5.1.3.a}</div><div>{clause_8.5.1.3.b}</div><div>{clause_8.5.1.3.c}</div><div>{clause_8.5.1.3.d}</div><div>{clause_8.5.1.3.e}</div><div>{clause_8.5.1.3.f}</div><div>{clause_8.5.1.3.g}</div>'),
    ('4779e5a2-c7d6-42fe-9f02-96f2bd7683b6', '8d3b510d-ad3c-4ff5-b5cb-f3ad88901035', 'es', 'Caracterí­sticas de los productos terminados', '<div>La organización debe asegurarse que se identifiquen todos los requisitos legales y reglamentarios de inocuidad de los alimentos aplicables para todos los productos terminados que se preveen producir.</div><div>La organización debe mantener la información documentada sobre las caracterí­sticas de los productos terminados en el grado que sea necesario para realizar el análisis de peligros (véase 8.5.2), incluyendo la información que sigue, según sea apropiado:</div><div>{clause_8.5.1.3.a}</div><div>{clause_8.5.1.3.b}</div><div>{clause_8.5.1.3.c}</div><div>{clause_8.5.1.3.d}</div><div>{clause_8.5.1.3.e}</div><div>{clause_8.5.1.3.f}</div><div>{clause_8.5.1.3.g}</div>'),
    ('ca64634e-206f-40ca-bee4-3df6d0455ff2', '863b4608-e9cf-4624-add0-ca2e81900530', 'en', '', '<div>a) product name or similar identification</div>'),
    ('b7644565-2659-46d1-be5c-b739e5458101', '863b4608-e9cf-4624-add0-ca2e81900530', 'es', '', '<div>a) el nombre del producto o identificación similar</div>'),
    ('aa6e5277-7fe4-48a3-aaed-71232030bbbb', '873b479b-71f8-466f-b453-13ab829006c3', 'en', '', '<div>b) composition</div>'),
    ('ad6e5730-e6e4-44f4-9aa7-a0180b309aac', '873b479b-71f8-466f-b453-13ab829006c3', 'es', '', '<div>b) la composición</div>'),
    ('8b280b8c-c4aa-4fd0-abd0-9dacce8f03f0', '883b492e-ccef-4ade-b3c7-b50483900856', 'en', '', '<div>c) biological, chemical and physical characteristics relevant for food safety</div>'),
    ('a0282c9b-644b-4b97-807a-004fcb8eff37', '883b492e-ccef-4ade-b3c7-b50483900856', 'es', '', '<div>c) las caracterí­sticas biológicas, quí­micas y fí­sicas pertinentes para la inocuidad de los alimentos</div>'),
    ('42210f8d-3de0-41f9-a7b8-8ac1f4cfa881', '893b4ac1-d393-4819-9a74-48e1849009e9', 'en', '', '<div>d) intended shelf life and storage conditions</div>'),
    ('2520e1e6-918f-4722-a2e1-788edfcf8772', '893b4ac1-d393-4819-9a74-48e1849009e9', 'es', '', '<div>d) la vida útil prevista y las condiciones de almacenamiento</div>'),
    ('9cd3f92a-20aa-4bd6-b913-b15a8db1f506', '823b3fbc-41dc-48e8-8364-60a28d901814', 'en', '', '<div>e) packaging</div>'),
    ('a1d40109-064d-45f5-9dfb-68c5aab222ad', '823b3fbc-41dc-48e8-8364-60a28d901814', 'es', '', '<div>e) el envase y embalaje</div>'),
    ('cfd75c53-ebdd-45ff-b87d-23a73b02072f', '833b414f-ca2c-48a3-a816-00af8e9019a7', 'en', '', '<div>f) labelling relating to food safety and/or instructions for handling, preparation and intended use</div>'),
    ('ead786d4-a3cf-4428-bf2f-c4142e01f2b8', '833b414f-ca2c-48a3-a816-00af8e9019a7', 'es', '', '<div>f) el etiquetado en relación con la inocuidad de los alimentos y/o instrucciones para su manipulación, preparación y uso previsto</div>'),
    ('1fb84f7b-e9c8-475b-83e7-faafc2a80fdf', '744c72d3-16fd-49e7-9674-dd570f798b6b', 'en', '', '<div>g) method(s) of distribution and delivery.</div>'),
    ('0ab82e6c-62a4-4b5c-b745-7a0cd5a82dc8', '744c72d3-16fd-49e7-9674-dd570f798b6b', 'es', '', '<div>g) los métodos de distribución y entrega.</div>'),
    ('cd528ab2-c7c4-4802-880b-3fe2e29e20b6', '734c7140-8821-4c3c-9840-43ea0e7989d8', 'en', 'Intended use', '<div>The intended use, including reasonably expected handling of the end product and any unintended use but reasonably expected mishandling and misuse of the end product, shall be considered and shall be maintained as documented information to the extent needed to conduct the hazard analysis (see 8.5.2).</div><div>Where appropriate, groups of consumers/users shall be identified for each product.</div><div>Groups of consumers/users known to be especially vulnerable to specific food safety hazards shall be identified.</div>'),
    ('e252abc1-5df5-4a59-ad6c-7e7ddf9e1bfd', '734c7140-8821-4c3c-9840-43ea0e7989d8', 'es', 'Uso previsto', '<div>El uso previsto, incluyendo la manipulación razonablemente esperada del producto terminado y todo uso no previsto pero razonablemente esperado, mal manejo y uso incorrecto del producto terminado, deben ser considerados y se deben mantener como información documentada en la medida que sea necesaria para realizar el análisis de peligros (véase 8.5.2). </div><div>Para cada producto se deben identificar los grupos de consumidores/usuarios, cuando sea apropiado. </div><div>Se deben identificar los grupos de consumidores/usuarios, conocidos por ser especialmente vulnerables a peligros especí­ficos relacionados con la inocuidad de los alimentos.</div>'),
    ('f1dcd341-2e6d-43b1-a0a5-02fde7012775', '764c75f9-4300-4871-b178-99dd11798e91', 'en', 'Flow diagrams and description of processes', '<div>{clause_8.5.1.5.1}</div><div>{clause_8.5.1.5.2}</div><div>{clause_8.5.1.5.3}</div>'),
    ('dcdcb232-0fe9-4c2a-bb43-c462da0112fe', '764c75f9-4300-4871-b178-99dd11798e91', 'es', 'Diagramas de flujo y descripción de los procesos', '<div>{clause_8.5.1.5.1}</div><div>{clause_8.5.1.5.2}</div><div>{clause_8.5.1.5.3}</div>'),
    ('ce1504b0-4968-4ee8-aed3-e818c361fb54', '754c7466-6813-4476-8ce0-2fa010798cfe', 'en', 'Preparation of the flow diagrams', '<div>The food safety team shall establish, maintain and update flow diagrams as documented information for the products or product categories and the processes covered by the FSMS.</div><div>Flow diagrams provide a graphic representation of the process. Flow diagrams shall be used when conducting the hazard analysis as a basis for evaluating the possible occurrence, increase, decrease or introduction of food safety hazards.</div><div>Flow diagrams shall be clear, accurate and sufficiently detailed to the extent needed to conduct the hazard analysis. Flow diagrams shall, as appropriate, include the following:</div><div>{clause_8.5.1.5.1.a}</div><div>{clause_8.5.1.5.1.b}</div><div>{clause_8.5.1.5.1.c}</div><div>{clause_8.5.1.5.1.d}</div><div>{clause_8.5.1.5.1.e}</div>'),
    ('cb14fff7-9174-4dbf-bf19-b923a861d0d3', '754c7466-6813-4476-8ce0-2fa010798cfe', 'es', 'Preparación de los diagramas de flujo', '<div>El equipo de inocuidad de los alimentos debe establecer, mantener y actualizar los diagramas de flujo como información documentada para los productos o categorí­as de productos y los procesos incluidos en el SGIA. </div><div>Los diagramas de flujo proporcionan una representación gráfica del proceso. Los diagramas de flujo se deben utilizar al realizar el análisis de peligros como base para evaluar la posible presencia, incremento, disminución o introducción de peligros relacionados con la inocuidad de los alimentos. </div><div>Los diagramas de flujo deben ser claros, precisos y suficientemente detallados en la medida necesaria para realizar el análisis de peligros. Los diagramas de flujo deben incluir, según sea apropiado, lo siguiente:</div><div>{clause_8.5.1.5.1.a}</div><div>{clause_8.5.1.5.1.b}</div><div>{clause_8.5.1.5.1.c}</div><div>{clause_8.5.1.5.1.d}</div><div>{clause_8.5.1.5.1.e}</div>'),
    ('d28b9327-94a8-496f-8f6e-3ab30d5a6333', '784c791f-93c0-4c13-b89e-d3db137991b7', 'en', '', '<div>a) the sequence and interaction of the steps in the operation</div>'),
    ('b58b6580-9021-4cb8-bc73-c748285a8db4', '784c791f-93c0-4c13-b89e-d3db137991b7', 'es', '', '<div>a) la secuencia e interacción de las etapas en la operación</div>'),
    ('b2813f3e-2a0e-4006-8ebc-7fc6dccfd60a', '774c778c-3adc-49d8-9b06-749e12799024', 'en', '', '<div>b) any outsourced processes</div>'),
    ('bf8153b5-66dc-4bc5-94e0-6fa9e1cfdde9', '774c778c-3adc-49d8-9b06-749e12799024', 'es', '', '<div>b) todo proceso contratado externamente</div>'),
    ('b783a9bd-ef3b-4aa5-aad2-a0915552f579', '7a4c7c45-6861-4bed-8152-6c11157994dd', 'en', '', '<div>c) where raw materials, ingredients, processing aids, packaging materials, utilities and intermediate products enter the flow</div>'),
    ('ba83ae76-9c4e-4666-8e6e-a2be70531ffa', '7a4c7c45-6861-4bed-8152-6c11157994dd', 'es', '', '<div>c) dónde se incorporan al flujo las materias primas, los ingredientes, coadyuvantes de elaboración, materiales de embalaje, servicios y los productos intermedios </div>'),
    ('b3e31cfc-c257-4c2c-86a4-4d7cde31b3c8', '794c7ab2-0dfc-4562-b669-2fb41479934a', 'en', '', '<div>d) where reworking and recycling take place</div>'),
    ('a8e30bab-a6ed-430b-af32-38ffcb3195df', '794c7ab2-0dfc-4562-b669-2fb41479934a', 'es', '', '<div>d) dónde se reprocesa y se hace el reciclado </div>'),
    ('849af783-f9ea-46d3-9a3b-74375b4afed7', '7c4c7f6b-5753-47df-aa1c-fcdf07797ed3', 'en', '', '<div>e) where end products, intermediate products, by-products and waste are released or removed.</div>'),
    ('7f9aefa4-0744-4884-aa65-5b045e4b0390', '7c4c7f6b-5753-47df-aa1c-fcdf07797ed3', 'es', '', '<div>e) dónde se liberan o eliminan los productos terminados, los productos intermedios, los subproductos y los desechos.</div>'),
    ('c809739a-0a57-4dba-8bc7-a82a7dbb78ae', '7b4c7dd8-cf2a-4794-af08-60d206797d40', 'en', 'On-site confirmation of flow diagrams', '<div>The food safety team shall confirm on-site the accuracy of the flow diagrams, update the flow diagrams where appropriate and retain as documented information.</div>'),
    ('ad094919-b2d1-4be1-9485-55756abb5ac5', '7b4c7dd8-cf2a-4794-af08-60d206797d40', 'es', 'Confirmación in situ de diagramas de flujo', '<div>El equipo de inocuidad de los alimentos debe confirmar in situ la precisión de los diagramas de flujo, actualizar los diagramas de flujo cuando corresponda, y conservar como información documentada.</div>'),
    ('2e679834-52a6-41c4-a2ac-e674d1575898', '8e4a5d2a-f7ee-4c26-84ad-accc09774362', 'en', 'Description of processes and process environment', '<div>The food safety team shall describe, to the extent needed to conduct the hazard analysis:</div><div>{clause_8.5.1.5.3.a}</div><div>{clause_8.5.1.5.3.b}</div><div>{clause_8.5.1.5.3.c}</div><div>{clause_8.5.1.5.3.d}</div><div>The variations resulting from expected seasonal changes or shift patterns shall be included as appropriate.</div><div>The descriptions shall be updated as appropriate and maintained as documented information.</div>'),
    ('13676db3-42d1-4713-bdaa-d087de576d0f', '8e4a5d2a-f7ee-4c26-84ad-accc09774362', 'es', 'Descripción de procesos y su entorno', '<div>En la medida que sea necesaria para realizar el análisis de peligros, el equipo de inocuidad de los alimentos debe describir: </div><div>{clause_8.5.1.5.3.a}</div><div>{clause_8.5.1.5.3.b}</div><div>{clause_8.5.1.5.3.c}</div><div>{clause_8.5.1.5.3.d}</div><div>Se deben incluir las variaciones resultantes de cambios estacionales esperados o patrones de cambio según sea apropiado.</div><div>Las descripciones se deben actualizar como sea apropiado y mantener como información documentada.</div>'),
    ('c56069d5-72a3-43bd-8112-75498878ff09', '8f4a5ebd-d556-4c21-8afd-bcc90a7744f5', 'en', '', '<div>a) the layout of premises, including food and non-food handling areas</div>'),
    ('b860555e-e8c1-48ae-b01e-e8e68378f72a', '8f4a5ebd-d556-4c21-8afd-bcc90a7744f5', 'es', '', '<div>a) la distribución de las instalaciones, incluidas las áreas de manipulación de alimentos y otras</div>'),
    ('c0fd6316-2e49-411e-82a2-eade83eee8da', '8c4a5a04-2ff7-44ac-aaf5-c5b60777403c', 'en', '', '<div>b) processing equipment and contact materials, processing aids and flow of materials</div>'),
    ('bdfd5e5d-fc51-420d-a97e-663168eebe59', '8c4a5a04-2ff7-44ac-aaf5-c5b60777403c', 'es', '', '<div>b) el equipo de procesamiento y materiales de contacto, coadyuvantes de procesamiento y flujo de materiales</div>'),
    ('2dadacbf-506d-4247-9474-1e8b42f942c3', '8d4a5b97-a954-4d97-a577-92d3087741cf', 'en', '', '<div>c) existing PRPs, process parameters, control measures (if any) and/or the strictness with which they are applied, or procedures that can influence food safety</div>'),
    ('40adcaa8-5725-48e0-a6dd-2eb03df93ae4', '8d4a5b97-a954-4d97-a577-92d3087741cf', 'es', '', '<div>c) los PPR existentes, los parámetros del proceso, las medidas de control (si las hay) y/o la rigurosidad con que se aplican, o los procedimientos que pueden influir en la inocuidad de los alimentos</div>'),
    ('46bce7a8-e609-42e0-9654-24b0b72570e4', '8a4a56de-848b-4b12-9518-041805773d16', 'en', '', '<div>d) external requirements (e.g. from statutory and regulatory authorities or customers) that can impact the choice and the strictness of the control measures.</div>'),
    ('33bcc9bf-df51-4c47-83eb-148bbc2578c3', '8a4a56de-848b-4b12-9518-041805773d16', 'es', '', '<div>d) los requisitos externos (por ejemplo, de autoridades legales o reglamentarias o clientes) que pueden afectar la elección y la rigurosidad de las medidas de control.</div>'),
    ('c0589259-19f4-42c9-9247-9c354e1e4285', '8b4a5871-f79d-42dd-b087-28b506773ea9', 'en', 'Hazard analysis', '<div>{clause_8.5.2.1}</div><div>{clause_8.5.2.2}</div><div>{clause_8.5.2.3}</div><div>{clause_8.5.2.4}</div>'),
    ('db58bcda-2a1e-45d2-a46f-bbea611e606e', '8b4a5871-f79d-42dd-b087-28b506773ea9', 'es', 'Análisis de peligros', '<div>{clause_8.5.2.1}</div><div>{clause_8.5.2.2}</div><div>{clause_8.5.2.3}</div><div>{clause_8.5.2.4}</div>'),
    ('bb2f186a-4436-4c1a-a917-e89a491d6b06', '884a53b8-cd32-4d88-af0f-6e62037739f0', 'en', 'General', '<div>The food safety team shall conduct a hazard analysis, based on the preliminary information, to determine the hazards that need to be controlled. The degree of control shall ensure food safety and, where appropriate, a combination of control measures shall be used.</div>'),
    ('c02f2049-ef2b-4341-95d8-1205661d98ad', '884a53b8-cd32-4d88-af0f-6e62037739f0', 'es', 'Generalidades', '<div>El equipo de la inocuidad de los alimentos debe realizar un análisis de peligros, basado en la información preliminar, para determinar cuáles son los peligros que necesitan ser controlados. El nivel de control debe asegurar la inocuidad de los alimentos y, cuando sea apropiado, se debe utilizar una combinación de medidas de control.</div>'),
    ('ebb81293-cd0a-4d33-9c98-1ee7f66d7d2f', '894a554b-3c36-4843-a61c-7b6f04773b83', 'en', 'Hazard identification and determination of acceptable levels', '<div>{clause_8.5.2.2.1}</div><div>{clause_8.5.2.2.2}</div><div>{clause_8.5.2.2.3}</div>'),
    ('06b83d14-da63-4be4-bf1f-6c54e96d68b8', '894a554b-3c36-4843-a61c-7b6f04773b83', 'es', 'Identificación de peligros y determinación de los niveles aceptables', '<div>{clause_8.5.2.2.1}</div><div>{clause_8.5.2.2.2}</div><div>{clause_8.5.2.2.3}</div>'),
    ('a708c1cc-d810-470c-915f-39ec89fa79f0', '864a5092-5845-4f7e-aaf3-7dc411774ffa', 'en', '', '<div>The organization shall identify and document all food safety hazards that are reasonably expected to occur in relation to the type of product, type of process and process environment.</div><div>The identification shall be based on:</div><div>{clause_8.5.2.2.1.a}</div><div>{clause_8.5.2.2.1.b}</div><div>{clause_8.5.2.2.1.c}</div><div>{clause_8.5.2.2.1.d}</div><div>{clause_8.5.2.2.1.e}</div><div>NOTE 1: Experience can include information from staff and external experts who are familiar with the product and/or processes in other facilities..</div><div>NOTE 2: Statutory and regulatory requirements can include food safety objectives (FSOs). The Codex Alimentarius Commission defines FSOs as “The maximum frequency and/or concentration of a hazard in a food at the time of consumption that provides or contributes to the appropriate level of protection (ALOP)”.</div><div>Hazards should be considered in sufficient detail to enable hazard assessment and the selection of appropriate control measures.</div>'),
    ('bc08e2db-bca6-4deb-99a8-f98f86fa7537', '864a5092-5845-4f7e-aaf3-7dc411774ffa', 'es', '', '<div>La organización debe identificar y documentar todos los peligros relacionados con la inocuidad de los alimentos razonablemente previsibles en relación con el tipo de producto, el tipo de proceso y su entorno. </div><div>La identificación debe realizarse en base a:</div><div>{clause_8.5.2.2.1.a}</div><div>{clause_8.5.2.2.1.b}</div><div>{clause_8.5.2.2.1.c}</div><div>{clause_8.5.2.2.1.d}</div><div>{clause_8.5.2.2.1.e}</div><div>NOTA: 1 La experiencia puede incluir información del personal y de expertos externos que esten familiarizados con el producto y/o procesos en otras instalaciones.</div><div>NOTA 2: Los requisitos legales y reglamentarios pueden incluir objetivos de inocuidad de los alimentos (OIA). La Comisión del Codex Alimentarius define los OIA como "La frecuencia y/o concentración máxima de un peligro en un alimento en el momento del consumo que proporciona o contribuye al nivel de protección apropiado (NPA)".</div><div>Los peligros se deberí­an considerar con suficiente detalle para permitir la evaluación de peligros y la selección de medidas de control apropiadas.</div>'),
    ('607c2ecd-818c-4805-a760-3401b03b1e81', '874a5225-5eea-4cb9-bf63-d4a11277518d', 'en', '', '<div>a) the preliminary information and data collected in accordance with 8.5.1</div>'),
    ('437c0126-4245-4646-820f-38ce9b3afd72', '874a5225-5eea-4cb9-bf63-d4a11277518d', 'es', '', '<div>a) la información preliminar y los datos recopilados de acuerdo con el apartado 8.5.1 </div>'),
    ('318f02d2-7649-4a62-9d3f-3082a7035366', '05a19e20-4d41-470c-b305-ba4a20f68fa8', 'en', '', '<div>b) experience</div>'),
    ('468f23e1-094b-4d39-bbec-8e1dc403810d', '05a19e20-4d41-470c-b305-ba4a20f68fa8', 'es', '', '<div>b) la experiencia</div>'),
    ('83f4c79b-4255-40bb-ab19-994fc7ab780f', '06a19fb3-dcbb-4577-ab87-ef3721f6913b', 'en', '', '<div>c) internal and external information including, to the extent possible, epidemiological, scientific and other historical data</div>'),
    ('6ef4a68c-9f69-46bc-9670-36acbaab6398', '06a19fb3-dcbb-4577-ab87-ef3721f6913b', 'es', '', '<div>c) la información interna y externa que incluya, en la medida de lo posible, los datos epidemiológicos, cientí­ficos y otros antecedentes históricos y </div>'),
    ('bef96a50-c6fa-4d48-80b9-8538150b5944', '07a1a146-44a3-4c06-ae7c-0a0022f692ce', 'en', '', '<div>d) information from the food chain on food safety hazards related to the safety of the end products, intermediate products and the food at the time of consumption</div>'),
    ('bbf96597-1182-481f-8cbd-6c431a0b6123', '07a1a146-44a3-4c06-ae7c-0a0022f692ce', 'es', '', '<div>d) la información de la cadena alimentaria sobre los peligros para la inocuidad de los alimentos relacionados con la inocuidad de los productos terminados, los productos intermedios y los alimentos en el momento del consumo </div>'),
    ('5893b461-07a0-4391-ba09-819dac042ae5', '08a1a2d9-f29e-4b81-bfb4-e8bd23f69461', 'en', '', '<div>e) statutory, regulatory and customer requirements.</div>'),
    ('43939352-ff3a-418a-9b5c-2402bf0448ce', '08a1a2d9-f29e-4b81-bfb4-e8bd23f69461', 'es', '', '<div>e) los requisitos legales, reglamentarios y de los clientes.</div>'),
    ('1939b35e-bf47-4d66-b081-fce6e1d33e3a', '09a1a46c-ea7c-4fe8-9630-1e7e24f695f4', 'en', '', '<div>The organization shall identify step(s) (e.g. receiving raw materials, processing, distribution and delivery) at which each food safety hazard can be present, be introduced, increase or persist.</div><div>When identifying hazards, the organization shall consider:</div><div>{clause_8.5.2.2.2.a}</div><div>{clause_8.5.2.2.2.b}</div><div>{clause_8.5.2.2.2.c}</div>'),
    ('2639c7d5-1234-41a5-8175-8949c6d313b9', '09a1a46c-ea7c-4fe8-9630-1e7e24f695f4', 'es', '', '<div>La organización debe indicar las etapas (por ejemplo, la recepción de las materias primas, procesamiento, distribución y entrega) en las cuales se puede presentar, introducir, aumentar o mantener cada peligro relacionado con la inocuidad de los alimentos.</div><div>Cuando se identifican los peligros, la organización debe considerar:</div><div>{clause_8.5.2.2.2.a}</div><div>{clause_8.5.2.2.2.b}</div><div>{clause_8.5.2.2.2.c}</div>'),
    ('c36ff8c7-29e0-46cf-acbd-e15311be67a3', '0aa1a5ff-72cc-4fa3-bf16-a7bb25f69787', 'en', '', '<div>a) the stages preceding and following in the food chain</div>'),
    ('a66fcb20-3b77-4f98-95bc-21680cbe5fc4', '0aa1a5ff-72cc-4fa3-bf16-a7bb25f69787', 'es', '', '<div>a) las etapas precedentes y siguientes en la cadena alimentaria </div>'),
    ('a4c7829c-daf6-440c-82c4-b29ca296e678', '0ba1a792-d13f-47f2-8526-2e1426f6991a', 'en', '', '<div>b) all steps in the flow diagram</div>'),
    ('99c7714b-bf8c-4aeb-bebe-cc1faf96faef', '0ba1a792-d13f-47f2-8526-2e1426f6991a', 'es', '', '<div>b) todas las etapas en el diagrama de flujo</div>'),
    ('1e3a8add-8472-4505-a785-6cb1e65d5469', '0ca1a925-2b06-4dbd-855f-93f127f69aad', 'en', '', '<div>c) the process equipment, utilities/services, process environment and persons.</div>'),
    ('213a8f96-452c-4346-80a9-f15ee15d4c8a', '0ca1a925-2b06-4dbd-855f-93f127f69aad', 'es', '', '<div>c) los equipos del proceso, instalaciones/servicios, entorno del proceso y las personas.</div>'),
    ('b8ec463a-471d-491a-b34a-844a4220ab5e', '0da1aab8-926f-4d24-884f-393218f68310', 'en', '', '<div>The organization shall determine the acceptable level in the end product of each food safety hazard identified, whenever possible.</div><div>When determining acceptable levels, the organization shall:</div><div>{clause_8.5.2.2.3.a}</div><div>{clause_8.5.2.2.3.b}</div><div>{clause_8.5.2.2.3.c}</div><div>The organization shall maintain documented information concerning the determination of acceptable levels and the justification for the acceptable levels.</div>'),
    ('9dec1bb9-f211-4041-b186-af154f20bfd5', '0da1aab8-926f-4d24-884f-393218f68310', 'es', '', '<div>La organización debe determinar para cada peligro relacionado con la inocuidad de los alimentos, siempre que sea posible, el nivel aceptable en el producto terminado.</div><div>Al determinar los niveles aceptables, la organización debe: </div><div>{clause_8.5.2.2.3.a}</div><div>{clause_8.5.2.2.3.b}</div><div>{clause_8.5.2.2.3.c}</div><div>La organización debe mantener información documentada sobre la determinación de niveles aceptables y la justificación de los niveles aceptables.</div>'),
    ('e8d76fa3-cff0-4a33-89e8-7ed7ec56f0c7', '0ea1ac4b-1a98-4d6f-b3d6-f2bf19f684a3', 'en', '', '<div>a) ensure that applicable statutory, regulatory and customer requirements are identified</div>'),
    ('e3d767c4-dd49-48e4-bc54-95a4cf56c320', '0ea1ac4b-1a98-4d6f-b3d6-f2bf19f684a3', 'es', '', '<div>a) asegurar que se identifiquen los requisitos legales, reglamentarios y de los clientes, que sean aplicables</div>'),
    ('0eb05191-e787-42c1-8ae0-062da2212cd5', '0ba3e629-c385-4345-b5d1-f1ed26f8d7b1', 'en', '', '<div>b) consider the intended use of end products</div>'),
    ('19b062e2-3c93-4b9a-8445-35b29521185e', '0ba3e629-c385-4345-b5d1-f1ed26f8d7b1', 'es', '', '<div>b) considerar el uso previsto de los productos terminados</div>'),
    ('75b3d840-cfb7-48f8-84c1-17880b285b34', '0aa3e496-7073-4dda-b8ce-963025f8d61e', 'en', '', '<div>c) consider any other relevant information.</div>'),
    ('92b405e7-baf3-43af-908e-32f3f02830b3', '0aa3e496-7073-4dda-b8ce-963025f8d61e', 'es', '', '<div>c) considerar toda otra información pertinente.</div>'),
    ('c755900b-d3be-452b-adb2-085f0a6e6fbf', '09a3e303-73eb-496b-813b-80a724f8d48b', 'en', 'Hazard assessment', '<div>The organization shall conduct, for each identified food safety hazard, a hazard assessment to determine whether its prevention or reduction to an acceptable level is essential.</div><div>The organization shall evaluate each food safety hazard with regard to:</div><div>{clause_8.5.2.3.a}</div><div>{clause_8.5.2.3.b}</div><div>The organization shall identify any significant food safety hazards.</div><div>The methodology used shall be described, and the result of the hazard assessment shall be maintained as documented information.</div>'),
    ('d255a15c-d361-404c-b4a8-dcdc1d6e8da8', '09a3e303-73eb-496b-813b-80a724f8d48b', 'es', 'Evaluación de peligros', '<div>Para cada peligro relacionado con la inocuidad de los alimentos identificado, la organización debe realizar una evaluación de peligros, para determinar si su prevención o reducción a niveles aceptables es esencial. </div><div>La organización debe valorar cada peligro relacionado con la inocuidad de los alimentos con respecto a:</div><div>{clause_8.5.2.3.a}</div><div>{clause_8.5.2.3.b}</div><div>La organización debe identificar cualquier peligro significativo relacionado con la inocuidad de los alimentos.</div><div>La metodologí­a utilizada se debe describir y el resultado de la evaluación de peligros se debe mantener como información documentada. </div>'),
    ('27ac04c2-25ed-4bd2-85be-66929dbe2616', '08a3e170-987b-4a30-a31c-cf3a23f8d2f8', 'en', '', '<div>a) the likelihood of its occurrence in the end product prior to application of control measures</div>'),
    ('1cabf371-15c3-48c9-be03-3c8d9abe215d', '08a3e170-987b-4a30-a31c-cf3a23f8d2f8', 'es', '', '<div>a) la probabilidad de que ocurra en el producto terminado antes de la aplicación de las medidas de control </div>'),
    ('1455f9cd-4d64-4e75-8914-b9819d195559', '0fa3ec75-e9dd-4b69-ab72-36212af8ddfd', 'en', '', '<div>b) the severity of its adverse health effects in relation to the intended use (see 8.5.1.4). </div>'),
    ('f755cc26-67c2-4456-a3c3-be4eb8197fda', '0fa3ec75-e9dd-4b69-ab72-36212af8ddfd', 'es', '', '<div>b) la gravedad de sus efectos adversos para la salud en relación con el uso previsto (véase 8.5.1.4). </div>'),
    ('5ae28ccc-7292-497c-b313-bf6c237daaa8', '0ea3eae2-e338-4e2e-9701-df4429f8dc6a', 'en', 'Selection and categorization of control measure(s)', '<div>{clause_8.5.2.4.1}</div><div>{clause_8.5.2.4.2}</div>'),
    ('6fe2addb-1305-4d7b-bb5d-7f0f107d8cbf', '0ea3eae2-e338-4e2e-9701-df4429f8dc6a', 'es', 'Selección y categorización de las medidas de control', '<div>{clause_8.5.2.4.1}</div><div>{clause_8.5.2.4.2}</div>'),
    ('7a2a66b7-04d9-4dff-aebc-8ae3c878d593', '0da3e94f-749c-4a3f-8d9a-ddeb28f8dad7', 'en', '', '<div>Based on the hazard assessment, the organization shall select an appropriate control measure or combination of control measures that will be capable of preventing or reducing the identified significant food safety hazards to defined acceptable levels.</div><div>The organization shall categorize the selected identified control measure(s) to be managed as OPRP(s) (see 3.30) or at CCPs (see 3.11). </div><div>The categorization shall be carried out using a systematic approach. For each of the control measures selected, there shall be an assessment of the following:</div><div>{clause_8.5.2.4.1.a}</div><div>{clause_8.5.2.4.1.b}</div>'),
    ('7d2a6b70-bccb-4c28-a256-4ad8e3790014', '0da3e94f-749c-4a3f-8d9a-ddeb28f8dad7', 'es', '', '<div>Con base en la evaluación de peligros, la organización debe seleccionar una medida de control o combinación de medidas de control apropiadas que sea capaz de prevenir o reducir estos peligros significativos identificados relacionados con la inocuidad de los alimentos hasta los niveles aceptables definidos.</div><div>La organización debe categorizar las medidas de control, identificadas y seleccionadas, para ser gestionadas como los PPRO (véase 3.30) o en los PCC (véase 3.11).&nbsp</div><div>La categorización se debe llevar a cabo utilizando un enfoque sistemático. Para cada una de las medidas de control seleccionadas, se debe realizar una evaluación de lo siguiente:</div><div>{clause_8.5.2.4.1.a}</div><div>{clause_8.5.2.4.1.b}</div>'),
    ('9a20778e-39a7-43d6-b2c5-7cb697efdb6a', '0ca3e7bc-1be0-4774-a849-5c6e27f8d944', 'en', '', '<div>a) the likelihood of failure of its functioning</div>'),
    ('872059a5-1f49-4df5-92ed-35f99cefe349', '0ca3e7bc-1be0-4774-a849-5c6e27f8d944', 'es', '', '<div>a) la probabilidad de que falle su funcionamiento </div>'),
    ('74325d59-56dd-49f9-b3fc-21b53d3cf1cd', '13a3f2c1-832e-424d-9c95-8a351ef8cb19', 'en', '', '<div>b) the severity of the consequence in the case of failure of its functioning this assessment shall include: </div><ul><li>{clause_8.5.2.4.1.b.1}</li><li>{clause_8.5.2.4.1.b.2}</li><li>{clause_8.5.2.4.1.b.3}</li><li>{clause_8.5.2.4.1.b.4}</li></ul>'),
    ('8f3287da-aa8c-4f22-8624-416a203cc426', '13a3f2c1-832e-424d-9c95-8a351ef8cb19', 'es', '', '<div>b) la gravedad de la consecuencia en el caso de que falle su funcionamiento esta evaluación debe incluir: &nbsp</div><ul><li>{clause_8.5.2.4.1.b.1}</li><li>{clause_8.5.2.4.1.b.2}</li><li>{clause_8.5.2.4.1.b.3}</li><li>{clause_8.5.2.4.1.b.4}</li></ul>'),
    ('fa96b2a8-dda7-47d0-b808-aa3083c984cc', '12a3f12e-3eea-4742-8126-65981df8c986', 'en', '', '<div>1) the effect on identified significant food safety hazards</div>'),
    ('e79694bf-7d48-4397-a59f-9a0b98c9a5db', '12a3f12e-3eea-4742-8126-65981df8c986', 'es', '', '<div>1) el efecto sobre los peligros significativos relacionados con la inocuidad de los alimentos identificados</div>'),
    ('a0996d98-f84c-4aac-8d63-1e400a33138c', '11a62e32-5180-4b3e-b40f-15082cfb1fba', 'en', '', '<div>2) the location in relation to other control measure(s)</div>'),
    ('ad99820f-dce2-418b-9843-327b1f33349b', '11a62e32-5180-4b3e-b40f-15082cfb1fba', 'es', '', '<div>2) la ubicación en relación con otras medidas de control</div>'),
    ('57bb1409-2530-4925-af56-7645c12c178d', '12a62fc5-7172-4079-b41c-31652dfb214d', 'en', '', '<div>3) whether it is specifically established and applied to reduce the hazards to an acceptable level</div>'),
    ('52bb0c2a-d243-44e6-8a6e-bedaa42be9e6', '12a62fc5-7172-4079-b41c-31652dfb214d', 'es', '', '<div>3) si está especí­ficamente establecido y aplicado para reducir los peligros a un nivel aceptable </div>'),
    ('5330fdda-6003-4e86-b1b7-05ea496f6b4e', '0fa62b0c-7409-4f04-867d-16122afb1c94', 'en', '', '<div>4) whether it is a single measure or is part of combination of control measure(s).</div>'),
    ('3830d359-9cd1-4a45-9f8e-e635366f4d65', '0fa62b0c-7409-4f04-867d-16122afb1c94', 'es', '', '<div>4) si se trata de una medida única o es parte de una combinación de medidas de control.</div>'),
    ('123b57c3-ca9d-47ef-bf2a-1ff729795a77', '10a62c9f-e2e5-4a4f-a97a-821f2bfb1e27', 'en', '', '<div>In addition, for each control measure, the systematic approach shall include an assessment of the feasibility of:</div><div>{clause_8.5.2.4.2.a}</div><div>{clause_8.5.2.4.2.b}</div><div>{clause_8.5.2.4.2.c}</div><div>The decision-making process and results of the selection and categorization of the control measures shall be maintained as documented information.</div><div>External requirements (e.g. statutory, regulatory and customer requirements) that can impact the choice and the strictness of the control measures shall also be maintained as documented information.</div>'),
    ('0d3b4fe4-c616-4b38-98ff-77c42c795f30', '10a62c9f-e2e5-4a4f-a97a-821f2bfb1e27', 'es', '', '<div>Asimismo, para cada medida de control, el enfoque sistemático debe incluir una evaluación de la viabilidad de: </div><div>{clause_8.5.2.4.2.a}</div><div>{clause_8.5.2.4.2.b}</div><div>{clause_8.5.2.4.2.c}</div><div>Se debe mantener como información documentada el proceso de toma de decisión y los resultados de la selección y categorización de las medidas de control. </div><div>Los requisitos externos (por ejemplo, requisitos legales, reglamentarios y de los clientes) que pueden afectar en la elección y la rigurosidad de las medidas de control también se deben mantener como información documentada.</div>'),
    ('866785e4-7f5d-4d68-8eb5-fc4422886300', '0da627e6-de1d-4a2a-af06-417c28fb196e', 'en', '', '<div>a) establishing measurable critical limits and/or measurable/observable action criteria</div>'),
    ('8b678dc3-c769-4c3f-b4e0-a4773f8890a7', '0da627e6-de1d-4a2a-af06-417c28fb196e', 'es', '', '<div>a) establecer lí­mites crí­ticos medibles y/o criterios de acción medibles/observables</div>'),
    ('1d605785-6462-4231-9979-7959bb84dc51', '0ea62979-31ce-4355-8604-75f929fb1b01', 'en', '', '<div>b) monitoring to detect any failure to remain within critical limit and/or measurable/observable action criteria</div>'),
    ('3060756e-45de-4aaa-9b01-d916c684eda2', '0ea62979-31ce-4355-8604-75f929fb1b01', 'es', '', '<div>b) seguimiento para detectar cualquier falla en permanecer dentro del lí­mite crí­tico y/o criterios de acción medibles/observables</div>'),
    ('185f8006-fdb9-4682-8a7d-41aed6faf882', '0ba624c0-f0a5-41c0-bf86-d1a626fb1648', 'en', '', '<div>c) applying timely corrections in case of failure.</div>'),
    ('355fadad-93ea-48d9-a70e-e5e1cbfae731', '0ba624c0-f0a5-41c0-bf86-d1a626fb1648', 'es', '', '<div>c) aplicar correcciones oportunas en caso de falla.</div>'),
    ('c5af922f-1fbd-45db-9098-6e9b742badcb', '0ca62653-e234-497b-a311-0fc327fb17db', 'en', 'Validation of control measure(s) and combinations of control measures', '<div>The food safety team shall validate that the selected control measures are capable of achieving the intended control of the significant food safety hazard(s). This validation shall be done prior to implementation of control measure(s) and combinations of control measures to be included in the hazard control plan (see 8.5.4) and after any change therein (see 7.4.2, 7.4.3, 10.2 and 10.3).</div><div>When the result of validation shows that the control measures(s) is (are) not capable of achieving the intended control, the food safety team shall modify and re-assess the control measure(s) and/or combination(s) of control measure(s).</div><div>The food safety team shall maintain the validation methodology and evidence of capability of the control measure(s) to achieve the intended control as documented information.</div><div>NOTE: Modification can include changes in control measure(s) (i.e. process parameters, rigour and/or their combination) and/or change(s) in the manufacturing technologies for raw materials, end product characteristics, methods of distribution and intended use of the end products.</div>'),
    ('b8af7db8-9899-49dc-8b21-db607f2bbf1c', '0ca62653-e234-497b-a311-0fc327fb17db', 'es', 'Validación de las medidas de control y combinaciones de medidas de control', '<div>El equipo de inocuidad de los alimentos debe validar que las medidas de control seleccionadas sean capaces de lograr el control previsto de los peligros significativos para la inocuidad de los alimentos. Esta validación debe hacerse antes de la implementación de las medidas de control y combinaciones de medidas de control para ser incluidas en el plan de control de peligros (véase 8.5.4) y después de todo cambio en las mismas (véase 7.4.2, 7.4.3, 10.2 y 10.3).</div><div>Cuando el resultado de la validación muestra que las medidas de control no son capaces de lograr el control previsto, el equipo de inocuidad de los alimentos debe modificar y volver a evaluar las medidas de control y/o las combinaciones de medidas de control.</div><div>El equipo de inocuidad de los alimentos debe mantener la metodologí­a de validación y la evidencia de la capacidad de las medidas de control para lograr el control previsto como información documentada.</div><div>NOTA: La modificación puede incluir cambios en las medidas de control (es decir, parámetros del proceso, rigor y/o combinación) y/o cambios en las tecnologí­as de fabricación de materias primas, caracterí­sticas del producto terminado, métodos de distribución y uso previsto del producto terminado.</div>'),
    ('593c8ef0-4c41-48e4-b098-89d88f15edf4', '19a63aca-0cf1-48e6-afea-c0e024fb1322', 'en', 'Hazard control plan (HACCP/OPRP plan)', '<div>{clause_8.5.4.1}</div><div>{clause_8.5.4.2}</div><div>{clause_8.5.4.3}</div><div>{clause_8.5.4.4}</div><div>{clause_8.5.4.5}</div>'),
    ('563c8a37-3ee8-4a33-bcfe-c9e37415c373', '19a63aca-0cf1-48e6-afea-c0e024fb1322', 'es', 'Plan de control de peligros (plan HACCP/PPRO)', '<div>{clause_8.5.4.1}</div><div>{clause_8.5.4.2}</div><div>{clause_8.5.4.3}</div><div>{clause_8.5.4.4}</div><div>{clause_8.5.4.5}</div>'),
    ('7f7d3381-a76e-4c5d-b866-fbbd28892895', '1aa63c5d-ce91-47e1-93b9-6d1d25fb14b5', 'en', 'General', '<div>The organization shall establish, implement and maintain a hazard control plan. The hazard control plan shall be maintained as documented information and shall include the following information for each control measure at each CCP or OPRP:</div><div>{clause_8.5.4.1.a}</div><div>{clause_8.5.4.1.b}</div><div>{clause_8.5.4.1.c}</div><div>{clause_8.5.4.1.d}</div><div>{clause_8.5.4.1.e}</div><div>{clause_8.5.4.1.f}</div>'),
    ('6a7d1272-33ac-49ce-904f-f1221b89141e', '1aa63c5d-ce91-47e1-93b9-6d1d25fb14b5', 'es', 'Generalidades', '<div>La organización debe establecer, implementar y mantener un plan de control de peligros. El plan de control de peligros se debe mantener como información documentada y debe incluir la información siguiente para cada medida de control en cada PCC o PPRO:</div><div>{clause_8.5.4.1.a}</div><div>{clause_8.5.4.1.b}</div><div>{clause_8.5.4.1.c}</div><div>{clause_8.5.4.1.d}</div><div>{clause_8.5.4.1.e}</div><div>{clause_8.5.4.1.f}</div>'),
    ('91ea24df-4d9a-42c3-999e-c72b05837033', '97a93fbb-5309-4f9f-bf33-be3392fdfee3', 'en', '', '<div>a) food safety hazard(s) to be controlled at the CCP or by the OPRP</div>'),
    ('a4ea42c8-9e7a-4694-910e-795020839ab4', '97a93fbb-5309-4f9f-bf33-be3392fdfee3', 'es', '', '<div>a) peligros relacionados con la inocuidad de los alimentos a ser controlados en el PCC o por el PPRO </div>'),
    ('b1e035b6-4749-406a-9feb-6efed4f8e30a', '96a93e28-e42d-4454-a8bd-dc9691fdfd50', 'en', '', '<div>b) critical limit(s) at CCP or action criteria for OPRP</div>'),
    ('aee030fd-6354-41f1-ae1d-80d1d9f8eae9', '96a93e28-e42d-4454-a8bd-dc9691fdfd50', 'es', '', '<div>b) lí­mites crí­ticos en el PCC o criterios de acción para el PPRO</div>'),
    ('b6433c75-a6a1-4299-90d6-91694d7c0279', '99a942e1-cb77-4d49-8cba-11a994fe0209', 'en', '', '<div>c) monitoring procedure(s)</div>'),
    ('a94327fe-2743-4f42-827f-3c86687c2cfa', '99a942e1-cb77-4d49-8cba-11a994fe0209', 'es', '', '<div>c) procedimientos de seguimiento</div>'),
    ('92a41054-2f13-4970-8dcc-6f94d65ac0c8', '98a9414e-c1a5-438e-aed0-15ac93fe0076', 'en', '', '<div>d) correction(s) to be made if critical limits or action criteria are not met</div>'),
    ('77a3e5d3-ceb4-4537-8719-cf27c35aa2df', '98a9414e-c1a5-438e-aed0-15ac93fe0076', 'es', '', '<div>d) correcciones a tomar, si no se cumplen los lí­mites crí­ticos o los criterios de acción</div>'),
    ('dc9c7833-1849-4397-9662-7607bad11cdf', '9ba94607-5258-4ecb-912b-374f96fe052f', 'en', '', '<div>e) responsibilities and authorities</div>'),
    ('f79ca2b4-78a8-47d0-bb64-8bf4cdd13ac8', '9ba94607-5258-4ecb-912b-374f96fe052f', 'es', '', '<div>e) responsabilidades y autoridades</div>'),
    ('ac11eb0a-475e-48ee-8e93-023adac72db6', '9aa94474-60c9-4710-b413-534295fe039c', 'en', '', '<div>f) records of monitoring.</div>'),
    ('b111f2e9-d140-43fd-983c-ca25d7c728fd', '9aa94474-60c9-4710-b413-534295fe039c', 'es', '', '<div>f) registros de seguimiento.</div>'),
    ('24950a79-bf78-478d-90a9-3b55df2a3475', '9da9492d-a1f2-48a5-bd9f-2e1598fe0855', 'en', 'Determination of critical limits and action criteria', '<div>Critical limits at CCPs and action criteria for OPRPs shall be specified. The rationale for their determination shall be maintained as documented information.</div><div>Critical limits at CCPs shall be measurable. Conformance with critical limits shall ensure that the acceptable level is not exceeded.</div><div>Action criteria for OPRPs shall be measurable or observable. Conformance with action criteria shall contribute to the assurance that the acceptable level is not exceeded.</div>'),
    ('3f9534fa-f171-469e-aaef-3c8ad22a1ffe', '9da9492d-a1f2-48a5-bd9f-2e1598fe0855', 'es', 'Determinación de lí­mites crí­ticos y criterios de acción', '<div>Se deben especificar los lí­mites crí­ticos en los PCC y los criterios de acción para los PPRO. La razón de su determinación se debe mantener como información documentada.</div><div>Los lí­mites crí­ticos en los PCC deben ser medibles. La conformidad con los lí­mites crí­ticos debe asegurar que no se exceda el nivel aceptable.</div><div>Los criterios de acción para los PPRO deben ser medibles u observables. La conformidad con los criterios de acción debe contribuir a la garantí­a de que no se excede el nivel aceptable. </div>'),
    ('ad73c8c8-93ef-4e14-8085-6f50bb8b0854', '9ca9479a-682b-453a-bbf5-2cf897fe06c2', 'en', 'Monitoring systems at CCPs and for OPRPs', '<div>At each CCP, a monitoring system shall be established for each control measure or combination of control measure(s) to detect any failure to remain within the critical limits. The system shall include all scheduled measurements relative to the critical limit(s).</div><div>For each OPRP, a monitoring system shall be established for the control measure or combination of control measure(s) to detect failure to meet the action criterion.</div><div>The monitoring system, at each CCP and for each OPRP, shall consist of documented information, including:</div><div>{clause_8.5.4.3.a}</div><div>{clause_8.5.4.3.b}</div><div>{clause_8.5.4.3.c}</div><div>{clause_8.5.4.3.d}</div><div>{clause_8.5.4.3.e}</div><div>{clause_8.5.4.3.f}</div><div>{clause_8.5.4.3.g}</div><div>At each CCP, the monitoring method and frequency shall be capable of timely detection of any failure to remain within critical limits, to allow timely isolation and evaluation of the product (see 8.9.4).</div><div>For each OPRP, the monitoring method and frequency shall be proportionate to the likelihood of failure and the severity of consequences.</div><div>When monitoring an OPRP is based on subjective data from observations (e.g. visual inspection), the method shall be supported by instructions or specifications.</div>'),
    ('9a73aadf-430e-4a43-8915-bd2ba08addd3', '9ca9479a-682b-453a-bbf5-2cf897fe06c2', 'es', 'Sistemas de seguimiento en los PCC y para los PPRO', '<div>En cada PCC, se debe establecer un sistema de seguimiento para cada medida de control o combinación de medidas de control para detectar toda falla en permanecer dentro de los lí­mites crí­ticos. El sistema debe incluir todas las mediciones programadas relacionadas con los lí­mites crí­ticos. </div><div>Para cada PPRO, se debe establecer un sistema de seguimiento para la medida de control o combinación de medidas de control para detectar el incumplimiento del criterio de acción.</div><div>El sistema de seguimiento, en cada PCC y para cada PPRO, debe consistir en información documentada, incluyendo:</div><div>{clause_8.5.4.3.a}</div><div>{clause_8.5.4.3.b}</div><div>{clause_8.5.4.3.c}</div><div>{clause_8.5.4.3.d}</div><div>{clause_8.5.4.3.e}</div><div>{clause_8.5.4.3.f}</div><div>{clause_8.5.4.3.g}</div><div>En cada PCC, el método y la frecuencia de seguimiento deben ser capaces de detectar oportunamente toda falla para permanecer dentro de los lí­mites crí­ticos de manera que permita oportunamente el aislamiento y la evaluación del producto (véase 8.9.4).</div><div>Para cada PPRO, el método y frecuencia de seguimiento deben ser proporcionales a la probabilidad de falla y la gravedad de las consecuencias.</div><div>Cuando el seguimiento de un PPRO se basa en datos subjetivos de observaciones (por ejemplo, inspección visual), el método debe ser respaldado por instrucciones o especificaciones.</div>'),
    ('2a8d13d7-3729-404b-b9fc-9503a09f352b', '8fa93323-2bff-43a7-9f52-2e4b9afe0b7b', 'en', '', '<div>a) measurements or observations that provide results within an adequate time frame</div>'),
    ('2d8d1890-5293-496c-8427-0bf8ab9f467c', '8fa93323-2bff-43a7-9f52-2e4b9afe0b7b', 'es', '', '<div>a) las mediciones u observaciones que proporcionen resultados dentro de un perí­odo de tiempo adecuado</div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('4cfd8dae-7759-4d72-8247-69d690166d62', '8ea93190-83d6-40fc-a1d9-8ace99fe09e8', 'en', '', '<div>b) monitoring methods or devices used</div>'),
    ('39fd6fc5-4de3-4569-9175-7a1985165c11', '8ea93190-83d6-40fc-a1d9-8ace99fe09e8', 'es', '', '<div>b) los métodos de seguimiento o dispositivos utilizados </div>'),
    ('ee6d9f56-21b2-4ade-a114-939e14040022', '9dab87c4-e5de-4810-a153-a7f6990046ec', 'en', '', '<div>c) applicable calibration methods or, for OPRPs, equivalent methods for verification of reliable measurements or observations (see 8.7)</div>'),
    ('eb6d9a9d-ed3d-4fcd-970c-57f10903eed1', '9dab87c4-e5de-4810-a153-a7f6990046ec', 'es', '', '<div>c) los métodos de calibración aplicables o, para los PPRO, los métodos equivalentes para la verificación de las mediciones u observaciones confiables (véase 8.7) </div>'),
    ('5b1f7bff-9523-4307-8692-764b248e5aeb', '9eab8957-d76e-4fcb-bb35-f6139a00487f', 'en', '', '<div>d) monitoring frequency</div>'),
    ('6e1f99e8-9bdd-4ca0-98cd-62702f8e6c3c', '9eab8957-d76e-4fcb-bb35-f6139a00487f', 'es', '', '<div>d) la frecuencia del seguimiento</div>'),
    ('5bd7d474-5ce1-4784-ad46-a334620d66a0', '9fab8aea-ed41-463a-93ae-e50c9b004a12', 'en', '', '<div>e) monitoring results</div>'),
    ('40d7a9f3-4f86-45d3-9f66-aa477f0d9447', '9fab8aea-ed41-463a-93ae-e50c9b004a12', 'es', '', '<div>e) los resultados del seguimiento</div>'),
    ('f54b0f15-269f-427d-97d4-0d09f88f76f1', 'a0ab8c7d-2708-49a5-b927-98099c004ba5', 'en', '', '<div>f) responsibility and authority related to monitoring</div>'),
    ('e84afa9e-9cbc-476e-9db5-a8a6038f8842', 'a0ab8c7d-2708-49a5-b927-98099c004ba5', 'es', '', '<div>f) la responsabilidad y autoridad relacionadas con el seguimiento</div>'),
    ('e8a0e7aa-379f-45da-82ea-865af9d2186e', '99ab8178-6943-4554-a6c2-7da2950040a0', 'en', '', '<div>g) responsibility and authority related to evaluation of monitoring results.</div>'),
    ('eda0ef89-fbde-4f01-a7d2-3dc5e6d1fa85', '99ab8178-6943-4554-a6c2-7da2950040a0', 'es', '', '<div>g) la responsabilidad y autoridad relacionadas con la evaluación de los resultados del seguimiento. </div>'),
    ('1ba44ad3-814b-46f3-8253-f8a7d9dd9a97', '9aab830b-d81f-409f-8b74-1daf96004233', 'en', 'Actions when critical limits or action criteria are not met', '<div>The organization shall specify corrections (see 8.9.2) and corrective actions (see 8.9.3) to be taken when critical limits or action criterion are not met and shall ensure that:</div><div>{clause_8.5.4.4.a}</div><div>{clause_8.5.4.4.b}</div><div>{clause_8.5.4.4.c}</div><div>{clause_8.5.4.4.d}</div><div>The organization shall make corrections in accordance with 8.9.2 and corrective actions in accordance with 8.9.3.</div>'),
    ('36a47554-7559-43a4-8906-9914dcdd9f50', '9aab830b-d81f-409f-8b74-1daf96004233', 'es', 'Acciones cuando no se cumplen los lí­mites crí­ticos o los criterios de acción', '<div>La organización debe especificar las correcciones (véase 8.9.2) y las acciones correctivas (véase 8.9.3) a tomarse cuando no se cumplen los lí­mites crí­ticos o el criterio de acción y se debe asegurar que:</div><div>{clause_8.5.4.4.a}</div><div>{clause_8.5.4.4.b}</div><div>{clause_8.5.4.4.c}</div><div>{clause_8.5.4.4.d}</div><div>La organización debe tomar correcciones en conformidad con el apartado 8.9.2 y acciones correctivas en conformidad con el apartado 8.9.3.</div>'),
    ('76a91fe8-2ac1-46a0-8844-5870473c1b2c', '9bab849e-46bb-448e-96dd-0058970043c6', 'en', '', '<div>a) the potentially unsafe products are not released (see 8.9.4)</div>'),
    ('63a901ff-2407-4d07-b609-6c4b5c3c3c3b', '9bab849e-46bb-448e-96dd-0058970043c6', 'es', '', '<div>a) los productos potencialmente no inocuos no sean liberados (véase 8.9.4)</div>'),
    ('edc8ce99-b22a-4689-b7c3-cbf5fe351f2d', '9cab8631-508c-4e49-9e3e-e4f598004559', 'en', '', '<div>b) the cause of nonconformity is identified</div>'),
    ('08c8f91a-c254-4992-af06-1eaae134f186', '9cab8631-508c-4e49-9e3e-e4f598004559', 'es', '', '<div>b) se identifica la causa de la no conformidad </div>'),
    ('163151ce-fe9d-4826-88bb-12f65b6271ca', '95ab7b2c-bba6-4f98-912e-e72ea1005384', 'en', '', '<div>c) the parameter(s) controlled at the CCP or by the OPRP is (are) returned within the critical limits or action criteria</div>'),
    ('033133e5-6ad6-4165-8833-8c39606279a9', '95ab7b2c-bba6-4f98-912e-e72ea1005384', 'es', '', '<div>c) los parámetros controlados en el PCC o por el PPRO, vuelven a estar dentro de los lí­mites crí­ticos o los criterios de acción</div>'),
    ('f63b40f7-daf5-488f-b4c4-46238beb6bf3', '96ab7cbf-2dd8-49d3-97b1-30aba2005517', 'en', '', '<div>d) recurrence is prevented.</div>'),
    ('f93b45b0-ea14-4b58-a47e-7518a6eb9674', '96ab7cbf-2dd8-49d3-97b1-30aba2005517', 'es', '', '<div>d) se previene la recurrencia.</div>'),
    ('bfaa9c85-b62d-41ad-b6fc-46590569d221', 'a3adcfcd-6b32-4cd9-befd-4af99f028ef5', 'en', 'Implementation of the hazard control plan', '<div>The organization shall implement and maintain the hazard control plan, and retain evidence of the implementation as documented information.</div>'),
    ('d2aaba6e-ced9-4bbe-b884-a616f069b112', 'a3adcfcd-6b32-4cd9-befd-4af99f028ef5', 'es', 'Implementación del plan de control de peligros', '<div>La organización debe implementar y mantener el plan de control de peligros y mantener evidencia de la implementación como información documentada.</div>'),
    ('28b1cae4-09fe-44b4-ac38-c9446e485e10', 'a2adce3a-648c-4c9e-a7ff-167c9e028d62', 'en', 'Updating the information specifying the PRPs and the hazard control plan', '<div>Following the establishment of the hazard control plan, the organization shall update the following information, if necessary:</div><div>{clause_8.6.a}</div><div>{clause_8.6.b}</div><div>{clause_8.6.c}</div><div>{clause_8.6.d}</div><div>The organization shall ensure that the hazard control plan and/or the PRP(s) are up to date.</div>'),
    ('2db1d2c3-a2ff-4863-9263-71776b485957', 'a2adce3a-648c-4c9e-a7ff-167c9e028d62', 'es', 'Actualización de la información que especifica los PPR y el plan de control de peligros', '<div>Después del establecimiento del plan de control de peligros, la organización debe actualizar la siguiente información, si es necesario:</div><div>{clause_8.6.a}</div><div>{clause_8.6.b}</div><div>{clause_8.6.c}</div><div>{clause_8.6.d}</div><div>La organización debe asegurarse que el plan de control de peligros y/o los PPR estén actualizados.</div>'),
    ('67f9d72f-8e57-4737-ae1b-3b9b30c9525b', 'a1adcca7-f2c4-4f2f-9c09-e4c39d028bcf', 'en', '', '<div>a) characteristics of raw materials, ingredients and product-contact materials</div>'),
    ('5af9c2b8-eeb6-4b70-a8a4-a8601bc9314c', 'a1adcca7-f2c4-4f2f-9c09-e4c39d028bcf', 'es', '', '<div>a) las caracterí­sticas de las materias primas, los ingredientes y los materiales que entran en contacto con el producto</div>'),
    ('baa9c506-ced0-480e-a800-0eaee0df8992', 'a0adcb14-83e6-40e4-b87f-a6a69c028a3c', 'en', '', '<div>b) characteristics of end products</div>'),
    ('d7a9f2ad-5bdd-4c9d-8491-b2e1f5dfaaa1', 'a0adcb14-83e6-40e4-b87f-a6a69c028a3c', 'es', '', '<div>b) las caracterí­sticas de los productos terminados</div>'),
    ('fa055909-eea5-46b9-8cd9-4345cb0f159d', '9fadc981-2b8c-4cb5-ad15-06659b0288a9', 'en', '', '<div>c) intended use</div>'),
    ('f505512a-5ba3-43e2-a7f1-8bdace0f1a56', '9fadc981-2b8c-4cb5-ad15-06659b0288a9', 'es', '', '<div>c) el uso previsto</div>'),
    ('42e3b298-917c-4d90-aae5-eb405416765c', '9eadc7ee-0747-410a-ad07-ea089a028716', 'en', '', '<div>d) flow diagrams and descriptions of processes and process environment.</div>'),
    ('4fe3c70f-2ea3-4057-b5c5-ff7b4916650b', '9eadc7ee-0747-410a-ad07-ea089a028716', 'es', '', '<div>d) los diagramas de flujo y descripciones de los procesos y su entorno.</div>'),
    ('b4859cc3-d838-4e63-9cac-ecf772beec87', '9dadc65b-f211-4b5b-a273-571f99028583', 'en', 'Control of monitoring and measuring', '<div>The organization shall provide evidence that the specified monitoring and measuring methods and equipment in use are adequate for the monitoring and measuring activities related to the PRP(s) and the hazard control plan.</div><div>The monitoring and measuring equipment used shall be:</div><div>{clause_8.7.a}</div><div>{clause_8.7.b}</div><div>{clause_8.7.c}</div><div>{clause_8.7.d}</div><div>{clause_8.7.e}</div><div>The results of calibration and verification shall be retained as documented information. The calibration of all the equipment shall be traceable to international or national measurement standards where no standards exist, the basis used for calibration or verification shall be retained as documented information.</div><div>The organization shall assess the validity of the previous measurement results when the equipment or process environment is found not to conform to requirements. The organization shall take appropriate action in relation to the equipment or process environment and any product affected by the nonconformance.</div><div>The assessment and resulting action shall be maintained as documented information.</div><div>Software used in monitoring and measuring within the FSMS shall be validated by the organization, software supplier or third party prior to use. Documented information on validation activities shall be maintained by the organization and the software shall be updated in a timely manner.</div><div>Whenever there are changes, including software configuration/modifications to commercial off-theshelf software, they shall be authorized, documented and validated before implementation.</div><div>NOTE: Commercial off-the-shelf software in general use within its designed application range can be considered to be sufficiently validated. </div>'),
    ('af8594e4-3f38-4ab4-b682-44c455bebee0', '9dadc65b-f211-4b5b-a273-571f99028583', 'es', 'Control del seguimiento y la medición', '<div>La organización debe proporcionar evidencia que los métodos y los equipos de seguimiento y medición especificados son adecuados para las actividades de seguimiento y la medición relacionados con los PPR y el plan de control de peligros.</div><div>Los equipos de seguimiento y medición utilizados deben:</div><div>{clause_8.7.a}</div><div>{clause_8.7.b}</div><div>{clause_8.7.c}</div><div>{clause_8.7.d}</div><div>{clause_8.7.e}</div><div>Los resultados de la calibración y la verificación se deben conservar como información documentada. La calibración de todos los equipos debe ser trazable a patrones de medición nacionales o internacionales cuando no existan tales patrones, la base utilizada para la calibración o verificación se debe conservar como información documentada. </div><div>La organización debe evaluar la validez de los resultados de las mediciones previas cuando se detecte que el equipo o el entorno del proceso no son conformes con los requisitos. La organización debe tomar las acciones apropiadas en relación a los equipos o el entorno de los procesos y todo producto afectado por la no conformidad.</div><div>La evaluación y la acción resultante se deben mantener como información documentada.</div><div>El software utilizado en el seguimiento y medición dentro del SGIA debe ser validado por la organización, el proveedor de softwares o un tercero antes de su uso. La organización debe mantener la información documentada sobre las actividades de validación y el software debe actualizarse oportunamente. </div><div>Siempre que haya cambios, incluida la configuración/modificaciones de los softwares comerciales, se deben autorizar, documentar y validar antes de la implementación.</div><div>NOTA: Un software comercial, de uso general dentro de su rango de aplicación diseñado, se puede considerar suficientemente validado.&nbsp</div>'),
    ('f57b42da-e806-418a-8f39-d2eac60e3e1e', '9cadc4c8-0083-46a0-bf75-eb12980283f0', 'en', '', '<div>a) calibrated or verified at specified intervals prior to use</div>'),
    ('da7b1859-f06c-4391-bd11-b335d30e5295', '9cadc4c8-0083-46a0-bf75-eb12980283f0', 'es', '', '<div>a) calibrarse o verificarse a intervalos especificados antes de su utilización </div>'),
    ('e76e4efd-8cba-4935-8ea7-0b516cc6e329', '9badc335-c850-4441-b674-6a51a7029b8d', 'en', '', '<div>b) adjusted or re-adjusted as necessary</div>'),
    ('ea6e53b6-a994-4b16-8074-f97e67c6db4a', '9badc335-c850-4441-b674-6a51a7029b8d', 'es', '', '<div>b) ajustarse o reajustarse cuando sea necesario</div>'),
    ('e154ec3c-212e-453c-a82c-a23c26860c38', '9aadc1a2-1a55-44c6-bf99-80f4a60299fa', 'en', '', '<div>c) identified to enable the calibration status to be determined</div>'),
    ('d654daeb-c41a-4f3b-8ad3-a6bf338620af', '9aadc1a2-1a55-44c6-bf99-80f4a60299fa', 'es', '', '<div>c) identificarse para determinar su estado de calibración</div>'),
    ('67bce7fc-02be-4958-a858-d2fc813365a8', '09b0aef6-2d2a-4212-a277-9134a504d6fe', 'en', '', '<div>d) safeguarded from adjustments that would invalidate the measurement results</div>'),
    ('5cbcd6ab-f3a0-468f-90e6-be7f6e3347bf', '09b0aef6-2d2a-4212-a277-9134a504d6fe', 'es', '', '<div>d) protegerse contra ajustes que pudieran invalidar el resultado de la medición</div>'),
    ('6b5d74bd-b6fb-47a1-8c87-2611facf1059', '0ab0b089-a03c-49dd-ad60-cd91a604d891', 'en', '', '<div>e) protected from damage and deterioration.</div>'),
    ('6e5d7976-f2bb-4b7a-b023-283e15cf3ada', '0ab0b089-a03c-49dd-ad60-cd91a604d891', 'es', '', '<div>e) protegerse contra los daños y el deterioro.</div>'),
    ('665b0a3e-d99a-42b2-b071-0546f5a5966a', '07b0abd0-75d2-4488-8714-d61ea304d3d8', 'en', 'Verification related to PRPs and the hazard control plan', '<div>{clause_8.8.1}</div><div>{clause_8.8.2}</div>'),
    ('735b1eb5-cbeb-48a9-b694-f529faa59e49', '07b0abd0-75d2-4488-8714-d61ea304d3d8', 'es', 'Verificación relacionada con los PPR y el plan de control de peligros', '<div>{clause_8.8.1}</div><div>{clause_8.8.2}</div>'),
    ('86655e27-5cbd-4e8b-b122-c033262e9093', '08b0ad63-e4d5-4f43-a4ad-355ba404d56b', 'en', 'Verification', '<div>The organization shall establish, implement and maintain verification activities. The verification planning shall define purpose, methods, frequencies and responsibilities for the verification activities.</div><div>The verification activities shall confirm that:</div><div>{clause_8.8.1.a}</div><div>{clause_8.8.1.b}</div><div>{clause_8.8.1.c}</div><div>{clause_8.8.1.d}</div><div>{clause_8.8.1.e}</div><div>The organization shall ensure that verification activities are not carried out by the person responsible for monitoring the same activities.</div><div>Verification results shall be retained as documented information and shall be communicated.</div><div>Where verification is based on testing of end product samples or direct process samples and where such test samples show nonconformity with the acceptable level of the food safety hazard (see 8.5.2.2), the organization shall handle the affected lot(s) of product as potentially unsafe (see 8.9.4.3) and apply corrective actions in accordance with 8.9.3.</div>'),
    ('69653080-7827-47ac-9e28-4cc8412ebb14', '08b0ad63-e4d5-4f43-a4ad-355ba404d56b', 'es', 'Verificación', '<div>La organización debe establecer, implementar y mantener las actividades de verificación. La planificación de la verificación debe definir el propósito, método, frecuencia y responsabilidades para las actividades de verificación.</div><div>Las actividades de verificación deben confirmar que: </div><div>{clause_8.8.1.a}</div><div>{clause_8.8.1.b}</div><div>{clause_8.8.1.c}</div><div>{clause_8.8.1.d}</div><div>{clause_8.8.1.e}</div><div>La organización debe asegurar que las actividades de verificación no son llevadas a cabo por la persona responsable del seguimiento de las mismas actividades.</div><div>Los resultados de la verificación deben conservarse como información documentada y deben ser comunicados. </div><div>Cuando la verificación está basada en ensayos de muestras del producto terminado o muestras directas del proceso, y cuando tales muestras de ensayo presentan no conformidad con el nivel aceptable de peligros para la inocuidad de los alimentos (véase 8.5.2.2), la organización debe manipular los lotes de productos afectados como potencialmente no inocuos (véase 8.9.4.3) y aplicar acciones correctivas según el apartado 8.9.3.</div>'),
    ('81eecfb0-4206-4e5c-9088-6d9868de1634', '0db0b542-a08d-4326-b8ee-9120a904dd4a', 'en', '', '<div>a) the PRP(s) are implemented and effective</div>'),
    ('7eeecaf7-c92b-4a5b-a0ce-3ea34dddebb3', '0db0b542-a08d-4326-b8ee-9120a904dd4a', 'es', '', '<div>a) los PPR se han implementado y son eficaces </div>'),
    ('a5b69e41-ab19-4c55-8259-887dffd6e7d5', '0eb0b6d5-7df6-4321-9d86-fb5daa04dedd', 'en', '', '<div>b) the hazard control plan is implemented and effective</div>'),
    ('90b67d32-b1d2-42b6-9cf8-49e2f2d6d35e', '0eb0b6d5-7df6-4321-9d86-fb5daa04dedd', 'es', '', '<div>b) el plan de control de peligros se implementa y es eficaz</div>'),
    ('812c55b2-d9af-4b36-a9bf-c562fb73e116', '0bb0b21c-d897-4bac-844e-a56aa704da24', 'en', '', '<div>c) hazard levels are within identified acceptable levels</div>'),
    ('962c76c1-d2f7-44d5-8f21-03fdf873dc5d', '0bb0b21c-d897-4bac-844e-a56aa704da24', 'es', '', '<div>c) los niveles de los peligros están dentro de los niveles aceptables identificados </div>'),
    ('d3921a7b-9051-4d5f-a59c-802f68242abf', '0cb0b3af-51f3-4497-8283-3ed7a804dbb7', 'en', '', '<div>d) input to the hazard analysis is updated</div>'),
    ('be91f96c-4845-4e88-98f9-ff8c7b2448a8', '0cb0b3af-51f3-4497-8283-3ed7a804dbb7', 'es', '', '<div>d) los elementos de entrada para el análisis de peligros estén actualizados </div>'),
    ('aca0f0a4-05d2-46b0-b6eb-f604fc508b40', '11b0bb8e-8d80-426a-b9c5-80bc9d04ca66', 'en', '', '<div>e) other actions determined by the organization are implemented and effective.</div>'),
    ('b1a0f883-8c26-4d77-a6c2-0f371950b8e7', '11b0bb8e-8d80-426a-b9c5-80bc9d04ca66', 'es', '', '<div>e) otras acciones determinadas por la organización estén implementadas y son eficaces.</div>'),
    ('46142b45-cc36-43d9-88e1-5e19954d0491', '12b0bd21-e131-4b95-bff9-92399e04cbf9', 'en', 'Analysis of results of verification activities', '<div>The food safety team shall conduct an analysis of the results of verification that shall be used as an input to the performance evaluation of the FSMS (see 9.1.2).</div>'),
    ('5914492e-3605-4182-b9b3-4dd6a04d15e2', '12b0bd21-e131-4b95-bff9-92399e04cbf9', 'es', 'Análisis de los resultados de las actividades de verificación', '<div>El equipo de inocuidad de los alimentos debe realizar un análisis de los resultados de la verificación que se debe utilizar como entrada de la evaluación del desempeño del SGIA (véase 9.1.2).</div>'),
    ('64e9dce3-3ff7-41cf-9115-d41772841cef', '0fb2f6ff-3c5f-4313-8f5c-d77f2b07e887', 'en', 'Control of product and process nonconformities', '<div>{clause_8.9.1}</div><div>{clause_8.9.2}</div><div>{clause_8.9.3}</div><div>{clause_8.9.4}</div><div>{clause_8.9.5}</div>'),
    ('5fe9d504-518e-4a98-a1f5-42e465840878', '0fb2f6ff-3c5f-4313-8f5c-d77f2b07e887', 'es', 'Control de las no conformidades del producto y el proceso', '<div>{clause_8.9.1}</div><div>{clause_8.9.2}</div><div>{clause_8.9.3}</div><div>{clause_8.9.4}</div><div>{clause_8.9.5}</div>'),
    ('32844a7a-d55d-4866-9653-008ac7b006c6', '0eb2f56c-e37c-40d8-859c-17f22a07e6f4', 'en', 'General', '<div>The organization shall ensure that data derived from the monitoring of OPRPs and at CCPs are evaluated by designated persons who are competent and have the authority to initiate corrections and corrective actions.</div>'),
    ('17841ff9-284a-4ca5-bc0c-ff55e4b0346d', '0eb2f56c-e37c-40d8-859c-17f22a07e6f4', 'es', 'Generalidades', '<div>La organización debe asegurarse que los datos derivados del seguimiento de los PPRO y de los PCC sean evaluados por personas designadas que sean competentes y tengan la autoridad para iniciar correcciones y acciones correctivas.</div>'),
    ('3988c9a9-9a88-4005-bf8b-7ee5ccb0de45', '11b2fa25-1100-42ed-9bfe-97c52d07ebad', 'en', 'Corrections', '<div>{clause_8.9.2.1}</div><div>{clause_8.9.2.2}</div><div>{clause_8.9.2.3}</div><div>{clause_8.9.2.4}</div>'),
    ('3488c1ca-5b42-4e46-8c9b-4dfadfb0fc2e', '11b2fa25-1100-42ed-9bfe-97c52d07ebad', 'es', 'Correcciones', '<div>{clause_8.9.2.1}</div><div>{clause_8.9.2.2}</div><div>{clause_8.9.2.3}</div><div>{clause_8.9.2.4}</div>'),
    ('f347f2b8-f10d-4f0c-8a47-7a60333da3a4', '10b2f892-b69b-4c62-ba87-d0e82c07ea1a', 'en', '', '<div>The organization shall ensure that when critical limits at CCP(s) and/or action criteria for OPRPs are not met, the products affected are identified and controlled with regard to their use and release.</div><div>The organization shall establish, maintain and update documented information that includes:</div><div>{clause_8.9.2.1.a}</div><div>{clause_8.9.2.1.b}</div>'),
    ('0048072f-d5a3-45eb-8fbe-0d9b383dab83', '10b2f892-b69b-4c62-ba87-d0e82c07ea1a', 'es', '', '<div>La organización debe asegurarse que, cuando no se cumplen los lí­mites crí­ticos para los PCC y/o los criterios de acción para los PPRO, los productos afectados se identifican y controlan en lo que concierne a su uso y liberación.</div><div>La organización debe establecer, mantener y actualizar información documentada que incluya: </div><div>{clause_8.9.2.1.a}</div><div>{clause_8.9.2.1.b}</div>'),
    ('185c844f-586b-4bbb-a198-e1bbbf117583', '0bb2f0b3-bf9d-40e7-ac91-ad232707e23b', 'en', '', '<div>a) a method of identification, assessment and correction for affected products to ensure their proper handling</div>'),
    ('0b5c6fd8-b580-41bc-a8c6-6780ba116da4', '0bb2f0b3-bf9d-40e7-ac91-ad232707e23b', 'es', '', '<div>a) un método de identificación, evaluación y corrección de los productos afectados para asegurar su apropiada manipulación </div>'),
    ('fa2d35a6-8c5f-4562-a3f4-28ce027ff19a', '0ab2ef20-30c0-433c-88c6-6b862607e0a8', 'en', '', '<div>b) arrangements for review of the corrections carried out.</div>'),
    ('172d634d-1f62-4839-8945-2401e77fc719', '0ab2ef20-30c0-433c-88c6-6b862607e0a8', 'es', '', '<div>b) disposiciones para la revisión de las correcciones realizadas.</div>'),
    ('ff2fa025-1db6-4e91-90c1-92f9070a07c9', '0db2f3d9-eb9f-4f71-8cca-b4d92907e561', 'en', '', '<div>When critical limits at CCPs are not met, affected products shall be identified and handled as potentially unsafe products (see 8.9.4).</div>'),
    ('122fbe0e-1550-4c8a-b099-d9b60209ffea', '0db2f3d9-eb9f-4f71-8cca-b4d92907e561', 'es', '', '<div>Cuando no se cumplan los lí­mites crí­ticos en los PCC, los productos afectados deben identificarse y manipularse como productos potencialmente no inocuos (véase 8.9.4).</div>'),
    ('65bc6584-dd11-4848-84de-68e44d6f8b58', '0cb2f246-10b3-4b76-8a84-6e5c2807e3ce', 'en', '', '<div>Where action criteria for an OPRP are not met, the following shall be carried out:</div><div>{clause_8.9.2.3.a}</div><div>{clause_8.9.2.3.b}</div><div>{clause_8.9.2.3.c}</div><div>The organization shall retain results of the evaluation as documented information.</div>'),
    ('6abc6d63-2799-431f-b3fe-fa175a6f9fcf', '0cb2f246-10b3-4b76-8a84-6e5c2807e3ce', 'es', '', '<div>Cuando no se cumplen los criterios de acción para un PPRO, debe llevarse a cabo lo siguiente: </div><div>{clause_8.9.2.3.a}</div><div>{clause_8.9.2.3.b}</div><div>{clause_8.9.2.3.c}</div><div>La organización debe conservar los resultados de la evaluación como información documentada.</div>'),
    ('fd8b38db-6969-4a47-9be1-568f0d021127', '17b30397-ff41-4e0b-b3b9-6df72307dbef', 'en', '', '<div>a) determination of the consequences of that failure with respect to food safety</div>'),
    ('e88b17cc-7021-40e0-9397-96ecf001e380', '17b30397-ff41-4e0b-b3b9-6df72307dbef', 'es', '', '<div>a) la determinación de las consecuencias de esa falla con respecto a la inocuidad de los alimentos</div>'),
    ('ada17012-4746-491e-9b76-36c2ecf7bd3e', '16b30204-f466-4450-a49b-ba0a2207da5c', 'en', '', '<div>b) determination of the cause(s) of failure</div>'),
    ('c2a19121-154d-4a0d-8cb6-ad5df9f7d1b5', '16b30204-f466-4450-a49b-ba0a2207da5c', 'es', '', '<div>b) la determinación de las causas de la falla</div>'),
    ('718c1d1a-4f82-43ca-b81b-b02a6551b48e', '15b53f08-d149-4ec4-996d-a8d290e22540', 'en', '', '<div>c) identification of the affected products and handling in accordance with 8.9.4.</div>'),
    ('568bf299-556c-49d1-80d9-5d75525196a5', '15b53f08-d149-4ec4-996d-a8d290e22540', 'es', '', '<div>c) la identificación de los productos afectados y manipulación de acuerdo con el apartado 8.9.4.</div>'),
    ('2e1da103-aef7-4ba3-868f-7c37455ba3b7', '16b5409b-5972-4f0f-9482-44df91e226d3', 'en', '', '<div>Documented information shall be retained to describe corrections made on nonconforming products and processes, including:</div><div>{clause_8.9.2.4.a}</div><div>{clause_8.9.2.4.b}</div><div>{clause_8.9.2.4.c}</div>'),
    ('291d9924-15f7-47f4-96b9-6304485ba870', '16b5409b-5972-4f0f-9482-44df91e226d3', 'es', '', '<div>Se debe conservar la información documentada que describa las correcciones realizadas en productos y procesos no conformes, incluyendo: </div><div>{clause_8.9.2.4.a}</div><div>{clause_8.9.2.4.b}</div><div>{clause_8.9.2.4.c}</div>'),
    ('bc7bb6d8-f3bd-42d0-b0ee-75802613c9cc', '17b5422e-c80e-42fe-ba10-4ec892e22866', 'en', '', '<div>a) the nature of the nonconformity</div>'),
    ('c97bcb4f-935e-4e97-a9c0-efbb3b13eadb', '17b5422e-c80e-42fe-ba10-4ec892e22866', 'es', '', '<div>a) la naturaleza de la no conformidad</div>'),
    ('76163349-6cf3-44f9-a733-1f85df8736cd', '18b543c1-ceb3-4039-a7c4-462593e229f9', 'en', '', '<div>b) the cause(s) of the failure</div>'),
    ('71162b6a-c0a2-4a22-ba72-f61ac2870926', '18b543c1-ceb3-4039-a7c4-462593e229f9', 'es', '', '<div>b) las causas de la falla</div>'),
    ('36bc3246-f464-464e-b857-6beef2dd41c2', '19b54554-4de5-4180-8b34-056694e22b8c', 'en', '', '<div>c) the consequences as a result of the nonconformity.</div>'),
    ('53bc5fed-6826-48dd-ba90-8a21e7dd3071', '19b54554-4de5-4180-8b34-056694e22b8c', 'es', '', '<div>c) las consecuencias como resultado de la no conformidad.</div>'),
    ('e190486f-4bc9-4f77-b03b-c8db9286cd0b', '1ab546e7-58c1-4e3b-99e3-838395e22d1f', 'en', 'Corrective actions', '<div>The need for corrective actions shall be evaluated when critical limits at CCP(s) and/or action criteria for OPRPs are not met.</div><div>The organization shall establish and maintain documented information that specifies appropriate actions to identify and eliminate the cause of detected nonconformities, to prevent recurrence, and to return the process to control after a nonconformity is identified.</div><div>These actions shall include:</div><div>{clause_8.9.3.a}</div><div>{clause_8.9.3.b}</div><div>{clause_8.9.3.c}</div><div>{clause_8.9.3.d}</div><div>{clause_8.9.3.e}</div><div>{clause_8.9.3.f}</div><div>The organization shall retain documented information on all corrective actions</div>'),
    ('d49033f8-c575-48b0-80a3-eea09d86de5c', '1ab546e7-58c1-4e3b-99e3-838395e22d1f', 'es', 'Acciones correctivas', '<div>La necesidad de acciones correctivas debe ser evaluada cuando los lí­mites crí­ticos de los PCC y/o los criterios de acción para los PPRO no se cumplen.</div><div>La organización debe establecer y mantener la información documentada que especifique las acciones apropiadas para identificar y eliminar la causa de las no conformidades detectadas, para prevenir su recurrencia, y tener el proceso nuevamente bajo control después que se ha identificado la no conformidad. </div><div>Estas acciones deben incluir:</div><div>{clause_8.9.3.a}</div><div>{clause_8.9.3.b}</div><div>{clause_8.9.3.c}</div><div>{clause_8.9.3.d}</div><div>{clause_8.9.3.e}</div><div>{clause_8.9.3.f}</div><div>La organización debe conservar información documentada de todas las acciones correctivas</div>'),
    ('a249cf24-e0bd-41f4-818b-788440e51540', '1bb5487a-54aa-4eea-b81c-673c96e22eb2', 'en', '', '<div>a) reviewing nonconformities identified by customer and/or consumer complaints and/or regulatory inspection reports</div>'),
    ('a749d703-79bd-45a3-b161-91b75de542e7', '1bb5487a-54aa-4eea-b81c-673c96e22eb2', 'es', '', '<div>a) la revisión de las no conformidades identificadas por quejas de clientes y/o consumidores y/o informes de inspecciones reglamentarias </div>'),
    ('3bbd09c5-c4f0-46ed-9380-e099d9e18e91', '1cb54a0d-a85b-4815-be50-78b997e23045', 'en', '', '<div>b) reviewing trends in monitoring results that can indicate loss of control</div>'),
    ('4ebd27ae-f6e9-45fe-8452-d056e4e19fe2', '1cb54a0d-a85b-4815-be50-78b997e23045', 'es', '', '<div>b) la revisión de las tendencias en los resultados del seguimiento que pueden indicar una pérdida de control</div>'),
    ('76d53432-3c03-46d2-b45f-47e240086b16', '0db53270-9fc1-482c-82a5-8bea98e231d8', 'en', '', '<div>c) determining the cause(s) of nonconformities</div>'),
    ('8bd55541-2bda-43c9-99c0-867d3d08665d', '0db53270-9fc1-482c-82a5-8bea98e231d8', 'es', '', '<div>c) la determinación de las causas de las no conformidades </div>'),
    ('c93af8fb-e9d5-402b-b03c-02afacb8b4bf', '0eb53403-191d-4117-80da-255799e2336b', 'en', '', '<div>d) determining and implementing actions to ensure that nonconformities do not recur</div>'),
    ('b43ad7ec-e977-4b4c-a399-820cbfb8d2a8', '0eb53403-191d-4117-80da-255799e2336b', 'es', '', '<div>d) la determinación e implementación de acciones para asegurar que las no conformidades no vuelvan a ocurrir</div>'),
    ('42f029b9-ba61-46e9-a360-cb95368eb1bd', '1bb78711-b01b-4ebd-9cf7-0fd516e536c9', 'en', '', '<div>e) documenting the results of corrective actions taken</div>'),
    ('5df0543a-e3d8-4ef2-a524-a0ca398eb676', '1bb78711-b01b-4ebd-9cf7-0fd516e536c9', 'es', '', '<div>e) la documentación de los resultados de las acciones correctivas tomadas y</div>'),
    ('c9561208-ef6a-4d00-b3e8-a49032ee24fc', '1ab7857e-5654-48f2-98f1-c0b815e53536', 'en', '', '<div>f) verifying corrective actions taken to ensure that they are effective.</div>'),
    ('b655f41f-e637-4d67-b04a-ee6b27ee13ab', '1ab7857e-5654-48f2-98f1-c0b815e53536', 'es', '', '<div>f) la verificación de las acciones correctivas tomadas para asegurar que sean eficaces.</div>'),
    ('faf79773-45f5-4053-b3ec-974751969b27', '19b783eb-f7e1-40a3-a208-510f14e533a3', 'en', 'Handling of potentially unsafe products', '<div>{clause_8.9.4.1}</div><div>{clause_8.9.4.2}</div><div>{clause_8.9.4.3}</div>'),
    ('15f7c1f4-5350-4204-81cc-903434966d80', '19b783eb-f7e1-40a3-a208-510f14e533a3', 'es', 'Manipulación de productos potencialmente no inocuos', '<div>{clause_8.9.4.1}</div><div>{clause_8.9.4.2}</div><div>{clause_8.9.4.3}</div>'),
    ('ca6e9d4a-5662-473a-8517-157a318c473e', '18b78258-6f91-40e8-872b-130213e53210', 'en', 'General', '<div>The organization shall take action(s) to prevent potentially unsafe products from entering the food chain, unless it can demonstrate that:</div><div>{clause_8.9.4.1.a}</div><div>{clause_8.9.4.1.b}</div><div>{clause_8.9.4.1.c}</div><div>The organization shall retain products that have been identified as potentially unsafe under its control until the products have been evaluated and the disposition has been determined.</div><div>If products that have left the control of the organization are subsequently determined to be unsafe, the organization shall notify relevant interested parties and initiate a withdrawal/recall (see 8.9.5).</div><div>The controls and related responses from relevant interested parties and authorization for dealing with potentially unsafe products shall be retained as documented information.</div>'),
    ('cf6ea529-fedc-4561-b807-46653e8c5bb5', '18b78258-6f91-40e8-872b-130213e53210', 'es', 'Generalidades', '<div>La organización debe tomar acciones para prevenir el ingreso de productos potencialmente no inocuos en la cadena alimentaria, a menos que se pueda demostrar que: </div><div>{clause_8.9.4.1.a}</div><div>{clause_8.9.4.1.b}</div><div>{clause_8.9.4.1.c}</div><div>La organización debe conservar los productos que se han identificado como potencialmente no inocuos bajo su control hasta que los productos hayan sido evaluados y la disposición haya sido determinada. </div><div>Si a los productos que ya no están bajo el control de la organización se les determina subsecuentemente como no inocuos, la organización debe notificarlo a las partes interesadas pertinentes e iniciar una retirada/recuperación (véase 8.9.5).</div><div>Los controles y las respuestas relacionadas de las partes interesadas pertinentes y la autorización para tratar con productos potencialmente no inocuos deben conservarse como información documentada.</div>'),
    ('d49e5bb5-bd85-475d-bbd1-aca970e7db41', '1fb78d5d-77b3-4c81-af73-ac691ae53d15', 'en', '', '<div>a) the food safety hazard(s) of concern is (are) reduced to the defined acceptable levels</div>'),
    ('c79e473e-49c2-44ce-b5ad-bcc65be7ba32', '1fb78d5d-77b3-4c81-af73-ac691ae53d15', 'es', '', '<div>a) los peligros relacionados con la inocuidad de los alimentos en cuestión han sido reducidos a los niveles aceptables definidos </div>'),
    ('ae84c694-6257-43e4-82d7-a8d44d200cb0', '1eb78bca-c9b9-4d06-acb6-816c19e53b82', 'en', '', '<div>b) the food safety hazard(s) of concern will be reduced to identified acceptable levels prior to entering the food chain or</div>'),
    ('93849c13-54fe-4533-a050-5b674a2007f7', '1eb78bca-c9b9-4d06-acb6-816c19e53b82', 'es', '', '<div>b) los peligros relacionados con la inocuidad de los alimentos en cuestión serán reducidos a los niveles aceptables identificados antes de su ingreso en la cadena alimentaria o</div>'),
    ('adcc6e1f-5753-4367-b5ef-896b9ec3577b', '1db78a37-61d0-4677-a26b-9ff318e539ef', 'en', '', '<div>c) the product still meets the defined acceptable level(s) of the food safety hazard(s) of concern despite the nonconformity.</div>'),
    ('c0cc8c08-6086-4300-b98d-3f9089c3366c', '1db78a37-61d0-4677-a26b-9ff318e539ef', 'es', '', '<div>c) a pesar de la no conformidad, el producto todaví­a cumple los niveles aceptables definidos en lo concerniente a los peligros relacionados con la inocuidad de los alimentos.</div>'),
    ('d03ce7f6-a408-47be-b7bb-ed3e4c5d92b2', '1cb788a4-d256-480c-94ba-ab5617e5385c', 'en', 'Evaluation for release', '<div>Each lot of products affected by the nonconformity shall be evaluated.</div><div>Products affected by failure to remain within critical limits at CCPs shall not be released, but shall be handled in accordance with 8.9.4.3.</div><div>Products affected by failure to meet action criterion for OPRPs shall only be released as safe when any of the following conditions apply:</div><div>{clause_8.9.4.2.a}</div><div>{clause_8.9.4.2.b}</div><div>{clause_8.9.4.2.c}</div><div>Results of evaluation for release of products shall be retained as documented information.</div>'),
    ('cd3ce33d-8b5c-4dad-941f-eb11615db3c1', '1cb788a4-d256-480c-94ba-ab5617e5385c', 'es', 'Evaluación para la liberación', '<div>Cada lote de productos afectados por la no conformidad debe ser evaluado. </div><div>Los productos afectados por incumplimiento, al no mantenerse dentro de los lí­mites crí­ticos de los PCC, no deben liberarse sino que deben ser tratados de acuerdo con el apartado 8.9.4.3.</div><div>Los productos afectados por incumplimiento del criterio de acción para los PPRO solamente deben ser liberados como inocuos, cuando alguna de las condiciones siguientes se aplica:</div><div>{clause_8.9.4.2.a}</div><div>{clause_8.9.4.2.b}</div><div>{clause_8.9.4.2.c}</div><div>Los resultados de la evaluación de la liberación de productos deben conservarse como información documentada.</div>'),
    ('679ba271-7a78-4d31-b625-e88d11456845', '13b77a79-daf1-47f5-a665-3a8d1ee54361', 'en', '', '<div>a) evidence other than the monitoring system demonstrates that the control measures have been effective</div>'),
    ('729bb3c2-5bf4-45aa-bde1-12922445862e', '13b77a79-daf1-47f5-a665-3a8d1ee54361', 'es', '', '<div>a) otra evidencia aparte del sistema de seguimiento demuestra que las medidas de control han sido eficaces</div>'),
    ('d1199220-9573-4868-83d4-af6877d22da4', '12b778e6-9d5f-474a-af38-3cd01de541ce', 'en', '', '<div>b) evidence shows that the combined effect of the control measures for that particular product conforms to the performance intended (i.e. identified acceptable levels)</div>'),
    ('ee19bfc7-dd80-473f-9ad6-6f537cd23583', '12b778e6-9d5f-474a-af38-3cd01de541ce', 'es', '', '<div>b) la evidencia muestra que el efecto combinado de las medidas de control para ese producto en particular cumple con el desempeño previsto (es decir, niveles aceptables identificados)</div>'),
    ('3a953b85-7b77-42ad-abe4-fd5977207fb1', '9df052cd-0a31-4125-aeb4-99f9994511f5', 'en', '', '<div>c) the results of sampling, analysis and/or other verification activities demonstrate that the affected products conform to the identified acceptable levels for the food safety hazard(s) concerned.</div>'),
    ('4d95596e-9424-4cbe-ad6d-5d1682209102', '9df052cd-0a31-4125-aeb4-99f9994511f5', 'es', '', '<div>c) los resultados del muestreo, análisis y/o de otras actividades de verificación demuestran que los productos afectados son conformes con los niveles aceptables identificados para los peligros relacionados con la inocuidad de los alimentos en cuestión.</div>'),
    ('a39c69e4-cf49-45b4-a121-8044de240660', '9cf0513a-d06a-4dba-97b6-657c98451062', 'en', 'Disposition of nonconforming products', '<div>Products that are not acceptable for release shall be:</div><div>{clause_8.9.4.3.a}</div><div>{clause_8.9.4.3.b}</div><div>{clause_8.9.4.3.c}</div><div>Documented information on the disposition of nonconforming products, including the identification of the person(s) with approving authority shall be retained.</div>'),
    ('a89c71c3-6849-4963-874c-2877fb243407', '9cf0513a-d06a-4dba-97b6-657c98451062', 'es', 'Disposición de productos no conformes', '<div>Los productos que no son aceptables para su liberación deben ser: </div><div>{clause_8.9.4.3.a}</div><div>{clause_8.9.4.3.b}</div><div>{clause_8.9.4.3.c}</div><div>Debe conservarse la información documentada sobre la disposición de los productos no conformes, incluida la identificación de las personas con autoridad de aprobación.</div>'),
    ('e2e4762f-53a2-4837-a303-f29ba31f63ab', '9bf04fa7-ba97-474b-8bc1-33c397450ecf', 'en', '', '<div>a) reprocessed or further processed within or outside the organization to ensure that the food safety hazard is reduced to acceptable levels or</div>'),
    ('d5e461b8-b401-4c70-9d8d-5f60ae1f74fc', '9bf04fa7-ba97-474b-8bc1-33c397450ecf', 'es', '', '<div>a) reprocesados o procesados posteriormente dentro o fuera de la organización para asegurar que el peligro relacionado con la inocuidad de los alimentos es reducido a niveles aceptables o </div>'),
    ('35946406-941a-490e-9ce8-c5ae92969be2', '9af04e14-c908-4f90-a836-f5a696450d3c', 'en', '', '<div>b) redirected for other use as long as food safety in the food chain is not affected or</div>'),
    ('529491ad-2128-4d9d-b97a-69e187968a91', '9af04e14-c908-4f90-a836-f5a696450d3c', 'es', '', '<div>b) redirigidos para otro uso siempre que la inocuidad de los alimentos en la cadena alimentaria no se vea afectada o </div>'),
    ('74eff809-b3f0-47b9-81c1-fa457cc7baed', '99f04c81-33b6-45c9-9ccc-556595450ba9', 'en', '', '<div>c) destroyed and/or disposed as waste.</div>'),
    ('6feff02a-20ed-44e2-9cda-42da5fc78d46', '99f04c81-33b6-45c9-9ccc-556595450ba9', 'es', '', '<div>c) destruidos y/o dispuestos como desecho.</div>'),
    ('bdce5198-56c7-4e90-9fce-a240c3544dec', '98f04aee-29e4-4c0e-9cbf-390894450a16', 'en', 'Withdrawal/recall', '<div>The organization shall be able to ensure the timely withdrawal/recall of lots of end products that have been identified as potentially unsafe, by appointing competent person(s) having the authority to initiate and carry out the withdrawal/recall.</div><div>The organization shall establish and maintain documented information for: </div><div>{clause_8.9.5.a}</div><div>{clause_8.9.5.b}</div><div>{clause_8.9.5.c}</div><div>Withdrawn/recalled products and end products still in stock shall be secured or held under the control of the organization until they are managed in accordance with 8.9.4.3.</div><div>The cause, extent and result of a withdrawal/recall shall be retained as documented information and reported to the top management as input for the management review (see 9.3).</div><div>The organization shall verify the implementation and effectiveness of withdrawals/recalls through the use of appropriate techniques (e.g. mock withdrawal/recall or practice withdrawal/recall) and retain documented information.</div>'),
    ('cace660f-f3ed-4157-aaae-b67bd8546efb', '98f04aee-29e4-4c0e-9cbf-390894450a16', 'es', 'Retirada/recuperación', '<div>La organización debe poder garantizar la retirada/recuperación oportuna de lotes de productos terminados que se han identificado como potencialmente no inocuos, mediante la asignación de personas competentes que tengan la autoridad para iniciar y llevar a cabo la retirada/recuperación.</div><div>La organización debe establecer y mantener información documentada para:&nbsp</div><div>{clause_8.9.5.a}</div><div>{clause_8.9.5.b}</div><div>{clause_8.9.5.c}</div><div>Los productos retirados/recuperados y los productos terminados que aún estén en stock deben asegurarse o mantenerse bajo el control de la organización hasta que se gestionen de acuerdo con el apartado 8.9.4.3.</div><div>La causa, el alcance y el resultado de una retirada/recuperación deben conservarse como información documentada y deben informarse a la alta dirección como entrada para la revisión por la dirección (véase 9.3).</div><div>La organización debe verificar la implementación y la eficacia de las retiradas/recuperaciones, mediante el uso de técnicas apropiadas (por ejemplo, simulacro de retirada/recuperación o ensayos de retirada/recuperación) y conservar la información documentada. </div>'),
    ('2f703bc3-9d83-4f63-9195-a3f755f43a57', '97f0495b-bb49-481f-922a-a61f93450883', 'en', '', '<div>a) notifying relevant interested parties (e.g. statutory and regulatory authorities, customers and/or consumers) </div>'),
    ('2a7033e4-0482-4bb4-ab6a-fbc458f43f10', '97f0495b-bb49-481f-922a-a61f93450883', 'es', '', '<div>a) notificar a las partes interesadas pertinentes (por ejemplo, autoridades legales y reglamentarias, clientes y/o consumidores) </div>'),
    ('7065e1da-ad51-428a-8422-89ea7864b42e', '96f047c8-4c6c-4cd4-af2d-3a12924506f0', 'en', '', '<div>b) handling withdrawn/recalled products as well as products still in stock</div>'),
    ('5565b759-b5b6-4491-b1fa-6a3565649645', '96f047c8-4c6c-4cd4-af2d-3a12924506f0', 'es', '', '<div>b) manipulación de productos retirados/recuperados, así­ como productos que todaví­a están en stock</div>'),
    ('6258edfd-5205-4a35-838f-c2514ffc30f9', '95f04635-e327-452d-a62b-b951a1451e8d', 'en', '', '<div>c) performing the sequence of actions to be taken.</div>'),
    ('6558f2b6-6ede-4c16-b55d-b07e6afc5b7a', '95f04635-e327-452d-a62b-b951a1451e8d', 'es', '', '<div>c) realizar la secuencia de acciones a tomar. </div>'),
    ('5c3f8b3c-e679-463c-9d15-593cd8daef48', '94f044a2-6f75-49a2-af50-cff4a0451cfa', 'en', 'Performance evaluation', '<div>{clause_9.1}</div><div>{clause_9.2}</div><div>{clause_9.3}</div>'),
    ('513f79eb-8964-403b-bfbc-5dbfc5dad15f', '94f044a2-6f75-49a2-af50-cff4a0451cfa', 'es', 'Evaluación del desempeño', '<div>{clause_9.1}</div><div>{clause_9.2}</div><div>{clause_9.3}</div>'),
    ('69583e56-e6fc-4bde-95fd-4a9e865a1172', '97ee0ac4-93ed-44ec-910a-f6f69342c9ec', 'en', 'Monitoring, measurement, analysis and evaluation', '<div>{clause_9.1.1}</div><div>{clause_9.1.2}</div>'),
    ('6658399d-b288-40cd-8bf5-0ef19b5a3281', '97ee0ac4-93ed-44ec-910a-f6f69342c9ec', 'es', 'Seguimiento, medición, análisis y evaluación', '<div>{clause_9.1.1}</div><div>{clause_9.1.2}</div>'),
    ('d60a1aff-5a6e-4407-bb7b-2d4bd6456d3b', '98ee0c57-241a-46d7-aaed-45139442cb7f', 'en', 'General', '<div>The organization shall determine:</div><div>{clause_9.1.1.a}</div><div>{clause_9.1.1.b}</div><div>{clause_9.1.1.c}</div><div>{clause_9.1.1.d}</div><div>{clause_9.1.1.e}</div><div>The organization shall retain appropriate documented information as evidence of the results.</div><div>The organization shall evaluate the performance and the effectiveness of the FSMS.</div>'),
    ('e90a38e8-6128-4da0-8db6-1970c1454c2c', '98ee0c57-241a-46d7-aaed-45139442cb7f', 'es', 'Generalidades', '<div>La organización debe determinar:</div><div>{clause_9.1.1.a}</div><div>{clause_9.1.1.b}</div><div>{clause_9.1.1.c}</div><div>{clause_9.1.1.d}</div><div>{clause_9.1.1.e}</div><div>La organización debe conservar la información documentada apropiada como evidencia de los resultados.</div><div>La organización debe evaluar el desempeño y la eficacia del SGIA.</div>'),
    ('d6c27374-222b-4884-a22f-5a3484a3b570', '99ee0dea-7530-4166-8366-340c9542cd12', 'en', '', '<div>a) what needs to be monitored and measured</div>'),
    ('bbc248f3-14d1-46d3-944f-614781a3b0b7', '99ee0dea-7530-4166-8366-340c9542cd12', 'es', '', '<div>a) qué necesita seguimiento y medición</div>'),
    ('7035ae15-ebe9-437d-8cbc-c409aae45a01', '9aee0f7d-36d0-4061-a8de-e7099642cea5', 'en', '', '<div>b) the methods for monitoring, measurement, analysis and evaluation, as applicable, to ensure valid results</div>'),
    ('6335999e-6207-486e-929e-5fa695e438f2', '9aee0f7d-36d0-4061-a8de-e7099642cea5', 'es', '', '<div>b) los métodos de seguimiento, medición, análisis y evaluación necesarios, según corresponda, para asegurar resultados válidos</div>')
INSERT INTO public.requisito_traduccion (id, id_requisito, lang, title, content_html) VALUES
    ('638b86aa-fce9-46da-b7d3-3d5a6b8a58fe', '93ee0478-2eac-41c8-9679-cca28f42c3a0', 'en', '', '<div>c) when the monitoring and measuring shall be performed</div>'),
    ('688b8e89-c129-4001-9cba-f4c5788a6d75', '93ee0478-2eac-41c8-9679-cca28f42c3a0', 'es', '', '<div>c) cuándo se deben llevar a cabo el seguimiento y la medición </div>'),
    ('968ee9d3-4695-47f3-b73c-afa78b94ace7', '94ee060b-b6fd-4483-bb2b-6caf9042c533', 'en', '', '<div>d) when the results from monitoring and measurement shall be analysed and evaluated</div>'),
    ('b18f1454-3aa3-44a4-bdef-50146e947f40', '94ee060b-b6fd-4483-bb2b-6caf9042c533', 'es', '', '<div>d) cuándo se deben analizar y evaluar los resultados del seguimiento y la medición. </div>'),
    ('f193bee8-f00c-47a0-bd2d-0f706a71cdbc', '95ee079e-01cb-4d52-8694-4f589142c6c6', 'en', '', '<div>e) who shall analyse and evaluate the results from monitoring and measurement.</div>'),
    ('de93a0ff-e952-4e07-aaf2-234b5f71bc6b', '95ee079e-01cb-4d52-8694-4f589142c6c6', 'es', '', '<div>e) quién debe analizar y evaluar los resultados del seguimiento y la medición.</div>'),
    ('68b36d99-7775-4789-acac-82f5708b307d', '96ee0931-74de-451d-8df6-33f59242c859', 'en', 'Analysis and evaluation', '<div>The organization shall analyse and evaluate appropriate data and information arising from monitoring and measurement, including the results of verification activities related to PRPs and the hazard control plan (see 8.8 and 8.5.4), the internal audits (see 9.2) and external audits.</div><div>The analysis shall be carried out:</div><div>{clause_9.1.2.a}</div><div>{clause_9.1.2.b}</div><div>{clause_9.1.2.c}</div><div>{clause_9.1.2.d}</div><div>{clause_9.1.2.e}</div><div>The results of the analysis and the resulting activities shall be retained as documented information.</div><div>The results shall be reported to top management and used as input to the management review (see 9.3) and the updating of the FSMS (see 10.3).</div><div>NOTE: Methods to analyse data can include statistical techniques.</div>'),
    ('83b3981a-879f-4a92-a3ee-d5aa738b3536', '96ee0931-74de-451d-8df6-33f59242c859', 'es', 'Análisis y evaluación', '<div>La organización debe analizar y evaluar los datos y la información apropiados que surgen del seguimiento y la medición, incluyendo los resultados de las actividades de verificación relacionadas con los PPR y el plan de control de peligros (véanse 8.8 y 8.5.4), las auditorí­as internas (véase 9.2) y las auditorí­as externas.</div><div>Los análisis deben llevarse a cabo para:</div><div>{clause_9.1.2.a}</div><div>{clause_9.1.2.b}</div><div>{clause_9.1.2.c}</div><div>{clause_9.1.2.d}</div><div>{clause_9.1.2.e}</div><div>Los resultados del análisis y las actividades resultantes deben conservarse como información documentada.</div><div>Los resultados deben ser informados a la alta dirección y utilizarse como elementos de entrada para la revisión por la dirección (véase 9.3) y la actualización del SGIA (véase 10.3).</div><div>NOTA: Los métodos para analizar los datos pueden incluir técnicas estadí­sticas.</div>'),
    ('911bf0ce-c3e7-4926-bda3-c9f67e98245a', '8fedfe2c-dc48-4784-80e6-362e9b42d684', 'en', '', '<div>a) to confirm that the overall performance of the system meets the planned arrangements and the FSMS requirements established by the organization</div>'),
    ('7e1bd2e5-3021-4265-bd1c-43396397f9d9', '8fedfe2c-dc48-4784-80e6-362e9b42d684', 'es', '', '<div>a) confirmar que el desempeño global del sistema cumple con las disposiciones planificadas y los requisitos del SGIA establecidos por la organización </div>'),
    ('7125dff7-a040-498f-a9ac-fd233da27e43', '90edffbf-4b24-42cf-8768-7fab9c42d817', 'en', '', '<div>b) to identify the need for updating or improving the FSMS</div>'),
    ('7425e4b0-af5e-4c58-9967-2c1838a27664', '90edffbf-4b24-42cf-8768-7fab9c42d817', 'es', '', '<div>b) identificar la necesidad para la actualización y mejora del SGIA</div>'),
    ('dfd47be3-0541-42cf-85fe-8b17e43c5d7f', '09f579ff-46c5-4f7f-bf14-267f254a6b87', 'en', '', '<div>c) to identify trends which indicate a higher incidence of potentially unsafe products or process failures</div>'),
    ('dad47404-16d8-4b98-96dd-f9e4f73c7b68', '09f579ff-46c5-4f7f-bf14-267f254a6b87', 'es', '', '<div>c) identificar las tendencias que indican una mayor incidencia de productos potencialmente no inocuos o fallas en los procesos </div>'),
    ('ad6ee97a-9aa7-4966-8b3b-b78a778a80d6', '08f5786c-d4bb-47b4-b553-66f2244a69f4', 'en', '', '<div>d) to establish information for planning of the internal audit programme related to the status and importance of areas to be audited</div>'),
    ('926ebef9-ed94-4da5-b0f5-b655748a7c1d', '08f5786c-d4bb-47b4-b553-66f2244a69f4', 'es', '', '<div>d) establecer información para la planificación del programa de auditorí­a interna relacionada con el estado y la importancia de las áreas a ser auditadas</div>'),
    ('b47368a9-5fd3-4105-b474-35e57e67f095', '0bf57d25-be7f-49a9-8bb5-e6c5274a6ead', 'en', '', '<div>e) to provide evidence that corrections and corrective actions are effective.</div>'),
    ('af7360ca-208c-4f46-8184-04fa7167dc1e', '0bf57d25-be7f-49a9-8bb5-e6c5274a6ead', 'es', '', '<div>e) proporcionar evidencia de que las correcciones y acciones correctivas son eficaces. </div>'),
    ('6e3291b8-b657-400c-bf30-3160e4f4b5f4', '0af57b92-b7d9-496e-aa3f-1fe8264a6d1a', 'en', 'Internal audit', '<div>{clause_9.2.1}</div><div>{clause_9.2.2}</div>'),
    ('7b32a62f-9aed-46eb-84a6-c49bc9f48b73', '0af57b92-b7d9-496e-aa3f-1fe8264a6d1a', 'es', 'Auditorí­a interna', '<div>{clause_9.2.1}</div><div>{clause_9.2.2}</div>'),
    ('9347234f-1db6-4cbb-9681-98bba4c12c53', '05f573b3-488c-44ab-9c48-fc23214a653b', 'en', '', '<div>The organization shall conduct internal audits at planned intervals to provide information on whether the FSMS: </div><div>{clause_9.2.1.a}</div><div>{clause_9.2.1.b}</div>'),
    ('86470ed8-7aca-42bc-9daf-1e80bfc156d4', '05f573b3-488c-44ab-9c48-fc23214a653b', 'es', '', '<div>La organización debe realizar auditorí­as internas a intervalos planificados para proporcionar información acerca de si el SGIA:&nbsp</div><div>{clause_9.2.1.a}</div><div>{clause_9.2.1.b}</div>'),
    ('7517d4a6-51aa-4662-98dc-dfce71bdc92a', '04f57220-5157-4a70-b87d-ba86204a63a8', 'en', '', '<div>a) conforms to:</div><ul><li>{clause_9.2.1.a.1}</li><li>{clause_9.2.1.a.2}</li></ul>'),
    ('9218024d-e4ac-4939-be2d-db0176bdd109', '04f57220-5157-4a70-b87d-ba86204a63a8', 'es', '', '<div>a) es conforme con:</div><ul><li>{clause_9.2.1.a.1}</li><li>{clause_9.2.1.a.2}</li></ul>'),
    ('7a1a3f25-e301-4f91-85aa-49f976e5b019', '07f576d9-7eda-4985-bc82-03d9234a6861', 'en', '', '<div>1) the organization’s own requirements for its FSMS</div>'),
    ('8d1a5d0e-da9b-4d8a-a582-90b691e5da9a', '07f576d9-7eda-4985-bc82-03d9234a6861', 'es', '', '<div>1) los requisitos propios de la organización para su SGIA</div>'),
    ('e0a70484-a25b-4948-b9c7-1fe4ffc60168', '06f57546-429a-401a-ba3b-bd5c224a66ce', 'en', '', '<div>2) the requirements of this document</div>'),
    ('e5a70c63-ece3-441f-a8e7-b117ecc5e37f', '06f57546-429a-401a-ba3b-bd5c224a66ce', 'es', '', '<div>2) los requisitos de este documento</div>'),
    ('7875d7db-2eb4-4b47-90ca-0d8f7f582277', '11f58697-1f08-4007-a370-bcf71d4a5eef', 'en', '', '<div>b) is effectively implemented and maintained.</div>'),
    ('6375b6cc-356c-41e0-8880-4dec82582730', '11f58697-1f08-4007-a370-bcf71d4a5eef', 'es', '', '<div>b) se implementa y mantiene eficazmente.</div>'),
    ('288c0f12-0c91-4a1e-905e-edc29f4e334e', '10f58504-902b-425c-9453-090a1c4a5d5c', 'en', '', '<div>The organization shall:</div><div>{clause_9.2.2.a}</div><div>{clause_9.2.2.b}</div><div>{clause_9.2.2.c}</div><div>{clause_9.2.2.d}</div><div>{clause_9.2.2.e}</div><div>{clause_9.2.2.f}</div><div>{clause_9.2.2.g}</div><div>Follow-up activities by the organization shall include the verification of the actions taken and the reporting of the verification results.</div><div>NOTE: ISO 19011 provides guidelines for auditing management systems.</div>'),
    ('3d8c3021-da98-4b0d-819f-645d8c4e1565', '10f58504-902b-425c-9453-090a1c4a5d5c', 'es', '', '<div>La organización debe:</div><div>{clause_9.2.2.a}</div><div>{clause_9.2.2.b}</div><div>{clause_9.2.2.c}</div><div>{clause_9.2.2.d}</div><div>{clause_9.2.2.e}</div><div>{clause_9.2.2.f}</div><div>{clause_9.2.2.g}</div><div>Las actividades de seguimiento por la organización deben incluir la verificación de las acciones tomadas y el informe de los resultados de la verificación.</div><div>NOTA: La Norma ISO 19011 proporciona orientación sobre las auditorí­as del sistema de gestión.</div>'),
    ('e2a786fc-c809-4a58-9d41-89fc7c64d438', '03f331f6-47b5-441e-922e-e0349f4759fe', 'en', '', '<div>a) plan, establish, implement and maintain (an) audit programme(s), including the frequency, methods, responsibilities, planning requirements and reporting, which shall take into consideration the importance of the processes concerned, changes in the FSMS, and the results of monitoring, measurement and previous audits</div>'),
    ('d7a775ab-b8ea-478f-85cf-757f8964e8af', '03f331f6-47b5-441e-922e-e0349f4759fe', 'es', '', '<div>a) planificar, establecer, implementar y mantener uno o varios programas de auditorí­a que incluyan la frecuencia, los métodos, las responsabilidades, los requisitos de planificación e informes, que deben tener en consideración la importancia de los procesos involucrados, los cambios en el SGIA y los resultados de seguimiento, medición y auditorí­as previas</div>'),
    ('e64813bd-7c46-48a1-816f-dd11c2a5ab29', '04f33389-4e5b-4459-9d18-1c91a0475b91', 'en', '', '<div>b) define the audit criteria and scope for each audit</div>'),
    ('e9481876-b805-4c7a-a50b-df3ebda5a34a', '04f33389-4e5b-4459-9d18-1c91a0475b91', 'es', '', '<div>b) definir los criterios de la auditorí­a y el alcance para cada auditorí­a</div>'),
    ('e145a93e-9ee5-43b2-a559-bc46bba12bfa', '01f32ed0-6710-4864-b6cc-251e9d4756d8', 'en', '', '<div>c) select competent auditors and conduct audits to ensure objectivity and the impartiality of the audit process</div>'),
    ('ee45bdb5-9135-49a9-ab7d-ac29a0a10179', '01f32ed0-6710-4864-b6cc-251e9d4756d8', 'es', '', '<div>c) seleccionar los auditores competentes y realizar auditorí­as para asegurar la objetividad y la imparcialidad del proceso de auditorí­a </div>'),
    ('014ffd27-2207-4f8b-a60b-7733ee06be63', '02f33063-d5ee-46af-9464-845b9e47586b', 'en', '', '<div>d) ensure that the results of the audits are reported to the food safety team and relevant management</div>'),
    ('e44fcf80-3d71-48ac-9311-03c8e906b684', '02f33063-d5ee-46af-9464-845b9e47586b', 'es', '', '<div>d) asegurarse que los resultados de las auditorí­as se informen al equipo de inocuidad de los alimentos y a la dirección pertinente </div>'),
    ('fcd96eb0-0751-4f5c-8571-2498eed94704', '07f33842-ea70-488a-a8a5-e020a347604a', 'en', '', '<div>e) retain documented information as evidence of the implementation of the audit programme and the audit results</div>'),
    ('f9d969f7-8e75-4b5b-95b6-f5a3f3d94ee3', '07f33842-ea70-488a-a8a5-e020a347604a', 'es', '', '<div>e) conservar información documentada como evidencia de la implementación del programa de auditorí­a y de los resultados de las auditorí­as </div>'),
    ('20a13d41-7064-4d55-b742-3f7d884c81a5', '08f339d5-0eb5-4435-8d3e-4a5da44761dd', 'en', '', '<div>f) make the necessary correction and take the necessary corrective action within the agreed time frame</div>'),
    ('0ba11c32-771c-43b6-91e1-00e29b4c9f8e', '08f339d5-0eb5-4435-8d3e-4a5da44761dd', 'es', '', '<div>f) realizar la corrección necesaria y tomar la acción correctiva requerida dentro del perí­odo de tiempo acordado</div>'),
    ('fc16f4b2-9ef9-4c36-9ea8-7c62834a1726', '05f3351c-e3ad-4e20-b405-f46aa1475d24', 'en', '', '<div>g) determine if the FSMS meets the intent of the food safety policy (see 5.2) and objectives of the FSMS (see 6.2). </div>'),
    ('111715c1-9841-45d5-8409-bafda04a44cd', '05f3351c-e3ad-4e20-b405-f46aa1475d24', 'es', '', '<div>g) determinar si el SGIA cumple con la intención de la polí­tica de inocuidad de los alimentos (véase 5.2) y los objetivos del SGIA (véase 6.2).</div>'),
    ('4e7cb97b-559b-4e5f-9a85-372fa17965cf', '06f336af-d53b-42db-b23a-8dd7a2475eb7', 'en', 'Management review', '<div>{clause_9.3.1}</div><div>{clause_9.3.2}</div><div>{clause_9.3.3}</div>'),
    ('397c986c-0d8f-4f88-8de2-b68c94795158', '06f336af-d53b-42db-b23a-8dd7a2475eb7', 'es', 'Revisión por la dirección', '<div>{clause_9.3.1}</div><div>{clause_9.3.2}</div><div>{clause_9.3.3}</div>'),
    ('278b8fa4-cb1c-47b0-abd4-ad04c4272610', '0bf33e8e-fd7f-4c46-a97c-cfbc97474d66', 'en', 'General', '<div>Top management shall review the organization’s FSMS, at planned intervals, to ensure its continuing suitability, adequacy and effectiveness</div>'),
    ('2c8b9783-5170-4e77-9baa-c637c1272157', '0bf33e8e-fd7f-4c46-a97c-cfbc97474d66', 'es', 'Generalidades', '<div>La alta dirección debe revisar el SGIA de la organización a intervalos planificados, para asegurarse de su pertinencia, adecuación y eficacia continuas.</div>'),
    ('c0feca45-9181-44d9-bdca-15195b489a21', '0cf34021-ab7a-4bc1-afb0-e13998474ef9', 'en', 'Management review input', '<div>The management review shall consider:</div><div>{clause_9.3.2.a}</div><div>{clause_9.3.2.b}</div><div>{clause_9.3.2.c}</div><div>{clause_9.3.2.d}</div><div>{clause_9.3.2.e}</div><div>{clause_9.3.2.f}</div><div>{clause_9.3.2.g}</div><div>The data shall be presented in a manner that enables top management to relate the information to stated objectives of the FSMS.</div>'),
    ('d3fee82e-fb50-4282-ae9c-04d646487912', '0cf34021-ab7a-4bc1-afb0-e13998474ef9', 'es', 'Entradas de la revisión por la dirección', '<div>La revisión por la dirección debe considerar:</div><div>{clause_9.3.2.a}</div><div>{clause_9.3.2.b}</div><div>{clause_9.3.2.c}</div><div>{clause_9.3.2.d}</div><div>{clause_9.3.2.e}</div><div>{clause_9.3.2.f}</div><div>{clause_9.3.2.g}</div><div>Los datos deben presentarse de una manera que permita a la alta dirección relacionar la información con los objetivos establecidos del SGIA.</div>'),
    ('899af091-acd2-43c1-bfc8-bd2d2a96c6a5', '05e66929-b1dc-47b9-a589-40ed213b5ab1', 'en', '', '<div>a) the status of actions from previous management reviews</div>'),
    ('949b01e2-01dd-4c9a-b92d-ecb23d96e48e', '05e66929-b1dc-47b9-a589-40ed213b5ab1', 'es', '', '<div>a) el estado de las acciones de las revisiones por la dirección previas </div>'),
    ('f09e7740-9502-49f8-b9a9-ce8891238c04', '04e66796-ab38-4a7e-a885-e530203b591e', 'en', '', '<div>b) changes in external and internal issues that are relevant to the FSMS, including changes in the organization and its context (see 4.1)</div>'),
    ('0d9ea4e7-803d-44af-8576-e9f3962393e3', '04e66796-ab38-4a7e-a885-e530203b591e', 'es', '', '<div>b) los cambios en las cuestiones externas e internas que sean pertinentes al SGIA, incluyendo cambios en la organización y su contexto (véase 4.1)</div>'),
    ('42402f0b-9909-462b-a29a-bf5f43c3aacf', '03e66603-3c9c-468f-b0f2-cfa71f3b578b', 'en', '', '<div>c) information on the performance and the effectiveness of the FSMS, including trends in:</div><ul><li>{clause_9.3.2.c.1}</li><li>{clause_9.3.2.c.2}</li><li>{clause_9.3.2.c.3}</li><li>{clause_9.3.2.c.4}</li><li>{clause_9.3.2.c.5}</li><li>{clause_9.3.2.c.6}</li><li>{clause_9.3.2.c.7}</li><li>{clause_9.3.2.c.8}</li><li>{clause_9.3.2.c.9}</li></ul>'),
    ('4d40405c-98ac-414c-a991-93dc36c39658', '03e66603-3c9c-468f-b0f2-cfa71f3b578b', 'es', '', '<div>c) la información sobre el desempeño y la eficacia del SGIA, incluidas las tendencias relativas a:</div><ul><li>{clause_9.3.2.c.1}</li><li>{clause_9.3.2.c.2}</li><li>{clause_9.3.2.c.3}</li><li>{clause_9.3.2.c.4}</li><li>{clause_9.3.2.c.5}</li><li>{clause_9.3.2.c.6}</li><li>{clause_9.3.2.c.7}</li><li>{clause_9.3.2.c.8}</li><li>{clause_9.3.2.c.9}</li></ul>'),
    ('a296a3c2-eb37-4cd2-baa7-1d9225945c26', '02e66470-b473-4644-92d4-1e3a1e3b55f8', 'en', '', '<div>1) result(s) of system updating activities (see 4.4 and 10.3)</div>'),
    ('97969271-db0e-49c9-b2eb-f38d429489cd', '02e66470-b473-4644-92d4-1e3a1e3b55f8', 'es', '', '<div>1) los resultados de las actividades de actualización (véanse 4.4 y 10.3)</div>'),
    ('8f4098cd-12af-4f75-bdfd-708164eff029', '09e66f75-8b85-4f95-9b29-8521253b60fd', 'en', '', '<div>2) monitoring and measurement results</div>'),
    ('72406b26-2d0c-4556-98ac-754e5fefe84a', '09e66f75-8b85-4f95-9b29-8521253b60fd', 'es', '', '<div>2) los resultados del seguimiento y medición</div>'),
    ('d5cd2bcc-37dd-4a7c-a7fc-766c1eaf1938', '08e66de2-37d3-466a-86b9-2e44243b5f6a', 'en', '', '<div>3) analysis of the results of verification activities related to PRPs and the hazard control plan (see 8.8.2)</div>'),
    ('eacd4cdb-d84f-4e7b-b046-360f2baf2daf', '08e66de2-37d3-466a-86b9-2e44243b5f6a', 'es', '', '<div>3) el análisis de los resultados de las actividades de verificación relacionadas con los PPR y el plan de control de peligros (véase 8.8.2)</div>'),
    ('f51505b7-ca24-4eff-a3a5-41e390510363', '07e66c4f-3beb-45bb-bd52-2ceb233b5dd7', 'en', '', '<div>4) nonconformities and corrective actions</div>'),
    ('f8150a70-8216-4d28-973f-01d88b50fb84', '07e66c4f-3beb-45bb-bd52-2ceb233b5dd7', 'es', '', '<div>4) las no conformidades y acciones correctivas </div>'),
    ('150b168e-fef1-44d6-a7ae-33b65deb70fa', '06e66abc-310e-4900-9800-ab6e223b5c44', 'en', '', '<div>5) audit results (internal and external)</div>'),
    ('020af8a5-e494-4ef5-87d5-ecf942eb4679', '06e66abc-310e-4900-9800-ab6e223b5c44', 'es', '', '<div>5) los resultados de las auditorí­as (internas y externas) </div>'),
    ('ef1cfc59-1c27-4af9-a8e4-d8b5c338229d', '0de675c1-2849-4721-8c4c-d935193b4e19', 'en', '', '<div>6) inspections (e.g. regulatory, customer)</div>'),
    ('0a1d26da-6fd6-4022-bb0c-f86ac6382756', '0de675c1-2849-4721-8c4c-d935193b4e19', 'es', '', '<div>6) las inspecciones (por ejemplo regulatorias o de los clientes)</div>'),
    ('758151a8-a2f1-48d0-acf1-61304c3f835c', '0ce6742e-4ae1-4726-b0dd-b498183b4c86', 'en', '', '<div>7) the performance of external providers</div>'),
    ('628133bf-4292-4497-9a88-510b413f720b', '0ce6742e-4ae1-4726-b0dd-b498183b4c86', 'es', '', '<div>7) el desempeño de los proveedores externos</div>'),
    ('ac79a1d2-3b93-4b62-9227-e7825959c976', 'ffe42120-d66c-4b70-a2bd-094a1b3912a8', 'en', '', '<div>8) the review of risks and opportunities and of the effectiveness of actions taken to address them (see 6.1)</div>'),
    ('c179c2e1-ce96-4e39-b0d5-451d5659c4bd', 'ffe42120-d66c-4b70-a2bd-094a1b3912a8', 'es', '', '<div>8) la revisión de los riesgos y oportunidades y de la eficacia de las acciones tomadas para abordarlos (véase 6.1)</div>'),
    ('fedf669b-079f-41bb-a002-504f36e94f9f', '00e422b3-cda2-45ab-9b3f-3e371c39143b', 'en', '', '<div>9) the extent to which objectives of the FSMS have been met</div>'),
    ('e9df458c-64b4-47bc-8b58-edac49e96d88', '00e422b3-cda2-45ab-9b3f-3e371c39143b', 'es', '', '<div>9) la medida en que se han cumplido los objetivos del SGIA</div>'),
    ('39e40950-8c45-4e48-b5a2-3c3837a1a814', '01e42446-c7af-411a-9e33-59001d3915ce', 'en', '', '<div>d) the adequacy of resources</div>'),
    ('36e40497-d6cd-491f-81a6-23431ca17d93', '01e42446-c7af-411a-9e33-59001d3915ce', 'es', '', '<div>d) la adecuación de los recursos </div>'),
    ('d37e5361-ccea-4491-aef2-389d5dbb3d35', '02e425d9-03ef-4a85-af6c-37bd1e391761', 'en', '', '<div>e) any emergency situation, incident (see 8.4.2) or withdrawal/recall (see 8.9.5) that occurred</div>'),
    ('be7e3252-c484-428a-9044-db0250bb28be', '02e425d9-03ef-4a85-af6c-37bd1e391761', 'es', '', '<div>e) toda situación de emergencia, incidente (véase 8.4.2) o retirada/recuperación (véase 8.9.5) que hayan ocurrido</div>'),
    ('9424525e-8491-4e66-a56a-b3e6538b7eca', '03e4276c-59d1-48b4-85e7-6d7e1f3918f4', 'en', '', '<div>f) relevant information obtained through external (see 7.4.2) and internal (see 7.4.3) communication, including requests and complaints from interested parties</div>'),
    ('a12466d5-d77e-42a5-b65e-4049588b86a9', '03e4276c-59d1-48b4-85e7-6d7e1f3918f4', 'es', '', '<div>f) la información pertinente obtenida mediante comunicación externa (véase 7.4.2) e interna (véase 7.4.3), incluidas las solicitudes y quejas de las partes interesadas</div>'),
    ('3e5a97c7-ef2b-47cf-a1a6-9853841478f3', '04e428ff-cbda-407f-aecd-f6bb20391a87', 'en', '', '<div>g) opportunities for continual improvement.</div>'),
    ('215a6a20-00c2-4098-8aa4-d8689f14a374', '04e428ff-cbda-407f-aecd-f6bb20391a87', 'es', '', '<div>g) las oportunidades de mejora continua</div>'),
    ('1fb2219c-a041-450c-b7ad-699c5272f388', '05e42a92-3cef-4a6e-b4dd-7d1421391c1a', 'en', 'Management review output', '<div>The outputs of the management review shall include:</div><div>{clause_9.3.3.a}</div><div>{clause_9.3.3.b}</div><div>The organization shall retain documented information as evidence of the results of management reviews.</div>'),
    ('14b2104b-84d7-4beb-b3a7-831f3f72d59f', '05e42a92-3cef-4a6e-b4dd-7d1421391c1a', 'es', 'Salidas de la revisión por la dirección', '<div>Las salidas de la revisión por la dirección deben incluir:</div><div>{clause_9.3.3.a}</div><div>{clause_9.3.3.b}</div><div>La organización debe conservar la información documentada como evidencia de los resultados de las revisiones por la dirección.</div>'),
    ('992529dd-49bc-4605-9c6e-23b1cc0d0b39', '06e42c25-4395-4aa9-b516-e2f122391dad', 'en', '', '<div>a) decisions and actions related to continual improvement opportunities</div>'),
    ('9c252e96-0a76-4446-b592-a85ee70d35ba', '06e42c25-4395-4aa9-b516-e2f122391dad', 'es', '', '<div>a) las decisiones y acciones relacionadas con las oportunidades de mejora continua </div>'),
    ('33d6e53a-0c67-4a1a-a833-3b4af1fb256e', '07e42db8-b1dc-4878-b806-883213390610', 'en', '', '<div>b) any need for updates and changes to the FSMS, including resource needs and revision of the food safety policy and objectives of the FSMS.</div>'),
    ('18d6bab9-b75b-4141-a66f-6615defb0785', '07e42db8-b1dc-4878-b806-883213390610', 'es', '', '<div>b) toda necesidad de actualización y cambio al SGIA, incluida la necesidad de recursos y la revisión de la polí­tica y los objetivos de inocuidad de los alimentos del SGIA. </div>'),
    ('63c20ea3-953a-4b33-bed1-35d7d206a797', '08e42f4b-20e1-4633-a38e-41bf143907a3', 'en', 'Improvement', '<div>{clause_10.1}</div><div>{clause_10.2}</div><div>{clause_10.3}</div>'),
    ('5ec206c4-a293-49e4-b13d-4ca4d506ac50', '08e42f4b-20e1-4633-a38e-41bf143907a3', 'es', 'Mejora', '<div>{clause_10.1}</div><div>{clause_10.2}</div><div>{clause_10.3}</div>'),
    ('0cd4c3df-12e4-43c3-8e87-7e2bb73a8283', '91ebc2bb-48b4-4473-aeeb-0d338d4081e3', 'en', 'Nonconformity and corrective action', '<div>{clause_10.1.1}</div><div>{clause_10.1.2}</div>'),
    ('1fd4e1c8-63c4-4794-85f7-3050b23a7aa4', '91ebc2bb-48b4-4473-aeeb-0d338d4081e3', 'es', 'No conformidad y acción correctiva', '<div>{clause_10.1.1}</div><div>{clause_10.1.2}</div>'),
    ('2ccad4b6-0c94-416a-94d4-25fefaa8fe9a', '90ebc128-c064-44b8-9875-2b968c408050', 'en', '', '<div>When a nonconformity occurs, the organization shall:</div><div>{clause_10.1.1.a}</div><div>{clause_10.1.1.b}</div><div>{clause_10.1.1.c}</div><div>{clause_10.1.1.d}</div><div>{clause_10.1.1.e}</div><div>Corrective actions shall be appropriate to the effects of the nonconformities encountered.</div>'),
    ('29cacffd-289f-42f1-a306-37d1dfa8d419', '90ebc128-c064-44b8-9875-2b968c408050', 'es', '', '<div>Cuando ocurra una no conformidad, la organización debe:</div><div>{clause_10.1.1.a}</div><div>{clause_10.1.1.b}</div><div>{clause_10.1.1.c}</div><div>{clause_10.1.1.d}</div><div>{clause_10.1.1.e}</div><div>Las acciones correctivas deben ser apropiadas a los efectos de las no conformidades encontradas.</div>'),
    ('312ddb75-6beb-4399-85bf-4869ff3314c9', '93ebc5e1-eb6d-4acd-bc71-60a98f408509', 'en', '', '<div>a) react to the nonconformity and, as applicable:</div><ul><li>{clause_10.1.1.a.1}</li><li>{clause_10.1.1.a.2}</li></ul>'),
    ('242dc6fe-ec8e-4042-b767-f386fa330cea', '93ebc5e1-eb6d-4acd-bc71-60a98f408509', 'es', '', '<div>a) reaccionar ante la no conformidad y, según corresponda: </div><ul><li>{clause_10.1.1.a.1}</li><li>{clause_10.1.1.a.2}</li></ul>'),
    ('0d8eaf54-f45d-4a70-82b5-269445989858', '92ebc44e-a729-4fc2-9e87-64ac8e408376', 'en', '', '<div>1) take action to control and correct it</div>'),
    ('f28e84d3-93fe-4637-bc02-86275298accf', '92ebc44e-a729-4fc2-9e87-64ac8e408376', 'es', '', '<div>1) tomar acción para controlarla y corregirla </div>'),
    ('57871733-dd93-4497-8b4b-2d076aad29ef', '95ebc907-cbf2-4247-80e2-864f9140882f', 'en', '', '<div>2) deal with the consequences</div>'),
    ('728741b4-3df2-48d0-b04d-42f45dad1578', '95ebc907-cbf2-4247-80e2-864f9140882f', 'es', '', '<div>2) hacer frente a las consecuencias</div>'),
    ('26fc8a0a-0ca8-49ee-837b-b93abfd913c6', '94ebc774-23c9-4f9c-a3ca-a2429040869c', 'en', '', '<div>b) evaluate the need for action to eliminate the cause(s) of the nonconformity, in order that it does not recur or occur elsewhere, by:</div><ul><li>{clause_10.1.1.b.1}</li><li>{clause_10.1.1.b.2}</li><li>{clause_10.1.1.b.3}</li></ul>'),
    ('2bfc91e9-968b-44fd-8d25-8125dcd9416d', '94ebc774-23c9-4f9c-a3ca-a2429040869c', 'es', '', '<div>b) evaluar la necesidad de tomar acción para eliminar las causas de la no conformidad, con la finalidad de que no vuelva a ocurrir ni ocurra en otra parte, mediante: </div><ul><li>{clause_10.1.1.b.1}</li><li>{clause_10.1.1.b.2}</li><li>{clause_10.1.1.b.3}</li></ul>'),
    ('9f7fa979-84c3-488d-8591-f255c4d9eb45', '97ebcc2d-c887-4051-ad56-7d1593408b55', 'en', '', '<div>1) reviewing the nonconformity</div>'),
    ('ba7fd3fa-b6bc-479e-9fd7-f38ad7da092e', '97ebcc2d-c887-4051-ad56-7d1593408b55', 'es', '', '<div>1) la revisión de la no conformidad </div>'),
    ('285e67c8-5939-4f14-b56e-26502b66b0a4', '96ebca9a-1a8c-40d6-abac-7bf8924089c2', 'en', '', '<div>2) determining the causes of the nonconformity</div>'),
    ('155e49df-0859-4b43-bdfe-742b3066b883', '96ebca9a-1a8c-40d6-abac-7bf8924089c2', 'es', '', '<div>2) la determinación de las causas de la no conformidad</div>'),
    ('a577b2d7-fc73-414b-aee5-4c035257da7b', '89ebb623-dc2a-41eb-8f09-7d4b95408e7b', 'en', '', '<div>3) determining if similar nonconformities exist, or could potentially occur</div>'),
    ('a877b790-17dd-4a6c-b90f-c2f83d57b96c', '89ebb623-dc2a-41eb-8f09-7d4b95408e7b', 'es', '', '<div>3) la determinación de la existencia de no conformidades similares, o que potencialmente podrí­an ocurrir </div>'),
    ('c7e82cae-3ca4-4e72-b730-20d6fff215b2', '88ebb490-00ba-42b0-9190-d9ce94408ce8', 'en', '', '<div>c) implement any action needed</div>'),
    ('b4e80ec5-132d-4669-865e-311914f236c1', '88ebb490-00ba-42b0-9190-d9ce94408ce8', 'es', '', '<div>c) implementar toda acción necesaria</div>'),
    ('1b840c98-bd97-4bac-824b-d540d02ea91c', '0be8b132-397e-4072-a3c6-6408273da2ba', 'en', '', '<div>d) review the effectiveness of any corrective action taken</div>'),
    ('2884210f-a22d-428b-8d2b-e97bc52e97cb', '0be8b132-397e-4072-a3c6-6408273da2ba', 'es', '', '<div>d) revisar la eficacia de toda acción correctiva tomada</div>'),
    ('d2a5b309-ea7b-4a25-a43f-2d4549a1b15d', '0ce8b2c5-9345-463d-a3d3-8065283da44d', 'en', '', '<div>e) make changes to the FSMS, if necessary.</div>'),
    ('cda5ab2a-978e-45e6-bf57-75da4ca1b616', '0ce8b2c5-9345-463d-a3d3-8065283da44d', 'es', '', '<div>e) si fuera necesario, realizar cambios en el SGIA.</div>'),
    ('ce1b9cda-254e-4f86-a69f-bcea44a0d9de', '09e8ae0c-52bb-4868-b634-6512253d9f94', 'en', '', '<div>The organization shall retain documented information as evidence of:</div><div>{clause_10.1.2.a}</div><div>{clause_10.1.2.b}</div>'),
    ('b31b7259-621b-4b45-9477-9d3551a0ee55', '09e8ae0c-52bb-4868-b634-6512253d9f94', 'es', '', '<div>La organización debe conservar la información documentada como evidencia de:</div><div>{clause_10.1.2.a}</div><div>{clause_10.1.2.b}</div>'),
    ('8d25f6c3-8fe7-48ef-b412-d6f7eed71f47', '0ae8af9f-db0b-4823-9931-d11f263da127', 'en', '', '<div>a) the nature of the nonconformities and any subsequent actions taken</div>'),
    ('8825eee4-8b61-4c38-8de8-2ec4d1d6f1a0', '0ae8af9f-db0b-4823-9931-d11f263da127', 'es', '', '<div>a) la naturaleza de las no conformidades y toda acción tomada posteriormente</div>'),
    ('015224e4-44a7-4e68-839e-b344ea6090d0', '07e8aae6-ace2-4486-9ebd-907c233d9c6e', 'en', '', '<div>b) the results of any corrective action.</div>'),
    ('06522cc3-8cb4-4d3f-a9c9-5b77e7608c17', '07e8aae6-ace2-4486-9ebd-907c233d9c6e', 'es', '', '<div>b) los resultados de toda acción correctiva.</div>'),
    ('984af685-29ac-4331-8e62-305983fadae1', '08e8ac79-5add-4401-b5bb-c4f9243d9e01', 'en', 'Continual improvement', '<div>The organization shall continually improve the suitability, adequacy and effectiveness of the FSMS.</div><div>Top management shall ensure that the organization continually improves the effectiveness of the FSMS through the use of communication (see 7.4), management review (see 9.3), internal audit (see 9.2), analysis of results of verification activities (see 8.8.2), validation of control measure(s) and combination(s) of control measure(s) (see 8.5.3), corrective actions (see 8.9.3) and FSMS updating (see 10.3).</div>'),
    ('ab4b146e-0b28-4baa-8fea-90166efab9d2', '08e8ac79-5add-4401-b5bb-c4f9243d9e01', 'es', 'Mejora continua', '<div>La organización debe mejorar continuamente la pertinencia, adecuación y eficacia del SGIA.</div><div>La alta dirección debe asegurarse que la organización mejora continuamente la eficacia del SGIA mediante el uso de la comunicación (véase 7.4), la revisión por la dirección (véase 9.3), la auditorí­a interna (véase 9.2), el análisis de los resultados de las actividades de verificación (véase 8.8.2), la validación de las medidas de control y las combinaciones de las medidas de control (véase 8.5.3), las acciones correctivas (véase 8.9.3) y la actualización del SGIA (véase 10.3). </div>'),
    ('934a1f06-c303-4782-bf65-f8ae5cf62952', '05e8a7c0-b580-4f8c-af3e-20a6213d9948', 'en', 'Update of the food safety management system', '<div>Top management shall ensure that the FSMS is continually updated. To achieve this, the food safety team shall evaluate the FSMS at planned intervals. The team shall consider whether it is necessary to review the hazard analysis (see 8.5.2), the established hazard control plan (see 8.5.4) and the established PRPs (see 8.2). The updating activities shall be based on:</div><div>{clause_10.3.a}</div><div>{clause_10.3.b}</div><div>{clause_10.3.c}</div><div>{clause_10.3.d}</div><div>System updating activities shall be retained as documented information and reported as input to the management review (see 9.3).</div>'),
    ('b04a4cad-5934-49d9-9bf7-9ce171f64a61', '05e8a7c0-b580-4f8c-af3e-20a6213d9948', 'es', 'Actualización del sistema de gestión de la inocuidad de los alimentos', '<div>La alta dirección debe asegurarse que el SGIA se actualiza continuamente. Para lograr esto, el equipo de la inocuidad de los alimentos debe evaluar al SGIA a intervalos planificados. El equipo debe considerar si es necesario revisar el análisis de peligros (véase 8.5.2), el plan de control de peligros establecido (véase 8.5.4) y los PPR establecidos (véase 8.2). Las actividades de actualización se deben basar en:</div><div>{clause_10.3.a}</div><div>{clause_10.3.b}</div><div>{clause_10.3.c}</div><div>{clause_10.3.d}</div><div>Las actividades de actualización del sistema deben ser conservadas como información documentada e informadas como elementos de entrada para la revisión por la dirección (véase 9.3).</div>'),
    ('409a312f-e507-46db-8581-259baf5bee1b', '06e8a953-44fa-4df7-92c8-5ec3223d9adb', 'en', '', '<div>a) input from communication, external as well as internal (see 7.4)</div>'),
    ('339a1cb8-5de3-4adc-800a-92609a5bcd0c', '06e8a953-44fa-4df7-92c8-5ec3223d9adb', 'es', '', '<div>a) los elementos de entrada de la comunicación, tanto externa como interna (véase 7.4)</div>'),
    ('d4272df0-118b-49e4-a581-40d8178b87c4', '13e8bdca-8088-4eca-9fa2-0fe01f3d9622', 'en', '', '<div>b) input from other information concerning the suitability, adequacy and effectiveness of the FSMS</div>'),
    ('d1272937-0432-4b33-b1e7-80e31c8b8fa3', '13e8bdca-8088-4eca-9fa2-0fe01f3d9622', 'es', '', '<div>b) los elementos de entrada de cualquier otra información relativa a la pertinencia, adecuación y eficacia del SGIA</div>'),
    ('fa67d281-6cb9-4d5d-ad4f-b2bdae845965', '14e8bf5d-be1a-4f75-8370-bc1d203d97b5', 'en', '', '<div>c) output from the analysis of results of verification activities (see 9.1.2)</div>'),
    ('e567b172-f8f6-4ace-8538-a822c184774e', '14e8bf5d-be1a-4f75-8370-bc1d203d97b5', 'es', '', '<div>c) los elementos de salida del análisis de los resultados de las actividades de verificación (véase 9.1.2)</div>'),
    ('10dfbd6d-867a-4855-934a-08a195426259', '0e048ad5-f9f3-461d-a70b-e901a931a36d', 'en', '', '<div>d) output from management review (see 9.3).</div>'),
    ('f3df8fc6-8d33-4eb6-9110-ea6eb0428cda', '0e048ad5-f9f3-461d-a70b-e901a931a36d', 'es', '', '<div>d) los elementos de salida de la revisión por la dirección (véase 9.3). </div>')
